window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["解释"] = {"guanyushenlifeifaxingyixingshianjianjutiyingyongfa0c0f7b":[{"i":1,"n":"第一条","txt":"具有下列情形之一的，应认定为刑法第三百三十六条第一款规定的“未取得医生执业资格的人非法行医”："},{"i":2,"n":"第二条","txt":"具有下列情形之一的，应认定为刑法第三百三十六条第一款规定的“情节严重”："},{"i":3,"n":"第三条","txt":"具有下列情形之一的，应认定为刑法第三百三十六条第一款规定的“严重损害就诊人身体健康”："},{"i":4,"n":"第四条","txt":"非法行医行为系造成就诊人死亡的直接、主要原因的，应认定为刑法第三百三十六条第一款规定的“造成就诊人死亡”。"},{"i":5,"n":"第五条","txt":"实施非法行医犯罪，同时构成生产、销售假药罪，生产、销售劣药罪，诈骗罪等其他犯罪的，依照刑法处罚较重的规定定罪处罚。"},{"i":6,"n":"第六条","txt":"本解释所称“医疗活动”“医疗行为”，参照《医疗机构管理条例实施细则》中的“诊疗活动”“医疗美容”认定。"}],"zuigaorenminjianchayuanguanyugongrendengfeijiangua80492c":[],"zuigaorenminjianchayuanguanyushanzixiaoshoujinliao373a8a":[],"zuigaorenminjianchayuanguanyugouchengpiaosuyounvzu90a2f4":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban902f2b":[{"i":1,"n":"第一条","txt":"奸淫幼女的，依照刑法第二百三十六条第二款的规定从重处罚。具有下列情形之一的，应当适用较重的从重处罚幅度："},{"i":2,"n":"第二条","txt":"强奸已满十四周岁的未成年女性或者奸淫幼女，具有下列情形之一的，应当认定为刑法第二百三十六条第三款第一项规定的“强奸妇女、奸淫幼女情节恶劣”："},{"i":3,"n":"第三条","txt":"奸淫幼女，具有下列情形之一的，应当认定为刑法第二百三十六条第三款第五项规定的“造成幼女伤害”："},{"i":4,"n":"第四条","txt":"强奸已满十四周岁的未成年女性或者奸淫幼女，致使其感染艾滋病病毒的，应当认定为刑法第二百三十六第三款第六项规定的“致使被害人重伤”。"},{"i":5,"n":"第五条","txt":"对已满十四周岁不满十六周岁的未成年女性负有特殊职责的人员，与该未成年女性发生性关系，具有下列情形之一的，应当认定为刑法第二百三十六条之一规定的“情节恶劣”："},{"i":6,"n":"第六条","txt":"对已满十四周岁的未成年女性负有特殊职责的人员，利用优势地位或者被害人孤立无援的境地，迫使被害人与其发生性关系的，依照刑法第二百三十六条的规定，以强奸罪定罪处罚。"},{"i":7,"n":"第七条","txt":"猥亵儿童，具有下列情形之一的，应当认定为刑法第二百三十七条第三款第三项规定的“造成儿童伤害或者其他严重后果”："},{"i":8,"n":"第八条","txt":"猥亵儿童，具有下列情形之一的，应当认定为刑法第二百三十七条第三款第四项规定的“猥亵手段恶劣或者有其他恶劣情节”："},{"i":9,"n":"第九条","txt":"胁迫、诱骗未成年人通过网络视频聊天或者发送视频、照片等方式，暴露身体隐私部位或者实施淫秽行为，符合刑法第二百三十七条规定的，以强制猥亵罪或者猥亵儿童罪定罪处罚。"},{"i":10,"n":"第十条","txt":"实施猥亵未成年人犯罪，造成被害人轻伤以上后果，同时符合刑法第二百三十四条或者第二百三十二条的规定，构成故意伤害罪、故意杀人罪的，依照处罚较重的规定定罪处罚。"},{"i":11,"n":"第十一条","txt":"强奸、猥亵未成年人的成年被告人认罪认罚的，是否从宽处罚及从宽幅度应当从严把握。"},{"i":12,"n":"第十二条","txt":"对强奸未成年人的成年被告人判处刑罚时，一般不适用缓刑。"},{"i":13,"n":"第十三条","txt":"对于利用职业便利实施强奸、猥亵未成年人等犯罪的，人民法院应当依法适用从业禁止。"},{"i":14,"n":"第十四条","txt":"对未成年人实施强奸、猥亵等犯罪造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支付的合理费用，以及因误工减少的收入。"},{"i":15,"n":"第十五条","txt":"本解释规定的“负有特殊职责的人员”，是指对未成年人负有监护、收养、看护、教育、医疗等职责的人员，包括与未成年人具有共同生活关系且事实上负有照顾、保护等职责的人员。"},{"i":16,"n":"第十六条","txt":"本解释自2023年6月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubana94458":[{"i":1,"n":"第一条","txt":"行为人具有下列情形之一的，可以认定为刑法第一百八十二条第一款第四项规定的“以其他方法操纵证券、期货市场”："},{"i":2,"n":"第二条","txt":"操纵证券、期货市场，具有下列情形之一的，应当认定为刑法第一百八十二条第一款规定的“情节严重”："},{"i":3,"n":"第三条","txt":"操纵证券、期货市场，违法所得数额在五十万元以上，具有下列情形之一的，应当认定为刑法第一百八十二条第一款规定的“情节严重”："},{"i":4,"n":"第四条","txt":"具有下列情形之一的，应当认定为刑法第一百八十二条第一款规定的“情节特别严重”："},{"i":5,"n":"第五条","txt":"下列账户应当认定为刑法第一百八十二条中规定的“自己实际控制的账户”："},{"i":6,"n":"第六条","txt":"二次以上实施操纵证券、期货市场行为，依法应予行政处理或者刑事处理而未经处理的，相关交易数额或者违法所得数额累计计算。"},{"i":7,"n":"第七条","txt":"符合本解释第二条、第三条规定的标准，行为人如实供述犯罪事实，认罪悔罪，并积极配合调查，退缴违法所得的，可以从轻处罚；其中犯罪情节轻微的，可以依法不起诉或者免予刑事处罚。"},{"i":8,"n":"第八条","txt":"单位实施刑法第一百八十二条第一款行为的，依照本解释规定的定罪量刑标准，对其直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":9,"n":"第九条","txt":"本解释所称“违法所得”，是指通过操纵证券、期货市场所获利益或者避免的损失。"},{"i":10,"n":"第十条","txt":"对于在全国中小企业股份转让系统中实施操纵证券市场行为，社会危害性大，严重破坏公平公正的市场秩序的，比照本解释的规定执行，但本解释第二条第一项、第二项和第四条第一项、第二项除外。"},{"i":11,"n":"第十一条","txt":"本解释自2019年7月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanbf7539":[{"i":1,"n":"第一条","txt":"违反国家规定，具有下列情形之一的，属于刑法第二百二十五条第三项规定的“非法从事资金支付结算业务”："},{"i":2,"n":"第二条","txt":"违反国家规定，实施倒买倒卖外汇或者变相买卖外汇等非法买卖外汇行为，扰乱金融市场秩序，情节严重的，依照刑法第二百二十五条第四项的规定，以非法经营罪定罪处罚。"},{"i":3,"n":"第三条","txt":"非法从事资金支付结算业务或者非法买卖外汇，具有下列情形之一的，应当认定为非法经营行为“情节严重”："},{"i":4,"n":"第四条","txt":"非法从事资金支付结算业务或者非法买卖外汇，具有下列情形之一的，应当认定为非法经营行为“情节特别严重”："},{"i":5,"n":"第五条","txt":"非法从事资金支付结算业务或者非法买卖外汇，构成非法经营罪，同时又构成刑法第一百二十条之一规定的帮助恐怖活动罪或者第一百九十一条规定的洗钱罪的，依照处罚较重的规定定罪处罚。"},{"i":6,"n":"第六条","txt":"二次以上非法从事资金支付结算业务或者非法买卖外汇，依法应予行政处理或者刑事处理而未经处理的，非法经营数额或者违法所得数额累计计算。"},{"i":7,"n":"第七条","txt":"非法从事资金支付结算业务或者非法买卖外汇违法所得数额难以确定的，按非法经营数额的千分之一认定违法所得数额，依法并处或者单处违法所得一倍以上五倍以下罚金。"},{"i":8,"n":"第八条","txt":"符合本解释第三条规定的标准，行为人如实供述犯罪事实，认罪悔罪，并积极配合调查，退缴违法所得的，可以从轻处罚；其中犯罪情节轻微的，可以依法不起诉或者免予刑事处罚。"},{"i":9,"n":"第九条","txt":"单位实施本解释第一条、第二条规定的非法从事资金支付结算业务、非法买卖外汇行为，依照本解释规定的定罪量刑标准，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员定罪处罚。"},{"i":10,"n":"第十条","txt":"非法从事资金支付结算业务、非法买卖外汇刑事案件中的犯罪地，包括犯罪嫌疑人、被告人用于犯罪活动的账户开立地、资金接收地、资金过渡账户开立地、资金账户操作地，以及资金交易对手资金交付和汇出地等。"},{"i":11,"n":"第十一条","txt":"涉及外汇的犯罪数额，按照案发当日中国外汇交易中心或者中国人民银行授权机构公布的人民币对该货币的中间价折合成人民币计算。中国外汇交易中心或者中国人民银行授权机构未公布汇率中间价的境外货币，按照案发当日境内银行人民币对该货币的中间价折算成人民币，或者该货币在境内银行、国际外汇市场对美元汇率，与人民币对美元汇率中间价进行套算。"},{"i":12,"n":"第十二条","txt":"本解释自2019年2月1日起施行。《最高人民法院关于审理骗购外汇、非法买卖外汇刑事案件具体应用法律若干问题的解释》（法释〔1998〕20号）与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban4b3e85":[{"i":1,"n":"第一条","txt":"明知是盗窃、抢劫、诈骗、抢夺的机动车，实施下列行为之一的，依照刑法第三百一十二条的规定，以掩饰、隐瞒犯罪所得、犯罪所得收益罪定罪，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金："},{"i":2,"n":"第二条","txt":"伪造、变造、买卖机动车行驶证、登记证书，累计三本以上的，依照刑法第二百八十条第一款的规定，以伪造、变造、买卖国家机关证件罪定罪，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":3,"n":"第三条","txt":"国家机关工作人员滥用职权，有下列情形之一，致使盗窃、抢劫、诈骗、抢夺的机动车被办理登记手续，数量达到三辆以上或者价值总额达到三十万元以上的，依照刑法第三百九十七条第一款的规定，以滥用职权罪定罪，处三年以下有期徒刑或者拘役："},{"i":4,"n":"第四条","txt":"实施本解释第一条、第二条、第三条第一款或者第三款规定的行为，事前与盗窃、抢劫、诈骗、抢夺机动车的犯罪分子通谋的，以盗窃罪、抢劫罪、诈骗罪、抢夺罪的共犯论处。"},{"i":5,"n":"第五条","txt":"对跨地区实施的涉及同一机动车的盗窃、抢劫、诈骗、抢夺以及掩饰、隐瞒犯罪所得、犯罪所得收益行为，有关公安机关可以依照法律和有关规定一并立案侦查，需要提请批准逮捕、移送审查起诉、提起公诉的，由该公安机关所在地的同级人民检察院、人民法院受理。"},{"i":6,"n":"第六条","txt":"行为人实施本解释第一条、第三条第三款规定的行为，涉及的机动车有下列情形之一的，应当认定行为人主观上属于上述条款所称“明知”："}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban0d4da6":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban07deaf":[{"i":1,"n":"第一条","txt":"刑法第二百五十三条之一规定的“公民个人信息”，是指以电子或者其他方式记录的能够单独或者与其他信息结合识别特定自然人身份或者反映特定自然人活动情况的各种信息，包括姓名、身份证件号码、通信通讯联系方式、住址、账号密码、财产状况、行踪轨迹等。"},{"i":2,"n":"第二条","txt":"违反法律、行政法规、部门规章有关公民个人信息保护的规定的，应当认定为刑法第二百五十三条之一规定的“违反国家有关规定”。"},{"i":3,"n":"第三条","txt":"向特定人提供公民个人信息，以及通过信息网络或者其他途径发布公民个人信息的，应当认定为刑法第二百五十三条之一规定的“提供公民个人信息”。"},{"i":4,"n":"第四条","txt":"违反国家有关规定，通过购买、收受、交换等方式获取公民个人信息，或者在履行职责、提供服务过程中收集公民个人信息的，属于刑法第二百五十三条之一第三款规定的“以其他方法非法获取公民个人信息”。"},{"i":5,"n":"第五条","txt":"非法获取、出售或者提供公民个人信息，具有下列情形之一的，应当认定为刑法第二百五十三条之一规定的“情节严重”："},{"i":6,"n":"第六条","txt":"为合法经营活动而非法购买、收受本解释第五条第一款第三项、第四项规定以外的公民个人信息，具有下列情形之一的，应当认定为刑法第二百五十三条之一规定的“情节严重”："},{"i":7,"n":"第七条","txt":"单位犯刑法第二百五十三条之一规定之罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":8,"n":"第八条","txt":"设立用于实施非法获取、出售或者提供公民个人信息违法犯罪活动的网站、通讯群组，情节严重的，应当依照刑法第二百八十七条之一的规定，以非法利用信息网络罪定罪处罚；同时构成侵犯公民个人信息罪的，依照侵犯公民个人信息罪定罪处罚。"},{"i":9,"n":"第九条","txt":"网络服务提供者拒不履行法律、行政法规规定的信息网络安全管理义务，经监管部门责令采取改正措施而拒不改正，致使用户的公民个人信息泄露，造成严重后果的，应当依照刑法第二百八十六条之一的规定，以拒不履行信息网络安全管理义务罪定罪处罚。"},{"i":10,"n":"第十条","txt":"实施侵犯公民个人信息犯罪，不属于“情节特别严重”，行为人系初犯，全部退赃，并确有悔罪表现的，可以认定为情节轻微，不起诉或者免予刑事处罚；确有必要判处刑罚的，应当从宽处罚。"},{"i":11,"n":"第十一条","txt":"非法获取公民个人信息后又出售或者提供的，公民个人信息的条数不重复计算。"},{"i":12,"n":"第十二条","txt":"对于侵犯公民个人信息犯罪，应当综合考虑犯罪的危害程度、犯罪的违法所得数额以及被告人的前科情况、认罪悔罪态度等，依法判处罚金。罚金数额一般在违法所得的一倍以上五倍以下。"},{"i":13,"n":"第十三条","txt":"本解释自2017年6月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban613c8a":[{"i":1,"n":"第一条","txt":"未经注册商标所有人许可，在同一种商品、服务上使用与其注册商标相同的商标，具有下列情形之一的，应当认定为刑法第二百一十三条规定的“同一种商品、服务”："},{"i":2,"n":"第二条","txt":"与被假冒的注册商标完全相同，或者与被假冒的注册商标基本无差别、足以对相关公众产生误导的商标，应当认定为刑法第二百一十三条规定的“与其注册商标相同的商标”。具有下列情形之一的，应当认定为与被假冒的注册商标基本无差别、足以对相关公众产生误导的商标："},{"i":3,"n":"第三条","txt":"未经注册商标所有人许可，在同一种商品上使用与其注册商标相同的商标，具有下列情形之一的，应当认定为刑法第二百一十三条规定的“情节严重”："},{"i":4,"n":"第四条","txt":"销售假冒注册商标的商品，具有下列情形之一的，可以认定为刑法第二百一十四条规定的“明知”，但有证据证明确实不知道的除外："},{"i":5,"n":"第五条","txt":"销售明知是假冒注册商标的商品，违法所得数额在三万元以上的，应当认定为刑法第二百一十四条规定的“违法所得数额较大”；具有下列情形之一的，应当认定为刑法第二百一十四条规定的“其他严重情节”："},{"i":6,"n":"第六条","txt":"伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识，具有下列情形之一的，应当认定为刑法第二百一十五条规定的“情节严重”："},{"i":7,"n":"第七条","txt":"本解释所称“两种以上注册商标”，是指识别商品、服务不同来源的两种以上注册商标。虽然注册商标不同，但在同一种商品、服务上使用，均指向同一商品、服务来源的，不应当认定为“两种以上注册商标”。"},{"i":8,"n":"第八条","txt":"实施刑法第二百一十三条规定的假冒注册商标犯罪，又销售该假冒注册商标的商品，构成犯罪的，应当依照刑法第二百一十三条的规定，以假冒注册商标罪定罪处罚。"},{"i":9,"n":"第九条","txt":"具有下列情形之一的，应当认定为刑法第二百一十六条规定的“假冒他人专利”："},{"i":10,"n":"第十条","txt":"假冒他人专利，具有下列情形之一的，应当认定为刑法第二百一十六条规定的“情节严重”："},{"i":11,"n":"第十一条","txt":"实施侵犯著作权或者与著作权有关的权利的行为，没有取得著作权人、录音录像制作者、表演者授权，或者伪造、涂改授权许可文件，或者超出授权许可范围，应当认定为刑法第二百一十七条规定的“未经著作权人许可”、“未经录音录像制作者许可”、“未经表演者许可”。"},{"i":12,"n":"第十二条","txt":"未经著作权人或者与著作权有关的权利人许可，既复制又发行或者为发行而复制作品、录音录像制品的行为，应当认定为刑法第二百一十七条规定的“复制发行”。"},{"i":13,"n":"第十三条","txt":"实施刑法第二百一十七条规定的侵犯著作权或者与著作权有关的权利的行为，违法所得数额在三万元以上的，应当认定为刑法第二百一十七条规定的“违法所得数额较大”；具有下列情形之一的，应当认定为刑法第二百一十七条规定的“其他严重情节”："},{"i":14,"n":"第十四条","txt":"销售明知是刑法第二百一十七条规定的侵权复制品，违法所得数额在五万元以上的，应当认定为刑法第二百一十八条规定的“违法所得数额巨大”；具有下列情形之一的，应当认定为刑法第二百一十八条规定的“其他严重情节”："},{"i":15,"n":"第十五条","txt":"实施刑法第二百一十七条规定的侵犯著作权犯罪，又销售该侵权复制品，构成犯罪的，应当依照刑法第二百一十七条的规定，以侵犯著作权罪定罪处罚。"},{"i":16,"n":"第十六条","txt":"采取非法复制等方式获取商业秘密的，应当认定为刑法第二百一十九条第一款第一项规定的“盗窃”；未经授权或者超越授权使用计算机信息系统等方式获取商业秘密的，应当认定为刑法第二百一十九条第一款第一项规定的“电子侵入”。"},{"i":17,"n":"第十七条","txt":"侵犯商业秘密，具有下列情形之一的，应当认定为刑法第二百一十九条规定的“情节严重”："},{"i":18,"n":"第十八条","txt":"本解释规定的侵犯商业秘密“损失数额”，按照下列方式予以认定："},{"i":19,"n":"第十九条","txt":"本解释规定的侵犯商业秘密“违法所得数额”，是指因披露、允许他人使用商业秘密而获得的财物或者其他财产性利益的价值，或者因使用商业秘密所获得的利润。该利润可以根据侵权产品销售量乘以每件侵权产品的合理利润确定。"},{"i":20,"n":"第二十条","txt":"为境外机构、组织、人员窃取、刺探、收买、非法提供商业秘密，具有本解释第十七条规定情形的，应当认定为刑法第二百一十九条之一规定的“情节严重”。"},{"i":21,"n":"第二十一条","txt":"在刑事诉讼程序中，当事人、辩护人、诉讼代理人或者案外人书面申请对有关商业秘密或者其他需要保密的商业信息的证据、材料采取保密措施的，应当根据案件情况采取组织诉讼参与人签署保密承诺书等必要的保密措施。"},{"i":22,"n":"第二十二条","txt":"明知他人实施侵犯知识产权犯罪，具有下列行为之一的，以共同犯罪论处，但法律和司法解释另有规定的除外："},{"i":23,"n":"第二十三条","txt":"实施侵犯知识产权犯罪，具有下列情形之一的，一般酌情从重处罚："},{"i":24,"n":"第二十四条","txt":"实施侵犯知识产权犯罪，具有下列情形之一的，可以依法从轻处罚："},{"i":25,"n":"第二十五条","txt":"实施侵犯知识产权犯罪的，应当综合考虑犯罪违法所得数额、非法经营数额、给权利人造成的损失数额、侵权假冒物品数量及社会危害性等情节，依法判处罚金。"},{"i":26,"n":"第二十六条","txt":"单位实施刑法第二百一十三条至第二百一十九条之一行为的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本解释规定的定罪量刑标准处罚。"},{"i":27,"n":"第二十七条","txt":"除特殊情况外，假冒注册商标的商品、非法制造的注册商标标识、侵犯著作权的复制品、主要用于制造假冒注册商标的商品、注册商标标识或者侵权复制品的材料和工具，应当依法予以没收和销毁。"},{"i":28,"n":"第二十八条","txt":"本解释所称“非法经营数额”，是指行为人在实施侵犯知识产权行为过程中，制造、储存、运输、销售侵权产品的价值。已销售侵权产品的价值，按照实际销售的价格计算。尚未销售侵权产品的价值，按照已经查清的侵权产品实际销售平均价格计算。实际销售平均价格无法查清的，按照侵权产品的标价计算。无法查清实际销售价格或者侵权产品没有标价的，按照被侵权产品的市场中间价格计算。"},{"i":29,"n":"第二十九条","txt":"多次实施侵犯知识产权行为，未经处理且依法应当追诉的，定罪量刑所涉数额、数量等分别累计计算。"},{"i":30,"n":"第三十条","txt":"人民法院依法受理侵犯知识产权刑事自诉案件，对于当事人因客观原因不能取得的证据，在提起自诉时能够提供有关线索，申请人民法院调取的，人民法院应当依法调取。"},{"i":31,"n":"第三十一条","txt":"本解释自2025年4月26日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanbcce42":[{"i":1,"n":"第一条","txt":"下列人员应当认定为刑法第一百八十条第一款规定的“证券、期货交易内幕信息的知情人员”："},{"i":2,"n":"第二条","txt":"具有下列行为的人员应当认定为刑法第一百八十条第一款规定的“非法获取证券、期货交易内幕信息的人员”："},{"i":3,"n":"第三条","txt":"本解释第二条第二项、第三项规定的“相关交易行为明显异常”，要综合以下情形，从时间吻合程度、交易背离程度和利益关联程度等方面予以认定："},{"i":4,"n":"第四条","txt":"具有下列情形之一的，不属于刑法第一百八十条第一款规定的从事与内幕信息有关的证券、期货交易："},{"i":5,"n":"第五条","txt":"本解释所称“内幕信息敏感期”是指内幕信息自形成至公开的期间。"},{"i":6,"n":"第六条","txt":"在内幕信息敏感期内从事或者明示、暗示他人从事或者泄露内幕信息导致他人从事与该内幕信息有关的证券、期货交易，具有下列情形之一的，应当认定为刑法第一百八十条第一款规定的“情节严重”："},{"i":7,"n":"第七条","txt":"在内幕信息敏感期内从事或者明示、暗示他人从事或者泄露内幕信息导致他人从事与该内幕信息有关的证券、期货交易，具有下列情形之一的，应当认定为刑法第一百八十条第一款规定的“情节特别严重”："},{"i":8,"n":"第八条","txt":"二次以上实施内幕交易或者泄露内幕信息行为，未经行政处理或者刑事处理的，应当对相关交易数额依法累计计算。"},{"i":9,"n":"第九条","txt":"同一案件中，成交额、占用保证金额、获利或者避免损失额分别构成情节严重、情节特别严重的，按照处罚较重的数额定罪处罚。"},{"i":10,"n":"第十条","txt":"刑法第一百八十条第一款规定的“违法所得”，是指通过内幕交易行为所获利益或者避免的损失。"},{"i":11,"n":"第十一条","txt":"单位实施刑法第一百八十条第一款规定的行为，具有本解释第六条规定情形之一的，按照刑法第一百八十条第二款的规定定罪处罚。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubande8145":[{"i":1,"n":"第一条","txt":"赔偿请求人因行使侦查、检察、审判职权的机关以及看守所、监狱管理机关及其工作人员行使职权的行为侵犯其人身权、财产权而申请国家赔偿，具备国家赔偿法第十七条、第十八条规定情形的，属于本解释规定的刑事赔偿范围。"},{"i":2,"n":"第二条","txt":"解除、撤销拘留或者逮捕措施后虽尚未撤销案件、作出不起诉决定或者判决宣告无罪，但是符合下列情形之一的，属于国家赔偿法第十七条第一项、第二项规定的终止追究刑事责任："},{"i":3,"n":"第三条","txt":"对财产采取查封、扣押、冻结、追缴等措施后，有下列情形之一，且办案机关未依法解除查封、扣押、冻结等措施或者返还财产的，属于国家赔偿法第十八条规定的侵犯财产权："},{"i":4,"n":"第四条","txt":"赔偿义务机关作出赔偿决定，应当依法告知赔偿请求人有权在三十日内向赔偿义务机关的上一级机关申请复议。赔偿义务机关未依法告知，赔偿请求人收到赔偿决定之日起两年内提出复议申请的，复议机关应当受理。"},{"i":5,"n":"第五条","txt":"对公民采取刑事拘留措施后终止追究刑事责任，具有下列情形之一的，属于国家赔偿法第十七条第一项规定的违法刑事拘留："},{"i":6,"n":"第六条","txt":"数罪并罚的案件经再审改判部分罪名不成立，监禁期限超出再审判决确定的刑期，公民对超期监禁申请国家赔偿的，应当决定予以赔偿。"},{"i":7,"n":"第七条","txt":"根据国家赔偿法第十九条第二项、第三项的规定，依照刑法第十七条、第十八条规定不负刑事责任的人和依照刑事诉讼法第十五条、第一百七十三条第二款规定不追究刑事责任的人被羁押，国家不承担赔偿责任。但是，对起诉后经人民法院错判拘役、有期徒刑、无期徒刑并已执行的，人民法院应当对该判决确定后继续监禁期间侵犯公民人身自由权的情形予以赔偿。"},{"i":8,"n":"第八条","txt":"赔偿义务机关主张依据国家赔偿法第十九条第一项、第五项规定的情形免除赔偿责任的，应当就该免责事由的成立承担举证责任。"},{"i":9,"n":"第九条","txt":"受害的公民死亡，其继承人和其他有扶养关系的亲属有权申请国家赔偿。"},{"i":10,"n":"第十条","txt":"看守所及其工作人员在行使职权时侵犯公民合法权益造成损害的，看守所的主管机关为赔偿义务机关。"},{"i":11,"n":"第十一条","txt":"对公民采取拘留措施后又采取逮捕措施，国家承担赔偿责任的，作出逮捕决定的机关为赔偿义务机关。"},{"i":12,"n":"第十二条","txt":"一审判决有罪，二审发回重审后具有下列情形之一的，属于国家赔偿法第二十一条第四款规定的重审无罪赔偿，作出一审有罪判决的人民法院为赔偿义务机关："},{"i":13,"n":"第十三条","txt":"医疗费赔偿根据医疗机构出具的医药费、治疗费、住院费等收款凭证，结合病历和诊断证明等相关证据确定。赔偿义务机关对治疗的必要性和合理性提出异议的，应当承担举证责任。"},{"i":14,"n":"第十四条","txt":"护理费赔偿参照当地护工从事同等级别护理的劳务报酬标准计算，原则上按照一名护理人员的标准计算护理费；但医疗机构或者司法鉴定人有明确意见的，可以参照确定护理人数并赔偿相应的护理费。"},{"i":15,"n":"第十五条","txt":"残疾生活辅助器具费赔偿按照普通适用器具的合理费用标准计算。伤情有特殊需要的，可以参照辅助器具配制机构的意见确定。"},{"i":16,"n":"第十六条","txt":"误工减少收入的赔偿根据受害公民的误工时间和国家上年度职工日平均工资确定，最高为国家上年度职工年平均工资的五倍。"},{"i":17,"n":"第十七条","txt":"造成公民身体伤残的赔偿，应当根据司法鉴定人的伤残等级鉴定确定公民丧失劳动能力的程度，并参照以下标准确定残疾赔偿金："},{"i":18,"n":"第十八条","txt":"受害的公民全部丧失劳动能力的，对其扶养的无劳动能力人的生活费发放标准，参照作出赔偿决定时被扶养人住所地所属省级人民政府确定的最低生活保障标准执行。"},{"i":19,"n":"第十九条","txt":"侵犯公民、法人和其他组织的财产权造成损害的，应当依照国家赔偿法第三十六条的规定承担赔偿责任。"},{"i":20,"n":"第二十条","txt":"返还执行的罚款或者罚金、追缴或者没收的金钱，解除冻结的汇款的，应当支付银行同期存款利息，利率参照赔偿义务机关作出赔偿决定时中国人民银行公布的人民币整存整取定期存款一年期基准利率确定，不计算复利。"},{"i":21,"n":"第二十一条","txt":"国家赔偿法第三十三条、第三十四条规定的上年度，是指赔偿义务机关作出赔偿决定时的上一年度；复议机关或者人民法院赔偿委员会改变原赔偿决定，按照新作出决定时的上一年度国家职工平均工资标准计算人身自由赔偿金。"},{"i":22,"n":"第二十二条","txt":"下列赔偿决定、复议决定是发生法律效力的决定："},{"i":23,"n":"第二十三条","txt":"本解释自2016年1月1日起施行。本解释施行前最高人民法院、最高人民检察院发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban5c2a1b":[{"i":1,"n":"第一条","txt":"以牟利为目的，利用互联网、移动通讯终端制作、复制、出版、贩卖、传播淫秽电子信息，具有下列情形之一的，依照刑法第三百六十三条第一款的规定，以制作、复制、出版、贩卖、传播淫秽物品牟利罪定罪处罚："},{"i":2,"n":"第二条","txt":"实施第一条规定的行为，数量或者数额达到第一条第一款第（一）项至第（六）项规定标准五倍以上的，应当认定为刑法第三百六十三条第一款规定的“情节严重”；达到规定标准二十五倍以上的，应当认定为“情节特别严重”。"},{"i":3,"n":"第三条","txt":"不以牟利为目的，利用互联网或者移动通讯终端传播淫秽电子信息，具有下列情形之一的，依照刑法第三百六十四条第一款的规定，以传播淫秽物品罪定罪处罚；"},{"i":4,"n":"第四条","txt":"明知是淫秽电子信息而在自己所有、管理或者使用的网站或者网页上提供直接链接的，其数量标准根据所链接的淫秽电子信息的种类计算。"},{"i":5,"n":"第五条","txt":"以牟利为目的，通过声讯台传播淫秽语音信息，具有下列情形之一的，依照刑法第三百六十三条第一款的规定，对直接负责的主管人员和其他直接责任人员以传播淫秽物品牟利罪定罪处罚："},{"i":6,"n":"第六条","txt":"实施本解释前五条规定的犯罪，具有下列情形之一的，依照刑法第三百六十三条第一款、第三百六十四条第一款的规定从重处罚："},{"i":7,"n":"第七条","txt":"明知他人实施制作、复制、出版、贩卖、传播淫秽电子信息犯罪，为其提供互联网接入、服务器托管、网络存储空间、通讯传输通道、费用结算等帮助的，对直接负责的主管人员和其他直接责任人员，以共同犯罪论处。"},{"i":8,"n":"第八条","txt":"利用互联网、移动通讯终端、声讯台贩卖、传播淫秽书刊、影片、录像带、录音带等以实物为载体的淫秽物品的，依照《最高人民法院关于审理非法出版物刑事案件具体应用法律若干问题的解释》的有关规定定罪处罚。"},{"i":9,"n":"第九条","txt":"刑法第三百六十七条第一款规定的“其他淫秽物品”，包括具体描绘性行为或者露骨宣扬色情的诲淫性的视频文件、音频文件、电子刊物、图片、文章、短信息等互联网、移动通讯终端电子信息和声讯台语音信息。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban5ae3ce":[{"i":1,"n":"第一条","txt":"以牟利为目的，利用互联网、移动通讯终端制作、复制、出版、贩卖、传播淫秽电子信息的，依照《最高人民法院、最高人民检察院关于办理利用互联网、移动通讯终端、声讯台制作、复制、出版、贩卖、传播淫秽电子信息刑事案件具体应用法律若干问题的解释》第一条、第二条的规定定罪处罚。"},{"i":2,"n":"第二条","txt":"利用互联网、移动通讯终端传播淫秽电子信息的，依照《最高人民法院、最高人民检察院关于办理利用互联网、移动通讯终端、声讯台制作、复制、出版、贩卖、传播淫秽电子信息刑事案件具体应用法律若干问题的解释》第三条的规定定罪处罚。"},{"i":3,"n":"第三条","txt":"利用互联网建立主要用于传播淫秽电子信息的群组，成员达三十人以上或者造成严重后果的，对建立者、管理者和主要传播者，依照刑法第三百六十四条第一款的规定，以传播淫秽物品罪定罪处罚。"},{"i":4,"n":"第四条","txt":"以牟利为目的，网站建立者、直接负责的管理者明知他人制作、复制、出版、贩卖、传播的是淫秽电子信息，允许或者放任他人在自己所有、管理的网站或者网页上发布，具有下列情形之一的，依照刑法第三百六十三条第一款的规定，以传播淫秽物品牟利罪定罪处罚："},{"i":5,"n":"第五条","txt":"网站建立者、直接负责的管理者明知他人制作、复制、出版、贩卖、传播的是淫秽电子信息，允许或者放任他人在自己所有、管理的网站或者网页上发布，具有下列情形之一的，依照刑法第三百六十四条第一款的规定，以传播淫秽物品罪定罪处罚："},{"i":6,"n":"第六条","txt":"电信业务经营者、互联网信息服务提供者明知是淫秽网站，为其提供互联网接入、服务器托管、网络存储空间、通讯传输通道、代收费等服务，并收取服务费，具有下列情形之一的，对直接负责的主管人员和其他直接责任人员，依照刑法第三百六十三条第一款的规定，以传播淫秽物品牟利罪定罪处罚："},{"i":7,"n":"第七条","txt":"明知是淫秽网站，以牟利为目的，通过投放广告等方式向其直接或者间接提供资金，或者提供费用结算服务，具有下列情形之一的，对直接负责的主管人员和其他直接责任人员，依照刑法第三百六十三条第一款的规定，以制作、复制、出版、贩卖、传播淫秽物品牟利罪的共同犯罪处罚："},{"i":8,"n":"第八条","txt":"实施第四条至第七条规定的行为，具有下列情形之一的，应当认定行为人“明知”，但是有证据证明确实不知道的除外："},{"i":9,"n":"第九条","txt":"一年内多次实施制作、复制、出版、贩卖、传播淫秽电子信息行为未经处理，数量或者数额累计计算构成犯罪的，应当依法定罪处罚。"},{"i":10,"n":"第十条","txt":"单位实施制作、复制、出版、贩卖、传播淫秽电子信息犯罪的，依照《中华人民共和国刑法》、《最高人民法院、最高人民检察院关于办理利用互联网、移动通讯终端、声讯台制作、复制、出版、贩卖、传播淫秽电子信息刑事案件具体应用法律若干问题的解释》和本解释规定的相应个人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":11,"n":"第十一条","txt":"对于以牟利为目的，实施制作、复制、出版、贩卖、传播淫秽电子信息犯罪的，人民法院应当综合考虑犯罪的违法所得、社会危害性等情节，依法判处罚金或者没收财产。罚金数额一般在违法所得的一倍以上五倍以下。"},{"i":12,"n":"第十二条","txt":"《最高人民法院、最高人民检察院关于办理利用互联网、移动通讯终端、声讯台制作、复制、出版、贩卖、传播淫秽电子信息刑事案件具体应用法律若干问题的解释》和本解释所称网站，是指可以通过互联网域名、IP地址等方式访问的内容提供站点。"},{"i":13,"n":"第十三条","txt":"以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanf81ddb":[{"i":1,"n":"第一条","txt":"具有下列情形之一的，应当认定为刑法第二百四十六条第一款规定的“捏造事实诽谤他人”："},{"i":2,"n":"第二条","txt":"利用信息网络诽谤他人，具有下列情形之一的，应当认定为刑法第二百四十六条第一款规定的“情节严重”："},{"i":3,"n":"第三条","txt":"利用信息网络诽谤他人，具有下列情形之一的，应当认定为刑法第二百四十六条第二款规定的“严重危害社会秩序和国家利益”："},{"i":4,"n":"第四条","txt":"一年内多次实施利用信息网络诽谤他人行为未经处理，诽谤信息实际被点击、浏览、转发次数累计计算构成犯罪的，应当依法定罪处罚。"},{"i":5,"n":"第五条","txt":"利用信息网络辱骂、恐吓他人，情节恶劣，破坏社会秩序的，依照刑法第二百九十三条第一款第（二）项的规定，以寻衅滋事罪定罪处罚。"},{"i":6,"n":"第六条","txt":"以在信息网络上发布、删除等方式处理网络信息为由，威胁、要挟他人，索取公私财物，数额较大，或者多次实施上述行为的，依照刑法第二百七十四条的规定，以敲诈勒索罪定罪处罚。"},{"i":7,"n":"第七条","txt":"违反国家规定，以营利为目的，通过信息网络有偿提供删除信息服务，或者明知是虚假信息，通过信息网络有偿提供发布信息等服务，扰乱市场秩序，具有下列情形之一的，属于非法经营行为“情节严重”，依照刑法第二百二十五条第（四）项的规定，以非法经营罪定罪处罚："},{"i":8,"n":"第八条","txt":"明知他人利用信息网络实施诽谤、寻衅滋事、敲诈勒索、非法经营等犯罪，为其提供资金、场所、技术支持等帮助的，以共同犯罪论处。"},{"i":9,"n":"第九条","txt":"利用信息网络实施诽谤、寻衅滋事、敲诈勒索、非法经营犯罪，同时又构成刑法第二百二十一条规定的损害商业信誉、商品声誉罪，第二百七十八条规定的煽动暴力抗拒法律实施罪，第二百九十一条之一规定的编造、故意传播虚假恐怖信息罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"本解释所称信息网络，包括以计算机、电视机、固定电话机、移动电话机等电子设备为终端的计算机互联网、广播电视网、固定通信网、移动通信网等信息网络，以及向公众开放的局域网络。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban9372c4":[{"i":1,"n":"第一条","txt":"有下列情形之一的，应当认定为刑法第一百一十四条、第一百一十五条第一款规定的“其他危险方法”："},{"i":2,"n":"第二条","txt":"对飞行中的民用航空器上的人员使用暴力，有下列情形之一的，应当认定为刑法第一百二十三条规定的“危及飞行安全”："},{"i":3,"n":"第三条","txt":"违反国家规定，破坏民航运输企业、民用机场、空中交通管制单位、民航运行保障单位等民航运行单位计算机信息系统功能、数据或者应用程序，或者故意制作、传播计算机病毒等破坏性程序，符合刑法第二百八十六条规定的，以破坏计算机信息系统罪定罪处罚。"},{"i":4,"n":"第四条","txt":"通过明示或者暗示方式，编造以发生严重威胁民航飞行安全的爆炸、生化、放射、劫持民用航空器等事件为内容、可能引起公众恐慌或者公共安全危机的信息，或者明知是编造的上述恐怖信息而故意传播，有下列情形之一的，依照刑法第二百九十一条之一第一款的规定，以编造、故意传播虚假恐怖信息罪定罪处罚："},{"i":5,"n":"第五条","txt":"民用航空器内发生的刑事案件，行为人在民用航空器飞行期间被抓获的，由行为发生后民用航空器最初降落地的人民法院管辖；必要时，可以由民用航空器始发地、经停地或者目的地的人民法院管辖。"},{"i":6,"n":"第六条","txt":"本解释所称“民用航空器”，是指从事公共航空运输和其他载人活动的民用航空器。"},{"i":7,"n":"第七条","txt":"本解释自2026年4月9日起施行。最高人民法院、最高人民检察院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban276c03":[{"i":1,"n":"第一条","txt":"刑法第一百三十四条第一款规定的犯罪主体，包括对生产、作业负有组织、指挥或者管理职责的负责人、管理人员、实际控制人、投资人等人员，以及直接从事生产、作业的人员。"},{"i":2,"n":"第二条","txt":"刑法第一百三十四条第二款规定的犯罪主体，包括对生产、作业负有组织、指挥或者管理职责的负责人、管理人员、实际控制人、投资人等人员。"},{"i":3,"n":"第三条","txt":"刑法第一百三十五条规定的“直接负责的主管人员和其他直接责任人员”，是指对安全生产设施或者安全生产条件不符合国家规定负有直接责任的生产经营单位负责人、管理人员、实际控制人、投资人，以及其他对安全生产设施或者安全生产条件负有管理、维护职责的人员。"},{"i":4,"n":"第四条","txt":"刑法第一百三十九条之一规定的“负有报告职责的人员”，是指负有组织、指挥或者管理职责的负责人、管理人员、实际控制人、投资人，以及其他负有报告职责的人员。"},{"i":5,"n":"第五条","txt":"明知存在事故隐患、继续作业存在危险，仍然违反有关安全管理的规定，实施下列行为之一的，应当认定为刑法第一百三十四条第二款规定的“强令他人违章冒险作业”："},{"i":6,"n":"第六条","txt":"实施刑法第一百三十二条、第一百三十四条第一款、第一百三十五条、第一百三十五条之一、第一百三十六条、第一百三十九条规定的行为，因而发生安全事故，具有下列情形之一的，应当认定为“造成严重后果”或者“发生重大伤亡事故或者造成其他严重后果”，对相关责任人员，处三年以下有期徒刑或者拘役："},{"i":7,"n":"第七条","txt":"实施刑法第一百三十二条、第一百三十四条第一款、第一百三十五条、第一百三十五条之一、第一百三十六条、第一百三十九条规定的行为，因而发生安全事故，具有下列情形之一的，对相关责任人员，处三年以上七年以下有期徒刑："},{"i":8,"n":"第八条","txt":"在安全事故发生后，负有报告职责的人员不报或者谎报事故情况，贻误事故抢救，具有下列情形之一的，应当认定为刑法第一百三十九条之一规定的“情节严重”："},{"i":9,"n":"第九条","txt":"在安全事故发生后，与负有报告职责的人员串通，不报或者谎报事故情况，贻误事故抢救，情节严重的，依照刑法第一百三十九条之一的规定，以共犯论处。"},{"i":10,"n":"第十条","txt":"在安全事故发生后，直接负责的主管人员和其他直接责任人员故意阻挠开展抢救，导致人员死亡或者重伤，或者为了逃避法律追究，对被害人进行隐藏、遗弃，致使被害人因无法得到救助而死亡或者重度残疾的，分别依照刑法第二百三十二条、第二百三十四条的规定，以故意杀人罪或者故意伤害罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"生产不符合保障人身、财产安全的国家标准、行业标准的安全设备，或者明知安全设备不符合保障人身、财产安全的国家标准、行业标准而进行销售，致使发生安全事故，造成严重后果的，依照刑法第一百四十六条的规定，以生产、销售不符合安全标准的产品罪定罪处罚。"},{"i":12,"n":"第十二条","txt":"实施刑法第一百三十二条、第一百三十四条至第一百三十九条之一规定的犯罪行为，具有下列情形之一的，从重处罚："},{"i":13,"n":"第十三条","txt":"实施刑法第一百三十二条、第一百三十四条至第一百三十九条之一规定的犯罪行为，在安全事故发生后积极组织、参与事故抢救，或者积极配合调查、主动赔偿损失的，可以酌情从轻处罚。"},{"i":14,"n":"第十四条","txt":"国家工作人员违反规定投资入股生产经营，构成本解释规定的有关犯罪的，或者国家工作人员的贪污、受贿犯罪行为与安全事故发生存在关联性的，从重处罚；同时构成贪污、受贿犯罪和危害生产安全犯罪的，依照数罪并罚的规定处罚。"},{"i":15,"n":"第十五条","txt":"国家机关工作人员在履行安全监督管理职责时滥用职权、玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，或者徇私舞弊，对发现的刑事案件依法应当移交司法机关追究刑事责任而不移交，情节严重的，分别依照刑法第三百九十七条、第四百零二条的规定，以滥用职权罪、玩忽职守罪或者徇私舞弊不移交刑事案件罪定罪处罚。"},{"i":16,"n":"第十六条","txt":"对于实施危害生产安全犯罪适用缓刑的犯罪分子，可以根据犯罪情况，禁止其在缓刑考验期限内从事与安全生产相关联的特定活动；对于被判处刑罚的犯罪分子，可以根据犯罪情况和预防再犯罪的需要，禁止其自刑罚执行完毕之日或者假释之日起三年至五年内从事与安全生产相关的职业。"},{"i":17,"n":"第十七条","txt":"本解释自2015年12月16日起施行。本解释施行后，最高人民法院、最高人民检察院《关于办理危害矿山生产安全刑事案件具体应用法律若干问题的解释》（法释〔2007〕5号）同时废止。最高人民法院、最高人民检察院此前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanc18a90":[{"i":1,"n":"第一条","txt":"明知存在事故隐患，继续作业存在危险，仍然违反有关安全管理的规定，有下列情形之一的，属于刑法第一百三十四条第二款规定的“强令他人违章冒险作业”："},{"i":2,"n":"第二条","txt":"刑法第一百三十四条之一规定的犯罪主体，包括对生产、作业负有组织、指挥或者管理职责的负责人、管理人员、实际控制人、投资人等人员，以及直接从事生产、作业的人员。"},{"i":3,"n":"第三条","txt":"因存在重大事故隐患被依法责令停产停业、停止施工、停止使用有关设备、设施、场所或者立即采取排除危险的整改措施，有下列情形之一的，属于刑法第一百三十四条之一第二项规定的“拒不执行”："},{"i":4,"n":"第四条","txt":"刑法第一百三十四条第二款和第一百三十四条之一第二项规定的“重大事故隐患”，依照法律、行政法规、部门规章、强制性标准以及有关行政规范性文件进行认定。"},{"i":5,"n":"第五条","txt":"在生产、作业中违反有关安全管理的规定，有刑法第一百三十四条之一规定情形之一，因而发生重大伤亡事故或者造成其他严重后果，构成刑法第一百三十四条、第一百三十五条至第一百三十九条等规定的重大责任事故罪、重大劳动安全事故罪、危险物品肇事罪、工程重大安全事故罪等犯罪的，依照该规定定罪处罚。"},{"i":6,"n":"第六条","txt":"承担安全评价职责的中介组织的人员提供的证明文件有下列情形之一的，属于刑法第二百二十九条第一款规定的“虚假证明文件”："},{"i":7,"n":"第七条","txt":"承担安全评价职责的中介组织的人员故意提供虚假证明文件，有下列情形之一的，属于刑法第二百二十九条第一款规定的“情节严重”："},{"i":8,"n":"第八条","txt":"承担安全评价职责的中介组织的人员，严重不负责任，出具的证明文件有重大失实，有下列情形之一的，属于刑法第二百二十九条第三款规定的“造成严重后果”："},{"i":9,"n":"第九条","txt":"承担安全评价职责的中介组织犯刑法第二百二十九条规定之罪的，对该中介组织判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本解释第七条、第八条的规定处罚。"},{"i":10,"n":"第十条","txt":"有刑法第一百三十四条之一行为，积极配合公安机关或者负有安全生产监督管理职责的部门采取措施排除事故隐患，确有悔改表现，认罪认罚的，可以依法从宽处罚；犯罪情节轻微不需要判处刑罚的，可以不起诉或者免予刑事处罚；情节显著轻微危害不大的，不作为犯罪处理。"},{"i":11,"n":"第十一条","txt":"有本解释规定的行为，被不起诉或者免予刑事处罚，需要给予行政处罚、政务处分或者其他处分的，依法移送有关主管机关处理。"},{"i":12,"n":"第十二条","txt":"本解释自2022年12月19日起施行。最高人民法院、最高人民检察院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanab3c29":[{"i":1,"n":"第一条","txt":"纳税人进行虚假纳税申报，具有下列情形之一的，应当认定为刑法第二百零一条第一款规定的“欺骗、隐瞒手段”："},{"i":2,"n":"第二条","txt":"纳税人逃避缴纳税款十万元以上、五十万元以上的，应当分别认定为刑法第二百零一条第一款规定的“数额较大”、“数额巨大”。"},{"i":3,"n":"第三条","txt":"纳税人有刑法第二百零一条第一款规定的逃避缴纳税款行为，在公安机关立案前，经税务机关依法下达追缴通知后，在规定的期限或者批准延缓、分期缴纳的期限内足额补缴应纳税款，缴纳滞纳金，并全部履行税务机关作出的行政处罚决定的，不予追究刑事责任。但是，五年内因逃避缴纳税款受过刑事处罚或者被税务机关给予二次以上行政处罚的除外。"},{"i":4,"n":"第四条","txt":"刑法第二百零一条第一款规定的“逃避缴纳税款数额”，是指在确定的纳税期间，不缴或者少缴税务机关负责征收的各税种税款的总额。"},{"i":5,"n":"第五条","txt":"以暴力、威胁方法拒不缴纳税款，具有下列情形之一的，应当认定为刑法第二百零二条规定的“情节严重”："},{"i":6,"n":"第六条","txt":"纳税人欠缴应纳税款，为逃避税务机关追缴，具有下列情形之一的，应当认定为刑法第二百零三条规定的“采取转移或者隐匿财产的手段”："},{"i":7,"n":"第七条","txt":"具有下列情形之一的，应当认定为刑法第二百零四条第一款规定的“假报出口或者其他欺骗手段”："},{"i":8,"n":"第八条","txt":"骗取国家出口退税款数额十万元以上、五十万元以上、五百万元以上的，应当分别认定为刑法第二百零四条第一款规定的“数额较大”、“数额巨大”、“数额特别巨大”。"},{"i":9,"n":"第九条","txt":"实施骗取国家出口退税行为，没有实际取得出口退税款的，可以比照既遂犯从轻或者减轻处罚。"},{"i":10,"n":"第十条","txt":"具有下列情形之一的，应当认定为刑法第二百零五条第一款规定的“虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票”："},{"i":11,"n":"第十一条","txt":"虚开增值税专用发票、用于骗取出口退税、抵扣税款的其他发票，税款数额在十万元以上的，应当依照刑法第二百零五条的规定定罪处罚；虚开税款数额在五十万元以上、五百万元以上的，应当分别认定为刑法第二百零五条第一款规定的“数额较大”、“数额巨大”。"},{"i":12,"n":"第十二条","txt":"具有下列情形之一的，应当认定为刑法第二百零五条之一第一款规定的“虚开刑法第二百零五条规定以外的其他发票”："},{"i":13,"n":"第十三条","txt":"具有下列情形之一的，应当认定为刑法第二百零五条之一第一款规定的“情节严重”："},{"i":14,"n":"第十四条","txt":"伪造或者出售伪造的增值税专用发票，具有下列情形之一的，应当依照刑法第二百零六条的规定定罪处罚："},{"i":15,"n":"第十五条","txt":"非法出售增值税专用发票的，依照本解释第十四条的定罪量刑标准定罪处罚。"},{"i":16,"n":"第十六条","txt":"非法购买增值税专用发票或者购买伪造的增值税专用发票票面税额二十万元以上的，或者二十份以上且票面税额十万元以上的，应当依照刑法第二百零八条第一款的规定定罪处罚。"},{"i":17,"n":"第十七条","txt":"伪造、擅自制造或者出售伪造、擅自制造的用于骗取出口退税、抵扣税款的其他发票，具有下列情形之一的，应当依照刑法第二百零九条第一款的规定定罪处罚："},{"i":18,"n":"第十八条","txt":"具有下列情形之一的，应当认定为刑法第二百一十条之一第一款规定的“数量较大”："},{"i":19,"n":"第十九条","txt":"明知他人实施危害税收征管犯罪而仍为其提供账号、资信证明或者其他帮助的，以相应犯罪的共犯论处。"},{"i":20,"n":"第二十条","txt":"单位实施危害税收征管犯罪的定罪量刑标准，依照本解释规定的标准执行。"},{"i":21,"n":"第二十一条","txt":"实施危害税收征管犯罪，造成国家税款损失，行为人补缴税款、挽回税收损失，有效合规整改的，可以从宽处罚；犯罪情节轻微不需要判处刑罚的，可以不起诉或者免予刑事处罚；情节显著轻微危害不大的，不作为犯罪处理。"},{"i":22,"n":"第二十二条","txt":"本解释自2024年3月20日起施行。《最高人民法院关于适用〈全国人民代表大会常务委员会关于惩治虚开、伪造和非法出售增值税专用发票犯罪的决定〉的若干问题的解释》（法发〔1996〕30号）、《最高人民法院关于审理骗取出口退税刑事案件具体应用法律若干问题的解释》（法释〔2002〕30号）、《最高人民法院关于审理偷税、抗税刑事案件具体应用法律若干问题的解释》（法释〔2002〕33号）同时废止；最高人民法院、最高人民检察院以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubana72741":[{"i":1,"n":"第一条","txt":"生产、销售、提供假药，具有下列情形之一的，应当酌情从重处罚："},{"i":2,"n":"第二条","txt":"生产、销售、提供假药，具有下列情形之一的，应当认定为刑法第一百四十一条规定的“对人体健康造成严重危害”："},{"i":3,"n":"第三条","txt":"生产、销售、提供假药，具有下列情形之一的，应当认定为刑法第一百四十一条规定的“其他严重情节”："},{"i":4,"n":"第四条","txt":"生产、销售、提供假药，具有下列情形之一的，应当认定为刑法第一百四十一条规定的“其他特别严重情节”："},{"i":5,"n":"第五条","txt":"生产、销售、提供劣药，具有本解释第一条规定情形之一的，应当酌情从重处罚。"},{"i":6,"n":"第六条","txt":"以生产、销售、提供假药、劣药为目的，合成、精制、提取、储存、加工炮制药品原料，或者在将药品原料、辅料、包装材料制成成品过程中，进行配料、混合、制剂、储存、包装的，应当认定为刑法第一百四十一条、第一百四十二条规定的“生产”。"},{"i":7,"n":"第七条","txt":"实施妨害药品管理的行为，具有下列情形之一的，应当认定为刑法第一百四十二条之一规定的“足以严重危害人体健康”："},{"i":8,"n":"第八条","txt":"实施妨害药品管理的行为，具有本解释第二条规定情形之一的，应当认定为刑法第一百四十二条之一规定的“对人体健康造成严重危害”。"},{"i":9,"n":"第九条","txt":"明知他人实施危害药品安全犯罪，而有下列情形之一的，以共同犯罪论处："},{"i":10,"n":"第十条","txt":"办理生产、销售、提供假药、生产、销售、提供劣药、妨害药品管理等刑事案件，应当结合行为人的从业经历、认知能力、药品质量、进货渠道和价格、销售渠道和价格以及生产、销售方式等事实综合判断认定行为人的主观故意。具有下列情形之一的，可以认定行为人有实施相关犯罪的主观故意，但有证据证明确实不具有故意的除外："},{"i":11,"n":"第十一条","txt":"以提供给他人生产、销售、提供药品为目的，违反国家规定，生产、销售不符合药用要求的原料、辅料，符合刑法第一百四十条规定的，以生产、销售伪劣产品罪从重处罚；同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":12,"n":"第十二条","txt":"广告主、广告经营者、广告发布者违反国家规定，利用广告对药品作虚假宣传，情节严重的，依照刑法第二百二十二条的规定，以虚假广告罪定罪处罚。"},{"i":13,"n":"第十三条","txt":"明知系利用医保骗保购买的药品而非法收购、销售，金额五万元以上的，应当依照刑法第三百一十二条的规定，以掩饰、隐瞒犯罪所得罪定罪处罚；指使、教唆、授意他人利用医保骗保购买药品，进而非法收购、销售，符合刑法第二百六十六条规定的，以诈骗罪定罪处罚。"},{"i":14,"n":"第十四条","txt":"负有药品安全监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，构成药品监管渎职罪，同时构成商检徇私舞弊罪、商检失职罪等其他渎职犯罪的，依照处罚较重的规定定罪处罚。"},{"i":15,"n":"第十五条","txt":"对于犯生产、销售、提供假药罪、生产、销售、提供劣药罪、妨害药品管理罪的，应当结合被告人的犯罪数额、违法所得，综合考虑被告人缴纳罚金的能力，依法判处罚金。罚金一般应当在生产、销售、提供的药品金额二倍以上；共同犯罪的，对各共同犯罪人合计判处的罚金一般应当在生产、销售、提供的药品金额二倍以上。"},{"i":16,"n":"第十六条","txt":"对于犯生产、销售、提供假药罪、生产、销售、提供劣药罪、妨害药品管理罪的，应当依照刑法规定的条件，严格缓刑、免予刑事处罚的适用。对于被判处刑罚的，可以根据犯罪情况和预防再犯罪的需要，依法宣告职业禁止或者禁止令。《中华人民共和国药品管理法》等法律、行政法规另有规定的，从其规定。"},{"i":17,"n":"第十七条","txt":"单位犯生产、销售、提供假药罪、生产、销售、提供劣药罪、妨害药品管理罪的，对单位判处罚金，并对直接负责的主管人员和其他直接责任人员，依照本解释规定的自然人犯罪的定罪量刑标准处罚。"},{"i":18,"n":"第十八条","txt":"根据民间传统配方私自加工药品或者销售上述药品，数量不大，且未造成他人伤害后果或者延误诊治的，或者不以营利为目的实施带有自救、互助性质的生产、进口、销售药品的行为，不应当认定为犯罪。"},{"i":19,"n":"第十九条","txt":"刑法第一百四十一条、第一百四十二条规定的“假药”“劣药”，依照《中华人民共和国药品管理法》的规定认定。"},{"i":20,"n":"第二十条","txt":"对于生产、提供药品的金额，以药品的货值金额计算；销售药品的金额，以所得和可得的全部违法收入计算。"},{"i":21,"n":"第二十一条","txt":"本解释自2022年3月6日起施行。本解释公布施行后，《最高人民法院、最高人民检察院关于办理危害药品安全刑事案件适用法律若干问题的解释》（法释〔2014〕14号）、《最高人民法院、最高人民检察院关于办理药品、医疗器械注册申请材料造假刑事案件适用法律若干问题的解释》（法释〔2017〕15号）同时废止。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban6378a6":[{"i":1,"n":"第一条","txt":"非法获取计算机信息系统数据或者非法控制计算机信息系统，具有下列情形之一的，应当认定为刑法第二百八十五条第二款规定的“情节严重”："},{"i":2,"n":"第二条","txt":"具有下列情形之一的程序、工具，应当认定为刑法第二百八十五条第三款规定的“专门用于侵入、非法控制计算机信息系统的程序、工具”："},{"i":3,"n":"第三条","txt":"提供侵入、非法控制计算机信息系统的程序、工具，具有下列情形之一的，应当认定为刑法第二百八十五条第三款规定的“情节严重”："},{"i":4,"n":"第四条","txt":"破坏计算机信息系统功能、数据或者应用程序，具有下列情形之一的，应当认定为刑法第二百八十六条第一款和第二款规定的“后果严重”："},{"i":5,"n":"第五条","txt":"具有下列情形之一的程序，应当认定为刑法第二百八十六条第三款规定的“计算机病毒等破坏性程序”："},{"i":6,"n":"第六条","txt":"故意制作、传播计算机病毒等破坏性程序，影响计算机系统正常运行，具有下列情形之一的，应当认定为刑法第二百八十六条第三款规定的“后果严重”："},{"i":7,"n":"第七条","txt":"明知是非法获取计算机信息系统数据犯罪所获取的数据、非法控制计算机信息系统犯罪所获取的计算机信息系统控制权，而予以转移、收购、代为销售或者以其他方法掩饰、隐瞒，违法所得五千元以上的，应当依照刑法第三百一十二条第一款的规定，以掩饰、隐瞒犯罪所得罪定罪处罚。"},{"i":8,"n":"第八条","txt":"以单位名义或者单位形式实施危害计算机信息系统安全犯罪，达到本解释规定的定罪量刑标准的，应当依照刑法第二百八十五条、第二百八十六条的规定追究直接负责的主管人员和其他直接责任人员的刑事责任。"},{"i":9,"n":"第九条","txt":"明知他人实施刑法第二百八十五条、第二百八十六条规定的行为，具有下列情形之一的，应当认定为共同犯罪，依照刑法第二百八十五条、第二百八十六条的规定处罚："},{"i":10,"n":"第十条","txt":"对于是否属于刑法第二百八十五条、第二百八十六条规定的“国家事务、国防建设、尖端科学技术领域的计算机信息系统”、“专门用于侵入、非法控制计算机信息系统的程序、工具”、“计算机病毒等破坏性程序”难以确定的，应当委托省级以上负责计算机信息系统安全保护管理工作的部门检验。司法机关根据检验结论，并结合案件具体情况认定。"},{"i":11,"n":"第十一条","txt":"本解释所称“计算机信息系统”和“计算机系统”，是指具备自动处理数据功能的系统，包括计算机、网络设备、通信设备、自动化控制设备等。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban1d5539":[{"i":1,"n":"第一条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“足以造成严重食物中毒事故或者其他严重食源性疾病”："},{"i":2,"n":"第二条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“对人体健康造成严重危害”："},{"i":3,"n":"第三条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“其他严重情节”："},{"i":4,"n":"第四条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“后果特别严重”："},{"i":5,"n":"第五条","txt":"在食品生产、销售、运输、贮存等过程中，违反食品安全标准，超限量或者超范围滥用食品添加剂，足以造成严重食物中毒事故或者其他严重食源性疾病的，依照刑法第一百四十三条的规定以生产、销售不符合安全标准的食品罪定罪处罚。"},{"i":6,"n":"第六条","txt":"生产、销售有毒、有害食品，具有本解释第二条规定情形之一的，应当认定为刑法第一百四十四条规定的“对人体健康造成严重危害”。"},{"i":7,"n":"第七条","txt":"生产、销售有毒、有害食品，具有下列情形之一的，应当认定为刑法第一百四十四条规定的“其他严重情节”："},{"i":8,"n":"第八条","txt":"生产、销售有毒、有害食品，生产、销售金额五十万元以上，或者具有本解释第四条第二项至第六项规定的情形之一的，应当认定为刑法第一百四十四条规定的“其他特别严重情节”。"},{"i":9,"n":"第九条","txt":"下列物质应当认定为刑法第一百四十四条规定的“有毒、有害的非食品原料”："},{"i":10,"n":"第十条","txt":"刑法第一百四十四条规定的“明知”，应当综合行为人的认知能力、食品质量、进货或者销售的渠道及价格等主、客观因素进行认定。"},{"i":11,"n":"第十一条","txt":"在食品生产、销售、运输、贮存等过程中，掺入有毒、有害的非食品原料，或者使用有毒、有害的非食品原料生产食品的，依照刑法第一百四十四条的规定以生产、销售有毒、有害食品罪定罪处罚。"},{"i":12,"n":"第十二条","txt":"在食品生产、销售、运输、贮存等过程中，使用不符合食品安全标准的食品包装材料、容器、洗涤剂、消毒剂，或者用于食品生产经营的工具、设备等，造成食品被污染，符合刑法第一百四十三条、第一百四十四条规定的，以生产、销售不符合安全标准的食品罪或者生产、销售有毒、有害食品罪定罪处罚。"},{"i":13,"n":"第十三条","txt":"生产、销售不符合食品安全标准的食品，有毒、有害食品，符合刑法第一百四十三条、第一百四十四条规定的，以生产、销售不符合安全标准的食品罪或者生产、销售有毒、有害食品罪定罪处罚。同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":14,"n":"第十四条","txt":"明知他人生产、销售不符合食品安全标准的食品，有毒、有害食品，具有下列情形之一的，以生产、销售不符合安全标准的食品罪或者生产、销售有毒、有害食品罪的共犯论处："},{"i":15,"n":"第十五条","txt":"生产、销售不符合食品安全标准的食品添加剂，用于食品的包装材料、容器、洗涤剂、消毒剂，或者用于食品生产经营的工具、设备等，符合刑法第一百四十条规定的，以生产、销售伪劣产品罪定罪处罚。"},{"i":16,"n":"第十六条","txt":"以提供给他人生产、销售食品为目的，违反国家规定，生产、销售国家禁止用于食品生产、销售的非食品原料，情节严重的，依照刑法第二百二十五条的规定以非法经营罪定罪处罚。"},{"i":17,"n":"第十七条","txt":"违反国家规定，私设生猪屠宰厂（场），从事生猪屠宰、销售等经营活动，情节严重的，依照刑法第二百二十五条的规定以非法经营罪定罪处罚。"},{"i":18,"n":"第十八条","txt":"实施本解释规定的非法经营行为，非法经营数额在十万元以上，或者违法所得数额在五万元以上的，应当认定为刑法第二百二十五条规定的“情节严重”；非法经营数额在五十万元以上，或者违法所得数额在二十五万元以上的，应当认定为刑法第二百二十五条规定的“情节特别严重”。"},{"i":19,"n":"第十九条","txt":"违反国家规定，利用广告对保健食品或者其他食品作虚假宣传，符合刑法第二百二十二条规定的，以虚假广告罪定罪处罚；以非法占有为目的，利用销售保健食品或者其他食品诈骗财物，符合刑法第二百六十六条规定的，以诈骗罪定罪处罚。同时构成生产、销售伪劣产品罪等其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":20,"n":"第二十条","txt":"负有食品安全监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，构成食品监管渎职罪，同时构成徇私舞弊不移交刑事案件罪、商检徇私舞弊罪、动植物检疫徇私舞弊罪、放纵制售伪劣商品犯罪行为罪等其他渎职犯罪的，依照处罚较重的规定定罪处罚。"},{"i":21,"n":"第二十一条","txt":"犯生产、销售不符合安全标准的食品罪，生产、销售有毒、有害食品罪，一般应当依法判处生产、销售金额二倍以上的罚金。"},{"i":22,"n":"第二十二条","txt":"对实施本解释规定之犯罪的犯罪分子，应当依照刑法规定的条件，严格适用缓刑、免予刑事处罚。对于依法适用缓刑的，可以根据犯罪情况，同时宣告禁止令。"},{"i":23,"n":"第二十三条","txt":"单位实施本解释规定的犯罪的，对单位判处罚金，并对直接负责的主管人员和其他直接责任人员，依照本解释规定的定罪量刑标准处罚。"},{"i":24,"n":"第二十四条","txt":"“足以造成严重食物中毒事故或者其他严重食源性疾病”“有毒、有害的非食品原料”等专门性问题难以确定的，司法机关可以依据鉴定意见、检验报告、地市级以上相关行政主管部门组织出具的书面意见，结合其他证据作出认定。必要时，专门性问题由省级以上相关行政主管部门组织出具书面意见。"},{"i":25,"n":"第二十五条","txt":"本解释所称“二年内”，以第一次违法行为受到行政处罚的生效之日与又实施相应行为之日的时间间隔计算确定。"},{"i":26,"n":"第二十六条","txt":"本解释自2022年1月1日起施行。本解释公布实施后，《最高人民法院、最高人民检察院关于办理危害食品安全刑事案件适用法律若干问题的解释》（法释〔2013〕12号）同时废止；之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban6b67b7":[{"i":1,"n":"第一条","txt":"领导、策划、指挥他人偷越国（边）境或者在首要分子指挥下，实施拉拢、引诱、介绍他人偷越国（边）境等行为的，应当认定为刑法第三百一十八条规定的“组织他人偷越国（边）境”。"},{"i":2,"n":"第二条","txt":"为组织他人偷越国（边）境，编造出境事由、身份信息或者相关的境外关系证明的，应当认定为刑法第三百一十九条第一款规定的“弄虚作假”。"},{"i":3,"n":"第三条","txt":"刑法第三百二十条规定的“出入境证件”，包括本解释第二条第二款所列的证件以及其他入境时需要查验的资料。"},{"i":4,"n":"第四条","txt":"运送他人偷越国（边）境人数在十人以上的，应当认定为刑法第三百二十一条第一款第（一）项规定的“人数众多”；违法所得数额在二十万元以上的，应当认定为刑法第三百二十一条第一款第（三）项规定的“违法所得数额巨大”。"},{"i":5,"n":"第五条","txt":"偷越国（边）境，具有下列情形之一的，应当认定为刑法第三百二十二条规定的“情节严重”："},{"i":6,"n":"第六条","txt":"具有下列情形之一的，应当认定为刑法第六章第三节规定的“偷越国（边）境”行为："},{"i":7,"n":"第七条","txt":"以单位名义或者单位形式组织他人偷越国（边）境、为他人提供伪造、变造的出入境证件或者运送他人偷越国（边）境的，应当依照刑法第三百一十八条、第三百二十条、第三百二十一条的规定追究直接负责的主管人员和其他直接责任人员的刑事责任。"},{"i":8,"n":"第八条","txt":"实施组织他人偷越国（边）境犯罪，同时构成骗取出境证件罪、提供伪造、变造的出入境证件罪、出售出入境证件罪、运送他人偷越国（边）境罪的，依照处罚较重的规定定罪处罚。"},{"i":9,"n":"第九条","txt":"对跨地区实施的不同妨害国（边）境管理犯罪，符合并案处理要求，有关地方公安机关依照法律和相关规定一并立案侦查，需要提请批准逮捕、移送审查起诉、提起公诉的，由该公安机关所在地的同级人民检察院、人民法院依法受理。"},{"i":10,"n":"第十条","txt":"本解释发布实施后，《最高人民法院关于审理组织、运送他人偷越国（边）境等刑事案件适用法律若干问题的解释》（法释〔2002〕3号）不再适用。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban49263c":[{"i":1,"n":"第一条","txt":"刑法第一百五十一条规定的“国家禁止出口的文物”，依照《中华人民共和国文物保护法》规定的“国家禁止出境的文物”的范围认定。"},{"i":2,"n":"第二条","txt":"盗窃一般文物、三级文物、二级以上文物的，应当分别认定为刑法第二百六十四条规定的“数额较大”“数额巨大”“数额特别巨大”。"},{"i":3,"n":"第三条","txt":"全国重点文物保护单位、省级文物保护单位的本体，应当认定为刑法第三百二十四条第一款规定的“被确定为全国重点文物保护单位、省级文物保护单位的文物”。"},{"i":4,"n":"第四条","txt":"风景名胜区的核心景区以及未被确定为全国重点文物保护单位、省级文物保护单位的古文化遗址、古墓葬、古建筑、石窟寺、石刻、壁画、近代现代重要史迹和代表性建筑等不可移动文物的本体，应当认定为刑法第三百二十四条第二款规定的“国家保护的名胜古迹”。"},{"i":5,"n":"第五条","txt":"过失损毁国家保护的珍贵文物或者被确定为全国重点文物保护单位、省级文物保护单位的文物，具有本解释第三条第二款第一项至第三项规定情形之一的，应当认定为刑法第三百二十四条第三款规定的“造成严重后果”。"},{"i":6,"n":"第六条","txt":"出售或者为出售而收购、运输、储存《中华人民共和国文物保护法》规定的“国家禁止买卖的文物”的，应当认定为刑法第三百二十六条规定的“倒卖国家禁止经营的文物”。"},{"i":7,"n":"第七条","txt":"国有博物馆、图书馆以及其他国有单位，违反文物保护法规，将收藏或者管理的国家保护的文物藏品出售或者私自送给非国有单位或者个人的，依照刑法第三百二十七条的规定，以非法出售、私赠文物藏品罪追究刑事责任。"},{"i":8,"n":"第八条","txt":"刑法第三百二十八条第一款规定的“古文化遗址、古墓葬”包括水下古文化遗址、古墓葬。“古文化遗址、古墓葬”不以公布为不可移动文物的古文化遗址、古墓葬为限。"},{"i":9,"n":"第九条","txt":"明知是盗窃文物、盗掘古文化遗址、古墓葬等犯罪所获取的三级以上文物，而予以窝藏、转移、收购、加工、代为销售或者以其他方法掩饰、隐瞒的，依照刑法第三百一十二条的规定，以掩饰、隐瞒犯罪所得罪追究刑事责任。"},{"i":10,"n":"第十条","txt":"国家机关工作人员严重不负责任，造成珍贵文物损毁或者流失，具有下列情形之一的，应当认定为刑法第四百一十九条规定的“后果严重”："},{"i":11,"n":"第十一条","txt":"单位实施走私文物、倒卖文物等行为，构成犯罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":12,"n":"第十二条","txt":"针对不可移动文物整体实施走私、盗窃、倒卖等行为的，根据所属不可移动文物的等级，依照本解释第一条、第二条、第六条的规定定罪量刑："},{"i":13,"n":"第十三条","txt":"案件涉及不同等级的文物的，按照高级别文物的量刑幅度量刑；有多件同级文物的，五件同级文物视为一件高一级文物，但是价值明显不相当的除外。"},{"i":14,"n":"第十四条","txt":"依照文物价值定罪量刑的，根据涉案文物的有效价格证明认定文物价值；无有效价格证明，或者根据价格证明认定明显不合理的，根据销赃数额认定，或者结合本解释第十五条规定的鉴定意见、报告认定。"},{"i":15,"n":"第十五条","txt":"在行为人实施有关行为前，文物行政部门已对涉案文物及其等级作出认定的，可以直接对有关案件事实作出认定。"},{"i":16,"n":"第十六条","txt":"实施本解释第一条、第二条、第六条至第九条规定的行为，虽已达到应当追究刑事责任的标准，但行为人系初犯，积极退回或者协助追回文物，未造成文物损毁，并确有悔罪表现的，可以认定为犯罪情节轻微，不起诉或者免予刑事处罚。"},{"i":17,"n":"第十七条","txt":"走私、盗窃、损毁、倒卖、盗掘或者非法转让具有科学价值的古脊椎动物化石、古人类化石的，依照刑法和本解释的有关规定定罪量刑。"},{"i":18,"n":"第十八条","txt":"本解释自2016年1月1日起施行。本解释公布施行后，最高人民法院、最高人民检察院《关于办理盗窃、盗掘、非法经营和走私文物的案件具体应用法律的若干问题的解释》（法（研）发〔1987〕32号）同时废止；之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanf2d3a7":[{"i":1,"n":"第一条","txt":"伪造、变造、买卖或者盗窃、抢夺武装部队公文、证件、印章，具有下列情形之一的，应当依照刑法第三百七十五条第一款的规定，以伪造、变造、买卖武装部队公文、证件、印章罪或者盗窃、抢夺武装部队公文、证件、印章罪定罪处罚："},{"i":2,"n":"第二条","txt":"非法生产、买卖武装部队现行装备的制式服装，具有下列情形之一的，应当认定为刑法第三百七十五条第二款规定的“情节严重”，以非法生产、买卖武装部队制式服装罪定罪处罚："},{"i":3,"n":"第三条","txt":"伪造、盗窃、买卖或者非法提供、使用武装部队车辆号牌等专用标志，具有下列情形之一的，应当认定为刑法第三百七十五条第三款规定的“情节严重”，以伪造、盗窃、买卖、非法提供、非法使用武装部队专用标志罪定罪处罚："},{"i":4,"n":"第四条","txt":"买卖、盗窃、抢夺伪造、变造的武装部队公文、证件、印章的，买卖仿制的现行装备的武装部队制式服装情节严重的，盗窃、买卖、提供、使用伪造、变造的武装部队车辆号牌等专用标志情节严重的，应当追究刑事责任。定罪量刑标准适用本解释第一至第三条的规定。"},{"i":5,"n":"第五条","txt":"明知他人实施刑法第三百七十五条规定的犯罪行为，而为其生产、提供专用材料或者提供资金、账号、技术、生产经营场所等帮助的，以共犯论处。"},{"i":6,"n":"第六条","txt":"实施刑法第三百七十五条规定的犯罪行为，同时又构成逃税、诈骗、冒充军人招摇撞骗等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"单位实施刑法第三百七十五条第二款、第三款规定的犯罪行为，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，分别依照本解释的有关规定处罚。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban9348a9":[{"i":1,"n":"第一条","txt":"故意传播突发传染病病原体，危害公共安全的，依照刑法第一百一十四条、第一百一十五条第一款的规定，按照以危险方法危害公共安全罪定罪处罚。"},{"i":2,"n":"第二条","txt":"在预防、控制突发传染病疫情等灾害期间，生产、销售伪劣的防治、防护产品、物资，或者生产、销售用于防治传染病的假药、劣药，构成犯罪的，分别依照刑法第一百四十条、第一百四十一条、第一百四十二条的规定，以生产、销售伪劣产品罪，生产、销售假药罪或者生产、销售劣药罪定罪，依法从重处罚。"},{"i":3,"n":"第三条","txt":"在预防、控制突发传染病疫情等灾害期间，生产用于防治传染病的不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，或者销售明知是用于防治传染病的不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，不具有防护、救治功能，足以严重危害人体健康的，依照刑法第一百四十五条的规定，以生产、销售不符合标准的医用器材罪定罪，依法从重处罚。"},{"i":4,"n":"第四条","txt":"国有公司、企业、事业单位的工作人员，在预防、控制突发传染病疫情等灾害的工作中，由于严重不负责任或者滥用职权，造成国有公司、企业破产或者严重损失，致使国家利益遭受重大损失的，依照刑法第一百六十八条的规定，以国有公司、企业、事业单位人员失职罪或者国有公司、企业、事业单位人员滥用职权罪定罪处罚。"},{"i":5,"n":"第五条","txt":"广告主、广告经营者、广告发布者违反国家规定，假借预防、控制突发传染病疫情等灾害的名义，利用广告对所推销的商品或者服务作虚假宣传，致使多人上当受骗，违法所得数额较大或者有其他严重情节的，依照刑法第二百二十二条的规定，以虚假广告罪定罪处罚。"},{"i":6,"n":"第六条","txt":"违反国家在预防、控制突发传染病疫情等灾害期间有关市场经营、价格管理等规定，哄抬物价、牟取暴利，严重扰乱市场秩序，违法所得数额较大或者有其他严重情节的，依照刑法第二百二十五条第（四）项的规定，以非法经营罪定罪，依法从重处罚。"},{"i":7,"n":"第七条","txt":"在预防、控制突发传染病疫情等灾害期间，假借研制、生产或者销售用于预防、控制突发传染病疫情等灾害用品的名义，诈骗公私财物数额较大的，依照刑法有关诈骗罪的规定定罪，依法从重处罚。"},{"i":8,"n":"第八条","txt":"以暴力、威胁方法阻碍国家机关工作人员、红十字会工作人员依法履行为防治突发传染病疫情等灾害而采取的防疫、检疫、强制隔离、隔离治疗等预防、控制措施的，依照刑法第二百七十七条第一款、第三款的规定，以妨害公务罪定罪处罚。"},{"i":9,"n":"第九条","txt":"在预防、控制突发传染病疫情等灾害期间，聚众“打砸抢”，致人伤残、死亡的，依照刑法第二百八十九条、第二百三十四条、第二百三十二条的规定，以故意伤害罪或者故意杀人罪定罪，依法从重处罚。对毁坏或者抢走公私财物的首要分子，依照刑法第二百八十九条、第二百六十三条的规定，以抢劫罪定罪，依法从重处罚。"},{"i":10,"n":"第十条","txt":"编造与突发传染病疫情等灾害有关的恐怖信息，或者明知是编造的此类恐怖信息而故意传播，严重扰乱社会秩序的，依照刑法第二百九十一条之一的规定，以编造、故意传播虚假恐怖信息罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"在预防、控制突发传染病疫情等灾害期间，强拿硬要或者任意损毁、占用公私财物情节严重，或者在公共场所起哄闹事，造成公共场所秩序严重混乱的，依照刑法第二百九十三条的规定，以寻衅滋事罪定罪，依法从重处罚。"},{"i":12,"n":"第十二条","txt":"未取得医师执业资格非法行医，具有造成突发传染病病人、病原携带者、疑似突发传染病病人贻误诊治或者造成交叉感染等严重情节的，依照刑法第三百三十六条第一款的规定，以非法行医罪定罪，依法从重处罚。"},{"i":13,"n":"第十三条","txt":"违反传染病防治法等国家有关规定，向土地、水体、大气排放、倾倒或者处置含传染病病原体的废物、有毒物质或者其他危险废物，造成突发传染病传播等重大环境污染事故，致使公私财产遭受重大损失或者人身伤亡的严重后果的，依照刑法第三百三十八条的规定，以重大环境污染事故罪定罪处罚。"},{"i":14,"n":"第十四条","txt":"贪污、侵占用于预防、控制突发传染病疫情等灾害的款物或者挪用归个人使用，构成犯罪的，分别依照刑法第三百八十二条、第三百八十三条、第二百七十一条、第三百八十四条、第二百七十二条的规定，以贪污罪、职务侵占罪、挪用公款罪、挪用资金罪定罪，依法从重处罚。"},{"i":15,"n":"第十五条","txt":"在预防、控制突发传染病疫情等灾害的工作中，负有组织、协调、指挥、灾害调查、控制、医疗救治、信息传递、交通运输、物资保障等职责的国家机关工作人员，滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，依照刑法第三百九十七条的规定，以滥用职权罪或者玩忽职守罪定罪处罚。"},{"i":16,"n":"第十六条","txt":"在预防、控制突发传染病疫情等灾害期间，从事传染病防治的政府卫生行政部门的工作人员，或者在受政府卫生行政部门委托代表政府卫生行政部门行使职权的组织中从事公务的人员，或者虽未列入政府卫生行政部门人员编制但在政府卫生行政部门从事公务的人员，在代表政府卫生行政部门行使职权时，严重不负责任，导致传染病传播或者流行，情节严重的，依照刑法第四百零九条的规定，以传染病防治失职罪定罪处罚。"},{"i":17,"n":"第十七条","txt":"人民法院、人民检察院办理有关妨害预防、控制突发传染病疫情等灾害的刑事案件，对于有自首、立功等悔罪表现的，依法从轻、减轻、免除处罚或者依法作出不起诉决定。"},{"i":18,"n":"第十八条","txt":"本解释所称“突发传染病疫情等灾害”，是指突然发生，造成或者可能造成社会公众健康严重损害的重大传染病疫情、群体性不明原因疾病以及其他严重影响公众健康的灾害。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanee1d6d":[{"i":1,"n":"第一条","txt":"行为人为寻求刺激、发泄情绪、逞强耍横等，无事生非，实施刑法第二百九十三条规定的行为的，应当认定为“寻衅滋事”。"},{"i":2,"n":"第二条","txt":"随意殴打他人，破坏社会秩序，具有下列情形之一的，应当认定为刑法第二百九十三条第一款第一项规定的“情节恶劣”："},{"i":3,"n":"第三条","txt":"追逐、拦截、辱骂、恐吓他人，破坏社会秩序，具有下列情形之一的，应当认定为刑法第二百九十三条第一款第二项规定的“情节恶劣”："},{"i":4,"n":"第四条","txt":"强拿硬要或者任意损毁、占用公私财物，破坏社会秩序，具有下列情形之一的，应当认定为刑法第二百九十三条第一款第三项规定的“情节严重”："},{"i":5,"n":"第五条","txt":"在车站、码头、机场、医院、商场、公园、影剧院、展览会、运动场或者其他公共场所起哄闹事，应当根据公共场所的性质、公共活动的重要程度、公共场所的人数、起哄闹事的时间、公共场所受影响的范围与程度等因素，综合判断是否“造成公共场所秩序严重混乱”。"},{"i":6,"n":"第六条","txt":"纠集他人三次以上实施寻衅滋事犯罪，未经处理的，应当依照刑法第二百九十三条第二款的规定处罚。"},{"i":7,"n":"第七条","txt":"实施寻衅滋事行为，同时符合寻衅滋事罪和故意杀人罪、故意伤害罪、故意毁坏财物罪、敲诈勒索罪、抢夺罪、抢劫罪等罪的构成要件的，依照处罚较重的犯罪定罪处罚。"},{"i":8,"n":"第八条","txt":"行为人认罪、悔罪，积极赔偿被害人损失或者取得被害人谅解的，可以从轻处罚；犯罪情节轻微的，可以不起诉或者免予刑事处罚。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanf4c113":[{"i":1,"n":"第二条","txt":"违反国家规定，擅自设置、使用无线电台（站），或者擅自使用无线电频率，干扰无线电通讯秩序，具有下列情形之一的，应当认定为刑法第二百八十八条第一款规定的“情节严重”："},{"i":2,"n":"第三条","txt":"违反国家规定，擅自设置、使用无线电台（站），或者擅自使用无线电频率，干扰无线电通讯秩序，具有下列情形之一的，应当认定为刑法第二百八十八条第一款规定的“情节特别严重”："},{"i":3,"n":"第四条","txt":"非法生产、销售“黑广播”“伪基站”、无线电干扰器等无线电设备，具有下列情形之一的，应当认定为刑法第二百二十五条规定的“情节严重”："},{"i":4,"n":"第五条","txt":"单位犯本解释规定之罪的，对单位判处罚金，并对直接负责的主管人员和其他直接责任人员，依照本解释规定的自然人犯罪的定罪量刑标准定罪处罚。"},{"i":5,"n":"第六条","txt":"擅自设置、使用无线电台（站），或者擅自使用无线电频率，同时构成其他犯罪的，按照处罚较重的规定定罪处罚。"},{"i":6,"n":"第七条","txt":"负有无线电监督管理职责的国家机关工作人员滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，应当依照刑法第三百九十七条的规定，以滥用职权罪或者玩忽职守罪追究刑事责任。"},{"i":7,"n":"第八条","txt":"为合法经营活动，使用“黑广播”“伪基站”或者实施其他扰乱无线电通讯管理秩序的行为，构成扰乱无线电通讯管理秩序罪，但不属于“情节特别严重”，行为人系初犯，并确有悔罪表现的，可以认定为情节轻微，不起诉或者免予刑事处罚；确有必要判处刑罚的，应当从宽处罚。"},{"i":8,"n":"第九条","txt":"对案件所涉的有关专门性问题难以确定的，依据司法鉴定机构出具的鉴定意见，或者下列机构出具的报告，结合其他证据作出认定："},{"i":9,"n":"第十条","txt":"本解释自2017年7月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban919c68":[{"i":1,"n":"第一条","txt":"抢夺公私财物价值一千元至三千元以上、三万元至八万元以上、二十万元至四十万元以上的，应当分别认定为刑法第二百六十七条规定的“数额较大”“数额巨大”“数额特别巨大”。"},{"i":2,"n":"第二条","txt":"抢夺公私财物，具有下列情形之一的，“数额较大”的标准按照前条规定标准的百分之五十确定："},{"i":3,"n":"第三条","txt":"抢夺公私财物，具有下列情形之一的，应当认定为刑法第二百六十七条规定的“其他严重情节”："},{"i":4,"n":"第四条","txt":"抢夺公私财物，具有下列情形之一的，应当认定为刑法第二百六十七条规定的“其他特别严重情节”："},{"i":5,"n":"第五条","txt":"抢夺公私财物数额较大，但未造成他人轻伤以上伤害，行为人系初犯，认罪、悔罪，退赃、退赔，且具有下列情形之一的，可以认定为犯罪情节轻微，不起诉或者免予刑事处罚；必要时，由有关部门依法予以行政处罚："},{"i":6,"n":"第六条","txt":"驾驶机动车、非机动车夺取他人财物，具有下列情形之一的，应当以抢劫罪定罪处罚："},{"i":7,"n":"第七条","txt":"本解释公布施行后，《最高人民法院关于审理抢夺刑事案件具体应用法律若干问题的解释》（法释〔2002〕18号）同时废止；之前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanbebd2e":[{"i":1,"n":"第一条","txt":"被执行人、协助执行义务人、担保人等负有执行义务的人，对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，应当依照刑法第三百一十三条的规定，以拒不执行判决、裁定罪处罚。"},{"i":2,"n":"第二条","txt":"刑法第三百一十三条规定的“人民法院的判决、裁定”，是指人民法院依法作出的具有执行内容并已发生法律效力的判决、裁定。人民法院为依法执行支付令、生效的调解书、仲裁裁决、公证债权文书等所作的裁定属于该条规定的裁定。"},{"i":3,"n":"第三条","txt":"负有执行义务的人有能力执行而拒不执行，且具有下列情形之一，应当认定为全国人民代表大会常务委员会关于刑法第三百一十三条的解释中规定的“其他有能力执行而拒不执行，情节严重的情形”："},{"i":4,"n":"第四条","txt":"负有执行义务的人有能力执行而拒不执行，且具有下列情形之一，应当认定属于“情节特别严重”的情形："},{"i":5,"n":"第五条","txt":"有能力执行是指负有执行义务的人有全部执行或者部分执行给付财产义务或履行特定行为义务的能力。"},{"i":6,"n":"第六条","txt":"行为人为逃避执行义务，在诉讼开始后、裁判生效前实施隐藏、转移财产等行为，在判决、裁定生效后经查证属实，要求其执行而拒不执行的，可以认定其有能力执行而拒不执行，情节严重，以拒不执行判决、裁定罪追究刑事责任。"},{"i":7,"n":"第七条","txt":"全国人民代表大会常务委员会关于刑法第三百一十三条的解释和本解释中规定的“致使判决、裁定无法执行”，一般是指人民法院依据法律及相关规定采取执行措施后仍无法执行的情形，包括判决、裁定全部无法执行，也包括部分无法执行。"},{"i":8,"n":"第八条","txt":"案外人明知负有执行义务的人有能力执行而拒不执行人民法院的判决、裁定，与其通谋，协助实施隐藏、转移财产等拒不执行行为，致使判决、裁定无法执行的，以拒不执行判决、裁定罪的共犯论处。"},{"i":9,"n":"第九条","txt":"负有执行义务的人有能力执行而拒不执行人民法院的判决、裁定，同时构成拒不执行判决、裁定罪，妨害公务罪，袭警罪，非法处置查封、扣押、冻结的财产罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"拒不执行支付赡养费、扶养费、抚养费、抚恤金、医疗费用、劳动报酬等判决、裁定，构成犯罪的，应当依法从重处罚。"},{"i":11,"n":"第十一条","txt":"实施刑法第三百一十三条规定的拒不执行判决、裁定行为，情节显著轻微危害不大的，不认为是犯罪；在提起公诉前，履行全部或者部分执行义务，犯罪情节轻微的，可以依法不起诉。在一审宣告判决前，履行全部或者部分执行义务，犯罪情节轻微的，可以依法从轻或者免除处罚。"},{"i":12,"n":"第十二条","txt":"对被告人以拒不执行判决、裁定罪追诉时，对其故意毁损、无偿处分、以明显不合理价格处分、虚假转让等方式违法处置的财产，应当依法予以追缴或者责令退赔，交由执行法院依法处置。"},{"i":13,"n":"第十三条","txt":"人民检察院应当结合侦查移送情况对涉案财产进行审查，在提起公诉时对涉案财产提出明确处理意见。人民法院应当依法作出判决，对涉案财产作出处理。"},{"i":14,"n":"第十四条","txt":"申请执行人有证据证明同时具有下列情形，人民法院认为符合刑事诉讼法第二百一十条第三项规定的，以自诉案件立案审理："},{"i":15,"n":"第十五条","txt":"拒不执行判决、裁定刑事案件，一般由执行法院所在地人民法院管辖。"},{"i":16,"n":"第十六条","txt":"本解释自2024年12月1日起施行。《最高人民法院关于审理拒不执行判决、裁定刑事案件适用法律若干问题的解释》（法释〔2015〕16号）同时废止。最高人民法院、最高人民检察院此前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanbbbafb":[{"i":1,"n":"第一条","txt":"刑法第三百一十二条规定的“犯罪所得”，是指通过犯罪得到的赃款、赃物或其他财产性利益；“犯罪所得收益”，是指通过犯罪所得获取的孳息等财产性利益。"},{"i":2,"n":"第二条","txt":"刑法第三百一十二条规定的“明知”，包括知道或者应当知道。应当根据行为人所接触、接收的信息，经手他人犯罪所得及其收益的情况，犯罪所得及其收益的种类、数额，犯罪所得及其收益的转移、转换方式，交易行为、资金账户的异常情况，结合行为人的职业经历、与上游犯罪人之间的关系以及其供述和辩解等综合审查判断。"},{"i":3,"n":"第三条","txt":"办理掩饰、隐瞒犯罪所得、犯罪所得收益刑事案件，应当综合考虑上游犯罪的性质和社会危害，掩饰、隐瞒犯罪所得及其收益的情节、后果和妨害司法秩序的程度等，依法定罪处罚。"},{"i":4,"n":"第四条","txt":"掩饰、隐瞒犯罪所得及其收益，行为人认罪认罚并积极配合追缴犯罪所得及其收益，且具有下列情形之一，情节轻微的，可以不起诉或者免予刑事处罚："},{"i":5,"n":"第五条","txt":"上游犯罪为非法采矿罪等定罪量刑数额标准相对较高的犯罪，掩饰、隐瞒犯罪所得及其收益的数额达到五百万元以上，且具有下列情形之一的，可以认定为刑法第三百一十二条第一款规定的“情节严重”："},{"i":6,"n":"第六条","txt":"掩饰、隐瞒犯罪所得及其收益的数额，应当以实施掩饰、隐瞒行为时为准。收购或者代为销售财物的价格高于其实际价值的，以收购或者代为销售的价格计算。"},{"i":7,"n":"第七条","txt":"事前与盗窃、抢劫、诈骗、抢夺等行为人通谋，掩饰、隐瞒犯罪所得及其收益，构成犯罪的，分别以盗窃、抢劫、诈骗、抢夺等犯罪的共犯论处。"},{"i":8,"n":"第八条","txt":"对犯罪所得及其收益实施盗窃、抢劫、诈骗、抢夺等行为，构成犯罪的，分别以盗窃、抢劫、诈骗、抢夺等犯罪定罪处罚。"},{"i":9,"n":"第九条","txt":"明知是犯罪所得及其收益而予以掩饰、隐瞒，构成掩饰、隐瞒犯罪所得、犯罪所得收益罪，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"认定掩饰、隐瞒犯罪所得、犯罪所得收益罪，以上游犯罪事实存在为前提。"},{"i":11,"n":"第十一条","txt":"单位实施掩饰、隐瞒犯罪所得及其收益犯罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员定罪处罚。"},{"i":12,"n":"第十二条","txt":"本解释自2025年8月26日起施行。《最高人民法院关于审理掩饰、隐瞒犯罪所得、犯罪所得收益刑事案件适用法律若干问题的解释》（法释〔2015〕11号）及《最高人民法院关于修改〈关于审理掩饰、隐瞒犯罪所得、犯罪所得收益刑事案件适用法律若干问题的解释〉的决定》（法释〔2021〕8号）同时废止。最高人民法院、最高人民检察院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban18a5fe":[{"i":1,"n":"第一条","txt":"敲诈勒索公私财物价值二千元至五千元以上、三万元至十万元以上、三十万元至五十万元以上的，应当分别认定为刑法第二百七十四条规定的“数额较大”、“数额巨大”、“数额特别巨大”。"},{"i":2,"n":"第二条","txt":"敲诈勒索公私财物，具有下列情形之一的，“数额较大”的标准可以按照本解释第一条规定标准的百分之五十确定："},{"i":3,"n":"第三条","txt":"二年内敲诈勒索三次以上的，应当认定为刑法第二百七十四条规定的“多次敲诈勒索”。"},{"i":4,"n":"第四条","txt":"敲诈勒索公私财物，具有本解释第二条第三项至第七项规定的情形之一，数额达到本解释第一条规定的“数额巨大”、“数额特别巨大”百分之八十的，可以分别认定为刑法第二百七十四条规定的“其他严重情节”、“其他特别严重情节”。"},{"i":5,"n":"第五条","txt":"敲诈勒索数额较大，行为人认罪、悔罪，退赃、退赔，并具有下列情形之一的，可以认定为犯罪情节轻微，不起诉或者免予刑事处罚，由有关部门依法予以行政处罚："},{"i":6,"n":"第六条","txt":"敲诈勒索近亲属的财物，获得谅解的，一般不认为是犯罪；认定为犯罪的，应当酌情从宽处理。"},{"i":7,"n":"第七条","txt":"明知他人实施敲诈勒索犯罪，为其提供信用卡、手机卡、通讯工具、通讯传输通道、网络技术支持等帮助的，以共同犯罪论处。"},{"i":8,"n":"第八条","txt":"对犯敲诈勒索罪的被告人，应当在二千元以上、敲诈勒索数额的二倍以下判处罚金；被告人没有获得财物的，应当在二千元以上十万元以下判处罚金。"},{"i":9,"n":"第九条","txt":"本解释公布施行后，《最高人民法院关于敲诈勒索罪数额认定标准问题的规定》（法释〔2000〕11号）同时废止；此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanb02e03":[{"i":1,"n":"第一条","txt":"为掩饰、隐瞒本人实施刑法第一百九十一条规定的上游犯罪的所得及其产生的收益的来源和性质，实施该条第一款规定的洗钱行为的，依照刑法第一百九十一条的规定定罪处罚。"},{"i":2,"n":"第二条","txt":"知道或者应当知道是他人实施刑法第一百九十一条规定的上游犯罪的所得及其产生的收益，为掩饰、隐瞒其来源和性质，实施该条第一款规定的洗钱行为的，依照刑法第一百九十一条的规定定罪处罚。"},{"i":3,"n":"第三条","txt":"认定“知道或者应当知道”，应当根据行为人所接触、接收的信息，经手他人犯罪所得及其收益的情况，犯罪所得及其收益的种类、数额，犯罪所得及其收益的转移、转换方式，交易行为、资金账户等异常情况，结合行为人职业经历、与上游犯罪人员之间的关系以及其供述和辩解，同案人指证和证人证言等情况综合审查判断。有证据证明行为人确实不知道的除外。"},{"i":4,"n":"第四条","txt":"洗钱数额在五百万元以上的，且具有下列情形之一的，应当认定为刑法第一百九十一条规定的“情节严重”："},{"i":5,"n":"第五条","txt":"为掩饰、隐瞒实施刑法第一百九十一条规定的上游犯罪的所得及其产生的收益的来源和性质，实施下列行为之一的，可以认定为刑法第一百九十一条第一款第五项规定的“以其他方法掩饰、隐瞒犯罪所得及其收益的来源和性质”："},{"i":6,"n":"第六条","txt":"掩饰、隐瞒刑法第一百九十一条规定的上游犯罪的犯罪所得及其产生的收益，构成刑法第一百九十一条规定的洗钱罪，同时又构成刑法第三百一十二条规定的掩饰、隐瞒犯罪所得、犯罪所得收益罪的，依照刑法第一百九十一条的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"认定洗钱罪应当以上游犯罪事实成立为前提。有下列情形的，不影响洗钱罪的认定："},{"i":8,"n":"第八条","txt":"刑法第一百九十一条规定的“黑社会性质的组织犯罪的所得及其产生的收益”，是指黑社会性质组织及其成员实施相关犯罪的所得及其产生的收益，包括黑社会性质组织的形成、发展过程中，该组织及组织成员通过违法犯罪活动聚敛的全部财物、财产性权益及其孳息、收益。"},{"i":9,"n":"第九条","txt":"犯洗钱罪，判处五年以下有期徒刑或者拘役，并处或者单处罚金的，判处一万元以上罚金；判处五年以上十年以下有期徒刑的，并处二十万元以上罚金。"},{"i":10,"n":"第十条","txt":"符合本解释第一条、第二条的规定，行为人如实供述犯罪事实，认罪悔罪，并积极配合追缴犯罪所得及其产生的收益的，可以从轻处罚；犯罪情节轻微的，可以依法不起诉或者免予刑事处罚。"},{"i":11,"n":"第十一条","txt":"单位实施洗钱犯罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员定罪处罚。"},{"i":12,"n":"第十二条","txt":"本解释所称“上游犯罪”，是指刑法第一百九十一条规定的毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪。"},{"i":13,"n":"第十三条","txt":"本解释自2024年8月20日起施行。《最高人民法院关于审理洗钱等刑事案件具体应用法律若干问题的解释》（法释〔2009〕15号）同时废止。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubancad0ae":[{"i":1,"n":"第一条","txt":"国家机关工作人员滥用职权或者玩忽职守，具有下列情形之一的，应当认定为刑法第三百九十七条规定的“致使公共财产、国家和人民利益遭受重大损失”："},{"i":2,"n":"第二条","txt":"国家机关工作人员实施滥用职权或者玩忽职守犯罪行为，触犯刑法分则第九章第三百九十八条至第四百一十九条规定的，依照该规定定罪处罚。"},{"i":3,"n":"第三条","txt":"国家机关工作人员实施渎职犯罪并收受贿赂，同时构成受贿罪的，除刑法另有规定外，以渎职犯罪和受贿罪数罪并罚。"},{"i":4,"n":"第四条","txt":"国家机关工作人员实施渎职行为，放纵他人犯罪或者帮助他人逃避刑事处罚，构成犯罪的，依照渎职罪的规定定罪处罚。"},{"i":5,"n":"第五条","txt":"国家机关负责人员违法决定，或者指使、授意、强令其他国家机关工作人员违法履行职务或者不履行职务，构成刑法分则第九章规定的渎职犯罪的，应当依法追究刑事责任。"},{"i":6,"n":"第六条","txt":"以危害结果为条件的渎职犯罪的追诉期限，从危害结果发生之日起计算；有数个危害结果的，从最后一个危害结果发生之日起计算。"},{"i":7,"n":"第七条","txt":"依法或者受委托行使国家行政管理职权的公司、企业、事业单位的工作人员，在行使行政管理职权时滥用职权或者玩忽职守，构成犯罪的，应当依照《全国人民代表大会常务委员会关于〈中华人民共和国刑法〉第九章渎职罪主体适用问题的解释》的规定，适用渎职罪的规定追究刑事责任。"},{"i":8,"n":"第八条","txt":"本解释规定的“经济损失”，是指渎职犯罪或者与渎职犯罪相关联的犯罪立案时已经实际造成的财产损失，包括为挽回渎职犯罪所造成损失而支付的各种开支、费用等。立案后至提起公诉前持续发生的经济损失，应一并计入渎职犯罪造成的经济损失。"},{"i":9,"n":"第九条","txt":"负有监督管理职责的国家机关工作人员滥用职权或者玩忽职守，致使不符合安全标准的食品、有毒有害食品、假药、劣药等流入社会，对人民群众生命、健康造成严重危害后果的，依照渎职罪的规定从严惩处。"},{"i":10,"n":"第十条","txt":"最高人民法院、最高人民检察院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban8d88e7":[{"i":1,"n":"第一条","txt":"实施刑法第三百三十八条规定的行为，具有下列情形之一的，应当认定为“严重污染环境”："},{"i":2,"n":"第二条","txt":"实施刑法第三百三十八条规定的行为，具有下列情形之一的，应当认定为“情节严重”："},{"i":3,"n":"第三条","txt":"实施刑法第三百三十八条规定的行为，具有下列情形之一的，应当处七年以上有期徒刑，并处罚金："},{"i":4,"n":"第四条","txt":"实施刑法第三百三十九条第一款规定的行为，具有下列情形之一的，应当认定为“致使公私财产遭受重大损失或者严重危害人体健康”："},{"i":5,"n":"第五条","txt":"实施刑法第三百三十八条、第三百三十九条规定的犯罪行为，具有下列情形之一的，应当从重处罚："},{"i":6,"n":"第六条","txt":"实施刑法第三百三十八条规定的行为，行为人积极履行生态环境修复责任的，可以从宽处罚。犯罪情节轻微的，可以不起诉或者免予刑事处罚；情节显著轻微危害不大的，不作为犯罪处理。"},{"i":7,"n":"第七条","txt":"无危险废物经营许可证从事收集、贮存、利用、处置危险废物经营活动，严重污染环境的，按照污染环境罪定罪处罚；同时构成非法经营罪的，依照处罚较重的规定定罪处罚。"},{"i":8,"n":"第八条","txt":"明知他人无危险废物经营许可证，向其提供或者委托其收集、贮存、利用、处置危险废物，严重污染环境的，以共同犯罪论处。"},{"i":9,"n":"第九条","txt":"违反国家规定，排放、倾倒、处置含有毒害性、放射性、传染病病原体等物质的污染物，同时构成污染环境罪、非法处置进口的固体废物罪、投放危险物质罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"承担环境影响评价、环境监测、机动车排放检验、土壤污染调查评估、温室气体排放检验检测、排放报告编制或者核查等职责的中介组织的人员故意提供虚假证明文件，具有下列情形之一的，应当认定为刑法第二百二十九条第一款规定的“情节严重”："},{"i":11,"n":"第十一条","txt":"违反国家规定，针对环境质量监测系统实施下列行为，或者强令、指使、授意他人实施下列行为，后果严重的，应当依照刑法第二百八十六条的规定，以破坏计算机信息系统罪定罪处罚："},{"i":12,"n":"第十二条","txt":"对于实施本解释规定的相关行为被不起诉或者免予刑事处罚的行为人，需要给予行政处罚、政务处分或者其他处分的，依法移送有关主管机关处理。有关主管机关应当将处理结果及时通知人民检察院、人民法院。"},{"i":13,"n":"第十三条","txt":"单位实施本解释规定的犯罪的，依照本解释规定的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":14,"n":"第十四条","txt":"环境保护主管部门及其所属监测机构在行政执法过程中收集的监测数据，在刑事诉讼中可以作为证据使用。"},{"i":15,"n":"第十五条","txt":"对国家危险废物名录所列的废物，可以依据涉案物质的来源、产生过程、被告人供述、证人证言以及经批准或者备案的环境影响评价文件、排污许可证、排污登记表等证据，结合环境保护主管部门、公安机关等出具的书面意见作出认定。"},{"i":16,"n":"第十六条","txt":"对案件所涉的环境污染专门性问题难以确定的，依据鉴定机构出具的鉴定意见，或者国务院环境保护主管部门、公安部门指定的机构出具的报告，结合其他证据作出认定。"},{"i":17,"n":"第十七条","txt":"下列物质应当认定为刑法第三百三十八条规定的“有毒物质”："},{"i":18,"n":"第十八条","txt":"无危险废物经营许可证，以营利为目的，从危险废物中提取物质作为原材料或者燃料，并具有超标排放污染物、非法倾倒污染物或者其他违法造成环境污染的情形的行为，应当认定为“非法处置危险废物”。"},{"i":19,"n":"第十九条","txt":"本解释所称“二年内”，以第一次违法行为受到行政处罚的生效之日与又实施相应行为之日的时间间隔计算确定。"},{"i":20,"n":"第二十条","txt":"本解释自2023年8月15日起施行。本解释施行后，《最高人民法院、最高人民检察院关于办理环境污染刑事案件适用法律若干问题的解释》（法释〔2016〕29号）同时废止；之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanf4a002":[{"i":1,"n":"第一条","txt":"刑法第一百四十条规定的“在产品中掺杂、掺假”，是指在产品中掺入杂质或者异物，致使产品质量不符合国家法律、法规或者产品明示质量标准规定的质量要求，降低、失去应有使用性能的行为。"},{"i":2,"n":"第二条","txt":"刑法第一百四十条、第一百四十九条规定的“销售金额”，是指生产者、销售者出售伪劣产品后所得和应得的全部违法收入。"},{"i":3,"n":"第三条","txt":"经省级以上药品监督管理部门设置或者确定的药品检验机构鉴定，生产、销售的假药具有下列情形之一的，应认定为刑法第一百四十一条规定的“足以严重危害人体健康”："},{"i":4,"n":"第四条","txt":"经省级以上卫生行政部门确定的机构鉴定，食品中含有可能导致严重食物中毒事故或者其他严重食源性疾患的超标准的有害细菌或者其他污染物的，应认定为刑法第一百四十三条规定的“足以造成严重食物中毒事故或者其他严重食源性疾患”。"},{"i":5,"n":"第五条","txt":"生产、销售的有毒、有害食品被食用后，造成轻伤、重伤或者其他严重后果的，应认定为刑法第一百四十四条规定的“对人体健康造成严重危害”。"},{"i":6,"n":"第六条","txt":"生产、销售不符合标准的医疗器械、医用卫生材料，致人轻伤或者其他严重后果的，应认定为刑法第一百四十五条规定的“对人体健康造成严重危害”。"},{"i":7,"n":"第七条","txt":"刑法第一百四十七条规定的生产、销售伪劣农药、兽药、化肥、种子罪中“使生产遭受较大损失”，一般以2万元为起点；“重大损失”，一般以10万元为起点；“特别重大损失”，一般以50万元为起点。"},{"i":8,"n":"第八条","txt":"国家机关工作人员徇私舞弊，对生产、销售伪劣商品犯罪不履行法律规定的查处职责，具有下列情形之一的，属于刑法第四百一十四条规定的“情节严重”："},{"i":9,"n":"第九条","txt":"知道或者应当知道他人实施生产、销售伪劣商品犯罪，而为其提供贷款、资金、账号、发票、证明、许可证件，或者提供生产、经营场所或者运输、仓储、保管、邮寄等便利条件，或者提供制假生产技术的，以生产、销售伪劣商品犯罪的共犯论处。"},{"i":10,"n":"第十条","txt":"实施生产、销售伪劣商品犯罪，同时构成侵犯知识产权、非法经营等其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":11,"n":"第十一条","txt":"实施刑法第一百四十条至第一百四十八条规定的犯罪，又以暴力、威胁方法抗拒查处，构成其他犯罪的，依照数罪并罚的规定处罚。"},{"i":12,"n":"第十二条","txt":"国家机关工作人员参与生产、销售伪劣商品犯罪的，从重处罚。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban5ca01d":[{"i":1,"n":"第一条","txt":"盗窃公私财物价值一千元至三千元以上、三万元至十万元以上、三十万元至五十万元以上的，应当分别认定为刑法第二百六十四条规定的“数额较大”、“数额巨大”、“数额特别巨大”。"},{"i":2,"n":"第二条","txt":"盗窃公私财物，具有下列情形之一的，“数额较大”的标准可以按照前条规定标准的百分之五十确定："},{"i":3,"n":"第三条","txt":"二年内盗窃三次以上的，应当认定为“多次盗窃”。"},{"i":4,"n":"第四条","txt":"盗窃的数额，按照下列方法认定："},{"i":5,"n":"第五条","txt":"盗窃有价支付凭证、有价证券、有价票证的，按照下列方法认定盗窃数额："},{"i":6,"n":"第六条","txt":"盗窃公私财物，具有本解释第二条第三项至第八项规定情形之一，或者入户盗窃、携带凶器盗窃，数额达到本解释第一条规定的“数额巨大”、“数额特别巨大”百分之五十的，可以分别认定为刑法第二百六十四条规定的“其他严重情节”或者“其他特别严重情节”。"},{"i":7,"n":"第七条","txt":"盗窃公私财物数额较大，行为人认罪、悔罪，退赃、退赔，且具有下列情形之一，情节轻微的，可以不起诉或者免予刑事处罚；必要时，由有关部门予以行政处罚："},{"i":8,"n":"第八条","txt":"偷拿家庭成员或者近亲属的财物，获得谅解的，一般可以不认为是犯罪；追究刑事责任的，应当酌情从宽。"},{"i":9,"n":"第九条","txt":"盗窃国有馆藏一般文物、三级文物、二级以上文物的，应当分别认定为刑法第二百六十四条规定的“数额较大”、“数额巨大”、“数额特别巨大”。"},{"i":10,"n":"第十条","txt":"偷开他人机动车的，按照下列规定处理："},{"i":11,"n":"第十一条","txt":"盗窃公私财物并造成财物损毁的，按照下列规定处理："},{"i":12,"n":"第十二条","txt":"盗窃未遂，具有下列情形之一的，应当依法追究刑事责任："},{"i":13,"n":"第十三条","txt":"单位组织、指使盗窃，符合刑法第二百六十四条及本解释有关规定的，以盗窃罪追究组织者、指使者、直接实施者的刑事责任。"},{"i":14,"n":"第十四条","txt":"因犯盗窃罪，依法判处罚金刑的，应当在一千元以上盗窃数额的二倍以下判处罚金；没有盗窃数额或者盗窃数额无法计算的，应当在一千元以上十万元以下判处罚金。"},{"i":15,"n":"第十五条","txt":"本解释发布实施后，《最高人民法院关于审理盗窃案件具体应用法律若干问题的解释》（法释〔1998〕4号）同时废止；之前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubane20edb":[{"i":1,"n":"第一条","txt":"具有下列情形之一的，应当认定为刑法第一百五十一条第二款规定的走私国家禁止进出口的珍贵动物及其制品："},{"i":2,"n":"第二条","txt":"走私国家禁止进出口的珍贵动物及其制品，价值二十万元以上不满二百万元的，应当依照刑法第一百五十一条第二款的规定，以走私珍贵动物、珍贵动物制品罪处五年以上十年以下有期徒刑，并处罚金；价值二百万元以上的，应当认定为“情节特别严重”，处十年以上有期徒刑或者无期徒刑，并处没收财产；价值二万元以上不满二十万元的，应当认定为“情节较轻”，处五年以下有期徒刑，并处罚金。"},{"i":3,"n":"第三条","txt":"在内陆水域，违反保护水产资源法规，在禁渔区、禁渔期或者使用禁用的工具、方法捕捞水产品，具有下列情形之一的，应当认定为刑法第三百四十条规定的“情节严重”，以非法捕捞水产品罪定罪处罚："},{"i":4,"n":"第四条","txt":"刑法第三百四十一条第一款规定的“国家重点保护的珍贵、濒危野生动物”包括："},{"i":5,"n":"第五条","txt":"刑法第三百四十一条第一款规定的“收购”包括以营利、自用等为目的的购买行为；“运输”包括采用携带、邮寄、利用他人、使用交通工具等方法进行运送的行为；“出售”包括出卖和以营利为目的的加工利用行为。"},{"i":6,"n":"第六条","txt":"非法猎捕、杀害国家重点保护的珍贵、濒危野生动物，或者非法收购、运输、出售国家重点保护的珍贵、濒危野生动物及其制品，价值二万元以上不满二十万元的，应当依照刑法第三百四十一条第一款的规定，以危害珍贵、濒危野生动物罪处五年以下有期徒刑或者拘役，并处罚金；价值二十万元以上不满二百万元的，应当认定为“情节严重”，处五年以上十年以下有期徒刑，并处罚金；价值二百万元以上的，应当认定为“情节特别严重”，处十年以上有期徒刑，并处罚金或者没收财产。"},{"i":7,"n":"第七条","txt":"违反狩猎法规，在禁猎区、禁猎期或者使用禁用的工具、方法进行狩猎，破坏野生动物资源，具有下列情形之一的，应当认定为刑法第三百四十一条第二款规定的“情节严重”，以非法狩猎罪定罪处罚："},{"i":8,"n":"第八条","txt":"违反野生动物保护管理法规，以食用为目的，非法猎捕、收购、运输、出售刑法第三百四十一条第一款规定以外的在野外环境自然生长繁殖的陆生野生动物，具有下列情形之一的，应当认定为刑法第三百四十一条第三款规定的“情节严重”，以非法猎捕、收购、运输、出售陆生野生动物罪定罪处罚："},{"i":9,"n":"第九条","txt":"明知是非法捕捞犯罪所得的水产品、非法狩猎犯罪所得的猎获物而收购、贩卖或者以其他方法掩饰、隐瞒，符合刑法第三百一十二条规定的，以掩饰、隐瞒犯罪所得罪定罪处罚。"},{"i":10,"n":"第十条","txt":"负有野生动物保护和进出口监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，应当依照刑法第三百九十七条的规定，以滥用职权罪或者玩忽职守罪追究刑事责任。"},{"i":11,"n":"第十一条","txt":"对于“以食用为目的”，应当综合涉案动物及其制品的特征，被查获的地点，加工、包装情况，以及可以证明来源、用途的标识、证明等证据作出认定。"},{"i":12,"n":"第十二条","txt":"二次以上实施本解释规定的行为构成犯罪，依法应当追诉的，或者二年内实施本解释规定的行为未经处理的，数量、数额累计计算。"},{"i":13,"n":"第十三条","txt":"实施本解释规定的相关行为，在认定是否构成犯罪以及裁量刑罚时，应当考虑涉案动物是否系人工繁育、物种的濒危程度、野外存活状况、人工繁育情况、是否列入人工繁育国家重点保护野生动物名录，行为手段、对野生动物资源的损害程度，以及对野生动物及其制品的认知程度等情节，综合评估社会危害性，准确认定是否构成犯罪，妥当裁量刑罚，确保罪责刑相适应；根据本解释的规定定罪量刑明显过重的，可以根据案件的事实、情节和社会危害程度，依法作出妥当处理。"},{"i":14,"n":"第十四条","txt":"对于实施本解释规定的相关行为被不起诉或者免予刑事处罚的行为人，依法应当给予行政处罚、政务处分或者其他处分的，依法移送有关主管机关处理。"},{"i":15,"n":"第十五条","txt":"对于涉案动物及其制品的价值，应当根据下列方法确定："},{"i":16,"n":"第十六条","txt":"根据本解释第十五条规定难以确定涉案动物及其制品价值的，依据司法鉴定机构出具的鉴定意见，或者下列机构出具的报告，结合其他证据作出认定："},{"i":17,"n":"第十七条","txt":"对于涉案动物的种属类别、是否系人工繁育，非法捕捞、狩猎的工具、方法，以及对野生动物资源的损害程度等专门性问题，可以由野生动物保护主管部门、侦查机关依据现场勘验、检查笔录等出具认定意见；难以确定的，依据司法鉴定机构出具的鉴定意见、本解释第十六条所列机构出具的报告，被告人及其辩护人提供的证据材料，结合其他证据材料综合审查，依法作出认定。"},{"i":18,"n":"第十八条","txt":"餐饮公司、渔业公司等单位实施破坏野生动物资源犯罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":19,"n":"第十九条","txt":"在海洋水域，非法捕捞水产品，非法采捕珊瑚、砗磲或者其他珍贵、濒危水生野生动物，或者非法收购、运输、出售珊瑚、砗磲或者其他珍贵、濒危水生野生动物及其制品的，定罪量刑标准适用《最高人民法院关于审理发生在我国管辖海域相关案件若干问题的规定（二）》（法释〔2016〕17号）的相关规定。"},{"i":20,"n":"第二十条","txt":"本解释自2022年4月9日起施行。本解释公布施行后，《最高人民法院关于审理破坏野生动物资源刑事案件具体应用法律若干问题的解释》（法释〔2000〕37号）同时废止；之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban6d460c":[{"i":1,"n":"第一条","txt":"违反土地管理法规，具有下列情形之一的，应当认定为刑法第三百四十二条规定的非法占用耕地，改变被占用耕地用途，造成耕地毁坏："},{"i":2,"n":"第二条","txt":"违反矿产资源法的规定，非法开采属于矿产资源的黑土，符合刑法第三百四十三条第一款规定的，以非法采矿罪定罪处罚。"},{"i":3,"n":"第三条","txt":"违反国家规定，排放、倾倒或者处置有放射性的废物、含传染病病原体的废物、有毒物质或者其他有害物质，严重污染黑土地，符合刑法第三百三十八条第一款规定的，以污染环境罪定罪处罚。"},{"i":4,"n":"第四条","txt":"实施本解释第一条、第二条或者第三条规定的行为，同时构成非法占用农用地罪、非法采矿罪或者污染环境罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":5,"n":"第五条","txt":"明知是犯罪所得的黑土及其产生的收益，而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒，符合刑法第三百一十二条规定的，以掩饰、隐瞒犯罪所得、犯罪所得收益罪妥当定罪量刑。"},{"i":6,"n":"第六条","txt":"实施破坏黑土地资源犯罪，具有下列情形之一的，从重处罚："},{"i":7,"n":"第七条","txt":"组织他人实施破坏黑土地资源犯罪的，应当按照其组织实施的全部罪行处罚。"},{"i":8,"n":"第八条","txt":"单位实施破坏黑土地资源犯罪的，依照本解释规定的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":9,"n":"第九条","txt":"多次实施破坏黑土地资源犯罪，依法应当追诉的，或者二年内多次实施破坏黑土地资源行为未经处理的，数量、数额累计计算。"},{"i":10,"n":"第十条","txt":"实施破坏黑土地资源的行为，在认定是否构成犯罪以及裁量刑罚时，应当综合考虑行为动机目的、对黑土地资源的破坏程度、是否积极履行生态环境修复责任等情节，综合评估社会危害性，准确认定是否构成犯罪，妥当裁量刑罚，确保罪责刑相适应。"},{"i":11,"n":"第十一条","txt":"对于实施破坏黑土地资源的相关行为被不起诉、宣告无罪或者免予刑事处罚的行为人，依法应当给予行政处罚、政务处分或者其他处分的，依法移送有关主管机关处理。"},{"i":12,"n":"第十二条","txt":"对于涉案黑土地类型、面积，涉案黑土体积、数量、价值等专门性事实问题，可以依据鉴定机构出具的鉴定意见，或者农业农村、自然资源、水行政、生态环境等主管部门出具的认定意见，或者价格认证机构、国务院相关主管部门指定或推荐的机构、地市级以上人民政府相关主管部门出具的报告，结合其他证据作出认定。"},{"i":13,"n":"第十三条","txt":"本解释所称“黑土地”，是指《中华人民共和国黑土地保护法》第二条第二款所规定的黑龙江省、吉林省、辽宁省、内蒙古自治区的相关区域范围内具有黑色或者暗黑色腐殖质表土层，性状好、肥力高的耕地。"},{"i":14,"n":"第十四条","txt":"本解释自2025年5月6日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban62bea4":[{"i":1,"n":"第一条","txt":"冒用宗教、气功或者以其他名义建立，神化、鼓吹首要分子，利用制造、散布迷信邪说等手段蛊惑、蒙骗他人，发展、控制成员，危害社会的非法组织，应当认定为刑法第三百条规定的“邪教组织”。"},{"i":2,"n":"第二条","txt":"组织、利用邪教组织，破坏国家法律、行政法规实施，具有下列情形之一的，应当依照刑法第三百条第一款的规定，处三年以上七年以下有期徒刑，并处罚金："},{"i":3,"n":"第三条","txt":"组织、利用邪教组织，破坏国家法律、行政法规实施，具有下列情形之一的，应当认定为刑法第三百条第一款规定的“情节特别严重”，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产："},{"i":4,"n":"第四条","txt":"组织、利用邪教组织，破坏国家法律、行政法规实施，具有下列情形之一的，应当认定为刑法第三百条第一款规定的“情节较轻”，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处或者单处罚金："},{"i":5,"n":"第五条","txt":"为了传播而持有、携带，或者传播过程中被当场查获，邪教宣传品数量达到本解释第二条至第四条规定的有关标准的，按照下列情形分别处理："},{"i":6,"n":"第六条","txt":"多次制作、传播邪教宣传品或者利用通讯信息网络宣扬邪教，未经处理的，数量或者数额累计计算。"},{"i":7,"n":"第七条","txt":"组织、利用邪教组织，制造、散布迷信邪说，蒙骗成员或者他人绝食、自虐等，或者蒙骗病人不接受正常治疗，致人重伤、死亡的，应当认定为刑法第三百条第二款规定的组织、利用邪教组织“蒙骗他人，致人重伤、死亡”。"},{"i":8,"n":"第八条","txt":"实施本解释第二条至第五条规定的行为，具有下列情形之一的，从重处罚："},{"i":9,"n":"第九条","txt":"组织、利用邪教组织破坏国家法律、行政法规实施，符合本解释第四条规定情形，但行为人能够真诚悔罪，明确表示退出邪教组织、不再从事邪教活动的，可以不起诉或者免予刑事处罚。其中，行为人系受蒙蔽、胁迫参加邪教组织的，可以不作为犯罪处理。"},{"i":10,"n":"第十条","txt":"组织、利用邪教组织破坏国家法律、行政法规实施过程中，又有煽动分裂国家、煽动颠覆国家政权或者侮辱、诽谤他人等犯罪行为的，依照数罪并罚的规定定罪处罚。"},{"i":11,"n":"第十一条","txt":"组织、利用邪教组织，制造、散布迷信邪说，组织、策划、煽动、胁迫、教唆、帮助其成员或者他人实施自杀、自伤的，依照刑法第二百三十二条、第二百三十四条的规定，以故意杀人罪或者故意伤害罪定罪处罚。"},{"i":12,"n":"第十二条","txt":"邪教组织人员以自焚、自爆或者其他危险方法危害公共安全的，依照刑法第一百一十四条、第一百一十五条的规定，以放火罪、爆炸罪、以危险方法危害公共安全罪等定罪处罚。"},{"i":13,"n":"第十三条","txt":"明知他人组织、利用邪教组织实施犯罪，而为其提供经费、场地、技术、工具、食宿、接送等便利条件或者帮助的，以共同犯罪论处。"},{"i":14,"n":"第十四条","txt":"对于犯组织、利用邪教组织破坏法律实施罪、组织、利用邪教组织致人重伤、死亡罪，严重破坏社会秩序的犯罪分子，根据刑法第五十六条的规定，可以附加剥夺政治权利。"},{"i":15,"n":"第十五条","txt":"对涉案物品是否属于邪教宣传品难以确定的，可以委托地市级以上公安机关出具认定意见。"},{"i":16,"n":"第十六条","txt":"本解释自2017年2月1日起施行。最高人民法院、最高人民检察院《关于办理组织和利用邪教组织犯罪案件具体应用法律若干问题的解释》（法释〔1999〕18号），最高人民法院、最高人民检察院《关于办理组织和利用邪教组织犯罪案件具体应用法律若干问题的解释（二）》（法释〔2001〕19号），以及最高人民法院、最高人民检察院《关于办理组织和利用邪教组织犯罪案件具体应用法律若干问题的解答》（法发〔2002〕7号）同时废止。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban69d61e":[{"i":1,"n":"第一条","txt":"以招募、雇佣、纠集等手段，管理或者控制他人卖淫，卖淫人员在三人以上的，应当认定为刑法第三百五十八条规定的“组织他人卖淫”。"},{"i":2,"n":"第二条","txt":"组织他人卖淫，具有下列情形之一的，应当认定为刑法第三百五十八条第一款规定的“情节严重”："},{"i":3,"n":"第三条","txt":"在组织卖淫犯罪活动中，对被组织卖淫的人有引诱、容留、介绍卖淫行为的，依照处罚较重的规定定罪处罚。但是，对被组织卖淫的人以外的其他人有引诱、容留、介绍卖淫行为的，应当分别定罪，实行数罪并罚。"},{"i":4,"n":"第四条","txt":"明知他人实施组织卖淫犯罪活动而为其招募、运送人员或者充当保镖、打手、管账人等的，依照刑法第三百五十八条第四款的规定，以协助组织卖淫罪定罪处罚，不以组织卖淫罪的从犯论处。"},{"i":5,"n":"第五条","txt":"协助组织他人卖淫，具有下列情形之一的，应当认定为刑法第三百五十八条第四款规定的“情节严重”："},{"i":6,"n":"第六条","txt":"强迫他人卖淫，具有下列情形之一的，应当认定为刑法第三百五十八条第一款规定的“情节严重”："},{"i":7,"n":"第七条","txt":"根据刑法第三百五十八条第三款的规定，犯组织、强迫卖淫罪，并有杀害、伤害、强奸、绑架等犯罪行为的，依照数罪并罚的规定处罚。协助组织卖淫行为人参与实施上述行为的，以共同犯罪论处。"},{"i":8,"n":"第八条","txt":"引诱、容留、介绍他人卖淫，具有下列情形之一的，应当依照刑法第三百五十九条第一款的规定定罪处罚："},{"i":9,"n":"第九条","txt":"引诱、容留、介绍他人卖淫，具有下列情形之一的，应当认定为刑法第三百五十九条第一款规定的“情节严重”："},{"i":10,"n":"第十条","txt":"组织、强迫、引诱、容留、介绍他人卖淫的次数，作为酌定情节在量刑时考虑。"},{"i":11,"n":"第十一条","txt":"具有下列情形之一的，应当认定为刑法第三百六十条规定的“明知”："},{"i":12,"n":"第十二条","txt":"明知自己患有艾滋病或者感染艾滋病病毒而卖淫、嫖娼的，依照刑法第三百六十条的规定，以传播性病罪定罪，从重处罚。"},{"i":13,"n":"第十三条","txt":"犯组织、强迫、引诱、容留、介绍卖淫罪的，应当依法判处犯罪所得二倍以上的罚金。共同犯罪的，对各共同犯罪人合计判处的罚金应当在犯罪所得的二倍以上。"},{"i":14,"n":"第十四条","txt":"根据刑法第三百六十二条、第三百一十条的规定，旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处卖淫、嫖娼活动时，为违法犯罪分子通风报信，情节严重的，以包庇罪定罪处罚。事前与犯罪分子通谋的，以共同犯罪论处。"},{"i":15,"n":"第十五条","txt":"本解释自2017年7月25日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban6976a1":[{"i":1,"n":"第一条","txt":"采取伪造证据、虚假陈述等手段，实施下列行为之一，捏造民事法律关系，虚构民事纠纷，向人民法院提起民事诉讼的，应当认定为刑法第三百零七条之一第一款规定的“以捏造的事实提起民事诉讼”："},{"i":2,"n":"第二条","txt":"以捏造的事实提起民事诉讼，有下列情形之一的，应当认定为刑法第三百零七条之一第一款规定的“妨害司法秩序或者严重侵害他人合法权益”："},{"i":3,"n":"第三条","txt":"以捏造的事实提起民事诉讼，有下列情形之一的，应当认定为刑法第三百零七条之一第一款规定的“情节严重”："},{"i":4,"n":"第四条","txt":"实施刑法第三百零七条之一第一款行为，非法占有他人财产或者逃避合法债务，又构成诈骗罪，职务侵占罪，拒不执行判决、裁定罪，贪污罪等犯罪的，依照处罚较重的规定定罪从重处罚。"},{"i":5,"n":"第五条","txt":"司法工作人员利用职权，与他人共同实施刑法第三百零七条之一前三款行为的，从重处罚；同时构成滥用职权罪，民事枉法裁判罪，执行判决、裁定滥用职权罪等犯罪的，依照处罚较重的规定定罪从重处罚。"},{"i":6,"n":"第六条","txt":"诉讼代理人、证人、鉴定人等诉讼参与人与他人通谋，代理提起虚假民事诉讼、故意作虚假证言或者出具虚假鉴定意见，共同实施刑法第三百零七条之一前三款行为的，依照共同犯罪的规定定罪处罚；同时构成妨害作证罪，帮助毁灭、伪造证据罪等犯罪的，依照处罚较重的规定定罪从重处罚。"},{"i":7,"n":"第七条","txt":"采取伪造证据等手段篡改案件事实，骗取人民法院裁判文书，构成犯罪的，依照刑法第二百八十条、第三百零七条等规定追究刑事责任。"},{"i":8,"n":"第八条","txt":"单位实施刑法第三百零七条之一第一款行为的，依照本解释规定的定罪量刑标准，对其直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":9,"n":"第九条","txt":"实施刑法第三百零七条之一第一款行为，未达到情节严重的标准，行为人系初犯，在民事诉讼过程中自愿具结悔过，接受人民法院处理决定，积极退赃、退赔的，可以认定为犯罪情节轻微，不起诉或者免予刑事处罚；确有必要判处刑罚的，可以从宽处罚。"},{"i":10,"n":"第十条","txt":"虚假诉讼刑事案件由虚假民事诉讼案件的受理法院所在地或者执行法院所在地人民法院管辖。有刑法第三百零七条之一第四款情形的，上级人民法院可以指定下级人民法院将案件移送其他人民法院审判。"},{"i":11,"n":"第十一条","txt":"本解释所称裁判文书，是指人民法院依照民事诉讼法、企业破产法等民事法律作出的判决、裁定、调解书、支付令等文书。"},{"i":12,"n":"第十二条","txt":"本解释自2018年10月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanee5ee7":[{"i":1,"n":"第一条","txt":"为谋取不正当利益，向国家工作人员行贿，数额在一万元以上的，应当依照刑法第三百九十条的规定追究刑事责任。"},{"i":2,"n":"第二条","txt":"因行贿谋取不正当利益，具有下列情形之一的，应当认定为刑法第三百九十条第一款规定的“情节严重”："},{"i":3,"n":"第三条","txt":"因行贿谋取不正当利益，造成直接经济损失数额在一百万元以上的，应当认定为刑法第三百九十条第一款规定的“使国家利益遭受重大损失”。"},{"i":4,"n":"第四条","txt":"因行贿谋取不正当利益，具有下列情形之一的，应当认定为刑法第三百九十条第一款规定的“情节特别严重”："},{"i":5,"n":"第五条","txt":"多次行贿未经处理的，按照累计行贿数额处罚。"},{"i":6,"n":"第六条","txt":"行贿人谋取不正当利益的行为构成犯罪的，应当与行贿犯罪实行数罪并罚。"},{"i":7,"n":"第七条","txt":"因行贿人在被追诉前主动交待行贿行为而破获相关受贿案件的，对行贿人不适用刑法第六十八条关于立功的规定，依照刑法第三百九十条第二款的规定，可以减轻或者免除处罚。"},{"i":8,"n":"第八条","txt":"行贿人被追诉后如实供述自己罪行的，依照刑法第六十七条第三款的规定，可以从轻处罚；因其如实供述自己罪行，避免特别严重后果发生的，可以减轻处罚。"},{"i":9,"n":"第九条","txt":"行贿人揭发受贿人与其行贿无关的其他犯罪行为，查证属实的，依照刑法第六十八条关于立功的规定，可以从轻、减轻或者免除处罚。"},{"i":10,"n":"第十条","txt":"实施行贿犯罪，具有下列情形之一的，一般不适用缓刑和免予刑事处罚："},{"i":11,"n":"第十一条","txt":"行贿犯罪取得的不正当财产性利益应当依照刑法第六十四条的规定予以追缴、责令退赔或者返还被害人。"},{"i":12,"n":"第十二条","txt":"行贿犯罪中的“谋取不正当利益”，是指行贿人谋取的利益违反法律、法规、规章、政策规定，或者要求国家工作人员违反法律、法规、规章、政策、行业规范的规定，为自己提供帮助或者方便条件。"},{"i":13,"n":"第十三条","txt":"刑法第三百九十条第二款规定的“被追诉前”，是指检察机关对行贿人的行贿行为刑事立案前。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanc0d62e":[{"i":1,"n":"第一条","txt":"袭击正在依法执行职务的人民警察，具有下列情形之一的，应当认定为刑法第二百七十七条第五款规定的“暴力袭击”："},{"i":2,"n":"第二条","txt":"暴力袭击正在依法执行职务的人民警察，具有下列情形之一，足以致人重伤或者死亡的，应当认定为刑法第二百七十七条第五款规定的“严重危及其人身安全”："},{"i":3,"n":"第三条","txt":"实施袭警犯罪，具有下列情形之一的，从重处罚："},{"i":4,"n":"第四条","txt":"对于人民警察执法活动存在过错，在认定行为人暴力袭击行为是否构成袭警罪时，应当综合考虑行为人的暴力程度、危害后果及执法过错程度等因素，依法妥当处理。"},{"i":5,"n":"第五条","txt":"醉酒的人实施袭警犯罪的，应当负刑事责任。"},{"i":6,"n":"第六条","txt":"教唆、煽动他人实施袭警犯罪或者明知他人实施袭警犯罪而提供工具或者其他帮助，情节严重的，以共同犯罪论处。"},{"i":7,"n":"第七条","txt":"行为人阻碍人民警察依法执行职务，但未实施暴力袭击行为的，不构成袭警罪；符合刑法第二百七十七条第一款规定的，以妨害公务罪定罪处罚。"},{"i":8,"n":"第八条","txt":"暴力袭击正在依法配合人民警察执行职务的警务辅助人员的，不构成袭警罪；符合刑法第二百七十七条第一款规定的，以妨害公务罪定罪处罚。"},{"i":9,"n":"第九条","txt":"实施本解释规定的行为，同时构成袭警罪、妨害公务罪和故意杀人罪、故意伤害罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"实施本解释规定的行为，综合考虑行为人认罪悔罪表现、赔偿损失情况、行为手段、危害后果等情形，认为犯罪情节较轻的，可以从宽处罚；犯罪情节轻微的，可以不起诉或者免予刑事处罚；情节显著轻微危害不大的，不作为犯罪处理。"},{"i":11,"n":"第十一条","txt":"对于实施本解释规定的相关行为被不起诉或者免予刑事处罚的行为人，需要给予行政处罚、政务处分或者其他处分的，依法移送有关主管机关处理。"},{"i":12,"n":"第十二条","txt":"对于刑法第二百七十七条第五款规定的“人民警察”，依照人民警察法的相关规定认定，包括公安机关、国家安全机关、监狱等部门的人民警察和人民法院、人民检察院的司法警察。"},{"i":13,"n":"第十三条","txt":"本解释自2025年1月18日起施行。本解释施行后，之前发布的规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanafef5d":[{"i":1,"n":"第一条","txt":"诈骗公私财物价值三千元至一万元以上、三万元至十万元以上、五十万元以上的，应当分别认定为刑法第二百六十六条规定的“数额较大”、“数额巨大”、“数额特别巨大”。"},{"i":2,"n":"第二条","txt":"诈骗公私财物达到本解释第一条规定的数额标准，具有下列情形之一的，可以依照刑法第二百六十六条的规定酌情从严惩处："},{"i":3,"n":"第三条","txt":"诈骗公私财物虽已达到本解释第一条规定的“数额较大”的标准，但具有下列情形之一，且行为人认罪、悔罪的，可以根据刑法第三十七条、刑事诉讼法第一百四十二条的规定不起诉或者免予刑事处罚："},{"i":4,"n":"第四条","txt":"诈骗近亲属的财物，近亲属谅解的，一般可不按犯罪处理。"},{"i":5,"n":"第五条","txt":"诈骗未遂，以数额巨大的财物为诈骗目标的，或者具有其他严重情节的，应当定罪处罚。"},{"i":6,"n":"第六条","txt":"诈骗既有既遂，又有未遂，分别达到不同量刑幅度的，依照处罚较重的规定处罚；达到同一量刑幅度的，以诈骗罪既遂处罚。"},{"i":7,"n":"第七条","txt":"明知他人实施诈骗犯罪，为其提供信用卡、手机卡、通讯工具、通讯传输通道、网络技术支持、费用结算等帮助的，以共同犯罪论处。"},{"i":8,"n":"第八条","txt":"冒充国家机关工作人员进行诈骗，同时构成诈骗罪和招摇撞骗罪的，依照处罚较重的规定定罪处罚。"},{"i":9,"n":"第九条","txt":"案发后查封、扣押、冻结在案的诈骗财物及其孳息，权属明确的，应当发还被害人；权属不明确的，可按被骗款物占查封、扣押、冻结在案的财物及其孳息总额的比例发还被害人，但已获退赔的应予扣除。"},{"i":10,"n":"第十条","txt":"行为人已将诈骗财物用于清偿债务或者转让给他人，具有下列情形之一的，应当依法追缴："},{"i":11,"n":"第十一条","txt":"以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban79077d":[{"i":1,"n":"第一条","txt":"贪污或者受贿数额在三万元以上不满二十万元的，应当认定为刑法第三百八十三条第一款规定的“数额较大”，依法判处三年以下有期徒刑或者拘役，并处罚金。"},{"i":2,"n":"第二条","txt":"贪污或者受贿数额在二十万元以上不满三百万元的，应当认定为刑法第三百八十三条第一款规定的“数额巨大”，依法判处三年以上十年以下有期徒刑，并处罚金或者没收财产。"},{"i":3,"n":"第三条","txt":"贪污或者受贿数额在三百万元以上的，应当认定为刑法第三百八十三条第一款规定的“数额特别巨大”，依法判处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产。"},{"i":4,"n":"第四条","txt":"贪污、受贿数额特别巨大，犯罪情节特别严重、社会影响特别恶劣、给国家和人民利益造成特别重大损失的，可以判处死刑。"},{"i":5,"n":"第五条","txt":"挪用公款归个人使用，进行非法活动，数额在三万元以上的，应当依照刑法第三百八十四条的规定以挪用公款罪追究刑事责任；数额在三百万元以上的，应当认定为刑法第三百八十四条第一款规定的“数额巨大”。具有下列情形之一的，应当认定为刑法第三百八十四条第一款规定的“情节严重”："},{"i":6,"n":"第六条","txt":"挪用公款归个人使用，进行营利活动或者超过三个月未还，数额在五万元以上的，应当认定为刑法第三百八十四条第一款规定的“数额较大”；数额在五百万元以上的，应当认定为刑法第三百八十四条第一款规定的“数额巨大”。具有下列情形之一的，应当认定为刑法第三百八十四条第一款规定的“情节严重”："},{"i":7,"n":"第七条","txt":"为谋取不正当利益，向国家工作人员行贿，数额在三万元以上的，应当依照刑法第三百九十条的规定以行贿罪追究刑事责任。"},{"i":8,"n":"第八条","txt":"犯行贿罪，具有下列情形之一的，应当认定为刑法第三百九十条第一款规定的“情节严重”："},{"i":9,"n":"第九条","txt":"犯行贿罪，具有下列情形之一的，应当认定为刑法第三百九十条第一款规定的“情节特别严重”："},{"i":10,"n":"第十条","txt":"刑法第三百八十八条之一规定的利用影响力受贿罪的定罪量刑适用标准，参照本解释关于受贿罪的规定执行。"},{"i":11,"n":"第十一条","txt":"刑法第一百六十三条规定的非国家工作人员受贿罪、第二百七十一条规定的职务侵占罪中的“数额较大”“数额巨大”的数额起点，按照本解释关于受贿罪、贪污罪相对应的数额标准规定的二倍、五倍执行。"},{"i":12,"n":"第十二条","txt":"贿赂犯罪中的“财物”，包括货币、物品和财产性利益。财产性利益包括可以折算为货币的物质利益如房屋装修、债务免除等，以及需要支付货币的其他利益如会员服务、旅游等。后者的犯罪数额，以实际支付或者应当支付的数额计算。"},{"i":13,"n":"第十三条","txt":"具有下列情形之一的，应当认定为“为他人谋取利益”，构成犯罪的，应当依照刑法关于受贿犯罪的规定定罪处罚："},{"i":14,"n":"第十四条","txt":"根据行贿犯罪的事实、情节，可能被判处三年有期徒刑以下刑罚的，可以认定为刑法第三百九十条第二款规定的“犯罪较轻”。"},{"i":15,"n":"第十五条","txt":"对多次受贿未经处理的，累计计算受贿数额。"},{"i":16,"n":"第十六条","txt":"国家工作人员出于贪污、受贿的故意，非法占有公共财物、收受他人财物之后，将赃款赃物用于单位公务支出或者社会捐赠的，不影响贪污罪、受贿罪的认定，但量刑时可以酌情考虑。"},{"i":17,"n":"第十七条","txt":"国家工作人员利用职务上的便利，收受他人财物，为他人谋取利益，同时构成受贿罪和刑法分则第三章第三节、第九章规定的渎职犯罪的，除刑法另有规定外，以受贿罪和渎职犯罪数罪并罚。"},{"i":18,"n":"第十八条","txt":"贪污贿赂犯罪分子违法所得的一切财物，应当依照刑法第六十四条的规定予以追缴或者责令退赔，对被害人的合法财产应当及时返还。对尚未追缴到案或者尚未足额退赔的违法所得，应当继续追缴或者责令退赔。"},{"i":19,"n":"第十九条","txt":"对贪污罪、受贿罪判处三年以下有期徒刑或者拘役的，应当并处十万元以上五十万元以下的罚金；判处三年以上十年以下有期徒刑的，应当并处二十万元以上犯罪数额二倍以下的罚金或者没收财产；判处十年以上有期徒刑或者无期徒刑的，应当并处五十万元以上犯罪数额二倍以下的罚金或者没收财产。"},{"i":20,"n":"第二十条","txt":"本解释自2016年4月18日起施行。最高人民法院、最高人民检察院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban1940ab":[{"i":1,"n":"第一条","txt":"以营利为目的，有下列情形之一的，属于刑法第三百零三条规定的“聚众赌博”："},{"i":2,"n":"第二条","txt":"以营利为目的，在计算机网络上建立赌博网站，或者为赌博网站担任代理，接受投注的，属于刑法第三百零三条规定的“开设赌场”。"},{"i":3,"n":"第三条","txt":"中华人民共和国公民在我国领域外周边地区聚众赌博、开设赌场，以吸引中华人民共和国公民为主要客源，构成赌博罪的，可以依照刑法规定追究刑事责任。"},{"i":4,"n":"第四条","txt":"明知他人实施赌博犯罪活动，而为其提供资金、计算机网络、通讯、费用结算等直接帮助的，以赌博罪的共犯论处。"},{"i":5,"n":"第五条","txt":"实施赌博犯罪，有下列情形之一的，依照刑法第三百零三条的规定从重处罚："},{"i":6,"n":"第六条","txt":"未经国家批准擅自发行、销售彩票，构成犯罪的，依照刑法第二百二十五条第（四）项的规定，以非法经营罪定罪处罚。"},{"i":7,"n":"第七条","txt":"通过赌博或者为国家工作人员赌博提供资金的形式实施行贿、受贿行为，构成犯罪的，依照刑法关于贿赂犯罪的规定定罪处罚。"},{"i":8,"n":"第八条","txt":"赌博犯罪中用作赌注的款物、换取筹码的款物和通过赌博赢取的款物属于赌资。通过计算机网络实施赌博犯罪的，赌资数额可以按照在计算机网络上投注或者赢取的点数乘以每一点实际代表的金额认定。"},{"i":9,"n":"第九条","txt":"不以营利为目的，进行带有少量财物输赢的娱乐活动，以及提供棋牌室等娱乐场所只收取正常的场所和服务费用的经营行为等，不以赌博论处。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban2854f9":[{"i":1,"n":"第一条","txt":"走私武器、弹药，具有下列情形之一的，可以认定为刑法第一百五十一条第一款规定的“情节较轻”："},{"i":2,"n":"第二条","txt":"刑法第一百五十一条第一款规定的“武器、弹药”的种类，参照《中华人民共和国进口税则》及《中华人民共和国禁止进出境物品表》的有关规定确定。"},{"i":3,"n":"第三条","txt":"走私枪支散件，构成犯罪的，依照刑法第一百五十一条第一款的规定，以走私武器罪定罪处罚。成套枪支散件以相应数量的枪支计，非成套枪支散件以每三十件为一套枪支散件计。"},{"i":4,"n":"第四条","txt":"走私各种弹药的弹头、弹壳，构成犯罪的，依照刑法第一百五十一条第一款的规定，以走私弹药罪定罪处罚。具体的定罪量刑标准，按照本解释第一条规定的数量标准的五倍执行。"},{"i":5,"n":"第五条","txt":"走私国家禁止或者限制进出口的仿真枪、管制刀具，构成犯罪的，依照刑法第一百五十一条第三款的规定，以走私国家禁止进出口的货物、物品罪定罪处罚。具体的定罪量刑标准，适用本解释第十一条第一款第六、七项和第二款的规定。"},{"i":6,"n":"第六条","txt":"走私伪造的货币，数额在二千元以上不满二万元，或者数量在二百张（枚）以上不满二千张（枚）的，可以认定为刑法第一百五十一条第一款规定的“情节较轻”。"},{"i":7,"n":"第七条","txt":"刑法第一百五十一条第一款规定的“货币”，包括正在流通的人民币和境外货币。伪造的境外货币数额，折合成人民币计算。"},{"i":8,"n":"第八条","txt":"走私国家禁止出口的三级文物二件以下的，可以认定为刑法第一百五十一条第二款规定的“情节较轻”。"},{"i":9,"n":"第九条","txt":"走私国家一、二级保护动物未达到本解释附表中（一）规定的数量标准，或者走私珍贵动物制品数额不满二十万元的，可以认定为刑法第一百五十一条第二款规定的“情节较轻”。"},{"i":10,"n":"第十条","txt":"刑法第一百五十一条第二款规定的“珍贵动物”，包括列入《国家重点保护野生动物名录》中的国家一、二级保护野生动物，《濒危野生动植物种国际贸易公约》附录I、附录II中的野生动物，以及驯养繁殖的上述动物。"},{"i":11,"n":"第十一条","txt":"走私国家禁止进出口的货物、物品，具有下列情形之一的，依照刑法第一百五十一条第三款的规定处五年以下有期徒刑或者拘役，并处或者单处罚金："},{"i":12,"n":"第十二条","txt":"刑法第一百五十一条第三款规定的“珍稀植物”，包括列入《国家重点保护野生植物名录》《国家重点保护野生药材物种名录》《国家珍贵树种名录》中的国家一、二级保护野生植物、国家重点保护的野生药材、珍贵树木，《濒危野生动植物种国际贸易公约》附录I、附录II中的野生植物，以及人工培育的上述植物。"},{"i":13,"n":"第十三条","txt":"以牟利或者传播为目的，走私淫秽物品，达到下列数量之一的，可以认定为刑法第一百五十二条第一款规定的“情节较轻”："},{"i":14,"n":"第十四条","txt":"走私国家禁止进口的废物或者国家限制进口的可用作原料的废物，具有下列情形之一的，应当认定为刑法第一百五十二条第二款规定的“情节严重”："},{"i":15,"n":"第十五条","txt":"国家限制进口的可用作原料的废物的具体种类，参照国家有关部门的规定确定。"},{"i":16,"n":"第十六条","txt":"走私普通货物、物品，偷逃应缴税额在十万元以上不满五十万元的，应当认定为刑法第一百五十三条第一款规定的“偷逃应缴税额较大”；偷逃应缴税额在五十万元以上不满二百五十万元的，应当认定为“偷逃应缴税额巨大”；偷逃应缴税额在二百五十万元以上的，应当认定为“偷逃应缴税额特别巨大”。"},{"i":17,"n":"第十七条","txt":"刑法第一百五十三条第一款规定的“一年内曾因走私被给予二次行政处罚后又走私”中的“一年内”，以因走私第一次受到行政处罚的生效之日与“又走私”行为实施之日的时间间隔计算确定；“被给予二次行政处罚”的走私行为，包括走私普通货物、物品以及其他货物、物品；“又走私”行为仅指走私普通货物、物品。"},{"i":18,"n":"第十八条","txt":"刑法第一百五十三条规定的“应缴税额”，包括进出口货物、物品应当缴纳的进出口关税和进口环节海关代征税的税额。应缴税额以走私行为实施时的税则、税率、汇率和完税价格计算；多次走私的，以每次走私行为实施时的税则、税率、汇率和完税价格逐票计算；走私行为实施时间不能确定的，以案发时的税则、税率、汇率和完税价格计算。"},{"i":19,"n":"第十九条","txt":"刑法第一百五十四条规定的“保税货物”，是指经海关批准，未办理纳税手续进境，在境内储存、加工、装配后应予复运出境的货物，包括通过加工贸易、补偿贸易等方式进口的货物，以及在保税仓库、保税工厂、保税区或者免税商店内等储存、加工、寄售的货物。"},{"i":20,"n":"第二十条","txt":"直接向走私人非法收购走私进口的货物、物品，在内海、领海、界河、界湖运输、收购、贩卖国家禁止进出口的物品，或者没有合法证明，在内海、领海、界河、界湖运输、收购、贩卖国家限制进出口的货物、物品，构成犯罪的，应当按照走私货物、物品的种类，分别依照刑法第一百五十一条、第一百五十二条、第一百五十三条、第三百四十七条、第三百五十条的规定定罪处罚。"},{"i":21,"n":"第二十一条","txt":"未经许可进出口国家限制进出口的货物、物品，构成犯罪的，应当依照刑法第一百五十一条、第一百五十二条的规定，以走私国家禁止进出口的货物、物品罪等罪名定罪处罚；偷逃应缴税额，同时又构成走私普通货物、物品罪的，依照处罚较重的规定定罪处罚。"},{"i":22,"n":"第二十二条","txt":"在走私的货物、物品中藏匿刑法第一百五十一条、第一百五十二条、第三百四十七条、第三百五十条规定的货物、物品，构成犯罪的，以实际走私的货物、物品定罪处罚；构成数罪的，实行数罪并罚。"},{"i":23,"n":"第二十三条","txt":"实施走私犯罪，具有下列情形之一的，应当认定为犯罪既遂："},{"i":24,"n":"第二十四条","txt":"单位犯刑法第一百五十一条、第一百五十二条规定之罪，依照本解释规定的标准定罪处罚。"},{"i":25,"n":"第二十五条","txt":"本解释发布实施后，《最高人民法院关于审理走私刑事案件具体应用法律若干问题的解释》（法释〔2000〕30号）、《最高人民法院关于审理走私刑事案件具体应用法律若干问题的解释（二）》（法释〔2006〕9号）同时废止。之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban4bd7e2":[{"i":1,"n":"第一条","txt":"提供下列服务的单位和个人，应当认定为刑法第二百八十六条之一第一款规定的“网络服务提供者”："},{"i":2,"n":"第二条","txt":"刑法第二百八十六条之一第一款规定的“监管部门责令采取改正措施”，是指网信、电信、公安等依照法律、行政法规的规定承担信息网络安全监管职责的部门，以责令整改通知书或者其他文书形式，责令网络服务提供者采取改正措施。"},{"i":3,"n":"第三条","txt":"拒不履行信息网络安全管理义务，具有下列情形之一的，应当认定为刑法第二百八十六条之一第一款第一项规定的“致使违法信息大量传播”："},{"i":4,"n":"第四条","txt":"拒不履行信息网络安全管理义务，致使用户信息泄露，具有下列情形之一的，应当认定为刑法第二百八十六条之一第一款第二项规定的“造成严重后果”："},{"i":5,"n":"第五条","txt":"拒不履行信息网络安全管理义务，致使影响定罪量刑的刑事案件证据灭失，具有下列情形之一的，应当认定为刑法第二百八十六条之一第一款第三项规定的“情节严重”："},{"i":6,"n":"第六条","txt":"拒不履行信息网络安全管理义务，具有下列情形之一的，应当认定为刑法第二百八十六条之一第一款第四项规定的“有其他严重情节”："},{"i":7,"n":"第七条","txt":"刑法第二百八十七条之一规定的“违法犯罪”，包括犯罪行为和属于刑法分则规定的行为类型但尚未构成犯罪的违法行为。"},{"i":8,"n":"第八条","txt":"以实施违法犯罪活动为目的而设立或者设立后主要用于实施违法犯罪活动的网站、通讯群组，应当认定为刑法第二百八十七条之一第一款第一项规定的“用于实施诈骗、传授犯罪方法、制作或者销售违禁物品、管制物品等违法犯罪活动的网站、通讯群组”。"},{"i":9,"n":"第九条","txt":"利用信息网络提供信息的链接、截屏、二维码、访问账号密码及其他指引访问服务的，应当认定为刑法第二百八十七条之一第一款第二项、第三项规定的“发布信息”。"},{"i":10,"n":"第十条","txt":"非法利用信息网络，具有下列情形之一的，应当认定为刑法第二百八十七条之一第一款规定的“情节严重”："},{"i":11,"n":"第十一条","txt":"为他人实施犯罪提供技术支持或者帮助，具有下列情形之一的，可以认定行为人明知他人利用信息网络实施犯罪，但是有相反证据的除外："},{"i":12,"n":"第十二条","txt":"明知他人利用信息网络实施犯罪，为其犯罪提供帮助，具有下列情形之一的，应当认定为刑法第二百八十七条之二第一款规定的“情节严重”："},{"i":13,"n":"第十三条","txt":"被帮助对象实施的犯罪行为可以确认，但尚未到案、尚未依法裁判或者因未达到刑事责任年龄等原因依法未予追究刑事责任的，不影响帮助信息网络犯罪活动罪的认定。"},{"i":14,"n":"第十四条","txt":"单位实施本解释规定的犯罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":15,"n":"第十五条","txt":"综合考虑社会危害程度、认罪悔罪态度等情节，认为犯罪情节轻微的，可以不起诉或者免予刑事处罚；情节显著轻微危害不大的，不以犯罪论处。"},{"i":16,"n":"第十六条","txt":"多次拒不履行信息网络安全管理义务、非法利用信息网络、帮助信息网络犯罪活动构成犯罪，依法应当追诉的，或者二年内多次实施前述行为未经处理的，数量或者数额累计计算。"},{"i":17,"n":"第十七条","txt":"对于实施本解释规定的犯罪被判处刑罚的，可以根据犯罪情况和预防再犯罪的需要，依法宣告职业禁止；被判处管制、宣告缓刑的，可以根据犯罪情况，依法宣告禁止令。"},{"i":18,"n":"第十八条","txt":"对于实施本解释规定的犯罪的，应当综合考虑犯罪的危害程度、违法所得数额以及被告人的前科情况、认罪悔罪态度等，依法判处罚金。"},{"i":19,"n":"第十九条","txt":"本解释自2019年11月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban575108":[{"i":1,"n":"第一条","txt":"非法制造、买卖、运输、储存毒鼠强等禁用剧毒化学品，危害公共安全，具有下列情形之一的，依照刑法第一百二十五条的规定，以非法制造、买卖、运输、储存危险物质罪，处三年以上十年以下有期徒刑："},{"i":2,"n":"第二条","txt":"非法制造、买卖、运输、储存毒鼠强等禁用剧毒化学品，具有下列情形之一的，属于刑法第一百二十五条规定的“情节严重”，处十年以上有期徒刑、无期徒刑或者死刑："},{"i":3,"n":"第三条","txt":"单位非法制造、买卖、运输、储存毒鼠强等禁用剧毒化学品的，依照本解释第一条、第二条规定的定罪量刑标准执行。"},{"i":4,"n":"第四条","txt":"对非法制造、买卖、运输、储存毒鼠强等禁用剧毒化学品行为负有查处职责的国家机关工作人员，滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，依照刑法第三百九十七条的规定，以滥用职权罪或者玩忽职守罪追究刑事责任。"},{"i":5,"n":"第五条","txt":"本解释施行以前，确因生产、生活需要而非法制造、买卖、运输、储存毒鼠强等禁用剧毒化学品饵料自用，没有造成严重社会危害的，可以依照刑法第十三条的规定，不作为犯罪处理。"},{"i":6,"n":"第六条","txt":"本解释所称“毒鼠强等禁用剧毒化学品”，是指国家明令禁止的毒鼠强、氟乙酰胺、氟乙酸钠、毒鼠硅、甘氟（见附表）。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanefb628":[{"i":1,"n":"第一条","txt":"未取得药品生产、经营许可证件和批准文号，非法生产、销售盐酸克仑特罗等禁止在饲料和动物饮用水中使用的药品，扰乱药品市场秩序，情节严重的，依照刑法第二百二十五条第（一）项的规定，以非法经营罪追究刑事责任。"},{"i":2,"n":"第二条","txt":"在生产、销售的饲料中添加盐酸克仑特罗等禁止在饲料和动物饮用水中使用的药品，或者销售明知是添加有该类药品的饲料，情节严重的，依照刑法第二百二十五条第（四）项的规定，以非法经营罪追究刑事责任。"},{"i":3,"n":"第三条","txt":"使用盐酸克仑特罗等禁止在饲料和动物饮用水中使用的药品或者含有该类药品的饲料养殖供人食用的动物，或者销售明知是使用该类药品或者含有该类药品的饲料养殖的供人食用的动物的，依照刑法第一百四十四条的规定，以生产、销售有毒、有害食品罪追究刑事责任。"},{"i":4,"n":"第四条","txt":"明知是使用盐酸克仑特罗等禁止在饲料和动物饮用水中使用的药品或者含有该类药品的饲料养殖的供人食用的动物，而提供屠宰等加工服务，或者销售其制品的，依照刑法第一百四十四条的规定，以生产、销售有毒、有害食品罪追究刑事责任。"},{"i":5,"n":"第五条","txt":"实施本解释规定的行为，同时触犯刑法规定的两种以上犯罪的，依照处罚较重的规定追究刑事责任。"},{"i":6,"n":"第六条","txt":"禁止在饲料和动物饮用水中使用的药品，依照国家有关部门公告的禁止在饲料和动物饮用水中使用的药物品种目录确定。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanb7bc8a":[{"i":1,"n":"第一条","txt":"生产、销售伪劣卷烟、雪茄烟等烟草专卖品，销售金额在五万元以上的，依照刑法第一百四十条的规定，以生产、销售伪劣产品罪定罪处罚。"},{"i":2,"n":"第二条","txt":"伪劣卷烟、雪茄烟等烟草专卖品尚未销售，货值金额达到刑法第一百四十条规定的销售金额定罪起点数额标准的三倍以上的，或者销售金额未达到五万元，但与未销售货值金额合计达到十五万元以上的，以生产、销售伪劣产品罪（未遂）定罪处罚。"},{"i":3,"n":"第三条","txt":"非法经营烟草专卖品，具有下列情形之一的，应当认定为刑法第二百二十五条规定的“情节严重”："},{"i":4,"n":"第四条","txt":"非法经营烟草专卖品，能够查清销售或者购买价格的，按照其销售或者购买的价格计算非法经营数额。无法查清销售或者购买价格的，按照下列方法计算非法经营数额："},{"i":5,"n":"第五条","txt":"行为人实施非法生产、销售烟草专卖品犯罪，同时构成生产、销售伪劣产品罪、侵犯知识产权犯罪、非法经营罪的，依照处罚较重的规定定罪处罚。"},{"i":6,"n":"第六条","txt":"明知他人实施本解释第一条所列犯罪，而为其提供贷款、资金、账号、发票、证明、许可证件，或者提供生产、经营场所、设备、运输、仓储、保管、邮寄、代理进出口等便利条件，或者提供生产技术、卷烟配方的，应当按照共犯追究刑事责任。"},{"i":7,"n":"第七条","txt":"办理非法生产、销售烟草专卖品等刑事案件，需要对伪劣烟草专卖品鉴定的，应当委托国务院产品质量监督管理部门和省、自治区、直辖市人民政府产品质量监督管理部门指定的烟草质量检测机构进行。"},{"i":8,"n":"第八条","txt":"以暴力、威胁方法阻碍烟草专卖执法人员依法执行职务，构成犯罪的，以妨害公务罪追究刑事责任。"},{"i":9,"n":"第九条","txt":"本解释所称“烟草专卖品”，是指卷烟、雪茄烟、烟丝、复烤烟叶、烟叶、卷烟纸、滤嘴棒、烟用丝束、烟草专用机械。"},{"i":10,"n":"第十条","txt":"以前发布的有关规定与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban7b00d5":[{"i":1,"n":"第一条","txt":"对未经国家主管部门批准或者超过批准的业务范围，采集、供应血液或者制作、供应血液制品的，应认定为刑法第三百三十四条第一款规定的“非法采集、供应血液或者制作、供应血液制品”。"},{"i":2,"n":"第二条","txt":"对非法采集、供应血液或者制作、供应血液制品，具有下列情形之一的，应认定为刑法第三百三十四条第一款规定的“不符合国家规定的标准，足以危害人体健康”，处五年以下有期徒刑或者拘役，并处罚金："},{"i":3,"n":"第三条","txt":"对非法采集、供应血液或者制作、供应血液制品，具有下列情形之一的，应认定为刑法第三百三十四条第一款规定的“对人体健康造成严重危害”，处五年以上十年以下有期徒刑，并处罚金："},{"i":4,"n":"第四条","txt":"对非法采集、供应血液或者制作、供应血液制品，具有下列情形之一的，应认定为刑法第三百三十四条第一款规定的“造成特别严重后果”，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产："},{"i":5,"n":"第五条","txt":"对经国家主管部门批准采集、供应血液或者制作、供应血液制品的部门，具有下列情形之一的，应认定为刑法第三百三十四条第二款规定的“不依照规定进行检测或者违背其他操作规定”："},{"i":6,"n":"第六条","txt":"对经国家主管部门批准采集、供应血液或者制作、供应血液制品的部门，不依照规定进行检测或者违背其他操作规定，具有下列情形之一的，应认定为刑法第三百三十四条第二款规定的“造成危害他人身体健康后果”，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役："},{"i":7,"n":"第七条","txt":"经国家主管部门批准的采供血机构和血液制品生产经营单位，应认定为刑法第三百三十四条第二款规定的“经国家主管部门批准采集、供应血液或者制作、供应血液制品的部门”。"},{"i":8,"n":"第八条","txt":"本解释所称“血液”，是指全血、成分血和特殊血液成分。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanf95565":[{"i":1,"n":"第一条","txt":"违反《中华人民共和国矿产资源法》《中华人民共和国水法》等法律、行政法规有关矿产资源开发、利用、保护和管理的规定的，应当认定为刑法第三百四十三条规定的“违反矿产资源法的规定”。"},{"i":2,"n":"第二条","txt":"具有下列情形之一的，应当认定为刑法第三百四十三条第一款规定的“未取得采矿许可证”："},{"i":3,"n":"第三条","txt":"实施非法采矿行为，具有下列情形之一的，应当认定为刑法第三百四十三条第一款规定的“情节严重”："},{"i":4,"n":"第四条","txt":"在河道管理范围内采砂，具有下列情形之一，符合刑法第三百四十三条第一款和本解释第二条、第三条规定的，以非法采矿罪定罪处罚："},{"i":5,"n":"第五条","txt":"未取得海砂开采海域使用权证，且未取得采矿许可证，采挖海砂，符合刑法第三百四十三条第一款和本解释第二条、第三条规定的，以非法采矿罪定罪处罚。"},{"i":6,"n":"第六条","txt":"造成矿产资源破坏的价值在五十万元至一百万元以上，或者造成国家规划矿区、对国民经济具有重要价值的矿区和国家规定实行保护性开采的特定矿种资源破坏的价值在二十五万元至五十万元以上的，应当认定为刑法第三百四十三条第二款规定的“造成矿产资源严重破坏”。"},{"i":7,"n":"第七条","txt":"明知是犯罪所得的矿产品及其产生的收益，而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒的，依照刑法第三百一十二条的规定，以掩饰、隐瞒犯罪所得、犯罪所得收益罪定罪处罚。"},{"i":8,"n":"第八条","txt":"多次非法采矿、破坏性采矿构成犯罪，依法应当追诉的，或者二年内多次非法采矿、破坏性采矿未经处理的，价值数额累计计算。"},{"i":9,"n":"第九条","txt":"单位犯刑法第三百四十三条规定之罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":10,"n":"第十条","txt":"实施非法采矿犯罪，不属于“情节特别严重”，或者实施破坏性采矿犯罪，行为人系初犯，全部退赃退赔，积极修复环境，并确有悔改表现的，可以认定为犯罪情节轻微，不起诉或者免予刑事处罚。"},{"i":11,"n":"第十一条","txt":"对受雇佣为非法采矿、破坏性采矿犯罪提供劳务的人员，除参与利润分成或者领取高额固定工资的以外，一般不以犯罪论处，但曾因非法采矿、破坏性采矿受过处罚的除外。"},{"i":12,"n":"第十二条","txt":"对非法采矿、破坏性采矿犯罪的违法所得及其收益，应当依法追缴或者责令退赔。"},{"i":13,"n":"第十三条","txt":"非法开采的矿产品价值，根据销赃数额认定；无销赃数额，销赃数额难以查证，或者根据销赃数额认定明显不合理的，根据矿产品价格和数量认定。"},{"i":14,"n":"第十四条","txt":"对案件所涉的有关专门性问题难以确定的，依据下列机构出具的鉴定意见或者报告，结合其他证据作出认定："},{"i":15,"n":"第十五条","txt":"各省、自治区、直辖市高级人民法院、人民检察院，可以根据本地区实际情况，在本解释第三条、第六条规定的数额幅度内，确定本地区执行的具体数额标准，报最高人民法院、最高人民检察院备案。"},{"i":16,"n":"第十六条","txt":"本解释自2016年12月1日起施行。本解释施行后，最高人民法院《关于审理非法采矿、破坏性采矿刑事案件具体应用法律若干问题的解释》（法释〔2003〕9号）同时废止。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyujia8854e5":[{"i":1,"n":"第一条","txt":"为正确适用《中华人民共和国民法典》《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》关于人民检察院提起公益诉讼制度的规定，结合审判、检察工作实际，制定本解释。"},{"i":2,"n":"第二条","txt":"人民法院、人民检察院办理公益诉讼案件主要任务是充分发挥司法审判、法律监督职能作用，维护宪法法律权威，维护社会公平正义，维护国家利益和社会公共利益，督促适格主体依法行使公益诉权，促进依法行政、严格执法。"},{"i":3,"n":"第三条","txt":"人民法院、人民检察院办理公益诉讼案件，应当遵守宪法法律规定，遵循诉讼制度的原则，遵循审判权、检察权运行规律。"},{"i":4,"n":"第四条","txt":"人民检察院以公益诉讼起诉人身份提起公益诉讼，依照民事诉讼法、行政诉讼法享有相应的诉讼权利，履行相应的诉讼义务，但法律、司法解释另有规定的除外。"},{"i":5,"n":"第五条","txt":"市（分、州）人民检察院提起的第一审民事公益诉讼案件，由侵权行为地或者被告住所地中级人民法院管辖。"},{"i":6,"n":"第六条","txt":"人民检察院办理公益诉讼案件，可以向有关行政机关以及其他组织、公民调查收集证据材料；有关行政机关以及其他组织、公民应当配合；需要采取证据保全措施的，依照民事诉讼法、行政诉讼法相关规定办理。"},{"i":7,"n":"第七条","txt":"人民法院审理人民检察院提起的第一审公益诉讼案件，适用人民陪审制。"},{"i":8,"n":"第八条","txt":"人民法院开庭审理人民检察院提起的公益诉讼案件，应当在开庭三日前向人民检察院送达出庭通知书。"},{"i":9,"n":"第九条","txt":"出庭检察人员履行以下职责："},{"i":10,"n":"第十条","txt":"人民检察院不服人民法院第一审判决、裁定的，可以向上一级人民法院提起上诉。"},{"i":11,"n":"第十一条","txt":"人民法院审理第二审案件，由提起公益诉讼的人民检察院派员出庭，上一级人民检察院也可以派员参加。"},{"i":12,"n":"第十二条","txt":"人民检察院提起公益诉讼案件判决、裁定发生法律效力，被告不履行的，人民法院应当移送执行。"},{"i":13,"n":"第十三条","txt":"人民检察院在履行职责中发现破坏生态环境和资源保护，食品药品安全领域侵害众多消费者合法权益，侵害英雄烈士等的姓名、肖像、名誉、荣誉等损害社会公共利益的行为，拟提起公益诉讼的，应当依法公告，公告期间为三十日。"},{"i":14,"n":"第十四条","txt":"人民检察院提起民事公益诉讼应当提交下列材料："},{"i":15,"n":"第十五条","txt":"人民检察院依据民事诉讼法第五十五条第二款的规定提起民事公益诉讼，符合民事诉讼法第一百一十九条第二项、第三项、第四项及本解释规定的起诉条件的，人民法院应当登记立案。"},{"i":16,"n":"第十六条","txt":"人民检察院提起的民事公益诉讼案件中，被告以反诉方式提出诉讼请求的，人民法院不予受理。"},{"i":17,"n":"第十七条","txt":"人民法院受理人民检察院提起的民事公益诉讼案件后，应当在立案之日起五日内将起诉书副本送达被告。"},{"i":18,"n":"第十八条","txt":"人民法院认为人民检察院提出的诉讼请求不足以保护社会公共利益的，可以向其释明变更或者增加停止侵害、恢复原状等诉讼请求。"},{"i":19,"n":"第十九条","txt":"民事公益诉讼案件审理过程中，人民检察院诉讼请求全部实现而撤回起诉的，人民法院应予准许。"},{"i":20,"n":"第二十条","txt":"人民检察院对破坏生态环境和资源保护，食品药品安全领域侵害众多消费者合法权益，侵害英雄烈士等的姓名、肖像、名誉、荣誉等损害社会公共利益的犯罪行为提起刑事公诉时，可以向人民法院一并提起附带民事公益诉讼，由人民法院同一审判组织审理。"},{"i":21,"n":"第二十一条","txt":"人民检察院在履行职责中发现生态环境和资源保护、食品药品安全、国有财产保护、国有土地使用权出让等领域负有监督管理职责的行政机关违法行使职权或者不作为，致使国家利益或者社会公共利益受到侵害的，应当向行政机关提出检察建议，督促其依法履行职责。"},{"i":22,"n":"第二十二条","txt":"人民检察院提起行政公益诉讼应当提交下列材料："},{"i":23,"n":"第二十三条","txt":"人民检察院依据行政诉讼法第二十五条第四款的规定提起行政公益诉讼，符合行政诉讼法第四十九条第二项、第三项、第四项及本解释规定的起诉条件的，人民法院应当登记立案。"},{"i":24,"n":"第二十四条","txt":"在行政公益诉讼案件审理过程中，被告纠正违法行为或者依法履行职责而使人民检察院的诉讼请求全部实现，人民检察院撤回起诉的，人民法院应当裁定准许；人民检察院变更诉讼请求，请求确认原行政行为违法的，人民法院应当判决确认违法。"},{"i":25,"n":"第二十五条","txt":"人民法院区分下列情形作出行政公益诉讼判决："},{"i":26,"n":"第二十六条","txt":"本解释未规定的其他事项，适用民事诉讼法、行政诉讼法以及相关司法解释的规定。"},{"i":27,"n":"第二十七条","txt":"本解释自2018年3月2日起施行。"}],"zuigaorenminfayuanguanyuxingfaxiuzhenganshijianxia61b553":[{"i":1,"n":"第一条","txt":"对于2011年4月30日以前犯罪，依法应当判处管制或者宣告缓刑的，人民法院根据犯罪情况，认为确有必要同时禁止犯罪分子在管制期间或者缓刑考验期内从事特定活动，进入特定区域、场所，接触特定人的，适用修正后刑法第三十八条第二款或者第七十二条第二款的规定。"},{"i":2,"n":"第二条","txt":"2011年4月30日以前犯罪，判处死刑缓期执行的，适用修正前刑法第五十条的规定。"},{"i":3,"n":"第三条","txt":"被判处有期徒刑以上刑罚，刑罚执行完毕或者赦免以后，在2011年4月30日以前再犯应当判处有期徒刑以上刑罚之罪的，是否构成累犯，适用修正前刑法第六十五条的规定；但是，前罪实施时不满十八周岁的，是否构成累犯，适用修正后刑法第六十五条的规定。"},{"i":4,"n":"第四条","txt":"2011年4月30日以前犯罪，虽不具有自首情节，但是如实供述自己罪行的，适用修正后刑法第六十七条第三款的规定。"},{"i":5,"n":"第五条","txt":"2011年4月30日以前犯罪，犯罪后自首又有重大立功表现的，适用修正前刑法第六十八条第二款的规定。"},{"i":6,"n":"第六条","txt":"2011年4月30日以前一人犯数罪，应当数罪并罚的，适用修正前刑法第六十九条的规定；2011年4月30日前后一人犯数罪，其中一罪发生在2011年5月1日以后的，适用修正后刑法第六十九条的规定。"},{"i":7,"n":"第七条","txt":"2011年4月30日以前犯罪，被判处无期徒刑的罪犯，减刑以后或者假释前实际执行的刑期，适用修正前刑法第七十八条第二款、第八十一条第一款的规定。"},{"i":8,"n":"第八条","txt":"2011年4月30日以前犯罪，因具有累犯情节或者系故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪并被判处十年以上有期徒刑、无期徒刑的犯罪分子，2011年5月1日以后仍在服刑的，能否假释，适用修正前刑法第八十一条第二款的规定；2011年4月30日以前犯罪，因其他暴力性犯罪被判处十年以上有期徒刑、无期徒刑的犯罪分子，2011年5月1日以后仍在服刑的，能否假释，适用修正后刑法第八十一条第二款、第三款的规定。"}],"zuigaorenminfayuanguanyuxingfaxiuzhenganshijianxia1b3902":[{"i":1,"n":"第一条","txt":"对于2015年10月31日以前因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪的，不适用修正后刑法第三十七条之一第一款的规定。其他法律、行政法规另有规定的，从其规定。"},{"i":2,"n":"第二条","txt":"对于被判处死刑缓期执行的犯罪分子，在死刑缓期执行期间，且在2015年10月31日以前故意犯罪的，适用修正后刑法第五十条第一款的规定。"},{"i":3,"n":"第三条","txt":"对于2015年10月31日以前一人犯数罪，数罪中有判处有期徒刑和拘役，有期徒刑和管制，或者拘役和管制，予以数罪并罚的，适用修正后刑法第六十九条第二款的规定。"},{"i":4,"n":"第四条","txt":"对于2015年10月31日以前通过信息网络实施的刑法第二百四十六条第一款规定的侮辱、诽谤行为，被害人向人民法院告诉，但提供证据确有困难的，适用修正后刑法第二百四十六条第三款的规定。"},{"i":5,"n":"第五条","txt":"对于2015年10月31日以前实施的刑法第二百六十条第一款规定的虐待行为，被害人没有能力告诉，或者因受到强制、威吓无法告诉的，适用修正后刑法第二百六十条第三款的规定。"},{"i":6,"n":"第六条","txt":"对于2015年10月31日以前组织考试作弊，为他人组织考试作弊提供作弊器材或者其他帮助，以及非法向他人出售或者提供考试试题、答案，根据修正前刑法应当以非法获取国家秘密罪、非法生产、销售间谍专用器材罪或者故意泄露国家秘密罪等追究刑事责任的，适用修正前刑法的有关规定。但是，根据修正后刑法第二百八十四条之一的规定处刑较轻的，适用修正后刑法的有关规定。"},{"i":7,"n":"第七条","txt":"对于2015年10月31日以前以捏造的事实提起民事诉讼，妨害司法秩序或者严重侵害他人合法权益，根据修正前刑法应当以伪造公司、企业、事业单位、人民团体印章罪或者妨害作证罪等追究刑事责任的，适用修正前刑法的有关规定。但是，根据修正后刑法第三百零七条之一的规定处刑较轻的，适用修正后刑法的有关规定。"},{"i":8,"n":"第八条","txt":"对于2015年10月31日以前实施贪污、受贿行为，罪行极其严重，根据修正前刑法判处死刑缓期执行不能体现罪刑相适应原则，而根据修正后刑法判处死刑缓期执行同时决定在其死刑缓期执行二年期满依法减为无期徒刑后，终身监禁，不得减刑、假释可以罚当其罪的，适用修正后刑法第三百八十三条第四款的规定。根据修正前刑法判处死刑缓期执行足以罚当其罪的，不适用修正后刑法第三百八十三条第四款的规定。"},{"i":9,"n":"第九条","txt":"本解释自2015年11月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuanduizhuceshangbd589a9":[{"i":1,"n":"第一条","txt":"人民法院根据民事诉讼法有关规定采取财产保全措施时，需要对注册商标权进行保全的，应当向国家知识产权局商标局（以下简称商标局）发出协助执行通知书，载明要求商标局协助保全的注册商标的名称、注册人、注册证号码、保全期限以及协助执行保全的内容，包括禁止转让、注销注册商标、变更注册事项和办理商标权质押登记等事项。"},{"i":2,"n":"第二条","txt":"对注册商标权保全的期限一次不得超过一年，自商标局收到协助执行通知书之日起计算。如果仍然需要对该注册商标权继续采取保全措施的，人民法院应当在保全期限届满前向商标局重新发出协助执行通知书，要求继续保全。否则，视为自动解除对该注册商标权的财产保全。"},{"i":3,"n":"第三条","txt":"人民法院对已经进行保全的注册商标权，不得重复进行保全。"}],"zuigaorenminfayuanguanyurenminfayuanduijinglaodongfd1adf":[{"i":1,"n":"第一条","txt":"当事人不服劳动争议仲裁裁决向人民法院起诉后又申请撤诉，经人民法院审查准予撤诉的，原仲裁裁决自人民法院裁定送达当事人之日起发生法律效力。"},{"i":2,"n":"第二条","txt":"当事人因超过起诉期间而被人民法院裁定驳回起诉的，原仲裁裁决自起诉期间届满之次日起恢复法律效力。"},{"i":3,"n":"第三条","txt":"因仲裁裁决确定的主体资格错误或仲裁裁决事项不属于劳动争议，被人民法院驳回起诉的，原仲裁裁决不发生法律效力。"}],"zuigaorenminfayuanguanyushangbiaofaxiugaijuedingsh9be3fa":[{"i":1,"n":"第一条","txt":"人民法院受理以下商标案件："},{"i":2,"n":"第二条","txt":"不服国家知识产权局作出的复审决定或者裁定的行政案件及国家知识产权局作出的有关商标的行政行为案件，由北京市有关中级人民法院管辖。"},{"i":3,"n":"第三条","txt":"第一审商标民事案件，由中级以上人民法院及最高人民法院指定的基层人民法院管辖。"},{"i":4,"n":"第四条","txt":"在行政管理部门查处侵害商标权行为过程中，当事人就相关商标提起商标权权属或者侵害商标权民事诉讼的，人民法院应当受理。"},{"i":5,"n":"第五条","txt":"对于在商标法修改决定施行前提出的商标注册及续展申请，国家知识产权局于决定施行后作出对该商标申请不予受理或者不予续展的决定，当事人提起行政诉讼的，人民法院审查时适用修改后的商标法。"},{"i":6,"n":"第六条","txt":"对于在商标法修改决定施行前当事人就尚未核准注册的商标申请复审，国家知识产权局于决定施行后作出复审决定或者裁定，当事人提起行政诉讼的，人民法院审查时适用修改后的商标法。"},{"i":7,"n":"第七条","txt":"对于在商标法修改决定施行前已经核准注册的商标，国家知识产权局于决定施行前受理、在决定施行后作出复审决定或者裁定，当事人提起行政诉讼的，人民法院审查相关程序问题适用修改后的商标法，审查实体问题适用修改前的商标法。"},{"i":8,"n":"第八条","txt":"对于在商标法修改决定施行前受理的相关商标案件，国家知识产权局于决定施行后作出决定或者裁定，当事人提起行政诉讼的，人民法院认定该决定或者裁定是否符合商标法有关审查时限规定时，应当从修改决定施行之日起计算该审查时限。"},{"i":9,"n":"第九条","txt":"除本解释另行规定外，商标法修改决定施行后人民法院受理的商标民事案件，涉及该决定施行前发生的行为的，适用修改前商标法的规定；涉及该决定施行前发生，持续到该决定施行后的行为的，适用修改后商标法的规定。"}],"zuigaorenminfayuanguanyuguoyouzichanchanquanguanli4b3c37":[],"zuigaorenminfayuanguanyuzaiminshishenpangongzuozhob960dc":[{"i":1,"n":"第一条","txt":"人民法院审理涉及工会组织的有关案件时，应当认定依照工会法建立的工会组织的社团法人资格。具有法人资格的工会组织依法独立享有民事权利，承担民事义务。建立工会的企业、事业单位、机关与所建工会以及工会投资兴办的企业，根据法律和司法解释的规定，应当分别承担各自的民事责任。"},{"i":2,"n":"第二条","txt":"根据工会法第十八条规定，人民法院审理劳动争议案件，涉及确定基层工会专职主席、副主席或者委员延长的劳动合同期限的，应当自上述人员工会职务任职期限届满之日起计算，延长的期限等于其工会职务任职的期间。"},{"i":3,"n":"第三条","txt":"基层工会或者上级工会依照工会法第四十三条规定向人民法院申请支付令的，由被申请人所在地的基层人民法院管辖。"},{"i":4,"n":"第四条","txt":"人民法院根据工会法第四十三条的规定受理工会提出的拨缴工会经费的支付令申请后，应当先行征询被申请人的意见。被申请人仅对应拨缴经费数额有异议的，人民法院应当就无异议部分的工会经费数额发出支付令。"},{"i":5,"n":"第五条","txt":"根据工会法第四十三条和民事诉讼法的有关规定，上级工会向人民法院申请支付令或者提起诉讼，要求企业、事业单位拨缴工会经费的，人民法院应当受理。基层工会要求参加诉讼的，人民法院可以准许其作为共同申请人或者共同原告参加诉讼。"},{"i":6,"n":"第六条","txt":"根据工会法第五十二条规定，人民法院审理涉及职工和工会工作人员因参加工会活动或者履行工会法规定的职责而被解除劳动合同的劳动争议案件，可以根据当事人的请求裁判用人单位恢复其工作，并补发被解除劳动合同期间应得的报酬；或者根据当事人的请求裁判用人单位给予本人年收入二倍的赔偿，并根据劳动合同法第四十六条、第四十七条规定给予解除劳动合同时的经济补偿。"},{"i":7,"n":"第七条","txt":"对于企业、事业单位无正当理由拖延或者拒不拨缴工会经费的，工会组织向人民法院请求保护其权利的诉讼时效期间，适用民法典第一百八十八条的规定。"},{"i":8,"n":"第八条","txt":"工会组织就工会经费的拨缴向人民法院申请支付令的，应当按照《诉讼费用交纳办法》第十四条的规定交纳申请费；督促程序终结后，工会组织另行起诉的，按照《诉讼费用交纳办法》第十三条规定的财产案件受理费标准交纳诉讼费用。"}],"zuigaorenminfayuanguanyuchulizishouheligongjutiyinda1da8":[{"i":1,"n":"第一条","txt":"根据刑法第六十七条第一款的规定，犯罪以后自动投案，如实供述自己的罪行的，是自首。"},{"i":2,"n":"第二条","txt":"根据刑法第六十七条第二款的规定，被采取强制措施的犯罪嫌疑人、被告人和已宣判的罪犯，如实供述司法机关尚未掌握的罪行，与司法机关已掌握的或者判决确定的罪行属不同种罪行的，以自首论。"},{"i":3,"n":"第三条","txt":"根据刑法第六十七条第一款的规定，对于自首的犯罪分子，可以从轻或者减轻处罚；对于犯罪较轻的，可以免除处罚。具体确定从轻、减轻还是免除处罚，应当根据犯罪轻重，并考虑自首的具体情节。"},{"i":4,"n":"第四条","txt":"被采取强制措施的犯罪嫌疑人、被告人和已宣判的罪犯，如实供述司法机关尚未掌握的罪行，与司法机关已掌握的或者判决确定的罪行属同种罪行的，可以酌情从轻处罚；如实供述的同种罪行较重的，一般应当从轻处罚。"},{"i":5,"n":"第五条","txt":"根据刑法第六十八条第一款的规定，犯罪分子到案后有检举、揭发他人犯罪行为，包括共同犯罪案件中的犯罪分子揭发同案犯共同犯罪以外的其他犯罪，经查证属实；提供侦破其他案件的重要线索，经查证属实；阻止他人犯罪活动；协助司法机关抓捕其他犯罪嫌疑人（包括同案犯）；具有其他有利于国家和社会的突出表现的，应当认定为有立功表现。"},{"i":6,"n":"第六条","txt":"共同犯罪案件的犯罪分子到案后，揭发同案犯共同犯罪事实的，可以酌情予以从轻处罚。"},{"i":7,"n":"第七条","txt":"根据刑法第六十八条第一款的规定，犯罪分子有检举、揭发他人重大犯罪行为，经查证属实；提供侦破其他重大案件的重要线索，经查证属实；阻止他人重大犯罪活动；协助司法机关抓捕其他重大犯罪嫌疑人（包括同案犯）；对国家和社会有其他重大贡献等表现的，应当认定为有重大立功表现。"}],"zuigaorenminfayuanguanyuruherendingguoyoukonggucan29adb1":[],"zuigaorenminfayuanguanyushenliweijingwaiqiequcitan5e7c43":[{"i":1,"n":"第一条","txt":"刑法第一百一十一条规定的“国家秘密”，是指《中华人民共和国保守国家秘密法》第二条、第八条以及《中华人民共和国保守国家秘密法实施办法》第四条确定的事项。"},{"i":2,"n":"第二条","txt":"为境外窃取、刺探、收买、非法提供国家秘密或者情报，具有下列情形之一的，属于“情节特别严重”，处10年以上有期徒刑、无期徒刑，可以并处没收财产："},{"i":3,"n":"第三条","txt":"为境外窃取、刺探、收买、非法提供国家秘密或者情报，具有下列情形之一的，处5年以上10年以下有期徒刑，可以并处没收财产："},{"i":4,"n":"第四条","txt":"为境外窃取、刺探、收买、非法提供秘密级国家秘密或者情报，属于“情节较轻”，处5年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处没收财产。"},{"i":5,"n":"第五条","txt":"行为人知道或者应当知道没有标明密级的事项关系国家安全和利益，而为境外窃取、刺探、收买、非法提供的，依照刑法第一百一十一条的规定以为境外窃取、刺探、收买、非法提供国家秘密罪定罪处罚。"},{"i":6,"n":"第六条","txt":"通过互联网将国家秘密或者情报非法发送给境外的机构、组织、个人的，依照刑法第一百一十一条的规定定罪处罚；将国家秘密通过互联网予以发布，情节严重的，依照刑法第三百九十八条的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"审理为境外窃取、刺探、收买、非法提供国家秘密案件，需要对有关事项是否属于国家秘密以及属于何种密级进行鉴定的，由国家保密工作部门或者省、自治区、直辖市保密工作部门鉴定。"}],"zuigaorenminfayuanguanyushenlimaimaihetongjiufenan476170":[{"i":1,"n":"第一条","txt":"当事人之间没有书面合同，一方以送货单、收货单、结算单、发票等主张存在买卖合同关系的，人民法院应当结合当事人之间的交易方式、交易习惯以及其他相关证据，对买卖合同是否成立作出认定。"},{"i":2,"n":"第二条","txt":"标的物为无需以有形载体交付的电子信息产品，当事人对交付方式约定不明确，且依照民法典第五百一十条的规定仍不能确定的，买受人收到约定的电子信息产品或者权利凭证即为交付。"},{"i":3,"n":"第三条","txt":"根据民法典第六百二十九条的规定，买受人拒绝接收多交部分标的物的，可以代为保管多交部分标的物。买受人主张出卖人负担代为保管期间的合理费用的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"民法典第五百九十九条规定的“提取标的物单证以外的有关单证和资料”，主要应当包括保险单、保修单、普通发票、增值税专用发票、产品合格证、质量保证书、质量鉴定书、品质检验证书、产品进出口检疫书、原产地证明书、使用说明书、装箱单等。"},{"i":5,"n":"第五条","txt":"出卖人仅以增值税专用发票及税款抵扣资料证明其已履行交付标的物义务，买受人不认可的，出卖人应当提供其他证据证明交付标的物的事实。"},{"i":6,"n":"第六条","txt":"出卖人就同一普通动产订立多重买卖合同，在买卖合同均有效的情况下，买受人均要求实际履行合同的，应当按照以下情形分别处理："},{"i":7,"n":"第七条","txt":"出卖人就同一船舶、航空器、机动车等特殊动产订立多重买卖合同，在买卖合同均有效的情况下，买受人均要求实际履行合同的，应当按照以下情形分别处理："},{"i":8,"n":"第八条","txt":"民法典第六百零三条第二款第一项规定的“标的物需要运输的”，是指标的物由出卖人负责办理托运，承运人系独立于买卖合同当事人之外的运输业者的情形。标的物毁损、灭失的风险负担，按照民法典第六百零七条第二款的规定处理。"},{"i":9,"n":"第九条","txt":"出卖人根据合同约定将标的物运送至买受人指定地点并交付给承运人后，标的物毁损、灭失的风险由买受人负担，但当事人另有约定的除外。"},{"i":10,"n":"第十条","txt":"出卖人出卖交由承运人运输的在途标的物，在合同成立时知道或者应当知道标的物已经毁损、灭失却未告知买受人，买受人主张出卖人负担标的物毁损、灭失的风险的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"当事人对风险负担没有约定，标的物为种类物，出卖人未以装运单据、加盖标记、通知买受人等可识别的方式清楚地将标的物特定于买卖合同，买受人主张不负担标的物毁损、灭失的风险的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"人民法院具体认定民法典第六百二十一条第二款规定的“合理期限”时，应当综合当事人之间的交易性质、交易目的、交易方式、交易习惯、标的物的种类、数量、性质、安装和使用情况、瑕疵的性质、买受人应尽的合理注意义务、检验方法和难易程度、买受人或者检验人所处的具体环境、自身技能以及其他合理因素，依据诚实信用原则进行判断。"},{"i":13,"n":"第十三条","txt":"买受人在合理期限内提出异议，出卖人以买受人已经支付价款、确认欠款数额、使用标的物等为由，主张买受人放弃异议的，人民法院不予支持，但当事人另有约定的除外。"},{"i":14,"n":"第十四条","txt":"民法典第六百二十一条规定的检验期限、合理期限、二年期限经过后，买受人主张标的物的数量或者质量不符合约定的，人民法院不予支持。"},{"i":15,"n":"第十五条","txt":"买受人依约保留部分价款作为质量保证金，出卖人在质量保证期未及时解决质量问题而影响标的物的价值或者使用效果，出卖人主张支付该部分价款的，人民法院不予支持。"},{"i":16,"n":"第十六条","txt":"买受人在检验期限、质量保证期、合理期限内提出质量异议，出卖人未按要求予以修理或者因情况紧急，买受人自行或者通过第三人修理标的物后，主张出卖人负担因此发生的合理费用的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"标的物质量不符合约定，买受人依照民法典第五百八十二条的规定要求减少价款的，人民法院应予支持。当事人主张以符合约定的标的物和实际交付的标的物按交付时的市场价值计算差价的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"买卖合同对付款期限作出的变更，不影响当事人关于逾期付款违约金的约定，但该违约金的起算点应当随之变更。"},{"i":19,"n":"第十九条","txt":"出卖人没有履行或者不当履行从给付义务，致使买受人不能实现合同目的，买受人主张解除合同的，人民法院应当根据民法典第五百六十三条第一款第四项的规定，予以支持。"},{"i":20,"n":"第二十条","txt":"买卖合同因违约而解除后，守约方主张继续适用违约金条款的，人民法院应予支持；但约定的违约金过分高于造成的损失的，人民法院可以参照民法典第五百八十五条第二款的规定处理。"},{"i":21,"n":"第二十一条","txt":"买卖合同当事人一方以对方违约为由主张支付违约金，对方以合同不成立、合同未生效、合同无效或者不构成违约等为由进行免责抗辩而未主张调整过高的违约金的，人民法院应当就法院若不支持免责抗辩，当事人是否需要主张调整违约金进行释明。"},{"i":22,"n":"第二十二条","txt":"买卖合同当事人一方违约造成对方损失，对方主张赔偿可得利益损失的，人民法院在确定违约责任范围时，应当根据当事人的主张，依据民法典第五百八十四条、第五百九十一条、第五百九十二条、本解释第二十三条等规定进行认定。"},{"i":23,"n":"第二十三条","txt":"买卖合同当事人一方因对方违约而获有利益，违约方主张从损失赔偿额中扣除该部分利益的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"买受人在缔约时知道或者应当知道标的物质量存在瑕疵，主张出卖人承担瑕疵担保责任的，人民法院不予支持，但买受人在缔约时不知道该瑕疵会导致标的物的基本效用显著降低的除外。"},{"i":25,"n":"第二十五条","txt":"买卖合同当事人主张民法典第六百四十一条关于标的物所有权保留的规定适用于不动产的，人民法院不予支持。"},{"i":26,"n":"第二十六条","txt":"买受人已经支付标的物总价款的百分之七十五以上，出卖人主张取回标的物的，人民法院不予支持。"},{"i":27,"n":"第二十七条","txt":"民法典第六百三十四条第一款规定的“分期付款”，系指买受人将应付的总价款在一定期限内至少分三次向出卖人支付。"},{"i":28,"n":"第二十八条","txt":"分期付款买卖合同约定出卖人在解除合同时可以扣留已受领价金，出卖人扣留的金额超过标的物使用费以及标的物受损赔偿额，买受人请求返还超过部分的，人民法院应予支持。"},{"i":29,"n":"第二十九条","txt":"合同约定的样品质量与文字说明不一致且发生纠纷时当事人不能达成合意，样品封存后外观和内在品质没有发生变化的，人民法院应当以样品为准；外观和内在品质发生变化，或者当事人对是否发生变化有争议而又无法查明的，人民法院应当以文字说明为准。"},{"i":30,"n":"第三十条","txt":"买卖合同存在下列约定内容之一的，不属于试用买卖。买受人主张属于试用买卖的，人民法院不予支持："},{"i":31,"n":"第三十一条","txt":"出卖人履行交付义务后诉请买受人支付价款，买受人以出卖人违约在先为由提出异议的，人民法院应当按照下列情况分别处理："},{"i":32,"n":"第三十二条","txt":"法律或者行政法规对债权转让、股权转让等权利转让合同有规定的，依照其规定；没有规定的，人民法院可以根据民法典第四百六十七条和第六百四十六条的规定，参照适用买卖合同的有关规定。"},{"i":33,"n":"第三十三条","txt":"本解释施行前本院发布的有关购销合同、销售合同等有偿转移标的物所有权的合同的规定，与本解释抵触的，自本解释施行之日起不再适用。"}],"zuigaorenminfayuanguanyushenlijiaotongzhaoshixingse0e114":[{"i":1,"n":"第一条","txt":"从事交通运输人员或者非交通运输人员，违反交通运输管理法规发生重大交通事故，在分清事故责任的基础上，对于构成犯罪的，依照刑法第一百三十三条的规定定罪处罚。"},{"i":2,"n":"第二条","txt":"交通肇事具有下列情形之一的，处3年以下有期徒刑或者拘役："},{"i":3,"n":"第三条","txt":"“交通运输肇事后逃逸”，是指行为人具有本解释第二条第一款规定和第二款第（一）至（五）项规定的情形之一，在发生交通事故后，为逃避法律追究而逃跑的行为。"},{"i":4,"n":"第四条","txt":"交通肇事具有下列情形之一的，属于“有其他特别恶劣情节”，处3年以上7年以下有期徒刑："},{"i":5,"n":"第五条","txt":"“因逃逸致人死亡”，是指行为人在交通肇事后为逃避法律追究而逃跑，致使被害人因得不到救助而死亡的情形。"},{"i":6,"n":"第六条","txt":"行为人在交通肇事后为逃避法律追究，将被害人带离事故现场后隐藏或者遗弃，致使被害人无法得到救助而死亡或者严重残疾的，应当分别依照刑法第二百三十二条、第二百三十四条第二款的规定，以故意杀人罪或者故意伤害罪定罪处罚。"},{"i":7,"n":"第七条","txt":"单位主管人员、机动车辆所有人或者机动车辆承包人指使、强令他人违章驾驶造成重大交通事故，具有本解释第二条规定情形之一的，以交通肇事罪定罪处罚。"},{"i":8,"n":"第八条","txt":"在实行公共交通管理的范围内发生重大交通事故的，依照刑法第一百三十三条和本解释的有关规定办理。"},{"i":9,"n":"第九条","txt":"各省、自治区、直辖市高级人民法院可以根据本地实际情况，在30万元至60万元、60万元至100万元的幅度内，确定本地区执行本解释第二条第一款第（三）项、第四条第（三）项的起点数额标准，并报最高人民法院备案。"}],"zuigaorenminfayuanguanyushenlirenshensunhaipeichanf8a1f2":[{"i":1,"n":"第一条","txt":"因生命、身体、健康遭受侵害，赔偿权利人起诉请求赔偿义务人赔偿物质损害和精神损害的，人民法院应予受理。"},{"i":2,"n":"第二条","txt":"赔偿权利人起诉部分共同侵权人的，人民法院应当追加其他共同侵权人作为共同被告。赔偿权利人在诉讼中放弃对部分共同侵权人的诉讼请求的，其他共同侵权人对被放弃诉讼请求的被告应当承担的赔偿份额不承担连带责任。责任范围难以确定的，推定各共同侵权人承担同等责任。"},{"i":3,"n":"第三条","txt":"依法应当参加工伤保险统筹的用人单位的劳动者，因工伤事故遭受人身损害，劳动者或者其近亲属向人民法院起诉请求用人单位承担民事赔偿责任的，告知其按《工伤保险条例》的规定处理。"},{"i":4,"n":"第四条","txt":"无偿提供劳务的帮工人，在从事帮工活动中致人损害的，被帮工人应当承担赔偿责任。被帮工人承担赔偿责任后向有故意或者重大过失的帮工人追偿的，人民法院应予支持。被帮工人明确拒绝帮工的，不承担赔偿责任。"},{"i":5,"n":"第五条","txt":"无偿提供劳务的帮工人因帮工活动遭受人身损害的，根据帮工人和被帮工人各自的过错承担相应的责任；被帮工人明确拒绝帮工的，被帮工人不承担赔偿责任，但可以在受益范围内予以适当补偿。"},{"i":6,"n":"第六条","txt":"医疗费根据医疗机构出具的医药费、住院费等收款凭证，结合病历和诊断证明等相关证据确定。赔偿义务人对治疗的必要性和合理性有异议的，应当承担相应的举证责任。"},{"i":7,"n":"第七条","txt":"误工费根据受害人的误工时间和收入状况确定。"},{"i":8,"n":"第八条","txt":"护理费根据护理人员的收入状况和护理人数、护理期限确定。"},{"i":9,"n":"第九条","txt":"交通费根据受害人及其必要的陪护人员因就医或者转院治疗实际发生的费用计算。交通费应当以正式票据为凭；有关凭据应当与就医地点、时间、人数、次数相符合。"},{"i":10,"n":"第十条","txt":"住院伙食补助费可以参照当地国家机关一般工作人员的出差伙食补助标准予以确定。"},{"i":11,"n":"第十一条","txt":"营养费根据受害人伤残情况参照医疗机构的意见确定。"},{"i":12,"n":"第十二条","txt":"残疾赔偿金根据受害人丧失劳动能力程度或者伤残等级，按照受诉法院所在地上一年度城镇居民人均可支配收入标准，自定残之日起按二十年计算。但六十周岁以上的，年龄每增加一岁减少一年；七十五周岁以上的，按五年计算。"},{"i":13,"n":"第十三条","txt":"残疾辅助器具费按照普通适用器具的合理费用标准计算。伤情有特殊需要的，可以参照辅助器具配制机构的意见确定相应的合理费用标准。"},{"i":14,"n":"第十四条","txt":"丧葬费按照受诉法院所在地上一年度职工月平均工资标准，以六个月总额计算。"},{"i":15,"n":"第十五条","txt":"死亡赔偿金按照受诉法院所在地上一年度城镇居民人均可支配收入标准，按二十年计算。但六十周岁以上的，年龄每增加一岁减少一年；七十五周岁以上的，按五年计算。"},{"i":16,"n":"第十六条","txt":"被扶养人生活费计入残疾赔偿金或者死亡赔偿金。"},{"i":17,"n":"第十七条","txt":"被扶养人生活费根据扶养人丧失劳动能力程度，按照受诉法院所在地上一年度城镇居民人均消费支出标准计算。被扶养人为未成年人的，计算至十八周岁；被扶养人无劳动能力又无其他生活来源的，计算二十年。但六十周岁以上的，年龄每增加一岁减少一年；七十五周岁以上的，按五年计算。"},{"i":18,"n":"第十八条","txt":"赔偿权利人举证证明其住所地或者经常居住地城镇居民人均可支配收入高于受诉法院所在地标准的，残疾赔偿金或者死亡赔偿金可以按照其住所地或者经常居住地的相关标准计算。"},{"i":19,"n":"第十九条","txt":"超过确定的护理期限、辅助器具费给付年限或者残疾赔偿金给付年限，赔偿权利人向人民法院起诉请求继续给付护理费、辅助器具费或者残疾赔偿金的，人民法院应予受理。赔偿权利人确需继续护理、配制辅助器具，或者没有劳动能力和生活来源的，人民法院应当判令赔偿义务人继续给付相关费用五至十年。"},{"i":20,"n":"第二十条","txt":"赔偿义务人请求以定期金方式给付残疾赔偿金、辅助器具费的，应当提供相应的担保。人民法院可以根据赔偿义务人的给付能力和提供担保的情况，确定以定期金方式给付相关费用。但是，一审法庭辩论终结前已经发生的费用、死亡赔偿金以及精神损害抚慰金，应当一次性给付。"},{"i":21,"n":"第二十一条","txt":"人民法院应当在法律文书中明确定期金的给付时间、方式以及每期给付标准。执行期间有关统计数据发生变化的，给付金额应当适时进行相应调整。"},{"i":22,"n":"第二十二条","txt":"本解释所称“城镇居民人均可支配收入”“城镇居民人均消费支出”“职工平均工资”，按照政府统计部门公布的各省、自治区、直辖市以及经济特区和计划单列市上一年度相关统计数据确定。"},{"i":23,"n":"第二十三条","txt":"精神损害抚慰金适用《最高人民法院关于确定民事侵权精神损害赔偿责任若干问题的解释》予以确定。"},{"i":24,"n":"第二十四条","txt":"本解释自2022年5月1日起施行。施行后发生的侵权行为引起的人身损害赔偿案件适用本解释。"}],"zuigaorenminfayuanguanyushenliweizaohuobidenganjia354f0f":[{"i":1,"n":"第一条","txt":"伪造货币的总面额在2000元以上不满3万元或者币量在200张（枚）以上不足3000张（枚）的，依照刑法第一百七十条的规定，处3年以上10年以下有期徒刑，并处5万元以上50万元以下罚金。"},{"i":2,"n":"第二条","txt":"行为人购买假币后使用，构成犯罪的，依照刑法第一百七十一条的规定，以购买假币罪定罪，从重处罚。"},{"i":3,"n":"第三条","txt":"出售、购买假币或者明知是假币而运输，总面额在4000元以上不满5万元的，属于“数额较大”；总面额在5万元以上不满20万元的，属于“数额巨大”；总面额在20万元以上的，属于“数额特别巨大”，依照刑法第一百七十一条第一款的规定定罪处罚。"},{"i":4,"n":"第四条","txt":"银行或者其他金融机构的工作人员购买假币或者利用职务上的便利，以假币换取货币，总面额在4000元以上不满5万元或者币量在400张（枚）以上不足5000张（枚）的，处3年以上10年以下有期徒刑，并处2万元以上20万元以下罚金；总面额在5万元以上或者币量在5000张（枚）以上或者有其他严重情节的，处10年以上有期徒刑或者无期徒刑，并处2万元以上20万元以下罚金或者没收财产；总面额不满人民币4000元或者币量不足400张（枚）或者具有其他情节较轻情形的，处3年以下有期徒刑或者拘役，并处或者单处1万元以上10万元以下罚金。"},{"i":5,"n":"第五条","txt":"明知是假币而持有、使用，总面额在4000元以上不满5万元的，属于“数额较大”；总面额在5万元以上不满20万元的，属于“数额巨大”；总面额在20万元以上的，属于“数额特别巨大”，依照刑法第一百七十二条的规定定罪处罚。"},{"i":6,"n":"第六条","txt":"变造货币的总面额在2000元以上不满3万元的，属于“数额较大”；总面额在3万元以上的，属于“数额巨大”，依照刑法第一百七十三条的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"本解释所称“货币”是指可在国内市场流通或者兑换的人民币和境外货币。"}],"zuigaorenminfayuanguanyushenliweizaohuobidenganjiab623fd":[{"i":1,"n":"第一条","txt":"仿照真货币的图案、形状、色彩等特征非法制造假币，冒充真币的行为，应当认定为刑法第一百七十条规定的“伪造货币”。"},{"i":2,"n":"第二条","txt":"同时采用伪造和变造手段，制造真伪拼凑货币的行为，依照刑法第一百七十条的规定，以伪造货币罪定罪处罚。"},{"i":3,"n":"第三条","txt":"以正在流通的境外货币为对象的假币犯罪，依照刑法第一百七十条至第一百七十三条的规定定罪处罚。"},{"i":4,"n":"第四条","txt":"以中国人民银行发行的普通纪念币和贵金属纪念币为对象的假币犯罪，依照刑法第一百七十条至第一百七十三条的规定定罪处罚。"},{"i":5,"n":"第五条","txt":"以使用为目的，伪造停止流通的货币，或者使用伪造的停止流通的货币的，依照刑法第二百六十六条的规定，以诈骗罪定罪处罚。"},{"i":6,"n":"第六条","txt":"此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenliqinhaizhishichanquand0af46":[{"i":1,"n":"第一条","txt":"原告主张被告故意侵害其依法享有的知识产权且情节严重，请求判令被告承担惩罚性赔偿责任的，人民法院应当依法审理。"},{"i":2,"n":"第二条","txt":"原告请求惩罚性赔偿的，应当提出明确的赔偿数额、计算方法以及所依据的事实和理由。"},{"i":3,"n":"第三条","txt":"原告在一审法庭辩论终结前增加惩罚性赔偿请求的，人民法院应当准许。在二审中增加惩罚性赔偿请求的，人民法院可以根据当事人自愿原则进行调解，调解不成的，不予支持。"},{"i":4,"n":"第四条","txt":"原告在知识产权侵权诉讼中请求赔偿损失但未请求惩罚性赔偿，经人民法院释明仍未请求，诉讼终结后基于同一侵权事实另行起诉请求惩罚性赔偿的，人民法院不予受理。"},{"i":5,"n":"第五条","txt":"原告针对被告故意实施侵犯商业秘密以外的不正当竞争行为请求惩罚性赔偿的，人民法院不予支持，但法律另有规定的除外。"},{"i":6,"n":"第六条","txt":"对于侵害知识产权故意的认定，人民法院应当综合考虑知识产权客体的类型、权利状态和知名度，被告与原告或者利害关系人的关系等因素。"},{"i":7,"n":"第七条","txt":"对于侵害知识产权情节严重的认定，人民法院应当综合考虑侵权手段、次数，侵权行为的持续时间、地域范围、规模、后果，侵权人对其侵权行为的认识、基本态度等因素。"},{"i":8,"n":"第八条","txt":"人民法院确定惩罚性赔偿数额时，应当分别依照相关法律，以原告实际损失数额、被告违法所得数额或者因侵权所获得的利益作为计算基数。计算基数不包括原告为制止侵权所支付的合理开支。法律另有规定的，依照其规定。"},{"i":9,"n":"第九条","txt":"以被告的违法所得或者侵权获利作为惩罚性赔偿计算基数的，可以参照营业利润确定。被告以侵害知识产权为业的，可以参照销售利润计算。利润率无法确定的，可以参照统计部门、行业协会等公布的同时期、同行业的平均利润率或者权利人的利润率计算。"},{"i":10,"n":"第十条","txt":"人民法院依法责令被告提供其掌握的与侵权行为相关的账簿、资料等，被告无正当理由拒不提供或者提供虚假的账簿、资料等的，人民法院可以根据原告的主张和在案证据依法确定惩罚性赔偿数额的计算基数。构成民事诉讼法第一百一十四条规定情形的，依法追究法律责任。法律另有规定的，依照其规定。"},{"i":11,"n":"第十一条","txt":"人民法院确定惩罚性赔偿的倍数时，应当综合考虑被告主观过错程度、侵权行为的情节严重程度等因素。惩罚性赔偿的倍数在法定范围内确定，可以不是整数。"},{"i":12,"n":"第十二条","txt":"人民法院适用惩罚性赔偿确定的赔偿数额总额，最高为计算基数的五倍。权利人为制止侵权行为所支付的合理开支在该总额之外另行计算。"},{"i":13,"n":"第十三条","txt":"因同一侵权行为已经被处以罚款或者罚金且执行完毕的，人民法院在确定惩罚性赔偿的倍数时应予考虑。"},{"i":14,"n":"第十四条","txt":"本解释自2026年5月1日起施行。"}],"zuigaorenminfayuanguanyushenliqinfanzhuanliquanjiufa2007":[{"i":1,"n":"第一条","txt":"人民法院应当根据权利人主张的权利要求，依据专利法第五十九条第一款的规定确定专利权的保护范围。权利人在一审法庭辩论终结前变更其主张的权利要求的，人民法院应当准许。"},{"i":2,"n":"第二条","txt":"人民法院应当根据权利要求的记载，结合本领域普通技术人员阅读说明书及附图后对权利要求的理解，确定专利法第五十九条第一款规定的权利要求的内容。"},{"i":3,"n":"第三条","txt":"人民法院对于权利要求，可以运用说明书及附图、权利要求书中的相关权利要求、专利审查档案进行解释。说明书对权利要求用语有特别界定的，从其特别界定。"},{"i":4,"n":"第四条","txt":"对于权利要求中以功能或者效果表述的技术特征，人民法院应当结合说明书和附图描述的该功能或者效果的具体实施方式及其等同的实施方式，确定该技术特征的内容。"},{"i":5,"n":"第五条","txt":"对于仅在说明书或者附图中描述而在权利要求中未记载的技术方案，权利人在侵犯专利权纠纷案件中将其纳入专利权保护范围的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"专利申请人、专利权人在专利授权或者无效宣告程序中，通过对权利要求、说明书的修改或者意见陈述而放弃的技术方案，权利人在侵犯专利权纠纷案件中又将其纳入专利权保护范围的，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"人民法院判定被诉侵权技术方案是否落入专利权的保护范围，应当审查权利人主张的权利要求所记载的全部技术特征。"},{"i":8,"n":"第八条","txt":"在与外观设计专利产品相同或者相近种类产品上，采用与授权外观设计相同或者近似的外观设计的，人民法院应当认定被诉侵权设计落入专利法第五十九条第二款规定的外观设计专利权的保护范围。"},{"i":9,"n":"第九条","txt":"人民法院应当根据外观设计产品的用途，认定产品种类是否相同或者相近。确定产品的用途，可以参考外观设计的简要说明、国际外观设计分类表、产品的功能以及产品销售、实际使用的情况等因素。"},{"i":10,"n":"第十条","txt":"人民法院应当以外观设计专利产品的一般消费者的知识水平和认知能力，判断外观设计是否相同或者近似。"},{"i":11,"n":"第十一条","txt":"人民法院认定外观设计是否相同或者近似时，应当根据授权外观设计、被诉侵权设计的设计特征，以外观设计的整体视觉效果进行综合判断；对于主要由技术功能决定的设计特征以及对整体视觉效果不产生影响的产品的材料、内部结构等特征，应当不予考虑。"},{"i":12,"n":"第十二条","txt":"将侵犯发明或者实用新型专利权的产品作为零部件，制造另一产品的，人民法院应当认定属于专利法第十一条规定的使用行为；销售该另一产品的，人民法院应当认定属于专利法第十一条规定的销售行为。"},{"i":13,"n":"第十三条","txt":"对于使用专利方法获得的原始产品，人民法院应当认定为专利法第十一条规定的依照专利方法直接获得的产品。"},{"i":14,"n":"第十四条","txt":"被诉落入专利权保护范围的全部技术特征，与一项现有技术方案中的相应技术特征相同或者无实质性差异的，人民法院应当认定被诉侵权人实施的技术属于专利法第六十二条规定的现有技术。"},{"i":15,"n":"第十五条","txt":"被诉侵权人以非法获得的技术或者设计主张先用权抗辩的，人民法院不予支持。"},{"i":16,"n":"第十六条","txt":"人民法院依据专利法第六十五条第一款的规定确定侵权人因侵权所获得的利益，应当限于侵权人因侵犯专利权行为所获得的利益；因其他权利所产生的利益，应当合理扣除。"},{"i":17,"n":"第十七条","txt":"产品或者制造产品的技术方案在专利申请日以前为国内外公众所知的，人民法院应当认定该产品不属于专利法第六十一条第一款规定的新产品。"},{"i":18,"n":"第十八条","txt":"权利人向他人发出侵犯专利权的警告，被警告人或者利害关系人经书面催告权利人行使诉权，自权利人收到该书面催告之日起一个月内或者自书面催告发出之日起二个月内，权利人不撤回警告也不提起诉讼，被警告人或者利害关系人向人民法院提起请求确认其行为不侵犯专利权的诉讼的，人民法院应当受理。"},{"i":19,"n":"第十九条","txt":"被诉侵犯专利权行为发生在2009年10月1日以前的，人民法院适用修改前的专利法；发生在2009年10月1日以后的，人民法院适用修改后的专利法。"},{"i":20,"n":"第二十条","txt":"本院以前发布的有关司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenliqinfanzhuanliquanjiuc4945b":[{"i":1,"n":"第一条","txt":"权利要求书有两项以上权利要求的，权利人应当在起诉状中载明据以起诉被诉侵权人侵犯其专利权的权利要求。起诉状对此未记载或者记载不明的，人民法院应当要求权利人明确。经释明，权利人仍不予明确的，人民法院可以裁定驳回起诉。"},{"i":2,"n":"第二条","txt":"权利人在专利侵权诉讼中主张的权利要求被国务院专利行政部门宣告无效的，审理侵犯专利权纠纷案件的人民法院可以裁定驳回权利人基于该无效权利要求的起诉。"},{"i":3,"n":"第三条","txt":"因明显违反专利法第二十六条第三款、第四款导致说明书无法用于解释权利要求，且不属于本解释第四条规定的情形，专利权因此被请求宣告无效的，审理侵犯专利权纠纷案件的人民法院一般应当裁定中止诉讼；在合理期限内专利权未被请求宣告无效的，人民法院可以根据权利要求的记载确定专利权的保护范围。"},{"i":4,"n":"第四条","txt":"权利要求书、说明书及附图中的语法、文字、标点、图形、符号等存有歧义，但本领域普通技术人员通过阅读权利要求书、说明书及附图可以得出唯一理解的，人民法院应当根据该唯一理解予以认定。"},{"i":5,"n":"第五条","txt":"在人民法院确定专利权的保护范围时，独立权利要求的前序部分、特征部分以及从属权利要求的引用部分、限定部分记载的技术特征均有限定作用。"},{"i":6,"n":"第六条","txt":"人民法院可以运用与涉案专利存在分案申请关系的其他专利及其专利审查档案、生效的专利授权确权裁判文书解释涉案专利的权利要求。"},{"i":7,"n":"第七条","txt":"被诉侵权技术方案在包含封闭式组合物权利要求全部技术特征的基础上增加其他技术特征的，人民法院应当认定被诉侵权技术方案未落入专利权的保护范围，但该增加的技术特征属于不可避免的常规数量杂质的除外。"},{"i":8,"n":"第八条","txt":"功能性特征，是指对于结构、组分、步骤、条件或其之间的关系等，通过其在发明创造中所起的功能或者效果进行限定的技术特征，但本领域普通技术人员仅通过阅读权利要求即可直接、明确地确定实现上述功能或者效果的具体实施方式的除外。"},{"i":9,"n":"第九条","txt":"被诉侵权技术方案不能适用于权利要求中使用环境特征所限定的使用环境的，人民法院应当认定被诉侵权技术方案未落入专利权的保护范围。"},{"i":10,"n":"第十条","txt":"对于权利要求中以制备方法界定产品的技术特征，被诉侵权产品的制备方法与其不相同也不等同的，人民法院应当认定被诉侵权技术方案未落入专利权的保护范围。"},{"i":11,"n":"第十一条","txt":"方法权利要求未明确记载技术步骤的先后顺序，但本领域普通技术人员阅读权利要求书、说明书及附图后直接、明确地认为该技术步骤应当按照特定顺序实施的，人民法院应当认定该步骤顺序对于专利权的保护范围具有限定作用。"},{"i":12,"n":"第十二条","txt":"权利要求采用“至少”“不超过”等用语对数值特征进行界定，且本领域普通技术人员阅读权利要求书、说明书及附图后认为专利技术方案特别强调该用语对技术特征的限定作用，权利人主张与其不相同的数值特征属于等同特征的，人民法院不予支持。"},{"i":13,"n":"第十三条","txt":"权利人证明专利申请人、专利权人在专利授权确权程序中对权利要求书、说明书及附图的限缩性修改或者陈述被明确否定的，人民法院应当认定该修改或者陈述未导致技术方案的放弃。"},{"i":14,"n":"第十四条","txt":"人民法院在认定一般消费者对于外观设计所具有的知识水平和认知能力时，一般应当考虑被诉侵权行为发生时授权外观设计所属相同或者相近种类产品的设计空间。设计空间较大的，人民法院可以认定一般消费者通常不容易注意到不同设计之间的较小区别；设计空间较小的，人民法院可以认定一般消费者通常更容易注意到不同设计之间的较小区别。"},{"i":15,"n":"第十五条","txt":"对于成套产品的外观设计专利，被诉侵权设计与其一项外观设计相同或者近似的，人民法院应当认定被诉侵权设计落入专利权的保护范围。"},{"i":16,"n":"第十六条","txt":"对于组装关系唯一的组件产品的外观设计专利，被诉侵权设计与其组合状态下的外观设计相同或者近似的，人民法院应当认定被诉侵权设计落入专利权的保护范围。"},{"i":17,"n":"第十七条","txt":"对于变化状态产品的外观设计专利，被诉侵权设计与变化状态图所示各种使用状态下的外观设计均相同或者近似的，人民法院应当认定被诉侵权设计落入专利权的保护范围；被诉侵权设计缺少其一种使用状态下的外观设计或者与之不相同也不近似的，人民法院应当认定被诉侵权设计未落入专利权的保护范围。"},{"i":18,"n":"第十八条","txt":"权利人依据专利法第十三条诉请在发明专利申请公布日至授权公告日期间实施该发明的单位或者个人支付适当费用的，人民法院可以参照有关专利许可使用费合理确定。"},{"i":19,"n":"第十九条","txt":"产品买卖合同依法成立的，人民法院应当认定属于专利法第十一条规定的销售。"},{"i":20,"n":"第二十条","txt":"对于将依照专利方法直接获得的产品进一步加工、处理而获得的后续产品，进行再加工、处理的，人民法院应当认定不属于专利法第十一条规定的“使用依照该专利方法直接获得的产品”。"},{"i":21,"n":"第二十一条","txt":"明知有关产品系专门用于实施专利的材料、设备、零部件、中间物等，未经专利权人许可，为生产经营目的将该产品提供给他人实施了侵犯专利权的行为，权利人主张该提供者的行为属于民法典第一千一百六十九条规定的帮助他人实施侵权行为的，人民法院应予支持。"},{"i":22,"n":"第二十二条","txt":"对于被诉侵权人主张的现有技术抗辩或者现有设计抗辩，人民法院应当依照专利申请日时施行的专利法界定现有技术或者现有设计。"},{"i":23,"n":"第二十三条","txt":"被诉侵权技术方案或者外观设计落入在先的涉案专利权的保护范围，被诉侵权人以其技术方案或者外观设计被授予专利权为由抗辩不侵犯涉案专利权的，人民法院不予支持。"},{"i":24,"n":"第二十四条","txt":"推荐性国家、行业或者地方标准明示所涉必要专利的信息，被诉侵权人以实施该标准无需专利权人许可为由抗辩不侵犯该专利权的，人民法院一般不予支持。"},{"i":25,"n":"第二十五条","txt":"为生产经营目的使用、许诺销售或者销售不知道是未经专利权人许可而制造并售出的专利侵权产品，且举证证明该产品合法来源的，对于权利人请求停止上述使用、许诺销售、销售行为的主张，人民法院应予支持，但被诉侵权产品的使用者举证证明其已支付该产品的合理对价的除外。"},{"i":26,"n":"第二十六条","txt":"被告构成对专利权的侵犯，权利人请求判令其停止侵权行为的，人民法院应予支持，但基于国家利益、公共利益的考量，人民法院可以不判令被告停止被诉行为，而判令其支付相应的合理费用。"},{"i":27,"n":"第二十七条","txt":"权利人因被侵权所受到的实际损失难以确定的，人民法院应当依照专利法第六十五条第一款的规定，要求权利人对侵权人因侵权所获得的利益进行举证；在权利人已经提供侵权人所获利益的初步证据，而与专利侵权行为相关的账簿、资料主要由侵权人掌握的情况下，人民法院可以责令侵权人提供该账簿、资料；侵权人无正当理由拒不提供或者提供虚假的账簿、资料的，人民法院可以根据权利人的主张和提供的证据认定侵权人因侵权所获得的利益。"},{"i":28,"n":"第二十八条","txt":"权利人、侵权人依法约定专利侵权的赔偿数额或者赔偿计算方法，并在专利侵权诉讼中主张依据该约定确定赔偿数额的，人民法院应予支持。"},{"i":29,"n":"第二十九条","txt":"宣告专利权无效的决定作出后，当事人根据该决定依法申请再审，请求撤销专利权无效宣告前人民法院作出但未执行的专利侵权的判决、调解书的，人民法院可以裁定中止再审审查，并中止原判决、调解书的执行。"},{"i":30,"n":"第三十条","txt":"在法定期限内对宣告专利权无效的决定不向人民法院起诉或者起诉后生效裁判未撤销该决定，当事人根据该决定依法申请再审，请求撤销宣告专利权无效前人民法院作出但未执行的专利侵权的判决、调解书的，人民法院应当再审。当事人根据该决定，依法申请终结执行宣告专利权无效前人民法院作出但未执行的专利侵权的判决、调解书的，人民法院应当裁定终结执行。"},{"i":31,"n":"第三十一条","txt":"本解释自2016年4月1日起施行。最高人民法院以前发布的相关司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlidaomaichepiaoxingshice9270":[{"i":1,"n":"第一条","txt":"高价、变相加价倒卖车票或者倒卖坐席、卧铺签字号及订购车票凭证，票面数额在5000元以上，或者非法获利数额在2000元以上的，构成刑法第二百二十七条第二款规定的“倒卖车票情节严重”。"},{"i":2,"n":"第二条","txt":"对于铁路职工倒卖车票或者与其他人员勾结倒卖车票；组织倒卖车票的首要分子；曾因倒卖车票受过治安处罚两次以上或者被劳动教养一次以上，两年内又倒卖车票，构成倒卖车票罪的，依法从重处罚。"}],"zuigaorenminfayuanguanyushenlilaodongzhengyianjian147101":[{"i":1,"n":"第一条","txt":"劳动者与用人单位之间发生的下列纠纷，属于劳动争议，当事人不服劳动争议仲裁机构作出的裁决，依法提起诉讼的，人民法院应予受理："},{"i":2,"n":"第二条","txt":"下列纠纷不属于劳动争议："},{"i":3,"n":"第三条","txt":"劳动争议案件由用人单位所在地或者劳动合同履行地的基层人民法院管辖。"},{"i":4,"n":"第四条","txt":"劳动者与用人单位均不服劳动争议仲裁机构的同一裁决，向同一人民法院起诉的，人民法院应当并案审理，双方当事人互为原告和被告，对双方的诉讼请求，人民法院应当一并作出裁决。在诉讼过程中，一方当事人撤诉的，人民法院应当根据另一方当事人的诉讼请求继续审理。双方当事人就同一仲裁裁决分别向有管辖权的人民法院起诉的，后受理的人民法院应当将案件移送给先受理的人民法院。"},{"i":5,"n":"第五条","txt":"劳动争议仲裁机构以无管辖权为由对劳动争议案件不予受理，当事人提起诉讼的，人民法院按照以下情形分别处理："},{"i":6,"n":"第六条","txt":"劳动争议仲裁机构以当事人申请仲裁的事项不属于劳动争议为由，作出不予受理的书面裁决、决定或者通知，当事人不服依法提起诉讼的，人民法院应当分别情况予以处理："},{"i":7,"n":"第七条","txt":"劳动争议仲裁机构以申请仲裁的主体不适格为由，作出不予受理的书面裁决、决定或者通知，当事人不服依法提起诉讼，经审查确属主体不适格的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":8,"n":"第八条","txt":"劳动争议仲裁机构为纠正原仲裁裁决错误重新作出裁决，当事人不服依法提起诉讼的，人民法院应当受理。"},{"i":9,"n":"第九条","txt":"劳动争议仲裁机构仲裁的事项不属于人民法院受理的案件范围，当事人不服依法提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":10,"n":"第十条","txt":"当事人不服劳动争议仲裁机构作出的预先支付劳动者劳动报酬、工伤医疗费、经济补偿或者赔偿金的裁决，依法提起诉讼的，人民法院不予受理。"},{"i":11,"n":"第十一条","txt":"劳动争议仲裁机构作出的调解书已经发生法律效力，一方当事人反悔提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":12,"n":"第十二条","txt":"劳动争议仲裁机构逾期未作出受理决定或仲裁裁决，当事人直接提起诉讼的，人民法院应予受理，但申请仲裁的案件存在下列事由的除外："},{"i":13,"n":"第十三条","txt":"劳动者依据劳动合同法第三十条第二款和调解仲裁法第十六条规定向人民法院申请支付令，符合民事诉讼法第十七章督促程序规定的，人民法院应予受理。"},{"i":14,"n":"第十四条","txt":"人民法院受理劳动争议案件后，当事人增加诉讼请求的，如该诉讼请求与讼争的劳动争议具有不可分性，应当合并审理；如属独立的劳动争议，应当告知当事人向劳动争议仲裁机构申请仲裁。"},{"i":15,"n":"第十五条","txt":"劳动者以用人单位的工资欠条为证据直接提起诉讼，诉讼请求不涉及劳动关系其他争议的，视为拖欠劳动报酬争议，人民法院按照普通民事纠纷受理。"},{"i":16,"n":"第十六条","txt":"劳动争议仲裁机构作出仲裁裁决后，当事人对裁决中的部分事项不服，依法提起诉讼的，劳动争议仲裁裁决不发生法律效力。"},{"i":17,"n":"第十七条","txt":"劳动争议仲裁机构对多个劳动者的劳动争议作出仲裁裁决后，部分劳动者对仲裁裁决不服，依法提起诉讼的，仲裁裁决对提起诉讼的劳动者不发生法律效力；对未提起诉讼的部分劳动者，发生法律效力，如其申请执行的，人民法院应当受理。"},{"i":18,"n":"第十八条","txt":"仲裁裁决的类型以仲裁裁决书确定为准。仲裁裁决书未载明该裁决为终局裁决或者非终局裁决，用人单位不服该仲裁裁决向基层人民法院提起诉讼的，应当按照以下情形分别处理："},{"i":19,"n":"第十九条","txt":"仲裁裁决书未载明该裁决为终局裁决或者非终局裁决，劳动者依据调解仲裁法第四十七条第一项规定，追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，如果仲裁裁决涉及数项，每项确定的数额均不超过当地月最低工资标准十二个月金额的，应当按照终局裁决处理。"},{"i":20,"n":"第二十条","txt":"劳动争议仲裁机构作出的同一仲裁裁决同时包含终局裁决事项和非终局裁决事项，当事人不服该仲裁裁决向人民法院提起诉讼的，应当按照非终局裁决处理。"},{"i":21,"n":"第二十一条","txt":"劳动者依据调解仲裁法第四十八条规定向基层人民法院提起诉讼，用人单位依据调解仲裁法第四十九条规定向劳动争议仲裁机构所在地的中级人民法院申请撤销仲裁裁决的，中级人民法院应当不予受理；已经受理的，应当裁定驳回申请。"},{"i":22,"n":"第二十二条","txt":"用人单位依据调解仲裁法第四十九条规定向中级人民法院申请撤销仲裁裁决，中级人民法院作出的驳回申请或者撤销仲裁裁决的裁定为终审裁定。"},{"i":23,"n":"第二十三条","txt":"中级人民法院审理用人单位申请撤销终局裁决的案件，应当组成合议庭开庭审理。经过阅卷、调查和询问当事人，对没有新的事实、证据或者理由，合议庭认为不需要开庭审理的，可以不开庭审理。"},{"i":24,"n":"第二十四条","txt":"当事人申请人民法院执行劳动争议仲裁机构作出的发生法律效力的裁决书、调解书，被申请人提出证据证明劳动争议仲裁裁决书、调解书有下列情形之一，并经审查核实的，人民法院可以根据民事诉讼法第二百三十七条规定，裁定不予执行："},{"i":25,"n":"第二十五条","txt":"劳动争议仲裁机构作出终局裁决，劳动者向人民法院申请执行，用人单位向劳动争议仲裁机构所在地的中级人民法院申请撤销的，人民法院应当裁定中止执行。"},{"i":26,"n":"第二十六条","txt":"用人单位与其它单位合并的，合并前发生的劳动争议，由合并后的单位为当事人；用人单位分立为若干单位的，其分立前发生的劳动争议，由分立后的实际用人单位为当事人。"},{"i":27,"n":"第二十七条","txt":"用人单位招用尚未解除劳动合同的劳动者，原用人单位与劳动者发生的劳动争议，可以列新的用人单位为第三人。"},{"i":28,"n":"第二十八条","txt":"劳动者在用人单位与其他平等主体之间的承包经营期间，与发包方和承包方双方或者一方发生劳动争议，依法提起诉讼的，应当将承包方和发包方作为当事人。"},{"i":29,"n":"第二十九条","txt":"劳动者与未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位发生争议的，应当将用人单位或者其出资人列为当事人。"},{"i":30,"n":"第三十条","txt":"未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位，以挂靠等方式借用他人营业执照经营的，应当将用人单位和营业执照出借方列为当事人。"},{"i":31,"n":"第三十一条","txt":"当事人不服劳动争议仲裁机构作出的仲裁裁决，依法提起诉讼，人民法院审查认为仲裁裁决遗漏了必须共同参加仲裁的当事人的，应当依法追加遗漏的人为诉讼当事人。"},{"i":32,"n":"第三十二条","txt":"用人单位与其招用的已经依法享受养老保险待遇或者领取退休金的人员发生用工争议而提起诉讼的，人民法院应当按劳务关系处理。"},{"i":33,"n":"第三十三条","txt":"外国人、无国籍人未依法取得就业证件即与中华人民共和国境内的用人单位签订劳动合同，当事人请求确认与用人单位存在劳动关系的，人民法院不予支持。"},{"i":34,"n":"第三十四条","txt":"劳动合同期满后，劳动者仍在原用人单位工作，原用人单位未表示异议的，视为双方同意以原条件继续履行劳动合同。一方提出终止劳动关系的，人民法院应予支持。"},{"i":35,"n":"第三十五条","txt":"劳动者与用人单位就解除或者终止劳动合同办理相关手续、支付工资报酬、加班费、经济补偿或者赔偿金等达成的协议，不违反法律、行政法规的强制性规定，且不存在欺诈、胁迫或者乘人之危情形的，应当认定有效。"},{"i":36,"n":"第三十六条","txt":"当事人在劳动合同或者保密协议中约定了竞业限制，但未约定解除或者终止劳动合同后给予劳动者经济补偿，劳动者履行了竞业限制义务，要求用人单位按照劳动者在劳动合同解除或者终止前十二个月平均工资的30%按月支付经济补偿的，人民法院应予支持。"},{"i":37,"n":"第三十七条","txt":"当事人在劳动合同或者保密协议中约定了竞业限制和经济补偿，当事人解除劳动合同时，除另有约定外，用人单位要求劳动者履行竞业限制义务，或者劳动者履行了竞业限制义务后要求用人单位支付经济补偿的，人民法院应予支持。"},{"i":38,"n":"第三十八条","txt":"当事人在劳动合同或者保密协议中约定了竞业限制和经济补偿，劳动合同解除或者终止后，因用人单位的原因导致三个月未支付经济补偿，劳动者请求解除竞业限制约定的，人民法院应予支持。"},{"i":39,"n":"第三十九条","txt":"在竞业限制期限内，用人单位请求解除竞业限制协议的，人民法院应予支持。"},{"i":40,"n":"第四十条","txt":"劳动者违反竞业限制约定，向用人单位支付违约金后，用人单位要求劳动者按照约定继续履行竞业限制义务的，人民法院应予支持。"},{"i":41,"n":"第四十一条","txt":"劳动合同被确认为无效，劳动者已付出劳动的，用人单位应当按照劳动合同法第二十八条、第四十六条、第四十七条的规定向劳动者支付劳动报酬和经济补偿。"},{"i":42,"n":"第四十二条","txt":"劳动者主张加班费的，应当就加班事实的存在承担举证责任。但劳动者有证据证明用人单位掌握加班事实存在的证据，用人单位不提供的，由用人单位承担不利后果。"},{"i":43,"n":"第四十三条","txt":"用人单位与劳动者协商一致变更劳动合同，虽未采用书面形式，但已经实际履行了口头变更的劳动合同超过一个月，变更后的劳动合同内容不违反法律、行政法规且不违背公序良俗，当事人以未采用书面形式为由主张劳动合同变更无效的，人民法院不予支持。"},{"i":44,"n":"第四十四条","txt":"因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。"},{"i":45,"n":"第四十五条","txt":"用人单位有下列情形之一，迫使劳动者提出解除劳动合同的，用人单位应当支付劳动者的劳动报酬和经济补偿，并可支付赔偿金："},{"i":46,"n":"第四十六条","txt":"劳动者非因本人原因从原用人单位被安排到新用人单位工作，原用人单位未支付经济补偿，劳动者依据劳动合同法第三十八条规定与新用人单位解除劳动合同，或者新用人单位向劳动者提出解除、终止劳动合同，在计算支付经济补偿或赔偿金的工作年限时，劳动者请求把在原用人单位的工作年限合并计算为新用人单位工作年限的，人民法院应予支持。"},{"i":47,"n":"第四十七条","txt":"建立了工会组织的用人单位解除劳动合同符合劳动合同法第三十九条、第四十条规定，但未按照劳动合同法第四十三条规定事先通知工会，劳动者以用人单位违法解除劳动合同为由请求用人单位支付赔偿金的，人民法院应予支持，但起诉前用人单位已经补正有关程序的除外。"},{"i":48,"n":"第四十八条","txt":"劳动合同法施行后，因用人单位经营期限届满不再继续经营导致劳动合同不能继续履行，劳动者请求用人单位支付经济补偿的，人民法院应予支持。"},{"i":49,"n":"第四十九条","txt":"在诉讼过程中，劳动者向人民法院申请采取财产保全措施，人民法院经审查认为申请人经济确有困难，或者有证据证明用人单位存在欠薪逃匿可能的，应当减轻或者免除劳动者提供担保的义务，及时采取保全措施。"},{"i":50,"n":"第五十条","txt":"用人单位根据劳动合同法第四条规定，通过民主程序制定的规章制度，不违反国家法律、行政法规及政策规定，并已向劳动者公示的，可以作为确定双方权利义务的依据。"},{"i":51,"n":"第五十一条","txt":"当事人在调解仲裁法第十条规定的调解组织主持下达成的具有劳动权利义务内容的调解协议，具有劳动合同的约束力，可以作为人民法院裁判的根据。"},{"i":52,"n":"第五十二条","txt":"当事人在人民调解委员会主持下仅就给付义务达成的调解协议，双方认为有必要的，可以共同向人民调解委员会所在地的基层人民法院申请司法确认。"},{"i":53,"n":"第五十三条","txt":"用人单位对劳动者作出的开除、除名、辞退等处理，或者因其他原因解除劳动合同确有错误的，人民法院可以依法判决予以撤销。"},{"i":54,"n":"第五十四条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlilaodongzhengyianjian89a384":[{"i":1,"n":"第一条","txt":"具备合法经营资格的承包人将承包业务转包或者分包给不具备合法经营资格的组织或者个人，该组织或者个人招用的劳动者请求确认承包人为承担用工主体责任单位，承担支付劳动报酬、认定工伤后的工伤保险待遇等责任的，人民法院依法予以支持。"},{"i":2,"n":"第二条","txt":"不具备合法经营资格的组织或者个人挂靠具备合法经营资格的单位对外经营，该组织或者个人招用的劳动者请求确认被挂靠单位为承担用工主体责任单位，承担支付劳动报酬、认定工伤后的工伤保险待遇等责任的，人民法院依法予以支持。"},{"i":3,"n":"第三条","txt":"劳动者被多个存在关联关系的单位交替或者同时用工，其请求确认劳动关系的，人民法院按照下列情形分别处理："},{"i":4,"n":"第四条","txt":"外国人与中华人民共和国境内的用人单位建立用工关系，有下列情形之一，外国人请求确认与用人单位存在劳动关系的，人民法院依法予以支持："},{"i":5,"n":"第五条","txt":"依法设立的外国企业常驻代表机构可以作为劳动争议案件的当事人。当事人申请追加外国企业参加诉讼的，人民法院依法予以支持。"},{"i":6,"n":"第六条","txt":"用人单位未依法与劳动者订立书面劳动合同，应当支付劳动者的二倍工资按月计算；不满一个月的，按该月实际工作日计算。"},{"i":7,"n":"第七条","txt":"劳动者以用人单位未订立书面劳动合同为由，请求用人单位支付二倍工资的，人民法院依法予以支持，但用人单位举证证明存在下列情形之一的除外："},{"i":8,"n":"第八条","txt":"劳动合同期满，有下列情形之一的，人民法院认定劳动合同期限依法自动续延，不属于用人单位未订立书面劳动合同的情形："},{"i":9,"n":"第九条","txt":"有证据证明存在劳动合同法第十四条第三款规定的“视为用人单位与劳动者已订立无固定期限劳动合同”情形，劳动者请求与用人单位订立书面劳动合同的，人民法院依法予以支持；劳动者以用人单位未及时补订书面劳动合同为由，请求用人单位支付视为已与劳动者订立无固定期限劳动合同期间二倍工资的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，人民法院应认定为符合劳动合同法第十四条第二款第三项“连续订立二次固定期限劳动合同”的规定："},{"i":11,"n":"第十一条","txt":"劳动合同期满后，劳动者仍在用人单位工作，用人单位未表示异议超过一个月，劳动者请求用人单位以原条件续订劳动合同的，人民法院依法予以支持。"},{"i":12,"n":"第十二条","txt":"除向劳动者支付正常劳动报酬外，用人单位与劳动者约定服务期限并提供特殊待遇，劳动者违反约定提前解除劳动合同且不符合劳动合同法第三十八条规定的单方解除劳动合同情形时，用人单位请求劳动者承担赔偿损失责任的，人民法院可以综合考虑实际损失、当事人的过错程度、已经履行的年限等因素确定劳动者应当承担的赔偿责任。"},{"i":13,"n":"第十三条","txt":"劳动者未知悉、接触用人单位的商业秘密和与知识产权相关的保密事项，劳动者请求确认竞业限制条款不生效的，人民法院依法予以支持。"},{"i":14,"n":"第十四条","txt":"用人单位与高级管理人员、高级技术人员和其他负有保密义务的人员约定在职期间竞业限制条款，劳动者以不得约定在职期间竞业限制、未支付经济补偿为由请求确认竞业限制条款无效的，人民法院不予支持。"},{"i":15,"n":"第十五条","txt":"劳动者违反有效的竞业限制约定，用人单位请求劳动者按照约定返还已经支付的经济补偿并支付违约金的，人民法院依法予以支持。"},{"i":16,"n":"第十六条","txt":"用人单位违法解除或者终止劳动合同后，有下列情形之一的，人民法院可以认定为劳动合同法第四十八条规定的“劳动合同已经不能继续履行”："},{"i":17,"n":"第十七条","txt":"用人单位未按照国务院安全生产监督管理部门、卫生行政部门的规定组织从事接触职业病危害作业的劳动者进行离岗前的职业健康检查，劳动者在双方解除劳动合同后请求继续履行劳动合同的，人民法院依法予以支持，但有下列情形之一的除外："},{"i":18,"n":"第十八条","txt":"用人单位违法解除、终止可以继续履行的劳动合同，劳动者请求用人单位支付违法解除、终止决定作出后至劳动合同继续履行前一日工资的，用人单位应当按照劳动者提供正常劳动时的工资标准向劳动者支付上述期间的工资。"},{"i":19,"n":"第十九条","txt":"用人单位与劳动者约定或者劳动者向用人单位承诺无需缴纳社会保险费的，人民法院应当认定该约定或者承诺无效。用人单位未依法缴纳社会保险费，劳动者根据劳动合同法第三十八条第一款第三项规定请求解除劳动合同、由用人单位支付经济补偿的，人民法院依法予以支持。"},{"i":20,"n":"第二十条","txt":"当事人在仲裁期间因自身原因未提出仲裁时效抗辩，在一审或者二审诉讼期间提出仲裁时效抗辩的，人民法院不予支持。当事人基于新的证据能够证明对方当事人请求权的仲裁时效期间届满的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"本解释自2025年9月1日起施行。《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》（法释〔2020〕26号）第三十二条第一款同时废止。最高人民法院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenliyiliaosunhaizerenjiu58a1ee":[{"i":1,"n":"第一条","txt":"患者以在诊疗活动中受到人身或者财产损害为由请求医疗机构，医疗产品的生产者、销售者、药品上市许可持有人或者血液提供机构承担侵权责任的案件，适用本解释。"},{"i":2,"n":"第二条","txt":"患者因同一伤病在多个医疗机构接受诊疗受到损害，起诉部分或者全部就诊的医疗机构的，应予受理。"},{"i":3,"n":"第三条","txt":"患者因缺陷医疗产品受到损害，起诉部分或者全部医疗产品的生产者、销售者、药品上市许可持有人和医疗机构的，应予受理。"},{"i":4,"n":"第四条","txt":"患者依据民法典第一千二百一十八条规定主张医疗机构承担赔偿责任的，应当提交到该医疗机构就诊、受到损害的证据。"},{"i":5,"n":"第五条","txt":"患者依据民法典第一千二百一十九条规定主张医疗机构承担赔偿责任的，应当按照前条第一款规定提交证据。"},{"i":6,"n":"第六条","txt":"民法典第一千二百二十二条规定的病历资料包括医疗机构保管的门诊病历、住院志、体温单、医嘱单、检验报告、医学影像检查资料、特殊检查（治疗）同意书、手术同意书、手术及麻醉记录、病理资料、护理记录、出院记录以及国务院卫生行政主管部门规定的其他病历资料。"},{"i":7,"n":"第七条","txt":"患者依据民法典第一千二百二十三条规定请求赔偿的，应当提交使用医疗产品或者输入血液、受到损害的证据。"},{"i":8,"n":"第八条","txt":"当事人依法申请对医疗损害责任纠纷中的专门性问题进行鉴定的，人民法院应予准许。"},{"i":9,"n":"第九条","txt":"当事人申请医疗损害鉴定的，由双方当事人协商确定鉴定人。"},{"i":10,"n":"第十条","txt":"委托医疗损害鉴定的，当事人应当按照要求提交真实、完整、充分的鉴定材料。提交的鉴定材料不符合要求的，人民法院应当通知当事人更换或者补充相应材料。"},{"i":11,"n":"第十一条","txt":"委托鉴定书，应当有明确的鉴定事项和鉴定要求。鉴定人应当按照委托鉴定的事项和要求进行鉴定。"},{"i":12,"n":"第十二条","txt":"鉴定意见可以按照导致患者损害的全部原因、主要原因、同等原因、次要原因、轻微原因或者与患者损害无因果关系，表述诊疗行为或者医疗产品等造成患者损害的原因力大小。"},{"i":13,"n":"第十三条","txt":"鉴定意见应当经当事人质证。"},{"i":14,"n":"第十四条","txt":"当事人申请通知一至二名具有医学专门知识的人出庭，对鉴定意见或者案件的其他专门性事实问题提出意见，人民法院准许的，应当通知具有医学专门知识的人出庭。"},{"i":15,"n":"第十五条","txt":"当事人自行委托鉴定人作出的医疗损害鉴定意见，其他当事人认可的，可予采信。"},{"i":16,"n":"第十六条","txt":"对医疗机构或者其医务人员的过错，应当依据法律、行政法规、规章以及其他有关诊疗规范进行认定，可以综合考虑患者病情的紧急程度、患者个体差异、当地的医疗水平、医疗机构与医务人员资质等因素。"},{"i":17,"n":"第十七条","txt":"医务人员违反民法典第一千二百一十九条第一款规定义务，但未造成患者人身损害，患者请求医疗机构承担损害赔偿责任的，不予支持。"},{"i":18,"n":"第十八条","txt":"因抢救生命垂危的患者等紧急情况且不能取得患者意见时，下列情形可以认定为民法典第一千二百二十条规定的不能取得患者近亲属意见："},{"i":19,"n":"第十九条","txt":"两个以上医疗机构的诊疗行为造成患者同一损害，患者请求医疗机构承担赔偿责任的，应当区分不同情况，依照民法典第一千一百六十八条、第一千一百七十一条或者第一千一百七十二条的规定，确定各医疗机构承担的赔偿责任。"},{"i":20,"n":"第二十条","txt":"医疗机构邀请本单位以外的医务人员对患者进行诊疗，因受邀医务人员的过错造成患者损害的，由邀请医疗机构承担赔偿责任。"},{"i":21,"n":"第二十一条","txt":"因医疗产品的缺陷或者输入不合格血液受到损害，患者请求医疗机构，缺陷医疗产品的生产者、销售者、药品上市许可持有人或者血液提供机构承担赔偿责任的，应予支持。"},{"i":22,"n":"第二十二条","txt":"缺陷医疗产品与医疗机构的过错诊疗行为共同造成患者同一损害，患者请求医疗机构与医疗产品的生产者、销售者、药品上市许可持有人承担连带责任的，应予支持。"},{"i":23,"n":"第二十三条","txt":"医疗产品的生产者、销售者、药品上市许可持有人明知医疗产品存在缺陷仍然生产、销售，造成患者死亡或者健康严重损害，被侵权人请求生产者、销售者、药品上市许可持有人赔偿损失及二倍以下惩罚性赔偿的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"被侵权人同时起诉两个以上医疗机构承担赔偿责任，人民法院经审理，受诉法院所在地的医疗机构依法不承担赔偿责任，其他医疗机构承担赔偿责任的，残疾赔偿金、死亡赔偿金的计算，按下列情形分别处理："},{"i":25,"n":"第二十五条","txt":"患者死亡后，其近亲属请求医疗损害赔偿的，适用本解释；支付患者医疗费、丧葬费等合理费用的人请求赔偿该费用的，适用本解释。"},{"i":26,"n":"第二十六条","txt":"本院以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlidanweifanzuianjianjuf38f45":[{"i":1,"n":"第一条","txt":"刑法第三十条规定的“公司、企业、事业单位”，既包括国有、集体所有的公司、企业、事业单位，也包括依法设立的合资经营、合作经营企业和具有法人资格的独资、私营等公司、企业、事业单位。"},{"i":2,"n":"第二条","txt":"个人为进行违法犯罪活动而设立的公司、企业、事业单位实施犯罪的，或者公司、企业、事业单位设立后，以实施犯罪为主要活动的，不以单位犯罪论处。"},{"i":3,"n":"第三条","txt":"盗用单位名义实施犯罪，违法所得由实施犯罪的个人私分的，依照刑法有关自然人犯罪的规定定罪处罚。"}],"zuigaorenminfayuanguanyushenliweihaijunshitongxinxc89b7b":[{"i":1,"n":"第一条","txt":"故意实施损毁军事通信线路、设备，破坏军事通信计算机信息系统，干扰、侵占军事通信电磁频谱等行为的，依照刑法第三百六十九条第一款的规定，以破坏军事通信罪定罪，处三年以下有期徒刑、拘役或者管制；破坏重要军事通信的，处三年以上十年以下有期徒刑。"},{"i":2,"n":"第二条","txt":"实施破坏军事通信行为，具有下列情形之一的，属于刑法第三百六十九条第一款规定的“情节特别严重”，以破坏军事通信罪定罪，处十年以上有期徒刑、无期徒刑或者死刑："},{"i":3,"n":"第三条","txt":"过失损坏军事通信，造成重要军事通信中断或者严重障碍的，属于刑法第三百六十九条第二款规定的“造成严重后果”，以过失损坏军事通信罪定罪，处三年以下有期徒刑或者拘役。"},{"i":4,"n":"第四条","txt":"过失损坏军事通信，具有下列情形之一的，属于刑法第三百六十九条第二款规定的“造成特别严重后果”，以过失损坏军事通信罪定罪，处三年以上七年以下有期徒刑："},{"i":5,"n":"第五条","txt":"建设、施工单位直接负责的主管人员、施工管理人员，明知是军事通信线路、设备而指使、强令、纵容他人予以损毁的，或者不听管护人员劝阻，指使、强令、纵容他人违章作业，造成军事通信线路、设备损毁的，以破坏军事通信罪定罪处罚。"},{"i":6,"n":"第六条","txt":"破坏、过失损坏军事通信，并造成公用电信设施损毁，危害公共安全，同时构成刑法第一百二十四条和第三百六十九条规定的犯罪的，依照处罚较重的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"本解释所称“重要军事通信”，是指军事首脑机关及重要指挥中心的通信，部队作战中的通信，等级战备通信，飞行航行训练、抢险救灾、军事演习或者处置突发性事件中的通信，以及执行试飞试航、武器装备科研试验或者远洋航行等重要军事任务中的通信。"}],"zuigaorenminfayuanguanyushenlisifapeichanganjianshd69651":[{"i":1,"n":"第一条","txt":"赔偿请求人向赔偿义务机关提出赔偿请求的时效期间为两年，自其知道或者应当知道国家机关及其工作人员行使职权时的行为侵犯其人身权、财产权之日起计算。"},{"i":2,"n":"第二条","txt":"赔偿请求人以人身权受到侵犯为由，依照国家赔偿法第十七条第一项、第二项、第三项规定申请赔偿的，请求时效期间自其收到决定撤销案件、终止侦查、不起诉或者判决宣告无罪等终止追究刑事责任或者再审改判无罪的法律文书之日起计算。"},{"i":3,"n":"第三条","txt":"赔偿请求人以人身权受到侵犯为由，依照国家赔偿法第十七条第四项、第五项规定申请赔偿的，请求时效期间自其知道或者应当知道损害结果之日起计算；损害结果当时不能确定的，自损害结果确定之日起计算。"},{"i":4,"n":"第四条","txt":"赔偿请求人以财产权受到侵犯为由，依照国家赔偿法第十八条第一项规定申请赔偿的，请求时效期间自其收到刑事诉讼程序或者执行程序终结的法律文书之日起计算，但是刑事诉讼程序或者执行程序终结之后办案机关对涉案财物尚未处理完毕的，请求时效期间自赔偿请求人知道或者应当知道其财产权受到侵犯之日起计算。"},{"i":5,"n":"第五条","txt":"赔偿请求人以人身权或者财产权受到侵犯为由，依照国家赔偿法第三十八条规定申请赔偿的，请求时效期间自赔偿请求人收到民事、行政诉讼程序或者执行程序终结的法律文书之日起计算，但是下列情形除外："},{"i":6,"n":"第六条","txt":"依照国家赔偿法第三十九条第一款规定，赔偿请求人被羁押等限制人身自由的期间，不计算在请求时效期间内。"},{"i":7,"n":"第七条","txt":"依照国家赔偿法第三十九条第二款规定，在请求时效期间的最后六个月内，赔偿请求人因下列障碍之一，不能行使请求权的，请求时效中止："},{"i":8,"n":"第八条","txt":"请求时效期间届满的，赔偿义务机关可以提出不予赔偿的抗辩。"},{"i":9,"n":"第九条","txt":"赔偿义务机关以请求时效期间届满为由抗辩，应当在人民法院赔偿委员会作出国家赔偿决定前提出。"},{"i":10,"n":"第十条","txt":"人民法院赔偿委员会审理国家赔偿案件，不得主动适用请求时效的规定。"},{"i":11,"n":"第十一条","txt":"请求时效期间起算的当日不计入，自下一日开始计算。"},{"i":12,"n":"第十二条","txt":"本解释自2023年6月1日起施行。本解释施行后，案件尚在审理的，适用本解释；对本解释施行前已经作出生效赔偿决定的案件进行再审，不适用本解释。"},{"i":13,"n":"第十三条","txt":"本院之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlishangpinfangmaimaihed399ad":[{"i":1,"n":"第一条","txt":"本解释所称的商品房买卖合同，是指房地产开发企业（以下统称为出卖人）将尚未建成或者已竣工的房屋向社会销售并转移房屋所有权于买受人，买受人支付价款的合同。"},{"i":2,"n":"第二条","txt":"出卖人未取得商品房预售许可证明，与买受人订立的商品房预售合同，应当认定无效，但是在起诉前取得商品房预售许可证明的，可以认定有效。"},{"i":3,"n":"第三条","txt":"商品房的销售广告和宣传资料为要约邀请，但是出卖人就商品房开发规划范围内的房屋及相关设施所作的说明和允诺具体确定，并对商品房买卖合同的订立以及房屋价格的确定有重大影响的，构成要约。该说明和允诺即使未载入商品房买卖合同，亦应当为合同内容，当事人违反的，应当承担违约责任。"},{"i":4,"n":"第四条","txt":"出卖人通过认购、订购、预订等方式向买受人收受定金作为订立商品房买卖合同担保的，如果因当事人一方原因未能订立商品房买卖合同，应当按照法律关于定金的规定处理；因不可归责于当事人双方的事由，导致商品房买卖合同未能订立的，出卖人应当将定金返还买受人。"},{"i":5,"n":"第五条","txt":"商品房的认购、订购、预订等协议具备《商品房销售管理办法》第十六条规定的商品房买卖合同的主要内容，并且出卖人已经按照约定收受购房款的，该协议应当认定为商品房买卖合同。"},{"i":6,"n":"第六条","txt":"当事人以商品房预售合同未按照法律、行政法规规定办理登记备案手续为由，请求确认合同无效的，不予支持。"},{"i":7,"n":"第七条","txt":"买受人以出卖人与第三人恶意串通，另行订立商品房买卖合同并将房屋交付使用，导致其无法取得房屋为由，请求确认出卖人与第三人订立的商品房买卖合同无效的，应予支持。"},{"i":8,"n":"第八条","txt":"对房屋的转移占有，视为房屋的交付使用，但当事人另有约定的除外。"},{"i":9,"n":"第九条","txt":"因房屋主体结构质量不合格不能交付使用，或者房屋交付使用后，房屋主体结构质量经核验确属不合格，买受人请求解除合同和赔偿损失的，应予支持。"},{"i":10,"n":"第十条","txt":"因房屋质量问题严重影响正常居住使用，买受人请求解除合同和赔偿损失的，应予支持。"},{"i":11,"n":"第十一条","txt":"根据民法典第五百六十三条的规定，出卖人迟延交付房屋或者买受人迟延支付购房款，经催告后在三个月的合理期限内仍未履行，解除权人请求解除合同的，应予支持，但当事人另有约定的除外。"},{"i":12,"n":"第十二条","txt":"当事人以约定的违约金过高为由请求减少的，应当以违约金超过造成的损失30％为标准适当减少；当事人以约定的违约金低于造成的损失为由请求增加的，应当以违约造成的损失确定违约金数额。"},{"i":13,"n":"第十三条","txt":"商品房买卖合同没有约定违约金数额或者损失赔偿额计算方法，违约金数额或者损失赔偿额可以参照以下标准确定："},{"i":14,"n":"第十四条","txt":"由于出卖人的原因，买受人在下列期限届满未能取得不动产权属证书的，除当事人有特殊约定外，出卖人应当承担违约责任："},{"i":15,"n":"第十五条","txt":"商品房买卖合同约定或者《城市房地产开发经营管理条例》第三十二条规定的办理不动产登记的期限届满后超过一年，由于出卖人的原因，导致买受人无法办理不动产登记，买受人请求解除合同和赔偿损失的，应予支持。"},{"i":16,"n":"第十六条","txt":"出卖人与包销人订立商品房包销合同，约定出卖人将其开发建设的房屋交由包销人以出卖人的名义销售的，包销期满未销售的房屋，由包销人按照合同约定的包销价格购买，但当事人另有约定的除外。"},{"i":17,"n":"第十七条","txt":"出卖人自行销售已经约定由包销人包销的房屋，包销人请求出卖人赔偿损失的，应予支持，但当事人另有约定的除外。"},{"i":18,"n":"第十八条","txt":"对于买受人因商品房买卖合同与出卖人发生的纠纷，人民法院应当通知包销人参加诉讼；出卖人、包销人和买受人对各自的权利义务有明确约定的，按照约定的内容确定各方的诉讼地位。"},{"i":19,"n":"第十九条","txt":"商品房买卖合同约定，买受人以担保贷款方式付款、因当事人一方原因未能订立商品房担保贷款合同并导致商品房买卖合同不能继续履行的，对方当事人可以请求解除合同和赔偿损失。因不可归责于当事人双方的事由未能订立商品房担保贷款合同并导致商品房买卖合同不能继续履行的，当事人可以请求解除合同，出卖人应当将收受的购房款本金及其利息或者定金返还买受人。"},{"i":20,"n":"第二十条","txt":"因商品房买卖合同被确认无效或者被撤销、解除，致使商品房担保贷款合同的目的无法实现，当事人请求解除商品房担保贷款合同的，应予支持。"},{"i":21,"n":"第二十一条","txt":"以担保贷款为付款方式的商品房买卖合同的当事人一方请求确认商品房买卖合同无效或者撤销、解除合同的，如果担保权人作为有独立请求权第三人提出诉讼请求，应当与商品房担保贷款合同纠纷合并审理；未提出诉讼请求的，仅处理商品房买卖合同纠纷。担保权人就商品房担保贷款合同纠纷另行起诉的，可以与商品房买卖合同纠纷合并审理。"},{"i":22,"n":"第二十二条","txt":"买受人未按照商品房担保贷款合同的约定偿还贷款，亦未与担保权人办理不动产抵押登记手续，担保权人起诉买受人，请求处分商品房买卖合同项下买受人合同权利的，应当通知出卖人参加诉讼；担保权人同时起诉出卖人时，如果出卖人为商品房担保贷款合同提供保证的，应当列为共同被告。"},{"i":23,"n":"第二十三条","txt":"买受人未按照商品房担保贷款合同的约定偿还贷款，但是已经取得不动产权属证书并与担保权人办理了不动产抵押登记手续，抵押权人请求买受人偿还贷款或者就抵押的房屋优先受偿的，不应当追加出卖人为当事人，但出卖人提供保证的除外。"},{"i":24,"n":"第二十四条","txt":"本解释自2003年6月1日起施行。"}],"zuigaorenminfayuanguanyushenlishangbiaoanjianyougu67a5a5":[{"i":1,"n":"第一条","txt":"人民法院受理以下商标案件："},{"i":2,"n":"第二条","txt":"本解释第一条所列第1项第一审案件，由北京市高级人民法院根据最高人民法院的授权确定其辖区内有关中级人民法院管辖。"},{"i":3,"n":"第三条","txt":"商标注册人或者利害关系人向国家知识产权局就侵犯商标权行为请求处理，又向人民法院提起侵害商标权诉讼请求损害赔偿的，人民法院应当受理。"},{"i":4,"n":"第四条","txt":"国家知识产权局在商标法修改决定施行前受理的案件，于该决定施行后作出复审决定或裁定，当事人对复审决定或裁定不服向人民法院起诉的，人民法院应当受理。"},{"i":5,"n":"第五条","txt":"除本解释另行规定外，对商标法修改决定施行前发生，属于修改后商标法第四条、第五条、第八条、第九条第一款、第十条第一款第（二）、（三）、（四）项、第十条第二款、第十一条、第十二条、第十三条、第十五条、第十六条、第二十四条、第二十五条、第三十一条所列举的情形，国家知识产权局于商标法修改决定施行后作出复审决定或者裁定，当事人不服向人民法院起诉的行政案件，适用修改后商标法的相应规定进行审查；属于其他情形的，适用修改前商标法的相应规定进行审查。"},{"i":6,"n":"第六条","txt":"当事人就商标法修改决定施行时已满一年的注册商标发生争议，不服国家知识产权局作出的裁定向人民法院起诉的，适用修改前商标法第二十七条第二款规定的提出申请的期限处理；商标法修改决定施行时商标注册不满一年的，适用修改后商标法第四十一条第二款、第三款规定的提出申请的期限处理。"},{"i":7,"n":"第七条","txt":"对商标法修改决定施行前发生的侵犯商标专用权行为，商标注册人或者利害关系人于该决定施行后在起诉前向人民法院提出申请采取责令停止侵权行为或者保全证据措施的，适用修改后商标法第五十七条、第五十八条的规定。"},{"i":8,"n":"第八条","txt":"对商标法修改决定施行前发生的侵犯商标专用权行为起诉的案件，人民法院于该决定施行时尚未作出生效判决的，参照修改后商标法第五十六条的规定处理。"},{"i":9,"n":"第九条","txt":"除本解释另行规定外，商标法修改决定施行后人民法院受理的商标民事纠纷案件，涉及该决定施行前发生的民事行为的，适用修改前商标法的规定；涉及该决定施行后发生的民事行为的，适用修改后商标法的规定；涉及该决定施行前发生，持续到该决定施行后的民事行为的，分别适用修改前、后商标法的规定。"},{"i":10,"n":"第十条","txt":"人民法院受理的侵犯商标权纠纷案件，已经过行政管理部门处理的，人民法院仍应当就当事人民事争议的事实进行审查。"}],"zuigaorenminfayuanguanyushenlishangbiaominshijiufeae046b":[{"i":1,"n":"第一条","txt":"下列行为属于商标法第五十七条第（七）项规定的给他人注册商标专用权造成其他损害的行为："},{"i":2,"n":"第二条","txt":"依据商标法第十三条第二款的规定，复制、摹仿、翻译他人未在中国注册的驰名商标或其主要部分，在相同或者类似商品上作为商标使用，容易导致混淆的，应当承担停止侵害的民事法律责任。"},{"i":3,"n":"第三条","txt":"商标法第四十三条规定的商标使用许可包括以下三类："},{"i":4,"n":"第四条","txt":"商标法第六十条第一款规定的利害关系人，包括注册商标使用许可合同的被许可人、注册商标财产权利的合法继承人等。"},{"i":5,"n":"第五条","txt":"商标注册人或者利害关系人在注册商标续展宽展期内提出续展申请，未获核准前，以他人侵犯其注册商标专用权提起诉讼的，人民法院应当受理。"},{"i":6,"n":"第六条","txt":"因侵犯注册商标专用权行为提起的民事诉讼，由商标法第十三条、第五十七条所规定侵权行为的实施地、侵权商品的储藏地或者查封扣押地、被告住所地人民法院管辖。"},{"i":7,"n":"第七条","txt":"对涉及不同侵权行为实施地的多个被告提起的共同诉讼，原告可以选择其中一个被告的侵权行为实施地人民法院管辖；仅对其中某一被告提起的诉讼，该被告侵权行为实施地的人民法院有管辖权。"},{"i":8,"n":"第八条","txt":"商标法所称相关公众，是指与商标所标识的某类商品或者服务有关的消费者和与前述商品或者服务的营销有密切关系的其他经营者。"},{"i":9,"n":"第九条","txt":"商标法第五十七条第（一）（二）项规定的商标相同，是指被控侵权的商标与原告的注册商标相比较，二者在视觉上基本无差别。"},{"i":10,"n":"第十条","txt":"人民法院依据商标法第五十七条第（一）（二）项的规定，认定商标相同或者近似按照以下原则进行："},{"i":11,"n":"第十一条","txt":"商标法第五十七条第（二）项规定的类似商品，是指在功能、用途、生产部门、销售渠道、消费对象等方面相同，或者相关公众一般认为其存在特定联系、容易造成混淆的商品。"},{"i":12,"n":"第十二条","txt":"人民法院依据商标法第五十七条第（二）项的规定，认定商品或者服务是否类似，应当以相关公众对商品或者服务的一般认识综合判断；《商标注册用商品和服务国际分类表》《类似商品和服务区分表》可以作为判断类似商品或者服务的参考。"},{"i":13,"n":"第十三条","txt":"人民法院依据商标法第六十三条第一款的规定确定侵权人的赔偿责任时，可以根据权利人选择的计算方法计算赔偿数额。"},{"i":14,"n":"第十四条","txt":"商标法第六十三条第一款规定的侵权所获得的利益，可以根据侵权商品销售量与该商品单位利润乘积计算；该商品单位利润无法查明的，按照注册商标商品的单位利润计算。"},{"i":15,"n":"第十五条","txt":"商标法第六十三条第一款规定的因被侵权所受到的损失，可以根据权利人因侵权所造成商品销售减少量或者侵权商品销售量与该注册商标商品的单位利润乘积计算。"},{"i":16,"n":"第十六条","txt":"权利人因被侵权所受到的实际损失、侵权人因侵权所获得的利益、注册商标使用许可费均难以确定的，人民法院可以根据当事人的请求或者依职权适用商标法第六十三条第三款的规定确定赔偿数额。"},{"i":17,"n":"第十七条","txt":"商标法第六十三条第一款规定的制止侵权行为所支付的合理开支，包括权利人或者委托代理人对侵权行为进行调查、取证的合理费用。"},{"i":18,"n":"第十八条","txt":"侵犯注册商标专用权的诉讼时效为三年，自商标注册人或者利害权利人知道或者应当知道权利受到损害以及义务人之日起计算。商标注册人或者利害关系人超过三年起诉的，如果侵权行为在起诉时仍在持续，在该注册商标专用权有效期限内，人民法院应当判决被告停止侵权行为，侵权损害赔偿数额应当自权利人向人民法院起诉之日起向前推算三年计算。"},{"i":19,"n":"第十九条","txt":"商标使用许可合同未经备案的，不影响该许可合同的效力，但当事人另有约定的除外。"},{"i":20,"n":"第二十条","txt":"注册商标的转让不影响转让前已经生效的商标使用许可合同的效力，但商标使用许可合同另有约定的除外。"},{"i":21,"n":"第二十一条","txt":"人民法院在审理侵犯注册商标专用权纠纷案件中，依据民法典第一百七十九条、商标法第六十条的规定和案件具体情况，可以判决侵权人承担停止侵害、排除妨碍、消除危险、赔偿损失、消除影响等民事责任，还可以作出罚款，收缴侵权商品、伪造的商标标识和主要用于生产侵权商品的材料、工具、设备等财物的民事制裁决定。罚款数额可以参照商标法第六十条第二款的有关规定确定。"},{"i":22,"n":"第二十二条","txt":"人民法院在审理商标纠纷案件中，根据当事人的请求和案件的具体情况，可以对涉及的注册商标是否驰名依法作出认定。"},{"i":23,"n":"第二十三条","txt":"本解释有关商品商标的规定，适用于服务商标。"},{"i":24,"n":"第二十四条","txt":"以前的有关规定与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenliguojiapeichanganjiancfe7a4":[{"i":1,"n":"第一条","txt":"公民以人身权受到侵犯为由提出国家赔偿申请，依照国家赔偿法第三十五条的规定请求精神损害赔偿的，适用本解释。"},{"i":2,"n":"第二条","txt":"公民以人身权受到侵犯为由提出国家赔偿申请，未请求精神损害赔偿，或者未同时请求消除影响、恢复名誉、赔礼道歉以及精神损害抚慰金的，人民法院应当向其释明。经释明后不变更请求，案件审结后又基于同一侵权事实另行提出申请的，人民法院不予受理。"},{"i":3,"n":"第三条","txt":"赔偿义务机关有国家赔偿法第三条、第十七条规定情形之一，依法应当承担国家赔偿责任的，可以同时认定该侵权行为致人精神损害。但是赔偿义务机关有证据证明该公民不存在精神损害，或者认定精神损害违背公序良俗的除外。"},{"i":4,"n":"第四条","txt":"侵权行为致人精神损害，应当为受害人消除影响、恢复名誉或者赔礼道歉；侵权行为致人精神损害并造成严重后果，应当在支付精神损害抚慰金的同时，视案件具体情形，为受害人消除影响、恢复名誉或者赔礼道歉。"},{"i":5,"n":"第五条","txt":"人民法院可以根据案件具体情况，组织赔偿请求人与赔偿义务机关就消除影响、恢复名誉或者赔礼道歉的具体方式进行协商。"},{"i":6,"n":"第六条","txt":"决定为受害人消除影响、恢复名誉或者赔礼道歉的，应当载入决定主文。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，可以认定为国家赔偿法第三十五条规定的“造成严重后果”："},{"i":8,"n":"第八条","txt":"致人精神损害，造成严重后果的，精神损害抚慰金一般应当在国家赔偿法第三十三条、第三十四条规定的人身自由赔偿金、生命健康赔偿金总额的百分之五十以下（包括本数）酌定；后果特别严重，或者虽然不具有本解释第七条第二款规定情形，但是确有证据证明前述标准不足以抚慰的，可以在百分之五十以上酌定。"},{"i":9,"n":"第九条","txt":"精神损害抚慰金的具体数额，应当在兼顾社会发展整体水平的同时，参考下列因素合理确定："},{"i":10,"n":"第十条","txt":"精神损害抚慰金的数额一般不少于一千元；数额在一千元以上的，以千为计数单位。"},{"i":11,"n":"第十一条","txt":"受害人对损害事实和后果的发生或者扩大有过错的，可以根据其过错程度减少或者不予支付精神损害抚慰金。"},{"i":12,"n":"第十二条","txt":"决定中载明的支付精神损害抚慰金及其他责任承担方式，赔偿义务机关应当履行。"},{"i":13,"n":"第十三条","txt":"人民法院审理国家赔偿法第三十八条所涉侵犯公民人身权的国家赔偿案件，以及作为赔偿义务机关审查处理国家赔偿案件，涉及精神损害赔偿的，参照本解释规定。"},{"i":14,"n":"第十四条","txt":"本解释自2021年4月1日起施行。本解释施行前的其他有关规定与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlilongduanminshijiufen05d1b7":[{"i":1,"n":"第一条","txt":"本解释所称垄断民事纠纷案件，是指自然人、法人或者非法人组织因垄断行为受到损失以及因合同内容或者经营者团体的章程、决议、决定等违反反垄断法而发生争议，依据反垄断法向人民法院提起民事诉讼的案件。"},{"i":2,"n":"第二条","txt":"原告依据反垄断法直接向人民法院提起民事诉讼，或者在反垄断执法机构认定构成垄断行为的处理决定作出后向人民法院提起民事诉讼，且符合法律规定的受理条件的，人民法院应予受理。"},{"i":3,"n":"第三条","txt":"一方当事人向人民法院提起垄断民事诉讼，另一方当事人以双方之间存在合同关系且有仲裁协议为由，主张人民法院不应受理的，人民法院不予支持。"},{"i":4,"n":"第四条","txt":"第一审垄断民事纠纷案件，由知识产权法院和最高人民法院指定的中级人民法院管辖。"},{"i":5,"n":"第五条","txt":"垄断民事纠纷案件的地域管辖，根据案件具体情况，依照民事诉讼法及相关司法解释有关侵权纠纷、合同纠纷等的管辖规定确定。"},{"i":6,"n":"第六条","txt":"原告依据反垄断法对在中华人民共和国境内没有住所的被告提起民事诉讼，主张被告在中华人民共和国境外的垄断行为对境内市场竞争产生排除、限制影响的，根据民事诉讼法第二百七十六条的规定确定管辖法院。"},{"i":7,"n":"第七条","txt":"案件立案时的案由并非垄断民事纠纷，人民法院受理后经审查发现属于垄断民事纠纷，但受诉人民法院并无垄断民事纠纷案件管辖权的，应当将案件移送有管辖权的人民法院。"},{"i":8,"n":"第八条","txt":"两个以上原告因同一垄断行为向有管辖权的同一人民法院分别提起诉讼的，人民法院可以合并审理。"},{"i":9,"n":"第九条","txt":"原告无正当理由而根据影响地域、持续时间、实施场合、损害范围等因素对被告的同一垄断行为予以拆分，分别提起数个诉讼的，由最先受理诉讼的人民法院合并审理。"},{"i":10,"n":"第十条","txt":"反垄断执法机构认定构成垄断行为的处理决定在法定期限内未被提起行政诉讼或者已为人民法院生效裁判所确认，原告在相关垄断民事纠纷案件中据此主张该处理决定认定的基本事实为真实的，无需再行举证证明，但有相反证据足以推翻的除外。"},{"i":11,"n":"第十一条","txt":"当事人可以向人民法院申请一至二名具有案件所涉领域、经济学等专门知识的人员出庭，就案件的专门性问题进行说明。"},{"i":12,"n":"第十二条","txt":"经营者实施垄断行为损害社会公共利益，设区的市级以上人民检察院依法提起民事公益诉讼的，适用与公益诉讼有关的法律和司法解释的规定，但本解释另有规定的除外。"},{"i":13,"n":"第十三条","txt":"反垄断执法机构对被诉垄断行为已经立案调查的，人民法院可以根据案件具体情况，裁定中止诉讼。"},{"i":14,"n":"第十四条","txt":"原告主张被诉垄断行为违反反垄断法的，一般应当界定反垄断法第十五条第二款所称的相关市场并提供证据或者充分说明理由。"},{"i":15,"n":"第十五条","txt":"人民法院界定经营者在一定时期内就特定商品或者服务（以下统称商品）进行竞争的相关商品市场和相关地域市场，可以根据案件具体情况，以被诉垄断行为直接涉及的特定商品为基础，从需求者角度进行需求替代分析；供给替代对经营者行为产生的竞争约束类似于需求替代的，还可以从供给者角度进行供给替代分析。"},{"i":16,"n":"第十六条","txt":"人民法院从需求替代的角度分析界定相关商品市场时，一般根据需求者对于商品特性、功能和用途的需求、质量的认可、价格的接受以及获取的难易程度等因素，确定由需求者认为具有较为紧密替代关系的一组或者一类商品所构成的市场为相关商品市场。从供给替代的角度分析界定相关商品市场时，可以综合考虑其他经营者进入市场的意图和能力、承担的成本与风险、克服的市场障碍、需要的时间等因素。"},{"i":17,"n":"第十七条","txt":"人民法院从需求替代的角度分析界定相关地域市场时，可以综合考虑需求者因商品价格或者其他竞争因素的变化而转向其他地域购买商品的情况、商品的运输成本和运输特征、多数需求者选择商品的实际区域和主要经营者的商品销售分布、地域间的市场障碍、特定区域需求者偏好等因素。从供给替代的角度分析界定相关地域市场时，可以综合考虑其他地域的经营者对商品价格等竞争因素的变化作出的反应、其他地域的经营者供应或者销售相关商品的及时性和可行性等因素。"},{"i":18,"n":"第十八条","txt":"人民法院认定反垄断法第十六条规定的其他协同行为，应当综合考虑下列因素："},{"i":19,"n":"第十九条","txt":"反垄断法第十七条规定的具有竞争关系的经营者，是指在商品生产经营过程中处于同一阶段、提供具有较为紧密替代关系的商品、独立经营决策并承担法律责任的两个以上的实际经营者或者可能进入同一相关市场进行竞争的潜在经营者。"},{"i":20,"n":"第二十条","txt":"原告有证据证明仿制药申请人与被仿制药专利权利人达成、实施的协议同时具备下列条件，主张该协议构成反垄断法第十七条规定的垄断协议的，人民法院可予支持："},{"i":21,"n":"第二十一条","txt":"被诉垄断行为属于反垄断法第十八条第一款第一项、第二项规定的垄断协议的，应当由被告对该协议不具有排除、限制竞争效果承担举证责任。"},{"i":22,"n":"第二十二条","txt":"人民法院依照反垄断法第十八条第一款和第二款的规定审查认定被诉垄断协议是否具有排除、限制竞争效果时，可以综合考虑下列因素："},{"i":23,"n":"第二十三条","txt":"被诉垄断协议具有下列情形之一，原告依据反垄断法第十八条第一款的规定主张被告应当承担法律责任的，人民法院不予支持："},{"i":24,"n":"第二十四条","txt":"经营者利用数据、算法、技术等手段进行意思联络、信息交流或者传递，或者利用数据、算法、技术、平台规则等手段实现行为一致性，达成、实施被诉垄断协议的，人民法院可以依照反垄断法第十七条的规定审查认定。"},{"i":25,"n":"第二十五条","txt":"平台经营者与平台内经营者的协议要求平台内经营者在该平台上提供与其他交易渠道相同或者更优惠交易条件的，根据原告的诉讼请求和具体案情，人民法院可以区别下列情形作出处理："},{"i":26,"n":"第二十六条","txt":"经营者、经营者团体等组织其他经营者达成、实施垄断协议，给原告造成损失，原告依据民法典第一千一百六十八条的规定主张实施组织行为的经营者、经营者团体等与达成、实施垄断协议的其他经营者承担连带责任的，人民法院应当予以支持。"},{"i":27,"n":"第二十七条","txt":"被告依据反垄断法第二十条第一款第一项至第五项的规定提出抗辩的，应当提供证据证明如下事实："},{"i":28,"n":"第二十八条","txt":"原告主张被诉垄断行为属于反垄断法第二十二条第一款规定的滥用市场支配地位的，应当对被告在相关市场内具有支配地位和被告滥用市场支配地位承担举证责任。被告以其行为具有正当性为由抗辩的，应当承担举证责任。"},{"i":29,"n":"第二十九条","txt":"原告有证据证明经营者具有下列情形之一的，人民法院可以根据具体案件中相关市场的结构和实际竞争状况，结合相关市场经济规律等经济学知识，初步认定经营者在相关市场具有支配地位，但有相反证据足以反驳的除外："},{"i":30,"n":"第三十条","txt":"反垄断法第二十三条和第二十四条所称的“经营者在相关市场的市场份额”，可以根据被诉垄断行为发生时经营者一定时期内的相关商品交易金额、交易数量、生产能力或者其他指标在相关市场所占的比例确定。"},{"i":31,"n":"第三十一条","txt":"原告主张公用企业或者其他依法具有独占地位的经营者滥用市场支配地位的，人民法院可以根据市场结构和竞争状况的具体情况，认定被告在相关市场具有支配地位，但有相反证据足以反驳的除外。"},{"i":32,"n":"第三十二条","txt":"人民法院依照反垄断法第二十三条的规定认定平台经营者的市场支配地位，可以重点考虑下列因素："},{"i":33,"n":"第三十三条","txt":"人民法院依照反垄断法第二十三条的规定认定被诉滥用知识产权的经营者的市场支配地位，可以重点考虑下列因素："},{"i":34,"n":"第三十四条","txt":"依据反垄断法第二十四条第一款第二项、第三项被推定共同具有市场支配地位的经营者，有证据证明具有下列情形之一，反驳上述推定的，人民法院应予支持："},{"i":35,"n":"第三十五条","txt":"经营者同时具备下列条件的，人民法院可以认定其构成反垄断法第二十二条规定的滥用市场支配地位行为："},{"i":36,"n":"第三十六条","txt":"人民法院认定反垄断法第二十二条第一款第一项规定的经营者“以不公平的高价销售商品或者以不公平的低价购买商品”，可以综合考虑下列因素："},{"i":37,"n":"第三十七条","txt":"具有市场支配地位的经营者，具有下列情形之一的，人民法院可以初步认定其构成反垄断法第二十二条第一款第二项规定的“以低于成本的价格销售商品”："},{"i":38,"n":"第三十八条","txt":"具有市场支配地位的经营者，同时具备下列条件的，人民法院可以初步认定其构成反垄断法第二十二条第一款第三项规定的“拒绝与交易相对人进行交易”："},{"i":39,"n":"第三十九条","txt":"具有市场支配地位的经营者，同时具备下列条件的，人民法院可以初步认定其构成反垄断法第二十二条第一款第四项规定的“限定交易相对人只能与其进行交易或者只能与其指定的经营者进行交易”："},{"i":40,"n":"第四十条","txt":"具有市场支配地位的经营者，同时具备下列条件的，人民法院可以初步认定其构成反垄断法第二十二条第一款第五项规定的“搭售商品”："},{"i":41,"n":"第四十一条","txt":"具有市场支配地位的经营者，同时具备下列条件的，人民法院可以初步认定其构成反垄断法第二十二条第一款第六项规定的“对条件相同的交易相对人在交易价格等交易条件上实行差别待遇”："},{"i":42,"n":"第四十二条","txt":"平台内经营者作为原告提起诉讼，主张平台经营者利用数据、算法、技术、平台规则等实施滥用市场支配地位或者其他违法行为，根据原告的诉讼请求和具体案情，人民法院可以区别下列情形作出处理："},{"i":43,"n":"第四十三条","txt":"被告实施垄断行为，给原告造成损失的，根据原告的诉讼请求和查明的事实，人民法院可以依法判令被告承担停止侵害、赔偿损失等民事责任。"},{"i":44,"n":"第四十四条","txt":"原告因被诉垄断行为受到的损失包括直接损失和相对于该行为未发生条件下减少的可得利益。"},{"i":45,"n":"第四十五条","txt":"根据原告的诉讼请求和具体案情，人民法院可以将原告因调查、制止垄断行为所支付的合理开支，包括合理的市场调查费用、经济分析费用、律师费用等，计入损失赔偿范围。"},{"i":46,"n":"第四十六条","txt":"多个被诉垄断行为相互关联，在同一相关市场或者多个相关市场给原告造成难以分割的整体性损失的，人民法院在确定损失时应当整体考虑。"},{"i":47,"n":"第四十七条","txt":"横向垄断协议的经营者以达成、实施该协议的其他经营者为被告，依据反垄断法第六十条的规定请求赔偿其参与该协议期间的损失的，人民法院不予支持。"},{"i":48,"n":"第四十八条","txt":"当事人主张被诉垄断行为所涉合同或者经营者团体的章程、决议、决定等因违反反垄断法或者其他法律、行政法规的强制性规定而无效的，人民法院应当依照民法典第一百五十三条的规定审查认定。"},{"i":49,"n":"第四十九条","txt":"因垄断行为产生的损害赔偿请求权诉讼时效期间，从原告知道或者应当知道权益受到损害以及义务人之日起计算。"},{"i":50,"n":"第五十条","txt":"人民法院审理垄断民事纠纷案件，适用被诉垄断行为发生时施行的反垄断法。被诉垄断行为发生在修改后的反垄断法施行之前，行为持续至或者损害后果出现在修改后的反垄断法施行之后的，适用修改后的反垄断法。"},{"i":51,"n":"第五十一条","txt":"本解释自2024年7月1日起施行。《最高人民法院关于审理因垄断行为引发的民事纠纷案件应用法律若干问题的规定》（法释〔2012〕5号）同时废止。"}],"zuigaorenminfayuanguanyushenlichengzhenfangwuzulin9d1679":[{"i":1,"n":"第一条","txt":"本解释所称城镇房屋，是指城市、镇规划区内的房屋。"},{"i":2,"n":"第二条","txt":"出租人就未取得建设工程规划许可证或者未按照建设工程规划许可证的规定建设的房屋，与承租人订立的租赁合同无效。但在一审法庭辩论终结前取得建设工程规划许可证或者经主管部门批准建设的，人民法院应当认定有效。"},{"i":3,"n":"第三条","txt":"出租人就未经批准或者未按照批准内容建设的临时建筑，与承租人订立的租赁合同无效。但在一审法庭辩论终结前经主管部门批准建设的，人民法院应当认定有效。"},{"i":4,"n":"第四条","txt":"房屋租赁合同无效，当事人请求参照合同约定的租金标准支付房屋占有使用费的，人民法院一般应予支持。"},{"i":5,"n":"第五条","txt":"出租人就同一房屋订立数份租赁合同，在合同均有效的情况下，承租人均主张履行合同的，人民法院按照下列顺序确定履行合同的承租人："},{"i":6,"n":"第六条","txt":"承租人擅自变动房屋建筑主体和承重结构或者扩建，在出租人要求的合理期限内仍不予恢复原状，出租人请求解除合同并要求赔偿损失的，人民法院依照民法典第七百一十一条的规定处理。"},{"i":7,"n":"第七条","txt":"承租人经出租人同意装饰装修，租赁合同无效时，未形成附合的装饰装修物，出租人同意利用的，可折价归出租人所有；不同意利用的，可由承租人拆除。因拆除造成房屋毁损的，承租人应当恢复原状。"},{"i":8,"n":"第八条","txt":"承租人经出租人同意装饰装修，租赁期间届满或者合同解除时，除当事人另有约定外，未形成附合的装饰装修物，可由承租人拆除。因拆除造成房屋毁损的，承租人应当恢复原状。"},{"i":9,"n":"第九条","txt":"承租人经出租人同意装饰装修，合同解除时，双方对已形成附合的装饰装修物的处理没有约定的，人民法院按照下列情形分别处理："},{"i":10,"n":"第十条","txt":"承租人经出租人同意装饰装修，租赁期间届满时，承租人请求出租人补偿附合装饰装修费用的，不予支持。但当事人另有约定的除外。"},{"i":11,"n":"第十一条","txt":"承租人未经出租人同意装饰装修或者扩建发生的费用，由承租人负担。出租人请求承租人恢复原状或者赔偿损失的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"承租人经出租人同意扩建，但双方对扩建费用的处理没有约定的，人民法院按照下列情形分别处理："},{"i":13,"n":"第十三条","txt":"房屋租赁合同无效、履行期限届满或者解除，出租人请求负有腾房义务的次承租人支付逾期腾房占有使用费的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"租赁房屋在承租人按照租赁合同占有期限内发生所有权变动，承租人请求房屋受让人继续履行原租赁合同的，人民法院应予支持。但租赁房屋具有下列情形或者当事人另有约定的除外："},{"i":15,"n":"第十五条","txt":"出租人与抵押权人协议折价、变卖租赁房屋偿还债务，应当在合理期限内通知承租人。承租人请求以同等条件优先购买房屋的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"本解释施行前已经终审，本解释施行后当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。"}],"zuigaorenminfayuanguanyushenlijianzhuwuqufensuoyou7f33d5":[],"zuigaorenminfayuanguanyushenlijianshegongchengshig7143cd":[{"i":1,"n":"第一条","txt":"建设工程施工合同具有下列情形之一的，应当依据民法典第一百五十三条第一款的规定，认定无效："},{"i":2,"n":"第二条","txt":"招标人和中标人另行签订的建设工程施工合同约定的工程范围、建设工期、工程质量、工程价款等实质性内容，与中标合同不一致，一方当事人请求按照中标合同确定权利义务的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"当事人以发包人未取得建设工程规划许可证等规划审批手续为由，请求确认建设工程施工合同无效的，人民法院应予支持，但发包人在起诉前取得建设工程规划许可证等规划审批手续的除外。"},{"i":4,"n":"第四条","txt":"承包人超越资质等级许可的业务范围签订建设工程施工合同，在建设工程竣工前取得相应资质等级，当事人请求按照无效合同处理的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"具有劳务作业法定资质的承包人与总承包人、分包人签订的劳务分包合同，当事人请求确认无效的，人民法院依法不予支持。"},{"i":6,"n":"第六条","txt":"建设工程施工合同无效，一方当事人请求对方赔偿损失的，应当就对方过错、损失大小、过错与损失之间的因果关系承担举证责任。"},{"i":7,"n":"第七条","txt":"缺乏资质的单位或者个人借用有资质的建筑施工企业名义签订建设工程施工合同，发包人请求出借方与借用方对建设工程质量不合格等因出借资质造成的损失承担连带赔偿责任的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"当事人对建设工程开工日期有争议的，人民法院应当分别按照以下情形予以认定："},{"i":9,"n":"第九条","txt":"当事人对建设工程实际竣工日期有争议的，人民法院应当分别按照以下情形予以认定："},{"i":10,"n":"第十条","txt":"当事人约定顺延工期应当经发包人或者监理人签证等方式确认，承包人虽未取得工期顺延的确认，但能够证明在合同约定的期限内向发包人或者监理人申请过工期顺延且顺延事由符合合同约定，承包人以此为由主张工期顺延的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"建设工程竣工前，当事人对工程质量发生争议，工程质量经鉴定合格的，鉴定期间为顺延工期期间。"},{"i":12,"n":"第十二条","txt":"因承包人的原因造成建设工程质量不符合约定，承包人拒绝修理、返工或者改建，发包人请求减少支付工程价款的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"发包人具有下列情形之一，造成建设工程质量缺陷，应当承担过错责任："},{"i":14,"n":"第十四条","txt":"建设工程未经竣工验收，发包人擅自使用后，又以使用部分质量不符合约定为由主张权利的，人民法院不予支持；但是承包人应当在建设工程的合理使用寿命内对地基基础工程和主体结构质量承担民事责任。"},{"i":15,"n":"第十五条","txt":"因建设工程质量发生争议的，发包人可以以总承包人、分包人和实际施工人为共同被告提起诉讼。"},{"i":16,"n":"第十六条","txt":"发包人在承包人提起的建设工程施工合同纠纷案件中，以建设工程质量不符合合同约定或者法律规定为由，就承包人支付违约金或者赔偿修理、返工、改建的合理费用等损失提出反诉的，人民法院可以合并审理。"},{"i":17,"n":"第十七条","txt":"有下列情形之一，承包人请求发包人返还工程质量保证金的，人民法院应予支持："},{"i":18,"n":"第十八条","txt":"因保修人未及时履行保修义务，导致建筑物毁损或者造成人身损害、财产损失的，保修人应当承担赔偿责任。"},{"i":19,"n":"第十九条","txt":"当事人对建设工程的计价标准或者计价方法有约定的，按照约定结算工程价款。"},{"i":20,"n":"第二十条","txt":"当事人对工程量有争议的，按照施工过程中形成的签证等书面文件确认。承包人能够证明发包人同意其施工，但未能提供签证文件证明工程量发生的，可以按照当事人提供的其他证据确认实际发生的工程量。"},{"i":21,"n":"第二十一条","txt":"当事人约定，发包人收到竣工结算文件后，在约定期限内不予答复，视为认可竣工结算文件的，按照约定处理。承包人请求按照竣工结算文件结算工程价款的，人民法院应予支持。"},{"i":22,"n":"第二十二条","txt":"当事人签订的建设工程施工合同与招标文件、投标文件、中标通知书载明的工程范围、建设工期、工程质量、工程价款不一致，一方当事人请求将招标文件、投标文件、中标通知书作为结算工程价款的依据的，人民法院应予支持。"},{"i":23,"n":"第二十三条","txt":"发包人将依法不属于必须招标的建设工程进行招标后，与承包人另行订立的建设工程施工合同背离中标合同的实质性内容，当事人请求以中标合同作为结算建设工程价款依据的，人民法院应予支持，但发包人与承包人因客观情况发生了在招标投标时难以预见的变化而另行订立建设工程施工合同的除外。"},{"i":24,"n":"第二十四条","txt":"当事人就同一建设工程订立的数份建设工程施工合同均无效，但建设工程质量合格，一方当事人请求参照实际履行的合同关于工程价款的约定折价补偿承包人的，人民法院应予支持。"},{"i":25,"n":"第二十五条","txt":"当事人对垫资和垫资利息有约定，承包人请求按照约定返还垫资及其利息的，人民法院应予支持，但是约定的利息计算标准高于垫资时的同类贷款利率或者同期贷款市场报价利率的部分除外。"},{"i":26,"n":"第二十六条","txt":"当事人对欠付工程价款利息计付标准有约定的，按照约定处理。没有约定的，按照同期同类贷款利率或者同期贷款市场报价利率计息。"},{"i":27,"n":"第二十七条","txt":"利息从应付工程价款之日开始计付。当事人对付款时间没有约定或者约定不明的，下列时间视为应付款时间："},{"i":28,"n":"第二十八条","txt":"当事人约定按照固定价结算工程价款，一方当事人请求对建设工程造价进行鉴定的，人民法院不予支持。"},{"i":29,"n":"第二十九条","txt":"当事人在诉讼前已经对建设工程价款结算达成协议，诉讼中一方当事人申请对工程造价进行鉴定的，人民法院不予准许。"},{"i":30,"n":"第三十条","txt":"当事人在诉讼前共同委托有关机构、人员对建设工程造价出具咨询意见，诉讼中一方当事人不认可该咨询意见申请鉴定的，人民法院应予准许，但双方当事人明确表示受该咨询意见约束的除外。"},{"i":31,"n":"第三十一条","txt":"当事人对部分案件事实有争议的，仅对有争议的事实进行鉴定，但争议事实范围不能确定，或者双方当事人请求对全部事实鉴定的除外。"},{"i":32,"n":"第三十二条","txt":"当事人对工程造价、质量、修复费用等专门性问题有争议，人民法院认为需要鉴定的，应当向负有举证责任的当事人释明。当事人经释明未申请鉴定，虽申请鉴定但未支付鉴定费用或者拒不提供相关材料的，应当承担举证不能的法律后果。"},{"i":33,"n":"第三十三条","txt":"人民法院准许当事人的鉴定申请后，应当根据当事人申请及查明案件事实的需要，确定委托鉴定的事项、范围、鉴定期限等，并组织当事人对争议的鉴定材料进行质证。"},{"i":34,"n":"第三十四条","txt":"人民法院应当组织当事人对鉴定意见进行质证。鉴定人将当事人有争议且未经质证的材料作为鉴定依据的，人民法院应当组织当事人就该部分材料进行质证。经质证认为不能作为鉴定依据的，根据该材料作出的鉴定意见不得作为认定案件事实的依据。"},{"i":35,"n":"第三十五条","txt":"与发包人订立建设工程施工合同的承包人，依据民法典第八百零七条的规定请求其承建工程的价款就工程折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":36,"n":"第三十六条","txt":"承包人根据民法典第八百零七条规定享有的建设工程价款优先受偿权优于抵押权和其他债权。"},{"i":37,"n":"第三十七条","txt":"装饰装修工程具备折价或者拍卖条件，装饰装修工程的承包人请求工程价款就该装饰装修工程折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":38,"n":"第三十八条","txt":"建设工程质量合格，承包人请求其承建工程的价款就工程折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":39,"n":"第三十九条","txt":"未竣工的建设工程质量合格，承包人请求其承建工程的价款就其承建工程部分折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":40,"n":"第四十条","txt":"承包人建设工程价款优先受偿的范围依照国务院有关行政主管部门关于建设工程价款范围的规定确定。"},{"i":41,"n":"第四十一条","txt":"承包人应当在合理期限内行使建设工程价款优先受偿权，但最长不得超过十八个月，自发包人应当给付建设工程价款之日起算。"},{"i":42,"n":"第四十二条","txt":"发包人与承包人约定放弃或者限制建设工程价款优先受偿权，损害建筑工人利益，发包人根据该约定主张承包人不享有建设工程价款优先受偿权的，人民法院不予支持。"},{"i":43,"n":"第四十三条","txt":"实际施工人以转包人、违法分包人为被告起诉的，人民法院应当依法受理。"},{"i":44,"n":"第四十四条","txt":"实际施工人依据民法典第五百三十五条规定，以转包人或者违法分包人怠于向发包人行使到期债权或者与该债权有关的从权利，影响其到期债权实现，提起代位权诉讼的，人民法院应予支持。"},{"i":45,"n":"第四十五条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlizhixingyiyizhisuanjifd8cd6":[{"i":1,"n":"第一条","txt":"案外人依照民事诉讼法第二百三十八条规定，在执行过程中就执行标的提出执行异议，由提出异议时负责执行该执行标的人民法院审查处理；案外人、当事人对执行异议裁定不服，自裁定送达之日起十五日内向作出执行异议裁定的执行法院提起执行异议之诉的，人民法院应予受理。"},{"i":2,"n":"第二条","txt":"金钱债权纠纷的财产保全、执行中，执行标的存在轮候查封、扣押、冻结的，案外人提起执行异议之诉，以首先查封、享有担保物权等优先受偿权的申请保全人、申请执行人为被告，以其他已知的轮候查封的申请保全人、申请执行人为第三人。"},{"i":3,"n":"第三条","txt":"案外人就执行标的享有足以排除强制执行的民事权益，人民法院判决不得执行该执行标的的，应同时判决解除执行措施并写明相关查封、扣押、冻结裁定书案号。案外人可以持生效判决请求相关执行法院解除执行措施。"},{"i":4,"n":"第四条","txt":"案外人提起执行异议之诉并依照民法典第二百三十四条等规定就执行标的的归属提出确权请求的，以被执行人为被告。"},{"i":5,"n":"第五条","txt":"案外人提起执行异议之诉并以被执行人等为被告提出返还原物、返还价款或者交付标的物、办理转移登记手续等给付请求的，人民法院可以合并审理，法律另有规定不宜合并审理的，应当分别立案。"},{"i":6,"n":"第六条","txt":"案外人执行异议之诉案件审理期间，申请执行人请求人民法院继续执行并提供相应担保的，由负责审理执行异议之诉的人民法院裁定是否准许。执行法院依法继续执行的，案外人执行异议之诉案件按照下列情形分别处理："},{"i":7,"n":"第七条","txt":"案外人执行异议之诉案件审理或者再审申请审查期间，执行案件已经结案，执行法院未对执行标的进行处分且执行措施已经解除的，人民法院应当裁定终结诉讼或者终结审查。原由执行法院作出的执行异议裁定失效。案外人根据本解释第四条、第五条提出的确权、给付请求，人民法院可以继续审理或者审查。"},{"i":8,"n":"第八条","txt":"执行异议之诉案件审理或者再审申请审查期间，人民法院对作为执行依据的原判决、裁定等依法决定再审，执行标的系原判决、裁定等所涉争议标的以外的财产，或者案外人可能享有足以排除担保物权等优先受偿权的强制执行的民事权益的，执行异议之诉案件可以继续审理或者审查，不能认定案外人享有足以排除强制执行的民事权益的，执行异议之诉案件应当中止审理或者审查。"},{"i":9,"n":"第九条","txt":"执行异议之诉案件审理或者再审申请审查期间，人民法院裁定受理被执行人破产案件的，执行异议之诉案件应当中止审理或者审查，管理人接管债务人财产后，执行异议之诉案件可以继续审理或者审查。"},{"i":10,"n":"第十条","txt":"案外人执行异议之诉案件经审判监督程序发现支持案外人排除强制执行确有错误，人民法院认定案外人不享有足以排除强制执行的民事权益，判决驳回案外人诉讼请求的，原相关执行法院按照原顺位恢复执行；执行标的已合法转让给他人，人民法院裁定撤销原判决、终结诉讼的，申请执行人可以依法另行向被执行人、案外人等主张权利。"},{"i":11,"n":"第十一条","txt":"人民法院对登记在被执行的房地产开发企业名下的新建商品房实施强制执行，案外人以其系商品房消费者为由，提起执行异议之诉，请求排除建设工程价款优先受偿权、抵押权以及一般金钱债权的强制执行，并能够证明其主张同时符合下列条件的，人民法院应予支持："},{"i":12,"n":"第十二条","txt":"执行法院冻结被执行的房地产开发企业的预售资金监管账户，案外人以其已向该账户交付购房款，且房屋买卖合同已经解除为由，提起执行异议之诉，请求排除相应购房款的强制执行并申请向其发放，事由成立的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"人民法院对登记在被执行人名下的不动产实施强制执行，案外人以其系不动产的买受人为由，提起执行异议之诉，请求排除建设工程价款优先受偿权、抵押权以及一般金钱债权的强制执行，案外人与被执行人签订合法有效的书面买卖合同且在一审法庭辩论终结前交付执行法院的价款足以代为清偿相应主债权的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"人民法院对登记在被执行人名下的不动产实施强制执行，案外人以其系该不动产买受人为由，提起执行异议之诉，请求排除一般金钱债权的强制执行，并能够证明其主张同时符合下列条件的，人民法院应予支持："},{"i":15,"n":"第十五条","txt":"人民法院对登记在被执行人名下的不动产实施强制执行，案外人以被执行人已将该不动产向其抵偿债务为由，提起执行异议之诉，请求排除一般金钱债权的强制执行，并能够证明其主张同时符合下列条件的，人民法院应予支持："},{"i":16,"n":"第十六条","txt":"人民法院查封前，符合下列情形之一，可以认定为本解释第十四条、第十五条中的“非因案外人自身原因”："},{"i":17,"n":"第十七条","txt":"人民法院对登记在被执行的发包人名下的不动产实施强制执行，案外人以其与被执行人约定以不动产折抵工程债务为由，提起执行异议之诉，请求排除抵押权和一般金钱债权的强制执行，并能够证明其主张同时符合下列条件的，人民法院应予支持："},{"i":18,"n":"第十八条","txt":"人民法院对登记在被执行人名下的不动产实施强制执行，案外人以该不动产系用于产权调换的征收补偿为由，提起执行异议之诉，请求排除建设工程价款优先受偿权、抵押权以及其他债权的强制执行，并能够证明其主张同时符合下列条件的，人民法院应予支持："},{"i":19,"n":"第十九条","txt":"人民法院对登记在被执行人名下的不动产实施强制执行，案外人以在查封前已与被执行人签订合法有效的书面买卖合同且已按照合同约定支付价款，并已办理了合法有效的不动产预告登记为由，提起执行异议之诉，请求停止处分，事由成立的，人民法院应予支持；符合物权登记条件，案外人请求排除强制执行的，人民法院应予支持。"},{"i":20,"n":"第二十条","txt":"不带租拍卖、变卖等情况下的强制执行中，案外人以在查封前已与被执行人签订合法有效的书面租赁合同并合法占有使用执行标的，且已按照合同约定支付租金为由，提起执行异议之诉，请求在租赁期内排除一般债权的不带租强制执行，事由成立的，人民法院应予支持；符合上述规定条件的案外人签订租赁合同及合法占有使用执行标的均在抵押权设立之前，请求在租赁期内排除抵押权的不带租强制执行的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"案外人与被执行人、申请执行人之间恶意串通，通过伪造证据，或者单方捏造案件基本事实，以执行异议之诉妨碍依法执行的，人民法院应当驳回其诉讼请求，并根据情节轻重予以罚款、拘留；涉嫌刑事犯罪的，人民法院应当将犯罪线索移送公安机关。"},{"i":22,"n":"第二十二条","txt":"申请执行人依照民事诉讼法第二百三十八条规定提起执行异议之诉的，参照本解释的相关规定处理。"},{"i":23,"n":"第二十三条","txt":"本解释自2025年7月24日起施行。"}],"zuigaorenminfayuanguanyushenliraoluandianxinshicha9856ca":[{"i":1,"n":"第一条","txt":"违反国家规定，采取租用国际专线、私设转接设备或者其他方法，擅自经营国际电信业务或者涉港澳台电信业务进行营利活动，扰乱电信市场管理秩序，情节严重的，依照刑法第二百二十五条第（四）项的规定，以非法经营罪定罪处罚。"},{"i":2,"n":"第二条","txt":"实施本解释第一条规定的行为，具有下列情形之一的，属于非法经营行为“情节严重”："},{"i":3,"n":"第三条","txt":"实施本解释第一条规定的行为，经营数额或者造成电信资费损失数额接近非法经营行为“情节严重”、“情节特别严重”的数额起点标准，并具有下列情形之一的，可以分别认定为非法经营行为“情节严重”、“情节特别严重”："},{"i":4,"n":"第四条","txt":"单位实施本解释第一条规定的行为构成犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本解释第二条、第三条的规定处罚。"},{"i":5,"n":"第五条","txt":"违反国家规定，擅自设置、使用无线电台（站），或者擅自占用频率，非法经营国际电信业务或者涉港澳台电信业务进行营利活动，同时构成非法经营罪和刑法第二百八十八条规定的扰乱无线电通讯管理秩序罪的，依照处罚较重的规定定罪处罚。"},{"i":6,"n":"第六条","txt":"国有电信企业的工作人员，由于严重不负责任或者滥用职权，造成国有电信企业破产或者严重损失，致使国家利益遭受重大损失的，依照刑法第一百六十八条的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"将电信卡非法充值后使用，造成电信资费损失数额较大的，依照刑法第二百六十四条的规定，以盗窃罪定罪处罚。"},{"i":8,"n":"第八条","txt":"盗用他人公共信息网络上网账号、密码上网，造成他人电信资费损失数额较大的，依照刑法第二百六十四条的规定，以盗窃罪定罪处罚。"},{"i":9,"n":"第九条","txt":"以虚假、冒用的身份证件办理入网手续并使用移动电话，造成电信资费损失数额较大的，依照刑法第二百六十六条的规定，以诈骗罪定罪处罚。"},{"i":10,"n":"第十条","txt":"本解释所称“经营去话业务数额”，是指以行为人非法经营国际电信业务或者涉港澳台电信业务的总时长（分钟数）乘以行为人每分钟收取的用户使用费所得的数额。"}],"zuigaorenminfayuanguanyushenlijishuhetongjiufenanj695533":[{"i":1,"n":"第一条","txt":"技术成果，是指利用科学技术知识、信息和经验作出的涉及产品、工艺、材料及其改进等的技术方案，包括专利、专利申请、技术秘密、计算机软件、集成电路布图设计、植物新品种等。"},{"i":2,"n":"第二条","txt":"民法典第八百四十七条第二款所称“执行法人或者非法人组织的工作任务”，包括："},{"i":3,"n":"第三条","txt":"民法典第八百四十七条第二款所称“物质技术条件”，包括资金、设备、器材、原材料、未公开的技术信息和资料等。"},{"i":4,"n":"第四条","txt":"民法典第八百四十七条第二款所称“主要是利用法人或者非法人组织的物质技术条件”，包括职工在技术成果的研究开发过程中，全部或者大部分利用了法人或者非法人组织的资金、设备、器材或者原材料等物质条件，并且这些物质条件对形成该技术成果具有实质性的影响；还包括该技术成果实质性内容是在法人或者非法人组织尚未公开的技术成果、阶段性技术成果基础上完成的情形。但下列情况除外："},{"i":5,"n":"第五条","txt":"个人完成的技术成果，属于执行原所在法人或者非法人组织的工作任务，又主要利用了现所在法人或者非法人组织的物质技术条件的，应当按照该自然人原所在和现所在法人或者非法人组织达成的协议确认权益。不能达成协议的，根据对完成该项技术成果的贡献大小由双方合理分享。"},{"i":6,"n":"第六条","txt":"民法典第八百四十七条所称“职务技术成果的完成人”、第八百四十八条所称“完成技术成果的个人”，包括对技术成果单独或者共同作出创造性贡献的人，也即技术成果的发明人或者设计人。人民法院在对创造性贡献进行认定时，应当分解所涉及技术成果的实质性技术构成。提出实质性技术构成并由此实现技术方案的人，是作出创造性贡献的人。"},{"i":7,"n":"第七条","txt":"不具有民事主体资格的科研组织订立的技术合同，经法人或者非法人组织授权或者认可的，视为法人或者非法人组织订立的合同，由法人或者非法人组织承担责任；未经法人或者非法人组织授权或者认可的，由该科研组织成员共同承担责任，但法人或者非法人组织因该合同受益的，应当在其受益范围内承担相应责任。"},{"i":8,"n":"第八条","txt":"生产产品或者提供服务依法须经有关部门审批或者取得行政许可，而未经审批或者许可的，不影响当事人订立的相关技术合同的效力。"},{"i":9,"n":"第九条","txt":"当事人一方采取欺诈手段，就其现有技术成果作为研究开发标的与他人订立委托开发合同收取研究开发费用，或者就同一研究开发课题先后与两个或者两个以上的委托人分别订立委托开发合同重复收取研究开发费用，使对方在违背真实意思的情况下订立的合同，受损害方依照民法典第一百四十八条规定请求撤销合同的，人民法院应当予以支持。"},{"i":10,"n":"第十条","txt":"下列情形，属于民法典第八百五十条所称的“非法垄断技术”："},{"i":11,"n":"第十一条","txt":"技术合同无效或者被撤销后，技术开发合同研究开发人、技术转让合同让与人、技术许可合同许可人、技术咨询合同和技术服务合同的受托人已经履行或者部分履行了约定的义务，并且造成合同无效或者被撤销的过错在对方的，对其已履行部分应当收取的研究开发经费、技术使用费、提供咨询服务的报酬，人民法院可以认定为因对方原因导致合同无效或者被撤销给其造成的损失。"},{"i":12,"n":"第十二条","txt":"根据民法典第八百五十条的规定，侵害他人技术秘密的技术合同被确认无效后，除法律、行政法规另有规定的以外，善意取得该技术秘密的一方当事人可以在其取得时的范围内继续使用该技术秘密，但应当向权利人支付合理的使用费并承担保密义务。"},{"i":13,"n":"第十三条","txt":"依照前条第一款规定可以继续使用技术秘密的人与权利人就使用费支付发生纠纷的，当事人任何一方都可以请求人民法院予以处理。继续使用技术秘密但又拒不支付使用费的，人民法院可以根据权利人的请求判令使用人停止使用。"},{"i":14,"n":"第十四条","txt":"对技术合同的价款、报酬和使用费，当事人没有约定或者约定不明确的，人民法院可以按照以下原则处理："},{"i":15,"n":"第十五条","txt":"技术合同当事人一方迟延履行主要债务，经催告后在30日内仍未履行，另一方依据民法典第五百六十三条第一款第（三）项的规定主张解除合同的，人民法院应当予以支持。"},{"i":16,"n":"第十六条","txt":"当事人以技术成果向企业出资但未明确约定权属，接受出资的企业主张该技术成果归其享有的，人民法院一般应当予以支持，但是该技术成果价值与该技术成果所占出资额比例明显不合理损害出资人利益的除外。"},{"i":17,"n":"第十七条","txt":"民法典第八百五十一条第一款所称“新技术、新产品、新工艺、新品种或者新材料及其系统”，包括当事人在订立技术合同时尚未掌握的产品、工艺、材料及其系统等技术方案，但对技术上没有创新的现有产品的改型、工艺变更、材料配方调整以及对技术成果的验证、测试和使用除外。"},{"i":18,"n":"第十八条","txt":"民法典第八百五十一条第四款规定的“当事人之间就具有实用价值的科技成果实施转化订立的”技术转化合同，是指当事人之间就具有实用价值但尚未实现工业化应用的科技成果包括阶段性技术成果，以实现该科技成果工业化应用为目标，约定后续试验、开发和应用等内容的合同。"},{"i":19,"n":"第十九条","txt":"民法典第八百五十五条所称“分工参与研究开发工作”，包括当事人按照约定的计划和分工，共同或者分别承担设计、工艺、试验、试制等工作。"},{"i":20,"n":"第二十条","txt":"民法典第八百六十一条所称“当事人均有使用和转让的权利”，包括当事人均有不经对方同意而自己使用或者以普通使用许可的方式许可他人使用技术秘密，并独占由此所获利益的权利。当事人一方将技术秘密成果的转让权让与他人，或者以独占或者排他使用许可的方式许可他人使用技术秘密，未经对方当事人同意或者追认的，应当认定该让与或者许可行为无效。"},{"i":21,"n":"第二十一条","txt":"技术开发合同当事人依照民法典的规定或者约定自行实施专利或使用技术秘密，但因其不具备独立实施专利或者使用技术秘密的条件，以一个普通许可方式许可他人实施或者使用的，可以准许。"},{"i":22,"n":"第二十二条","txt":"就尚待研究开发的技术成果或者不涉及专利、专利申请或者技术秘密的知识、技术、经验和信息所订立的合同，不属于民法典第八百六十二条规定的技术转让合同或者技术许可合同。"},{"i":23,"n":"第二十三条","txt":"专利申请权转让合同当事人以专利申请被驳回或者被视为撤回为由请求解除合同，该事实发生在依照专利法第十条第三款的规定办理专利申请权转让登记之前的，人民法院应当予以支持；发生在转让登记之后的，不予支持，但当事人另有约定的除外。"},{"i":24,"n":"第二十四条","txt":"订立专利权转让合同或者专利申请权转让合同前，让与人自己已经实施发明创造，在合同生效后，受让人要求让与人停止实施的，人民法院应当予以支持，但当事人另有约定的除外。"},{"i":25,"n":"第二十五条","txt":"专利实施许可包括以下方式："},{"i":26,"n":"第二十六条","txt":"专利实施许可合同许可人负有在合同有效期内维持专利权有效的义务，包括依法缴纳专利年费和积极应对他人提出宣告专利权无效的请求，但当事人另有约定的除外。"},{"i":27,"n":"第二十七条","txt":"排他实施许可合同许可人不具备独立实施其专利的条件，以一个普通许可的方式许可他人实施专利的，人民法院可以认定为许可人自己实施专利，但当事人另有约定的除外。"},{"i":28,"n":"第二十八条","txt":"民法典第八百六十四条所称“实施专利或者使用技术秘密的范围”，包括实施专利或者使用技术秘密的期限、地域、方式以及接触技术秘密的人员等。"},{"i":29,"n":"第二十九条","txt":"当事人之间就申请专利的技术成果所订立的许可使用合同，专利申请公开以前，适用技术秘密许可合同的有关规定；发明专利申请公开以后、授权以前，参照适用专利实施许可合同的有关规定；授权以后，原合同即为专利实施许可合同，适用专利实施许可合同的有关规定。"},{"i":30,"n":"第三十条","txt":"民法典第八百七十八条第一款所称“特定技术项目”，包括有关科学技术与经济社会协调发展的软科学研究项目，促进科技进步和管理现代化、提高经济效益和社会效益等运用科学知识和技术手段进行调查、分析、论证、评价、预测的专业性技术项目。"},{"i":31,"n":"第三十一条","txt":"当事人对技术咨询合同委托人提供的技术资料和数据或者受托人提出的咨询报告和意见未约定保密义务，当事人一方引用、发表或者向第三人提供的，不认定为违约行为，但侵害对方当事人对此享有的合法权益的，应当依法承担民事责任。"},{"i":32,"n":"第三十二条","txt":"技术咨询合同受托人发现委托人提供的资料、数据等有明显错误或者缺陷，未在合理期限内通知委托人的，视为其对委托人提供的技术资料、数据等予以认可。委托人在接到受托人的补正通知后未在合理期限内答复并予补正的，发生的损失由委托人承担。"},{"i":33,"n":"第三十三条","txt":"民法典第八百七十八条第二款所称“特定技术问题”，包括需要运用专业技术知识、经验和信息解决的有关改进产品结构、改良工艺流程、提高产品质量、降低产品成本、节约资源能耗、保护资源环境、实现安全操作、提高经济效益和社会效益等专业技术问题。"},{"i":34,"n":"第三十四条","txt":"当事人一方以技术转让或者技术许可的名义提供已进入公有领域的技术，或者在技术转让合同、技术许可合同履行过程中合同标的技术进入公有领域，但是技术提供方进行技术指导、传授技术知识，为对方解决特定技术问题符合约定条件的，按照技术服务合同处理，约定的技术转让费、使用费可以视为提供技术服务的报酬和费用，但是法律、行政法规另有规定的除外。"},{"i":35,"n":"第三十五条","txt":"技术服务合同受托人发现委托人提供的资料、数据、样品、材料、场地等工作条件不符合约定，未在合理期限内通知委托人的，视为其对委托人提供的工作条件予以认可。委托人在接到受托人的补正通知后未在合理期限内答复并予补正的，发生的损失由委托人承担。"},{"i":36,"n":"第三十六条","txt":"民法典第八百八十七条规定的“技术培训合同”，是指当事人一方委托另一方对指定的学员进行特定项目的专业技术训练和技术指导所订立的合同，不包括职业培训、文化学习和按照行业、法人或者非法人组织的计划进行的职工业余教育。"},{"i":37,"n":"第三十七条","txt":"当事人对技术培训必需的场地、设施和试验条件等工作条件的提供和管理责任没有约定或者约定不明确的，由委托人负责提供和管理。"},{"i":38,"n":"第三十八条","txt":"民法典第八百八十七条规定的“技术中介合同”，是指当事人一方以知识、技术、经验和信息为另一方与第三人订立技术合同进行联系、介绍以及对履行合同提供专门服务所订立的合同。"},{"i":39,"n":"第三十九条","txt":"中介人从事中介活动的费用，是指中介人在委托人和第三人订立技术合同前，进行联系、介绍活动所支出的通信、交通和必要的调查研究等费用。中介人的报酬，是指中介人为委托人与第三人订立技术合同以及对履行该合同提供服务应当得到的收益。"},{"i":40,"n":"第四十条","txt":"中介人未促成委托人与第三人之间的技术合同成立的，其要求支付报酬的请求，人民法院不予支持；其要求委托人支付其从事中介活动必要费用的请求，应当予以支持，但当事人另有约定的除外。"},{"i":41,"n":"第四十一条","txt":"中介人对造成委托人与第三人之间的技术合同的无效或者被撤销没有过错，并且该技术合同的无效或者被撤销不影响有关中介条款或者技术中介合同继续有效，中介人要求按照约定或者本解释的有关规定给付从事中介活动的费用和报酬的，人民法院应当予以支持。"},{"i":42,"n":"第四十二条","txt":"当事人将技术合同和其他合同内容或者将不同类型的技术合同内容订立在一个合同中的，应当根据当事人争议的权利义务内容，确定案件的性质和案由。"},{"i":43,"n":"第四十三条","txt":"技术合同纠纷案件一般由中级以上人民法院管辖。"},{"i":44,"n":"第四十四条","txt":"一方当事人以诉讼争议的技术合同侵害他人技术成果为由请求确认合同无效，或者人民法院在审理技术合同纠纷中发现可能存在该无效事由的，人民法院应当依法通知有关利害关系人，其可以作为有独立请求权的第三人参加诉讼或者依法向有管辖权的人民法院另行起诉。"},{"i":45,"n":"第四十五条","txt":"第三人向受理技术合同纠纷案件的人民法院就合同标的技术提出权属或者侵权请求时，受诉人民法院对此也有管辖权的，可以将权属或者侵权纠纷与合同纠纷合并审理；受诉人民法院对此没有管辖权的，应当告知其向有管辖权的人民法院另行起诉或者将已经受理的权属或者侵权纠纷案件移送有管辖权的人民法院。权属或者侵权纠纷另案受理后，合同纠纷应当中止诉讼。"},{"i":46,"n":"第四十六条","txt":"计算机软件开发等合同争议，著作权法以及其他法律、行政法规另有规定的，依照其规定；没有规定的，适用民法典第三编第一分编的规定，并可以参照民法典第三编第二分编第二十章和本解释的有关规定处理。"},{"i":47,"n":"第四十七条","txt":"本解释自2005年1月1日起施行。"}],"zuigaorenminfayuanguanyushenliqiangjieanjianjutiyi5a0c36":[{"i":1,"n":"第一条","txt":"刑法第二百六十三条第（一）项规定的“入户抢劫”，是指为实施抢劫行为而进入他人生活的与外界相对隔离的住所，包括封闭的院落、牧民的帐篷、渔民作为家庭生活场所的渔船、为生活租用的房屋等进行抢劫的行为。"},{"i":2,"n":"第二条","txt":"刑法第二百六十三条第（二）项规定的“在公共交通工具上抢劫”，既包括在从事旅客运输的各种公共汽车，大、中型出租车，火车，船只，飞机等正在运营中的机动公共交通工具上对旅客、司售、乘务人员实施的抢劫，也包括对运行途中的机动公共交通工具加以拦截后，对公共交通工具上的人员实施的抢劫。"},{"i":3,"n":"第三条","txt":"刑法第二百六十三条第（三）项规定的“抢劫银行或者其他金融机构”，是指抢劫银行或者其他金融机构的经营资金、有价证券和客户的资金等。"},{"i":4,"n":"第四条","txt":"刑法第二百六十三条第（四）项规定的“抢劫数额巨大”的认定标准，参照各地确定的盗窃罪数额巨大的认定标准执行。"},{"i":5,"n":"第五条","txt":"刑法第二百六十三条第（七）项规定的“持枪抢劫”，是指行为人使用枪支或者向被害人显示持有、佩带的枪支进行抢劫的行为。“枪支”的概念和范围，适用《中华人民共和国枪支管理法》的规定。"},{"i":6,"n":"第六条","txt":"刑法第二百六十七条第二款规定的“携带凶器抢夺”，是指行为人随身携带枪支、爆炸物、管制刀具等国家禁止个人携带的器械进行抢夺或者为了实施犯罪而携带其他器械进行抢夺的行为。"}],"zuigaorenminfayuanguanyushenliguaimaifunvertongfanf1c0cf":[{"i":1,"n":"第一条","txt":"对婴幼儿采取欺骗、利诱等手段使其脱离监护人或者看护人的，视为刑法第二百四十条第一款第（六）项规定的“偷盗婴幼儿”。"},{"i":2,"n":"第二条","txt":"医疗机构、社会福利机构等单位的工作人员以非法获利为目的，将所诊疗、护理、抚养的儿童出卖给他人的，以拐卖儿童罪论处。"},{"i":3,"n":"第三条","txt":"以介绍婚姻为名，采取非法扣押身份证件、限制人身自由等方式，或者利用妇女人地生疏、语言不通、孤立无援等境况，违背妇女意志，将其出卖给他人的，应当以拐卖妇女罪追究刑事责任。"},{"i":4,"n":"第四条","txt":"在国家机关工作人员排查来历不明儿童或者进行解救时，将所收买的儿童藏匿、转移或者实施其他妨碍解救行为，经说服教育仍不配合的，属于刑法第二百四十一条第六款规定的“阻碍对其进行解救”。"},{"i":5,"n":"第五条","txt":"收买被拐卖的妇女，业已形成稳定的婚姻家庭关系，解救时被买妇女自愿继续留在当地共同生活的，可以视为“按照被买妇女的意愿，不阻碍其返回原居住地”。"},{"i":6,"n":"第六条","txt":"收买被拐卖的妇女、儿童后又组织、强迫卖淫或者组织乞讨、进行违反治安管理活动等构成其他犯罪的，依照数罪并罚的规定处罚。"},{"i":7,"n":"第七条","txt":"收买被拐卖的妇女、儿童，又以暴力、威胁方法阻碍国家机关工作人员解救被收买的妇女、儿童，或者聚众阻碍国家机关工作人员解救被收买的妇女、儿童，构成妨害公务罪、聚众阻碍解救被收买的妇女、儿童罪的，依照数罪并罚的规定处罚。"},{"i":8,"n":"第八条","txt":"出于结婚目的收买被拐卖的妇女，或者出于抚养目的收买被拐卖的儿童，涉及多名家庭成员、亲友参与的，对其中起主要作用的人员应当依法追究刑事责任。"},{"i":9,"n":"第九条","txt":"刑法第二百四十条、第二百四十一条规定的儿童，是指不满十四周岁的人。其中，不满一周岁的为婴儿，一周岁以上不满六周岁的为幼儿。"},{"i":10,"n":"第十条","txt":"本解释自2017年1月1日起施行。"}],"zuigaorenminfayuanguanyushenliguaimaifunvanjianshi3ce065":[{"i":1,"n":"第一条","txt":"刑法第二百四十条规定的拐卖妇女罪中的“妇女”，既包括具有中国国籍的妇女，也包括具有外国国籍和无国籍的妇女。被拐卖的外国妇女没有身份证明的，不影响对犯罪分子的定罪处罚。"},{"i":2,"n":"第二条","txt":"外国人或者无国籍人拐卖外国妇女到我国境内被查获的，应当根据刑法第六条的规定，适用我国刑法定罪处罚。"},{"i":3,"n":"第三条","txt":"对于外国籍被告人身份无法查明或者其国籍国拒绝提供有关身份证明，人民检察院根据刑事诉讼法第一百二十八条第二款的规定起诉的案件，人民法院应当依法受理。"}],"zuigaorenminfayuanguanyushenlijubuzhifulaodongbaoc96db6f":[{"i":1,"n":"第一条","txt":"劳动者依照《中华人民共和国劳动法》和《中华人民共和国劳动合同法》等法律的规定应得的劳动报酬，包括工资、奖金、津贴、补贴、延长工作时间的工资报酬及特殊情况下支付的工资等，应当认定为刑法第二百七十六条之一第一款规定的“劳动者的劳动报酬”。"},{"i":2,"n":"第二条","txt":"以逃避支付劳动者的劳动报酬为目的，具有下列情形之一的，应当认定为刑法第二百七十六条之一第一款规定的“以转移财产、逃匿等方法逃避支付劳动者的劳动报酬”："},{"i":3,"n":"第三条","txt":"具有下列情形之一的，应当认定为刑法第二百七十六条之一第一款规定的“数额较大”："},{"i":4,"n":"第四条","txt":"经人力资源社会保障部门或者政府其他有关部门依法以限期整改指令书、行政处理决定书等文书责令支付劳动者的劳动报酬后，在指定的期限内仍不支付的，应当认定为刑法第二百七十六条之一第一款规定的“经政府有关部门责令支付仍不支付”，但有证据证明行为人有正当理由未知悉责令支付或者未及时支付劳动报酬的除外。"},{"i":5,"n":"第五条","txt":"拒不支付劳动者的劳动报酬，符合本解释第三条的规定，并具有下列情形之一的，应当认定为刑法第二百七十六条之一第一款规定的“造成严重后果”："},{"i":6,"n":"第六条","txt":"拒不支付劳动者的劳动报酬，尚未造成严重后果，在刑事立案前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以认定为情节显著轻微危害不大，不认为是犯罪；在提起公诉前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以减轻或者免除刑事处罚；在一审宣判前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以从轻处罚。"},{"i":7,"n":"第七条","txt":"不具备用工主体资格的单位或者个人，违法用工且拒不支付劳动者的劳动报酬，数额较大，经政府有关部门责令支付仍不支付的，应当依照刑法第二百七十六条之一的规定，以拒不支付劳动报酬罪追究刑事责任。"},{"i":8,"n":"第八条","txt":"用人单位的实际控制人实施拒不支付劳动报酬行为，构成犯罪的，应当依照刑法第二百七十六条之一的规定追究刑事责任。"},{"i":9,"n":"第九条","txt":"单位拒不支付劳动报酬，构成犯罪的，依照本解释规定的相应个人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"}],"zuigaorenminfayuanguanyushenlinuoyonggongkuananjia6e3494":[{"i":1,"n":"第一条","txt":"刑法第三百八十四条规定的“挪用公款归个人使用”，包括挪用者本人使用或者给他人使用。"},{"i":2,"n":"第二条","txt":"对挪用公款罪，应区分3种不同情况予以认定："},{"i":3,"n":"第三条","txt":"挪用公款归个人使用，“数额较大、进行营利活动的”，或者“数额较大、超过3个月未还的”，以挪用公款1万元至3万元为“数额较大”的起点，以挪用公款15万元至20万元为“数额巨大”的起点。挪用公款“情节严重”，是指挪用公款数额巨大，或者数额虽未达到巨大，但挪用公款手段恶劣；多次挪用公款；因挪用公款严重影响生产、经营，造成严重损失等情形。"},{"i":4,"n":"第四条","txt":"多次挪用公款不还，挪用公款数额累计计算；多次挪用公款，并以后次挪用的公款归还前次挪用的公款，挪用公款数额以案发时未还的实际数额认定。"},{"i":5,"n":"第五条","txt":"“挪用公款数额巨大不退还的”，是指挪用公款数额巨大，因客观原因在一审宣判前不能退还的。"},{"i":6,"n":"第六条","txt":"携带挪用的公款潜逃的，依照刑法第三百八十二条、第三百八十三条的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"因挪用公款索取、收受贿赂构成犯罪的，依照数罪并罚的规定处罚。"},{"i":8,"n":"第八条","txt":"挪用公款给他人使用，使用人与挪用人共谋，指使或者参与策划取得挪用款的，以挪用公款罪的共犯定罪处罚。"}],"zuigaorenminfayuanguanyushenlizhengfuxinxigongkaix04d285":[{"i":1,"n":"第一条","txt":"公民、法人或者其他组织认为下列涉政府信息公开行为侵犯其合法权益，依法提起行政诉讼的，人民法院应当受理："},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为行政机关不依法履行主动公开政府信息职责，直接向人民法院提起诉讼的，应当告知其先向行政机关申请获取政府信息。"},{"i":3,"n":"第三条","txt":"认为行政机关作出的政府信息公开、不予公开等行为侵害其合法权益提起诉讼的公民、法人或者其他组织，属于行政诉讼法第二十五条第一款规定的“有利害关系的公民、法人或者其他组织”。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对主动公开政府信息行为不服提起诉讼的，以公开该政府信息的行政机关为被告。"},{"i":5,"n":"第五条","txt":"被告对其作出的政府信息公开、不予公开等行为的合法性承担举证责任。"},{"i":6,"n":"第六条","txt":"被告主张原告申请公开的信息系国家秘密不予公开，并提供密级标识、保密期限或者其他证明材料的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"原告应当就下列事项承担举证责任："},{"i":8,"n":"第八条","txt":"人民法院审理第一审政府信息公开案件，可以适用简易程序。"},{"i":9,"n":"第九条","txt":"政府信息由被告的档案机构或者档案工作人员保管的，适用政府信息公开条例的相关规定。"},{"i":10,"n":"第十条","txt":"公民、法人或者其他组织提起的涉政府信息公开诉讼明显不符合行政诉讼法规定的起诉条件的，人民法院不予登记立案。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，人民法院判决被告履行政府信息公开职责："},{"i":12,"n":"第十二条","txt":"有下列情形之一的，人民法院判决确认违法："},{"i":13,"n":"第十三条","txt":"政府信息尚未公开前，原告起诉要求被告不得公开政府信息的，人民法院经审理认为政府信息涉及原告商业秘密、个人隐私且不存在不公开会对公共利益造成重大影响的，应当判决被告不得公开政府信息。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，人民法院判决驳回原告的诉讼请求："},{"i":15,"n":"第十五条","txt":"本解释自2025年6月1日起施行。"}],"zuigaorenminfayuanguanyushenliweichengnianrenxings817921":[{"i":1,"n":"第一条","txt":"本解释所称未成年人刑事案件，是指被告人实施被指控的犯罪时已满十四周岁不满十八周岁的案件。"},{"i":2,"n":"第二条","txt":"刑法第十七条规定的“周岁”，按照公历的年、月、日计算，从周岁生日的第二天起算。"},{"i":3,"n":"第三条","txt":"审理未成年人刑事案件，应当查明被告人实施被指控的犯罪时的年龄。裁判文书中应当写明被告人出生的年、月、日。"},{"i":4,"n":"第四条","txt":"对于没有充分证据证明被告人实施被指控的犯罪时已经达到法定刑事责任年龄且确实无法查明的，应当推定其没有达到相应法定刑事责任年龄。"},{"i":5,"n":"第五条","txt":"已满十四周岁不满十六周岁的人实施刑法第十七条第二款规定以外的行为，如果同时触犯了刑法第十七条第二款规定的，应当依照刑法第十七条第二款的规定确定罪名，定罪处罚。"},{"i":6,"n":"第六条","txt":"已满十四周岁不满十六周岁的人偶尔与幼女发生性行为，情节轻微、未造成严重后果的，不认为是犯罪。"},{"i":7,"n":"第七条","txt":"已满十四周岁不满十六周岁的人使用轻微暴力或者威胁，强行索要其他未成年人随身携带的生活、学习用品或者钱财数量不大，且未造成被害人轻微伤以上或者不敢正常到校学习、生活等危害后果的，不认为是犯罪。"},{"i":8,"n":"第八条","txt":"已满十六周岁不满十八周岁的人出于以大欺小、以强凌弱或者寻求精神刺激，随意殴打其他未成年人、多次对其他未成年人强拿硬要或者任意损毁公私财物，扰乱学校及其他公共场所秩序，情节严重的，以寻衅滋事罪定罪处罚。"},{"i":9,"n":"第九条","txt":"已满十六周岁不满十八周岁的人实施盗窃行为未超过三次，盗窃数额虽已达到“数额较大”标准，但案发后能如实供述全部盗窃事实并积极退赃，且具有下列情形之一的，可以认定为“情节显著轻微危害不大”，不认为是犯罪："},{"i":10,"n":"第十条","txt":"已满十四周岁不满十六周岁的人盗窃、诈骗、抢夺他人财物，为窝藏赃物、抗拒抓捕或者毁灭罪证，当场使用暴力，故意伤害致人重伤或者死亡，或者故意杀人的，应当分别以故意伤害罪或者故意杀人罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"对未成年罪犯适用刑罚，应当充分考虑是否有利于未成年罪犯的教育和矫正。"},{"i":12,"n":"第十二条","txt":"行为人在达到法定刑事责任年龄前后均实施了危害社会的行为，只能依法追究其达到法定刑事责任年龄后实施的危害社会行为的刑事责任。"},{"i":13,"n":"第十三条","txt":"未成年人犯罪只有罪行极其严重的，才可以适用无期徒刑。对已满十四周岁不满十六周岁的人犯罪一般不判处无期徒刑。"},{"i":14,"n":"第十四条","txt":"除刑法规定“应当”附加剥夺政治权利外，对未成年罪犯一般不判处附加剥夺政治权利。"},{"i":15,"n":"第十五条","txt":"对未成年罪犯实施刑法规定的“并处”没收财产或者罚金的犯罪，应当依法判处相应的财产刑；对未成年罪犯实施刑法规定的“可以并处”没收财产或者罚金的犯罪，一般不判处财产刑。"},{"i":16,"n":"第十六条","txt":"对未成年罪犯符合刑法第七十二条第一款规定的，可以宣告缓刑。如果同时具有下列情形之一，对其适用缓刑确实不致再危害社会的，应当宣告缓刑："},{"i":17,"n":"第十七条","txt":"未成年罪犯根据其所犯罪行，可能被判处拘役、三年以下有期徒刑，如果悔罪表现好，并具有下列情形之一的，应当依照刑法第三十七条的规定免予刑事处罚："},{"i":18,"n":"第十八条","txt":"对未成年罪犯的减刑、假释，在掌握标准上可以比照成年罪犯依法适度放宽。"},{"i":19,"n":"第十九条","txt":"刑事附带民事案件的未成年被告人有个人财产的，应当由本人承担民事赔偿责任，不足部分由监护人予以赔偿，但单位担任监护人的除外。"},{"i":20,"n":"第二十条","txt":"本解释自公布之日起施行。"}],"zuigaorenminfayuanguanyushenlisenlinziyuanminshiji538a8d":[{"i":1,"n":"第一条","txt":"人民法院审理涉及森林、林木、林地等森林资源的民事纠纷案件，应当贯彻民法典绿色原则，尊重自然、尊重历史、尊重习惯，依法推动森林资源保护和利用的生态效益、经济效益、社会效益相统一，促进人与自然和谐共生。"},{"i":2,"n":"第二条","txt":"当事人因下列行为，对林地、林木的物权归属、内容产生争议，依据民法典第二百三十四条的规定提起民事诉讼，请求确认权利的，人民法院应当依法受理："},{"i":3,"n":"第三条","txt":"当事人以未办理批准、登记、备案、审查、审核等手续为由，主张林地承包、林地承包经营权互换或者转让、林地经营权流转、林木流转、森林资源担保等合同无效的，人民法院不予支持。"},{"i":4,"n":"第四条","txt":"当事人一方未依法经林权证等权利证书载明的共有人同意，擅自处分林地、林木，另一方主张取得相关权利的，人民法院不予支持。但符合民法典第三百一十一条关于善意取得规定的除外。"},{"i":5,"n":"第五条","txt":"当事人以违反法律规定的民主议定程序为由，主张集体林地承包合同无效的，人民法院应予支持。但下列情形除外："},{"i":6,"n":"第六条","txt":"家庭承包林地的承包方转让林地承包经营权未经发包方同意，或者受让方不是本集体经济组织成员，受让方主张取得林地承包经营权的，人民法院不予支持。但发包方无法定理由不同意或者拖延表态的除外。"},{"i":7,"n":"第七条","txt":"当事人就同一集体林地订立多个经营权流转合同，在合同有效的情况下，受让方均主张取得林地经营权的，由具有下列情形的受让方取得："},{"i":8,"n":"第八条","txt":"家庭承包林地的承包方以林地经营权人擅自再流转林地经营权为由，请求解除林地经营权流转合同、收回林地的，人民法院应予支持。但林地经营权人能够证明林地经营权再流转已经承包方书面同意的除外。"},{"i":9,"n":"第九条","txt":"本集体经济组织成员以其在同等条件下享有的优先权受到侵害为由，主张家庭承包林地经营权流转合同无效的，人民法院不予支持；其请求赔偿损失的，依法予以支持。"},{"i":10,"n":"第十条","txt":"林地承包期内，因林地承包经营权互换、转让、继承等原因，承包方发生变动，林地经营权人请求新的承包方继续履行原林地经营权流转合同的，人民法院应予支持。但当事人另有约定的除外。"},{"i":11,"n":"第十一条","txt":"林地经营权流转合同约定的流转期限超过承包期的剩余期限，或者林地经营权再流转合同约定的流转期限超过原林地经营权流转合同的剩余期限，林地经营权流转、再流转合同当事人主张超过部分无效的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"林地经营权流转合同约定的流转期限超过承包期的剩余期限，发包方主张超过部分的约定对其不具有法律约束力的，人民法院应予支持。但发包方对此知道或者应当知道的除外。"},{"i":13,"n":"第十三条","txt":"林地经营权流转合同终止时，对于林地经营权人种植的地上林木，按照下列情形处理："},{"i":14,"n":"第十四条","txt":"人民法院对于当事人为利用公益林林地资源和森林景观资源开展林下经济、森林旅游、森林康养等经营活动订立的合同，应当综合考虑公益林生态区位保护要求、公益林生态功能及是否经科学论证的合理利用等因素，依法认定合同效力。"},{"i":15,"n":"第十五条","txt":"以林地经营权、林木所有权等法律、行政法规未禁止抵押的森林资源资产设定抵押，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人与抵押人协议以抵押的森林资源资产折价，并据此请求接管经营抵押财产的，人民法院依法予以支持。"},{"i":16,"n":"第十六条","txt":"以森林生态效益补偿收益、林业碳汇等提供担保，债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，担保物权人请求就担保财产优先受偿的，人民法院依法予以支持。"},{"i":17,"n":"第十七条","txt":"违反国家规定造成森林生态环境损害，生态环境能够修复的，国家规定的机关或者法律规定的组织依据民法典第一千二百三十四条的规定，请求侵权人在合理期限内以补种树木、恢复植被、恢复林地土壤性状、投放相应生物种群等方式承担修复责任的，人民法院依法予以支持。"},{"i":18,"n":"第十八条","txt":"人民法院判决侵权人承担森林生态环境修复责任的，可以根据鉴定意见，或者参考林业主管部门、林业调查规划设计单位、相关科研机构和人员出具的专业意见，合理确定森林生态环境修复方案，明确侵权人履行修复义务的具体要求。"},{"i":19,"n":"第十九条","txt":"人民法院依据民法典第一千二百三十五条的规定确定侵权人承担的森林生态环境损害赔偿金额，应当综合考虑受损森林资源在调节气候、固碳增汇、保护生物多样性、涵养水源、保持水土、防风固沙等方面的生态环境服务功能，予以合理认定。"},{"i":20,"n":"第二十条","txt":"当事人请求以认购经核证的林业碳汇方式替代履行森林生态环境损害赔偿责任的，人民法院可以综合考虑各方当事人意见、不同责任方式的合理性等因素，依法予以准许。"},{"i":21,"n":"第二十一条","txt":"当事人请求以森林管护、野生动植物保护、社区服务等劳务方式替代履行森林生态环境损害赔偿责任的，人民法院可以综合考虑侵权人的代偿意愿、经济能力、劳动能力、赔偿金额、当地相应工资标准等因素，决定是否予以准许，并合理确定劳务代偿方案。"},{"i":22,"n":"第二十二条","txt":"侵权人自愿交纳保证金作为履行森林生态环境修复义务担保的，在其不履行修复义务时，人民法院可以将保证金用于支付森林生态环境修复费用。"},{"i":23,"n":"第二十三条","txt":"本解释自2022年6月15日起施行。施行前本院公布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlizhiwuxinpinzhongjiufe159dc":[{"i":1,"n":"第一条","txt":"人民法院受理的植物新品种纠纷案件主要包括以下几类："},{"i":2,"n":"第二条","txt":"人民法院在依法审查当事人涉及植物新品种权的起诉时，只要符合《中华人民共和国民事诉讼法》第一百一十九条、《中华人民共和国行政诉讼法》第四十九条规定的民事案件或者行政案件的起诉条件，均应当依法予以受理。"},{"i":3,"n":"第三条","txt":"本解释第一条所列第一至五类案件，由北京知识产权法院作为第一审人民法院审理；第六至十八类案件，由知识产权法院，各省、自治区、直辖市人民政府所在地和最高人民法院指定的中级人民法院作为第一审人民法院审理。"},{"i":4,"n":"第四条","txt":"以侵权行为地确定人民法院管辖的侵害植物新品种权的民事案件，其所称的侵权行为地，是指未经品种权所有人许可，生产、繁殖或者销售该授权植物新品种的繁殖材料的所在地，或者为商业目的将该授权品种的繁殖材料重复使用于生产另一品种的繁殖材料的所在地。"},{"i":5,"n":"第五条","txt":"关于植物新品种申请驳回复审行政纠纷案件、植物新品种权无效或者更名行政纠纷案件，应当以植物新品种审批机关为被告；关于植物新品种强制许可纠纷案件，应当以植物新品种审批机关为被告；关于实施强制许可使用费纠纷案件，应当根据原告所请求的事项和所起诉的当事人确定被告。"},{"i":6,"n":"第六条","txt":"人民法院审理侵害植物新品种权纠纷案件，被告在答辩期间内向植物新品种审批机关请求宣告该植物新品种权无效的，人民法院一般不中止诉讼。"}],"zuigaorenminfayuanguanyushenlidupinfanzuianjianshi1717df":[{"i":1,"n":"第一条","txt":"走私、贩卖、运输、制造、非法持有下列毒品，应当认定为刑法第三百四十七条第二款第一项、第三百四十八条规定的“其他毒品数量大”："},{"i":2,"n":"第二条","txt":"走私、贩卖、运输、制造、非法持有下列毒品，应当认定为刑法第三百四十七条第三款、第三百四十八条规定的“其他毒品数量较大”："},{"i":3,"n":"第三条","txt":"在实施走私、贩卖、运输、制造毒品犯罪的过程中，携带枪支、弹药或者爆炸物用于掩护的，应当认定为刑法第三百四十七条第二款第三项规定的“武装掩护走私、贩卖、运输、制造毒品”。枪支、弹药、爆炸物种类的认定，依照相关司法解释的规定执行。"},{"i":4,"n":"第四条","txt":"走私、贩卖、运输、制造毒品，具有下列情形之一的，应当认定为刑法第三百四十七条第四款规定的“情节严重”："},{"i":5,"n":"第五条","txt":"非法持有毒品达到刑法第三百四十八条或者本解释第二条规定的“数量较大”标准，且具有下列情形之一的，应当认定为刑法第三百四十八条规定的“情节严重”："},{"i":6,"n":"第六条","txt":"包庇走私、贩卖、运输、制造毒品的犯罪分子，具有下列情形之一的，应当认定为刑法第三百四十九条第一款规定的“情节严重”："},{"i":7,"n":"第七条","txt":"违反国家规定，非法生产、买卖、运输制毒物品、走私制毒物品，达到下列数量标准的，应当认定为刑法第三百五十条第一款规定的“情节较重”："},{"i":8,"n":"第八条","txt":"违反国家规定，非法生产、买卖、运输制毒物品、走私制毒物品，具有下列情形之一的，应当认定为刑法第三百五十条第一款规定的“情节严重”："},{"i":9,"n":"第九条","txt":"非法种植毒品原植物，具有下列情形之一的，应当认定为刑法第三百五十一条第一款第一项规定的“数量较大”："},{"i":10,"n":"第十条","txt":"非法买卖、运输、携带、持有未经灭活的毒品原植物种子或者幼苗，具有下列情形之一的，应当认定为刑法第三百五十二条规定的“数量较大”："},{"i":11,"n":"第十一条","txt":"引诱、教唆、欺骗他人吸食、注射毒品，具有下列情形之一的，应当认定为刑法第三百五十三条第一款规定的“情节严重”："},{"i":12,"n":"第十二条","txt":"容留他人吸食、注射毒品，具有下列情形之一的，应当依照刑法第三百五十四条的规定，以容留他人吸毒罪定罪处罚："},{"i":13,"n":"第十三条","txt":"依法从事生产、运输、管理、使用国家管制的麻醉药品、精神药品的人员，违反国家规定，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品，具有下列情形之一的，应当依照刑法第三百五十五条第一款的规定，以非法提供麻醉药品、精神药品罪定罪处罚："},{"i":14,"n":"第十四条","txt":"利用信息网络，设立用于实施传授制造毒品、非法生产制毒物品的方法，贩卖毒品，非法买卖制毒物品或者组织他人吸食、注射毒品等违法犯罪活动的网站、通讯群组，或者发布实施前述违法犯罪活动的信息，情节严重的，应当依照刑法第二百八十七条之一的规定，以非法利用信息网络罪定罪处罚。"}],"zuigaorenminfayuanguanyushenliminshixingzhengsusonedb060":[{"i":1,"n":"第一条","txt":"人民法院在民事、行政诉讼过程中，违法采取对妨害诉讼的强制措施、保全措施、先予执行措施，或者对判决、裁定及其他生效法律文书执行错误，侵犯公民、法人和其他组织合法权益并造成损害的，赔偿请求人可以依法向人民法院申请赔偿。"},{"i":2,"n":"第二条","txt":"违法采取对妨害诉讼的强制措施，包括以下情形："},{"i":3,"n":"第三条","txt":"违法采取保全措施，包括以下情形："},{"i":4,"n":"第四条","txt":"违法采取先予执行措施，包括以下情形："},{"i":5,"n":"第五条","txt":"对判决、裁定及其他生效法律文书执行错误，包括以下情形："},{"i":6,"n":"第六条","txt":"人民法院工作人员在民事、行政诉讼过程中，有殴打、虐待或者唆使、放纵他人殴打、虐待等行为，以及违法使用武器、警械，造成公民身体伤害或者死亡的，适用国家赔偿法第十七条第四项、第五项的规定予以赔偿。"},{"i":7,"n":"第七条","txt":"具有下列情形之一的，国家不承担赔偿责任："},{"i":8,"n":"第八条","txt":"因多种原因造成公民、法人和其他组织合法权益损害的，应当根据人民法院及其工作人员行使职权的行为对损害结果的发生或者扩大所起的作用等因素，合理确定赔偿金额。"},{"i":9,"n":"第九条","txt":"受害人对损害结果的发生或者扩大也有过错的，应当根据其过错对损害结果的发生或者扩大所起的作用等因素，依法减轻国家赔偿责任。"},{"i":10,"n":"第十条","txt":"公民、法人和其他组织的损失，已经在民事、行政诉讼过程中获得赔偿、补偿的，对该部分损失，国家不承担赔偿责任。"},{"i":11,"n":"第十一条","txt":"人民法院及其工作人员在民事、行政诉讼过程中，具有本解释第二条、第六条规定情形，侵犯公民人身权的，应当依照国家赔偿法第三十三条、第三十四条的规定计算赔偿金。致人精神损害的，应当依照国家赔偿法第三十五条的规定，在侵权行为影响的范围内，为受害人消除影响、恢复名誉、赔礼道歉；造成严重后果的，还应当支付相应的精神损害抚慰金。"},{"i":12,"n":"第十二条","txt":"人民法院及其工作人员在民事、行政诉讼过程中，具有本解释第二条至第五条规定情形，侵犯公民、法人和其他组织的财产权并造成损害的，应当依照国家赔偿法第三十六条的规定承担赔偿责任。"},{"i":13,"n":"第十三条","txt":"人民法院及其工作人员对判决、裁定及其他生效法律文书执行错误，且对公民、法人或者其他组织的财产已经依照法定程序拍卖或者变卖的，应当给付拍卖或者变卖所得的价款。"},{"i":14,"n":"第十四条","txt":"国家赔偿法第三十六条第六项规定的停产停业期间必要的经常性费用开支，是指法人、其他组织和个体工商户为维系停产停业期间运营所需的基本开支，包括留守职工工资、必须缴纳的税费、水电费、房屋场地租金、设备租金、设备折旧费等必要的经常性费用。"},{"i":15,"n":"第十五条","txt":"国家赔偿法第三十六条第七项规定的银行同期存款利息，以作出生效赔偿决定时中国人民银行公布的一年期人民币整存整取定期存款基准利率计算，不计算复利。"},{"i":16,"n":"第十六条","txt":"依照国家赔偿法第三十六条规定返还的财产系国家批准的金融机构贷款的，除贷款本金外，还应当支付该贷款借贷状态下的贷款利息。"},{"i":17,"n":"第十七条","txt":"用益物权人、担保物权人、承租人或者其他合法占有使用财产的人，依据国家赔偿法第三十八条规定申请赔偿的，人民法院应当依照《最高人民法院关于国家赔偿案件立案工作的规定》予以审查立案。"},{"i":18,"n":"第十八条","txt":"人民法院在民事、行政诉讼过程中，违法采取对妨害诉讼的强制措施、保全措施、先予执行措施，或者对判决、裁定及其他生效法律文书执行错误，系因上一级人民法院复议改变原裁决所致的，由该上一级人民法院作为赔偿义务机关。"},{"i":19,"n":"第十九条","txt":"公民、法人或者其他组织依据国家赔偿法第三十八条规定申请赔偿的，应当在民事、行政诉讼程序或者执行程序终结后提出，但下列情形除外："},{"i":20,"n":"第二十条","txt":"人民法院赔偿委员会审理民事、行政诉讼中的司法赔偿案件，有下列情形之一的，相应期间不计入审理期限："},{"i":21,"n":"第二十一条","txt":"人民法院赔偿委员会审理民事、行政诉讼中的司法赔偿案件，应当对人民法院及其工作人员行使职权的行为是否符合法律规定，赔偿请求人主张的损害事实是否存在，以及该职权行为与损害事实之间是否存在因果关系等事项一并予以审查。"},{"i":22,"n":"第二十二条","txt":"本解释自2016年10月1日起施行。本解释施行前最高人民法院发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlixiaofeiminshigongyiseaf2b5":[{"i":1,"n":"第一条","txt":"中国消费者协会以及在省、自治区、直辖市设立的消费者协会，对经营者侵害众多不特定消费者合法权益或者具有危及消费者人身、财产安全危险等损害社会公共利益的行为提起消费民事公益诉讼的，适用本解释。"},{"i":2,"n":"第二条","txt":"经营者提供的商品或者服务具有下列情形之一的，适用消费者权益保护法第四十七条规定："},{"i":3,"n":"第三条","txt":"消费民事公益诉讼案件管辖适用《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第二百八十五条的有关规定。"},{"i":4,"n":"第四条","txt":"提起消费民事公益诉讼应当提交下列材料："},{"i":5,"n":"第五条","txt":"人民法院认为原告提出的诉讼请求不足以保护社会公共利益的，可以向其释明变更或者增加停止侵害等诉讼请求。"},{"i":6,"n":"第六条","txt":"人民法院受理消费民事公益诉讼案件后，应当公告案件受理情况，并在立案之日起十日内书面告知相关行政主管部门。"},{"i":7,"n":"第七条","txt":"人民法院受理消费民事公益诉讼案件后，依法可以提起诉讼的其他机关或者社会组织，可以在一审开庭前向人民法院申请参加诉讼。"},{"i":8,"n":"第八条","txt":"有权提起消费民事公益诉讼的机关或者社会组织，可以依据民事诉讼法第八十一条规定申请保全证据。"},{"i":9,"n":"第九条","txt":"人民法院受理消费民事公益诉讼案件后，因同一侵权行为受到损害的消费者申请参加诉讼的，人民法院应当告知其根据民事诉讼法第一百一十九条规定主张权利。"},{"i":10,"n":"第十条","txt":"消费民事公益诉讼案件受理后，因同一侵权行为受到损害的消费者请求对其根据民事诉讼法第一百一十九条规定提起的诉讼予以中止，人民法院可以准许。"},{"i":11,"n":"第十一条","txt":"消费民事公益诉讼案件审理过程中，被告提出反诉的，人民法院不予受理。"},{"i":12,"n":"第十二条","txt":"原告在诉讼中承认对己方不利的事实，人民法院认为损害社会公共利益的，不予确认。"},{"i":13,"n":"第十三条","txt":"原告在消费民事公益诉讼案件中，请求被告承担停止侵害、排除妨碍、消除危险、赔礼道歉等民事责任的，人民法院可予支持。"},{"i":14,"n":"第十四条","txt":"消费民事公益诉讼案件裁判生效后，人民法院应当在十日内书面告知相关行政主管部门，并可发出司法建议。"},{"i":15,"n":"第十五条","txt":"消费民事公益诉讼案件的裁判发生法律效力后，其他依法具有原告资格的机关或者社会组织就同一侵权行为另行提起消费民事公益诉讼的，人民法院不予受理。"},{"i":16,"n":"第十六条","txt":"已为消费民事公益诉讼生效裁判认定的事实，因同一侵权行为受到损害的消费者根据民事诉讼法第一百一十九条规定提起的诉讼，原告、被告均无需举证证明，但当事人对该事实有异议并有相反证据足以推翻的除外。"},{"i":17,"n":"第十七条","txt":"原告为停止侵害、排除妨碍、消除危险采取合理预防、处置措施而发生的费用，请求被告承担的，人民法院应依法予以支持。"},{"i":18,"n":"第十八条","txt":"原告及其诉讼代理人对侵权行为进行调查、取证的合理费用、鉴定费用、合理的律师代理费用，人民法院可根据实际情况予以相应支持。"},{"i":19,"n":"第十九条","txt":"本解释自2016年5月1日起施行。"}],"zuigaorenminfayuanguanyushenlishejinongcuntudichenc1a175":[{"i":1,"n":"第一条","txt":"下列涉及农村土地承包民事纠纷，人民法院应当依法受理："},{"i":2,"n":"第二条","txt":"当事人自愿达成书面仲裁协议的，受诉人民法院应当参照《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第二百一十五条、第二百一十六条的规定处理。"},{"i":3,"n":"第三条","txt":"承包合同纠纷，以发包方和承包方为当事人。"},{"i":4,"n":"第四条","txt":"农户成员为多人的，由其代表人进行诉讼。"},{"i":5,"n":"第五条","txt":"承包合同中有关收回、调整承包地的约定违反农村土地承包法第二十七条、第二十八条、第三十一条规定的，应当认定该约定无效。"},{"i":6,"n":"第六条","txt":"因发包方违法收回、调整承包地，或者因发包方收回承包方弃耕、撂荒的承包地产生的纠纷，按照下列情形，分别处理："},{"i":7,"n":"第七条","txt":"承包合同约定或者土地承包经营权证等证书记载的承包期限短于农村土地承包法规定的期限，承包方请求延长的，应予支持。"},{"i":8,"n":"第八条","txt":"承包方违反农村土地承包法第十八条规定，未经依法批准将承包地用于非农建设或者对承包地造成永久性损害，发包方请求承包方停止侵害、恢复原状或者赔偿损失的，应予支持。"},{"i":9,"n":"第九条","txt":"发包方根据农村土地承包法第二十七条规定收回承包地前，承包方已经以出租、入股或者其他形式将其土地经营权流转给第三人，且流转期限尚未届满，因流转价款收取产生的纠纷，按照下列情形，分别处理："},{"i":10,"n":"第十条","txt":"承包方交回承包地不符合农村土地承包法第三十条规定程序的，不得认定其为自愿交回。"},{"i":11,"n":"第十一条","txt":"土地经营权流转中，本集体经济组织成员在流转价款、流转期限等主要内容相同的条件下主张优先权的，应予支持。但下列情形除外："},{"i":12,"n":"第十二条","txt":"发包方胁迫承包方将土地经营权流转给第三人，承包方请求撤销其与第三人签订的流转合同的，应予支持。"},{"i":13,"n":"第十三条","txt":"承包方未经发包方同意，转让其土地承包经营权的，转让合同无效。但发包方无法定理由不同意或者拖延表态的除外。"},{"i":14,"n":"第十四条","txt":"承包方依法采取出租、入股或者其他方式流转土地经营权，发包方仅以该土地经营权流转合同未报其备案为由，请求确认合同无效的，不予支持。"},{"i":15,"n":"第十五条","txt":"因承包方不收取流转价款或者向对方支付费用的约定产生纠纷，当事人协商变更无法达成一致，且继续履行又显失公平的，人民法院可以根据发生变更的客观情况，按照公平原则处理。"},{"i":16,"n":"第十六条","txt":"当事人对出租地流转期限没有约定或者约定不明的，参照民法典第七百三十条规定处理。除当事人另有约定或者属于林地承包经营外，承包地交回的时间应当在农作物收获期结束后或者下一耕种期开始前。"},{"i":17,"n":"第十七条","txt":"发包方或者其他组织、个人擅自截留、扣缴承包收益或者土地经营权流转收益，承包方请求返还的，应予支持。"},{"i":18,"n":"第十八条","txt":"本集体经济组织成员在承包费、承包期限等主要内容相同的条件下主张优先承包的，应予支持。但在发包方将农村土地发包给本集体经济组织以外的组织或者个人，已经法律规定的民主议定程序通过，并由乡（镇）人民政府批准后主张优先承包的，不予支持。"},{"i":19,"n":"第十九条","txt":"发包方就同一土地签订两个以上承包合同，承包方均主张取得土地经营权的，按照下列情形，分别处理："},{"i":20,"n":"第二十条","txt":"承包地被依法征收，承包方请求发包方给付已经收到的地上附着物和青苗的补偿费的，应予支持。"},{"i":21,"n":"第二十一条","txt":"承包地被依法征收，放弃统一安置的家庭承包方，请求发包方给付已经收到的安置补助费的，应予支持。"},{"i":22,"n":"第二十二条","txt":"农村集体经济组织或者村民委员会、村民小组，可以依照法律规定的民主议定程序，决定在本集体经济组织内部分配已经收到的土地补偿费。征地补偿安置方案确定时已经具有本集体经济组织成员资格的人，请求支付相应份额的，应予支持。但已报全国人大常委会、国务院备案的地方性法规、自治条例和单行条例、地方政府规章对土地补偿费在农村集体经济组织内部的分配办法另有规定的除外。"},{"i":23,"n":"第二十三条","txt":"林地家庭承包中，承包方的继承人请求在承包期内继续承包的，应予支持。"},{"i":24,"n":"第二十四条","txt":"人民法院在审理涉及本解释第五条、第六条第一款第（二）项及第二款、第十五条的纠纷案件时，应当着重进行调解。必要时可以委托人民调解组织进行调解。"},{"i":25,"n":"第二十五条","txt":"本解释自2005年9月1日起施行。施行后受理的第一审案件，适用本解释的规定。"}],"zuigaorenminfayuanguanyushenlishejinongcuntudichen624b78":[{"i":1,"n":"第一条","txt":"农村土地承包仲裁委员会根据农村土地承包经营纠纷调解仲裁法第十八条规定，以超过申请仲裁的时效期间为由驳回申请后，当事人就同一纠纷提起诉讼的，人民法院应予受理。"},{"i":2,"n":"第二条","txt":"当事人在收到农村土地承包仲裁委员会作出的裁决书之日起三十日后或者签收农村土地承包仲裁委员会作出的调解书后，就同一纠纷向人民法院提起诉讼的，裁定不予受理；已经受理的，裁定驳回起诉。"},{"i":3,"n":"第三条","txt":"当事人在收到农村土地承包仲裁委员会作出的裁决书之日起三十日内，向人民法院提起诉讼，请求撤销仲裁裁决的，人民法院应当告知当事人就原纠纷提起诉讼。"},{"i":4,"n":"第四条","txt":"农村土地承包仲裁委员会依法向人民法院提交当事人财产保全申请的，申请财产保全的当事人为申请人。"},{"i":5,"n":"第五条","txt":"人民法院对农村土地承包仲裁委员会提交的财产保全申请材料，应当进行审查。符合前条规定的，应予受理；申请材料不齐全或不符合规定的，人民法院应当告知农村土地承包仲裁委员会需要补齐的内容。"},{"i":6,"n":"第六条","txt":"人民法院受理财产保全申请后，应当在十日内作出裁定。因特殊情况需要延长的，经本院院长批准，可以延长五日。"},{"i":7,"n":"第七条","txt":"农村土地承包经营纠纷仲裁中采取的财产保全措施，在申请保全的当事人依法提起诉讼后，自动转为诉讼中的财产保全措施，并适用《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第四百八十七条关于查封、扣押、冻结期限的规定。"},{"i":8,"n":"第八条","txt":"农村土地承包仲裁委员会依法向人民法院提交当事人证据保全申请的，应当提供下列材料："},{"i":9,"n":"第九条","txt":"农村土地承包仲裁委员会作出先行裁定后，一方当事人依法向被执行人住所地或者被执行的财产所在地基层人民法院申请执行的，人民法院应予受理和执行。"},{"i":10,"n":"第十条","txt":"当事人根据农村土地承包经营纠纷调解仲裁法第四十九条规定，向人民法院申请执行调解书、裁决书，符合《最高人民法院关于人民法院执行工作若干问题的规定（试行）》第十六条规定条件的，人民法院应予受理和执行。"},{"i":11,"n":"第十一条","txt":"当事人因不服农村土地承包仲裁委员会作出的仲裁裁决向人民法院提起诉讼的，起诉期从其收到裁决书的次日起计算。"},{"i":12,"n":"第十二条","txt":"本解释施行后，人民法院尚未审结的一审、二审案件适用本解释规定。本解释施行前已经作出生效裁判的案件，本解释施行后依法再审的，不适用本解释规定。"}],"zuigaorenminfayuanguanyushenlishejiguoyoutudishiyoef1c3e":[{"i":1,"n":"第一条","txt":"本解释所称的土地使用权出让合同，是指市、县人民政府自然资源主管部门作为出让方将国有土地使用权在一定年限内让与受让方，受让方支付土地使用权出让金的合同。"},{"i":2,"n":"第二条","txt":"开发区管理委员会作为出让方与受让方订立的土地使用权出让合同，应当认定无效。"},{"i":3,"n":"第三条","txt":"经市、县人民政府批准同意以协议方式出让的土地使用权，土地使用权出让金低于订立合同时当地政府按照国家规定确定的最低价的，应当认定土地使用权出让合同约定的价格条款无效。"},{"i":4,"n":"第四条","txt":"土地使用权出让合同的出让方因未办理土地使用权出让批准手续而不能交付土地，受让方请求解除合同的，应予支持。"},{"i":5,"n":"第五条","txt":"受让方经出让方和市、县人民政府城市规划行政主管部门同意，改变土地使用权出让合同约定的土地用途，当事人请求按照起诉时同种用途的土地出让金标准调整土地出让金的，应予支持。"},{"i":6,"n":"第六条","txt":"受让方擅自改变土地使用权出让合同约定的土地用途，出让方请求解除合同的，应予支持。"},{"i":7,"n":"第七条","txt":"本解释所称的土地使用权转让合同，是指土地使用权人作为转让方将出让土地使用权转让于受让方，受让方支付价款的合同。"},{"i":8,"n":"第八条","txt":"土地使用权人作为转让方与受让方订立土地使用权转让合同后，当事人一方以双方之间未办理土地使用权变更登记手续为由，请求确认合同无效的，不予支持。"},{"i":9,"n":"第九条","txt":"土地使用权人作为转让方就同一出让土地使用权订立数个转让合同，在转让合同有效的情况下，受让方均要求履行合同的，按照以下情形分别处理："},{"i":10,"n":"第十条","txt":"土地使用权人与受让方订立合同转让划拨土地使用权，起诉前经有批准权的人民政府同意转让，并由受让方办理土地使用权出让手续的，土地使用权人与受让方订立的合同可以按照补偿性质的合同处理。"},{"i":11,"n":"第十一条","txt":"土地使用权人与受让方订立合同转让划拨土地使用权，起诉前经有批准权的人民政府决定不办理土地使用权出让手续，并将该划拨土地使用权直接划拨给受让方使用的，土地使用权人与受让方订立的合同可以按照补偿性质的合同处理。"},{"i":12,"n":"第十二条","txt":"本解释所称的合作开发房地产合同，是指当事人订立的以提供出让土地使用权、资金等作为共同投资，共享利润、共担风险合作开发房地产为基本内容的合同。"},{"i":13,"n":"第十三条","txt":"合作开发房地产合同的当事人一方具备房地产开发经营资质的，应当认定合同有效。"},{"i":14,"n":"第十四条","txt":"投资数额超出合作开发房地产合同的约定，对增加的投资数额的承担比例，当事人协商不成的，按照当事人的违约情况确定；因不可归责于当事人的事由或者当事人的违约情况无法确定的，按照约定的投资比例确定；没有约定投资比例的，按照约定的利润分配比例确定。"},{"i":15,"n":"第十五条","txt":"房屋实际建筑面积少于合作开发房地产合同的约定，对房屋实际建筑面积的分配比例，当事人协商不成的，按照当事人的违约情况确定；因不可归责于当事人的事由或者当事人违约情况无法确定的，按照约定的利润分配比例确定。"},{"i":16,"n":"第十六条","txt":"在下列情形下，合作开发房地产合同的当事人请求分配房地产项目利益的，不予受理；已经受理的，驳回起诉："},{"i":17,"n":"第十七条","txt":"房屋实际建筑面积超出规划建筑面积，经有批准权的人民政府主管部门批准后，当事人对超出部分的房屋分配比例协商不成的，按照约定的利润分配比例确定。对增加的投资数额的承担比例，当事人协商不成的，按照约定的投资比例确定；没有约定投资比例的，按照约定的利润分配比例确定。"},{"i":18,"n":"第十八条","txt":"当事人违反规划开发建设的房屋，被有批准权的人民政府主管部门认定为违法建筑责令拆除，当事人对损失承担协商不成的，按照当事人过错确定责任；过错无法确定的，按照约定的投资比例确定责任；没有约定投资比例的，按照约定的利润分配比例确定责任。"},{"i":19,"n":"第十九条","txt":"合作开发房地产合同约定仅以投资数额确定利润分配比例，当事人未足额交纳出资的，按照当事人的实际投资比例分配利润。"},{"i":20,"n":"第二十条","txt":"合作开发房地产合同的当事人要求将房屋预售款充抵投资参与利润分配的，不予支持。"},{"i":21,"n":"第二十一条","txt":"合作开发房地产合同约定提供土地使用权的当事人不承担经营风险，只收取固定利益的，应当认定为土地使用权转让合同。"},{"i":22,"n":"第二十二条","txt":"合作开发房地产合同约定提供资金的当事人不承担经营风险，只分配固定数量房屋的，应当认定为房屋买卖合同。"},{"i":23,"n":"第二十三条","txt":"合作开发房地产合同约定提供资金的当事人不承担经营风险，只收取固定数额货币的，应当认定为借款合同。"},{"i":24,"n":"第二十四条","txt":"合作开发房地产合同约定提供资金的当事人不承担经营风险，只以租赁或者其他形式使用房屋的，应当认定为房屋租赁合同。"},{"i":25,"n":"第二十五条","txt":"本解释自2005年8月1日起施行；施行后受理的第一审案件适用本解释。"}],"zuigaorenminfayuanguanyushenlishejijisuanjiwangluoa43cb7":[{"i":1,"n":"第一条","txt":"对于涉及计算机网络域名注册、使用等行为的民事纠纷，当事人向人民法院提起诉讼，经审查符合民事诉讼法第一百一十九条规定的，人民法院应当受理。"},{"i":2,"n":"第二条","txt":"涉及域名的侵权纠纷案件，由侵权行为地或者被告住所地的中级人民法院管辖。对难以确定侵权行为地和被告住所地的，原告发现该域名的计算机终端等设备所在地可以视为侵权行为地。"},{"i":3,"n":"第三条","txt":"域名纠纷案件的案由，根据双方当事人争议的法律关系的性质确定，并在其前冠以计算机网络域名；争议的法律关系的性质难以确定的，可以通称为计算机网络域名纠纷案件。"},{"i":4,"n":"第四条","txt":"人民法院审理域名纠纷案件，对符合以下各项条件的，应当认定被告注册、使用域名等行为构成侵权或者不正当竞争："},{"i":5,"n":"第五条","txt":"被告的行为被证明具有下列情形之一的，人民法院应当认定其具有恶意："},{"i":6,"n":"第六条","txt":"人民法院审理域名纠纷案件，根据当事人的请求以及案件的具体情况，可以对涉及的注册商标是否驰名依法作出认定。"},{"i":7,"n":"第七条","txt":"人民法院认定域名注册、使用等行为构成侵权或者不正当竞争的，可以判令被告停止侵权、注销域名，或者依原告的请求判令由原告注册使用该域名；给权利人造成实际损害的，可以判令被告赔偿损失。"}],"zuigaorenminfayuanguanyushenlishejichimingshangbia1c7bcc":[{"i":1,"n":"第一条","txt":"本解释所称驰名商标，是指在中国境内为相关公众所熟知的商标。"},{"i":2,"n":"第二条","txt":"在下列民事纠纷案件中，当事人以商标驰名作为事实根据，人民法院根据案件具体情况，认为确有必要的，对所涉商标是否驰名作出认定："},{"i":3,"n":"第三条","txt":"在下列民事纠纷案件中，人民法院对于所涉商标是否驰名不予审查："},{"i":4,"n":"第四条","txt":"人民法院认定商标是否驰名，应当以证明其驰名的事实为依据，综合考虑商标法第十四条第一款规定的各项因素，但是根据案件具体情况无需考虑该条规定的全部因素即足以认定商标驰名的情形除外。"},{"i":5,"n":"第五条","txt":"当事人主张商标驰名的，应当根据案件具体情况，提供下列证据，证明被诉侵犯商标权或者不正当竞争行为发生时，其商标已属驰名："},{"i":6,"n":"第六条","txt":"原告以被诉商标的使用侵犯其注册商标专用权为由提起民事诉讼，被告以原告的注册商标复制、摹仿或者翻译其在先未注册驰名商标为由提出抗辩或者提起反诉的，应当对其在先未注册商标驰名的事实负举证责任。"},{"i":7,"n":"第七条","txt":"被诉侵犯商标权或者不正当竞争行为发生前，曾被人民法院或者行政管理部门认定驰名的商标，被告对该商标驰名的事实不持异议的，人民法院应当予以认定。被告提出异议的，原告仍应当对该商标驰名的事实负举证责任。"},{"i":8,"n":"第八条","txt":"对于在中国境内为社会公众所熟知的商标，原告已提供其商标驰名的基本证据，或者被告不持异议的，人民法院对该商标驰名的事实予以认定。"},{"i":9,"n":"第九条","txt":"足以使相关公众对使用驰名商标和被诉商标的商品来源产生误认，或者足以使相关公众认为使用驰名商标和被诉商标的经营者之间具有许可使用、关联企业关系等特定联系的，属于商标法第十三条第二款规定的“容易导致混淆”。"},{"i":10,"n":"第十条","txt":"原告请求禁止被告在不相类似商品上使用与原告驰名的注册商标相同或者近似的商标或者企业名称的，人民法院应当根据案件具体情况，综合考虑以下因素后作出裁判："},{"i":11,"n":"第十一条","txt":"被告使用的注册商标违反商标法第十三条的规定，复制、摹仿或者翻译原告驰名商标，构成侵犯商标权的，人民法院应当根据原告的请求，依法判决禁止被告使用该商标，但被告的注册商标有下列情形之一的，人民法院对原告的请求不予支持："},{"i":12,"n":"第十二条","txt":"当事人请求保护的未注册驰名商标，属于商标法第十条、第十一条、第十二条规定不得作为商标使用或者注册情形的，人民法院不予支持。"},{"i":13,"n":"第十三条","txt":"在涉及驰名商标保护的民事纠纷案件中，人民法院对于商标驰名的认定，仅作为案件事实和判决理由，不写入判决主文；以调解方式审结的，在调解书中对商标驰名的事实不予认定。"},{"i":14,"n":"第十四条","txt":"本院以前有关司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlishewaiminshangshianjee4488":[{"i":1,"n":"第一条","txt":"人民法院审理《中华人民共和国海商法》、《中华人民共和国票据法》、《中华人民共和国民用航空法》、《中华人民共和国海上交通安全法》调整的涉外民商事案件，涉及适用国际条约的，分别按照《中华人民共和国海商法》第二百六十八条、《中华人民共和国票据法》第九十五条、《中华人民共和国民用航空法》第一百八十四条、《中华人民共和国海上交通安全法》第一百二十一条的规定予以适用。"},{"i":2,"n":"第二条","txt":"涉外民商事案件涉及两项或多项国际条约的适用时，人民法院应当根据国际条约中的适用关系条款确定应当适用的国际条约。"},{"i":3,"n":"第三条","txt":"国际条约规定当事人可以约定排除或部分排除国际条约的适用，当事人主张依据其约定排除或部分排除国际条约适用的，人民法院予以支持。国际条约限制当事人排除或部分排除国际条约的适用，当事人主张依据其约定排除或部分排除国际条约适用的，人民法院不予支持。"},{"i":4,"n":"第四条","txt":"当事人在合同中援引尚未对中华人民共和国生效的国际条约的，人民法院可以根据该国际条约的内容确定当事人之间的权利义务，但违反中华人民共和国法律、行政法规强制性规定或者损害中华人民共和国主权、安全和社会公共利益的除外。"},{"i":5,"n":"第五条","txt":"涉外民商事合同当事人明示选择适用国际惯例，当事人主张根据国际惯例确定合同当事人之间的权利义务的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"中华人民共和国法律和中华人民共和国缔结或者参加的国际条约没有规定的，人民法院可以适用国际惯例。当事人仅以未明示选择为由主张排除适用国际惯例的，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"适用国际条约和国际惯例损害中华人民共和国主权、安全和社会公共利益的，人民法院不予适用。"},{"i":8,"n":"第八条","txt":"本解释自2024年1月1日起施行。"},{"i":9,"n":"第九条","txt":"最高人民法院以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlishezhixingsifapeichaa0f815":[{"i":1,"n":"第一条","txt":"人民法院在执行判决、裁定及其他生效法律文书过程中，错误采取财产调查、控制、处置、交付、分配等执行措施或者罚款、拘留等强制措施，侵犯公民、法人和其他组织合法权益并造成损害，受害人依照国家赔偿法第三十八条规定申请赔偿的，适用本解释。"},{"i":2,"n":"第二条","txt":"公民、法人和其他组织认为有下列错误执行行为造成损害申请赔偿的，人民法院应当依法受理："},{"i":3,"n":"第三条","txt":"原债权人转让债权的，其基于债权申请国家赔偿的权利随之转移，但根据债权性质、当事人约定或者法律规定不得转让的除外。"},{"i":4,"n":"第四条","txt":"人民法院将查封、扣押、冻结等事项委托其他人民法院执行的，公民、法人和其他组织认为错误执行行为造成损害申请赔偿的，委托法院为赔偿义务机关。"},{"i":5,"n":"第五条","txt":"公民、法人和其他组织申请错误执行赔偿，应当在执行程序终结后提出，终结前提出的不予受理。但有下列情形之一，且无法在相关诉讼或者执行程序中予以补救的除外："},{"i":6,"n":"第六条","txt":"公民、法人和其他组织在执行异议、复议或者执行监督程序审查期间，就相关执行措施或者强制措施申请赔偿的，人民法院不予受理，已经受理的予以驳回，并告知其在上述程序终结后可以依照本解释第五条的规定依法提出赔偿申请。"},{"i":7,"n":"第七条","txt":"经执行异议、复议或者执行监督程序作出的生效法律文书，对执行行为是否合法已有认定的，该生效法律文书可以作为人民法院赔偿委员会认定执行行为合法性的根据。"},{"i":8,"n":"第八条","txt":"根据当时有效的执行依据或者依法认定的基本事实作出的执行行为，不因下列情形而认定为错误执行："},{"i":9,"n":"第九条","txt":"赔偿请求人应当对其主张的损害负举证责任。但因人民法院未列清单、列举不详等过错致使赔偿请求人无法就损害举证的，应当由人民法院对上述事实承担举证责任。"},{"i":10,"n":"第十条","txt":"被执行人因财产权被侵犯依照本解释第五条第一款规定申请赔偿，其债务尚未清偿的，获得的赔偿金应当首先用于清偿其债务。"},{"i":11,"n":"第十一条","txt":"因错误执行取得不当利益且无法返还的，人民法院承担赔偿责任后，可以依据赔偿决定向取得不当利益的人追偿。"},{"i":12,"n":"第十二条","txt":"在执行过程中，因保管人或者第三人的行为侵犯公民、法人和其他组织合法权益并造成损害的，应当由保管人或者第三人承担责任。但人民法院未尽监管职责的，应当在其能够防止或者制止损害发生、扩大的范围内承担相应的赔偿责任，并可以依据赔偿决定向保管人或者第三人追偿。"},{"i":13,"n":"第十三条","txt":"属于下列情形之一的，人民法院不承担赔偿责任："},{"i":14,"n":"第十四条","txt":"错误执行造成公民、法人和其他组织利息、租金等实际损失的，适用国家赔偿法第三十六条第八项的规定予以赔偿。"},{"i":15,"n":"第十五条","txt":"侵犯公民、法人和其他组织的财产权，按照错误执行行为发生时的市场价格不足以弥补受害人损失或者该价格无法确定的，可以采用下列方式计算损失："},{"i":16,"n":"第十六条","txt":"错误执行造成受害人停产停业的，下列损失属于停产停业期间必要的经常性费用开支："},{"i":17,"n":"第十七条","txt":"错误执行侵犯债权的，赔偿范围一般应当以债权标的额为限。债权受让人申请赔偿的，赔偿范围以其受让债权时支付的对价为限。"},{"i":18,"n":"第十八条","txt":"违法采取保全措施的案件进入执行程序后，公民、法人和其他组织申请赔偿的，应当作为错误执行案件予以立案审查。"},{"i":19,"n":"第十九条","txt":"审理违法采取妨害诉讼的强制措施、保全、先予执行赔偿案件，可以参照适用本解释。"},{"i":20,"n":"第二十条","txt":"本解释自2022年3月1日起施行。施行前本院公布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenliwuyefuwujiufenanjianccb4b9":[{"i":1,"n":"第一条","txt":"业主违反物业服务合同或者法律、法规、管理规约，实施妨碍物业服务与管理的行为，物业服务人请求业主承担停止侵害、排除妨碍、恢复原状等相应民事责任的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"物业服务人违反物业服务合同约定或者法律、法规、部门规章规定，擅自扩大收费范围、提高收费标准或者重复收费，业主以违规收费为由提出抗辩的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"物业服务合同的权利义务终止后，业主请求物业服务人退还已经预收，但尚未提供物业服务期间的物业费的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"因物业的承租人、借用人或者其他物业使用人实施违反物业服务合同，以及法律、法规或者管理规约的行为引起的物业服务纠纷，人民法院可以参照关于业主的规定处理。"},{"i":5,"n":"第五条","txt":"本解释自2009年10月1日起施行。"}],"zuigaorenminfayuanguanyushenlihuanjingminshigongyi3b7d9e":[{"i":1,"n":"第一条","txt":"法律规定的机关和有关组织依据民事诉讼法第五十五条、环境保护法第五十八条等法律的规定，对已经损害社会公共利益或者具有损害社会公共利益重大风险的污染环境、破坏生态的行为提起诉讼，符合民事诉讼法第一百一十九条第二项、第三项、第四项规定的，人民法院应予受理。"},{"i":2,"n":"第二条","txt":"依照法律、法规的规定，在设区的市级以上人民政府民政部门登记的社会团体、基金会以及社会服务机构等，可以认定为环境保护法第五十八条规定的社会组织。"},{"i":3,"n":"第三条","txt":"设区的市，自治州、盟、地区，不设区的地级市，直辖市的区以上人民政府民政部门，可以认定为环境保护法第五十八条规定的“设区的市级以上人民政府民政部门”。"},{"i":4,"n":"第四条","txt":"社会组织章程确定的宗旨和主要业务范围是维护社会公共利益，且从事环境保护公益活动的，可以认定为环境保护法第五十八条规定的“专门从事环境保护公益活动”。"},{"i":5,"n":"第五条","txt":"社会组织在提起诉讼前五年内未因从事业务活动违反法律、法规的规定受过行政、刑事处罚的，可以认定为环境保护法第五十八条规定的“无违法记录”。"},{"i":6,"n":"第六条","txt":"第一审环境民事公益诉讼案件由污染环境、破坏生态行为发生地、损害结果地或者被告住所地的中级以上人民法院管辖。"},{"i":7,"n":"第七条","txt":"经最高人民法院批准，高级人民法院可以根据本辖区环境和生态保护的实际情况，在辖区内确定部分中级人民法院受理第一审环境民事公益诉讼案件。"},{"i":8,"n":"第八条","txt":"提起环境民事公益诉讼应当提交下列材料："},{"i":9,"n":"第九条","txt":"人民法院认为原告提出的诉讼请求不足以保护社会公共利益的，可以向其释明变更或者增加停止侵害、修复生态环境等诉讼请求。"},{"i":10,"n":"第十条","txt":"人民法院受理环境民事公益诉讼后，应当在立案之日起五日内将起诉状副本发送被告，并公告案件受理情况。"},{"i":11,"n":"第十一条","txt":"检察机关、负有环境资源保护监督管理职责的部门及其他机关、社会组织、企业事业单位依据民事诉讼法第十五条的规定，可以通过提供法律咨询、提交书面意见、协助调查取证等方式支持社会组织依法提起环境民事公益诉讼。"},{"i":12,"n":"第十二条","txt":"人民法院受理环境民事公益诉讼后，应当在十日内告知对被告行为负有环境资源保护监督管理职责的部门。"},{"i":13,"n":"第十三条","txt":"原告请求被告提供其排放的主要污染物名称、排放方式、排放浓度和总量、超标排放情况以及防治污染设施的建设和运行情况等环境信息，法律、法规、规章规定被告应当持有或者有证据证明被告持有而拒不提供，如果原告主张相关事实不利于被告的，人民法院可以推定该主张成立。"},{"i":14,"n":"第十四条","txt":"对于审理环境民事公益诉讼案件需要的证据，人民法院认为必要的，应当调查收集。"},{"i":15,"n":"第十五条","txt":"当事人申请通知有专门知识的人出庭，就鉴定人作出的鉴定意见或者就因果关系、生态环境修复方式、生态环境修复费用以及生态环境受到损害至修复完成期间服务功能丧失导致的损失等专门性问题提出意见的，人民法院可以准许。"},{"i":16,"n":"第十六条","txt":"原告在诉讼过程中承认的对己方不利的事实和认可的证据，人民法院认为损害社会公共利益的，应当不予确认。"},{"i":17,"n":"第十七条","txt":"环境民事公益诉讼案件审理过程中，被告以反诉方式提出诉讼请求的，人民法院不予受理。"},{"i":18,"n":"第十八条","txt":"对污染环境、破坏生态，已经损害社会公共利益或者具有损害社会公共利益重大风险的行为，原告可以请求被告承担停止侵害、排除妨碍、消除危险、修复生态环境、赔偿损失、赔礼道歉等民事责任。"},{"i":19,"n":"第十九条","txt":"原告为防止生态环境损害的发生和扩大，请求被告停止侵害、排除妨碍、消除危险的，人民法院可以依法予以支持。"},{"i":20,"n":"第二十条","txt":"原告请求修复生态环境的，人民法院可以依法判决被告将生态环境修复到损害发生之前的状态和功能。无法完全修复的，可以准许采用替代性修复方式。"},{"i":21,"n":"第二十一条","txt":"原告请求被告赔偿生态环境受到损害至修复完成期间服务功能丧失导致的损失、生态环境功能永久性损害造成的损失的，人民法院可以依法予以支持。"},{"i":22,"n":"第二十二条","txt":"原告请求被告承担以下费用的，人民法院可以依法予以支持："},{"i":23,"n":"第二十三条","txt":"生态环境修复费用难以确定或者确定具体数额所需鉴定费用明显过高的，人民法院可以结合污染环境、破坏生态的范围和程度，生态环境的稀缺性，生态环境恢复的难易程度，防治污染设备的运行成本，被告因侵害行为所获得的利益以及过错程度等因素，并可以参考负有环境资源保护监督管理职责的部门的意见、专家意见等，予以合理确定。"},{"i":24,"n":"第二十四条","txt":"人民法院判决被告承担的生态环境修复费用、生态环境受到损害至修复完成期间服务功能丧失导致的损失、生态环境功能永久性损害造成的损失等款项，应当用于修复被损害的生态环境。"},{"i":25,"n":"第二十五条","txt":"环境民事公益诉讼当事人达成调解协议或者自行达成和解协议后，人民法院应当将协议内容公告，公告期间不少于三十日。"},{"i":26,"n":"第二十六条","txt":"负有环境资源保护监督管理职责的部门依法履行监管职责而使原告诉讼请求全部实现，原告申请撤诉的，人民法院应予准许。"},{"i":27,"n":"第二十七条","txt":"法庭辩论终结后，原告申请撤诉的，人民法院不予准许，但本解释第二十六条规定的情形除外。"},{"i":28,"n":"第二十八条","txt":"环境民事公益诉讼案件的裁判生效后，有权提起诉讼的其他机关和社会组织就同一污染环境、破坏生态行为另行起诉，有下列情形之一的，人民法院应予受理："},{"i":29,"n":"第二十九条","txt":"法律规定的机关和社会组织提起环境民事公益诉讼的，不影响因同一污染环境、破坏生态行为受到人身、财产损害的公民、法人和其他组织依据民事诉讼法第一百一十九条的规定提起诉讼。"},{"i":30,"n":"第三十条","txt":"已为环境民事公益诉讼生效裁判认定的事实，因同一污染环境、破坏生态行为依据民事诉讼法第一百一十九条规定提起诉讼的原告、被告均无需举证证明，但原告对该事实有异议并有相反证据足以推翻的除外。"},{"i":31,"n":"第三十一条","txt":"被告因污染环境、破坏生态在环境民事公益诉讼和其他民事诉讼中均承担责任，其财产不足以履行全部义务的，应当先履行其他民事诉讼生效裁判所确定的义务，但法律另有规定的除外。"},{"i":32,"n":"第三十二条","txt":"发生法律效力的环境民事公益诉讼案件的裁判，需要采取强制执行措施的，应当移送执行。"},{"i":33,"n":"第三十三条","txt":"原告交纳诉讼费用确有困难，依法申请缓交的，人民法院应予准许。"},{"i":34,"n":"第三十四条","txt":"社会组织有通过诉讼违法收受财物等牟取经济利益行为的，人民法院可以根据情节轻重依法收缴其非法所得、予以罚款；涉嫌犯罪的，依法移送有关机关处理。"},{"i":35,"n":"第三十五条","txt":"本解释施行前最高人民法院发布的司法解释和规范性文件，与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlishengtaihuanjingqinqccd08d":[{"i":1,"n":"第一条","txt":"人民法院审理生态环境侵权纠纷案件适用惩罚性赔偿，应当严格审慎，注重公平公正，依法保护民事主体合法权益，统筹生态环境保护和经济社会发展。"},{"i":2,"n":"第二条","txt":"因环境污染、生态破坏受到损害的自然人、法人或者非法人组织，依据民法典第一千二百三十二条的规定，请求判令侵权人承担惩罚性赔偿责任的，适用本解释。"},{"i":3,"n":"第三条","txt":"被侵权人在生态环境侵权纠纷案件中请求惩罚性赔偿的，应当在起诉时明确赔偿数额以及所依据的事实和理由。"},{"i":4,"n":"第四条","txt":"被侵权人主张侵权人承担惩罚性赔偿责任的，应当提供证据证明以下事实："},{"i":5,"n":"第五条","txt":"人民法院认定侵权人污染环境、破坏生态的行为是否违反法律规定，应当以法律、法规为依据，可以参照规章的规定。"},{"i":6,"n":"第六条","txt":"人民法院认定侵权人是否具有污染环境、破坏生态的故意，应当根据侵权人的职业经历、专业背景或者经营范围，因同一或者同类行为受到行政处罚或者刑事追究的情况，以及污染物的种类，污染环境、破坏生态行为的方式等因素综合判断。"},{"i":7,"n":"第七条","txt":"具有下列情形之一的，人民法院应当认定侵权人具有污染环境、破坏生态的故意："},{"i":8,"n":"第八条","txt":"人民法院认定侵权人污染环境、破坏生态行为是否造成严重后果，应当根据污染环境、破坏生态行为的持续时间、地域范围，造成环境污染、生态破坏的范围和程度，以及造成的社会影响等因素综合判断。"},{"i":9,"n":"第九条","txt":"人民法院确定惩罚性赔偿金数额，应当以环境污染、生态破坏造成的人身损害赔偿金、财产损失数额作为计算基数。"},{"i":10,"n":"第十条","txt":"人民法院确定惩罚性赔偿金数额，应当综合考虑侵权人的恶意程度、侵权后果的严重程度、侵权人因污染环境、破坏生态行为所获得的利益或者侵权人所采取的修复措施及其效果等因素，但一般不超过人身损害赔偿金、财产损失数额的二倍。"},{"i":11,"n":"第十一条","txt":"侵权人因同一污染环境、破坏生态行为，应当承担包括惩罚性赔偿在内的民事责任、行政责任和刑事责任，其财产不足以支付的，应当优先用于承担民事责任。"},{"i":12,"n":"第十二条","txt":"国家规定的机关或者法律规定的组织作为被侵权人代表，请求判令侵权人承担惩罚性赔偿责任的，人民法院可以参照前述规定予以处理。但惩罚性赔偿金数额的确定，应当以生态环境受到损害至修复完成期间服务功能丧失导致的损失、生态环境功能永久性损害造成的损失数额作为计算基数。"},{"i":13,"n":"第十三条","txt":"侵权行为实施地、损害结果发生地在中华人民共和国管辖海域内的海洋生态环境侵权纠纷案件惩罚性赔偿问题，另行规定。"},{"i":14,"n":"第十四条","txt":"本规定自2022年1月20日起施行。"}],"zuigaorenminfayuanguanyushenlishengtaihuanjingqinq2b185b":[{"i":1,"n":"第一条","txt":"侵权人因实施下列污染环境、破坏生态行为造成他人人身、财产损害，被侵权人请求侵权人承担生态环境侵权责任的，人民法院应予支持："},{"i":2,"n":"第二条","txt":"因下列污染环境、破坏生态引发的民事纠纷，不作为生态环境侵权案件处理："},{"i":3,"n":"第三条","txt":"不动产权利人因经营活动污染环境、破坏生态造成相邻不动产权利人损害，被侵权人请求其承担生态环境侵权责任的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"污染环境、破坏生态造成他人损害，行为人不论有无过错，都应当承担侵权责任。"},{"i":5,"n":"第五条","txt":"两个以上侵权人分别污染环境、破坏生态造成同一损害，每一个侵权人的行为都足以造成全部损害，被侵权人根据民法典第一千一百七十一条的规定请求侵权人承担连带责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"两个以上侵权人分别污染环境、破坏生态，每一个侵权人的行为都不足以造成全部损害，被侵权人根据民法典第一千一百七十二条的规定请求侵权人承担责任的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"两个以上侵权人分别污染环境、破坏生态，部分侵权人的行为足以造成全部损害，部分侵权人的行为只造成部分损害，被侵权人请求足以造成全部损害的侵权人对全部损害承担责任，并与其他侵权人就共同造成的损害部分承担连带责任的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"两个以上侵权人分别污染环境、破坏生态，部分侵权人能够证明其他侵权人的侵权行为已先行造成全部或者部分损害，并请求在相应范围内不承担责任或者减轻责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"两个以上侵权人分别排放的物质相互作用产生污染物造成他人损害，被侵权人请求侵权人承担连带责任的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"为侵权人污染环境、破坏生态提供场地或者储存、运输等帮助，被侵权人根据民法典第一千一百六十九条的规定请求行为人与侵权人承担连带责任的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"过失为侵权人污染环境、破坏生态提供场地或者储存、运输等便利条件，被侵权人请求行为人承担与过错相适应责任的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"排污单位将所属的环保设施委托第三方治理机构运营，第三方治理机构在合同履行过程中污染环境造成他人损害，被侵权人请求排污单位承担侵权责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"排污单位将污染物交由第三方治理机构集中处置，第三方治理机构在合同履行过程中污染环境造成他人损害，被侵权人请求第三方治理机构承担侵权责任的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"存在下列情形之一的，排污单位与第三方治理机构应当根据民法典第一千一百六十八条的规定承担连带责任："},{"i":15,"n":"第十五条","txt":"公司污染环境、破坏生态，被侵权人请求股东承担责任，符合公司法第二十条规定情形的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"侵权人污染环境、破坏生态造成他人损害，被侵权人请求未尽到安全保障义务的经营场所、公共场所的经营者、管理者或者群众性活动的组织者承担相应补充责任的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"依照法律规定应当履行生态环境风险管控和修复义务的民事主体，未履行法定义务造成他人损害，被侵权人请求其承担相应责任的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"因第三人的过错污染环境、破坏生态造成他人损害，被侵权人请求侵权人或者第三人承担责任的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"因第三人的过错污染环境、破坏生态造成他人损害，被侵权人同时起诉侵权人和第三人承担责任，侵权人对损害的发生没有过错的，人民法院应当判令侵权人、第三人就全部损害承担责任。侵权人承担责任后有权向第三人追偿。"},{"i":20,"n":"第二十条","txt":"被侵权人起诉第三人承担责任的，人民法院应当向被侵权人释明是否同时起诉侵权人。被侵权人不起诉侵权人的，人民法院应当根据民事诉讼法第五十九的规定通知侵权人参加诉讼。"},{"i":21,"n":"第二十一条","txt":"环境影响评价机构、环境监测机构以及从事环境监测设备和防治污染设施维护、运营的机构存在下列情形之一，被侵权人请求其与造成环境污染、生态破坏的其他责任人根据环境保护法第六十五条的规定承担连带责任的，人民法院应予支持："},{"i":22,"n":"第二十二条","txt":"被侵权人请求侵权人赔偿因污染环境、破坏生态造成的人身、财产损害，以及为防止损害发生和扩大而采取必要措施所支出的合理费用的，人民法院应予支持。"},{"i":23,"n":"第二十三条","txt":"因污染环境、破坏生态影响他人取水、捕捞、狩猎、采集等日常生活并造成经济损失，同时符合下列情形，请求人主张行为人承担责任的，人民法院应予支持："},{"i":24,"n":"第二十四条","txt":"两个以上侵权人就污染环境、破坏生态造成的损害承担连带责任，实际承担责任超过自己责任份额的侵权人根据民法典第一百七十八条的规定向其他侵权人追偿的，人民法院应予支持。侵权人就惩罚性赔偿责任向其他侵权人追偿的，人民法院不予支持。"},{"i":25,"n":"第二十五条","txt":"两个以上侵权人污染环境、破坏生态造成他人损害，人民法院应当根据行为有无许可，污染物的种类、浓度、排放量、危害性，破坏生态的方式、范围、程度，以及行为对损害后果所起的作用等因素确定各侵权人的责任份额。"},{"i":26,"n":"第二十六条","txt":"被侵权人对同一污染环境、破坏生态行为造成损害的发生或者扩大有重大过失，侵权人请求减轻责任的，人民法院可以予以支持。"},{"i":27,"n":"第二十七条","txt":"被侵权人请求侵权人承担生态环境侵权责任的诉讼时效期间，以被侵权人知道或者应当知道权利受到损害以及侵权人、其他责任人之日起计算。"},{"i":28,"n":"第二十八条","txt":"被侵权人以向负有环境资源监管职能的行政机关请求处理因污染环境、破坏生态造成的损害为由，主张诉讼时效中断的，人民法院应予支持。"},{"i":29,"n":"第二十九条","txt":"本解释自2023年9月1日起施行。"}],"zuigaorenminfayuanguanyushenlikuangchanziyuanjiufedf6990":[{"i":1,"n":"第一条","txt":"矿业权出让部门作为出让人与受让人签订的矿业权出让合同，当事人请求确认自依法成立之日起生效的，人民法院应予支持，但是法律、行政法规另有规定或者当事人另有约定的除外。"},{"i":2,"n":"第二条","txt":"出让人未按照矿业权出让合同的约定为受让人办理矿业权登记，经催告后在合理期限内仍未办理，或者因出让人原因致使受让人受让矿业权后不能依法取得矿业用地进行勘查、开采，受让人请求解除出让合同的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"当事人订立合同对未设置矿业权的矿产资源实施勘查、开采，违反矿产资源法第四条第二款规定的，人民法院应当认定合同无效。"},{"i":4,"n":"第四条","txt":"当事人约定在国家公园等自然保护地区域内勘查、开采矿产资源，违反国家公园法第二十七条、第二十八条等法律、行政法规的强制性规定的，人民法院应当认定合同无效。"},{"i":5,"n":"第五条","txt":"当事人请求确认矿业权转让、出资、抵押或者合作勘查、开采等合同自依法成立之日起生效的，人民法院应予支持，但是国家另有规定、矿业权出让合同或者当事人另有约定的除外。"},{"i":6,"n":"第六条","txt":"矿业权转让、出资合同生效后，矿业权人未依约履行转移矿业权的义务，合同相对人请求其继续履行的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"矿业权转让合同生效后，转让人又将矿业权转让给第三人并办理了转移登记，受让人请求解除合同、返还已付转让款，并由转让人承担违约责任的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"受让人请求确认自矿业权相关事项记载于矿业权登记簿时取得矿业权的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"以矿业权设立抵押，当事人请求确认抵押权自抵押事项记载于矿业权登记簿时设立的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"以矿业权设立抵押，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人依照民事诉讼法第二百零七条、第二百零八条规定申请实现抵押权的，人民法院可以拍卖、变卖矿业权。"},{"i":11,"n":"第十一条","txt":"矿业权依法抵押后，因矿产资源被压覆、矿业权被收回等原因导致矿业权消灭，抵押权人请求按照原抵押权的顺位就抵押人获得的保险金、赔偿金或者补偿金等优先受偿或者将该款项予以提存的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"越界勘查、开采矿产资源纠纷案件中，当事人因登记的勘查、开采区域重叠或者界限不清发生争议，依法应当由有关机关处理的，人民法院裁定不予受理，并告知当事人向有关机关申请解决；已经受理的，裁定驳回起诉。"},{"i":13,"n":"第十三条","txt":"因越界勘查、开采矿产资源，矿业权人请求侵权人承担停止侵害、排除妨碍、返还财产、赔偿损失等民事责任的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"采矿权人请求侵权人赔偿因越界勘查、开采造成的下列损失的，人民法院应予支持："},{"i":15,"n":"第十五条","txt":"下列情形之一，人民法院可以认定为矿产资源法第三十二条规定的“压覆矿产资源”："},{"i":16,"n":"第十六条","txt":"建设单位与矿业权人签订压覆矿产资源补偿协议后未履行约定义务，矿业权人请求建设单位继续履行并承担违约责任的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"建设单位未与矿业权人签订补偿协议即压覆矿产资源，矿业权人请求建设单位承担侵权责任的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"当事人对被压覆矿产资源储量有争议的，人民法院应当根据自然资源主管部门压覆审批时的调查评估报告或者经自然资源主管部门评审备案的储量报告予以认定。"},{"i":19,"n":"第十九条","txt":"矿产资源被压覆时矿业权因期限届满已消灭，原矿业权人基于矿产资源被压覆请求建设单位赔偿或者补偿其损失的，人民法院不予支持，但是有证据证明因建设项目压覆导致矿业权未能续期的除外。"},{"i":20,"n":"第二十条","txt":"矿业权在期限届满前因公共利益的需要被依法收回，矿业权人请求作出收回决定的行政机关给予补偿的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"探矿权人按照规定完成勘查区域的清理、恢复，或者采矿权人按照批准的矿区生态修复方案完成矿区生态修复，并已验收合格的，除有新的事实外，国家规定的机关或者法律规定的组织对同一勘查、开采行为造成的生态破坏提起民事公益诉讼，人民法院不予受理。"},{"i":22,"n":"第二十二条","txt":"人民法院在审理矿产资源纠纷案件中，发现当事人无证勘查、开采，地质资料造假，或者勘查、开采未履行生态环境保护义务等行为涉嫌违法犯罪的，依法将有关违法犯罪线索、材料移送有关机关处理。"},{"i":23,"n":"第二十三条","txt":"2025年7月1日《中华人民共和国矿产资源法》施行前的法律事实引起的矿产资源纠纷案件，适用当时的法律、司法解释的规定，但是法律另有规定的除外。"}],"zuigaorenminfayuanguanyushenlipohuaigongyongdianxi0cd130":[{"i":1,"n":"第一条","txt":"采用截断通信线路、损毁通信设备或者删除、修改、增加电信网计算机信息系统中存储、处理或者传输的数据和应用程序等手段，故意破坏正在使用的公用电信设施，具有下列情形之一的，属于刑法第一百二十四条规定的“危害公共安全”，依照刑法第一百二十四条第一款规定，以破坏公用电信设施罪处三年以上七年以下有期徒刑："},{"i":2,"n":"第二条","txt":"实施本解释第一条规定的行为，具有下列情形之一的，属于刑法第一百二十四条第一款规定的“严重后果”，以破坏公用电信设施罪处七年以上有期徒刑："},{"i":3,"n":"第三条","txt":"故意破坏正在使用的公用电信设施尚未危害公共安全，或者故意毁坏尚未投入使用的公用电信设施，造成财物损失，构成犯罪的，依照刑法第二百七十五条规定，以故意毁坏财物罪定罪处罚。"},{"i":4,"n":"第四条","txt":"指使、组织、教唆他人实施本解释规定的故意犯罪行为的，按照共犯定罪处罚。"},{"i":5,"n":"第五条","txt":"本解释中规定的公用电信设施的范围、用户数、通信中断和严重障碍的标准和时间长度，依据国家电信行业主管部门的有关规定确定。"}],"zuigaorenminfayuanguanyushenlipohuaitudiziyuanxingeffb97":[{"i":1,"n":"第一条","txt":"以牟利为目的，违反土地管理法规，非法转让、倒卖土地使用权，具有下列情形之一的，属于非法转让、倒卖土地使用权“情节严重”，依照刑法第二百二十八条的规定，以非法转让、倒卖土地使用权罪定罪处罚："},{"i":2,"n":"第二条","txt":"实施第一条规定的行为，具有下列情形之一的，属于非法转让、倒卖土地使用权“情节特别严重”："},{"i":3,"n":"第三条","txt":"违反土地管理法规，非法占用耕地改作他用，数量较大，造成耕地大量毁坏的，依照刑法第三百四十二条的规定，以非法占用耕地罪定罪处罚："},{"i":4,"n":"第四条","txt":"国家机关工作人员徇私舞弊，违反土地管理法规，滥用职权，非法批准征用、占用土地，具有下列情形之一的，属于非法批准征用、占用土地“情节严重”，依照刑法第四百一十条的规定，以非法批准征用、占用土地罪定罪处罚："},{"i":5,"n":"第五条","txt":"实施第四条规定的行为，具有下列情形之一的，属于非法批准征用、占用土地“致使国家或者集体利益遭受特别重大损失”："},{"i":6,"n":"第六条","txt":"国家机关工作人员徇私舞弊，违反土地管理法规，非法低价出让国有土地使用权，具有下列情形之一的，属于“情节严重”，依照刑法第四百一十条的规定，以非法低价出让国有土地使用权罪定罪处罚："},{"i":7,"n":"第七条","txt":"实施第六条规定的行为，具有下列情形之一的，属于非法低价出让国有土地使用权，“致使国家和集体利益遭受特别重大损失”："},{"i":8,"n":"第八条","txt":"单位犯非法转让、倒卖土地使用权罪、非法占有耕地罪的定罪量刑标准，依照本解释第一条、第二条、第三条的规定执行。"},{"i":9,"n":"第九条","txt":"多次实施本解释规定的行为依法应当追诉的，或者1年内多次实施本解释规定的行为未经处理的，按照累计的数量、数额处罚。"}],"zuigaorenminfayuanguanyushenlipohuaiguangbodianshi6338cc":[{"i":1,"n":"第一条","txt":"采取拆卸、毁坏设备，剪割缆线，删除、修改、增加广播电视设备系统中存储、处理、传输的数据和应用程序，非法占用频率等手段，破坏正在使用的广播电视设施，具有下列情形之一的，依照刑法第一百二十四条第一款的规定，以破坏广播电视设施罪处三年以上七年以下有期徒刑："},{"i":2,"n":"第二条","txt":"实施本解释第一条规定的行为，具有下列情形之一的，应当认定为刑法第一百二十四条第一款规定的“造成严重后果”，以破坏广播电视设施罪处七年以上有期徒刑："},{"i":3,"n":"第三条","txt":"过失损坏正在使用的广播电视设施，造成本解释第二条规定的严重后果的，依照刑法第一百二十四条第二款的规定，以过失损坏广播电视设施罪处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。"},{"i":4,"n":"第四条","txt":"建设、施工单位的管理人员、施工人员，在建设、施工过程中，违反广播电视设施保护规定，故意或者过失损毁正在使用的广播电视设施，构成犯罪的，以破坏广播电视设施罪或者过失损坏广播电视设施罪定罪处罚。其定罪量刑标准适用本解释第一至三条的规定。"},{"i":5,"n":"第五条","txt":"盗窃正在使用的广播电视设施，尚未构成盗窃罪，但具有本解释第一条、第二条规定情形的，以破坏广播电视设施罪定罪处罚；同时构成盗窃罪和破坏广播电视设施罪的，依照处罚较重的规定定罪处罚。"},{"i":6,"n":"第六条","txt":"破坏正在使用的广播电视设施未危及公共安全，或者故意毁坏尚未投入使用的广播电视设施，造成财物损失数额较大或者有其他严重情节的，以故意毁坏财物罪定罪处罚。"},{"i":7,"n":"第七条","txt":"实施破坏广播电视设施犯罪，并利用广播电视设施实施煽动分裂国家、煽动颠覆国家政权、煽动民族仇恨、民族歧视或者宣扬邪教等行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":8,"n":"第八条","txt":"本解释所称广播电视台中直接关系节目播出的设施、广播电视传输网内的设施，参照国家广播电视行政主管部门和其他相关部门的有关规定确定。"}],"zuigaorenminfayuanguanyushenlipohuaisenlinziyuanxi15f03c":[{"i":1,"n":"第一条","txt":"违反土地管理法规，非法占用林地，改变被占用林地用途，具有下列情形之一的，应当认定为刑法第三百四十二条规定的造成林地“毁坏”："},{"i":2,"n":"第二条","txt":"违反国家规定，非法采伐、毁坏列入《国家重点保护野生植物名录》的野生植物，或者非法收购、运输、加工、出售明知是非法采伐、毁坏的上述植物及其制品，具有下列情形之一的，应当依照刑法第三百四十四条的规定，以危害国家重点保护植物罪定罪处罚："},{"i":3,"n":"第三条","txt":"以非法占有为目的，具有下列情形之一的，应当认定为刑法第三百四十五条第一款规定的“盗伐森林或者其他林木”："},{"i":4,"n":"第四条","txt":"盗伐森林或者其他林木，涉案林木具有下列情形之一的，应当认定为刑法第三百四十五条第一款规定的“数量较大”："},{"i":5,"n":"第五条","txt":"具有下列情形之一的，应当认定为刑法第三百四十五条第二款规定的“滥伐森林或者其他林木”："},{"i":6,"n":"第六条","txt":"滥伐森林或者其他林木，涉案林木具有下列情形之一的，应当认定为刑法第三百四十五条第二款规定的“数量较大”："},{"i":7,"n":"第七条","txt":"认定刑法第三百四十五条第三款规定的“明知是盗伐、滥伐的林木”，应当根据涉案林木的销售价格、来源以及收购、运输行为违反有关规定等情节，结合行为人的职业要求、经历经验、前科情况等作出综合判断。"},{"i":8,"n":"第八条","txt":"非法收购、运输明知是盗伐、滥伐的林木，具有下列情形之一的，应当认定为刑法第三百四十五条第三款规定的“情节严重”："},{"i":9,"n":"第九条","txt":"多次实施本解释规定的行为，未经处理，且依法应当追诉的，数量、数额累计计算。"},{"i":10,"n":"第十条","txt":"伪造、变造、买卖采伐许可证，森林、林地、林木权属证书以及占用或者征用林地审核同意书等国家机关批准的林业证件、文件构成犯罪的，依照刑法第二百八十条第一款的规定，以伪造、变造、买卖国家机关公文、证件罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"下列行为，符合刑法第二百六十四条规定的，以盗窃罪定罪处罚："},{"i":12,"n":"第十二条","txt":"实施破坏森林资源犯罪，具有下列情形之一的，从重处罚："},{"i":13,"n":"第十三条","txt":"单位犯刑法第三百四十二条、第三百四十四条、第三百四十五条规定之罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":14,"n":"第十四条","txt":"针对国家、集体或者他人所有的国家重点保护植物和其他林木实施犯罪的违法所得及其收益，应当依法追缴或者责令退赔。"},{"i":15,"n":"第十五条","txt":"组织他人实施本解释规定的破坏森林资源犯罪的，应当按照其组织实施的全部罪行处罚。"},{"i":16,"n":"第十六条","txt":"对于实施本解释规定的相关行为未被追究刑事责任的行为人，依法应当给予行政处罚、政务处分或者其他处分的，移送有关主管机关处理。"},{"i":17,"n":"第十七条","txt":"涉案国家重点保护植物或者其他林木的价值，可以根据销赃数额认定；无销赃数额，销赃数额难以查证，或者根据销赃数额认定明显不合理的，根据市场价格认定。"},{"i":18,"n":"第十八条","txt":"对于涉案农用地类型、面积，国家重点保护植物或者其他林木的种类、立木蓄积、株数、价值，以及涉案行为对森林资源的损害程度等问题，可以由林业主管部门、侦查机关依据现场勘验、检查笔录等出具认定意见；难以确定的，依据鉴定机构出具的鉴定意见或者下列机构出具的报告，结合其他证据作出认定："},{"i":19,"n":"第十九条","txt":"本解释所称“立木蓄积”的计算方法为：原木材积除以该树种的出材率。"},{"i":20,"n":"第二十条","txt":"本解释自2023年8月15日起施行。本解释施行后，《最高人民法院关于滥伐自己所有权的林木其林木应如何处理的问题的批复》（法复〔1993〕5号）、《最高人民法院关于审理破坏森林资源刑事案件具体应用法律若干问题的解释》（法释〔2000〕36号）、《最高人民法院关于在林木采伐许可证规定的地点以外采伐本单位或者本人所有的森林或者其他林木的行为如何适用法律问题的批复》（法释〔2004〕3号）、《最高人民法院关于审理破坏林地资源刑事案件具体应用法律若干问题的解释》（法释〔2005〕15号）同时废止；之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlipohuaicaoyuanziyuanxa7e570":[{"i":1,"n":"第一条","txt":"违反草原法等土地管理法规，非法占用草原，改变被占用草原用途，数量较大，造成草原大量毁坏的，依照刑法第三百四十二条的规定，以非法占用农用地罪定罪处罚。"},{"i":2,"n":"第二条","txt":"非法占用草原，改变被占用草原用途，数量在二十亩以上的，或者曾因非法占用草原受过行政处罚，在三年内又非法占用草原，改变被占用草原用途，数量在十亩以上的，应当认定为刑法第三百四十二条规定的“数量较大”。"},{"i":3,"n":"第三条","txt":"国家机关工作人员徇私舞弊，违反草原法等土地管理法规，具有下列情形之一的，应当认定为刑法第四百一十条规定的“情节严重”："},{"i":4,"n":"第四条","txt":"以暴力、威胁方法阻碍草原监督检查人员依法执行职务，构成犯罪的，依照刑法第二百七十七条的规定，以妨害公务罪追究刑事责任。"},{"i":5,"n":"第五条","txt":"单位实施刑法第三百四十二条规定的行为，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本解释规定的定罪量刑标准定罪处罚。"},{"i":6,"n":"第六条","txt":"多次实施破坏草原资源的违法犯罪行为，未经处理，应当依法追究刑事责任的，按照累计的数量、数额定罪处罚。"},{"i":7,"n":"第七条","txt":"本解释所称“草原”，是指天然草原和人工草地，天然草原包括草地、草山和草坡，人工草地包括改良草地和退耕还草地，不包括城镇草地。"}],"zuigaorenminfayuanguanyushenlibianzaoguyichuanboxuc38edd":[{"i":1,"n":"第一条","txt":"编造恐怖信息，传播或者放任传播，严重扰乱社会秩序的，依照刑法第二百九十一条之一的规定，应认定为编造虚假恐怖信息罪。"},{"i":2,"n":"第二条","txt":"编造、故意传播虚假恐怖信息，具有下列情形之一的，应当认定为刑法第二百九十一条之一的“严重扰乱社会秩序”："},{"i":3,"n":"第三条","txt":"编造、故意传播虚假恐怖信息，严重扰乱社会秩序，具有下列情形之一的，应当依照刑法第二百九十一条之一的规定，在五年以下有期徒刑范围内酌情从重处罚："},{"i":4,"n":"第四条","txt":"编造、故意传播虚假恐怖信息，严重扰乱社会秩序，具有下列情形之一的，应当认定为刑法第二百九十一条之一的“造成严重后果”，处五年以上有期徒刑："},{"i":5,"n":"第五条","txt":"编造、故意传播虚假恐怖信息，严重扰乱社会秩序，同时又构成其他犯罪的，择一重罪处罚。"},{"i":6,"n":"第六条","txt":"本解释所称的“虚假恐怖信息”，是指以发生爆炸威胁、生化威胁、放射威胁、劫持航空器威胁、重大灾情、重大疫情等严重威胁公共安全的事件为内容，可能引起社会恐慌或者公共安全危机的不真实信息。"}],"zuigaorenminfayuanguanyushenlizhuzuoquanminshijiufaf346d":[{"i":1,"n":"第一条","txt":"人民法院受理以下著作权民事纠纷案件："},{"i":2,"n":"第二条","txt":"著作权民事纠纷案件，由中级以上人民法院管辖。"},{"i":3,"n":"第三条","txt":"对著作权行政管理部门查处的侵害著作权行为，当事人向人民法院提起诉讼追究该行为人民事责任的，人民法院应当受理。"},{"i":4,"n":"第四条","txt":"因侵害著作权行为提起的民事诉讼，由著作权法第四十七条、第四十八条所规定侵权行为的实施地、侵权复制品储藏地或者查封扣押地、被告住所地人民法院管辖。"},{"i":5,"n":"第五条","txt":"对涉及不同侵权行为实施地的多个被告提起的共同诉讼，原告可以选择向其中一个被告的侵权行为实施地人民法院提起诉讼；"},{"i":6,"n":"第六条","txt":"依法成立的著作权集体管理组织，根据著作权人的书面授权，以自己的名义提起诉讼，人民法院应当受理。"},{"i":7,"n":"第七条","txt":"当事人提供的涉及著作权的底稿、原件、合法出版物、著作权登记证书、认证机构出具的证明、取得权利的合同等，可以作为证据。"},{"i":8,"n":"第八条","txt":"当事人自行或者委托他人以定购、现场交易等方式购买侵权复制品而取得的实物、发票等，可以作为证据。"},{"i":9,"n":"第九条","txt":"著作权法第十条第（一）项规定的“公之于众”，是指著作权人自行或者经著作权人许可将作品向不特定的人公开，但不以公众知晓为构成条件。"},{"i":10,"n":"第十条","txt":"著作权法第十五条第二款所指的作品，著作权人是自然人的，其保护期适用著作权法第二十一条第一款的规定；"},{"i":11,"n":"第十一条","txt":"因作品署名顺序发生的纠纷，人民法院按照下列原则处理："},{"i":12,"n":"第十二条","txt":"按照著作权法第十七条规定委托作品著作权属于受托人的情形，委托人在约定的使用范围内享有使用作品的权利；"},{"i":13,"n":"第十三条","txt":"除著作权法第十一条第三款规定的情形外，由他人执笔，本人审阅定稿并以本人名义发表的报告、讲话等作品，著作权归报告人或者讲话人享有。"},{"i":14,"n":"第十四条","txt":"当事人合意以特定人物经历为题材完成的自传体作品，当事人对著作权权属有约定的，依其约定；"},{"i":15,"n":"第十五条","txt":"由不同作者就同一题材创作的作品，作品的表达系独立完成并且有创作性的，应当认定作者各自享有独立著作权。"},{"i":16,"n":"第十六条","txt":"通过大众传播媒介传播的单纯事实消息属于著作权法第五条第（二）项规定的时事新闻。"},{"i":17,"n":"第十七条","txt":"著作权法第三十三条第二款规定的转载，是指报纸、期刊登载其他报刊已发表作品的行为。"},{"i":18,"n":"第十八条","txt":"著作权法第二十二条第（十）项规定的室外公共场所的艺术作品，是指设置或者陈列在室外社会公众活动处所的雕塑、绘画、书法等艺术作品。"},{"i":19,"n":"第十九条","txt":"出版者、制作者应当对其出版、制作有合法授权承担举证责任，发行者、出租者应当对其发行或者出租的复制品有合法来源承担举证责任。"},{"i":20,"n":"第二十条","txt":"出版物侵害他人著作权的，出版者应当根据其过错、侵权程度及损害后果等承担赔偿损失的责任。"},{"i":21,"n":"第二十一条","txt":"计算机软件用户未经许可或者超过许可范围商业使用计算机软件的，依据著作权法第四十八条第（一）项、《计算机软件保护条例》第二十四条第（一）项的规定承担民事责任。"},{"i":22,"n":"第二十二条","txt":"著作权转让合同未采取书面形式的，人民法院依据民法典第四百九十条的规定审查合同是否成立。"},{"i":23,"n":"第二十三条","txt":"出版者将著作权人交付出版的作品丢失、毁损致使出版合同不能履行的，著作权人有权依据民法典第一百八十六条、第二百三十八条、第一千一百八十四条等规定要求出版者承担相应的民事责任。"},{"i":24,"n":"第二十四条","txt":"权利人的实际损失，可以根据权利人因侵权所造成复制品发行减少量或者侵权复制品销售量与权利人发行该复制品单位利润乘积计算。"},{"i":25,"n":"第二十五条","txt":"权利人的实际损失或者侵权人的违法所得无法确定的，人民法院根据当事人的请求或者依职权适用著作权法第四十九条第二款的规定确定赔偿数额。"},{"i":26,"n":"第二十六条","txt":"著作权法第四十九条第一款规定的制止侵权行为所支付的合理开支，包括权利人或者委托代理人对侵权行为进行调查、取证的合理费用。"},{"i":27,"n":"第二十七条","txt":"侵害著作权的诉讼时效为三年，自著作权人知道或者应当知道权利受到损害以及义务人之日起计算。"},{"i":28,"n":"第二十八条","txt":"人民法院采取保全措施的，依据民事诉讼法及《最高人民法院关于审查知识产权纠纷行为保全案件适用法律若干问题的规定》的有关规定办理。"},{"i":29,"n":"第二十九条","txt":"除本解释另行规定外，人民法院受理的著作权民事纠纷案件，涉及著作权法修改前发生的民事行为的，适用修改前著作权法的规定；"},{"i":30,"n":"第三十条","txt":"以前的有关规定与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlirongzizulinhetongjiuc13af6":[{"i":1,"n":"第一条","txt":"人民法院应当根据民法典第七百三十五条的规定，结合标的物的性质、价值、租金的构成以及当事人的合同权利和义务，对是否构成融资租赁法律关系作出认定。"},{"i":2,"n":"第二条","txt":"承租人将其自有物出卖给出租人，再通过融资租赁合同将租赁物从出租人处租回的，人民法院不应仅以承租人和出卖人系同一人为由认定不构成融资租赁法律关系。"},{"i":3,"n":"第三条","txt":"承租人拒绝受领租赁物，未及时通知出租人，或者无正当理由拒绝受领租赁物，造成出租人损失，出租人向承租人主张损害赔偿的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"出租人转让其在融资租赁合同项下的部分或者全部权利，受让方以此为由请求解除或者变更融资租赁合同的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"有下列情形之一，出租人请求解除融资租赁合同的，人民法院应予支持："},{"i":6,"n":"第六条","txt":"因出租人的原因致使承租人无法占有、使用租赁物，承租人请求解除融资租赁合同的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"当事人在一审诉讼中仅请求解除融资租赁合同，未对租赁物的归属及损失赔偿提出主张的，人民法院可以向当事人进行释明。"},{"i":8,"n":"第八条","txt":"租赁物不符合融资租赁合同的约定且出租人实施了下列行为之一，承租人依照民法典第七百四十四条、第七百四十七条的规定，要求出租人承担相应责任的，人民法院应予支持："},{"i":9,"n":"第九条","txt":"承租人逾期履行支付租金义务或者迟延履行其他付款义务，出租人按照融资租赁合同的约定要求承租人支付逾期利息、相应违约金的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"出租人既请求承租人支付合同约定的全部未付租金又请求解除融资租赁合同的，人民法院应告知其依照民法典第七百五十二条的规定作出选择。"}],"zuigaorenminfayuanguanyushenlitanwuzhiwuqinzhananjf0da25":[{"i":1,"n":"第一条","txt":"行为人与国家工作人员勾结，利用国家工作人员的职务便利，共同侵吞、窃取、骗取或者以其他手段非法占有公共财物的，以贪污罪共犯论处。"},{"i":2,"n":"第二条","txt":"行为人与公司、企业或者其他单位的人员勾结，利用公司、企业或者其他单位人员的职务便利，共同将该单位财物非法占为己有，数额较大的，以职务侵占罪共犯论处。"},{"i":3,"n":"第三条","txt":"公司、企业或者其他单位中，不具有国家工作人员身份的人与国家工作人员勾结，分别利用各自的职务便利，共同将本单位财物非法占为己有的，按照主犯的犯罪性质定罪。"}],"zuigaorenminfayuanguanyushenlizousifeifajingyingfe1e170f":[{"i":1,"n":"第一条","txt":"运动员、运动员辅助人员走私兴奋剂目录所列物质，或者其他人员以在体育竞赛中非法使用为目的走私兴奋剂目录所列物质，涉案物质属于国家禁止进出口的货物、物品，具有下列情形之一的，应当依照刑法第一百五十一条第三款的规定，以走私国家禁止进出口的货物、物品罪定罪处罚："},{"i":2,"n":"第二条","txt":"违反国家规定，未经许可经营兴奋剂目录所列物质，涉案物质属于法律、行政法规规定的限制买卖的物品，扰乱市场秩序，情节严重的，应当依照刑法第二百二十五条的规定，以非法经营罪定罪处罚。"},{"i":3,"n":"第三条","txt":"对未成年人、残疾人负有监护、看护职责的人组织未成年人、残疾人在体育运动中非法使用兴奋剂，具有下列情形之一的，应当认定为刑法第二百六十条之一规定的“情节恶劣”，以虐待被监护、看护人罪定罪处罚："},{"i":4,"n":"第四条","txt":"在普通高等学校招生、公务员录用等法律规定的国家考试涉及的体育、体能测试等体育运动中，组织考生非法使用兴奋剂的，应当依照刑法第二百八十四条之一的规定，以组织考试作弊罪定罪处罚。"},{"i":5,"n":"第五条","txt":"生产、销售含有兴奋剂目录所列物质的食品，符合刑法第一百四十三条、第一百四十四条规定的，以生产、销售不符合安全标准的食品罪、生产、销售有毒、有害食品罪定罪处罚。"},{"i":6,"n":"第六条","txt":"国家机关工作人员在行使反兴奋剂管理职权时滥用职权或者玩忽职守，造成严重兴奋剂违规事件，严重损害国家声誉或者造成恶劣社会影响，符合刑法第三百九十七条规定的，以滥用职权罪、玩忽职守罪定罪处罚。"},{"i":7,"n":"第七条","txt":"实施本解释规定的行为，涉案物质属于毒品、制毒物品等，构成有关犯罪的，依照相应犯罪定罪处罚。"},{"i":8,"n":"第八条","txt":"对于是否属于本解释规定的“兴奋剂”“兴奋剂目录所列物质”“体育运动”“国内、国际重大体育竞赛”等专门性问题，应当依据《中华人民共和国体育法》《反兴奋剂条例》等法律法规，结合国务院体育主管部门出具的认定意见等证据材料作出认定。"},{"i":9,"n":"第九条","txt":"本解释自2020年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlidaolujiaotongshigusueab0ac":[{"i":1,"n":"第一条","txt":"机动车发生交通事故造成损害，机动车所有人或者管理人有下列情形之一，人民法院应当认定其对损害的发生有过错，并适用民法典第一千二百零九条的规定确定其相应的赔偿责任："},{"i":2,"n":"第二条","txt":"被多次转让但是未办理登记的机动车发生交通事故造成损害，属于该机动车一方责任，当事人请求由最后一次转让并交付的受让人承担赔偿责任的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"套牌机动车发生交通事故造成损害，属于该机动车一方责任，当事人请求由套牌机动车的所有人或者管理人承担赔偿责任的，人民法院应予支持；被套牌机动车所有人或者管理人同意套牌的，应当与套牌机动车的所有人或者管理人承担连带责任。"},{"i":4,"n":"第四条","txt":"拼装车、已达到报废标准的机动车或者依法禁止行驶的其他机动车被多次转让，并发生交通事故造成损害，当事人请求由所有的转让人和受让人承担连带责任的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"接受机动车驾驶培训的人员，在培训活动中驾驶机动车发生交通事故造成损害，属于该机动车一方责任，当事人请求驾驶培训单位承担赔偿责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"机动车试乘过程中发生交通事故造成试乘人损害，当事人请求提供试乘服务者承担赔偿责任的，人民法院应予支持。试乘人有过错的，应当减轻提供试乘服务者的赔偿责任。"},{"i":7,"n":"第七条","txt":"因道路管理维护缺陷导致机动车发生交通事故造成损害，当事人请求道路管理者承担相应赔偿责任的，人民法院应予支持。但道路管理者能够证明已经依照法律、法规、规章的规定，或者按照国家标准、行业标准、地方标准的要求尽到安全防护、警示等管理维护义务的除外。"},{"i":8,"n":"第八条","txt":"未按照法律、法规、规章或者国家标准、行业标准、地方标准的强制性规定设计、施工，致使道路存在缺陷并造成交通事故，当事人请求建设单位与施工单位承担相应赔偿责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"机动车存在产品缺陷导致交通事故造成损害，当事人请求生产者或者销售者依照民法典第七编第四章的规定承担赔偿责任的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"多辆机动车发生交通事故造成第三人损害，当事人请求多个侵权人承担赔偿责任的，人民法院应当区分不同情况，依照民法典第一千一百七十条、第一千一百七十一条、第一千一百七十二条的规定，确定侵权人承担连带责任或者按份责任。"},{"i":11,"n":"第十一条","txt":"道路交通安全法第七十六条规定的“人身伤亡”，是指机动车发生交通事故侵害被侵权人的生命权、身体权、健康权等人身权益所造成的损害，包括民法典第一千一百七十九条和第一千一百八十三条规定的各项损害。"},{"i":12,"n":"第十二条","txt":"因道路交通事故造成下列财产损失，当事人请求侵权人赔偿的，人民法院应予支持："},{"i":13,"n":"第十三条","txt":"同时投保机动车第三者责任强制保险（以下简称交强险）和第三者责任商业保险（以下简称商业三者险）的机动车发生交通事故造成损害，当事人同时起诉侵权人和保险公司的，人民法院应当依照民法典第一千二百一十三条的规定，确定赔偿责任。"},{"i":14,"n":"第十四条","txt":"投保人允许的驾驶人驾驶机动车致使投保人遭受损害，当事人请求承保交强险的保险公司在责任限额范围内予以赔偿的，人民法院应予支持，但投保人为本车上人员的除外。"},{"i":15,"n":"第十五条","txt":"有下列情形之一导致第三人人身损害，当事人请求保险公司在交强险责任限额范围内予以赔偿，人民法院应予支持："},{"i":16,"n":"第十六条","txt":"未依法投保交强险的机动车发生交通事故造成损害，当事人请求投保义务人在交强险责任限额范围内予以赔偿的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"具有从事交强险业务资格的保险公司违法拒绝承保、拖延承保或者违法解除交强险合同，投保义务人在向第三人承担赔偿责任后，请求该保险公司在交强险责任限额范围内承担相应赔偿责任的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"多辆机动车发生交通事故造成第三人损害，损失超出各机动车交强险责任限额之和的，由各保险公司在各自责任限额范围内承担赔偿责任；损失未超出各机动车交强险责任限额之和，当事人请求由各保险公司按照其责任限额与责任限额之和的比例承担赔偿责任的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"同一交通事故的多个被侵权人同时起诉的，人民法院应当按照各被侵权人的损失比例确定交强险的赔偿数额。"},{"i":20,"n":"第二十条","txt":"机动车所有权在交强险合同有效期内发生变动，保险公司在交通事故发生后，以该机动车未办理交强险合同变更手续为由主张免除赔偿责任的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"当事人主张交强险人身伤亡保险金请求权转让或者设定担保的行为无效的，人民法院应予支持。"},{"i":22,"n":"第二十二条","txt":"人民法院审理道路交通事故损害赔偿案件，应当将承保交强险的保险公司列为共同被告。但该保险公司已经在交强险责任限额范围内予以赔偿且当事人无异议的除外。"},{"i":23,"n":"第二十三条","txt":"被侵权人因道路交通事故死亡，无近亲属或者近亲属不明，未经法律授权的机关或者有关组织向人民法院起诉主张死亡赔偿金的，人民法院不予受理。"},{"i":24,"n":"第二十四条","txt":"公安机关交通管理部门制作的交通事故认定书，人民法院应依法审查并确认其相应的证明力，但有相反证据推翻的除外。"},{"i":25,"n":"第二十五条","txt":"机动车在道路以外的地方通行时引发的损害赔偿案件，可以参照适用本解释的规定。"},{"i":26,"n":"第二十六条","txt":"本解释施行后尚未终审的案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。"}],"zuigaorenminfayuanguanyushenlidaolujiaotongshigusua499ce":[{"i":1,"n":"第一条","txt":"因租赁、借用等情形机动车所有人、管理人与使用人不是同一人时，发生交通事故造成他人损害，对于该机动车一方责任，被侵权人一并请求机动车使用人与机动车所有人、管理人承担的，由机动车使用人承担侵权人应承担的全部责任；机动车所有人、管理人对损害的发生有过错的，在其过错范围内与机动车使用人共同承担赔偿责任，但是责任主体实际支付的赔偿费用总和不应超出被侵权人应受偿的损失数额。"},{"i":2,"n":"第二条","txt":"机动车乘车人开车门致他人损害，被侵权人一并起诉乘车人、驾驶人以及承保该机动车交通事故责任强制保险（以下简称交强险）、第三者责任商业保险（以下简称商业三者险）的保险人，主张乘车人责任属于该机动车一方责任，并依据民法典第一千二百一十三条关于交通事故责任承担主体赔偿顺序的规定，请求由承保交强险的保险人在责任限额范围内予以赔偿、承保商业三者险的保险人按照保险合同的约定予以赔偿的，人民法院应予支持；保险人以乘车人不属于被保险人或者其允许的驾驶人为由抗辩不承担赔偿责任的，人民法院对该抗辩不予支持。赔偿后不足的，由乘车人、驾驶人依据民法典第七编侵权责任的规定承担赔偿责任。"},{"i":3,"n":"第三条","txt":"非营运机动车发生交通事故造成无偿搭乘人损害，对于该机动车一方责任，被侵权人起诉机动车使用人承担，机动车使用人主张减轻自身赔偿责任的，人民法院应予支持。但是，机动车使用人有故意或者重大过失的除外。"},{"i":4,"n":"第四条","txt":"机动车在驾驶人驾驶证超过有效期但是尚未被注销期间，发生交通事故造成他人损害，被侵权人主张承保交强险、商业三者险的保险人承担保险责任，保险人仅以机动车驾驶人的驾驶证超过有效期为由拒绝承担保险责任的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"起重、升降等工程专项作业机动车发生交通事故造成他人损害，被侵权人主张保险人在交强险责任限额范围内承担赔偿责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"被侵权人超过法定退休年龄，但是有证据证明因交通事故产生误工损失并请求侵权人赔偿的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"被侵权人因交通事故致残后，又因其他原因在道路交通事故损害赔偿案件诉讼期间死亡，赔偿权利人主张按照《最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释》第十二条关于残疾赔偿金赔偿的标准计算残疾赔偿金的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"交通事故被侵权人有多个被扶养人的，确定被扶养人的生活费，应当根据被侵权人丧失劳动能力程度计算出单个被扶养人生活费，再将各被扶养人生活费相加，相加后年赔偿总额以不超过上一年度城镇居民人均消费支出额为限。"},{"i":9,"n":"第九条","txt":"道路交通事故损害赔偿案件中，侵权人及其保险人败诉的，人民法院应当根据各方对诉讼标的的利害关系决定各自负担的案件受理费数额；保险人仅以保险合同约定其不承担案件受理费为由抗辩的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"当事人就基本医疗保险基金、工伤保险基金已经支付的医疗费用和道路交通事故社会救助基金垫付的抢救费用、丧葬费用请求侵权人承担赔偿责任的，人民法院不予支持。"},{"i":11,"n":"第十一条","txt":"当事人以侵权人为被告提起非机动车交通事故责任纠纷诉讼，同时将承保非机动车商业三者险的保险人列为被告并请求其承担赔偿责任的，人民法院应当合并审理。"},{"i":12,"n":"第十二条","txt":"本解释自2026年6月30日起施行。"}],"zuigaorenminfayuanguanyushenlitieluyunshurenshensuacfb17":[{"i":1,"n":"第一条","txt":"人民法院审理铁路行车事故及其他铁路运营事故造成的铁路运输人身损害赔偿纠纷案件，适用本解释。"},{"i":2,"n":"第二条","txt":"铁路运输人身损害的受害人以及死亡受害人的近亲属为赔偿权利人，有权请求赔偿。"},{"i":3,"n":"第三条","txt":"赔偿权利人要求对方当事人承担侵权责任的，由事故发生地、列车最先到达地或者被告住所地铁路运输法院管辖。"},{"i":4,"n":"第四条","txt":"铁路运输造成人身损害的，铁路运输企业应当承担赔偿责任；法律另有规定的，依照其规定。"},{"i":5,"n":"第五条","txt":"铁路行车事故及其他铁路运营事故造成人身损害，有下列情形之一的，铁路运输企业不承担赔偿责任："},{"i":6,"n":"第六条","txt":"因受害人的过错行为造成人身损害，依照法律规定应当由铁路运输企业承担赔偿责任的，根据受害人的过错程度可以适当减轻铁路运输企业的赔偿责任，并按照以下情形分别处理："},{"i":7,"n":"第七条","txt":"铁路运输造成无民事行为能力人人身损害的，铁路运输企业应当承担赔偿责任；监护人有过错的，按照过错程度减轻铁路运输企业的赔偿责任。"},{"i":8,"n":"第八条","txt":"铁路机车车辆与机动车发生碰撞造成机动车驾驶人员以外的人人身损害的，由铁路运输企业与机动车一方对受害人承担连带赔偿责任。铁路运输企业与机动车一方之间的责任份额根据各自责任大小确定；难以确定责任大小的，平均承担责任。对受害人实际承担赔偿责任超出应当承担份额的一方，有权向另一方追偿。"},{"i":9,"n":"第九条","txt":"在非铁路运输企业实行监护的铁路无人看守道口发生事故造成人身损害的，由铁路运输企业按照本解释的有关规定承担赔偿责任。道口管理单位有过错的，铁路运输企业对赔偿权利人承担赔偿责任后，有权向道口管理单位追偿。"},{"i":10,"n":"第十条","txt":"对于铁路桥梁、涵洞等设施负有管理、维护等职责的单位，因未尽职责使该铁路桥梁、涵洞等设施不能正常使用，导致行人、车辆穿越铁路线路造成人身损害的，铁路运输企业按照本解释有关规定承担赔偿责任后，有权向该单位追偿。"},{"i":11,"n":"第十一条","txt":"有权作出事故认定的组织依照《铁路交通事故应急救援和调查处理条例》等有关规定制作的事故认定书，经庭审质证，对于事故认定书所认定的事实，当事人没有相反证据和理由足以推翻的，人民法院应当作为认定事实的根据。"},{"i":12,"n":"第十二条","txt":"在专用铁路及铁路专用线上因运输造成人身损害，依法应当由肇事工具或者设备的所有人、使用人或者管理人承担赔偿责任的，适用本解释。"},{"i":13,"n":"第十三条","txt":"本院以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlitieluyunshusunhaipei2008ef":[],"zuigaorenminfayuanguanyushenlifeifachubanwuxingshiffa8d7":[{"i":1,"n":"第一条","txt":"明知出版物中载有煽动分裂国家、破坏国家统一或者煽动颠覆国家政权、推翻社会主义制度的内容，而予以出版、印刷、复制、发行、传播的，依照刑法第一百零三条第二款或者第一百零五条第二款的规定，以煽动分裂国家罪或者煽动颠覆国家政权罪定罪处罚。"},{"i":2,"n":"第二条","txt":"以营利为目的，实施刑法第二百一十七条所列侵犯著作权行为之一，个人违法所得数额在5万元以上，单位违法所得数额在20万元以上的，属于“违法所得数额较大”；具有下列情形之一的，属于“有其他严重情节”："},{"i":3,"n":"第三条","txt":"刑法第二百一十七条第（一）项中规定的“复制发行”，是指行为人以营利为目的，未经著作权人许可而实施的复制、发行或者既复制又发行其文字作品、音乐、电影、电视、录像作品、计算机软件及其他作品的行为。"},{"i":4,"n":"第四条","txt":"以营利为目的，实施刑法第二百一十八条规定的行为，个人违法所得数额在10万元以上，单位违法所得数额在50万元以上的，依照刑法第二百一十八条的规定，以销售侵权复制品罪定罪处罚。"},{"i":5,"n":"第五条","txt":"实施刑法第二百一十七条规定的侵犯著作权行为，又销售该侵权复制品，违法所得数额巨大的，只定侵犯著作权罪，不实行数罪并罚。"},{"i":6,"n":"第六条","txt":"在出版物中公然侮辱他人或者捏造事实诽谤他人，情节严重的，依照刑法第二百四十六条的规定，分别以侮辱罪或者诽谤罪定罪处罚。"},{"i":7,"n":"第七条","txt":"出版刊载歧视、侮辱少数民族内容的作品，情节恶劣，造成严重后果的，依照刑法第二百五十条的规定，以出版歧视、侮辱少数民族作品罪定罪处罚。"},{"i":8,"n":"第八条","txt":"以牟利为目的，实施刑法第三百六十三条第一款规定的行为，具有下列情形之一的，以制作、复制、出版、贩卖、传播淫秽物品牟利罪定罪处罚："},{"i":9,"n":"第九条","txt":"为他人提供书号、刊号，出版淫秽书刊的，依照刑法第三百六十三条第二款的规定，以为他人提供书号出版淫秽书刊罪定罪处罚。"},{"i":10,"n":"第十条","txt":"向他人传播淫秽的书刊、影片、音像、图片等出版物达300至600人次以上或者造成恶劣社会影响的，属于“情节严重”，依照刑法第三百六十四条第一款的规定，以传播淫秽物品罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"违反国家规定，出版、印刷、复制、发行本解释第一条至第十条规定以外的其他严重危害社会秩序和扰乱市场秩序的非法出版物，情节严重的，依照刑法第二百二十五条第（三）项的规定，以非法经营罪定罪处罚。"},{"i":12,"n":"第十二条","txt":"个人实施本解释第十一条规定的行为，具有下列情形之一的，属于非法经营行为“情节严重”："},{"i":13,"n":"第十三条","txt":"单位实施本解释第十一条规定的行为，具有下列情形之一的，属于非法经营行为“情节严重”："},{"i":14,"n":"第十四条","txt":"实施本解释第十一条规定的行为，经营数额、违法所得数额或者经营数量接近非法经营行为“情节严重”、“情节特别严重”的数额、数量起点标准，并具有下列情形之一的，可以认定为非法经营行为“情节严重”、“情节特别严重”："},{"i":15,"n":"第十五条","txt":"非法从事出版物的出版、印刷、复制、发行业务，严重扰乱市场秩序，情节特别严重，构成犯罪的，可以依照刑法第二百二十五条第（三）项的规定，以非法经营罪定罪处罚。"},{"i":16,"n":"第十六条","txt":"出版单位与他人事前通谋，向其出售、出租或者以其他形式转让该出版单位的名称、书号、刊号、版号，他人实施本解释第二条、第四条、第八条、第九条、第十条、第十一条规定的行为，构成犯罪的，对该出版单位应当以共犯论处。"},{"i":17,"n":"第十七条","txt":"本解释所称“经营数额”，是指以非法出版物的定价数额乘以行为人经营的非法出版物数量所得的数额。"},{"i":18,"n":"第十八条","txt":"各省、自治区、直辖市高级人民法院可以根据本地的情况和社会治安状况，在本解释第八条、第十条、第十二条、第十三条规定的有关数额、数量标准的幅度内，确定本地执行的具体标准，并报最高人民法院备案。"}],"zuigaorenminfayuanguanyushenlifeifazhizaomaimaiyunba9563":[{"i":1,"n":"第一条","txt":"个人或者单位非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物，具有下列情形之一的，依照刑法第一百二十五条第一款的规定，以非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物罪定罪处罚："},{"i":2,"n":"第二条","txt":"非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物，具有下列情形之一的，属于刑法第一百二十五条第一款规定的“情节严重”："},{"i":3,"n":"第三条","txt":"依法被指定或者确定的枪支制造、销售企业，实施刑法第一百二十六条规定的行为，具有下列情形之一的，以违规制造、销售枪支罪定罪处罚："},{"i":4,"n":"第四条","txt":"盗窃、抢夺枪支、弹药、爆炸物，具有下列情形之一的，依照刑法第一百二十七条第一款的规定，以盗窃、抢夺枪支、弹药、爆炸物罪定罪处罚："},{"i":5,"n":"第五条","txt":"具有下列情形之一的，依照刑法第一百二十八条第一款的规定，以非法持有、私藏枪支、弹药罪定罪处罚："},{"i":6,"n":"第六条","txt":"非法携带枪支、弹药、爆炸物进入公共场所或者公共交通工具，危及公共安全，具有下列情形之一的，属于刑法第一百三十条规定的“情节严重”："},{"i":7,"n":"第七条","txt":"非法制造、买卖、运输、邮寄、储存、盗窃、抢夺、持有、私藏、携带成套枪支散件的，以相应数量的枪支计；非成套枪支散件以每三十件为一成套枪支散件计。"},{"i":8,"n":"第八条","txt":"刑法第一百二十五条第一款规定的“非法储存”，是指明知是他人非法制造、买卖、运输、邮寄的枪支、弹药而为其存放的行为，或者非法存放爆炸物的行为。"},{"i":9,"n":"第九条","txt":"因筑路、建房、打井、整修宅基地和土地等正常生产、生活需要，以及因从事合法的生产经营活动而非法制造、买卖、运输、邮寄、储存爆炸物，数量达到本解释第一条规定标准，没有造成严重社会危害，并确有悔改表现的，可依法从轻处罚；情节轻微的，可以免除处罚。"},{"i":10,"n":"第十条","txt":"实施非法制造、买卖、运输、邮寄、储存、盗窃、抢夺、持有、私藏其他弹药、爆炸物品等行为，参照本解释有关条文规定的定罪量刑标准处罚。"}],"zuigaorenminfayuanguanyushenlifeifajizixingshianji17a720":[{"i":1,"n":"第一条","txt":"违反国家金融管理法律规定，向社会公众（包括单位和个人）吸收资金的行为，同时具备下列四个条件的，除刑法另有规定的以外，应当认定为刑法第一百七十六条规定的“非法吸收公众存款或者变相吸收公众存款”："},{"i":2,"n":"第二条","txt":"实施下列行为之一，符合本解释第一条第一款规定的条件的，应当依照刑法第一百七十六条的规定，以非法吸收公众存款罪定罪处罚："},{"i":3,"n":"第三条","txt":"非法吸收或者变相吸收公众存款，具有下列情形之一的，应当依法追究刑事责任："},{"i":4,"n":"第四条","txt":"非法吸收或者变相吸收公众存款，具有下列情形之一的，应当认定为刑法第一百七十六条规定的“数额巨大或者有其他严重情节”："},{"i":5,"n":"第五条","txt":"非法吸收或者变相吸收公众存款，具有下列情形之一的，应当认定为刑法第一百七十六条规定的“数额特别巨大或者有其他特别严重情节”："},{"i":6,"n":"第六条","txt":"非法吸收或者变相吸收公众存款的数额，以行为人所吸收的资金全额计算。在提起公诉前积极退赃退赔，减少损害结果发生的，可以从轻或者减轻处罚；在提起公诉后退赃退赔的，可以作为量刑情节酌情考虑。"},{"i":7,"n":"第七条","txt":"以非法占有为目的，使用诈骗方法实施本解释第二条规定所列行为的，应当依照刑法第一百九十二条的规定，以集资诈骗罪定罪处罚。"},{"i":8,"n":"第八条","txt":"集资诈骗数额在10万元以上的，应当认定为“数额较大”；数额在100万元以上的，应当认定为“数额巨大”。"},{"i":9,"n":"第九条","txt":"犯非法吸收公众存款罪，判处三年以下有期徒刑或者拘役，并处或者单处罚金的，处五万元以上一百万元以下罚金；判处三年以上十年以下有期徒刑的，并处十万元以上五百万元以下罚金；判处十年以上有期徒刑的，并处五十万元以上罚金。"},{"i":10,"n":"第十条","txt":"未经国家有关主管部门批准，向社会不特定对象发行、以转让股权等方式变相发行股票或者公司、企业债券，或者向特定对象发行、变相发行股票或者公司、企业债券累计超过200人的，应当认定为刑法第一百七十九条规定的“擅自发行股票或者公司、企业债券”。构成犯罪的，以擅自发行股票、公司、企业债券罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"违反国家规定，未经依法核准擅自发行基金份额募集基金，情节严重的，依照刑法第二百二十五条的规定，以非法经营罪定罪处罚。"},{"i":12,"n":"第十二条","txt":"广告经营者、广告发布者违反国家规定，利用广告为非法集资活动相关的商品或者服务作虚假宣传，具有下列情形之一的，依照刑法第二百二十二条的规定，以虚假广告罪定罪处罚："},{"i":13,"n":"第十三条","txt":"通过传销手段向社会公众非法吸收资金，构成非法吸收公众存款罪或者集资诈骗罪，同时又构成组织、领导传销活动罪的，依照处罚较重的规定定罪处罚。"},{"i":14,"n":"第十四条","txt":"单位实施非法吸收公众存款、集资诈骗犯罪的，依照本解释规定的相应自然人犯罪的定罪量刑标准，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员定罪处罚。"},{"i":15,"n":"第十五条","txt":"此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenliyufushixiaofeiminshia64633":[{"i":1,"n":"第一条","txt":"在零售、住宿、餐饮、健身、出行、理发、美容、培训、养老、旅游等生活消费领域，经营者收取预付款后多次或者持续向消费者兑付商品或者提供服务产生的纠纷适用本解释。"},{"i":2,"n":"第二条","txt":"不记名预付卡的持卡人起诉请求经营者承担民事责任的，人民法院应当依法受理。记名预付卡的实际持卡人与预付卡记载的持卡人不一致，但提供其系合法持卡人的初步证据，起诉请求经营者承担民事责任的，人民法院应当依法受理。"},{"i":3,"n":"第三条","txt":"监护人与经营者订立预付式消费合同，约定由经营者向被监护人兑付商品或者提供服务，监护人因预付式消费合同纠纷以被监护人名义起诉，请求经营者承担民事责任的，人民法院应当向监护人释明应以其本人名义起诉。"},{"i":4,"n":"第四条","txt":"经营者允许他人使用其营业执照或者以其他方式允许他人使用其名义与消费者订立预付式消费合同，消费者请求经营者承担民事责任，经营者以其并非实际经营者为由提出抗辩的，人民法院对其抗辩不予支持。"},{"i":5,"n":"第五条","txt":"同一品牌商业特许经营体系内企业标志或者注册商标使用权的特许人与消费者订立预付式消费合同，消费者因权益受到损害请求被特许人承担民事责任，存在下列情形之一的，人民法院应予支持："},{"i":6,"n":"第六条","txt":"商场场地出租者未要求租赁商场场地的经营者提供经营资质证明、营业执照，致使不具有资质的经营者租赁其场地收取消费者预付款并造成消费者损失，消费者请求场地出租者根据其过错承担民事责任的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"经营者收取预付款后因经营困难不能按照合同约定兑付商品或者提供服务的，应当及时依法清算。经营者依法应当清算但未及时进行清算，造成消费者损失，消费者请求经营者的清算义务人依法承担民事责任的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"经营者未与消费者就商品或者服务的质量、价款、履行期限、履行地点和履行方式等内容订立书面合同或者虽订立书面合同但对合同内容约定不明，依照民法典第五百一十条、第五百一十一条等规定对合同内容可以作出两种以上解释，消费者主张就合同内容作出对其有利的解释的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"消费者依照消费者权益保护法第二十六条、民法典第四百九十七条等法律规定，主张经营者提供的下列格式条款无效的，人民法院应予支持："},{"i":10,"n":"第十条","txt":"无民事行为能力人与经营者订立预付式消费合同，向经营者支付预付款，法定代理人请求确认合同无效、经营者返还预付款的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"消费者转让预付式消费合同债权的，自债权转让通知到达经营者时对经营者发生法律效力。债权转让对经营者发生效力后，受让人请求经营者依据预付式消费合同约定兑付商品或者提供服务的，人民法院依法予以支持。受让人请求经营者提供预付卡更名、修改密码等服务的，人民法院依法予以支持。"},{"i":12,"n":"第十二条","txt":"经营者与消费者订立预付式消费合同后，未经消费者同意，单方提高商品或者服务的价格、降低商品或者服务的质量，消费者请求经营者按合同约定履行义务并承担相应违约责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"消费者请求解除预付式消费合同，经营者存在下列情形之一的，人民法院应予支持："},{"i":14,"n":"第十四条","txt":"消费者自付款之日起七日内请求经营者返还预付款本金的，人民法院应予支持，但存在下列情形之一的除外："},{"i":15,"n":"第十五条","txt":"预付式消费合同解除、无效、被撤销或者确定不发生效力，消费者请求经营者返还剩余预付款并支付利息的，人民法院应予支持。返还预付款本金应为预付款扣减已兑付商品或者提供服务的价款后的余额。"},{"i":16,"n":"第十六条","txt":"当事人对返还预付款利息计付标准有约定的，按照约定处理。没有约定或者约定不明，因经营者原因返还预付款的，按照预付式消费合同成立时一年期贷款市场报价利率计算利息；因消费者原因返还预付款的，按照预付式消费合同成立时中国人民银行公布的一年定期存款基准利率计算利息。"},{"i":17,"n":"第十七条","txt":"预付式消费合同解除、无效、被撤销或者确定不发生效力，消费者请求返还预付款的，自合同解除、被确认无效、被撤销或者确定不发生效力时起计算利息。"},{"i":18,"n":"第十八条","txt":"非因消费者原因返还预付款的，人民法院按下列方式计算已兑付商品或者提供服务的价款："},{"i":19,"n":"第十九条","txt":"因消费者原因返还预付款，经营者向消费者提供折扣商品、服务或者向消费者赠送消费金额的，人民法院应当按商品或者服务打折前的价格计算已兑付商品或者提供服务的价款。"},{"i":20,"n":"第二十条","txt":"按折扣价或者优惠比例计算已兑付商品或者提供服务的价款未超出消费者预付款，但按打折前的价格计算已兑付商品或者提供服务的价款超出消费者预付款，经营者请求消费者支付按打折前的价格计算超出预付款部分价款的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"经营者向消费者赠送商品或者服务，消费者在预付式消费合同解除、无效、被撤销、确定不发生效力后请求返还剩余预付款，经营者主张消费者返还或者折价补偿已经赠送的商品或者服务的，人民法院应当综合考虑已经赠送的商品或者服务的价值、预付式消费合同标的金额、合同履行情况、退款原因等因素，依照诚实信用原则对是否支持经营者主张作出认定。"},{"i":22,"n":"第二十二条","txt":"预付式消费合同约定经营者在履行期限内向消费者提供不限次数服务，消费者请求按合同解除后的剩余履行期限与全部履行期限的比例计算应予返还的预付款的，人民法院应予支持。"},{"i":23,"n":"第二十三条","txt":"经营者收取预付款后终止营业，既不按照约定兑付商品或者提供服务又恶意逃避消费者申请退款，消费者请求经营者承担惩罚性赔偿责任的，人民法院依法予以支持。"},{"i":24,"n":"第二十四条","txt":"消费者请求经营者对尚有资金余额的预付卡提供激活、换卡等服务的，人民法院应予支持。"},{"i":25,"n":"第二十五条","txt":"经营者控制合同文本或者记录消费内容、消费次数、消费金额、预付款余额等信息的证据，无正当理由拒不提交，消费者主张该证据的内容不利于经营者的，人民法院可以根据消费者的主张认定争议事实。"},{"i":26,"n":"第二十六条","txt":"本解释所称预付卡为单用途商业预付卡，包括以磁条卡、芯片卡、纸券等为载体的实体卡和以密码、串码、图形、生物特征信息等为载体的虚拟卡。"},{"i":27,"n":"第二十七条","txt":"本解释自2025年5月1日起施行。"}],"zuigaorenminfayuanguanyushenlishipinanquanminshijiac9144":[{"i":1,"n":"第一条","txt":"消费者因不符合食品安全标准的食品受到损害，依据食品安全法第一百四十八条第一款规定诉请食品生产者或者经营者赔偿损失，被诉的生产者或者经营者以赔偿责任应由生产经营者中的另一方承担为由主张免责的，人民法院不予支持。属于生产者责任的，经营者赔偿后有权向生产者追偿；属于经营者责任的，生产者赔偿后有权向经营者追偿。"},{"i":2,"n":"第二条","txt":"电子商务平台经营者以标记自营业务方式所销售的食品或者虽未标记自营但实际开展自营业务所销售的食品不符合食品安全标准，消费者依据食品安全法第一百四十八条规定主张电子商务平台经营者承担作为食品经营者的赔偿责任的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"电子商务平台经营者违反食品安全法第六十二条和第一百三十一条规定，未对平台内食品经营者进行实名登记、审查许可证，或者未履行报告、停止提供网络交易平台服务等义务，使消费者的合法权益受到损害，消费者主张电子商务平台经营者与平台内食品经营者承担连带责任的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"公共交通运输的承运人向旅客提供的食品不符合食品安全标准，旅客主张承运人依据食品安全法第一百四十八条规定承担作为食品生产者或者经营者的赔偿责任的，人民法院应予支持；承运人以其不是食品的生产经营者或者食品是免费提供为由进行免责抗辩的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"有关单位或者个人明知食品生产经营者从事食品安全法第一百二十三条第一款规定的违法行为而仍为其提供设备、技术、原料、销售渠道、运输、储存或者其他便利条件，消费者主张该单位或者个人依据食品安全法第一百二十三条第二款的规定与食品生产经营者承担连带责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"食品经营者具有下列情形之一，消费者主张构成食品安全法第一百四十八条规定的“明知”的，人民法院应予支持："},{"i":7,"n":"第七条","txt":"消费者认为生产经营者生产经营不符合食品安全标准的食品同时构成欺诈的，有权选择依据食品安全法第一百四十八条第二款或者消费者权益保护法第五十五条第一款规定主张食品生产者或者经营者承担惩罚性赔偿责任。"},{"i":8,"n":"第八条","txt":"经营者经营明知是不符合食品安全标准的食品，但向消费者承诺的赔偿标准高于食品安全法第一百四十八条规定的赔偿标准，消费者主张经营者按照承诺赔偿的，人民法院应当依法予以支持。"},{"i":9,"n":"第九条","txt":"食品符合食品安全标准但未达到生产经营者承诺的质量标准，消费者依照民法典、消费者权益保护法等法律规定主张生产经营者承担责任的，人民法院应予支持，但消费者主张生产经营者依据食品安全法第一百四十八条规定承担赔偿责任的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"食品不符合食品安全标准，消费者主张生产者或者经营者依据食品安全法第一百四十八条第二款规定承担惩罚性赔偿责任，生产者或者经营者以未造成消费者人身损害为由抗辩的，人民法院不予支持。"},{"i":11,"n":"第十一条","txt":"生产经营未标明生产者名称、地址、成分或者配料表，或者未清晰标明生产日期、保质期的预包装食品，消费者主张生产者或者经营者依据食品安全法第一百四十八条第二款规定承担惩罚性赔偿责任的，人民法院应予支持，但法律、行政法规、食品安全国家标准对标签标注事项另有规定的除外。"},{"i":12,"n":"第十二条","txt":"进口的食品不符合我国食品安全国家标准或者国务院卫生行政部门决定暂予适用的标准，消费者主张销售者、进口商等经营者依据食品安全法第一百四十八条规定承担赔偿责任，销售者、进口商等经营者仅以进口的食品符合出口地食品安全标准或者已经过我国出入境检验检疫机构检验检疫为由进行免责抗辩的，人民法院不予支持。"},{"i":13,"n":"第十三条","txt":"生产经营不符合食品安全标准的食品，侵害众多消费者合法权益，损害社会公共利益，民事诉讼法、消费者权益保护法等法律规定的机关和有关组织依法提起公益诉讼的，人民法院应予受理。"},{"i":14,"n":"第十四条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlishipinyaopinchengfaxe62c55":[{"i":1,"n":"第一条","txt":"购买者因个人或者家庭生活消费需要购买的食品不符合食品安全标准，购买后依照食品安全法第一百四十八条第二款规定请求生产者或者经营者支付惩罚性赔偿金的，人民法院依法予以支持。"},{"i":2,"n":"第二条","txt":"购买者明知所购买食品不符合食品安全标准或者所购买药品是假药、劣药，购买后请求经营者返还价款的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"受托人明知购买者委托购买的是不符合食品安全标准的食品或者假药、劣药仍然代购，购买者依照食品安全法第一百四十八条第二款或者药品管理法第一百四十四条第三款规定请求受托人承担惩罚性赔偿责任的，人民法院应予支持，但受托人不以代购为业的除外。"},{"i":4,"n":"第四条","txt":"食品生产加工小作坊和食品摊贩等生产经营的食品不符合食品安全标准，购买者请求生产者或者经营者依照食品安全法第一百四十八条第二款规定承担惩罚性赔偿责任的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"食品不符合食品中危害人体健康物质的限量规定，食品添加剂的品种、使用范围、用量要求，特定人群的主辅食品的营养成分要求，与卫生、营养等食品安全要求有关的标签、标志、说明书要求以及与食品安全有关的质量要求等方面的食品安全标准，购买者依照食品安全法第一百四十八条第二款规定请求生产者或者经营者承担惩罚性赔偿责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"购买者以食品的标签、说明书不符合食品安全标准为由请求生产者或者经营者支付惩罚性赔偿金，生产者或者经营者以食品的标签、说明书瑕疵不影响食品安全且不会对消费者造成误导为由进行抗辩，存在下列情形之一的，人民法院对生产者或者经营者的抗辩不予支持："},{"i":7,"n":"第七条","txt":"购买者以食品的标签、说明书不符合食品安全标准为由请求生产者或者经营者支付惩罚性赔偿金，生产者或者经营者以食品的标签、说明书虽不符合食品安全标准但不影响食品安全为由进行抗辩的，人民法院对其抗辩不予支持，但食品的标签、说明书瑕疵同时符合下列情形的除外："},{"i":8,"n":"第八条","txt":"购买者以食品的标签、说明书不符合食品安全标准为由请求生产者或者经营者支付惩罚性赔偿金，食品的标签、说明书虽存在瑕疵但属于下列情形之一的，人民法院不予支持："},{"i":9,"n":"第九条","txt":"经营明知是不符合食品安全标准的食品或者明知是假药、劣药仍然销售、使用的行为构成欺诈，购买者选择依照食品安全法第一百四十八条第二款、药品管理法第一百四十四条第三款或者消费者权益保护法第五十五条第一款规定起诉请求经营者承担惩罚性赔偿责任的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"购买者因个人或者家庭生活消费需要购买的药品是假药、劣药，依照药品管理法第一百四十四条第三款规定请求生产者或者经营者支付惩罚性赔偿金的，人民法院依法予以支持。"},{"i":11,"n":"第十一条","txt":"购买者依照药品管理法第一百四十四条第三款规定请求生产者或者经营者支付惩罚性赔偿金，生产者或者经营者抗辩不应适用药品管理法第一百四十四条第三款规定，存在下列情形之一的，人民法院对其抗辩应予支持："},{"i":12,"n":"第十二条","txt":"购买者明知所购买食品不符合食品安全标准，依照食品安全法第一百四十八条第二款规定请求生产者或者经营者支付价款十倍的惩罚性赔偿金的，人民法院应当在合理生活消费需要范围内依法支持购买者诉讼请求。"},{"i":13,"n":"第十三条","txt":"购买者明知食品不符合食品安全标准，在短时间内多次购买，并依照食品安全法第一百四十八条第二款规定起诉请求同一生产者或者经营者按每次购买金额分别计算惩罚性赔偿金的，人民法院应当根据购买者多次购买相同食品的总数，在合理生活消费需要范围内依法支持其诉讼请求。"},{"i":14,"n":"第十四条","txt":"购买者明知所购买食品不符合食品安全标准，在短时间内多次购买，并多次依照食品安全法第一百四十八条第二款规定就同一不符合食品安全标准的食品起诉请求同一生产者或者经营者支付惩罚性赔偿金的，人民法院应当在合理生活消费需要范围内依法支持其诉讼请求。"},{"i":15,"n":"第十五条","txt":"人民法院在审理食品药品纠纷案件过程中，发现购买者恶意制造生产者或者经营者违法生产经营食品、药品的假象，以投诉、起诉等方式相要挟，向生产者或者经营者索取赔偿金，涉嫌敲诈勒索的，应当及时将有关违法犯罪线索、材料移送公安机关。"},{"i":16,"n":"第十六条","txt":"购买者恶意制造生产者或者经营者违法生产经营食品、药品的假象，起诉请求生产者或者经营者承担赔偿责任的，人民法院应当驳回购买者诉讼请求；构成虚假诉讼的，人民法院应当依照民事诉讼法相关规定，根据情节轻重对其予以罚款、拘留。"},{"i":17,"n":"第十七条","txt":"人民法院在审理食品药品纠纷案件过程中，发现当事人的行为涉嫌生产、销售有毒、有害食品及假药、劣药，虚假诉讼等违法犯罪的，应当及时将有关违法犯罪线索、材料移送有关行政机关和公安机关。"},{"i":18,"n":"第十八条","txt":"人民法院在审理食品药品纠纷案件过程中，发现违法生产、销售、使用食品、药品行为的，可以向有关行政机关、生产者或者经营者发出司法建议。"},{"i":19,"n":"第十九条","txt":"本解释自2024年8月22日起施行。"}],"zuigaorenminfayuanguanyushenlipiangouwaihuifeifama90d692":[{"i":1,"n":"第一条","txt":"以进行走私、逃汇、洗钱、骗税等犯罪活动为目的，使用虚假、无效的凭证、商业单据或者采取其他手段向外汇指定银行骗购外汇的，应当分别按照刑法分则第三章第二节、第一百九十条、第一百九十一条和第二百零四条等规定定罪处罚。"},{"i":2,"n":"第二条","txt":"伪造、变造、买卖海关签发的报关单、进口证明、外汇管理机关的核准件等凭证或者购买伪造、变造的上述凭证的，按照刑法第二百八十条第一款的规定定罪处罚。"},{"i":3,"n":"第三条","txt":"在外汇指定银行和中国外汇交易中心及其分中心以外买卖外汇，扰乱金融市场秩序，具有下列情形之一的，按照刑法第二百二十五条第（三）项的规定定罪处罚："},{"i":4,"n":"第四条","txt":"公司、企业或者其他单位，违反有关外贸代理业务的规定，采用非法手段，或者明知是伪造、变造的凭证、商业单据，为他人向外汇指定银行骗购外汇，数额在500万美元以上或者违法所得50万元人民币以上的，按照刑法第二百二十五条第（三）项的规定定罪处罚。"},{"i":5,"n":"第五条","txt":"海关、银行、外汇管理机关工作人员与骗购外汇的行为人通谋，为其提供购买外汇的有关凭证，或者明知是伪造、变造的凭证和商业单据而出售外汇，构成犯罪的，按照刑法的有关规定从重处罚。"},{"i":6,"n":"第六条","txt":"实施本解释规定的行为，同时触犯两个以上罪名的，择一重罪从重处罚。"},{"i":7,"n":"第七条","txt":"根据刑法第六十四条规定，骗购外汇、非法买卖外汇的，其违法所得予以追缴，用于骗购外汇、非法买卖外汇的资金予以没收，上缴国库。"},{"i":8,"n":"第八条","txt":"骗购、非法买卖不同币种的外汇的，以案发时国家外汇管理机关制定的统一折算率折合后依照本解释处罚。"}],"zuigaorenminfayuanguanyushenliheishehuixingzhizuzh73e513":[{"i":1,"n":"第一条","txt":"刑法第二百九十四条规定的“黑社会性质的组织”，一般应具备以下特征："},{"i":2,"n":"第二条","txt":"刑法第二百九十四条第二款规定的“发展组织成员”，是指将境内、外人员吸收为该黑社会组织成员的行为。对黑社会组织成员进行内部调整等行为，可视为“发展组织成员”。"},{"i":3,"n":"第三条","txt":"组织、领导、参加黑社会性质的组织又有其他犯罪行为的，根据刑法第二百九十四条第三款的规定，依照数罪并罚的规定处罚；对于黑社会性质组织的组织者、领导者，应当按照其所组织、领导的黑社会性质组织所犯的全部罪行处罚；对于黑社会性质组织的参加者，应当按照其所参与的犯罪处罚。"},{"i":4,"n":"第四条","txt":"国家机关工作人员组织、领导、参加黑社会性质组织的，从重处罚。"},{"i":5,"n":"第五条","txt":"刑法第二百九十四条第四款规定的“包庇”，是指国家机关工作人员为使黑社会性质组织及其成员逃避查禁，而通风报信，隐匿、毁灭、伪造证据，阻止他人作证、检举揭发，指使他人作伪证，帮助逃匿，或者阻挠其他国家机关工作人员依法查禁等行为。"},{"i":6,"n":"第六条","txt":"国家机关工作人员包庇、纵容黑社会性质的组织，有下列情形之一的，属于刑法第二百九十四条第四款规定的“情节严重”："},{"i":7,"n":"第七条","txt":"对黑社会性质组织和组织、领导、参加黑社会性质组织的犯罪分子聚敛的财物及其收益，以及用于犯罪的工具等，应当依法追缴、没收。"}],"zuigaorenminfayuanguanyuduiweisuoqufalvbuyubaohude83ef9d":[],"zuigaorenminfayuanguanyuduibianzaodaomaibianzaoyou6d69b7":[],"zuigaorenminfayuanguanyudangshirenshenqingcaichanb8b0b3d":[],"zuigaorenminfayuanguanyuzhixingchengxuzhongjisuanc0e565a":[{"i":1,"n":"第一条","txt":"根据民事诉讼法第二百五十三条规定加倍计算之后的迟延履行期间的债务利息，包括迟延履行期间的一般债务利息和加倍部分债务利息。"},{"i":2,"n":"第二条","txt":"加倍部分债务利息自生效法律文书确定的履行期间届满之日起计算；生效法律文书确定分期履行的，自每次履行期间届满之日起计算；生效法律文书未确定履行期间的，自法律文书生效之日起计算。"},{"i":3,"n":"第三条","txt":"加倍部分债务利息计算至被执行人履行完毕之日；被执行人分次履行的，相应部分的加倍部分债务利息计算至每次履行完毕之日。"},{"i":4,"n":"第四条","txt":"被执行人的财产不足以清偿全部债务的，应当先清偿生效法律文书确定的金钱债务，再清偿加倍部分债务利息，但当事人对清偿顺序另有约定的除外。"},{"i":5,"n":"第五条","txt":"生效法律文书确定给付外币的，执行时以该种外币按日万分之一点七五计算加倍部分债务利息，但申请执行人主张以人民币计算的，人民法院应予准许。"},{"i":6,"n":"第六条","txt":"执行回转程序中，原申请执行人迟延履行金钱给付义务的，应当按照本解释的规定承担加倍部分债务利息。"},{"i":7,"n":"第七条","txt":"本解释施行时尚未执行完毕部分的金钱债务，本解释施行前的迟延履行期间债务利息按照之前的规定计算；施行后的迟延履行期间债务利息按照本解释计算。"}],"zuigaorenminfayuanguanyuhaiguanxingzhengchufaanjiaa4e217":[],"zuigaorenminfayuanguanyuquedingminshiqinquanjingsh105f23":[{"i":1,"n":"第一条","txt":"因人身权益或者具有人身意义的特定物受到侵害，自然人或者其近亲属向人民法院提起诉讼请求精神损害赔偿的，人民法院应当依法予以受理。"},{"i":2,"n":"第二条","txt":"非法使被监护人脱离监护，导致亲子关系或者近亲属间的亲属关系遭受严重损害，监护人向人民法院起诉请求赔偿精神损害的，人民法院应当依法予以受理。"},{"i":3,"n":"第三条","txt":"死者的姓名、肖像、名誉、荣誉、隐私、遗体、遗骨等受到侵害，其近亲属向人民法院提起诉讼请求精神损害赔偿的，人民法院应当依法予以支持。"},{"i":4,"n":"第四条","txt":"法人或者非法人组织以名誉权、荣誉权、名称权遭受侵害为由，向人民法院起诉请求精神损害赔偿的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"精神损害的赔偿数额根据以下因素确定："},{"i":6,"n":"第六条","txt":"在本解释公布施行之前已经生效施行的司法解释，其内容有与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushiyongrenminpeishenyuanfa1a5786":[{"i":1,"n":"第一条","txt":"根据人民陪审员法第十五条、第十六条的规定，人民法院决定由人民陪审员和法官组成合议庭审判的，合议庭成员确定后，应当及时告知当事人。"},{"i":2,"n":"第二条","txt":"对于人民陪审员法第十五条、第十六条规定之外的第一审普通程序案件，人民法院应当告知刑事案件被告人、民事案件原告和被告、行政案件原告，在收到通知五日内有权申请由人民陪审员参加合议庭审判案件。"},{"i":3,"n":"第三条","txt":"人民法院应当在开庭七日前从人民陪审员名单中随机抽取确定人民陪审员。"},{"i":4,"n":"第五条","txt":"人民陪审员不参加下列案件的审理："},{"i":5,"n":"第六条","txt":"人民陪审员不得参与审理由其以人民调解员身份先行调解的案件。"},{"i":6,"n":"第七条","txt":"当事人依法有权申请人民陪审员回避。人民陪审员的回避，适用审判人员回避的法律规定。"},{"i":7,"n":"第八条","txt":"人民法院应当在开庭前，将相关权利和义务告知人民陪审员，并为其阅卷提供便利条件。"},{"i":8,"n":"第九条","txt":"七人合议庭开庭前，应当制作事实认定问题清单，根据案件具体情况，区分事实认定问题与法律适用问题，对争议事实问题逐项列举，供人民陪审员在庭审时参考。事实认定问题和法律适用问题难以区分的，视为事实认定问题。"},{"i":9,"n":"第十条","txt":"案件审判过程中，人民陪审员依法有权参加案件调查和调解工作。"},{"i":10,"n":"第十一条","txt":"庭审过程中，人民陪审员依法有权向诉讼参加人发问，审判长应当提示人民陪审员围绕案件争议焦点进行发问。"},{"i":11,"n":"第十二条","txt":"合议庭评议案件时，先由承办法官介绍案件涉及的相关法律、证据规则，然后由人民陪审员和法官依次发表意见，审判长最后发表意见并总结合议庭意见。"},{"i":12,"n":"第十三条","txt":"七人合议庭评议时，审判长应当归纳和介绍需要通过评议讨论决定的案件事实认定问题，并列出案件事实问题清单。"},{"i":13,"n":"第十四条","txt":"人民陪审员应当认真阅读评议笔录，确认无误后签名。"},{"i":14,"n":"第十五条","txt":"人民陪审员列席审判委员会讨论其参加审理的案件时，可以发表意见。"},{"i":15,"n":"第十六条","txt":"案件审结后，人民法院应将裁判文书副本及时送交参加该案审判的人民陪审员。"},{"i":16,"n":"第十七条","txt":"中级、基层人民法院应当保障人民陪审员均衡参审，结合本院实际情况，一般在不超过30件的范围内合理确定每名人民陪审员年度参加审判案件的数量上限，报高级人民法院备案，并向社会公告。"},{"i":17,"n":"第十八条","txt":"人民法院应当依法规范和保障人民陪审员参加审判活动，不得安排人民陪审员从事与履行法定审判职责无关的工作。"},{"i":18,"n":"第十九条","txt":"本解释自2019年5月1日起施行。"}],"zuigaorenminfayuanguanyushiyongzhongcaifaruoganwen2473a5":[{"i":1,"n":"第一条","txt":"仲裁法第十六条规定的“其他书面形式”的仲裁协议，包括以合同书、信件和数据电文（包括电报、电传、传真、电子数据交换和电子邮件）等形式达成的请求仲裁的协议。"},{"i":2,"n":"第二条","txt":"当事人概括约定仲裁事项为合同争议的，基于合同成立、效力、变更、转让、履行、违约责任、解释、解除等产生的纠纷都可以认定为仲裁事项。"},{"i":3,"n":"第三条","txt":"仲裁协议约定的仲裁机构名称不准确，但能够确定具体的仲裁机构的，应当认定选定了仲裁机构。"},{"i":4,"n":"第四条","txt":"仲裁协议仅约定纠纷适用的仲裁规则的，视为未约定仲裁机构，但当事人达成补充协议或者按照约定的仲裁规则能够确定仲裁机构的除外。"},{"i":5,"n":"第五条","txt":"仲裁协议约定两个以上仲裁机构的，当事人可以协议选择其中的一个仲裁机构申请仲裁；当事人不能就仲裁机构选择达成一致的，仲裁协议无效。"},{"i":6,"n":"第六条","txt":"仲裁协议约定由某地的仲裁机构仲裁且该地仅有一个仲裁机构的，该仲裁机构视为约定的仲裁机构。该地有两个以上仲裁机构的，当事人可以协议选择其中的一个仲裁机构申请仲裁；当事人不能就仲裁机构选择达成一致的，仲裁协议无效。"},{"i":7,"n":"第七条","txt":"当事人约定争议可以向仲裁机构申请仲裁也可以向人民法院起诉的，仲裁协议无效。但一方向仲裁机构申请仲裁，另一方未在仲裁法第二十条第二款规定期间内提出异议的除外。"},{"i":8,"n":"第八条","txt":"当事人订立仲裁协议后合并、分立的，仲裁协议对其权利义务的继受人有效。"},{"i":9,"n":"第九条","txt":"债权债务全部或者部分转让的，仲裁协议对受让人有效，但当事人另有约定、在受让债权债务时受让人明确反对或者不知有单独仲裁协议的除外。"},{"i":10,"n":"第十条","txt":"合同成立后未生效或者被撤销的，仲裁协议效力的认定适用仲裁法第十九条第一款的规定。"},{"i":11,"n":"第十一条","txt":"合同约定解决争议适用其他合同、文件中的有效仲裁条款的，发生合同争议时，当事人应当按照该仲裁条款提请仲裁。"},{"i":12,"n":"第十二条","txt":"当事人向人民法院申请确认仲裁协议效力的案件，由仲裁协议约定的仲裁机构所在地的中级人民法院管辖；仲裁协议约定的仲裁机构不明确的，由仲裁协议签订地或者被申请人住所地的中级人民法院管辖。"},{"i":13,"n":"第十三条","txt":"依照仲裁法第二十条第二款的规定，当事人在仲裁庭首次开庭前没有对仲裁协议的效力提出异议，而后向人民法院申请确认仲裁协议无效的，人民法院不予受理。"},{"i":14,"n":"第十四条","txt":"仲裁法第二十六条规定的“首次开庭”是指答辩期满后人民法院组织的第一次开庭审理，不包括审前程序中的各项活动。"},{"i":15,"n":"第十五条","txt":"人民法院审理仲裁协议效力确认案件，应当组成合议庭进行审查，并询问当事人。"},{"i":16,"n":"第十六条","txt":"对涉外仲裁协议的效力审查，适用当事人约定的法律；当事人没有约定适用的法律但约定了仲裁地的，适用仲裁地法律；没有约定适用的法律也没有约定仲裁地或者仲裁地约定不明的，适用法院地法律。"},{"i":17,"n":"第十七条","txt":"当事人以不属于仲裁法第五十八条或者民事诉讼法第二百六十条规定的事由申请撤销仲裁裁决的，人民法院不予支持。"},{"i":18,"n":"第十八条","txt":"仲裁法第五十八条第一款第一项规定的“没有仲裁协议”是指当事人没有达成仲裁协议。仲裁协议被认定无效或者被撤销的，视为没有仲裁协议。"},{"i":19,"n":"第十九条","txt":"当事人以仲裁裁决事项超出仲裁协议范围为由申请撤销仲裁裁决，经审查属实的，人民法院应当撤销仲裁裁决中的超裁部分。但超裁部分与其他裁决事项不可分的，人民法院应当撤销仲裁裁决。"},{"i":20,"n":"第二十条","txt":"仲裁法第五十八条规定的“违反法定程序”，是指违反仲裁法规定的仲裁程序和当事人选择的仲裁规则可能影响案件正确裁决的情形。"},{"i":21,"n":"第二十一条","txt":"当事人申请撤销国内仲裁裁决的案件属于下列情形之一的，人民法院可以依照仲裁法第六十一条的规定通知仲裁庭在一定期限内重新仲裁："},{"i":22,"n":"第二十二条","txt":"仲裁庭在人民法院指定的期限内开始重新仲裁的，人民法院应当裁定终结撤销程序；未开始重新仲裁的，人民法院应当裁定恢复撤销程序。"},{"i":23,"n":"第二十三条","txt":"当事人对重新仲裁裁决不服的，可以在重新仲裁裁决书送达之日起六个月内依据仲裁法第五十八条规定向人民法院申请撤销。"},{"i":24,"n":"第二十四条","txt":"当事人申请撤销仲裁裁决的案件，人民法院应当组成合议庭审理，并询问当事人。"},{"i":25,"n":"第二十五条","txt":"人民法院受理当事人撤销仲裁裁决的申请后，另一方当事人申请执行同一仲裁裁决的，受理执行申请的人民法院应当在受理后裁定中止执行。"},{"i":26,"n":"第二十六条","txt":"当事人向人民法院申请撤销仲裁裁决被驳回后，又在执行程序中以相同理由提出不予执行抗辩的，人民法院不予支持。"},{"i":27,"n":"第二十七条","txt":"当事人在仲裁程序中未对仲裁协议的效力提出异议，在仲裁裁决作出后以仲裁协议无效为由主张撤销仲裁裁决或者提出不予执行抗辩的，人民法院不予支持。"},{"i":28,"n":"第二十八条","txt":"当事人请求不予执行仲裁调解书或者根据当事人之间的和解协议作出的仲裁裁决书的，人民法院不予支持。"},{"i":29,"n":"第二十九条","txt":"当事人申请执行仲裁裁决案件，由被执行人住所地或者被执行的财产所在地的中级人民法院管辖。"},{"i":30,"n":"第三十条","txt":"根据审理撤销、执行仲裁裁决案件的实际需要，人民法院可以要求仲裁机构作出说明或者向相关仲裁机构调阅仲裁案卷。"},{"i":31,"n":"第三十一条","txt":"本解释自公布之日起实施。"}],"zuigaorenminfayuanguanyushiyongbaoxianfaruoganwent550188":[{"i":1,"n":"第一条","txt":"保险法施行后成立的保险合同发生的纠纷，适用保险法的规定。保险法施行前成立的保险合同发生的纠纷，除本解释另有规定外，适用当时的法律规定；当时的法律没有规定的，参照适用保险法的有关规定。"},{"i":2,"n":"第二条","txt":"对于保险法施行前成立的保险合同，适用当时的法律认定无效而适用保险法认定有效的，适用保险法的规定。"},{"i":3,"n":"第三条","txt":"保险合同成立于保险法施行前而保险标的转让、保险事故、理赔、代位求偿等行为或事件，发生于保险法施行后的，适用保险法的规定。"},{"i":4,"n":"第四条","txt":"保险合同成立于保险法施行前，保险法施行后，保险人以投保人未履行如实告知义务或者申报被保险人年龄不真实为由，主张解除合同的，适用保险法的规定。"},{"i":5,"n":"第五条","txt":"保险法施行前成立的保险合同，下列情形下的期间自2009年10月1日起计算："},{"i":6,"n":"第六条","txt":"保险法施行前已经终审的案件，当事人申请再审或者按照审判监督程序提起再审的案件，不适用保险法的规定。"}],"zuigaorenminfayuanguanyushiyongbaoxianfaruoganwent51afc2":[{"i":1,"n":"第一条","txt":"当事人订立以死亡为给付保险金条件的合同，根据保险法第三十四条的规定，“被保险人同意并认可保险金额”可以采取书面形式、口头形式或者其他形式；可以在合同订立时作出，也可以在合同订立后追认。"},{"i":2,"n":"第二条","txt":"被保险人以书面形式通知保险人和投保人撤销其依据保险法第三十四条第一款规定所作出的同意意思表示的，可认定为保险合同解除。"},{"i":3,"n":"第三条","txt":"人民法院审理人身保险合同纠纷案件时，应主动审查投保人订立保险合同时是否具有保险利益，以及以死亡为给付保险金条件的合同是否经过被保险人同意并认可保险金额。"},{"i":4,"n":"第四条","txt":"保险合同订立后，因投保人丧失对被保险人的保险利益，当事人主张保险合同无效的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"保险合同订立时，被保险人根据保险人的要求在指定医疗服务机构进行体检，当事人主张投保人如实告知义务免除的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"未成年人父母之外的其他履行监护职责的人为未成年人订立以死亡为给付保险金条件的合同，当事人主张参照保险法第三十三条第二款、第三十四条第三款的规定认定该合同有效的，人民法院不予支持，但经未成年人父母同意的除外。"},{"i":7,"n":"第七条","txt":"当事人以被保险人、受益人或者他人已经代为支付保险费为由，主张投保人对应的交费义务已经履行的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"保险合同效力依照保险法第三十六条规定中止，投保人提出恢复效力申请并同意补交保险费，除被保险人的危险程度在中止期间显著增加外，保险人拒绝恢复效力的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"投保人指定受益人未经被保险人同意的，人民法院应认定指定行为无效。"},{"i":10,"n":"第十条","txt":"投保人或者被保险人变更受益人，当事人主张变更行为自变更意思表示发出时生效的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"投保人或者被保险人在保险事故发生后变更受益人，变更后的受益人请求保险人给付保险金的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"投保人或者被保险人指定数人为受益人，部分受益人在保险事故发生前死亡、放弃受益权或者依法丧失受益权的，该受益人应得的受益份额按照保险合同的约定处理；保险合同没有约定或者约定不明的，该受益人应得的受益份额按照以下情形分别处理："},{"i":13,"n":"第十三条","txt":"保险事故发生后，受益人将与本次保险事故相对应的全部或者部分保险金请求权转让给第三人，当事人主张该转让行为有效的，人民法院应予支持，但根据合同性质、当事人约定或者法律规定不得转让的除外。"},{"i":14,"n":"第十四条","txt":"保险金根据保险法第四十二条规定作为被保险人的遗产，被保险人的继承人要求保险人给付保险金，保险人以其已向持有保险单的被保险人的其他继承人给付保险金为由抗辩的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"受益人与被保险人存在继承关系，在同一事件中死亡且不能确定死亡先后顺序的，人民法院应根据保险法第四十二条第二款的规定推定受益人死亡在先，并按照保险法及本解释的相关规定确定保险金归属。"},{"i":16,"n":"第十六条","txt":"保险合同解除时，投保人与被保险人、受益人为不同主体，被保险人或者受益人要求退还保险单的现金价值的，人民法院不予支持，但保险合同另有约定的除外。"},{"i":17,"n":"第十七条","txt":"投保人解除保险合同，当事人以其解除合同未经被保险人或者受益人同意为由主张解除行为无效的，人民法院不予支持，但被保险人或者受益人已向投保人支付相当于保险单现金价值的款项并通知保险人的除外。"},{"i":18,"n":"第十八条","txt":"保险人给付费用补偿型的医疗费用保险金时，主张扣减被保险人从公费医疗或者社会医疗保险取得的赔偿金额的，应当证明该保险产品在厘定医疗费用保险费率时已经将公费医疗或者社会医疗保险部分相应扣除，并按照扣减后的标准收取保险费。"},{"i":19,"n":"第十九条","txt":"保险合同约定按照基本医疗保险的标准核定医疗费用，保险人以被保险人的医疗支出超出基本医疗保险范围为由拒绝给付保险金的，人民法院不予支持；保险人有证据证明被保险人支出的费用超过基本医疗保险同类医疗费用标准，要求对超出部分拒绝给付保险金的，人民法院应予支持。"},{"i":20,"n":"第二十条","txt":"保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持，但被保险人因情况紧急必须立即就医的除外。"},{"i":21,"n":"第二十一条","txt":"保险人以被保险人自杀为由拒绝给付保险金的，由保险人承担举证责任。"},{"i":22,"n":"第二十二条","txt":"保险法第四十五条规定的“被保险人故意犯罪”的认定，应当以刑事侦查机关、检察机关和审判机关的生效法律文书或者其他结论性意见为依据。"},{"i":23,"n":"第二十三条","txt":"保险人主张根据保险法第四十五条的规定不承担给付保险金责任的，应当证明被保险人的死亡、伤残结果与其实施的故意犯罪或者抗拒依法采取的刑事强制措施的行为之间存在因果关系。"},{"i":24,"n":"第二十四条","txt":"投保人为被保险人订立以死亡为给付保险金条件的保险合同，被保险人被宣告死亡后，当事人要求保险人按照保险合同约定给付保险金的，人民法院应予支持。"},{"i":25,"n":"第二十五条","txt":"被保险人的损失系由承保事故或者非承保事故、免责事由造成难以确定，当事人请求保险人给付保险金的，人民法院可以按照相应比例予以支持。"},{"i":26,"n":"第二十六条","txt":"本解释自2015年12月1日起施行。本解释施行后尚未终审的保险合同纠纷案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。"}],"zuigaorenminfayuanguanyushiyongbaoxianfaruoganwenta50b4b":[{"i":1,"n":"第一条","txt":"财产保险中，不同投保人就同一保险标的分别投保，保险事故发生后，被保险人在其保险利益范围内依据保险合同主张保险赔偿的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"人身保险中，因投保人对被保险人不具有保险利益导致保险合同无效，投保人主张保险人退还扣减相应手续费后的保险费的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"投保人或者投保人的代理人订立保险合同时没有亲自签字或者盖章，而由保险人或者保险人的代理人代为签字或者盖章的，对投保人不生效。但投保人已经交纳保险费的，视为其对代签字或者盖章行为的追认。"},{"i":4,"n":"第四条","txt":"保险人接受了投保人提交的投保单并收取了保险费，尚未作出是否承保的意思表示，发生保险事故，被保险人或者受益人请求保险人按照保险合同承担赔偿或者给付保险金责任，符合承保条件的，人民法院应予支持；不符合承保条件的，保险人不承担保险责任，但应当退还已经收取的保险费。"},{"i":5,"n":"第五条","txt":"保险合同订立时，投保人明知的与保险标的或者被保险人有关的情况，属于保险法第十六条第一款规定的投保人“应当如实告知”的内容。"},{"i":6,"n":"第六条","txt":"投保人的告知义务限于保险人询问的范围和内容。当事人对询问范围及内容有争议的，保险人负举证责任。"},{"i":7,"n":"第七条","txt":"保险人在保险合同成立后知道或者应当知道投保人未履行如实告知义务，仍然收取保险费，又依照保险法第十六条第二款的规定主张解除合同的，人民法院不予支持。"},{"i":8,"n":"第八条","txt":"保险人未行使合同解除权，直接以存在保险法第十六条第四款、第五款规定的情形为由拒绝赔偿的，人民法院不予支持。但当事人就拒绝赔偿事宜及保险合同存续另行达成一致的情况除外。"},{"i":9,"n":"第九条","txt":"保险人提供的格式合同文本中的责任免除条款、免赔额、免赔率、比例赔付或者给付等免除或者减轻保险人责任的条款，可以认定为保险法第十七条第二款规定的“免除保险人责任的条款”。"},{"i":10,"n":"第十条","txt":"保险人将法律、行政法规中的禁止性规定情形作为保险合同免责条款的免责事由，保险人对该条款作出提示后，投保人、被保险人或者受益人以保险人未履行明确说明义务为由主张该条款不成为合同内容的，人民法院不予支持。"},{"i":11,"n":"第十一条","txt":"保险合同订立时，保险人在投保单或者保险单等其他保险凭证上，对保险合同中免除保险人责任的条款，以足以引起投保人注意的文字、字体、符号或者其他明显标志作出提示的，人民法院应当认定其履行了保险法第十七条第二款规定的提示义务。"},{"i":12,"n":"第十二条","txt":"通过网络、电话等方式订立的保险合同，保险人以网页、音频、视频等形式对免除保险人责任条款予以提示和明确说明的，人民法院可以认定其履行了提示和明确说明义务。"},{"i":13,"n":"第十三条","txt":"保险人对其履行了明确说明义务负举证责任。"},{"i":14,"n":"第十四条","txt":"保险合同中记载的内容不一致的，按照下列规则认定："},{"i":15,"n":"第十五条","txt":"保险法第二十三条规定的三十日核定期间，应自保险人初次收到索赔请求及投保人、被保险人或者受益人提供的有关证明和资料之日起算。"},{"i":16,"n":"第十六条","txt":"保险人应以自己的名义行使保险代位求偿权。"},{"i":17,"n":"第十七条","txt":"保险人在其提供的保险合同格式条款中对非保险术语所作的解释符合专业意义，或者虽不符合专业意义，但有利于投保人、被保险人或者受益人的，人民法院应予认可。"},{"i":18,"n":"第十八条","txt":"行政管理部门依据法律规定制作的交通事故认定书、火灾事故认定书等，人民法院应当依法审查并确认其相应的证明力，但有相反证据能够推翻的除外。"},{"i":19,"n":"第十九条","txt":"保险事故发生后，被保险人或者受益人起诉保险人，保险人以被保险人或者受益人未要求第三者承担责任为由抗辩不承担保险责任的，人民法院不予支持。"},{"i":20,"n":"第二十条","txt":"保险公司依法设立并取得营业执照的分支机构属于《中华人民共和国民事诉讼法》第四十八条规定的其他组织，可以作为保险合同纠纷案件的当事人参加诉讼。"},{"i":21,"n":"第二十一条","txt":"本解释施行后尚未终审的保险合同纠纷案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。"}],"zuigaorenminfayuanguanyushiyongbaoxianfaruoganwent1ba944":[{"i":1,"n":"第一条","txt":"保险标的已交付受让人，但尚未依法办理所有权变更登记，承担保险标的毁损灭失风险的受让人，依照保险法第四十八条、第四十九条的规定主张行使被保险人权利的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"保险人已向投保人履行了保险法规定的提示和明确说明义务，保险标的受让人以保险标的转让后保险人未向其提示或者明确说明为由，主张免除保险人责任的条款不成为合同内容的，人民法院不予支持。"},{"i":3,"n":"第三条","txt":"被保险人死亡，继承保险标的的当事人主张承继被保险人的权利和义务的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"人民法院认定保险标的是否构成保险法第四十九条、第五十二条规定的“危险程度显著增加”时，应当综合考虑以下因素："},{"i":5,"n":"第五条","txt":"被保险人、受让人依法及时向保险人发出保险标的转让通知后，保险人作出答复前，发生保险事故，被保险人或者受让人主张保险人按照保险合同承担赔偿保险金的责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"保险事故发生后，被保险人依照保险法第五十七条的规定，请求保险人承担为防止或者减少保险标的的损失所支付的必要、合理费用，保险人以被保险人采取的措施未产生实际效果为由抗辩的，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"保险人依照保险法第六十条的规定，主张代位行使被保险人因第三者侵权或者违约等享有的请求赔偿的权利的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"投保人和被保险人为不同主体，因投保人对保险标的的损害而造成保险事故，保险人依法主张代位行使被保险人对投保人请求赔偿的权利的，人民法院应予支持，但法律另有规定或者保险合同另有约定的除外。"},{"i":9,"n":"第九条","txt":"在保险人以第三者为被告提起的代位求偿权之诉中，第三者以被保险人在保险合同订立前已放弃对其请求赔偿的权利为由进行抗辩，人民法院认定上述放弃行为合法有效，保险人就相应部分主张行使代位求偿权的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"因第三者对保险标的的损害而造成保险事故，保险人获得代位请求赔偿的权利的情况未通知第三者或者通知到达第三者前，第三者在被保险人已经从保险人处获赔的范围内又向被保险人作出赔偿，保险人主张代位行使被保险人对第三者请求赔偿的权利的，人民法院不予支持。保险人就相应保险金主张被保险人返还的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"被保险人因故意或者重大过失未履行保险法第六十三条规定的义务，致使保险人未能行使或者未能全部行使代位请求赔偿的权利，保险人主张在其损失范围内扣减或者返还相应保险金的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"保险人以造成保险事故的第三者为被告提起代位求偿权之诉的，以被保险人与第三者之间的法律关系确定管辖法院。"},{"i":13,"n":"第十三条","txt":"保险人提起代位求偿权之诉时，被保险人已经向第三者提起诉讼的，人民法院可以依法合并审理。"},{"i":14,"n":"第十四条","txt":"具有下列情形之一的，被保险人可以依照保险法第六十五条第二款的规定请求保险人直接向第三者赔偿保险金："},{"i":15,"n":"第十五条","txt":"被保险人对第三者应负的赔偿责任确定后，被保险人不履行赔偿责任，且第三者以保险人为被告或者以保险人与被保险人为共同被告提起诉讼时，被保险人尚未向保险人提出直接向第三者赔偿保险金的请求的，可以认定为属于保险法第六十五条第二款规定的“被保险人怠于请求”的情形。"},{"i":16,"n":"第十六条","txt":"责任保险的被保险人因共同侵权依法承担连带责任，保险人以该连带责任超出被保险人应承担的责任份额为由，拒绝赔付保险金的，人民法院不予支持。保险人承担保险责任后，主张就超出被保险人责任份额的部分向其他连带责任人追偿的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"责任保险的被保险人对第三者所负的赔偿责任已经生效判决确认并已进入执行程序，但未获得清偿或者未获得全部清偿，第三者依法请求保险人赔偿保险金，保险人以前述生效判决已进入执行程序为由抗辩的，人民法院不予支持。"},{"i":18,"n":"第十八条","txt":"商业责任险的被保险人向保险人请求赔偿保险金的诉讼时效期间，自被保险人对第三者应负的赔偿责任确定之日起计算。"},{"i":19,"n":"第十九条","txt":"责任保险的被保险人与第三者就被保险人的赔偿责任达成和解协议且经保险人认可，被保险人主张保险人在保险合同范围内依据和解协议承担保险责任的，人民法院应予支持。"},{"i":20,"n":"第二十条","txt":"责任保险的保险人在被保险人向第三者赔偿之前向被保险人赔偿保险金，第三者依照保险法第六十五条第二款的规定行使保险金请求权时，保险人以其已向被保险人赔偿为由拒绝赔偿保险金的，人民法院不予支持。保险人向第三者赔偿后，请求被保险人返还相应保险金的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"本解释自2018年9月1日起施行。"}],"zuigaorenminfayuanguanyushiyongxingshisusongfadejicaef4d":[{"i":1,"n":"第一条","txt":"人民法院直接受理的自诉案件包括："},{"i":2,"n":"第二条","txt":"犯罪地包括犯罪行为地和犯罪结果地。"},{"i":3,"n":"第三条","txt":"被告人的户籍地为其居住地。经常居住地与户籍地不一致的，经常居住地为其居住地。经常居住地为被告人被追诉前已连续居住一年以上的地方，但住院就医的除外。"},{"i":4,"n":"第四条","txt":"在中华人民共和国内水、领海发生的刑事案件，由犯罪地或者被告人登陆地的人民法院管辖。由被告人居住地的人民法院审判更为适宜的，可以由被告人居住地的人民法院管辖。"},{"i":5,"n":"第五条","txt":"在列车上的犯罪，被告人在列车运行途中被抓获的，由前方停靠站所在地负责审判铁路运输刑事案件的人民法院管辖。必要时，也可以由始发站或者终点站所在地负责审判铁路运输刑事案件的人民法院管辖。"},{"i":6,"n":"第六条","txt":"在国际列车上的犯罪，根据我国与相关国家签订的协定确定管辖；没有协定的，由该列车始发或者前方停靠的中国车站所在地负责审判铁路运输刑事案件的人民法院管辖。"},{"i":7,"n":"第七条","txt":"在中华人民共和国领域外的中国船舶内的犯罪，由该船舶最初停泊的中国口岸所在地或者被告人登陆地、入境地的人民法院管辖。"},{"i":8,"n":"第八条","txt":"在中华人民共和国领域外的中国航空器内的犯罪，由该航空器在中国最初降落地的人民法院管辖。"},{"i":9,"n":"第九条","txt":"中国公民在中国驻外使领馆内的犯罪，由其主管单位所在地或者原户籍地的人民法院管辖。"},{"i":10,"n":"第十条","txt":"中国公民在中华人民共和国领域外的犯罪，由其登陆地、入境地、离境前居住地或者现居住地的人民法院管辖；被害人是中国公民的，也可以由被害人离境前居住地或者现居住地的人民法院管辖。"},{"i":11,"n":"第十一条","txt":"外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，根据《中华人民共和国刑法》应当受处罚的，由该外国人登陆地、入境地或者入境后居住地的人民法院管辖，也可以由被害人离境前居住地或者现居住地的人民法院管辖。"},{"i":12,"n":"第十二条","txt":"对中华人民共和国缔结或者参加的国际条约所规定的罪行，中华人民共和国在所承担条约义务的范围内行使刑事管辖权的，由被告人被抓获地、登陆地或者入境地的人民法院管辖。"},{"i":13,"n":"第十三条","txt":"正在服刑的罪犯在判决宣告前还有其他罪没有判决的，由原审地人民法院管辖；由罪犯服刑地或者犯罪地的人民法院审判更为适宜的，可以由罪犯服刑地或者犯罪地的人民法院管辖。"},{"i":14,"n":"第十四条","txt":"人民检察院认为可能判处无期徒刑、死刑，向中级人民法院提起公诉的案件，中级人民法院受理后，认为不需要判处无期徒刑、死刑的，应当依法审判，不再交基层人民法院审判。"},{"i":15,"n":"第十五条","txt":"一人犯数罪、共同犯罪或者其他需要并案审理的案件，其中一人或者一罪属于上级人民法院管辖的，全案由上级人民法院管辖。"},{"i":16,"n":"第十六条","txt":"上级人民法院决定审判下级人民法院管辖的第一审刑事案件的，应当向下级人民法院下达改变管辖决定书，并书面通知同级人民检察院。"},{"i":17,"n":"第十七条","txt":"基层人民法院对可能判处无期徒刑、死刑的第一审刑事案件，应当移送中级人民法院审判。"},{"i":18,"n":"第十八条","txt":"有管辖权的人民法院因案件涉及本院院长需要回避或者其他原因，不宜行使管辖权的，可以请求移送上一级人民法院管辖。上一级人民法院可以管辖，也可以指定与提出请求的人民法院同级的其他人民法院管辖。"},{"i":19,"n":"第十九条","txt":"两个以上同级人民法院都有管辖权的案件，由最初受理的人民法院审判。必要时，可以移送主要犯罪地的人民法院审判。"},{"i":20,"n":"第二十条","txt":"管辖不明的案件，上级人民法院可以指定下级人民法院审判。"},{"i":21,"n":"第二十一条","txt":"上级人民法院指定管辖，应当将指定管辖决定书送达被指定管辖的人民法院和其他有关的人民法院。"},{"i":22,"n":"第二十二条","txt":"原受理案件的人民法院在收到上级人民法院改变管辖决定书、同意移送决定书或者指定其他人民法院管辖的决定书后，对公诉案件，应当书面通知同级人民检察院，并将案卷材料退回，同时书面通知当事人；对自诉案件，应当将案卷材料移送被指定管辖的人民法院，并书面通知当事人。"},{"i":23,"n":"第二十三条","txt":"第二审人民法院发回重新审判的案件，人民检察院撤回起诉后，又向原第一审人民法院的下级人民法院重新提起公诉的，下级人民法院应当将有关情况层报原第二审人民法院。原第二审人民法院根据具体情况，可以决定将案件移送原第一审人民法院或者其他人民法院审判。"},{"i":24,"n":"第二十四条","txt":"人民法院发现被告人还有其他犯罪被起诉的，可以并案审理；涉及同种犯罪的，一般应当并案审理。"},{"i":25,"n":"第二十五条","txt":"第二审人民法院在审理过程中，发现被告人还有其他犯罪没有判决的，参照前条规定处理。第二审人民法院决定并案审理的，应当发回第一审人民法院，由第一审人民法院作出处理。"},{"i":26,"n":"第二十六条","txt":"军队和地方互涉刑事案件，按照有关规定确定管辖。"},{"i":27,"n":"第二十七条","txt":"审判人员具有下列情形之一的，应当自行回避，当事人及其法定代理人有权申请其回避："},{"i":28,"n":"第二十八条","txt":"审判人员具有下列情形之一的，当事人及其法定代理人有权申请其回避："},{"i":29,"n":"第二十九条","txt":"参与过本案调查、侦查、审查起诉工作的监察、侦查、检察人员，调至人民法院工作的，不得担任本案的审判人员。"},{"i":30,"n":"第三十条","txt":"依照法律和有关规定应当实行任职回避的，不得担任案件的审判人员。"},{"i":31,"n":"第三十一条","txt":"人民法院应当依法告知当事人及其法定代理人有权申请回避，并告知其合议庭组成人员、独任审判员、法官助理、书记员等人员的名单。"},{"i":32,"n":"第三十二条","txt":"审判人员自行申请回避，或者当事人及其法定代理人申请审判人员回避的，可以口头或者书面提出，并说明理由，由院长决定。"},{"i":33,"n":"第三十三条","txt":"当事人及其法定代理人依照刑事诉讼法第三十条和本解释第二十八条的规定申请回避的，应当提供证明材料。"},{"i":34,"n":"第三十四条","txt":"应当回避的审判人员没有自行回避，当事人及其法定代理人也没有申请其回避的，院长或者审判委员会应当决定其回避。"},{"i":35,"n":"第三十五条","txt":"对当事人及其法定代理人提出的回避申请，人民法院可以口头或者书面作出决定，并将决定告知申请人。"},{"i":36,"n":"第三十六条","txt":"当事人及其法定代理人申请出庭的检察人员回避的，人民法院应当区分情况作出处理："},{"i":37,"n":"第三十七条","txt":"本章所称的审判人员，包括人民法院院长、副院长、审判委员会委员、庭长、副庭长、审判员和人民陪审员。"},{"i":38,"n":"第三十八条","txt":"法官助理、书记员、翻译人员和鉴定人适用审判人员回避的有关规定，其回避问题由院长决定。"},{"i":39,"n":"第三十九条","txt":"辩护人、诉讼代理人可以依照本章的有关规定要求回避、申请复议。"},{"i":40,"n":"第四十条","txt":"人民法院审判案件，应当充分保障被告人依法享有的辩护权利。"},{"i":41,"n":"第四十一条","txt":"审判人员和人民法院其他工作人员从人民法院离任后二年内，不得以律师身份担任辩护人。"},{"i":42,"n":"第四十二条","txt":"对接受委托担任辩护人的，人民法院应当核实其身份证明和授权委托书。"},{"i":43,"n":"第四十三条","txt":"一名被告人可以委托一至二人作为辩护人。"},{"i":44,"n":"第四十四条","txt":"被告人没有委托辩护人的，人民法院自受理案件之日起三日以内，应当告知其有权委托辩护人；被告人因经济困难或者其他原因没有委托辩护人的，应当告知其可以申请法律援助；被告人属于应当提供法律援助情形的，应当告知其将依法通知法律援助机构指派律师为其提供辩护。"},{"i":45,"n":"第四十五条","txt":"审判期间，在押的被告人要求委托辩护人的，人民法院应当在三日以内向其监护人、近亲属或者其指定的人员转达要求。被告人应当提供有关人员的联系方式。有关人员无法通知的，应当告知被告人。"},{"i":46,"n":"第四十六条","txt":"人民法院收到在押被告人提出的法律援助或者法律帮助申请，应当依照有关规定及时转交法律援助机构或者通知值班律师。"},{"i":47,"n":"第四十七条","txt":"对下列没有委托辩护人的被告人，人民法院应当通知法律援助机构指派律师为其提供辩护："},{"i":48,"n":"第四十八条","txt":"具有下列情形之一，被告人没有委托辩护人的，人民法院可以通知法律援助机构指派律师为其提供辩护："},{"i":49,"n":"第四十九条","txt":"人民法院通知法律援助机构指派律师提供辩护的，应当将法律援助通知书、起诉书副本或者判决书送达法律援助机构；决定开庭审理的，除适用简易程序或者速裁程序审理的以外，应当在开庭十五日以前将上述材料送达法律援助机构。"},{"i":50,"n":"第五十条","txt":"被告人拒绝法律援助机构指派的律师为其辩护，坚持自己行使辩护权的，人民法院应当准许。"},{"i":51,"n":"第五十一条","txt":"对法律援助机构指派律师为被告人提供辩护，被告人的监护人、近亲属又代为委托辩护人的，应当听取被告人的意见，由其确定辩护人人选。"},{"i":52,"n":"第五十二条","txt":"审判期间，辩护人接受被告人委托的，应当在接受委托之日起三日以内，将委托手续提交人民法院。"},{"i":53,"n":"第五十三条","txt":"辩护律师可以查阅、摘抄、复制案卷材料。其他辩护人经人民法院许可，也可以查阅、摘抄、复制案卷材料。合议庭、审判委员会的讨论记录以及其他依法不公开的材料不得查阅、摘抄、复制。"},{"i":54,"n":"第五十四条","txt":"对作为证据材料向人民法院移送的讯问录音录像，辩护律师申请查阅的，人民法院应当准许。"},{"i":55,"n":"第五十五条","txt":"查阅、摘抄、复制案卷材料，涉及国家秘密、商业秘密、个人隐私的，应当保密；对不公开审理案件的信息、材料，或者在办案过程中获悉的案件重要信息、证据材料，不得违反规定泄露、披露，不得用于办案以外的用途。人民法院可以要求相关人员出具承诺书。"},{"i":56,"n":"第五十六条","txt":"辩护律师可以同在押的或者被监视居住的被告人会见和通信。其他辩护人经人民法院许可，也可以同在押的或者被监视居住的被告人会见和通信。"},{"i":57,"n":"第五十七条","txt":"辩护人认为在调查、侦查、审查起诉期间监察机关、公安机关、人民检察院收集的证明被告人无罪或者罪轻的证据材料未随案移送，申请人民法院调取的，应当以书面形式提出，并提供相关线索或者材料。人民法院接受申请后，应当向人民检察院调取。人民检察院移送相关证据材料后，人民法院应当及时通知辩护人。"},{"i":58,"n":"第五十八条","txt":"辩护律师申请向被害人及其近亲属、被害人提供的证人收集与本案有关的材料，人民法院认为确有必要的，应当签发准许调查书。"},{"i":59,"n":"第五十九条","txt":"辩护律师向证人或者有关单位、个人收集、调取与本案有关的证据材料，因证人或者有关单位、个人不同意，申请人民法院收集、调取，或者申请通知证人出庭作证，人民法院认为确有必要的，应当同意。"},{"i":60,"n":"第六十条","txt":"辩护律师直接申请人民法院向证人或者有关单位、个人收集、调取证据材料，人民法院认为确有必要，且不宜或者不能由辩护律师收集、调取的，应当同意。"},{"i":61,"n":"第六十一条","txt":"本解释第五十八条至第六十条规定的申请，应当以书面形式提出，并说明理由，写明需要收集、调取证据材料的内容或者需要调查问题的提纲。"},{"i":62,"n":"第六十二条","txt":"人民法院自受理自诉案件之日起三日以内，应当告知自诉人及其法定代理人、附带民事诉讼当事人及其法定代理人，有权委托诉讼代理人，并告知其如果经济困难，可以申请法律援助。"},{"i":63,"n":"第六十三条","txt":"当事人委托诉讼代理人的，参照适用刑事诉讼法第三十三条和本解释的有关规定。"},{"i":64,"n":"第六十四条","txt":"诉讼代理人有权根据事实和法律，维护被害人、自诉人或者附带民事诉讼当事人的诉讼权利和其他合法权益。"},{"i":65,"n":"第六十五条","txt":"律师担任诉讼代理人的，可以查阅、摘抄、复制案卷材料。其他诉讼代理人经人民法院许可，也可以查阅、摘抄、复制案卷材料。"},{"i":66,"n":"第六十六条","txt":"诉讼代理人接受当事人委托或者法律援助机构指派后，应当在三日以内将委托手续或者法律援助手续提交人民法院。"},{"i":67,"n":"第六十七条","txt":"辩护律师向人民法院告知其委托人或者其他人准备实施、正在实施危害国家安全、公共安全以及严重危害他人人身安全犯罪的，人民法院应当记录在案，立即转告主管机关依法处理，并为反映有关情况的辩护律师保密。"},{"i":68,"n":"第六十八条","txt":"律师担任辩护人、诉讼代理人，经人民法院准许，可以带一名助理参加庭审。律师助理参加庭审的，可以从事辅助工作，但不得发表辩护、代理意见。"},{"i":69,"n":"第六十九条","txt":"认定案件事实，必须以证据为根据。"},{"i":70,"n":"第七十条","txt":"审判人员应当依照法定程序收集、审查、核实、认定证据。"},{"i":71,"n":"第七十一条","txt":"证据未经当庭出示、辨认、质证等法庭调查程序查证属实，不得作为定案的根据。"},{"i":72,"n":"第七十二条","txt":"应当运用证据证明的案件事实包括："},{"i":73,"n":"第七十三条","txt":"对提起公诉的案件，人民法院应当审查证明被告人有罪、无罪、罪重、罪轻的证据材料是否全部随案移送；未随案移送的，应当通知人民检察院在指定时间内移送。人民检察院未移送的，人民法院应当根据在案证据对案件事实作出认定。"},{"i":74,"n":"第七十四条","txt":"依法应当对讯问过程录音录像的案件，相关录音录像未随案移送的，必要时，人民法院可以通知人民检察院在指定时间内移送。人民检察院未移送，导致不能排除属于刑事诉讼法第五十六条规定的以非法方法收集证据情形的，对有关证据应当依法排除；导致有关证据的真实性无法确认的，不得作为定案的根据。"},{"i":75,"n":"第七十五条","txt":"行政机关在行政执法和查办案件过程中收集的物证、书证、视听资料、电子数据等证据材料，经法庭查证属实，且收集程序符合有关法律、行政法规规定的，可以作为定案的根据。"},{"i":76,"n":"第七十六条","txt":"监察机关依法收集的证据材料，在刑事诉讼中可以作为证据使用。"},{"i":77,"n":"第七十七条","txt":"对来自境外的证据材料，人民检察院应当随案移送有关材料来源、提供人、提取人、提取时间等情况的说明。经人民法院审查，相关证据材料能够证明案件事实且符合刑事诉讼法规定的，可以作为证据使用，但提供人或者我国与有关国家签订的双边条约对材料的使用范围有明确限制的除外；材料来源不明或者真实性无法确认的，不得作为定案的根据。"},{"i":78,"n":"第七十八条","txt":"控辩双方提供的证据材料涉及外国语言、文字的，应当附中文译本。"},{"i":79,"n":"第七十九条","txt":"人民法院依照刑事诉讼法第一百九十六条的规定调查核实证据，必要时，可以通知检察人员、辩护人、自诉人及其法定代理人到场。上述人员未到场的，应当记录在案。"},{"i":80,"n":"第八十条","txt":"下列人员不得担任见证人："},{"i":81,"n":"第八十一条","txt":"公开审理案件时，公诉人、诉讼参与人提出涉及国家秘密、商业秘密或者个人隐私的证据的，法庭应当制止；确与本案有关的，可以根据具体情况，决定将案件转为不公开审理，或者对相关证据的法庭调查不公开进行。"},{"i":82,"n":"第八十二条","txt":"对物证、书证应当着重审查以下内容："},{"i":83,"n":"第八十三条","txt":"据以定案的物证应当是原物。原物不便搬运、不易保存、依法应当返还或者依法应当由有关部门保管、处理的，可以拍摄、制作足以反映原物外形和特征的照片、录像、复制品。必要时，审判人员可以前往保管场所查看原物。"},{"i":84,"n":"第八十四条","txt":"据以定案的书证应当是原件。取得原件确有困难的，可以使用副本、复制件。"},{"i":85,"n":"第八十五条","txt":"对与案件事实可能有关联的血迹、体液、毛发、人体组织、指纹、足迹、字迹等生物样本、痕迹和物品，应当提取而没有提取，应当鉴定而没有鉴定，应当移送鉴定意见而没有移送，导致案件事实存疑的，人民法院应当通知人民检察院依法补充收集、调取、移送证据。"},{"i":86,"n":"第八十六条","txt":"在勘验、检查、搜查过程中提取、扣押的物证、书证，未附笔录或者清单，不能证明物证、书证来源的，不得作为定案的根据。"},{"i":87,"n":"第八十七条","txt":"对证人证言应当着重审查以下内容："},{"i":88,"n":"第八十八条","txt":"处于明显醉酒、中毒或者麻醉等状态，不能正常感知或者正确表达的证人所提供的证言，不得作为证据使用。"},{"i":89,"n":"第八十九条","txt":"证人证言具有下列情形之一的，不得作为定案的根据："},{"i":90,"n":"第九十条","txt":"证人证言的收集程序、方式有下列瑕疵，经补正或者作出合理解释的，可以采用；不能补正或者作出合理解释的，不得作为定案的根据："},{"i":91,"n":"第九十一条","txt":"证人当庭作出的证言，经控辩双方质证、法庭查证属实的，应当作为定案的根据。"},{"i":92,"n":"第九十二条","txt":"对被害人陈述的审查与认定，参照适用本节的有关规定。"},{"i":93,"n":"第九十三条","txt":"对被告人供述和辩解应当着重审查以下内容："},{"i":94,"n":"第九十四条","txt":"被告人供述具有下列情形之一的，不得作为定案的根据："},{"i":95,"n":"第九十五条","txt":"讯问笔录有下列瑕疵，经补正或者作出合理解释的，可以采用；不能补正或者作出合理解释的，不得作为定案的根据："},{"i":96,"n":"第九十六条","txt":"审查被告人供述和辩解，应当结合控辩双方提供的所有证据以及被告人的全部供述和辩解进行。"},{"i":97,"n":"第九十七条","txt":"对鉴定意见应当着重审查以下内容："},{"i":98,"n":"第九十八条","txt":"鉴定意见具有下列情形之一的，不得作为定案的根据："},{"i":99,"n":"第九十九条","txt":"经人民法院通知，鉴定人拒不出庭作证的，鉴定意见不得作为定案的根据。"},{"i":100,"n":"第一百条","txt":"因无鉴定机构，或者根据法律、司法解释的规定，指派、聘请有专门知识的人就案件的专门性问题出具的报告，可以作为证据使用。"},{"i":101,"n":"第一百零一条","txt":"有关部门对事故进行调查形成的报告，在刑事诉讼中可以作为证据使用；报告中涉及专门性问题的意见，经法庭查证属实，且调查程序符合法律、有关规定的，可以作为定案的根据。"},{"i":102,"n":"第一百零二条","txt":"对勘验、检查笔录应当着重审查以下内容："},{"i":103,"n":"第一百零三条","txt":"勘验、检查笔录存在明显不符合法律、有关规定的情形，不能作出合理解释的，不得作为定案的根据。"},{"i":104,"n":"第一百零四条","txt":"对辨认笔录应当着重审查辨认的过程、方法，以及辨认笔录的制作是否符合有关规定。"},{"i":105,"n":"第一百零五条","txt":"辨认笔录具有下列情形之一的，不得作为定案的根据："},{"i":106,"n":"第一百零六条","txt":"对侦查实验笔录应当着重审查实验的过程、方法，以及笔录的制作是否符合有关规定。"},{"i":107,"n":"第一百零七条","txt":"侦查实验的条件与事件发生时的条件有明显差异，或者存在影响实验结论科学性的其他情形的，侦查实验笔录不得作为定案的根据。"},{"i":108,"n":"第一百零八条","txt":"对视听资料应当着重审查以下内容："},{"i":109,"n":"第一百零九条","txt":"视听资料具有下列情形之一的，不得作为定案的根据："},{"i":110,"n":"第一百一十条","txt":"对电子数据是否真实，应当着重审查以下内容："},{"i":111,"n":"第一百一十一条","txt":"对电子数据是否完整，应当根据保护电子数据完整性的相应方法进行审查、验证："},{"i":112,"n":"第一百一十二条","txt":"对收集、提取电子数据是否合法，应当着重审查以下内容："},{"i":113,"n":"第一百一十三条","txt":"电子数据的收集、提取程序有下列瑕疵，经补正或者作出合理解释的，可以采用；不能补正或者作出合理解释的，不得作为定案的根据："},{"i":114,"n":"第一百一十四条","txt":"电子数据具有下列情形之一的，不得作为定案的根据："},{"i":115,"n":"第一百一十五条","txt":"对视听资料、电子数据，还应当审查是否移送文字抄清材料以及对绰号、暗语、俗语、方言等不易理解内容的说明。未移送的，必要时，可以要求人民检察院移送。"},{"i":116,"n":"第一百一十六条","txt":"依法采取技术调查、侦查措施收集的材料在刑事诉讼中可以作为证据使用。"},{"i":117,"n":"第一百一十七条","txt":"使用采取技术调查、侦查措施收集的证据材料可能危及有关人员的人身安全，或者可能产生其他严重后果的，可以采取下列保护措施："},{"i":118,"n":"第一百一十八条","txt":"移送技术调查、侦查证据材料的，应当附采取技术调查、侦查措施的法律文书、技术调查、侦查证据材料清单和有关说明材料。"},{"i":119,"n":"第一百一十九条","txt":"对采取技术调查、侦查措施收集的证据材料，除根据相关证据材料所属的证据种类，依照本章第二节至第七节的相应规定进行审查外，还应当着重审查以下内容："},{"i":120,"n":"第一百二十条","txt":"采取技术调查、侦查措施收集的证据材料，应当经过当庭出示、辨认、质证等法庭调查程序查证。"},{"i":121,"n":"第一百二十一条","txt":"采用技术调查、侦查证据作为定案根据的，人民法院在裁判文书中可以表述相关证据的名称、证据种类和证明对象，但不得表述有关人员身份和技术调查、侦查措施使用的技术设备、技术方法等。"},{"i":122,"n":"第一百二十二条","txt":"人民法院认为应当移送的技术调查、侦查证据材料未随案移送的，应当通知人民检察院在指定时间内移送。人民检察院未移送的，人民法院应当根据在案证据对案件事实作出认定。"},{"i":123,"n":"第一百二十三条","txt":"采用下列非法方法收集的被告人供述，应当予以排除："},{"i":124,"n":"第一百二十四条","txt":"采用刑讯逼供方法使被告人作出供述，之后被告人受该刑讯逼供行为影响而作出的与该供述相同的重复性供述，应当一并排除，但下列情形除外："},{"i":125,"n":"第一百二十五条","txt":"采用暴力、威胁以及非法限制人身自由等非法方法收集的证人证言、被害人陈述，应当予以排除。"},{"i":126,"n":"第一百二十六条","txt":"收集物证、书证不符合法定程序，可能严重影响司法公正的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，对该证据应当予以排除。"},{"i":127,"n":"第一百二十七条","txt":"当事人及其辩护人、诉讼代理人申请人民法院排除以非法方法收集的证据的，应当提供涉嫌非法取证的人员、时间、地点、方式、内容等相关线索或者材料。"},{"i":128,"n":"第一百二十八条","txt":"人民法院向被告人及其辩护人送达起诉书副本时，应当告知其申请排除非法证据的，应当在开庭审理前提出，但庭审期间才发现相关线索或者材料的除外。"},{"i":129,"n":"第一百二十九条","txt":"开庭审理前，当事人及其辩护人、诉讼代理人申请人民法院排除非法证据的，人民法院应当在开庭前及时将申请书或者申请笔录及相关线索、材料的复制件送交人民检察院。"},{"i":130,"n":"第一百三十条","txt":"开庭审理前，人民法院可以召开庭前会议，就非法证据排除等问题了解情况，听取意见。"},{"i":131,"n":"第一百三十一条","txt":"在庭前会议中，人民检察院可以撤回有关证据。撤回的证据，没有新的理由，不得在庭审中出示。"},{"i":132,"n":"第一百三十二条","txt":"当事人及其辩护人、诉讼代理人在开庭审理前未申请排除非法证据，在庭审过程中提出申请的，应当说明理由。人民法院经审查，对证据收集的合法性有疑问的，应当进行调查；没有疑问的，驳回申请。"},{"i":133,"n":"第一百三十三条","txt":"控辩双方在庭前会议中对证据收集是否合法未达成一致意见，人民法院对证据收集的合法性有疑问的，应当在庭审中进行调查；对证据收集的合法性没有疑问，且无新的线索或者材料表明可能存在非法取证的，可以决定不再进行调查并说明理由。"},{"i":134,"n":"第一百三十四条","txt":"庭审期间，法庭决定对证据收集的合法性进行调查的，应当先行当庭调查。但为防止庭审过分迟延，也可以在法庭调查结束前调查。"},{"i":135,"n":"第一百三十五条","txt":"法庭决定对证据收集的合法性进行调查的，由公诉人通过宣读调查、侦查讯问笔录、出示提讯登记、体检记录、对讯问合法性的核查材料等证据材料，有针对性地播放讯问录音录像，提请法庭通知有关调查人员、侦查人员或者其他人员出庭说明情况等方式，证明证据收集的合法性。"},{"i":136,"n":"第一百三十六条","txt":"控辩双方申请法庭通知调查人员、侦查人员或者其他人员出庭说明情况，法庭认为有必要的，应当通知有关人员出庭。"},{"i":137,"n":"第一百三十七条","txt":"法庭对证据收集的合法性进行调查后，确认或者不能排除存在刑事诉讼法第五十六条规定的以非法方法收集证据情形的，对有关证据应当排除。"},{"i":138,"n":"第一百三十八条","txt":"具有下列情形之一的，第二审人民法院应当对证据收集的合法性进行审查，并根据刑事诉讼法和本解释的有关规定作出处理："},{"i":139,"n":"第一百三十九条","txt":"对证据的真实性，应当综合全案证据进行审查。"},{"i":140,"n":"第一百四十条","txt":"没有直接证据，但间接证据同时符合下列条件的，可以认定被告人有罪："},{"i":141,"n":"第一百四十一条","txt":"根据被告人的供述、指认提取到了隐蔽性很强的物证、书证，且被告人的供述与其他证明犯罪事实发生的证据相互印证，并排除串供、逼供、诱供等可能性的，可以认定被告人有罪。"},{"i":142,"n":"第一百四十二条","txt":"对监察机关、侦查机关出具的被告人到案经过、抓获经过等材料，应当审查是否有出具该说明材料的办案人员、办案机关的签名、盖章。"},{"i":143,"n":"第一百四十三条","txt":"下列证据应当慎重使用，有其他证据印证的，可以采信："},{"i":144,"n":"第一百四十四条","txt":"证明被告人自首、坦白、立功的证据材料，没有加盖接受被告人投案、坦白、检举揭发等的单位的印章，或者接受人员没有签名的，不得作为定案的根据。"},{"i":145,"n":"第一百四十五条","txt":"证明被告人具有累犯、毒品再犯情节等的证据材料，应当包括前罪的裁判文书、释放证明等材料；材料不全的，应当通知人民检察院提供。"},{"i":146,"n":"第一百四十六条","txt":"审查被告人实施被指控的犯罪时或者审判时是否达到相应法定责任年龄，应当根据户籍证明、出生证明文件、学籍卡、人口普查登记、无利害关系人的证言等证据综合判断。"},{"i":147,"n":"第一百四十七条","txt":"人民法院根据案件情况，可以决定对被告人拘传、取保候审、监视居住或者逮捕。"},{"i":148,"n":"第一百四十八条","txt":"对经依法传唤拒不到庭的被告人，或者根据案件情况有必要拘传的被告人，可以拘传。"},{"i":149,"n":"第一百四十九条","txt":"拘传被告人，持续的时间不得超过十二小时；案情特别重大、复杂，需要采取逮捕措施的，持续的时间不得超过二十四小时。不得以连续拘传的形式变相拘禁被告人。应当保证被拘传人的饮食和必要的休息时间。"},{"i":150,"n":"第一百五十条","txt":"被告人具有刑事诉讼法第六十七条第一款规定情形之一的，人民法院可以决定取保候审。"},{"i":151,"n":"第一百五十一条","txt":"对下列被告人决定取保候审的，可以责令其提出一至二名保证人："},{"i":152,"n":"第一百五十二条","txt":"人民法院应当审查保证人是否符合法定条件。符合条件的，应当告知其必须履行的保证义务，以及不履行义务的法律后果，并由其出具保证书。"},{"i":153,"n":"第一百五十三条","txt":"对决定取保候审的被告人使用保证金保证的，应当依照刑事诉讼法第七十二条第一款的规定确定保证金的具体数额，并责令被告人或者为其提供保证金的单位、个人将保证金一次性存入公安机关指定银行的专门账户。"},{"i":154,"n":"第一百五十四条","txt":"人民法院向被告人宣布取保候审决定后，应当将取保候审决定书等相关材料送交当地公安机关。"},{"i":155,"n":"第一百五十五条","txt":"被告人被取保候审期间，保证人不愿继续履行保证义务或者丧失履行保证义务能力的，人民法院应当在收到保证人的申请或者公安机关的书面通知后三日以内，责令被告人重新提出保证人或者交纳保证金，或者变更强制措施，并通知公安机关。"},{"i":156,"n":"第一百五十六条","txt":"人民法院发现保证人未履行保证义务的，应当书面通知公安机关依法处理。"},{"i":157,"n":"第一百五十七条","txt":"根据案件事实和法律规定，认为已经构成犯罪的被告人在取保候审期间逃匿的，如果系保证人协助被告人逃匿，或者保证人明知被告人藏匿地点但拒绝向司法机关提供，对保证人应当依法追究责任。"},{"i":158,"n":"第一百五十八条","txt":"人民法院发现使用保证金保证的被取保候审人违反刑事诉讼法第七十一条第一款、第二款规定的，应当书面通知公安机关依法处理。"},{"i":159,"n":"第一百五十九条","txt":"对被取保候审的被告人的判决、裁定生效后，如果保证金属于其个人财产，且需要用以退赔被害人、履行附带民事赔偿义务或者执行财产刑的，人民法院可以书面通知公安机关移交全部保证金，由人民法院作出处理，剩余部分退还被告人。"},{"i":160,"n":"第一百六十条","txt":"对具有刑事诉讼法第七十四条第一款、第二款规定情形的被告人，人民法院可以决定监视居住。"},{"i":161,"n":"第一百六十一条","txt":"人民法院向被告人宣布监视居住决定后，应当将监视居住决定书等相关材料送交被告人住处或者指定居所所在地的公安机关执行。"},{"i":162,"n":"第一百六十二条","txt":"人民检察院、公安机关已经对犯罪嫌疑人取保候审、监视居住，案件起诉至人民法院后，需要继续取保候审、监视居住或者变更强制措施的，人民法院应当在七日以内作出决定，并通知人民检察院、公安机关。"},{"i":163,"n":"第一百六十三条","txt":"对具有刑事诉讼法第八十一条第一款、第三款规定情形的被告人，人民法院应当决定逮捕。"},{"i":164,"n":"第一百六十四条","txt":"被取保候审的被告人具有下列情形之一的，人民法院应当决定逮捕："},{"i":165,"n":"第一百六十五条","txt":"被监视居住的被告人具有下列情形之一的，人民法院应当决定逮捕："},{"i":166,"n":"第一百六十六条","txt":"对可能判处徒刑以下刑罚的被告人，违反取保候审、监视居住规定，严重影响诉讼活动正常进行的，可以决定逮捕。"},{"i":167,"n":"第一百六十七条","txt":"人民法院作出逮捕决定后，应当将逮捕决定书等相关材料送交公安机关执行，并将逮捕决定书抄送人民检察院。逮捕被告人后，人民法院应当将逮捕的原因和羁押的处所，在二十四小时以内通知其家属；确实无法通知的，应当记录在案。"},{"i":168,"n":"第一百六十八条","txt":"人民法院对决定逮捕的被告人，应当在逮捕后二十四小时以内讯问。发现不应当逮捕的，应当立即释放。必要时，可以依法变更强制措施。"},{"i":169,"n":"第一百六十九条","txt":"被逮捕的被告人具有下列情形之一的，人民法院可以变更强制措施："},{"i":170,"n":"第一百七十条","txt":"被逮捕的被告人具有下列情形之一的，人民法院应当立即释放；必要时，可以依法变更强制措施："},{"i":171,"n":"第一百七十一条","txt":"人民法院决定释放被告人的，应当立即将释放通知书送交公安机关执行。"},{"i":172,"n":"第一百七十二条","txt":"被采取强制措施的被告人，被判处管制、缓刑的，在社区矫正开始后，强制措施自动解除；被单处附加刑的，在判决、裁定发生法律效力后，强制措施自动解除；被判处监禁刑的，在刑罚开始执行后，强制措施自动解除。"},{"i":173,"n":"第一百七十三条","txt":"对人民法院决定逮捕的被告人，人民检察院建议释放或者变更强制措施的，人民法院应当在收到建议后十日以内将处理情况通知人民检察院。"},{"i":174,"n":"第一百七十四条","txt":"被告人及其法定代理人、近亲属或者辩护人申请变更、解除强制措施的，应当说明理由。人民法院收到申请后，应当在三日以内作出决定。同意变更、解除强制措施的，应当依照本解释规定处理；不同意的，应当告知申请人，并说明理由。"},{"i":175,"n":"第一百七十五条","txt":"被害人因人身权利受到犯罪侵犯或者财物被犯罪分子毁坏而遭受物质损失的，有权在刑事诉讼过程中提起附带民事诉讼；被害人死亡或者丧失行为能力的，其法定代理人、近亲属有权提起附带民事诉讼。"},{"i":176,"n":"第一百七十六条","txt":"被告人非法占有、处置被害人财产的，应当依法予以追缴或者责令退赔。被害人提起附带民事诉讼的，人民法院不予受理。追缴、退赔的情况，可以作为量刑情节考虑。"},{"i":177,"n":"第一百七十七条","txt":"国家机关工作人员在行使职权时，侵犯他人人身、财产权利构成犯罪，被害人或者其法定代理人、近亲属提起附带民事诉讼的，人民法院不予受理，但应当告知其可以依法申请国家赔偿。"},{"i":178,"n":"第一百七十八条","txt":"人民法院受理刑事案件后，对符合刑事诉讼法第一百零一条和本解释第一百七十五条第一款规定的，可以告知被害人或者其法定代理人、近亲属有权提起附带民事诉讼。"},{"i":179,"n":"第一百七十九条","txt":"国家财产、集体财产遭受损失，受损失的单位未提起附带民事诉讼，人民检察院在提起公诉时提起附带民事诉讼的，人民法院应当受理。"},{"i":180,"n":"第一百八十条","txt":"附带民事诉讼中依法负有赔偿责任的人包括："},{"i":181,"n":"第一百八十一条","txt":"被害人或者其法定代理人、近亲属仅对部分共同侵害人提起附带民事诉讼的，人民法院应当告知其可以对其他共同侵害人，包括没有被追究刑事责任的共同侵害人，一并提起附带民事诉讼，但共同犯罪案件中同案犯在逃的除外。"},{"i":182,"n":"第一百八十二条","txt":"附带民事诉讼的起诉条件是："},{"i":183,"n":"第一百八十三条","txt":"共同犯罪案件，同案犯在逃的，不应列为附带民事诉讼被告人。逃跑的同案犯到案后，被害人或者其法定代理人、近亲属可以对其提起附带民事诉讼，但已经从其他共同犯罪人处获得足额赔偿的除外。"},{"i":184,"n":"第一百八十四条","txt":"附带民事诉讼应当在刑事案件立案后及时提起。"},{"i":185,"n":"第一百八十五条","txt":"侦查、审查起诉期间，有权提起附带民事诉讼的人提出赔偿要求，经公安机关、人民检察院调解，当事人双方已经达成协议并全部履行，被害人或者其法定代理人、近亲属又提起附带民事诉讼的，人民法院不予受理，但有证据证明调解违反自愿、合法原则的除外。"},{"i":186,"n":"第一百八十六条","txt":"被害人或者其法定代理人、近亲属提起附带民事诉讼的，人民法院应当在七日以内决定是否受理。符合刑事诉讼法第一百零一条以及本解释有关规定的，应当受理；不符合的，裁定不予受理。"},{"i":187,"n":"第一百八十七条","txt":"人民法院受理附带民事诉讼后，应当在五日以内将附带民事起诉状副本送达附带民事诉讼被告人及其法定代理人，或者将口头起诉的内容及时通知附带民事诉讼被告人及其法定代理人，并制作笔录。"},{"i":188,"n":"第一百八十八条","txt":"附带民事诉讼当事人对自己提出的主张，有责任提供证据。"},{"i":189,"n":"第一百八十九条","txt":"人民法院对可能因被告人的行为或者其他原因，使附带民事判决难以执行的案件，根据附带民事诉讼原告人的申请，可以裁定采取保全措施，查封、扣押或者冻结被告人的财产；附带民事诉讼原告人未提出申请的，必要时，人民法院也可以采取保全措施。"},{"i":190,"n":"第一百九十条","txt":"人民法院审理附带民事诉讼案件，可以根据自愿、合法的原则进行调解。经调解达成协议的，应当制作调解书。调解书经双方当事人签收后即具有法律效力。"},{"i":191,"n":"第一百九十一条","txt":"调解未达成协议或者调解书签收前当事人反悔的，附带民事诉讼应当同刑事诉讼一并判决。"},{"i":192,"n":"第一百九十二条","txt":"对附带民事诉讼作出判决，应当根据犯罪行为造成的物质损失，结合案件具体情况，确定被告人应当赔偿的数额。"},{"i":193,"n":"第一百九十三条","txt":"人民检察院提起附带民事诉讼的，人民法院经审理，认为附带民事诉讼被告人依法应当承担赔偿责任的，应当判令附带民事诉讼被告人直接向遭受损失的单位作出赔偿；遭受损失的单位已经终止，有权利义务继受人的，应当判令其向继受人作出赔偿；没有权利义务继受人的，应当判令其向人民检察院交付赔偿款，由人民检察院上缴国库。"},{"i":194,"n":"第一百九十四条","txt":"审理刑事附带民事诉讼案件，人民法院应当结合被告人赔偿被害人物质损失的情况认定其悔罪表现，并在量刑时予以考虑。"},{"i":195,"n":"第一百九十五条","txt":"附带民事诉讼原告人经传唤，无正当理由拒不到庭，或者未经法庭许可中途退庭的，应当按撤诉处理。"},{"i":196,"n":"第一百九十六条","txt":"附带民事诉讼应当同刑事案件一并审判，只有为了防止刑事案件审判的过分迟延，才可以在刑事案件审判后，由同一审判组织继续审理附带民事诉讼；同一审判组织的成员确实不能继续参与审判的，可以更换。"},{"i":197,"n":"第一百九十七条","txt":"人民法院认定公诉案件被告人的行为不构成犯罪，对已经提起的附带民事诉讼，经调解不能达成协议的，可以一并作出刑事附带民事判决，也可以告知附带民事原告人另行提起民事诉讼。"},{"i":198,"n":"第一百九十八条","txt":"第一审期间未提起附带民事诉讼，在第二审期间提起的，第二审人民法院可以依法进行调解；调解不成的，告知当事人可以在刑事判决、裁定生效后另行提起民事诉讼。"},{"i":199,"n":"第一百九十九条","txt":"人民法院审理附带民事诉讼案件，不收取诉讼费。"},{"i":200,"n":"第二百条","txt":"被害人或者其法定代理人、近亲属在刑事诉讼过程中未提起附带民事诉讼，另行提起民事诉讼的，人民法院可以进行调解，或者根据本解释第一百九十二条第二款、第三款的规定作出判决。"},{"i":201,"n":"第二百零一条","txt":"人民法院审理附带民事诉讼案件，除刑法、刑事诉讼法以及刑事司法解释已有规定的以外，适用民事法律的有关规定。"},{"i":202,"n":"第二百零二条","txt":"以月计算的期间，自本月某日至下月同日为一个月；期限起算日为本月最后一日的，至下月最后一日为一个月；下月同日不存在的，自本月某日至下月最后一日为一个月；半个月一律按十五日计算。"},{"i":203,"n":"第二百零三条","txt":"当事人由于不能抗拒的原因或者有其他正当理由而耽误期限，依法申请继续进行应当在期满前完成的诉讼活动的，人民法院查证属实后，应当裁定准许。"},{"i":204,"n":"第二百零四条","txt":"送达诉讼文书，应当由收件人签收。收件人不在的，可以由其成年家属或者所在单位负责收件的人员代收。收件人或者代收人在送达回证上签收的日期为送达日期。"},{"i":205,"n":"第二百零五条","txt":"直接送达诉讼文书有困难的，可以委托收件人所在地的人民法院代为送达或者邮寄送达。"},{"i":206,"n":"第二百零六条","txt":"委托送达的，应当将委托函、委托送达的诉讼文书及送达回证寄送受托法院。受托法院收到后，应当登记，在十日以内送达收件人，并将送达回证寄送委托法院；无法送达的，应当告知委托法院，并将诉讼文书及送达回证退回。"},{"i":207,"n":"第二百零七条","txt":"邮寄送达的，应当将诉讼文书、送达回证邮寄给收件人。签收日期为送达日期。"},{"i":208,"n":"第二百零八条","txt":"诉讼文书的收件人是军人的，可以通过其所在部队团级以上单位的政治部门转交。"},{"i":209,"n":"第二百零九条","txt":"指定管辖案件的审理期限，自被指定管辖的人民法院收到指定管辖决定书和案卷、证据材料之日起计算。"},{"i":210,"n":"第二百一十条","txt":"对可能判处死刑的案件或者附带民事诉讼的案件，以及有刑事诉讼法第一百五十八条规定情形之一的案件，上一级人民法院可以批准延长审理期限一次，期限为三个月。因特殊情况还需要延长的，应当报请最高人民法院批准。"},{"i":211,"n":"第二百一十一条","txt":"审判期间，对被告人作精神病鉴定的时间不计入审理期限。"},{"i":212,"n":"第二百一十二条","txt":"合议庭由审判员担任审判长。院长或者庭长参加审理案件时，由其本人担任审判长。"},{"i":213,"n":"第二百一十三条","txt":"基层人民法院、中级人民法院、高级人民法院审判下列第一审刑事案件，由审判员和人民陪审员组成合议庭进行："},{"i":214,"n":"第二百一十四条","txt":"开庭审理和评议案件，应当由同一合议庭进行。合议庭成员在评议案件时，应当独立发表意见并说明理由。意见分歧的，应当按多数意见作出决定，但少数意见应当记入笔录。评议笔录由合议庭的组成人员在审阅确认无误后签名。评议情况应当保密。"},{"i":215,"n":"第二百一十五条","txt":"人民陪审员参加三人合议庭审判案件，应当对事实认定、法律适用独立发表意见，行使表决权。"},{"i":216,"n":"第二百一十六条","txt":"合议庭审理、评议后，应当及时作出判决、裁定。"},{"i":217,"n":"第二百一十七条","txt":"审判委员会的决定，合议庭、独任审判员应当执行；有不同意见的，可以建议院长提交审判委员会复议。"},{"i":218,"n":"第二百一十八条","txt":"对提起公诉的案件，人民法院应当在收到起诉书（一式八份，每增加一名被告人，增加起诉书五份）和案卷、证据后，审查以下内容："},{"i":219,"n":"第二百一十九条","txt":"人民法院对提起公诉的案件审查后，应当按照下列情形分别处理："},{"i":220,"n":"第二百二十条","txt":"对一案起诉的共同犯罪或者关联犯罪案件，被告人人数众多、案情复杂，人民法院经审查认为，分案审理更有利于保障庭审质量和效率的，可以分案审理。分案审理不得影响当事人质证权等诉讼权利的行使。"},{"i":221,"n":"第二百二十一条","txt":"开庭审理前，人民法院应当进行下列工作："},{"i":222,"n":"第二百二十二条","txt":"审判案件应当公开进行。"},{"i":223,"n":"第二百二十三条","txt":"精神病人、醉酒的人、未经人民法院批准的未成年人以及其他不宜旁听的人不得旁听案件审理。"},{"i":224,"n":"第二百二十四条","txt":"被害人人数众多，且案件不属于附带民事诉讼范围的，被害人可以推选若干代表人参加庭审。"},{"i":225,"n":"第二百二十五条","txt":"被害人、诉讼代理人经传唤或者通知未到庭，不影响开庭审理的，人民法院可以开庭审理。"},{"i":226,"n":"第二百二十六条","txt":"案件具有下列情形之一的，人民法院可以决定召开庭前会议："},{"i":227,"n":"第二百二十七条","txt":"控辩双方可以申请人民法院召开庭前会议，提出申请应当说明理由。人民法院经审查认为有必要的，应当召开庭前会议；决定不召开的，应当告知申请人。"},{"i":228,"n":"第二百二十八条","txt":"庭前会议可以就下列事项向控辩双方了解情况，听取意见："},{"i":229,"n":"第二百二十九条","txt":"庭前会议中，审判人员可以询问控辩双方对证据材料有无异议，对有异议的证据，应当在庭审时重点调查；无异议的，庭审时举证、质证可以简化。"},{"i":230,"n":"第二百三十条","txt":"庭前会议由审判长主持，合议庭其他审判员也可以主持庭前会议。"},{"i":231,"n":"第二百三十一条","txt":"庭前会议一般不公开进行。"},{"i":232,"n":"第二百三十二条","txt":"人民法院在庭前会议中听取控辩双方对案件事实、证据材料的意见后，对明显事实不清、证据不足的案件，可以建议人民检察院补充材料或者撤回起诉。建议撤回起诉的案件，人民检察院不同意的，开庭审理后，没有新的事实和理由，一般不准许撤回起诉。"},{"i":233,"n":"第二百三十三条","txt":"对召开庭前会议的案件，可以在开庭时告知庭前会议情况。对庭前会议中达成一致意见的事项，法庭在向控辩双方核实后，可以当庭予以确认；未达成一致意见的事项，法庭可以归纳控辩双方争议焦点，听取控辩双方意见，依法作出处理。"},{"i":234,"n":"第二百三十四条","txt":"开庭审理前，书记员应当依次进行下列工作："},{"i":235,"n":"第二百三十五条","txt":"审判长宣布开庭，传被告人到庭后，应当查明被告人的下列情况："},{"i":236,"n":"第二百三十六条","txt":"审判长宣布案件的来源、起诉的案由、附带民事诉讼当事人的姓名及是否公开审理；不公开审理的，应当宣布理由。"},{"i":237,"n":"第二百三十七条","txt":"审判长宣布合议庭组成人员、法官助理、书记员、公诉人的名单，以及辩护人、诉讼代理人、鉴定人、翻译人员等诉讼参与人的名单。"},{"i":238,"n":"第二百三十八条","txt":"审判长应当告知当事人及其法定代理人、辩护人、诉讼代理人在法庭审理过程中依法享有下列诉讼权利："},{"i":239,"n":"第二百三十九条","txt":"审判长应当询问当事人及其法定代理人、辩护人、诉讼代理人是否申请回避、申请何人回避和申请回避的理由。"},{"i":240,"n":"第二百四十条","txt":"审判长宣布法庭调查开始后，应当先由公诉人宣读起诉书；公诉人宣读起诉书后，审判长应当询问被告人对起诉书指控的犯罪事实和罪名有无异议。"},{"i":241,"n":"第二百四十一条","txt":"在审判长主持下，被告人、被害人可以就起诉书指控的犯罪事实分别陈述。"},{"i":242,"n":"第二百四十二条","txt":"在审判长主持下，公诉人可以就起诉书指控的犯罪事实讯问被告人。"},{"i":243,"n":"第二百四十三条","txt":"讯问同案审理的被告人，应当分别进行。"},{"i":244,"n":"第二百四十四条","txt":"经审判长准许，控辩双方可以向被害人、附带民事诉讼原告人发问。"},{"i":245,"n":"第二百四十五条","txt":"必要时，审判人员可以讯问被告人，也可以向被害人、附带民事诉讼当事人发问。"},{"i":246,"n":"第二百四十六条","txt":"公诉人可以提请法庭通知证人、鉴定人、有专门知识的人、调查人员、侦查人员或者其他人员出庭，或者出示证据。被害人及其法定代理人、诉讼代理人，附带民事诉讼原告人及其诉讼代理人也可以提出申请。"},{"i":247,"n":"第二百四十七条","txt":"控辩双方申请证人出庭作证，出示证据，应当说明证据的名称、来源和拟证明的事实。法庭认为有必要的，应当准许；对方提出异议，认为有关证据与案件无关或者明显重复、不必要，法庭经审查异议成立的，可以不予准许。"},{"i":248,"n":"第二百四十八条","txt":"已经移送人民法院的案卷和证据材料，控辩双方需要出示的，可以向法庭提出申请，法庭可以准许。案卷和证据材料应当在质证后当庭归还。"},{"i":249,"n":"第二百四十九条","txt":"公诉人、当事人或者辩护人、诉讼代理人对证人证言有异议，且该证人证言对定罪量刑有重大影响，或者对鉴定意见有异议，人民法院认为证人、鉴定人有必要出庭作证的，应当通知证人、鉴定人出庭。"},{"i":250,"n":"第二百五十条","txt":"公诉人、当事人及其辩护人、诉讼代理人申请法庭通知有专门知识的人出庭，就鉴定意见提出意见的，应当说明理由。法庭认为有必要的，应当通知有专门知识的人出庭。"},{"i":251,"n":"第二百五十一条","txt":"为查明案件事实、调查核实证据，人民法院可以依职权通知证人、鉴定人、有专门知识的人、调查人员、侦查人员或者其他人员出庭。"},{"i":252,"n":"第二百五十二条","txt":"人民法院通知有关人员出庭的，可以要求控辩双方予以协助。"},{"i":253,"n":"第二百五十三条","txt":"证人具有下列情形之一，无法出庭作证的，人民法院可以准许其不出庭："},{"i":254,"n":"第二百五十四条","txt":"证人出庭作证所支出的交通、住宿、就餐等费用，人民法院应当给予补助。"},{"i":255,"n":"第二百五十五条","txt":"强制证人出庭的，应当由院长签发强制证人出庭令，由法警执行。必要时，可以商请公安机关协助。"},{"i":256,"n":"第二百五十六条","txt":"证人、鉴定人、被害人因出庭作证，本人或者其近亲属的人身安全面临危险的，人民法院应当采取不公开其真实姓名、住址和工作单位等个人信息，或者不暴露其外貌、真实声音等保护措施。辩护律师经法庭许可，查阅对证人、鉴定人、被害人使用化名情况的，应当签署保密承诺书。"},{"i":257,"n":"第二百五十七条","txt":"决定对出庭作证的证人、鉴定人、被害人采取不公开个人信息的保护措施的，审判人员应当在开庭前核实其身份，对证人、鉴定人如实作证的保证书不得公开，在判决书、裁定书等法律文书中可以使用化名等代替其个人信息。"},{"i":258,"n":"第二百五十八条","txt":"证人出庭的，法庭应当核实其身份、与当事人以及本案的关系，并告知其有关权利义务和法律责任。证人应当保证向法庭如实提供证言，并在保证书上签名。"},{"i":259,"n":"第二百五十九条","txt":"证人出庭后，一般先向法庭陈述证言；其后，经审判长许可，由申请通知证人出庭的一方发问，发问完毕后，对方也可以发问。"},{"i":260,"n":"第二百六十条","txt":"鉴定人、有专门知识的人、调查人员、侦查人员或者其他人员出庭的，参照适用前两条规定。"},{"i":261,"n":"第二百六十一条","txt":"向证人发问应当遵循以下规则："},{"i":262,"n":"第二百六十二条","txt":"控辩双方的讯问、发问方式不当或者内容与本案无关的，对方可以提出异议，申请审判长制止，审判长应当判明情况予以支持或者驳回；对方未提出异议的，审判长也可以根据情况予以制止。"},{"i":263,"n":"第二百六十三条","txt":"审判人员认为必要时，可以询问证人、鉴定人、有专门知识的人、调查人员、侦查人员或者其他人员。"},{"i":264,"n":"第二百六十四条","txt":"向证人、调查人员、侦查人员发问应当分别进行。"},{"i":265,"n":"第二百六十五条","txt":"证人、鉴定人、有专门知识的人、调查人员、侦查人员或者其他人员不得旁听对本案的审理。有关人员作证或者发表意见后，审判长应当告知其退庭。"},{"i":266,"n":"第二百六十六条","txt":"审理涉及未成年人的刑事案件，询问未成年被害人、证人，通知未成年被害人、证人出庭作证，适用本解释第二十二章的有关规定。"},{"i":267,"n":"第二百六十七条","txt":"举证方当庭出示证据后，由对方发表质证意见。"},{"i":268,"n":"第二百六十八条","txt":"对可能影响定罪量刑的关键证据和控辩双方存在争议的证据，一般应当单独举证、质证，充分听取质证意见。"},{"i":269,"n":"第二百六十九条","txt":"审理过程中，法庭认为有必要的，可以传唤同案被告人、分案审理的共同犯罪或者关联犯罪案件的被告人等到庭对质。"},{"i":270,"n":"第二百七十条","txt":"当庭出示的证据，尚未移送人民法院的，应当在质证后当庭移交。"},{"i":271,"n":"第二百七十一条","txt":"法庭对证据有疑问的，可以告知公诉人、当事人及其法定代理人、辩护人、诉讼代理人补充证据或者作出说明；必要时，可以宣布休庭，对证据进行调查核实。"},{"i":272,"n":"第二百七十二条","txt":"公诉人申请出示开庭前未移送或者提交人民法院的证据，辩护方提出异议的，审判长应当要求公诉人说明理由；理由成立并确有出示必要的，应当准许。"},{"i":273,"n":"第二百七十三条","txt":"法庭审理过程中，控辩双方申请通知新的证人到庭，调取新的证据，申请重新鉴定或者勘验的，应当提供证人的基本信息、证据的存放地点，说明拟证明的事项，申请重新鉴定或者勘验的理由。法庭认为有必要的，应当同意，并宣布休庭；根据案件情况，可以决定延期审理。"},{"i":274,"n":"第二百七十四条","txt":"审判期间，公诉人发现案件需要补充侦查，建议延期审理的，合议庭可以同意，但建议延期审理不得超过两次。"},{"i":275,"n":"第二百七十五条","txt":"人民法院向人民检察院调取需要调查核实的证据材料，或者根据被告人、辩护人的申请，向人民检察院调取在调查、侦查、审查起诉期间收集的有关被告人无罪或者罪轻的证据材料，应当通知人民检察院在收到调取证据材料决定书后三日以内移交。"},{"i":276,"n":"第二百七十六条","txt":"法庭审理过程中，对与量刑有关的事实、证据，应当进行调查。"},{"i":277,"n":"第二百七十七条","txt":"审判期间，合议庭发现被告人可能有自首、坦白、立功等法定量刑情节，而人民检察院移送的案卷中没有相关证据材料的，应当通知人民检察院在指定时间内移送。"},{"i":278,"n":"第二百七十八条","txt":"对被告人认罪的案件，在确认被告人了解起诉书指控的犯罪事实和罪名，自愿认罪且知悉认罪的法律后果后，法庭调查可以主要围绕量刑和其他有争议的问题进行。"},{"i":279,"n":"第二百七十九条","txt":"法庭审理过程中，应当对查封、扣押、冻结财物及其孳息的权属、来源等情况，是否属于违法所得或者依法应当追缴的其他涉案财物进行调查，由公诉人说明情况、出示证据、提出处理建议，并听取被告人、辩护人等诉讼参与人的意见。"},{"i":280,"n":"第二百八十条","txt":"合议庭认为案件事实已经调查清楚的，应当由审判长宣布法庭调查结束，开始就定罪、量刑、涉案财物处理的事实、证据、适用法律等问题进行法庭辩论。"},{"i":281,"n":"第二百八十一条","txt":"法庭辩论应当在审判长的主持下，按照下列顺序进行："},{"i":282,"n":"第二百八十二条","txt":"人民检察院可以提出量刑建议并说明理由；建议判处管制、宣告缓刑的，一般应当附有调查评估报告，或者附有委托调查函。"},{"i":283,"n":"第二百八十三条","txt":"对被告人认罪的案件，法庭辩论时，应当指引控辩双方主要围绕量刑和其他有争议的问题进行。"},{"i":284,"n":"第二百八十四条","txt":"附带民事部分的辩论应当在刑事部分的辩论结束后进行，先由附带民事诉讼原告人及其诉讼代理人发言，后由附带民事诉讼被告人及其诉讼代理人答辩。"},{"i":285,"n":"第二百八十五条","txt":"法庭辩论过程中，审判长应当充分听取控辩双方的意见，对控辩双方与案件无关、重复或者指责对方的发言应当提醒、制止。"},{"i":286,"n":"第二百八十六条","txt":"法庭辩论过程中，合议庭发现与定罪、量刑有关的新的事实，有必要调查的，审判长可以宣布恢复法庭调查，在对新的事实调查后，继续法庭辩论。"},{"i":287,"n":"第二百八十七条","txt":"审判长宣布法庭辩论终结后，合议庭应当保证被告人充分行使最后陈述的权利。"},{"i":288,"n":"第二百八十八条","txt":"被告人在最后陈述中提出新的事实、证据，合议庭认为可能影响正确裁判的，应当恢复法庭调查；被告人提出新的辩解理由，合议庭认为可能影响正确裁判的，应当恢复法庭辩论。"},{"i":289,"n":"第二百八十九条","txt":"公诉人当庭发表与起诉书不同的意见，属于变更、追加、补充或者撤回起诉的，人民法院应当要求人民检察院在指定时间内以书面方式提出；必要时，可以宣布休庭。人民检察院在指定时间内未提出的，人民法院应当根据法庭审理情况，就起诉书指控的犯罪事实依法作出判决、裁定。"},{"i":290,"n":"第二百九十条","txt":"辩护人应当及时将书面辩护意见提交人民法院。"},{"i":291,"n":"第二百九十一条","txt":"被告人最后陈述后，审判长应当宣布休庭，由合议庭进行评议。"},{"i":292,"n":"第二百九十二条","txt":"开庭审理的全部活动，应当由书记员制作笔录；笔录经审判长审阅后，分别由审判长和书记员签名。"},{"i":293,"n":"第二百九十三条","txt":"法庭笔录应当在庭审后交由当事人、法定代理人、辩护人、诉讼代理人阅读或者向其宣读。"},{"i":294,"n":"第二百九十四条","txt":"合议庭评议案件，应当根据已经查明的事实、证据和有关法律规定，在充分考虑控辩双方意见的基础上，确定被告人是否有罪、构成何罪，有无从重、从轻、减轻或者免除处罚情节，应否处以刑罚、判处何种刑罚，附带民事诉讼如何解决，查封、扣押、冻结的财物及其孳息如何处理等，并依法作出判决、裁定。"},{"i":295,"n":"第二百九十五条","txt":"对第一审公诉案件，人民法院审理后，应当按照下列情形分别作出判决、裁定："},{"i":296,"n":"第二百九十六条","txt":"在开庭后、宣告判决前，人民检察院要求撤回起诉的，人民法院应当审查撤回起诉的理由，作出是否准许的裁定。"},{"i":297,"n":"第二百九十七条","txt":"审判期间，人民法院发现新的事实，可能影响定罪量刑的，或者需要补查补证的，应当通知人民检察院，由其决定是否补充、变更、追加起诉或者补充侦查。"},{"i":298,"n":"第二百九十八条","txt":"对依照本解释第二百一十九条第一款第五项规定受理的案件，人民法院应当在判决中写明被告人曾被人民检察院提起公诉，因证据不足，指控的犯罪不能成立，被人民法院依法判决宣告无罪的情况；前案依照刑事诉讼法第二百条第三项规定作出的判决不予撤销。"},{"i":299,"n":"第二百九十九条","txt":"合议庭成员、法官助理、书记员应当在评议笔录上签名，在判决书、裁定书等法律文书上署名。"},{"i":300,"n":"第三百条","txt":"裁判文书应当写明裁判依据，阐释裁判理由，反映控辩双方的意见并说明采纳或者不予采纳的理由。"},{"i":301,"n":"第三百零一条","txt":"庭审结束后、评议前，部分合议庭成员不能继续履行审判职责的，人民法院应当依法更换合议庭组成人员，重新开庭审理。"},{"i":302,"n":"第三百零二条","txt":"当庭宣告判决的，应当在五日以内送达判决书。定期宣告判决的，应当在宣判前，先期公告宣判的时间和地点，传唤当事人并通知公诉人、法定代理人、辩护人和诉讼代理人；判决宣告后，应当立即送达判决书。"},{"i":303,"n":"第三百零三条","txt":"判决书应当送达人民检察院、当事人、法定代理人、辩护人、诉讼代理人，并可以送达被告人的近亲属。被害人死亡，其近亲属申请领取判决书的，人民法院应当及时提供。"},{"i":304,"n":"第三百零四条","txt":"宣告判决，一律公开进行。宣告判决结果时，法庭内全体人员应当起立。"},{"i":305,"n":"第三百零五条","txt":"在押被告人出庭受审时，不着监管机构的识别服。"},{"i":306,"n":"第三百零六条","txt":"庭审期间，全体人员应当服从法庭指挥，遵守法庭纪律，尊重司法礼仪，不得实施下列行为："},{"i":307,"n":"第三百零七条","txt":"有关人员危害法庭安全或者扰乱法庭秩序的，审判长应当按照下列情形分别处理："},{"i":308,"n":"第三百零八条","txt":"担任辩护人、诉讼代理人的律师严重扰乱法庭秩序，被强行带出法庭或者被处以罚款、拘留的，人民法院应当通报司法行政机关，并可以建议依法给予相应处罚。"},{"i":309,"n":"第三百零九条","txt":"实施下列行为之一，危害法庭安全或者扰乱法庭秩序，构成犯罪的，依法追究刑事责任："},{"i":310,"n":"第三百一十条","txt":"辩护人严重扰乱法庭秩序，被责令退出法庭、强行带出法庭或者被处以罚款、拘留，被告人自行辩护的，庭审继续进行；被告人要求另行委托辩护人，或者被告人属于应当提供法律援助情形的，应当宣布休庭。"},{"i":311,"n":"第三百一十一条","txt":"被告人在一个审判程序中更换辩护人一般不得超过两次。"},{"i":312,"n":"第三百一十二条","txt":"法庭审理过程中，辩护人拒绝为被告人辩护，有正当理由的，应当准许；是否继续庭审，参照适用前条规定。"},{"i":313,"n":"第三百一十三条","txt":"依照前两条规定另行委托辩护人或者通知法律援助机构指派律师的，自案件宣布休庭之日起至第十五日止，由辩护人准备辩护，但被告人及其辩护人自愿缩短时间的除外。"},{"i":314,"n":"第三百一十四条","txt":"有多名被告人的案件，部分被告人具有刑事诉讼法第二百零六条第一款规定情形的，人民法院可以对全案中止审理；根据案件情况，也可以对该部分被告人中止审理，对其他被告人继续审理。"},{"i":315,"n":"第三百一十五条","txt":"人民检察院认为人民法院审理案件违反法定程序，在庭审后提出书面纠正意见，人民法院认为正确的，应当采纳。"},{"i":316,"n":"第三百一十六条","txt":"人民法院受理自诉案件必须符合下列条件："},{"i":317,"n":"第三百一十七条","txt":"本解释第一条规定的案件，如果被害人死亡、丧失行为能力或者因受强制、威吓等无法告诉，或者是限制行为能力人以及因年老、患病、盲、聋、哑等不能亲自告诉，其法定代理人、近亲属告诉或者代为告诉的，人民法院应当依法受理。"},{"i":318,"n":"第三百一十八条","txt":"提起自诉应当提交刑事自诉状；同时提起附带民事诉讼的，应当提交刑事附带民事自诉状。"},{"i":319,"n":"第三百一十九条","txt":"自诉状一般应当包括以下内容："},{"i":320,"n":"第三百二十条","txt":"对自诉案件，人民法院应当在十五日以内审查完毕。经审查，符合受理条件的，应当决定立案，并书面通知自诉人或者代为告诉人。"},{"i":321,"n":"第三百二十一条","txt":"对已经立案，经审查缺乏罪证的自诉案件，自诉人提不出补充证据的，人民法院应当说服其撤回起诉或者裁定驳回起诉；自诉人撤回起诉或者被驳回起诉后，又提出了新的足以证明被告人有罪的证据，再次提起自诉的，人民法院应当受理。"},{"i":322,"n":"第三百二十二条","txt":"自诉人对不予受理或者驳回起诉的裁定不服的，可以提起上诉。"},{"i":323,"n":"第三百二十三条","txt":"自诉人明知有其他共同侵害人，但只对部分侵害人提起自诉的，人民法院应当受理，并告知其放弃告诉的法律后果；自诉人放弃告诉，判决宣告后又对其他共同侵害人就同一事实提起自诉的，人民法院不予受理。"},{"i":324,"n":"第三百二十四条","txt":"被告人实施两个以上犯罪行为，分别属于公诉案件和自诉案件，人民法院可以一并审理。对自诉部分的审理，适用本章的规定。"},{"i":325,"n":"第三百二十五条","txt":"自诉案件当事人因客观原因不能取得的证据，申请人民法院调取的，应当说明理由，并提供相关线索或者材料。人民法院认为有必要的，应当及时调取。"},{"i":326,"n":"第三百二十六条","txt":"对犯罪事实清楚，有足够证据的自诉案件，应当开庭审理。"},{"i":327,"n":"第三百二十七条","txt":"自诉案件符合简易程序适用条件的，可以适用简易程序审理。"},{"i":328,"n":"第三百二十八条","txt":"人民法院审理自诉案件，可以在查明事实、分清是非的基础上，根据自愿、合法的原则进行调解。调解达成协议的，应当制作刑事调解书，由审判人员、法官助理、书记员署名，并加盖人民法院印章。调解书经双方当事人签收后，即具有法律效力。调解没有达成协议，或者调解书签收前当事人反悔的，应当及时作出判决。"},{"i":329,"n":"第三百二十九条","txt":"判决宣告前，自诉案件的当事人可以自行和解，自诉人可以撤回自诉。"},{"i":330,"n":"第三百三十条","txt":"裁定准许撤诉的自诉案件，被告人被采取强制措施的，人民法院应当立即解除。"},{"i":331,"n":"第三百三十一条","txt":"自诉人经两次传唤，无正当理由拒不到庭，或者未经法庭准许中途退庭的，人民法院应当裁定按撤诉处理。"},{"i":332,"n":"第三百三十二条","txt":"被告人在自诉案件审判期间下落不明的，人民法院可以裁定中止审理；符合条件的，可以对被告人依法决定逮捕。"},{"i":333,"n":"第三百三十三条","txt":"对自诉案件，应当参照刑事诉讼法第二百条和本解释第二百九十五条的有关规定作出判决。对依法宣告无罪的案件，有附带民事诉讼的，其附带民事部分可以依法进行调解或者一并作出判决，也可以告知附带民事诉讼原告人另行提起民事诉讼。"},{"i":334,"n":"第三百三十四条","txt":"告诉才处理和被害人有证据证明的轻微刑事案件的被告人或者其法定代理人在诉讼过程中，可以对自诉人提起反诉。反诉必须符合下列条件："},{"i":335,"n":"第三百三十五条","txt":"人民法院受理单位犯罪案件，除依照本解释第二百一十八条的有关规定进行审查外，还应当审查起诉书是否列明被告单位的名称、住所地、联系方式，法定代表人、实际控制人、主要负责人以及代表被告单位出庭的诉讼代表人的姓名、职务、联系方式。需要人民检察院补充材料的，应当通知人民检察院在三日以内补送。"},{"i":336,"n":"第三百三十六条","txt":"被告单位的诉讼代表人，应当是法定代表人、实际控制人或者主要负责人；法定代表人、实际控制人或者主要负责人被指控为单位犯罪直接责任人员或者因客观原因无法出庭的，应当由被告单位委托其他负责人或者职工作为诉讼代表人。但是，有关人员被指控为单位犯罪直接责任人员或者知道案件情况、负有作证义务的除外。"},{"i":337,"n":"第三百三十七条","txt":"开庭审理单位犯罪案件，应当通知被告单位的诉讼代表人出庭；诉讼代表人不符合前条规定的，应当要求人民检察院另行确定。"},{"i":338,"n":"第三百三十八条","txt":"被告单位的诉讼代表人享有刑事诉讼法规定的有关被告人的诉讼权利。开庭时，诉讼代表人席位置于审判台前左侧，与辩护人席并列。"},{"i":339,"n":"第三百三十九条","txt":"被告单位委托辩护人的，参照适用本解释的有关规定。"},{"i":340,"n":"第三百四十条","txt":"对应当认定为单位犯罪的案件，人民检察院只作为自然人犯罪起诉的，人民法院应当建议人民检察院对犯罪单位追加起诉。人民检察院仍以自然人犯罪起诉的，人民法院应当依法审理，按照单位犯罪直接负责的主管人员或者其他直接责任人员追究刑事责任，并援引刑法分则关于追究单位犯罪中直接负责的主管人员和其他直接责任人员刑事责任的条款。"},{"i":341,"n":"第三百四十一条","txt":"被告单位的违法所得及其他涉案财物，尚未被依法追缴或者查封、扣押、冻结的，人民法院应当决定追缴或者查封、扣押、冻结。"},{"i":342,"n":"第三百四十二条","txt":"为保证判决的执行，人民法院可以先行查封、扣押、冻结被告单位的财产，或者由被告单位提出担保。"},{"i":343,"n":"第三百四十三条","txt":"采取查封、扣押、冻结等措施，应当严格依照法定程序进行，最大限度降低对被告单位正常生产经营活动的影响。"},{"i":344,"n":"第三百四十四条","txt":"审判期间，被告单位被吊销营业执照、宣告破产但尚未完成清算、注销登记的，应当继续审理；被告单位被撤销、注销的，对单位犯罪直接负责的主管人员和其他直接责任人员应当继续审理。"},{"i":345,"n":"第三百四十五条","txt":"审判期间，被告单位合并、分立的，应当将原单位列为被告单位，并注明合并、分立情况。对被告单位所判处的罚金以其在新单位的财产及收益为限。"},{"i":346,"n":"第三百四十六条","txt":"审理单位犯罪案件，本章没有规定的，参照适用本解释的有关规定。"},{"i":347,"n":"第三百四十七条","txt":"刑事诉讼法第十五条规定的“认罪”，是指犯罪嫌疑人、被告人自愿如实供述自己的罪行，对指控的犯罪事实没有异议。"},{"i":348,"n":"第三百四十八条","txt":"对认罪认罚案件，应当根据案件情况，依法适用速裁程序、简易程序或者普通程序审理。"},{"i":349,"n":"第三百四十九条","txt":"对人民检察院提起公诉的认罪认罚案件，人民法院应当重点审查以下内容："},{"i":350,"n":"第三百五十条","txt":"人民法院应当将被告人认罪认罚作为其是否具有社会危险性的重要考虑因素。被告人罪行较轻，采用非羁押性强制措施足以防止发生社会危险性的，应当依法适用非羁押性强制措施。"},{"i":351,"n":"第三百五十一条","txt":"对认罪认罚案件，法庭审理时应当告知被告人享有的诉讼权利和认罪认罚的法律规定，审查认罪认罚的自愿性和认罪认罚具结书内容的真实性、合法性。"},{"i":352,"n":"第三百五十二条","txt":"对认罪认罚案件，人民检察院起诉指控的事实清楚，但指控的罪名与审理认定的罪名不一致的，人民法院应当听取人民检察院、被告人及其辩护人对审理认定罪名的意见，依法作出判决。"},{"i":353,"n":"第三百五十三条","txt":"对认罪认罚案件，人民法院经审理认为量刑建议明显不当，或者被告人、辩护人对量刑建议提出异议的，人民检察院可以调整量刑建议。人民检察院不调整或者调整后仍然明显不当的，人民法院应当依法作出判决。"},{"i":354,"n":"第三百五十四条","txt":"对量刑建议是否明显不当，应当根据审理认定的犯罪事实、认罪认罚的具体情况，结合相关犯罪的法定刑、类似案件的刑罚适用等作出审查判断。"},{"i":355,"n":"第三百五十五条","txt":"对认罪认罚案件，人民法院一般应当对被告人从轻处罚；符合非监禁刑适用条件的，应当适用非监禁刑；具有法定减轻处罚情节的，可以减轻处罚。"},{"i":356,"n":"第三百五十六条","txt":"被告人在人民检察院提起公诉前未认罪认罚，在审判阶段认罪认罚的，人民法院可以不再通知人民检察院提出或者调整量刑建议。"},{"i":357,"n":"第三百五十七条","txt":"对被告人在第一审程序中未认罪认罚，在第二审程序中认罪认罚的案件，应当根据其认罪认罚的具体情况决定是否从宽，并依法作出裁判。确定从宽幅度时应当与第一审程序认罪认罚有所区别。"},{"i":358,"n":"第三百五十八条","txt":"案件审理过程中，被告人不再认罪认罚的，人民法院应当根据审理查明的事实，依法作出裁判。需要转换程"},{"i":359,"n":"第三百五十九条","txt":"基层人民法院受理公诉案件后，经审查认为案件事实清楚、证据充分的，在将起诉书副本送达被告人时，应当询问被告人对指控的犯罪事实的意见，告知其适用简易程序的法律规定。被告人对指控的犯罪事实没有异议并同意适用简易程序的，可以决定适用简易程序，并在开庭前通知人民检察院和辩护人。"},{"i":360,"n":"第三百六十条","txt":"具有下列情形之一的，不适用简易程序："},{"i":361,"n":"第三百六十一条","txt":"适用简易程序审理的案件，符合刑事诉讼法第三十五条第一款规定的，人民法院应当告知被告人及其近亲属可以申请法律援助。"},{"i":362,"n":"第三百六十二条","txt":"适用简易程序审理案件，人民法院应当在开庭前将开庭的时间、地点通知人民检察院、自诉人、被告人、辩护人，也可以通知其他诉讼参与人。"},{"i":363,"n":"第三百六十三条","txt":"适用简易程序审理案件，被告人有辩护人的，应当通知其出庭。"},{"i":364,"n":"第三百六十四条","txt":"适用简易程序审理案件，审判长或者独任审判员应当当庭询问被告人对指控的犯罪事实的意见，告知被告人适用简易程序审理的法律规定，确认被告人是否同意适用简易程序。"},{"i":365,"n":"第三百六十五条","txt":"适用简易程序审理案件，可以对庭审作如下简化："},{"i":366,"n":"第三百六十六条","txt":"适用简易程序独任审判过程中，发现对被告人可能判处的有期徒刑超过三年的，应当转由合议庭审理。"},{"i":367,"n":"第三百六十七条","txt":"适用简易程序审理案件，裁判文书可以简化。"},{"i":368,"n":"第三百六十八条","txt":"适用简易程序审理案件，在法庭审理过程中，具有下列情形之一的，应当转为普通程序审理："},{"i":369,"n":"第三百六十九条","txt":"对人民检察院在提起公诉时建议适用速裁程序的案件，基层人民法院经审查认为案件事实清楚，证据确实、充分，可能判处三年有期徒刑以下刑罚的，在将起诉书副本送达被告人时，应当告知被告人适用速裁程序的法律规定，询问其是否同意适用速裁程序。被告人同意适用速裁程序的，可以决定适用速裁程序，并在开庭前通知人民检察院和辩护人。"},{"i":370,"n":"第三百七十条","txt":"具有下列情形之一的，不适用速裁程序："},{"i":371,"n":"第三百七十一条","txt":"适用速裁程序审理案件，人民法院应当在开庭前将开庭的时间、地点通知人民检察院、被告人、辩护人，也可以通知其他诉讼参与人。"},{"i":372,"n":"第三百七十二条","txt":"适用速裁程序审理案件，可以集中开庭，逐案审理。公诉人简要宣读起诉书后，审判人员应当当庭询问被告人对指控事实、证据、量刑建议以及适用速裁程序的意见，核实具结书签署的自愿性、真实性、合法性，并核实附带民事诉讼赔偿等情况。"},{"i":373,"n":"第三百七十三条","txt":"适用速裁程序审理案件，一般不进行法庭调查、法庭辩论，但在判决宣告前应当听取辩护人的意见和被告人的最后陈述。"},{"i":374,"n":"第三百七十四条","txt":"适用速裁程序审理案件，裁判文书可以简化。"},{"i":375,"n":"第三百七十五条","txt":"适用速裁程序审理案件，在法庭审理过程中，具有下列情形之一的，应当转为普通程序或者简易程序审理："},{"i":376,"n":"第三百七十六条","txt":"决定转为普通程序或者简易程序审理的案件，审理期限应当从作出决定之日起计算。"},{"i":377,"n":"第三百七十七条","txt":"适用速裁程序审理的案件，第二审人民法院依照刑事诉讼法第二百三十六条第一款第三项的规定发回原审人民法院重新审判的，原审人民法院应当适用第一审普通程序重新审判。"},{"i":378,"n":"第三百七十八条","txt":"地方各级人民法院在宣告第一审判决、裁定时，应当告知被告人、自诉人及其法定代理人不服判决和准许撤回起诉、终止审理等裁定的，有权在法定期限内以书面或者口头形式，通过本院或者直接向上一级人民法院提出上诉；被告人的辩护人、近亲属经被告人同意，也可以提出上诉；附带民事诉讼当事人及其法定代理人，可以对判决、裁定中的附带民事部分提出上诉。"},{"i":379,"n":"第三百七十九条","txt":"人民法院受理的上诉案件，一般应当有上诉状正本及副本。"},{"i":380,"n":"第三百八十条","txt":"上诉、抗诉必须在法定期限内提出。不服判决的上诉、抗诉的期限为十日；不服裁定的上诉、抗诉的期限为五日。上诉、抗诉的期限，从接到判决书、裁定书的第二日起计算。"},{"i":381,"n":"第三百八十一条","txt":"上诉人通过第一审人民法院提出上诉的，第一审人民法院应当审查。上诉符合法律规定的，应当在上诉期满后三日以内将上诉状连同案卷、证据移送上一级人民法院，并将上诉状副本送交同级人民检察院和对方当事人。"},{"i":382,"n":"第三百八十二条","txt":"上诉人直接向第二审人民法院提出上诉的，第二审人民法院应当在收到上诉状后三日以内将上诉状交第一审人民法院。第一审人民法院应当审查上诉是否符合法律规定。符合法律规定的，应当在接到上诉状后三日以内将上诉状连同案卷、证据移送上一级人民法院，并将上诉状副本送交同级人民检察院和对方当事人。"},{"i":383,"n":"第三百八十三条","txt":"上诉人在上诉期限内要求撤回上诉的，人民法院应当准许。"},{"i":384,"n":"第三百八十四条","txt":"地方各级人民检察院对同级人民法院第一审判决、裁定的抗诉，应当通过第一审人民法院提交抗诉书。第一审人民法院应当在抗诉期满后三日以内将抗诉书连同案卷、证据移送上一级人民法院，并将抗诉书副本送交当事人。"},{"i":385,"n":"第三百八十五条","txt":"人民检察院在抗诉期限内要求撤回抗诉的，人民法院应当准许。"},{"i":386,"n":"第三百八十六条","txt":"在上诉、抗诉期满前撤回上诉、抗诉的，第一审判决、裁定在上诉、抗诉期满之日起生效。在上诉、抗诉期满后要求撤回上诉、抗诉，第二审人民法院裁定准许的，第一审判决、裁定应当自第二审裁定书送达上诉人或者抗诉机关之日起生效。"},{"i":387,"n":"第三百八十七条","txt":"第二审人民法院对第一审人民法院移送的上诉、抗诉案卷、证据，应当审查是否包括下列内容："},{"i":388,"n":"第三百八十八条","txt":"第二审人民法院审理上诉、抗诉案件，应当就第一审判决、裁定认定的事实和适用法律进行全面审查，不受上诉、抗诉范围的限制。"},{"i":389,"n":"第三百八十九条","txt":"共同犯罪案件，只有部分被告人提出上诉，或者自诉人只对部分被告人的判决提出上诉，或者人民检察院只对部分被告人的判决提出抗诉的，第二审人民法院应当对全案进行审查，一并处理。"},{"i":390,"n":"第三百九十条","txt":"共同犯罪案件，上诉的被告人死亡，其他被告人未上诉的，第二审人民法院应当对死亡的被告人终止审理；但有证据证明被告人无罪，经缺席审理确认无罪的，应当判决宣告被告人无罪。"},{"i":391,"n":"第三百九十一条","txt":"对上诉、抗诉案件，应当着重审查下列内容："},{"i":392,"n":"第三百九十二条","txt":"第二审期间，被告人除自行辩护外，还可以继续委托第一审辩护人或者另行委托辩护人辩护。"},{"i":393,"n":"第三百九十三条","txt":"下列案件，根据刑事诉讼法第二百三十四条的规定，应当开庭审理："},{"i":394,"n":"第三百九十四条","txt":"对上诉、抗诉案件，第二审人民法院经审查，认为原判事实不清、证据不足，或者具有刑事诉讼法第二百三十八条规定的违反法定诉讼程序情形，需要发回重新审判的，可以不开庭审理。"},{"i":395,"n":"第三百九十五条","txt":"第二审期间，人民检察院或者被告人及其辩护人提交新证据的，人民法院应当及时通知对方查阅、摘抄或者复制。"},{"i":396,"n":"第三百九十六条","txt":"开庭审理第二审公诉案件，应当在决定开庭审理后及时通知人民检察院查阅案卷。自通知后的第二日起，人民检察院查阅案卷的时间不计入审理期限。"},{"i":397,"n":"第三百九十七条","txt":"开庭审理上诉、抗诉的公诉案件，应当通知同级人民检察院派员出庭。"},{"i":398,"n":"第三百九十八条","txt":"开庭审理上诉、抗诉案件，除参照适用第一审程序的有关规定外，应当按照下列规定进行："},{"i":399,"n":"第三百九十九条","txt":"开庭审理上诉、抗诉案件，可以重点围绕对第一审判决、裁定有争议的问题或者有疑问的部分进行。根据案件情况，可以按照下列方式审理："},{"i":400,"n":"第四百条","txt":"第二审案件依法不开庭审理的，应当讯问被告人，听取其他当事人、辩护人、诉讼代理人的意见。合议庭全体成员应当阅卷，必要时应当提交书面阅卷意见。"},{"i":401,"n":"第四百零一条","txt":"审理被告人或者其法定代理人、辩护人、近亲属提出上诉的案件，不得对被告人的刑罚作出实质不利的改判，并应当执行下列规定："},{"i":402,"n":"第四百零二条","txt":"人民检察院只对部分被告人的判决提出抗诉，或者自诉人只对部分被告人的判决提出上诉的，第二审人民法院不得对其他同案被告人加重刑罚。"},{"i":403,"n":"第四百零三条","txt":"被告人或者其法定代理人、辩护人、近亲属提出上诉，人民检察院未提出抗诉的案件，第二审人民法院发回重新审判后，除有新的犯罪事实且人民检察院补充起诉的以外，原审人民法院不得加重被告人的刑罚。"},{"i":404,"n":"第四百零四条","txt":"第二审人民法院认为第一审判决事实不清、证据不足的，可以在查清事实后改判，也可以裁定撤销原判，发回原审人民法院重新审判。"},{"i":405,"n":"第四百零五条","txt":"原判事实不清、证据不足，第二审人民法院发回重新审判的案件，原审人民法院重新作出判决后，被告人上诉或者人民检察院抗诉的，第二审人民法院应当依法作出判决、裁定，不得再发回重新审判。"},{"i":406,"n":"第四百零六条","txt":"第二审人民法院发现原审人民法院在重新审判过程中，有刑事诉讼法第二百三十八条规定的情形之一，或者违反第二百三十九条规定的，应当裁定撤销原判，发回重新审判。"},{"i":407,"n":"第四百零七条","txt":"第二审人民法院审理对刑事部分提出上诉、抗诉，附带民事部分已经发生法律效力的案件，发现第一审判决、裁定中的附带民事部分确有错误的，应当依照审判监督程序对附带民事部分予以纠正。"},{"i":408,"n":"第四百零八条","txt":"刑事附带民事诉讼案件，只有附带民事诉讼当事人及其法定代理人上诉的，第一审刑事部分的判决在上诉期满后即发生法律效力。"},{"i":409,"n":"第四百零九条","txt":"第二审人民法院审理对附带民事部分提出上诉，刑事部分已经发生法律效力的案件，应当对全案进行审查，并按照下列情形分别处理："},{"i":410,"n":"第四百一十条","txt":"第二审期间，第一审附带民事诉讼原告人增加独立的诉讼请求或者第一审附带民事诉讼被告人提出反诉的，第二审人民法院可以根据自愿、合法的原则进行调解；调解不成的，告知当事人另行起诉。"},{"i":411,"n":"第四百一十一条","txt":"对第二审自诉案件，必要时可以调解，当事人也可以自行和解。调解结案的，应当制作调解书，第一审判决、裁定视为自动撤销。当事人自行和解的，依照本解释第三百二十九条的规定处理；裁定准许撤回自诉的，应当撤销第一审判决、裁定。"},{"i":412,"n":"第四百一十二条","txt":"第二审期间，自诉案件的当事人提出反诉的，应当告知其另行起诉。"},{"i":413,"n":"第四百一十三条","txt":"第二审人民法院可以委托第一审人民法院代为宣判，并向当事人送达第二审判决书、裁定书。第一审人民法院应当在代为宣判后五日以内将宣判笔录送交第二审人民法院，并在送达完毕后及时将送达回证送交第二审人民法院。"},{"i":414,"n":"第四百一十四条","txt":"报请最高人民法院核准在法定刑以下判处刑罚的案件，应当按照下列情形分别处理："},{"i":415,"n":"第四百一十五条","txt":"对符合刑法第六十三条第二款规定的案件，第一审人民法院未在法定刑以下判处刑罚的，第二审人民法院可以在法定刑以下判处刑罚，并层报最高人民法院核准。"},{"i":416,"n":"第四百一十六条","txt":"报请最高人民法院核准在法定刑以下判处刑罚的案件，应当报送判决书、报请核准的报告各五份，以及全部案卷、证据。"},{"i":417,"n":"第四百一十七条","txt":"对在法定刑以下判处刑罚的案件，最高人民法院予以核准的，应当作出核准裁定书；不予核准的，应当作出不核准裁定书，并撤销原判决、裁定，发回原审人民法院重新审判或者指定其他下级人民法院重新审判。"},{"i":418,"n":"第四百一十八条","txt":"依照本解释第四百一十四条、第四百一十七条规定发回第二审人民法院重新审判的案件，第二审人民法院可以直接改判；必须通过开庭查清事实、核实证据或者纠正原审程序违法的，应当开庭审理。"},{"i":419,"n":"第四百一十九条","txt":"最高人民法院和上级人民法院复核在法定刑以下判处刑罚案件的审理期限，参照适用刑事诉讼法第二百四十三条的规定。"},{"i":420,"n":"第四百二十条","txt":"报请最高人民法院核准因罪犯具有特殊情况，不受执行刑期限制的假释案件，应当按照下列情形分别处理："},{"i":421,"n":"第四百二十一条","txt":"报请最高人民法院核准因罪犯具有特殊情况，不受执行刑期限制的假释案件，应当报送报请核准的报告、罪犯具有特殊情况的报告、假释裁定书各五份，以及全部案卷。"},{"i":422,"n":"第四百二十二条","txt":"对因罪犯具有特殊情况，不受执行刑期限制的假释案件，最高人民法院予以核准的，应当作出核准裁定书；不予核准的，应当作出不核准裁定书，并撤销原裁定。"},{"i":423,"n":"第四百二十三条","txt":"报请最高人民法院核准死刑的案件，应当按照下列情形分别处理："},{"i":424,"n":"第四百二十四条","txt":"中级人民法院判处死刑缓期执行的第一审案件，被告人未上诉、人民检察院未抗诉的，应当报请高级人民法院核准。"},{"i":425,"n":"第四百二十五条","txt":"报请复核的死刑、死刑缓期执行案件，应当一案一报。报送的材料包括报请复核的报告，第一、二审裁判文书，案件综合报告各五份以及全部案卷、证据。案件综合报告，第一、二审裁判文书和审理报告应当附送电子文本。"},{"i":426,"n":"第四百二十六条","txt":"报请复核死刑、死刑缓期执行的报告，应当写明案由、简要案情、审理过程和判决结果。"},{"i":427,"n":"第四百二十七条","txt":"复核死刑、死刑缓期执行案件，应当全面审查以下内容："},{"i":428,"n":"第四百二十八条","txt":"高级人民法院复核死刑缓期执行案件，应当按照下列情形分别处理："},{"i":429,"n":"第四百二十九条","txt":"最高人民法院复核死刑案件，应当按照下列情形分别处理："},{"i":430,"n":"第四百三十条","txt":"最高人民法院裁定不予核准死刑的，根据案件情况，可以发回第二审人民法院或者第一审人民法院重新审判。"},{"i":431,"n":"第四百三十一条","txt":"高级人民法院依照复核程序审理后报请最高人民法院核准死刑，最高人民法院裁定不予核准，发回高级人民法院重新审判的，高级人民法院可以依照第二审程序提审或者发回重新审判。"},{"i":432,"n":"第四百三十二条","txt":"最高人民法院裁定不予核准死刑，发回重新审判的案件，原审人民法院应当另行组成合议庭审理，但本解释第四百二十九条第四项、第五项规定的案件除外。"},{"i":433,"n":"第四百三十三条","txt":"依照本解释第四百三十条、第四百三十一条发回重新审判的案件，第一审人民法院判处死刑、死刑缓期执行的，上一级人民法院依照第二审程序或者复核程序审理后，应当依法作出判决或者裁定，不得再发回重新审判。但是，第一审人民法院有刑事诉讼法第二百三十八条规定的情形或者违反刑事诉讼法第二百三十九条规定的除外。"},{"i":434,"n":"第四百三十四条","txt":"死刑复核期间，辩护律师要求当面反映意见的，最高人民法院有关合议庭应当在办公场所听取其意见，并制作笔录；辩护律师提出书面意见的，应当附卷。"},{"i":435,"n":"第四百三十五条","txt":"死刑复核期间，最高人民检察院提出意见的，最高人民法院应当审查，并将采纳情况及理由反馈最高人民检察院。"},{"i":436,"n":"第四百三十六条","txt":"最高人民法院应当根据有关规定向最高人民检察院通报死刑案件复核结果。"},{"i":437,"n":"第四百三十七条","txt":"人民法院对查封、扣押、冻结的涉案财物及其孳息，应当妥善保管，并制作清单，附卷备查；对人民检察院随案移送的实物，应当根据清单核查后妥善保管。任何单位和个人不得挪用或者自行处理。"},{"i":438,"n":"第四百三十八条","txt":"对被害人的合法财产，权属明确的，应当依法及时返还，但须经拍照、鉴定、估价，并在案卷中注明返还的理由，将原物照片、清单和被害人的领取手续附卷备查；权属不明的，应当在人民法院判决、裁定生效后，按比例返还被害人，但已获退赔的部分应予扣除。"},{"i":439,"n":"第四百三十九条","txt":"审判期间，对不宜长期保存、易贬值或者市场价格波动大的财产，或者有效期即将届满的票据等，经权利人申请或者同意，并经院长批准，可以依法先行处置，所得款项由人民法院保管。"},{"i":440,"n":"第四百四十条","txt":"对作为证据使用的实物，应当随案移送。第一审判决、裁定宣告后，被告人上诉或者人民检察院抗诉的，第一审人民法院应当将上述证据移送第二审人民法院。"},{"i":441,"n":"第四百四十一条","txt":"对实物未随案移送的，应当根据情况，分别审查以下内容："},{"i":442,"n":"第四百四十二条","txt":"法庭审理过程中，应当依照本解释第二百七十九条的规定，依法对查封、扣押、冻结的财物及其孳息进行审查。"},{"i":443,"n":"第四百四十三条","txt":"被告人将依法应当追缴的涉案财物用于投资或者置业的，对因此形成的财产及其收益，应当追缴。"},{"i":444,"n":"第四百四十四条","txt":"对查封、扣押、冻结的财物及其孳息，应当在判决书中写明名称、金额、数量、存放地点及其处理方式等。涉案财物较多，不宜在判决主文中详细列明的，可以附清单。"},{"i":445,"n":"第四百四十五条","txt":"查封、扣押、冻结的财物及其孳息，经审查，确属违法所得或者依法应当追缴的其他涉案财物的，应当判决返还被害人，或者没收上缴国库，但法律另有规定的除外。"},{"i":446,"n":"第四百四十六条","txt":"第二审期间，发现第一审判决未对随案移送的涉案财物及其孳息作出处理的，可以裁定撤销原判，发回原审人民法院重新审判，由原审人民法院依法对涉案财物及其孳息一并作出处理。"},{"i":447,"n":"第四百四十七条","txt":"随案移送的或者人民法院查封、扣押的财物及其孳息，由第一审人民法院在判决生效后负责处理。"},{"i":448,"n":"第四百四十八条","txt":"对冻结的存款、汇款、债券、股票、基金份额等财产判决没收的，第一审人民法院应当在判决生效后，将判决书、裁定书送达相关金融机构和财政部门，通知相关金融机构依法上缴国库并在接到执行通知书后十五日以内，将上缴国库的凭证、执行回单送回。"},{"i":449,"n":"第四百四十九条","txt":"查封、扣押、冻结的财物与本案无关但已列入清单的，应当由查封、扣押、冻结机关依法处理。"},{"i":450,"n":"第四百五十条","txt":"查封、扣押、冻结财物及其处理，本解释没有规定的，参照适用其他司法解释的有关规定。"},{"i":451,"n":"第四百五十一条","txt":"当事人及其法定代理人、近亲属对已经发生法律效力的判决、裁定提出申诉的，人民法院应当审查处理。"},{"i":452,"n":"第四百五十二条","txt":"向人民法院申诉，应当提交以下材料："},{"i":453,"n":"第四百五十三条","txt":"申诉由终审人民法院审查处理。但是，第二审人民法院裁定准许撤回上诉的案件，申诉人对第一审判决提出申诉的，可以由第一审人民法院审查处理。"},{"i":454,"n":"第四百五十四条","txt":"最高人民法院或者上级人民法院可以指定终审人民法院以外的人民法院对申诉进行审查。被指定的人民法院审查后，应当制作审查报告，提出处理意见，层报最高人民法院或者上级人民法院审查处理。"},{"i":455,"n":"第四百五十五条","txt":"对死刑案件的申诉，可以由原核准的人民法院直接审查处理，也可以交由原审人民法院审查。原审人民法院应当制作审查报告，提出处理意见，层报原核准的人民法院审查处理。"},{"i":456,"n":"第四百五十六条","txt":"对立案审查的申诉案件，人民法院可以听取当事人和原办案单位的意见，也可以对原判据以定罪量刑的证据和新的证据进行核实。必要时，可以进行听证。"},{"i":457,"n":"第四百五十七条","txt":"对立案审查的申诉案件，应当在三个月以内作出决定，至迟不得超过六个月。因案件疑难、复杂、重大或者其他特殊原因需要延长审查期限的，参照本解释第二百一十条的规定处理。"},{"i":458,"n":"第四百五十八条","txt":"具有下列情形之一，可能改变原判决、裁定据以定罪量刑的事实的证据，应当认定为刑事诉讼法第二百五十三条第一项规定的“新的证据”："},{"i":459,"n":"第四百五十九条","txt":"申诉人对驳回申诉不服的，可以向上一级人民法院申诉。上一级人民法院经审查认为申诉不符合刑事诉讼法第二百五十三条和本解释第四百五十七条第二款规定的，应当说服申诉人撤回申诉；对仍然坚持申诉的，应当驳回或者通知不予重新审判。"},{"i":460,"n":"第四百六十条","txt":"各级人民法院院长发现本院已经发生法律效力的判决、裁定确有错误的，应当提交审判委员会讨论决定是否再审。"},{"i":461,"n":"第四百六十一条","txt":"上级人民法院发现下级人民法院已经发生法律效力的判决、裁定确有错误的，可以指令下级人民法院再审；原判决、裁定认定事实正确但适用法律错误，或者案件疑难、复杂、重大，或者有不宜由原审人民法院审理情形的，也可以提审。"},{"i":462,"n":"第四百六十二条","txt":"对人民检察院依照审判监督程序提出抗诉的案件，人民法院应当在收到抗诉书后一个月以内立案。但是，有下列情形之一的，应当区别情况予以处理："},{"i":463,"n":"第四百六十三条","txt":"对人民检察院依照审判监督程序提出抗诉的案件，接受抗诉的人民法院应当组成合议庭审理。对原判事实不清、证据不足，包括有新的证据证明原判可能有错误，需要指令下级人民法院再审的，应当在立案之日起一个月以内作出决定，并将指令再审决定书送达抗诉的人民检察院。"},{"i":464,"n":"第四百六十四条","txt":"对决定依照审判监督程序重新审判的案件，人民法院应当制作再审决定书。再审期间不停止原判决、裁定的执行，但被告人可能经再审改判无罪，或者可能经再审减轻原判刑罚而致刑期届满的，可以决定中止原判决、裁定的执行，必要时，可以对被告人采取取保候审、监视居住措施。"},{"i":465,"n":"第四百六十五条","txt":"依照审判监督程序重新审判的案件，人民法院应当重点针对申诉、抗诉和决定再审的理由进行审理。必要时，应当对原判决、裁定认定的事实、证据和适用法律进行全面审查。"},{"i":466,"n":"第四百六十六条","txt":"原审人民法院审理依照审判监督程序重新审判的案件，应当另行组成合议庭。"},{"i":467,"n":"第四百六十七条","txt":"对依照审判监督程序重新审判的案件，人民法院在依照第一审程序进行审判的过程中，发现原审被告人还有其他犯罪的，一般应当并案审理，但分案审理更为适宜的，可以分案审理。"},{"i":468,"n":"第四百六十八条","txt":"开庭审理再审案件，再审决定书或者抗诉书只针对部分原审被告人，其他同案原审被告人不出庭不影响审理的，可以不出庭参加诉讼。"},{"i":469,"n":"第四百六十九条","txt":"除人民检察院抗诉的以外，再审一般不得加重原审被告人的刑罚。再审决定书或者抗诉书只针对部分原审被告人的，不得加重其他同案原审被告人的刑罚。"},{"i":470,"n":"第四百七十条","txt":"人民法院审理人民检察院抗诉的再审案件，人民检察院在开庭审理前撤回抗诉的，应当裁定准许；人民检察院接到出庭通知后不派员出庭，且未说明原因的，可以裁定按撤回抗诉处理，并通知诉讼参与人。"},{"i":471,"n":"第四百七十一条","txt":"开庭审理的再审案件，系人民法院决定再审的，由合议庭组成人员宣读再审决定书；系人民检察院抗诉的，由检察员宣读抗诉书；系申诉人申诉的，由申诉人或者其辩护人、诉讼代理人陈述申诉理由。"},{"i":472,"n":"第四百七十二条","txt":"再审案件经过重新审理后，应当按照下列情形分别处理："},{"i":473,"n":"第四百七十三条","txt":"原判决、裁定认定被告人姓名等身份信息有误，但认定事实和适用法律正确、量刑适当的，作出生效判决、裁定的人民法院可以通过裁定对有关信息予以更正。"},{"i":474,"n":"第四百七十四条","txt":"对再审改判宣告无罪并依法享有申请国家赔偿权利的当事人，人民法院宣判时，应当告知其在判决发生法律效力后可以依法申请国家赔偿。"},{"i":475,"n":"第四百七十五条","txt":"本解释所称的涉外刑事案件是指："},{"i":476,"n":"第四百七十六条","txt":"第一审涉外刑事案件，除刑事诉讼法第二十一条至第二十三条规定的以外，由基层人民法院管辖。必要时，中级人民法院可以指定辖区内若干基层人民法院集中管辖第一审涉外刑事案件，也可以依照刑事诉讼法第二十四条的规定，审理基层人民法院管辖的第一审涉外刑事案件。"},{"i":477,"n":"第四百七十七条","txt":"外国人的国籍，根据其入境时持用的有效证件确认；国籍不明的，根据公安机关或者有关国家驻华使领馆出具的证明确认。"},{"i":478,"n":"第四百七十八条","txt":"在刑事诉讼中，外国籍当事人享有我国法律规定的诉讼权利并承担相应义务。"},{"i":479,"n":"第四百七十九条","txt":"涉外刑事案件审判期间，人民法院应当将下列事项及时通报同级人民政府外事主管部门，并依照有关规定通知有关国家驻华使领馆："},{"i":480,"n":"第四百八十条","txt":"需要向有关国家驻华使领馆通知有关事项的，应当层报高级人民法院，由高级人民法院按照下列规定通知："},{"i":481,"n":"第四百八十一条","txt":"人民法院受理涉外刑事案件后，应当告知在押的外国籍被告人享有与其国籍国驻华使领馆联系，与其监护人、近亲属会见、通信，以及请求人民法院提供翻译的权利。"},{"i":482,"n":"第四百八十二条","txt":"涉外刑事案件审判期间，外国籍被告人在押，其国籍国驻华使领馆官员要求探视的，可以向受理案件的人民法院所在地的高级人民法院提出。人民法院应当根据我国与被告人国籍国签订的双边领事条约规定的时限予以安排；没有条约规定的，应当尽快安排。必要时，可以请人民政府外事主管部门协助。"},{"i":483,"n":"第四百八十三条","txt":"人民法院审理涉外刑事案件，应当公开进行，但依法不应公开审理的除外。"},{"i":484,"n":"第四百八十四条","txt":"人民法院审判涉外刑事案件，使用中华人民共和国通用的语言、文字，应当为外国籍当事人提供翻译。翻译人员应当在翻译文件上签名。"},{"i":485,"n":"第四百八十五条","txt":"外国籍被告人委托律师辩护，或者外国籍附带民事诉讼原告人、自诉人委托律师代理诉讼的，应当委托具有中华人民共和国律师资格并依法取得执业证书的律师。"},{"i":486,"n":"第四百八十六条","txt":"外国籍当事人从中华人民共和国领域外寄交或者托交给中国律师或者中国公民的委托书，以及外国籍当事人的监护人、近亲属提供的与当事人关系的证明，必须经所在国公证机关证明，所在国中央外交主管机关或者其授权机关认证，并经中华人民共和国驻该国使领馆认证，或者履行中华人民共和国与该所在国订立的有关条约中规定的证明手续，但我国与该国之间有互免认证协定的除外。"},{"i":487,"n":"第四百八十七条","txt":"对涉外刑事案件的被告人，可以决定限制出境；对开庭审理案件时必须到庭的证人，可以要求暂缓出境。限制外国人出境的，应当通报同级人民政府外事主管部门和当事人国籍国驻华使领馆。"},{"i":488,"n":"第四百八十八条","txt":"涉外刑事案件，符合刑事诉讼法第二百零八条第一款、第二百四十三条规定的，经有关人民法院批准或者决定，可以延长审理期限。"},{"i":489,"n":"第四百八十九条","txt":"涉外刑事案件宣判后，外国籍当事人国籍国驻华使领馆要求提供裁判文书的，可以向受理案件的人民法院所在地的高级人民法院提出，人民法院可以提供。"},{"i":490,"n":"第四百九十条","txt":"涉外刑事案件审理过程中的其他事项，依照法律、司法解释和其他有关规定办理。"},{"i":491,"n":"第四百九十一条","txt":"请求和提供司法协助，应当依照《中华人民共和国国际刑事司法协助法》、我国与有关国家、地区签订的刑事司法协助条约、移管被判刑人条约和有关法律规定进行。"},{"i":492,"n":"第四百九十二条","txt":"外国法院请求的事项有损中华人民共和国的主权、安全、社会公共利益以及违反中华人民共和国法律的基本原则的，人民法院不予协助；属于有关法律规定的可以拒绝提供刑事司法协助情形的，可以不予协助。"},{"i":493,"n":"第四百九十三条","txt":"人民法院请求外国提供司法协助的，应当层报最高人民法院，经最高人民法院审核同意后交由有关对外联系机关及时向外国提出请求。"},{"i":494,"n":"第四百九十四条","txt":"人民法院请求外国提供司法协助的请求书，应当依照刑事司法协助条约的规定提出；没有条约或者条约没有规定的，应当载明法律规定的相关信息并附相关材料。请求书及其所附材料应当以中文制作，并附有被请求国官方文字的译本。"},{"i":495,"n":"第四百九十五条","txt":"人民法院向在中华人民共和国领域外居住的当事人送达刑事诉讼文书，可以采用下列方式："},{"i":496,"n":"第四百九十六条","txt":"人民法院通过外交途径向在中华人民共和国领域外居住的受送达人送达刑事诉讼文书的，所送达的文书应当经高级人民法院审查后报最高人民法院审核。最高人民法院认为可以发出的，由最高人民法院交外交部主管部门转递。"},{"i":497,"n":"第四百九十七条","txt":"被判处死刑缓期执行的罪犯，在死刑缓期执行期间犯罪的，应当由罪犯服刑地的中级人民法院依法审判，所作的判决可以上诉、抗诉。"},{"i":498,"n":"第四百九十八条","txt":"死刑缓期执行的期间，从判决或者裁定核准死刑缓期执行的法律文书宣告或者送达之日起计算。"},{"i":499,"n":"第四百九十九条","txt":"最高人民法院的执行死刑命令，由高级人民法院交付第一审人民法院执行。第一审人民法院接到执行死刑命令后，应当在七日以内执行。"},{"i":500,"n":"第五百条","txt":"下级人民法院在接到执行死刑命令后、执行前，发现有下列情形之一的，应当暂停执行，并立即将请求停止执行死刑的报告和相关材料层报最高人民法院："},{"i":501,"n":"第五百零一条","txt":"最高人民法院在执行死刑命令签发后、执行前，发现有前条第一款规定情形的，应当立即裁定停止执行死刑，并将有关材料移交下级人民法院。"},{"i":502,"n":"第五百零二条","txt":"下级人民法院接到最高人民法院停止执行死刑的裁定后，应当会同有关部门调查核实停止执行死刑的事由，并及时将调查结果和意见层报最高人民法院审核。"},{"i":503,"n":"第五百零三条","txt":"对下级人民法院报送的停止执行死刑的调查结果和意见，由最高人民法院原作出核准死刑判决、裁定的合议庭负责审查；必要时，另行组成合议庭进行审查。"},{"i":504,"n":"第五百零四条","txt":"最高人民法院对停止执行死刑的案件，应当按照下列情形分别处理："},{"i":505,"n":"第五百零五条","txt":"第一审人民法院在执行死刑前，应当告知罪犯有权会见其近亲属。罪犯申请会见并提供具体联系方式的，人民法院应当通知其近亲属。确实无法与罪犯近亲属取得联系，或者其近亲属拒绝会见的，应当告知罪犯。罪犯申请通过录音录像等方式留下遗言的，人民法院可以准许。"},{"i":506,"n":"第五百零六条","txt":"第一审人民法院在执行死刑三日以前，应当通知同级人民检察院派员临场监督。"},{"i":507,"n":"第五百零七条","txt":"死刑采用枪决或者注射等方法执行。"},{"i":508,"n":"第五百零八条","txt":"执行死刑前，指挥执行的审判人员应当对罪犯验明正身，讯问有无遗言、信札，并制作笔录，再交执行人员执行死刑。"},{"i":509,"n":"第五百零九条","txt":"执行死刑后，应当由法医验明罪犯确实死亡，在场书记员制作笔录。负责执行的人民法院应当在执行死刑后十五日以内将执行情况，包括罪犯被执行死刑前后的照片，上报最高人民法院。"},{"i":510,"n":"第五百一十条","txt":"执行死刑后，负责执行的人民法院应当办理以下事项："},{"i":511,"n":"第五百一十一条","txt":"被判处死刑缓期执行、无期徒刑、有期徒刑、拘役的罪犯，第一审人民法院应当在判决、裁定生效后十日以内，将判决书、裁定书、起诉书副本、自诉状复印件、执行通知书、结案登记表送达公安机关、监狱或者其他执行机关。"},{"i":512,"n":"第五百一十二条","txt":"同案审理的案件中，部分被告人被判处死刑，对未被判处死刑的同案被告人需要羁押执行刑罚的，应当根据前条规定及时交付执行。但是，该同案被告人参与实施有关死刑之罪的，应当在复核讯问被判处死刑的被告人后交付执行。"},{"i":513,"n":"第五百一十三条","txt":"执行通知书回执经看守所盖章后，应当附卷备查。"},{"i":514,"n":"第五百一十四条","txt":"罪犯在被交付执行前，因有严重疾病、怀孕或者正在哺乳自己婴儿的妇女、生活不能自理的原因，依法提出暂予监外执行的申请的，有关病情诊断、妊娠检查和生活不能自理的鉴别，由人民法院负责组织进行。"},{"i":515,"n":"第五百一十五条","txt":"被判处无期徒刑、有期徒刑或者拘役的罪犯，符合刑事诉讼法第二百六十五条第一款、第二款的规定，人民法院决定暂予监外执行的，应当制作暂予监外执行决定书，写明罪犯基本情况、判决确定的罪名和刑罚、决定暂予监外执行的原因、依据等。"},{"i":516,"n":"第五百一十六条","txt":"人民法院收到社区矫正机构的收监执行建议书后，经审查，确认暂予监外执行的罪犯具有下列情形之一的，应当作出收监执行的决定："},{"i":517,"n":"第五百一十七条","txt":"人民法院应当在收到社区矫正机构的收监执行建议书后三十日以内作出决定。收监执行决定书一经作出，立即生效。"},{"i":518,"n":"第五百一十八条","txt":"被收监执行的罪犯有不计入执行刑期情形的，人民法院应当在作出收监决定时，确定不计入执行刑期的具体时间。"},{"i":519,"n":"第五百一十九条","txt":"对被判处管制、宣告缓刑的罪犯，人民法院应当依法确定社区矫正执行地。社区矫正执行地为罪犯的居住地；罪犯在多个地方居住的，可以确定其经常居住地为执行地；罪犯的居住地、经常居住地无法确定或者不适宜执行社区矫正的，应当根据有利于罪犯接受矫正、更好地融入社会的原则，确定执行地。"},{"i":520,"n":"第五百二十条","txt":"对单处剥夺政治权利的罪犯，人民法院应当在判决、裁定生效后十日以内，将判决书、裁定书、执行通知书等法律文书送达罪犯居住地的县级公安机关，并抄送罪犯居住地的县级人民检察院。"},{"i":521,"n":"第五百二十一条","txt":"刑事裁判涉财产部分的执行，是指发生法律效力的刑事裁判中下列判项的执行："},{"i":522,"n":"第五百二十二条","txt":"刑事裁判涉财产部分和附带民事裁判应当由人民法院执行的，由第一审人民法院负责裁判执行的机构执行。"},{"i":523,"n":"第五百二十三条","txt":"罚金在判决规定的期限内一次或者分期缴纳。期满无故不缴纳或者未足额缴纳的，人民法院应当强制缴纳。经强制缴纳仍不能全部缴纳的，在任何时候，包括主刑执行完毕后，发现被执行人有可供执行的财产的，应当追缴。"},{"i":524,"n":"第五百二十四条","txt":"因遭遇不能抗拒的灾祸等原因缴纳罚金确有困难，被执行人申请延期缴纳、酌情减少或者免除罚金的，应当提交相关证明材料。人民法院应当在收到申请后一个月以内作出裁定。符合法定条件的，应当准许；不符合条件的，驳回申请。"},{"i":525,"n":"第五百二十五条","txt":"判处没收财产的，判决生效后，应当立即执行。"},{"i":526,"n":"第五百二十六条","txt":"执行财产刑，应当参照被扶养人住所地政府公布的上年度当地居民最低生活费标准，保留被执行人及其所扶养人的生活必需费用。"},{"i":527,"n":"第五百二十七条","txt":"被判处财产刑，同时又承担附带民事赔偿责任的被执行人，应当先履行民事赔偿责任。"},{"i":528,"n":"第五百二十八条","txt":"执行刑事裁判涉财产部分、附带民事裁判过程中，当事人、利害关系人认为执行行为违反法律规定，或者案外人对被执行标的书面提出异议的，人民法院应当参照民事诉讼法的有关规定处理。"},{"i":529,"n":"第五百二十九条","txt":"执行刑事裁判涉财产部分、附带民事裁判过程中，具有下列情形之一的，人民法院应当裁定终结执行："},{"i":530,"n":"第五百三十条","txt":"被执行财产在外地的，第一审人民法院可以委托财产所在地的同级人民法院执行。"},{"i":531,"n":"第五百三十一条","txt":"刑事裁判涉财产部分、附带民事裁判全部或者部分被撤销的，已经执行的财产应当全部或者部分返还被执行人；无法返还的，应当依法赔偿。"},{"i":532,"n":"第五百三十二条","txt":"刑事裁判涉财产部分、附带民事裁判的执行，刑事诉讼法及有关刑事司法解释没有规定的，参照适用民事执行的有关规定。"},{"i":533,"n":"第五百三十三条","txt":"被判处死刑缓期执行的罪犯，在死刑缓期执行期间，没有故意犯罪的，死刑缓期执行期满后，应当裁定减刑；死刑缓期执行期满后，尚未裁定减刑前又犯罪的，应当在依法减刑后，对其所犯新罪另行审判。"},{"i":534,"n":"第五百三十四条","txt":"对减刑、假释案件，应当按照下列情形分别处理："},{"i":535,"n":"第五百三十五条","txt":"受理减刑、假释案件，应当审查执行机关移送的材料是否包括下列内容："},{"i":536,"n":"第五百三十六条","txt":"审理减刑、假释案件，对罪犯积极履行刑事裁判涉财产部分、附带民事裁判确定的义务的，可以认定有悔改表现，在减刑、假释时从宽掌握；对确有履行能力而不履行或者不全部履行的，在减刑、假释时从严掌握。"},{"i":537,"n":"第五百三十七条","txt":"审理减刑、假释案件，应当在立案后五日以内对下列事项予以公示："},{"i":538,"n":"第五百三十八条","txt":"审理减刑、假释案件，应当组成合议庭，可以采用书面审理的方式，但下列案件应当开庭审理："},{"i":539,"n":"第五百三十九条","txt":"人民法院作出减刑、假释裁定后，应当在七日以内送达提请减刑、假释的执行机关、同级人民检察院以及罪犯本人。人民检察院认为减刑、假释裁定不当，在法定期限内提出书面纠正意见的，人民法院应当在收到意见后另行组成合议庭审理，并在一个月以内作出裁定。"},{"i":540,"n":"第五百四十条","txt":"减刑、假释裁定作出前，执行机关书面提请撤回减刑、假释建议的，人民法院可以决定是否准许。"},{"i":541,"n":"第五百四十一条","txt":"人民法院发现本院已经生效的减刑、假释裁定确有错误的，应当另行组成合议庭审理；发现下级人民法院已经生效的减刑、假释裁定确有错误的，可以指令下级人民法院另行组成合议庭审理，也可以自行组成合议庭审理。"},{"i":542,"n":"第五百四十二条","txt":"罪犯在缓刑、假释考验期限内犯新罪或者被发现在判决宣告前还有其他罪没有判决，应当撤销缓刑、假释的，由审判新罪的人民法院撤销原判决、裁定宣告的缓刑、假释，并书面通知原审人民法院和执行机关。"},{"i":543,"n":"第五百四十三条","txt":"人民法院收到社区矫正机构的撤销缓刑建议书后，经审查，确认罪犯在缓刑考验期限内具有下列情形之一的，应当作出撤销缓刑的裁定："},{"i":544,"n":"第五百四十四条","txt":"被提请撤销缓刑、假释的罪犯可能逃跑或者可能发生社会危险，社区矫正机构在提出撤销缓刑、假释建议的同时，提请人民法院决定对其予以逮捕的，人民法院应当在四十八小时以内作出是否逮捕的决定。决定逮捕的，由公安机关执行。逮捕后的羁押期限不得超过三十日。"},{"i":545,"n":"第五百四十五条","txt":"人民法院应当在收到社区矫正机构的撤销缓刑、假释建议书后三十日以内作出裁定。撤销缓刑、假释的裁定一经作出，立即生效。"},{"i":546,"n":"第五百四十六条","txt":"人民法院审理未成年人刑事案件，应当贯彻教育、感化、挽救的方针，坚持教育为主、惩罚为辅的原则，加强对未成年人的特殊保护。"},{"i":547,"n":"第五百四十七条","txt":"人民法院应当加强同政府有关部门、人民团体、社会组织等的配合，推动未成年人刑事案件人民陪审、情况调查、安置帮教等工作的开展，充分保障未成年人的合法权益，积极参与社会治安综合治理。"},{"i":548,"n":"第五百四十八条","txt":"人民法院应当加强同政府有关部门、人民团体、社会组织等的配合，对遭受性侵害或者暴力伤害的未成年被害人及其家庭实施必要的心理干预、经济救助、法律援助、转学安置等保护措施。"},{"i":549,"n":"第五百四十九条","txt":"人民法院应当确定专门机构或者指定专门人员，负责审理未成年人刑事案件。审理未成年人刑事案件的人员应当经过专门培训，熟悉未成年人身心特点、善于做未成年人思想教育工作。"},{"i":550,"n":"第五百五十条","txt":"被告人实施被指控的犯罪时不满十八周岁、人民法院立案时不满二十周岁的案件，由未成年人案件审判组织审理。"},{"i":551,"n":"第五百五十一条","txt":"对分案起诉至同一人民法院的未成年人与成年人共同犯罪案件，可以由同一个审判组织审理；不宜由同一个审判组织审理的，可以分别审理。"},{"i":552,"n":"第五百五十二条","txt":"对未成年人刑事案件，必要时，上级人民法院可以根据刑事诉讼法第二十七条的规定，指定下级人民法院将案件移送其他人民法院审判。"},{"i":553,"n":"第五百五十三条","txt":"对未成年被告人应当严格限制适用逮捕措施。"},{"i":554,"n":"第五百五十四条","txt":"人民法院对无固定住所、无法提供保证人的未成年被告人适用取保候审的，应当指定合适成年人作为保证人，必要时可以安排取保候审的被告人接受社会观护。"},{"i":555,"n":"第五百五十五条","txt":"人民法院审理未成年人刑事案件，在讯问和开庭时，应当通知未成年被告人的法定代理人到场。法定代理人无法通知、不能到场或者是共犯的，也可以通知合适成年人到场，并将有关情况记录在案。"},{"i":556,"n":"第五百五十六条","txt":"询问未成年被害人、证人，适用前条规定。"},{"i":557,"n":"第五百五十七条","txt":"开庭审理时被告人不满十八周岁的案件，一律不公开审理。经未成年被告人及其法定代理人同意，未成年被告人所在学校和未成年人保护组织可以派代表到场。到场代表的人数和范围，由法庭决定。经法庭同意，到场代表可以参与对未成年被告人的法庭教育工作。"},{"i":558,"n":"第五百五十八条","txt":"开庭审理涉及未成年人的刑事案件，未成年被害人、证人一般不出庭作证；必须出庭的，应当采取保护其隐私的技术手段和心理干预等保护措施。"},{"i":559,"n":"第五百五十九条","txt":"审理涉及未成年人的刑事案件，不得向外界披露未成年人的姓名、住所、照片以及可能推断出未成年人身份的其他资料。"},{"i":560,"n":"第五百六十条","txt":"人民法院发现有关单位未尽到未成年人教育、管理、救助、看护等保护职责的，应当向该单位提出司法建议。"},{"i":561,"n":"第五百六十一条","txt":"人民法院应当结合实际，根据涉及未成年人刑事案件的特点，开展未成年人法治宣传教育工作。"},{"i":562,"n":"第五百六十二条","txt":"审理未成年人刑事案件，本章没有规定的，适用本解释的有关规定。"},{"i":563,"n":"第五百六十三条","txt":"人民法院向未成年被告人送达起诉书副本时，应当向其讲明被指控的罪行和有关法律规定，并告知其审判程序和诉讼权利、义务。"},{"i":564,"n":"第五百六十四条","txt":"审判时不满十八周岁的未成年被告人没有委托辩护人的，人民法院应当通知法律援助机构指派熟悉未成年人身心特点的律师为其提供辩护。"},{"i":565,"n":"第五百六十五条","txt":"未成年被害人及其法定代理人因经济困难或者其他原因没有委托诉讼代理人的，人民法院应当帮助其申请法律援助。"},{"i":566,"n":"第五百六十六条","txt":"对未成年人刑事案件，人民法院决定适用简易程序审理的，应当征求未成年被告人及其法定代理人、辩护人的意见。上述人员提出异议的，不适用简易程序。"},{"i":567,"n":"第五百六十七条","txt":"被告人实施被指控的犯罪时不满十八周岁，开庭时已满十八周岁、不满二十周岁的，人民法院开庭时，一般应当通知其近亲属到庭。经法庭同意，近亲属可以发表意见。近亲属无法通知、不能到场或者是共犯的，应当记录在案。"},{"i":568,"n":"第五百六十八条","txt":"对人民检察院移送的关于未成年被告人性格特点、家庭情况、社会交往、成长经历、犯罪原因、犯罪前后的表现、监护教育等情况的调查报告，以及辩护人提交的反映未成年被告人上述情况的书面材料，法庭应当接受。"},{"i":569,"n":"第五百六十九条","txt":"人民法院根据情况，可以对未成年被告人、被害人、证人进行心理疏导；根据实际需要并经未成年被告人及其法定代理人同意，可以对未成年被告人进行心理测评。"},{"i":570,"n":"第五百七十条","txt":"开庭前和休庭时，法庭根据情况，可以安排未成年被告人与其法定代理人或者合适成年人会见。"},{"i":571,"n":"第五百七十一条","txt":"人民法院应当在辩护台靠近旁听区一侧为未成年被告人的法定代理人或者合适成年人设置席位。"},{"i":572,"n":"第五百七十二条","txt":"未成年被告人或者其法定代理人当庭拒绝辩护人辩护的，适用本解释第三百一十一条第二款、第三款的规定。"},{"i":573,"n":"第五百七十三条","txt":"法庭审理过程中，审判人员应当根据未成年被告人的智力发育程度和心理状态，使用适合未成年人的语言表达方式。"},{"i":574,"n":"第五百七十四条","txt":"控辩双方提出对未成年被告人判处管制、宣告缓刑等量刑建议的，应当向法庭提供有关未成年被告人能够获得监护、帮教以及对所居住社区无重大不良影响的书面材料。"},{"i":575,"n":"第五百七十五条","txt":"对未成年被告人情况的调查报告，以及辩护人提交的有关未成年被告人情况的书面材料，法庭应当审查并听取控辩双方意见。上述报告和材料可以作为办理案件和教育未成年人的参考。"},{"i":576,"n":"第五百七十六条","txt":"法庭辩论结束后，法庭可以根据未成年人的生理、心理特点和案件情况，对未成年被告人进行法治教育；判决未成年被告人有罪的，宣判后，应当对未成年被告人进行法治教育。"},{"i":577,"n":"第五百七十七条","txt":"未成年被告人最后陈述后，法庭应当询问其法定代理人是否补充陈述。"},{"i":578,"n":"第五百七十八条","txt":"对未成年人刑事案件，宣告判决应当公开进行。"},{"i":579,"n":"第五百七十九条","txt":"定期宣告判决的未成年人刑事案件，未成年被告人的法定代理人无法通知、不能到场或者是共犯的，法庭可以通知合适成年人到庭，并在宣判后向未成年被告人的成年亲属送达判决书。"},{"i":580,"n":"第五百八十条","txt":"将未成年罪犯送监执行刑罚或者送交社区矫正时，人民法院应当将有关未成年罪犯的调查报告及其在案件审理中的表现材料，连同有关法律文书，一并送达执行机关。"},{"i":581,"n":"第五百八十一条","txt":"犯罪时不满十八周岁，被判处五年有期徒刑以下刑罚以及免予刑事处罚的未成年人的犯罪记录，应当封存。"},{"i":582,"n":"第五百八十二条","txt":"人民法院可以与未成年犯管教所等服刑场所建立联系，了解未成年罪犯的改造情况，协助做好帮教、改造工作，并可以对正在服刑的未成年罪犯进行回访考察。"},{"i":583,"n":"第五百八十三条","txt":"人民法院认为必要时，可以督促被收监服刑的未成年罪犯的父母或者其他监护人及时探视。"},{"i":584,"n":"第五百八十四条","txt":"对被判处管制、宣告缓刑、裁定假释、决定暂予监外执行的未成年罪犯，人民法院可以协助社区矫正机构制定帮教措施。"},{"i":585,"n":"第五百八十五条","txt":"人民法院可以适时走访被判处管制、宣告缓刑、免予刑事处罚、裁定假释、决定暂予监外执行等的未成年罪犯及其家庭，了解未成年罪犯的管理和教育情况，引导未成年罪犯的家庭承担管教责任，为未成年罪犯改过自新创造良好环境。"},{"i":586,"n":"第五百八十六条","txt":"被判处管制、宣告缓刑、免予刑事处罚、裁定假释、决定暂予监外执行等的未成年罪犯，具备就学、就业条件的，人民法院可以就其安置问题向有关部门提出建议，并附送必要的材料。"},{"i":587,"n":"第五百八十七条","txt":"对符合刑事诉讼法第二百八十八条规定的公诉案件，事实清楚、证据充分的，人民法院应当告知当事人可以自行和解；当事人提出申请的，人民法院可以主持双方当事人协商以达成和解。"},{"i":588,"n":"第五百八十八条","txt":"符合刑事诉讼法第二百八十八条规定的公诉案件，被害人死亡的，其近亲属可以与被告人和解。近亲属有多人的，达成和解协议，应当经处于最先继承顺序的所有近亲属同意。"},{"i":589,"n":"第五百八十九条","txt":"被告人的近亲属经被告人同意，可以代为和解。"},{"i":590,"n":"第五百九十条","txt":"对公安机关、人民检察院主持制作的和解协议书，当事人提出异议的，人民法院应当审查。经审查，和解自愿、合法的，予以确认，无需重新制作和解协议书；和解违反自愿、合法原则的，应当认定无效。和解协议被认定无效后，双方当事人重新达成和解的，人民法院应当主持制作新的和解协议书。"},{"i":591,"n":"第五百九十一条","txt":"审判期间，双方当事人和解的，人民法院应当听取当事人及其法定代理人等有关人员的意见。双方当事人在庭外达成和解的，人民法院应当通知人民检察院，并听取其意见。经审查，和解自愿、合法的，应当主持制作和解协议书。"},{"i":592,"n":"第五百九十二条","txt":"和解协议书应当包括以下内容："},{"i":593,"n":"第五百九十三条","txt":"和解协议约定的赔偿损失内容，被告人应当在协议签署后即时履行。"},{"i":594,"n":"第五百九十四条","txt":"双方当事人在侦查、审查起诉期间已经达成和解协议并全部履行，被害人或者其法定代理人、近亲属又提起附带民事诉讼的，人民法院不予受理，但有证据证明和解违反自愿、合法原则的除外。"},{"i":595,"n":"第五百九十五条","txt":"被害人或者其法定代理人、近亲属提起附带民事诉讼后，双方愿意和解，但被告人不能即时履行全部赔偿义务的，人民法院应当制作附带民事调解书。"},{"i":596,"n":"第五百九十六条","txt":"对达成和解协议的案件，人民法院应当对被告人从轻处罚；符合非监禁刑适用条件的，应当适用非监禁刑；判处法定最低刑仍然过重的，可以减轻处罚；综合全案认为犯罪情节轻微不需要判处刑罚的，可以免予刑事处罚。"},{"i":597,"n":"第五百九十七条","txt":"达成和解协议的，裁判文书应当叙明，并援引刑事诉讼法的相关条文。"},{"i":598,"n":"第五百九十八条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，人民法院应当重点审查以下内容："},{"i":599,"n":"第五百九十九条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，人民法院审查后，应当按照下列情形分别处理："},{"i":600,"n":"第六百条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，人民法院立案后，应当将传票和起诉书副本送达被告人，传票应当载明被告人到案期限以及不按要求到案的法律后果等事项；应当将起诉书副本送达被告人近亲属，告知其有权代为委托辩护人，并通知其敦促被告人归案。"},{"i":601,"n":"第六百零一条","txt":"人民法院审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，被告人有权委托或者由近亲属代为委托一至二名辩护人。委托律师担任辩护人的，应当委托具有中华人民共和国律师资格并依法取得执业证书的律师；在境外委托的，应当依照本解释第四百八十六条的规定对授权委托进行公证、认证。"},{"i":602,"n":"第六百零二条","txt":"人民法院审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，被告人的近亲属申请参加诉讼的，应当在收到起诉书副本后、第一审开庭前提出，并提供与被告人关系的证明材料。有多名近亲属的，应当推选一至二人参加诉讼。"},{"i":603,"n":"第六百零三条","txt":"人民法院审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，参照适用公诉案件第一审普通程序的有关规定。被告人的近亲属参加诉讼的，可以发表意见，出示证据，申请法庭通知证人、鉴定人等出庭，进行辩论。"},{"i":604,"n":"第六百零四条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，人民法院审理后应当参照本解释第二百九十五条的规定作出判决、裁定。"},{"i":605,"n":"第六百零五条","txt":"因被告人患有严重疾病导致缺乏受审能力，无法出庭受审，中止审理超过六个月，被告人仍无法出庭，被告人及其法定代理人、近亲属申请或者同意恢复审理的，人民法院可以根据刑事诉讼法第二百九十六条的规定缺席审判。"},{"i":606,"n":"第六百零六条","txt":"人民法院受理案件后被告人死亡的，应当裁定终止审理；但有证据证明被告人无罪，经缺席审理确认无罪的，应当判决宣告被告人无罪。"},{"i":607,"n":"第六百零七条","txt":"人民法院按照审判监督程序重新审判的案件，被告人死亡的，可以缺席审理。有证据证明被告人无罪，经缺席审理确认被告人无罪的，应当判决宣告被告人无罪；虽然构成犯罪，但原判量刑畸重的，应当依法作出判决。"},{"i":608,"n":"第六百零八条","txt":"人民法院缺席审理案件，本章没有规定的，参照适用本解释的有关规定。"},{"i":609,"n":"第六百零九条","txt":"刑事诉讼法第二百九十八条规定的“贪污贿赂犯罪、恐怖活动犯罪等”犯罪案件，是指下列案件："},{"i":610,"n":"第六百一十条","txt":"在省、自治区、直辖市或者全国范围内具有较大影响的犯罪案件，或者犯罪嫌疑人、被告人逃匿境外的犯罪案件，应当认定为刑事诉讼法第二百九十八条第一款规定的“重大犯罪案件”。"},{"i":611,"n":"第六百一十一条","txt":"犯罪嫌疑人、被告人死亡，依照刑法规定应当追缴其违法所得及其他涉案财产，人民检察院提出没收违法所得申请的，人民法院应当依法受理。"},{"i":612,"n":"第六百一十二条","txt":"对人民检察院提出的没收违法所得申请，人民法院应当审查以下内容："},{"i":613,"n":"第六百一十三条","txt":"对没收违法所得的申请，人民法院应当在三十日以内审查完毕，并按照下列情形分别处理："},{"i":614,"n":"第六百一十四条","txt":"人民法院受理没收违法所得的申请后，应当在十五日以内发布公告。公告应当载明以下内容："},{"i":615,"n":"第六百一十五条","txt":"公告应当在全国公开发行的报纸、信息网络媒体、最高人民法院的官方网站发布，并在人民法院公告栏发布。必要时，公告可以在犯罪地、犯罪嫌疑人、被告人居住地或者被申请没收财产所在地发布。最后发布的公告的日期为公告日期。发布公告的，应当采取拍照、录像等方式记录发布过程。"},{"i":616,"n":"第六百一十六条","txt":"刑事诉讼法第二百九十九条第二款、第三百条第二款规定的“其他利害关系人”，是指除犯罪嫌疑人、被告人的近亲属以外的，对申请没收的财产主张权利的自然人和单位。"},{"i":617,"n":"第六百一十七条","txt":"犯罪嫌疑人、被告人的近亲属和其他利害关系人申请参加诉讼的，应当在公告期间内提出。犯罪嫌疑人、被告人的近亲属应当提供其与犯罪嫌疑人、被告人关系的证明材料，其他利害关系人应当提供证明其对违法所得及其他涉案财产主张权利的证据材料。"},{"i":618,"n":"第六百一十八条","txt":"犯罪嫌疑人、被告人逃匿境外，委托诉讼代理人申请参加诉讼，且违法所得或者其他涉案财产所在国、地区主管机关明确提出意见予以支持的，人民法院可以准许。"},{"i":619,"n":"第六百一十九条","txt":"公告期满后，人民法院应当组成合议庭对申请没收违法所得的案件进行审理。"},{"i":620,"n":"第六百二十条","txt":"开庭审理申请没收违法所得的案件，按照下列程序进行："},{"i":621,"n":"第六百二十一条","txt":"对申请没收违法所得的案件，人民法院审理后，应当按照下列情形分别处理："},{"i":622,"n":"第六百二十二条","txt":"对没收违法所得或者驳回申请的裁定，犯罪嫌疑人、被告人的近亲属和其他利害关系人或者人民检察院可以在五日以内提出上诉、抗诉。"},{"i":623,"n":"第六百二十三条","txt":"对不服第一审没收违法所得或者驳回申请裁定的上诉、抗诉案件，第二审人民法院经审理，应当按照下列情形分别处理："},{"i":624,"n":"第六百二十四条","txt":"利害关系人非因故意或者重大过失在第一审期间未参加诉讼，在第二审期间申请参加诉讼的，人民法院应当准许，并撤销原裁定，发回原审人民法院重新审判。"},{"i":625,"n":"第六百二十五条","txt":"在审理申请没收违法所得的案件过程中，在逃的犯罪嫌疑人、被告人到案的，人民法院应当裁定终止审理。人民检察院向原受理申请的人民法院提起公诉的，可以由同一审判组织审理。"},{"i":626,"n":"第六百二十六条","txt":"在审理案件过程中，被告人脱逃或者死亡，符合刑事诉讼法第二百九十八条第一款规定的，人民检察院可以向人民法院提出没收违法所得的申请；符合刑事诉讼法第二百九十一条第一款规定的，人民检察院可以按照缺席审判程序向人民法院提起公诉。"},{"i":627,"n":"第六百二十七条","txt":"审理申请没收违法所得案件的期限，参照公诉案件第一审普通程序和第二审程序的审理期限执行。"},{"i":628,"n":"第六百二十八条","txt":"没收违法所得裁定生效后，犯罪嫌疑人、被告人到案并对没收裁定提出异议，人民检察院向原作出裁定的人民法院提起公诉的，可以由同一审判组织审理。"},{"i":629,"n":"第六百二十九条","txt":"人民法院审理申请没收违法所得的案件，本章没有规定的，参照适用本解释的有关规定。"},{"i":630,"n":"第六百三十条","txt":"实施暴力行为，危害公共安全或者严重危害公民人身安全，社会危害性已经达到犯罪程度，但经法定程序鉴定依法不负刑事责任的精神病人，有继续危害社会可能的，可以予以强制医疗。"},{"i":631,"n":"第六百三十一条","txt":"人民检察院申请对依法不负刑事责任的精神病人强制医疗的案件，由被申请人实施暴力行为所在地的基层人民法院管辖；由被申请人居住地的人民法院审判更为适宜的，可以由被申请人居住地的基层人民法院管辖。"},{"i":632,"n":"第六百三十二条","txt":"对人民检察院提出的强制医疗申请，人民法院应当审查以下内容："},{"i":633,"n":"第六百三十三条","txt":"对人民检察院提出的强制医疗申请，人民法院应当在七日以内审查完毕，并按照下列情形分别处理："},{"i":634,"n":"第六百三十四条","txt":"审理强制医疗案件，应当通知被申请人或者被告人的法定代理人到场；被申请人或者被告人的法定代理人经通知未到场的，可以通知被申请人或者被告人的其他近亲属到场。"},{"i":635,"n":"第六百三十五条","txt":"审理强制医疗案件，应当组成合议庭，开庭审理。但是，被申请人、被告人的法定代理人请求不开庭审理，并经人民法院审查同意的除外。"},{"i":636,"n":"第六百三十六条","txt":"开庭审理申请强制医疗的案件，按照下列程序进行："},{"i":637,"n":"第六百三十七条","txt":"对申请强制医疗的案件，人民法院审理后，应当按照下列情形分别处理："},{"i":638,"n":"第六百三十八条","txt":"第一审人民法院在审理刑事案件过程中，发现被告人可能符合强制医疗条件的，应当依照法定程序对被告人进行法医精神病鉴定。经鉴定，被告人属于依法不负刑事责任的精神病人的，应当适用强制医疗程序，对案件进行审理。"},{"i":639,"n":"第六百三十九条","txt":"对前条规定的案件，人民法院审理后，应当按照下列情形分别处理："},{"i":640,"n":"第六百四十条","txt":"第二审人民法院在审理刑事案件过程中，发现被告人可能符合强制医疗条件的，可以依照强制医疗程序对案件作出处理，也可以裁定发回原审人民法院重新审判。"},{"i":641,"n":"第六百四十一条","txt":"人民法院决定强制医疗的，应当在作出决定后五日以内，向公安机关送达强制医疗决定书和强制医疗执行通知书，由公安机关将被决定强制医疗的人送交强制医疗。"},{"i":642,"n":"第六百四十二条","txt":"被决定强制医疗的人、被害人及其法定代理人、近亲属对强制医疗决定不服的，可以自收到决定书第二日起五日以内向上一级人民法院申请复议。复议期间不停止执行强制医疗的决定。"},{"i":643,"n":"第六百四十三条","txt":"对不服强制医疗决定的复议申请，上一级人民法院应当组成合议庭审理，并在一个月以内，按照下列情形分别作出复议决定："},{"i":644,"n":"第六百四十四条","txt":"对本解释第六百三十九条第一项规定的判决、决定，人民检察院提出抗诉，同时被决定强制医疗的人、被害人及其法定代理人、近亲属申请复议的，上一级人民法院应当依照第二审程序一并处理。"},{"i":645,"n":"第六百四十五条","txt":"被强制医疗的人及其近亲属申请解除强制医疗的，应当向决定强制医疗的人民法院提出。"},{"i":646,"n":"第六百四十六条","txt":"强制医疗机构提出解除强制医疗意见，或者被强制医疗的人及其近亲属申请解除强制医疗的，人民法院应当审查是否附有对被强制医疗的人的诊断评估报告。"},{"i":647,"n":"第六百四十七条","txt":"强制医疗机构提出解除强制医疗意见，或者被强制医疗的人及其近亲属申请解除强制医疗的，人民法院应当组成合议庭进行审查，并在一个月以内，按照下列情形分别处理："},{"i":648,"n":"第六百四十八条","txt":"人民检察院认为强制医疗决定或者解除强制医疗决定不当，在收到决定书后二十日以内提出书面纠正意见的，人民法院应当另行组成合议庭审理，并在一个月以内作出决定。"},{"i":649,"n":"第六百四十九条","txt":"审理强制医疗案件，本章没有规定的，参照适用本解释的有关规定。"},{"i":650,"n":"第六百五十条","txt":"人民法院讯问被告人，宣告判决，审理减刑、假释案件等，可以根据情况采取视频方式。"},{"i":651,"n":"第六百五十一条","txt":"向人民法院提出自诉、上诉、申诉、申请等的，应当以书面形式提出。书写有困难的，除另有规定的以外，可以口头提出，由人民法院工作人员制作笔录或者记录在案，并向口述人宣读或者交其阅读。"},{"i":652,"n":"第六百五十二条","txt":"诉讼期间制作、形成的工作记录、告知笔录等材料，应当由制作人员和其他有关人员签名、盖章。宣告或者送达裁判文书、通知书等诉讼文书的，应当由接受宣告或者送达的人在诉讼文书、送达回证上签名、盖章。"},{"i":653,"n":"第六百五十三条","txt":"本解释的有关规定适用于军事法院等专门人民法院。"},{"i":654,"n":"第六百五十四条","txt":"本解释有关公安机关的规定，依照刑事诉讼法的有关规定，适用于国家安全机关、军队保卫部门、中国海警局和监狱。"},{"i":655,"n":"第六百五十五条","txt":"本解释自2021年3月1日起施行。最高人民法院2012年12月20日发布的《关于适用〈中华人民共和国刑事诉讼法〉的解释》（法释〔2012〕21号）同时废止。最高人民法院以前发布的司法解释和规范性文件，与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushiyongfanbuzhengdangjingz99bdd4":[{"i":1,"n":"第一条","txt":"经营者扰乱市场竞争秩序，损害其他经营者或者消费者合法权益，且属于违反反不正当竞争法第二章及专利法、商标法、著作权法等规定之外情形的，人民法院可以适用反不正当竞争法第二条予以认定。"},{"i":2,"n":"第二条","txt":"与经营者在生产经营活动中存在可能的争夺交易机会、损害竞争优势等关系的市场主体，人民法院可以认定为反不正当竞争法第二条规定的“其他经营者”。"},{"i":3,"n":"第三条","txt":"特定商业领域普遍遵循和认可的行为规范，人民法院可以认定为反不正当竞争法第二条规定的“商业道德”。"},{"i":4,"n":"第四条","txt":"具有一定的市场知名度并具有区别商品来源的显著特征的标识，人民法院可以认定为反不正当竞争法第六条规定的“有一定影响的”标识。"},{"i":5,"n":"第五条","txt":"反不正当竞争法第六条规定的标识有下列情形之一的，人民法院应当认定其不具有区别商品来源的显著特征："},{"i":6,"n":"第六条","txt":"因客观描述、说明商品而正当使用下列标识，当事人主张属于反不正当竞争法第六条规定的情形的，人民法院不予支持："},{"i":7,"n":"第七条","txt":"反不正当竞争法第六条规定的标识或者其显著识别部分属于商标法第十条第一款规定的不得作为商标使用的标志，当事人请求依据反不正当竞争法第六条规定予以保护的，人民法院不予支持。"},{"i":8,"n":"第八条","txt":"由经营者营业场所的装饰、营业用具的式样、营业人员的服饰等构成的具有独特风格的整体营业形象，人民法院可以认定为反不正当竞争法第六条第一项规定的“装潢”。"},{"i":9,"n":"第九条","txt":"市场主体登记管理部门依法登记的企业名称，以及在中国境内进行商业使用的境外企业名称，人民法院可以认定为反不正当竞争法第六条第二项规定的“企业名称”。"},{"i":10,"n":"第十条","txt":"在中国境内将有一定影响的标识用于商品、商品包装或者容器以及商品交易文书上，或者广告宣传、展览以及其他商业活动中，用于识别商品来源的行为，人民法院可以认定为反不正当竞争法第六条规定的“使用”。"},{"i":11,"n":"第十一条","txt":"经营者擅自使用与他人有一定影响的企业名称（包括简称、字号等）、社会组织名称（包括简称等）、姓名（包括笔名、艺名、译名等）、域名主体部分、网站名称、网页等近似的标识，引人误认为是他人商品或者与他人存在特定联系，当事人主张属于反不正当竞争法第六条第二项、第三项规定的情形的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"人民法院认定与反不正当竞争法第六条规定的“有一定影响的”标识相同或者近似，可以参照商标相同或者近似的判断原则和方法。"},{"i":13,"n":"第十三条","txt":"经营者实施下列混淆行为之一，足以引人误认为是他人商品或者与他人存在特定联系的，人民法院可以依照反不正当竞争法第六条第四项予以认定："},{"i":14,"n":"第十四条","txt":"经营者销售带有违反反不正当竞争法第六条规定的标识的商品，引人误认为是他人商品或者与他人存在特定联系，当事人主张构成反不正当竞争法第六条规定的情形的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"故意为他人实施混淆行为提供仓储、运输、邮寄、印制、隐匿、经营场所等便利条件，当事人请求依据民法典第一千一百六十九条第一款予以认定的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"经营者在商业宣传过程中，提供不真实的商品相关信息，欺骗、误导相关公众的，人民法院应当认定为反不正当竞争法第八条第一款规定的虚假的商业宣传。"},{"i":17,"n":"第十七条","txt":"经营者具有下列行为之一，欺骗、误导相关公众的，人民法院可以认定为反不正当竞争法第八条第一款规定的“引人误解的商业宣传”："},{"i":18,"n":"第十八条","txt":"当事人主张经营者违反反不正当竞争法第八条第一款的规定并请求赔偿损失的，应当举证证明其因虚假或者引人误解的商业宣传行为受到损失。"},{"i":19,"n":"第十九条","txt":"当事人主张经营者实施了反不正当竞争法第十一条规定的商业诋毁行为的，应当举证证明其为该商业诋毁行为的特定损害对象。"},{"i":20,"n":"第二十条","txt":"经营者传播他人编造的虚假信息或者误导性信息，损害竞争对手的商业信誉、商品声誉的，人民法院应当依照反不正当竞争法第十一条予以认定。"},{"i":21,"n":"第二十一条","txt":"未经其他经营者和用户同意而直接发生的目标跳转，人民法院应当认定为反不正当竞争法第十二条第二款第一项规定的“强制进行目标跳转”。"},{"i":22,"n":"第二十二条","txt":"经营者事前未明确提示并经用户同意，以误导、欺骗、强迫用户修改、关闭、卸载等方式，恶意干扰或者破坏其他经营者合法提供的网络产品或者服务，人民法院应当依照反不正当竞争法第十二条第二款第二项予以认定。"},{"i":23,"n":"第二十三条","txt":"对于反不正当竞争法第二条、第八条、第十一条、第十二条规定的不正当竞争行为，权利人因被侵权所受到的实际损失、侵权人因侵权所获得的利益难以确定，当事人主张依据反不正当竞争法第十七条第四款确定赔偿数额的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"对于同一侵权人针对同一主体在同一时间和地域范围实施的侵权行为，人民法院已经认定侵害著作权、专利权或者注册商标专用权等并判令承担民事责任，当事人又以该行为构成不正当竞争为由请求同一侵权人承担民事责任的，人民法院不予支持。"},{"i":25,"n":"第二十五条","txt":"依据反不正当竞争法第六条的规定，当事人主张判令被告停止使用或者变更其企业名称的诉讼请求依法应予支持的，人民法院应当判令停止使用该企业名称。"},{"i":26,"n":"第二十六条","txt":"因不正当竞争行为提起的民事诉讼，由侵权行为地或者被告住所地人民法院管辖。"},{"i":27,"n":"第二十七条","txt":"被诉不正当竞争行为发生在中华人民共和国领域外，但侵权结果发生在中华人民共和国领域内，当事人主张由该侵权结果发生地人民法院管辖的，人民法院应予支持。"},{"i":28,"n":"第二十八条","txt":"反不正当竞争法修改决定施行以后人民法院受理的不正当竞争民事案件，涉及该决定施行前发生的行为的，适用修改前的反不正当竞争法；涉及该决定施行前发生、持续到该决定施行以后的行为的，适用修改后的反不正当竞争法。"},{"i":29,"n":"第二十九条","txt":"本解释自2022年3月20日起施行。《最高人民法院关于审理不正当竞争民事案件应用法律若干问题的解释》（法释〔2007〕2号）同时废止。"}],"zuigaorenminfayuanguanyushiyongguojiapeichangfaruoe0c0b9":[{"i":1,"n":"第一条","txt":"国家机关及其工作人员行使职权侵犯公民、法人和其他组织合法权益的行为发生在2010年12月1日以后，或者发生在2010年12月1日以前、持续至2010年12月1日以后的，适用修正的国家赔偿法。"},{"i":2,"n":"第二条","txt":"国家机关及其工作人员行使职权侵犯公民、法人和其他组织合法权益的行为发生在2010年12月1日以前的，适用修正前的国家赔偿法，但有下列情形之一的，适用修正的国家赔偿法："},{"i":3,"n":"第三条","txt":"人民法院对2010年12月1日以前已经受理但尚未审结的国家赔偿确认案件，应当继续审理。"},{"i":4,"n":"第四条","txt":"公民、法人和其他组织对行使侦查、检察、审判职权的机关以及看守所、监狱管理机关在2010年12月1日以前作出并已发生法律效力的不予确认职务行为违法的法律文书不服，未依据修正前的国家赔偿法规定提出申诉并经有权机关作出侵权确认结论，直接向人民法院赔偿委员会申请赔偿的，不予受理。"},{"i":5,"n":"第五条","txt":"公民、法人和其他组织对在2010年12月1日以前发生法律效力的赔偿决定不服提出申诉的，人民法院审查处理时适用修正前的国家赔偿法；但是仅就修正的国家赔偿法增加的赔偿项目及标准提出申诉的，人民法院不予受理。"},{"i":6,"n":"第六条","txt":"人民法院审查发现2010年12月1日以前发生法律效力的确认裁定、赔偿决定确有错误应当重新审查处理的，适用修正前的国家赔偿法。"},{"i":7,"n":"第七条","txt":"赔偿请求人认为行使侦查、检察、审判职权的机关以及看守所、监狱管理机关及其工作人员在行使职权时有修正的国家赔偿法第十七条第（一）、（二）、（三）项、第十八条规定情形的，应当在刑事诉讼程序终结后提出赔偿请求，但下列情形除外："},{"i":8,"n":"第八条","txt":"赔偿请求人认为人民法院有修正的国家赔偿法第三十八条规定情形的，应当在民事、行政诉讼程序或者执行程序终结后提出赔偿请求，但人民法院已依法撤销对妨害诉讼采取的强制措施的情形除外。"},{"i":9,"n":"第九条","txt":"赔偿请求人或者赔偿义务机关认为人民法院赔偿委员会作出的赔偿决定存在错误，依法向上一级人民法院赔偿委员会提出申诉的，不停止赔偿决定的执行；但人民法院赔偿委员会依据修正的国家赔偿法第三十条的规定决定重新审查的，可以决定中止原赔偿决定的执行。"},{"i":10,"n":"第十条","txt":"人民检察院依据修正的国家赔偿法第三十条第三款的规定，对人民法院赔偿委员会在2010年12月1日以后作出的赔偿决定提出意见的，同级人民法院赔偿委员会应当决定重新审查，并可以决定中止原赔偿决定的执行。"},{"i":11,"n":"第十一条","txt":"本解释自公布之日起施行。"}],"zuigaorenminfayuanguanyushiyongwaishangtouzifaruog76676d":[{"i":1,"n":"第一条","txt":"本解释所称投资合同，是指外国投资者即外国的自然人、企业或者其他组织因直接或者间接在中国境内进行投资而形成的相关协议，包括设立外商投资企业合同、股份转让合同、股权转让合同、财产份额或者其他类似权益转让合同、新建项目合同等协议。"},{"i":2,"n":"第二条","txt":"对外商投资法第四条所指的外商投资准入负面清单之外的领域形成的投资合同，当事人以合同未经有关行政主管部门批准、登记为由主张合同无效或者未生效的，人民法院不予支持。"},{"i":3,"n":"第三条","txt":"外国投资者投资外商投资准入负面清单规定禁止投资的领域，当事人主张投资合同无效的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"外国投资者投资外商投资准入负面清单规定限制投资的领域，当事人以违反限制性准入特别管理措施为由，主张投资合同无效的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"在生效裁判作出前，因外商投资准入负面清单调整，外国投资者投资不再属于禁止或者限制投资的领域，当事人主张投资合同有效的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"人民法院审理香港特别行政区、澳门特别行政区投资者、定居在国外的中国公民在内地、台湾地区投资者在大陆投资产生的相关纠纷案件，可以参照适用本解释。"},{"i":7,"n":"第七条","txt":"本解释自2020年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminshisusongfashenpec0941":[{"i":1,"n":"第一条","txt":"当事人在民事诉讼法第二百零五条规定的期限内，以民事诉讼法第二百条所列明的再审事由，向原审人民法院的上一级人民法院申请再审的，上一级人民法院应当依法受理。"},{"i":2,"n":"第二条","txt":"民事诉讼法第二百零五条规定的申请再审期间不适用中止、中断和延长的规定。"},{"i":3,"n":"第三条","txt":"当事人申请再审，应当向人民法院提交再审申请书，并按照对方当事人人数提出副本。"},{"i":4,"n":"第四条","txt":"当事人申请再审，应当向人民法院提交已经发生法律效力的判决书、裁定书、调解书，身份证明及相关证据材料。"},{"i":5,"n":"第五条","txt":"申请再审人提交的再审申请书或者其他材料不符合本解释第三条、第四条的规定，或者有人身攻击等内容，可能引起矛盾激化的，人民法院应当要求申请再审人补充或改正。"},{"i":6,"n":"第六条","txt":"人民法院应当自收到符合条件的再审申请书等材料后五日内完成向申请再审人发送受理通知书等受理登记手续，并向对方当事人发送受理通知书及再审申请书副本。"},{"i":7,"n":"第七条","txt":"人民法院受理再审申请后，应当组成合议庭予以审查。"},{"i":8,"n":"第八条","txt":"人民法院对再审申请的审查，应当围绕再审事由是否成立进行。"},{"i":9,"n":"第九条","txt":"民事诉讼法第二百条第（五）项规定的“对审理案件需要的主要证据”，是指人民法院认定案件基本事实所必需的证据。"},{"i":10,"n":"第十条","txt":"原判决、裁定对基本事实和案件性质的认定系根据其他法律文书作出，而上述其他法律文书被撤销或变更的，人民法院可以认定为民事诉讼法第二百条第（十二）项规定的情形。"},{"i":11,"n":"第十一条","txt":"人民法院经审查再审申请书等材料，认为申请再审事由成立的，应当径行裁定再审。"},{"i":12,"n":"第十二条","txt":"人民法院认为仅审查再审申请书等材料难以作出裁定的，应当调阅原审卷宗予以审查。"},{"i":13,"n":"第十三条","txt":"人民法院可以根据案情需要决定是否询问当事人。"},{"i":14,"n":"第十四条","txt":"在审查再审申请过程中，对方当事人也申请再审的，人民法院应当将其列为申请再审人，对其提出的再审申请一并审查。"},{"i":15,"n":"第十五条","txt":"申请再审人在案件审查期间申请撤回再审申请的，是否准许，由人民法院裁定。"},{"i":16,"n":"第十六条","txt":"人民法院经审查认为申请再审事由不成立的，应当裁定驳回再审申请。"},{"i":17,"n":"第十七条","txt":"人民法院审查再审申请期间，人民检察院对该案提出抗诉的，人民法院应依照民事诉讼法第二百一十一条的规定裁定再审。申请再审人提出的具体再审请求应纳入审理范围。"},{"i":18,"n":"第十八条","txt":"上一级人民法院经审查认为申请再审事由成立的，一般由本院提审。最高人民法院、高级人民法院也可以指定与原审人民法院同级的其他人民法院再审，或者指令原审人民法院再审。"},{"i":19,"n":"第十九条","txt":"上一级人民法院可以根据案件的影响程度以及案件参与人等情况，决定是否指定再审。需要指定再审的，应当考虑便利当事人行使诉讼权利以及便利人民法院审理等因素。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，不得指令原审人民法院再审："},{"i":21,"n":"第二十一条","txt":"当事人未申请再审、人民检察院未抗诉的案件，人民法院发现原判决、裁定、调解协议有损害国家利益、社会公共利益等确有错误情形的，应当依照民事诉讼法第一百九十八条的规定提起再审。"},{"i":22,"n":"第二十二条","txt":"人民法院应当依照民事诉讼法第二百零七条的规定，按照第一审程序或者第二审程序审理再审案件。"},{"i":23,"n":"第二十三条","txt":"申请再审人在再审期间撤回再审申请的，是否准许由人民法院裁定。裁定准许的，应终结再审程序。申请再审人经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以裁定按自动撤回再审申请处理。"},{"i":24,"n":"第二十四条","txt":"按照第一审程序审理再审案件时，一审原告申请撤回起诉的，是否准许由人民法院裁定。裁定准许的，应当同时裁定撤销原判决、裁定、调解书。"},{"i":25,"n":"第二十五条","txt":"当事人在再审审理中经调解达成协议的，人民法院应当制作调解书。调解书经各方当事人签收后，即具有法律效力，原判决、裁定视为被撤销。"},{"i":26,"n":"第二十六条","txt":"人民法院经再审审理认为，原判决、裁定认定事实清楚、适用法律正确的，应予维持；原判决、裁定在认定事实、适用法律、阐述理由方面虽有瑕疵，但裁判结果正确的，人民法院应在再审判决、裁定中纠正上述瑕疵后予以维持。"},{"i":27,"n":"第二十七条","txt":"人民法院按照第二审程序审理再审案件，发现原判决认定事实错误或者认定事实不清的，应当在查清事实后改判。但原审人民法院便于查清事实，化解纠纷的，可以裁定撤销原判决，发回重审；原审程序遗漏必须参加诉讼的当事人且无法达成调解协议，以及其他违反法定程序不宜在再审程序中直接作出实体处理的，应当裁定撤销原判决，发回重审。"},{"i":28,"n":"第二十八条","txt":"人民法院以调解方式审结的案件裁定再审后，经审理发现申请再审人提出的调解违反自愿原则的事由不成立，且调解协议的内容不违反法律强制性规定的，应当裁定驳回再审申请，并恢复原调解书的执行。"},{"i":29,"n":"第二十九条","txt":"民事再审案件的当事人应为原审案件的当事人。原审案件当事人死亡或者终止的，其权利义务承受人可以申请再审并参加再审诉讼。"},{"i":30,"n":"第三十条","txt":"本院以前发布的司法解释与本解释不一致的，以本解释为准。本解释未作规定的，按照以前的规定执行。"}],"zuigaorenminfayuanguanyushiyongminshisusongfazhixib83922":[{"i":1,"n":"第一条","txt":"申请执行人向被执行的财产所在地人民法院申请执行的，应当提供该人民法院辖区有可供执行财产的证明材料。"},{"i":2,"n":"第二条","txt":"对两个以上人民法院都有管辖权的执行案件，人民法院在立案前发现其他有管辖权的人民法院已经立案的，不得重复立案。"},{"i":3,"n":"第三条","txt":"人民法院受理执行申请后，当事人对管辖权有异议的，应当自收到执行通知书之日起十日内提出。"},{"i":4,"n":"第四条","txt":"对人民法院采取财产保全措施的案件，申请执行人向采取保全措施的人民法院以外的其他有管辖权的人民法院申请执行的，采取保全措施的人民法院应当将保全的财产交执行法院处理。"},{"i":5,"n":"第五条","txt":"执行过程中，当事人、利害关系人认为执行法院的执行行为违反法律规定的，可以依照民事诉讼法第二百二十五条的规定提出异议。"},{"i":6,"n":"第六条","txt":"当事人、利害关系人依照民事诉讼法第二百二十五条规定申请复议的，应当采取书面形式。"},{"i":7,"n":"第七条","txt":"当事人、利害关系人申请复议的书面材料，可以通过执行法院转交，也可以直接向执行法院的上一级人民法院提交。"},{"i":8,"n":"第八条","txt":"当事人、利害关系人依照民事诉讼法第二百二十五条规定申请复议的，上一级人民法院应当自收到复议申请之日起三十日内审查完毕，并作出裁定。有特殊情况需要延长的，经本院院长批准，可以延长，延长的期限不得超过三十日。"},{"i":9,"n":"第九条","txt":"执行异议审查和复议期间，不停止执行。"},{"i":10,"n":"第十条","txt":"依照民事诉讼法第二百二十六条的规定，有下列情形之一的，上一级人民法院可以根据申请执行人的申请，责令执行法院限期执行或者变更执行法院："},{"i":11,"n":"第十一条","txt":"上一级人民法院依照民事诉讼法第二百二十六条规定责令执行法院限期执行的，应当向其发出督促执行令，并将有关情况书面通知申请执行人。"},{"i":12,"n":"第十二条","txt":"上一级人民法院责令执行法院限期执行，执行法院在指定期间内无正当理由仍未执行完结的，上一级人民法院应当裁定由本院执行或者指令本辖区其他人民法院执行。"},{"i":13,"n":"第十三条","txt":"民事诉讼法第二百二十六条规定的六个月期间，不应当计算执行中的公告期间、鉴定评估期间、管辖争议处理期间、执行争议协调期间、暂缓执行期间以及中止执行期间。"},{"i":14,"n":"第十四条","txt":"案外人对执行标的主张所有权或者有其他足以阻止执行标的转让、交付的实体权利的，可以依照民事诉讼法第二百二十七条的规定，向执行法院提出异议。"},{"i":15,"n":"第十五条","txt":"案外人异议审查期间，人民法院不得对执行标的进行处分。"},{"i":16,"n":"第十六条","txt":"案外人执行异议之诉审理期间，人民法院不得对执行标的进行处分。申请执行人请求人民法院继续执行并提供相应担保的，人民法院可以准许。"},{"i":17,"n":"第十七条","txt":"多个债权人对同一被执行人申请执行或者对执行财产申请参与分配的，执行法院应当制作财产分配方案，并送达各债权人和被执行人。债权人或者被执行人对分配方案有异议的，应当自收到分配方案之日起十五日内向执行法院提出书面异议。"},{"i":18,"n":"第十八条","txt":"债权人或者被执行人对分配方案提出书面异议的，执行法院应当通知未提出异议的债权人或被执行人。"},{"i":19,"n":"第十九条","txt":"在申请执行时效期间的最后六个月内，因不可抗力或者其他障碍不能行使请求权的，申请执行时效中止。从中止时效的原因消除之日起，申请执行时效期间继续计算。"},{"i":20,"n":"第二十条","txt":"申请执行时效因申请执行、当事人双方达成和解协议、当事人一方提出履行要求或者同意履行义务而中断。从中断时起，申请执行时效期间重新计算。"},{"i":21,"n":"第二十一条","txt":"生效法律文书规定债务人负有不作为义务的，申请执行时效期间从债务人违反不作为义务之日起计算。"},{"i":22,"n":"第二十二条","txt":"执行员依照民事诉讼法第二百四十条规定立即采取强制执行措施的，可以同时或者自采取强制执行措施之日起三日内发送执行通知书。"},{"i":23,"n":"第二十三条","txt":"依照民事诉讼法第二百五十五条规定对被执行人限制出境的，应当由申请执行人向执行法院提出书面申请；必要时，执行法院可以依职权决定。"},{"i":24,"n":"第二十四条","txt":"被执行人为单位的，可以对其法定代表人、主要负责人或者影响债务履行的直接责任人员限制出境。"},{"i":25,"n":"第二十五条","txt":"在限制出境期间，被执行人履行法律文书确定的全部债务的，执行法院应当及时解除限制出境措施；被执行人提供充分、有效的担保或者申请执行人同意的，可以解除限制出境措施。"},{"i":26,"n":"第二十六条","txt":"依照民事诉讼法第二百五十五条的规定，执行法院可以依职权或者依申请执行人的申请，将被执行人不履行法律文书确定义务的信息，通过报纸、广播、电视、互联网等媒体公布。"},{"i":27,"n":"第二十七条","txt":"本解释施行前本院公布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushiyongminshisusongfadejie0e9457":[{"i":1,"n":"第一条","txt":"民事诉讼法第十九条第一项规定的重大涉外案件，包括争议标的额大的案件、案情复杂的案件，或者一方当事人人数众多等具有重大影响的案件。"},{"i":2,"n":"第二条","txt":"专利纠纷案件由知识产权法院、最高人民法院确定的中级人民法院和基层人民法院管辖。"},{"i":3,"n":"第三条","txt":"公民的住所地是指公民的户籍所在地，法人或者其他组织的住所地是指法人或者其他组织的主要办事机构所在地。"},{"i":4,"n":"第四条","txt":"公民的经常居住地是指公民离开住所地至起诉时已连续居住一年以上的地方，但公民住院就医的地方除外。"},{"i":5,"n":"第五条","txt":"对没有办事机构的个人合伙、合伙型联营体提起的诉讼，由被告注册登记地人民法院管辖。没有注册登记，几个被告又不在同一辖区的，被告住所地的人民法院都有管辖权。"},{"i":6,"n":"第六条","txt":"被告被注销户籍的，依照民事诉讼法第二十三条规定确定管辖；原告、被告均被注销户籍的，由被告居住地人民法院管辖。"},{"i":7,"n":"第七条","txt":"当事人的户籍迁出后尚未落户，有经常居住地的，由该地人民法院管辖；没有经常居住地的，由其原户籍所在地人民法院管辖。"},{"i":8,"n":"第八条","txt":"双方当事人都被监禁或者被采取强制性教育措施的，由被告原住所地人民法院管辖。被告被监禁或者被采取强制性教育措施一年以上的，由被告被监禁地或者被采取强制性教育措施地人民法院管辖。"},{"i":9,"n":"第九条","txt":"追索赡养费、扶养费、抚养费案件的几个被告住所地不在同一辖区的，可以由原告住所地人民法院管辖。"},{"i":10,"n":"第十条","txt":"不服指定监护或者变更监护关系的案件，可以由被监护人住所地人民法院管辖。"},{"i":11,"n":"第十一条","txt":"双方当事人均为军人或者军队单位的民事案件由军事法院管辖。"},{"i":12,"n":"第十二条","txt":"夫妻一方离开住所地超过一年，另一方起诉离婚的案件，可以由原告住所地人民法院管辖。"},{"i":13,"n":"第十三条","txt":"在国内结婚并定居国外的华侨，如定居国法院以离婚诉讼须由婚姻缔结地法院管辖为由不予受理，当事人向人民法院提出离婚诉讼的，由婚姻缔结地或者一方在国内的最后居住地人民法院管辖。"},{"i":14,"n":"第十四条","txt":"在国外结婚并定居国外的华侨，如定居国法院以离婚诉讼须由国籍所属国法院管辖为由不予受理，当事人向人民法院提出离婚诉讼的，由一方原住所地或者在国内的最后居住地人民法院管辖。"},{"i":15,"n":"第十五条","txt":"中国公民一方居住在国外，一方居住在国内，不论哪一方向人民法院提起离婚诉讼，国内一方住所地人民法院都有权管辖。国外一方在居住国法院起诉，国内一方向人民法院起诉的，受诉人民法院有权管辖。"},{"i":16,"n":"第十六条","txt":"中国公民双方在国外但未定居，一方向人民法院起诉离婚的，应由原告或者被告原住所地人民法院管辖。"},{"i":17,"n":"第十七条","txt":"已经离婚的中国公民，双方均定居国外，仅就国内财产分割提起诉讼的，由主要财产所在地人民法院管辖。"},{"i":18,"n":"第十八条","txt":"合同约定履行地点的，以约定的履行地点为合同履行地。"},{"i":19,"n":"第十九条","txt":"财产租赁合同、融资租赁合同以租赁物使用地为合同履行地。合同对履行地有约定的，从其约定。"},{"i":20,"n":"第二十条","txt":"以信息网络方式订立的买卖合同，通过信息网络交付标的的，以买受人住所地为合同履行地；通过其他方式交付标的的，收货地为合同履行地。合同对履行地有约定的，从其约定。"},{"i":21,"n":"第二十一条","txt":"因财产保险合同纠纷提起的诉讼，如果保险标的物是运输工具或者运输中的货物，可以由运输工具登记注册地、运输目的地、保险事故发生地人民法院管辖。"},{"i":22,"n":"第二十二条","txt":"因股东名册记载、请求变更公司登记、股东知情权、公司决议、公司合并、公司分立、公司减资、公司增资等纠纷提起的诉讼，依照民事诉讼法第二十七条规定确定管辖。"},{"i":23,"n":"第二十三条","txt":"债权人申请支付令，适用民事诉讼法第二十二条规定，由债务人住所地基层人民法院管辖。"},{"i":24,"n":"第二十四条","txt":"民事诉讼法第二十九条规定的侵权行为地，包括侵权行为实施地、侵权结果发生地。"},{"i":25,"n":"第二十五条","txt":"信息网络侵权行为实施地包括实施被诉侵权行为的计算机等信息设备所在地，侵权结果发生地包括被侵权人住所地。"},{"i":26,"n":"第二十六条","txt":"因产品、服务质量不合格造成他人财产、人身损害提起的诉讼，产品制造地、产品销售地、服务提供地、侵权行为地和被告住所地人民法院都有管辖权。"},{"i":27,"n":"第二十七条","txt":"当事人申请诉前保全后没有在法定期间起诉或者申请仲裁，给被申请人、利害关系人造成损失引起的诉讼，由采取保全措施的人民法院管辖。"},{"i":28,"n":"第二十八条","txt":"民事诉讼法第三十四条第一项规定的不动产纠纷是指因不动产的权利确认、分割、相邻关系等引起的物权纠纷。"},{"i":29,"n":"第二十九条","txt":"民事诉讼法第三十五条规定的书面协议，包括书面合同中的协议管辖条款或者诉讼前以书面形式达成的选择管辖的协议。"},{"i":30,"n":"第三十条","txt":"根据管辖协议，起诉时能够确定管辖法院的，从其约定；不能确定的，依照民事诉讼法的相关规定确定管辖。"},{"i":31,"n":"第三十一条","txt":"经营者使用格式条款与消费者订立管辖协议，未采取合理方式提请消费者注意，消费者主张管辖协议无效的，人民法院应予支持。"},{"i":32,"n":"第三十二条","txt":"管辖协议约定由一方当事人住所地人民法院管辖，协议签订后当事人住所地变更的，由签订管辖协议时的住所地人民法院管辖，但当事人另有约定的除外。"},{"i":33,"n":"第三十三条","txt":"合同转让的，合同的管辖协议对合同受让人有效，但转让时受让人不知道有管辖协议，或者转让协议另有约定且原合同相对人同意的除外。"},{"i":34,"n":"第三十四条","txt":"当事人因同居或者在解除婚姻、收养关系后发生财产争议，约定管辖的，可以适用民事诉讼法第三十五条规定确定管辖。"},{"i":35,"n":"第三十五条","txt":"当事人在答辩期间届满后未应诉答辩，人民法院在一审开庭前，发现案件不属于本院管辖的，应当裁定移送有管辖权的人民法院。"},{"i":36,"n":"第三十六条","txt":"两个以上人民法院都有管辖权的诉讼，先立案的人民法院不得将案件移送给另一个有管辖权的人民法院。人民法院在立案前发现其他有管辖权的人民法院已先立案的，不得重复立案；立案后发现其他有管辖权的人民法院已先立案的，裁定将案件移送给先立案的人民法院。"},{"i":37,"n":"第三十七条","txt":"案件受理后，受诉人民法院的管辖权不受当事人住所地、经常居住地变更的影响。"},{"i":38,"n":"第三十八条","txt":"有管辖权的人民法院受理案件后，不得以行政区域变更为由，将案件移送给变更后有管辖权的人民法院。判决后的上诉案件和依审判监督程序提审的案件，由原审人民法院的上级人民法院进行审判；上级人民法院指令再审、发回重审的案件，由原审人民法院再审或者重审。"},{"i":39,"n":"第三十九条","txt":"人民法院对管辖异议审查后确定有管辖权的，不因当事人提起反诉、增加或者变更诉讼请求等改变管辖，但违反级别管辖、专属管辖规定的除外。"},{"i":40,"n":"第四十条","txt":"依照民事诉讼法第三十八条第二款规定，发生管辖权争议的两个人民法院因协商不成报请它们的共同上级人民法院指定管辖时，双方为同属一个地、市辖区的基层人民法院的，由该地、市的中级人民法院及时指定管辖；同属一个省、自治区、直辖市的两个人民法院的，由该省、自治区、直辖市的高级人民法院及时指定管辖；双方为跨省、自治区、直辖市的人民法院，高级人民法院协商不成的，由最高人民法院及时指定管辖。"},{"i":41,"n":"第四十一条","txt":"人民法院依照民事诉讼法第三十八条第二款规定指定管辖的，应当作出裁定。"},{"i":42,"n":"第四十二条","txt":"下列第一审民事案件，人民法院依照民事诉讼法第三十九条第一款规定，可以在开庭前交下级人民法院审理："},{"i":43,"n":"第四十三条","txt":"审判人员有下列情形之一的，应当自行回避，当事人有权申请其回避："},{"i":44,"n":"第四十四条","txt":"审判人员有下列情形之一的，当事人有权申请其回避："},{"i":45,"n":"第四十五条","txt":"在一个审判程序中参与过本案审判工作的审判人员，不得再参与该案其他程序的审判。"},{"i":46,"n":"第四十六条","txt":"审判人员有应当回避的情形，没有自行回避，当事人也没有申请其回避的，由院长或者审判委员会决定其回避。"},{"i":47,"n":"第四十七条","txt":"人民法院应当依法告知当事人对合议庭组成人员、独任审判员和书记员等人员有申请回避的权利。"},{"i":48,"n":"第四十八条","txt":"民事诉讼法第四十七条所称的审判人员，包括参与本案审理的人民法院院长、副院长、审判委员会委员、庭长、副庭长、审判员和人民陪审员。"},{"i":49,"n":"第四十九条","txt":"书记员和执行员适用审判人员回避的有关规定。"},{"i":50,"n":"第五十条","txt":"法人的法定代表人以依法登记的为准，但法律另有规定的除外。依法不需要办理登记的法人，以其正职负责人为法定代表人；没有正职负责人的，以其主持工作的副职负责人为法定代表人。"},{"i":51,"n":"第五十一条","txt":"在诉讼中，法人的法定代表人变更的，由新的法定代表人继续进行诉讼，并应向人民法院提交新的法定代表人身份证明书。原法定代表人进行的诉讼行为有效。"},{"i":52,"n":"第五十二条","txt":"民事诉讼法第五十一条规定的其他组织是指合法成立、有一定的组织机构和财产，但又不具备法人资格的组织，包括："},{"i":53,"n":"第五十三条","txt":"法人非依法设立的分支机构，或者虽依法设立，但没有领取营业执照的分支机构，以设立该分支机构的法人为当事人。"},{"i":54,"n":"第五十四条","txt":"以挂靠形式从事民事活动，当事人请求由挂靠人和被挂靠人依法承担民事责任的，该挂靠人和被挂靠人为共同诉讼人。"},{"i":55,"n":"第五十五条","txt":"在诉讼中，一方当事人死亡，需要等待继承人表明是否参加诉讼的，裁定中止诉讼。人民法院应当及时通知继承人作为当事人承担诉讼，被继承人已经进行的诉讼行为对承担诉讼的继承人有效。"},{"i":56,"n":"第五十六条","txt":"法人或者其他组织的工作人员执行工作任务造成他人损害的，该法人或者其他组织为当事人。"},{"i":57,"n":"第五十七条","txt":"提供劳务一方因劳务造成他人损害，受害人提起诉讼的，以接受劳务一方为被告。"},{"i":58,"n":"第五十八条","txt":"在劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，以接受劳务派遣的用工单位为当事人。当事人主张劳务派遣单位承担责任的，该劳务派遣单位为共同被告。"},{"i":59,"n":"第五十九条","txt":"在诉讼中，个体工商户以营业执照上登记的经营者为当事人。有字号的，以营业执照上登记的字号为当事人，但应同时注明该字号经营者的基本信息。"},{"i":60,"n":"第六十条","txt":"在诉讼中，未依法登记领取营业执照的个人合伙的全体合伙人为共同诉讼人。个人合伙有依法核准登记的字号的，应在法律文书中注明登记的字号。全体合伙人可以推选代表人；被推选的代表人，应由全体合伙人出具推选书。"},{"i":61,"n":"第六十一条","txt":"当事人之间的纠纷经人民调解委员会或者其他依法设立的调解组织调解达成协议后，一方当事人不履行调解协议，另一方当事人向人民法院提起诉讼的，应以对方当事人为被告。"},{"i":62,"n":"第六十二条","txt":"下列情形，以行为人为当事人："},{"i":63,"n":"第六十三条","txt":"企业法人合并的，因合并前的民事活动发生的纠纷，以合并后的企业为当事人；企业法人分立的，因分立前的民事活动发生的纠纷，以分立后的企业为共同诉讼人。"},{"i":64,"n":"第六十四条","txt":"企业法人解散的，依法清算并注销前，以该企业法人为当事人；未依法清算即被注销的，以该企业法人的股东、发起人或者出资人为当事人。"},{"i":65,"n":"第六十五条","txt":"借用业务介绍信、合同专用章、盖章的空白合同书或者银行账户的，出借单位和借用人为共同诉讼人。"},{"i":66,"n":"第六十六条","txt":"因保证合同纠纷提起的诉讼，债权人向保证人和被保证人一并主张权利的，人民法院应当将保证人和被保证人列为共同被告。保证合同约定为一般保证，债权人仅起诉保证人的，人民法院应当通知被保证人作为共同被告参加诉讼；债权人仅起诉被保证人的，可以只列被保证人为被告。"},{"i":67,"n":"第六十七条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害的，无民事行为能力人、限制民事行为能力人和其监护人为共同被告。"},{"i":68,"n":"第六十八条","txt":"居民委员会、村民委员会或者村民小组与他人发生民事纠纷的，居民委员会、村民委员会或者有独立财产的村民小组为当事人。"},{"i":69,"n":"第六十九条","txt":"对侵害死者遗体、遗骨以及姓名、肖像、名誉、荣誉、隐私等行为提起诉讼的，死者的近亲属为当事人。"},{"i":70,"n":"第七十条","txt":"在继承遗产的诉讼中，部分继承人起诉的，人民法院应通知其他继承人作为共同原告参加诉讼；被通知的继承人不愿意参加诉讼又未明确表示放弃实体权利的，人民法院仍应将其列为共同原告。"},{"i":71,"n":"第七十一条","txt":"原告起诉被代理人和代理人，要求承担连带责任的，被代理人和代理人为共同被告。"},{"i":72,"n":"第七十二条","txt":"共有财产权受到他人侵害，部分共有权人起诉的，其他共有权人为共同诉讼人。"},{"i":73,"n":"第七十三条","txt":"必须共同进行诉讼的当事人没有参加诉讼的，人民法院应当依照民事诉讼法第一百三十五条的规定，通知其参加；当事人也可以向人民法院申请追加。人民法院对当事人提出的申请，应当进行审查，申请理由不成立的，裁定驳回；申请理由成立的，书面通知被追加的当事人参加诉讼。"},{"i":74,"n":"第七十四条","txt":"人民法院追加共同诉讼的当事人时，应当通知其他当事人。应当追加的原告，已明确表示放弃实体权利的，可不予追加；既不愿意参加诉讼，又不放弃实体权利的，仍应追加为共同原告，其不参加诉讼，不影响人民法院对案件的审理和依法作出判决。"},{"i":75,"n":"第七十五条","txt":"民事诉讼法第五十六条、第五十七条和第二百零六条规定的人数众多，一般指十人以上。"},{"i":76,"n":"第七十六条","txt":"依照民事诉讼法第五十六条规定，当事人一方人数众多在起诉时确定的，可以由全体当事人推选共同的代表人，也可以由部分当事人推选自己的代表人；推选不出代表人的当事人，在必要的共同诉讼中可以自己参加诉讼，在普通的共同诉讼中可以另行起诉。"},{"i":77,"n":"第七十七条","txt":"根据民事诉讼法第五十七条规定，当事人一方人数众多在起诉时不确定的，由当事人推选代表人。当事人推选不出的，可以由人民法院提出人选与当事人协商；协商不成的，也可以由人民法院在起诉的当事人中指定代表人。"},{"i":78,"n":"第七十八条","txt":"民事诉讼法第五十六条和第五十七条规定的代表人为二至五人，每位代表人可以委托一至二人作为诉讼代理人。"},{"i":79,"n":"第七十九条","txt":"依照民事诉讼法第五十七条规定受理的案件，人民法院可以发出公告，通知权利人向人民法院登记。公告期间根据案件的具体情况确定，但不得少于三十日。"},{"i":80,"n":"第八十条","txt":"根据民事诉讼法第五十七条规定向人民法院登记的权利人，应当证明其与对方当事人的法律关系和所受到的损害。证明不了的，不予登记，权利人可以另行起诉。人民法院的裁判在登记的范围内执行。未参加登记的权利人提起诉讼，人民法院认定其请求成立的，裁定适用人民法院已作出的判决、裁定。"},{"i":81,"n":"第八十一条","txt":"根据民事诉讼法第五十九条的规定，有独立请求权的第三人有权向人民法院提出诉讼请求和事实、理由，成为当事人；无独立请求权的第三人，可以申请或者由人民法院通知参加诉讼。"},{"i":82,"n":"第八十二条","txt":"在一审诉讼中，无独立请求权的第三人无权提出管辖异议，无权放弃、变更诉讼请求或者申请撤诉，被判决承担民事责任的，有权提起上诉。"},{"i":83,"n":"第八十三条","txt":"在诉讼中，无民事行为能力人、限制民事行为能力人的监护人是他的法定代理人。事先没有确定监护人的，可以由有监护资格的人协商确定；协商不成的，由人民法院在他们之中指定诉讼中的法定代理人。当事人没有民法典第二十七条、第二十八条规定的监护人的，可以指定民法典第三十二条规定的有关组织担任诉讼中的法定代理人。"},{"i":84,"n":"第八十四条","txt":"无民事行为能力人、限制民事行为能力人以及其他依法不能作为诉讼代理人的，当事人不得委托其作为诉讼代理人。"},{"i":85,"n":"第八十五条","txt":"根据民事诉讼法第六十一条第二款第二项规定，与当事人有夫妻、直系血亲、三代以内旁系血亲、近姻亲关系以及其他有抚养、赡养关系的亲属，可以当事人近亲属的名义作为诉讼代理人。"},{"i":86,"n":"第八十六条","txt":"根据民事诉讼法第六十一条第二款第二项规定，与当事人有合法劳动人事关系的职工，可以当事人工作人员的名义作为诉讼代理人。"},{"i":87,"n":"第八十七条","txt":"根据民事诉讼法第六十一条第二款第三项规定，有关社会团体推荐公民担任诉讼代理人的，应当符合下列条件："},{"i":88,"n":"第八十八条","txt":"诉讼代理人除根据民事诉讼法第六十二条规定提交授权委托书外，还应当按照下列规定向人民法院提交相关材料："},{"i":89,"n":"第八十九条","txt":"当事人向人民法院提交的授权委托书，应当在开庭审理前送交人民法院。授权委托书仅写“全权代理”而无具体授权的，诉讼代理人无权代为承认、放弃、变更诉讼请求，进行和解，提出反诉或者提起上诉。"},{"i":90,"n":"第九十条","txt":"当事人对自己提出的诉讼请求所依据的事实或者反驳对方诉讼请求所依据的事实，应当提供证据加以证明，但法律另有规定的除外。"},{"i":91,"n":"第九十一条","txt":"人民法院应当依照下列原则确定举证证明责任的承担，但法律另有规定的除外："},{"i":92,"n":"第九十二条","txt":"一方当事人在法庭审理中，或者在起诉状、答辩状、代理词等书面材料中，对于己不利的事实明确表示承认的，另一方当事人无需举证证明。"},{"i":93,"n":"第九十三条","txt":"下列事实，当事人无须举证证明："},{"i":94,"n":"第九十四条","txt":"民事诉讼法第六十七条第二款规定的当事人及其诉讼代理人因客观原因不能自行收集的证据包括："},{"i":95,"n":"第九十五条","txt":"当事人申请调查收集的证据，与待证事实无关联、对证明待证事实无意义或者其他无调查收集必要的，人民法院不予准许。"},{"i":96,"n":"第九十六条","txt":"民事诉讼法第六十七条第二款规定的人民法院认为审理案件需要的证据包括："},{"i":97,"n":"第九十七条","txt":"人民法院调查收集证据，应当由两人以上共同进行。调查材料要由调查人、被调查人、记录人签名、捺印或者盖章。"},{"i":98,"n":"第九十八条","txt":"当事人根据民事诉讼法第八十四条第一款规定申请证据保全的，可以在举证期限届满前书面提出。"},{"i":99,"n":"第九十九条","txt":"人民法院应当在审理前的准备阶段确定当事人的举证期限。举证期限可以由当事人协商，并经人民法院准许。"},{"i":100,"n":"第一百条","txt":"当事人申请延长举证期限的，应当在举证期限届满前向人民法院提出书面申请。"},{"i":101,"n":"第一百零一条","txt":"当事人逾期提供证据的，人民法院应当责令其说明理由，必要时可以要求其提供相应的证据。"},{"i":102,"n":"第一百零二条","txt":"当事人因故意或者重大过失逾期提供的证据，人民法院不予采纳。但该证据与案件基本事实有关的，人民法院应当采纳，并依照民事诉讼法第六十八条、第一百一十八条第一款的规定予以训诫、罚款。"},{"i":103,"n":"第一百零三条","txt":"证据应当在法庭上出示，由当事人互相质证。未经当事人质证的证据，不得作为认定案件事实的根据。"},{"i":104,"n":"第一百零四条","txt":"人民法院应当组织当事人围绕证据的真实性、合法性以及与待证事实的关联性进行质证，并针对证据有无证明力和证明力大小进行说明和辩论。"},{"i":105,"n":"第一百零五条","txt":"人民法院应当按照法定程序，全面、客观地审核证据，依照法律规定，运用逻辑推理和日常生活经验法则，对证据有无证明力和证明力大小进行判断，并公开判断的理由和结果。"},{"i":106,"n":"第一百零六条","txt":"对以严重侵害他人合法权益、违反法律禁止性规定或者严重违背公序良俗的方法形成或者获取的证据，不得作为认定案件事实的根据。"},{"i":107,"n":"第一百零七条","txt":"在诉讼中，当事人为达成调解协议或者和解协议作出妥协而认可的事实，不得在后续的诉讼中作为对其不利的根据，但法律另有规定或者当事人均同意的除外。"},{"i":108,"n":"第一百零八条","txt":"对负有举证证明责任的当事人提供的证据，人民法院经审查并结合相关事实，确信待证事实的存在具有高度可能性的，应当认定该事实存在。"},{"i":109,"n":"第一百零九条","txt":"当事人对欺诈、胁迫、恶意串通事实的证明，以及对口头遗嘱或者赠与事实的证明，人民法院确信该待证事实存在的可能性能够排除合理怀疑的，应当认定该事实存在。"},{"i":110,"n":"第一百一十条","txt":"人民法院认为有必要的，可以要求当事人本人到庭，就案件有关事实接受询问。在询问当事人之前，可以要求其签署保证书。"},{"i":111,"n":"第一百一十一条","txt":"民事诉讼法第七十三条规定的提交书证原件确有困难，包括下列情形："},{"i":112,"n":"第一百一十二条","txt":"书证在对方当事人控制之下的，承担举证证明责任的当事人可以在举证期限届满前书面申请人民法院责令对方当事人提交。"},{"i":113,"n":"第一百一十三条","txt":"持有书证的当事人以妨碍对方当事人使用为目的，毁灭有关书证或者实施其他致使书证不能使用行为的，人民法院可以依照民事诉讼法第一百一十四条规定，对其处以罚款、拘留。"},{"i":114,"n":"第一百一十四条","txt":"国家机关或者其他依法具有社会管理职能的组织，在其职权范围内制作的文书所记载的事项推定为真实，但有相反证据足以推翻的除外。必要时，人民法院可以要求制作文书的机关或者组织对文书的真实性予以说明。"},{"i":115,"n":"第一百一十五条","txt":"单位向人民法院提出的证明材料，应当由单位负责人及制作证明材料的人员签名或者盖章，并加盖单位印章。人民法院就单位出具的证明材料，可以向单位及制作证明材料的人员进行调查核实。必要时，可以要求制作证明材料的人员出庭作证。"},{"i":116,"n":"第一百一十六条","txt":"视听资料包括录音资料和影像资料。"},{"i":117,"n":"第一百一十七条","txt":"当事人申请证人出庭作证的，应当在举证期限届满前提出。"},{"i":118,"n":"第一百一十八条","txt":"民事诉讼法第七十七条规定的证人因履行出庭作证义务而支出的交通、住宿、就餐等必要费用，按照机关事业单位工作人员差旅费用和补贴标准计算；误工损失按照国家上年度职工日平均工资标准计算。"},{"i":119,"n":"第一百一十九条","txt":"人民法院在证人出庭作证前应当告知其如实作证的义务以及作伪证的法律后果，并责令其签署保证书，但无民事行为能力人和限制民事行为能力人除外。"},{"i":120,"n":"第一百二十条","txt":"证人拒绝签署保证书的，不得作证，并自行承担相关费用。"},{"i":121,"n":"第一百二十一条","txt":"当事人申请鉴定，可以在举证期限届满前提出。申请鉴定的事项与待证事实无关联，或者对证明待证事实无意义的，人民法院不予准许。"},{"i":122,"n":"第一百二十二条","txt":"当事人可以依照民事诉讼法第八十二条的规定，在举证期限届满前申请一至二名具有专门知识的人出庭，代表当事人对鉴定意见进行质证，或者对案件事实所涉及的专业问题提出意见。"},{"i":123,"n":"第一百二十三条","txt":"人民法院可以对出庭的具有专门知识的人进行询问。经法庭准许，当事人可以对出庭的具有专门知识的人进行询问，当事人各自申请的具有专门知识的人可以就案件中的有关问题进行对质。"},{"i":124,"n":"第一百二十四条","txt":"人民法院认为有必要的，可以根据当事人的申请或者依职权对物证或者现场进行勘验。勘验时应当保护他人的隐私和尊严。"},{"i":125,"n":"第一百二十五条","txt":"依照民事诉讼法第八十五条第二款规定，民事诉讼中以时起算的期间从次时起算；以日、月、年计算的期间从次日起算。"},{"i":126,"n":"第一百二十六条","txt":"民事诉讼法第一百二十六条规定的立案期限，因起诉状内容欠缺通知原告补正的，从补正后交人民法院的次日起算。由上级人民法院转交下级人民法院立案的案件，从受诉人民法院收到起诉状的次日起算。"},{"i":127,"n":"第一百二十七条","txt":"民事诉讼法第五十九条第三款、第二百一十二条以及本解释第三百七十二条、第三百八十二条、第三百九十九条、第四百二十条、第四百二十一条规定的六个月，民事诉讼法第二百三十条规定的一年，为不变期间，不适用诉讼时效中止、中断、延长的规定。"},{"i":128,"n":"第一百二十八条","txt":"再审案件按照第一审程序或者第二审程序审理的，适用民事诉讼法第一百五十二条、第一百八十三条规定的审限。审限自再审立案的次日起算。"},{"i":129,"n":"第一百二十九条","txt":"对申请再审案件，人民法院应当自受理之日起三个月内审查完毕，但公告期间、当事人和解期间等不计入审查期限。有特殊情况需要延长的，由本院院长批准。"},{"i":130,"n":"第一百三十条","txt":"向法人或者其他组织送达诉讼文书，应当由法人的法定代表人、该组织的主要负责人或者办公室、收发室、值班室等负责收件的人签收或者盖章，拒绝签收或者盖章的，适用留置送达。"},{"i":131,"n":"第一百三十一条","txt":"人民法院直接送达诉讼文书的，可以通知当事人到人民法院领取。当事人到达人民法院，拒绝签署送达回证的，视为送达。审判人员、书记员应当在送达回证上注明送达情况并签名。"},{"i":132,"n":"第一百三十二条","txt":"受送达人有诉讼代理人的，人民法院既可以向受送达人送达，也可以向其诉讼代理人送达。受送达人指定诉讼代理人为代收人的，向诉讼代理人送达时，适用留置送达。"},{"i":133,"n":"第一百三十三条","txt":"调解书应当直接送达当事人本人，不适用留置送达。当事人本人因故不能签收的，可由其指定的代收人签收。"},{"i":134,"n":"第一百三十四条","txt":"依照民事诉讼法第九十一条规定，委托其他人民法院代为送达的，委托法院应当出具委托函，并附需要送达的诉讼文书和送达回证，以受送达人在送达回证上签收的日期为送达日期。"},{"i":135,"n":"第一百三十五条","txt":"电子送达可以采用传真、电子邮件、移动通信等即时收悉的特定系统作为送达媒介。"},{"i":136,"n":"第一百三十六条","txt":"受送达人同意采用电子方式送达的，应当在送达地址确认书中予以确认。"},{"i":137,"n":"第一百三十七条","txt":"当事人在提起上诉、申请再审、申请执行时未书面变更送达地址的，其在第一审程序中确认的送达地址可以作为第二审程序、审判监督程序、执行程序的送达地址。"},{"i":138,"n":"第一百三十八条","txt":"公告送达可以在法院的公告栏和受送达人住所地张贴公告，也可以在报纸、信息网络等媒体上刊登公告，发出公告日期以最后张贴或者刊登的日期为准。对公告送达方式有特殊要求的，应当按要求的方式进行。公告期满，即视为送达。"},{"i":139,"n":"第一百三十九条","txt":"公告送达应当说明公告送达的原因；公告送达起诉状或者上诉状副本的，应当说明起诉或者上诉要点，受送达人答辩期限及逾期不答辩的法律后果；公告送达传票，应当说明出庭的时间和地点及逾期不出庭的法律后果；公告送达判决书、裁定书的，应当说明裁判主要内容，当事人有权上诉的，还应当说明上诉权利、上诉期限和上诉的人民法院。"},{"i":140,"n":"第一百四十条","txt":"适用简易程序的案件，不适用公告送达。"},{"i":141,"n":"第一百四十一条","txt":"人民法院在定期宣判时，当事人拒不签收判决书、裁定书的，应视为送达，并在宣判笔录中记明。"},{"i":142,"n":"第一百四十二条","txt":"人民法院受理案件后，经审查，认为法律关系明确、事实清楚，在征得当事人双方同意后，可以径行调解。"},{"i":143,"n":"第一百四十三条","txt":"适用特别程序、督促程序、公示催告程序的案件，婚姻等身份关系确认案件以及其他根据案件性质不能进行调解的案件，不得调解。"},{"i":144,"n":"第一百四十四条","txt":"人民法院审理民事案件，发现当事人之间恶意串通，企图通过和解、调解方式侵害他人合法权益的，应当依照民事诉讼法第一百一十五条的规定处理。"},{"i":145,"n":"第一百四十五条","txt":"人民法院审理民事案件，应当根据自愿、合法的原则进行调解。当事人一方或者双方坚持不愿调解的，应当及时裁判。"},{"i":146,"n":"第一百四十六条","txt":"人民法院审理民事案件，调解过程不公开，但当事人同意公开的除外。"},{"i":147,"n":"第一百四十七条","txt":"人民法院调解案件时，当事人不能出庭的，经其特别授权，可由其委托代理人参加调解，达成的调解协议，可由委托代理人签名。"},{"i":148,"n":"第一百四十八条","txt":"当事人自行和解或者调解达成协议后，请求人民法院按照和解协议或者调解协议的内容制作判决书的，人民法院不予准许。"},{"i":149,"n":"第一百四十九条","txt":"调解书需经当事人签收后才发生法律效力的，应当以最后收到调解书的当事人签收的日期为调解书生效日期。"},{"i":150,"n":"第一百五十条","txt":"人民法院调解民事案件，需由无独立请求权的第三人承担责任的，应当经其同意。该第三人在调解书送达前反悔的，人民法院应当及时裁判。"},{"i":151,"n":"第一百五十一条","txt":"根据民事诉讼法第一百零一条第一款第四项规定，当事人各方同意在调解协议上签名或者盖章后即发生法律效力的，经人民法院审查确认后，应当记入笔录或者将调解协议附卷，并由当事人、审判人员、书记员签名或者盖章后即具有法律效力。"},{"i":152,"n":"第一百五十二条","txt":"人民法院依照民事诉讼法第一百零三条、第一百零四条规定，在采取诉前保全、诉讼保全措施时，责令利害关系人或者当事人提供担保的，应当书面通知。"},{"i":153,"n":"第一百五十三条","txt":"人民法院对季节性商品、鲜活、易腐烂变质以及其他不宜长期保存的物品采取保全措施时，可以责令当事人及时处理，由人民法院保存价款；必要时，人民法院可予以变卖，保存价款。"},{"i":154,"n":"第一百五十四条","txt":"人民法院在财产保全中采取查封、扣押、冻结财产措施时，应当妥善保管被查封、扣押、冻结的财产。不宜由人民法院保管的，人民法院可以指定被保全人负责保管；不宜由被保全人保管的，可以委托他人或者申请保全人保管。"},{"i":155,"n":"第一百五十五条","txt":"由人民法院指定被保全人保管的财产，如果继续使用对该财产的价值无重大影响，可以允许被保全人继续使用；由人民法院保管或者委托他人、申请保全人保管的财产，人民法院和其他保管人不得使用。"},{"i":156,"n":"第一百五十六条","txt":"人民法院采取财产保全的方法和措施，依照执行程序相关规定办理。"},{"i":157,"n":"第一百五十七条","txt":"人民法院对抵押物、质押物、留置物可以采取财产保全措施，但不影响抵押权人、质权人、留置权人的优先受偿权。"},{"i":158,"n":"第一百五十八条","txt":"人民法院对债务人到期应得的收益，可以采取财产保全措施，限制其支取，通知有关单位协助执行。"},{"i":159,"n":"第一百五十九条","txt":"债务人的财产不能满足保全请求，但对他人有到期债权的，人民法院可以依债权人的申请裁定该他人不得对本案债务人清偿。该他人要求偿付的，由人民法院提存财物或者价款。"},{"i":160,"n":"第一百六十条","txt":"当事人向采取诉前保全措施以外的其他有管辖权的人民法院起诉的，采取诉前保全措施的人民法院应当将保全手续移送受理案件的人民法院。诉前保全的裁定视为受移送人民法院作出的裁定。"},{"i":161,"n":"第一百六十一条","txt":"对当事人不服一审判决提起上诉的案件，在第二审人民法院接到报送的案件之前，当事人有转移、隐匿、出卖或者毁损财产等行为，必须采取保全措施的，由第一审人民法院依当事人申请或者依职权采取。第一审人民法院的保全裁定，应当及时报送第二审人民法院。"},{"i":162,"n":"第一百六十二条","txt":"第二审人民法院裁定对第一审人民法院采取的保全措施予以续保或者采取新的保全措施的，可以自行实施，也可以委托第一审人民法院实施。"},{"i":163,"n":"第一百六十三条","txt":"法律文书生效后，进入执行程序前，债权人因对方当事人转移财产等紧急情况，不申请保全将可能导致生效法律文书不能执行或者难以执行的，可以向执行法院申请采取保全措施。债权人在法律文书指定的履行期间届满后五日内不申请执行的，人民法院应当解除保全。"},{"i":164,"n":"第一百六十四条","txt":"对申请保全人或者他人提供的担保财产，人民法院应当依法办理查封、扣押、冻结等手续。"},{"i":165,"n":"第一百六十五条","txt":"人民法院裁定采取保全措施后，除作出保全裁定的人民法院自行解除或者其上级人民法院决定解除外，在保全期限内，任何单位不得解除保全措施。"},{"i":166,"n":"第一百六十六条","txt":"裁定采取保全措施后，有下列情形之一的，人民法院应当作出解除保全裁定："},{"i":167,"n":"第一百六十七条","txt":"财产保全的被保全人提供其他等值担保财产且有利于执行的，人民法院可以裁定变更保全标的物为被保全人提供的担保财产。"},{"i":168,"n":"第一百六十八条","txt":"保全裁定未经人民法院依法撤销或者解除，进入执行程序后，自动转为执行中的查封、扣押、冻结措施，期限连续计算，执行法院无需重新制作裁定书，但查封、扣押、冻结期限届满的除外。"},{"i":169,"n":"第一百六十九条","txt":"民事诉讼法规定的先予执行，人民法院应当在受理案件后终审判决作出前采取。先予执行应当限于当事人诉讼请求的范围，并以当事人的生活、生产经营的急需为限。"},{"i":170,"n":"第一百七十条","txt":"民事诉讼法第一百零九条第三项规定的情况紧急，包括："},{"i":171,"n":"第一百七十一条","txt":"当事人对保全或者先予执行裁定不服的，可以自收到裁定书之日起五日内向作出裁定的人民法院申请复议。人民法院应当在收到复议申请后十日内审查。裁定正确的，驳回当事人的申请；裁定不当的，变更或者撤销原裁定。"},{"i":172,"n":"第一百七十二条","txt":"利害关系人对保全或者先予执行的裁定不服申请复议的，由作出裁定的人民法院依照民事诉讼法第一百一十一条规定处理。"},{"i":173,"n":"第一百七十三条","txt":"人民法院先予执行后，根据发生法律效力的判决，申请人应当返还因先予执行所取得的利益的，适用民事诉讼法第二百四十条的规定。"},{"i":174,"n":"第一百七十四条","txt":"民事诉讼法第一百一十二条规定的必须到庭的被告，是指负有赡养、抚育、扶养义务和不到庭就无法查清案情的被告。"},{"i":175,"n":"第一百七十五条","txt":"拘传必须用拘传票，并直接送达被拘传人；在拘传前，应当向被拘传人说明拒不到庭的后果，经批评教育仍拒不到庭的，可以拘传其到庭。"},{"i":176,"n":"第一百七十六条","txt":"诉讼参与人或者其他人有下列行为之一的，人民法院可以适用民事诉讼法第一百一十三条规定处理："},{"i":177,"n":"第一百七十七条","txt":"训诫、责令退出法庭由合议庭或者独任审判员决定。训诫的内容、被责令退出法庭者的违法事实应当记入庭审笔录。"},{"i":178,"n":"第一百七十八条","txt":"人民法院依照民事诉讼法第一百一十三条至第一百一十七条的规定采取拘留措施的，应经院长批准，作出拘留决定书，由司法警察将被拘留人送交当地公安机关看管。"},{"i":179,"n":"第一百七十九条","txt":"被拘留人不在本辖区的，作出拘留决定的人民法院应当派员到被拘留人所在地的人民法院，请该院协助执行，受委托的人民法院应当及时派员协助执行。被拘留人申请复议或者在拘留期间承认并改正错误，需要提前解除拘留的，受委托人民法院应当向委托人民法院转达或者提出建议，由委托人民法院审查决定。"},{"i":180,"n":"第一百八十条","txt":"人民法院对被拘留人采取拘留措施后，应当在二十四小时内通知其家属；确实无法按时通知或者通知不到的，应当记录在案。"},{"i":181,"n":"第一百八十一条","txt":"因哄闹、冲击法庭，用暴力、威胁等方法抗拒执行公务等紧急情况，必须立即采取拘留措施的，可在拘留后，立即报告院长补办批准手续。院长认为拘留不当的，应当解除拘留。"},{"i":182,"n":"第一百八十二条","txt":"被拘留人在拘留期间认错悔改的，可以责令其具结悔过，提前解除拘留。提前解除拘留，应报经院长批准，并作出提前解除拘留决定书，交负责看管的公安机关执行。"},{"i":183,"n":"第一百八十三条","txt":"民事诉讼法第一百一十三条至第一百一十六条规定的罚款、拘留可以单独适用，也可以合并适用。"},{"i":184,"n":"第一百八十四条","txt":"对同一妨害民事诉讼行为的罚款、拘留不得连续适用。发生新的妨害民事诉讼行为的，人民法院可以重新予以罚款、拘留。"},{"i":185,"n":"第一百八十五条","txt":"被罚款、拘留的人不服罚款、拘留决定申请复议的，应当自收到决定书之日起三日内提出。上级人民法院应当在收到复议申请后五日内作出决定，并将复议结果通知下级人民法院和当事人。"},{"i":186,"n":"第一百八十六条","txt":"上级人民法院复议时认为强制措施不当的，应当制作决定书，撤销或者变更下级人民法院作出的拘留、罚款决定。情况紧急的，可以在口头通知后三日内发出决定书。"},{"i":187,"n":"第一百八十七条","txt":"民事诉讼法第一百一十四条第一款第五项规定的以暴力、威胁或者其他方法阻碍司法工作人员执行职务的行为，包括："},{"i":188,"n":"第一百八十八条","txt":"民事诉讼法第一百一十四条第一款第六项规定的拒不履行人民法院已经发生法律效力的判决、裁定的行为，包括："},{"i":189,"n":"第一百八十九条","txt":"诉讼参与人或者其他人有下列行为之一的，人民法院可以适用民事诉讼法第一百一十四条的规定处理："},{"i":190,"n":"第一百九十条","txt":"民事诉讼法第一百一十五条规定的他人合法权益，包括案外人的合法权益、国家利益、社会公共利益。"},{"i":191,"n":"第一百九十一条","txt":"单位有民事诉讼法第一百一十五条或者第一百一十六条规定行为的，人民法院应当对该单位进行罚款，并可以对其主要负责人或者直接责任人员予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":192,"n":"第一百九十二条","txt":"有关单位接到人民法院协助执行通知书后，有下列行为之一的，人民法院可以适用民事诉讼法第一百一十七条规定处理："},{"i":193,"n":"第一百九十三条","txt":"人民法院对个人或者单位采取罚款措施时，应当根据其实施妨害民事诉讼行为的性质、情节、后果，当地的经济发展水平，以及诉讼标的额等因素，在民事诉讼法第一百一十八条第一款规定的限额内确定相应的罚款金额。"},{"i":194,"n":"第一百九十四条","txt":"依照民事诉讼法第五十七条审理的案件不预交案件受理费，结案后按照诉讼标的额由败诉方交纳。"},{"i":195,"n":"第一百九十五条","txt":"支付令失效后转入诉讼程序的，债权人应当按照《诉讼费用交纳办法》补交案件受理费。"},{"i":196,"n":"第一百九十六条","txt":"人民法院改变原判决、裁定、调解结果的，应当在裁判文书中对原审诉讼费用的负担一并作出处理。"},{"i":197,"n":"第一百九十七条","txt":"诉讼标的物是证券的，按照证券交易规则并根据当事人起诉之日前最后一个交易日的收盘价、当日的市场价或者其载明的金额计算诉讼标的金额。"},{"i":198,"n":"第一百九十八条","txt":"诉讼标的物是房屋、土地、林木、车辆、船舶、文物等特定物或者知识产权，起诉时价值难以确定的，人民法院应当向原告释明主张过高或者过低的诉讼风险，以原告主张的价值确定诉讼标的金额。"},{"i":199,"n":"第一百九十九条","txt":"适用简易程序审理的案件转为普通程序的，原告自接到人民法院交纳诉讼费用通知之日起七日内补交案件受理费。"},{"i":200,"n":"第二百条","txt":"破产程序中有关债务人的民事诉讼案件，按照财产案件标准交纳诉讼费，但劳动争议案件除外。"},{"i":201,"n":"第二百零一条","txt":"既有财产性诉讼请求，又有非财产性诉讼请求的，按照财产性诉讼请求的标准交纳诉讼费。"},{"i":202,"n":"第二百零二条","txt":"原告、被告、第三人分别上诉的，按照上诉请求分别预交二审案件受理费。"},{"i":203,"n":"第二百零三条","txt":"承担连带责任的当事人败诉的，应当共同负担诉讼费用。"},{"i":204,"n":"第二百零四条","txt":"实现担保物权案件，人民法院裁定拍卖、变卖担保财产的，申请费由债务人、担保人负担；人民法院裁定驳回申请的，申请费由申请人负担。"},{"i":205,"n":"第二百零五条","txt":"拍卖、变卖担保财产的裁定作出后，人民法院强制执行的，按照执行金额收取执行申请费。"},{"i":206,"n":"第二百零六条","txt":"人民法院决定减半收取案件受理费的，只能减半一次。"},{"i":207,"n":"第二百零七条","txt":"判决生效后，胜诉方预交但不应负担的诉讼费用，人民法院应当退还，由败诉方向人民法院交纳，但胜诉方自愿承担或者同意败诉方直接向其支付的除外。"},{"i":208,"n":"第二百零八条","txt":"人民法院接到当事人提交的民事起诉状时，对符合民事诉讼法第一百二十二条的规定，且不属于第一百二十七条规定情形的，应当登记立案；对当场不能判定是否符合起诉条件的，应当接收起诉材料，并出具注明收到日期的书面凭证。"},{"i":209,"n":"第二百零九条","txt":"原告提供被告的姓名或者名称、住所等信息具体明确，足以使被告与他人相区别的，可以认定为有明确的被告。"},{"i":210,"n":"第二百一十条","txt":"原告在起诉状中有谩骂和人身攻击之辞的，人民法院应当告知其修改后提起诉讼。"},{"i":211,"n":"第二百一十一条","txt":"对本院没有管辖权的案件，告知原告向有管辖权的人民法院起诉；原告坚持起诉的，裁定不予受理；立案后发现本院没有管辖权的，应当将案件移送有管辖权的人民法院。"},{"i":212,"n":"第二百一十二条","txt":"裁定不予受理、驳回起诉的案件，原告再次起诉，符合起诉条件且不属于民事诉讼法第一百二十七条规定情形的，人民法院应予受理。"},{"i":213,"n":"第二百一十三条","txt":"原告应当预交而未预交案件受理费，人民法院应当通知其预交，通知后仍不预交或者申请减、缓、免未获批准而仍不预交的，裁定按撤诉处理。"},{"i":214,"n":"第二百一十四条","txt":"原告撤诉或者人民法院按撤诉处理后，原告以同一诉讼请求再次起诉的，人民法院应予受理。"},{"i":215,"n":"第二百一十五条","txt":"依照民事诉讼法第一百二十七条第二项的规定，当事人在书面合同中订有仲裁条款，或者在发生纠纷后达成书面仲裁协议，一方向人民法院起诉的，人民法院应当告知原告向仲裁机构申请仲裁，其坚持起诉的，裁定不予受理，但仲裁条款或者仲裁协议不成立、无效、失效、内容不明确无法执行的除外。"},{"i":216,"n":"第二百一十六条","txt":"在人民法院首次开庭前，被告以有书面仲裁协议为由对受理民事案件提出异议的，人民法院应当进行审查。"},{"i":217,"n":"第二百一十七条","txt":"夫妻一方下落不明，另一方诉至人民法院，只要求离婚，不申请宣告下落不明人失踪或者死亡的案件，人民法院应当受理，对下落不明人公告送达诉讼文书。"},{"i":218,"n":"第二百一十八条","txt":"赡养费、扶养费、抚养费案件，裁判发生法律效力后，因新情况、新理由，一方当事人再行起诉要求增加或者减少费用的，人民法院应作为新案受理。"},{"i":219,"n":"第二百一十九条","txt":"当事人超过诉讼时效期间起诉的，人民法院应予受理。受理后对方当事人提出诉讼时效抗辩，人民法院经审理认为抗辩事由成立的，判决驳回原告的诉讼请求。"},{"i":220,"n":"第二百二十条","txt":"民事诉讼法第七十一条、第一百三十七条、第一百五十九条规定的商业秘密，是指生产工艺、配方、贸易联系、购销渠道等当事人不愿公开的技术秘密、商业情报及信息。"},{"i":221,"n":"第二百二十一条","txt":"基于同一事实发生的纠纷，当事人分别向同一人民法院起诉的，人民法院可以合并审理。"},{"i":222,"n":"第二百二十二条","txt":"原告在起诉状中直接列写第三人的，视为其申请人民法院追加该第三人参加诉讼。是否通知第三人参加诉讼，由人民法院审查决定。"},{"i":223,"n":"第二百二十三条","txt":"当事人在提交答辩状期间提出管辖异议，又针对起诉状的内容进行答辩的，人民法院应当依照民事诉讼法第一百三十条第一款的规定，对管辖异议进行审查。"},{"i":224,"n":"第二百二十四条","txt":"依照民事诉讼法第一百三十六条第四项规定，人民法院可以在答辩期届满后，通过组织证据交换、召集庭前会议等方式，作好审理前的准备。"},{"i":225,"n":"第二百二十五条","txt":"根据案件具体情况，庭前会议可以包括下列内容："},{"i":226,"n":"第二百二十六条","txt":"人民法院应当根据当事人的诉讼请求、答辩意见以及证据交换的情况，归纳争议焦点，并就归纳的争议焦点征求当事人的意见。"},{"i":227,"n":"第二百二十七条","txt":"人民法院适用普通程序审理案件，应当在开庭三日前用传票传唤当事人。对诉讼代理人、证人、鉴定人、勘验人、翻译人员应当用通知书通知其到庭。当事人或者其他诉讼参与人在外地的，应当留有必要的在途时间。"},{"i":228,"n":"第二百二十八条","txt":"法庭审理应当围绕当事人争议的事实、证据和法律适用等焦点问题进行。"},{"i":229,"n":"第二百二十九条","txt":"当事人在庭审中对其在审理前的准备阶段认可的事实和证据提出不同意见的，人民法院应当责令其说明理由。必要时，可以责令其提供相应证据。人民法院应当结合当事人的诉讼能力、证据和案件的具体情况进行审查。理由成立的，可以列入争议焦点进行审理。"},{"i":230,"n":"第二百三十条","txt":"人民法院根据案件具体情况并征得当事人同意，可以将法庭调查和法庭辩论合并进行。"},{"i":231,"n":"第二百三十一条","txt":"当事人在法庭上提出新的证据的，人民法院应当依照民事诉讼法第六十八条第二款规定和本解释相关规定处理。"},{"i":232,"n":"第二百三十二条","txt":"在案件受理后，法庭辩论结束前，原告增加诉讼请求，被告提出反诉，第三人提出与本案有关的诉讼请求，可以合并审理的，人民法院应当合并审理。"},{"i":233,"n":"第二百三十三条","txt":"反诉的当事人应当限于本诉的当事人的范围。"},{"i":234,"n":"第二百三十四条","txt":"无民事行为能力人的离婚诉讼，当事人的法定代理人应当到庭；法定代理人不能到庭的，人民法院应当在查清事实的基础上，依法作出判决。"},{"i":235,"n":"第二百三十五条","txt":"无民事行为能力的当事人的法定代理人，经传票传唤无正当理由拒不到庭，属于原告方的，比照民事诉讼法第一百四十六条的规定，按撤诉处理；属于被告方的，比照民事诉讼法第一百四十七条的规定，缺席判决。必要时，人民法院可以拘传其到庭。"},{"i":236,"n":"第二百三十六条","txt":"有独立请求权的第三人经人民法院传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，比照民事诉讼法第一百四十六条的规定，按撤诉处理。"},{"i":237,"n":"第二百三十七条","txt":"有独立请求权的第三人参加诉讼后，原告申请撤诉，人民法院在准许原告撤诉后，有独立请求权的第三人作为另案原告，原案原告、被告作为另案被告，诉讼继续进行。"},{"i":238,"n":"第二百三十八条","txt":"当事人申请撤诉或者依法可以按撤诉处理的案件，如果当事人有违反法律的行为需要依法处理的，人民法院可以不准许撤诉或者不按撤诉处理。"},{"i":239,"n":"第二百三十九条","txt":"人民法院准许本诉原告撤诉的，应当对反诉继续审理；被告申请撤回反诉的，人民法院应予准许。"},{"i":240,"n":"第二百四十条","txt":"无独立请求权的第三人经人民法院传票传唤，无正当理由拒不到庭，或者未经法庭许可中途退庭的，不影响案件的审理。"},{"i":241,"n":"第二百四十一条","txt":"被告经传票传唤无正当理由拒不到庭，或者未经法庭许可中途退庭的，人民法院应当按期开庭或者继续开庭审理，对到庭的当事人诉讼请求、双方的诉辩理由以及已经提交的证据及其他诉讼材料进行审理后，可以依法缺席判决。"},{"i":242,"n":"第二百四十二条","txt":"一审宣判后，原审人民法院发现判决有错误，当事人在上诉期内提出上诉的，原审人民法院可以提出原判决有错误的意见，报送第二审人民法院，由第二审人民法院按照第二审程序进行审理；当事人不上诉的，按照审判监督程序处理。"},{"i":243,"n":"第二百四十三条","txt":"民事诉讼法第一百五十二条规定的审限，是指从立案之日起至裁判宣告、调解书送达之日止的期间，但公告期间、鉴定期间、双方当事人和解期间、审理当事人提出的管辖异议以及处理人民法院之间的管辖争议期间不应计算在内。"},{"i":244,"n":"第二百四十四条","txt":"可以上诉的判决书、裁定书不能同时送达双方当事人的，上诉期从各自收到判决书、裁定书之日计算。"},{"i":245,"n":"第二百四十五条","txt":"民事诉讼法第一百五十七条第一款第七项规定的笔误是指法律文书误写、误算，诉讼费用漏写、误算和其他笔误。"},{"i":246,"n":"第二百四十六条","txt":"裁定中止诉讼的原因消除，恢复诉讼程序时，不必撤销原裁定，从人民法院通知或者准许当事人双方继续进行诉讼时起，中止诉讼的裁定即失去效力。"},{"i":247,"n":"第二百四十七条","txt":"当事人就已经提起诉讼的事项在诉讼过程中或者裁判生效后再次起诉，同时符合下列条件的，构成重复起诉："},{"i":248,"n":"第二百四十八条","txt":"裁判发生法律效力后，发生新的事实，当事人再次提起诉讼的，人民法院应当依法受理。"},{"i":249,"n":"第二百四十九条","txt":"在诉讼中，争议的民事权利义务转移的，不影响当事人的诉讼主体资格和诉讼地位。人民法院作出的发生法律效力的判决、裁定对受让人具有拘束力。"},{"i":250,"n":"第二百五十条","txt":"依照本解释第二百四十九条规定，人民法院准许受让人替代当事人承担诉讼的，裁定变更当事人。"},{"i":251,"n":"第二百五十一条","txt":"二审裁定撤销一审判决发回重审的案件，当事人申请变更、增加诉讼请求或者提出反诉，第三人提出与本案有关的诉讼请求的，依照民事诉讼法第一百四十三条规定处理。"},{"i":252,"n":"第二百五十二条","txt":"再审裁定撤销原判决、裁定发回重审的案件，当事人申请变更、增加诉讼请求或者提出反诉，符合下列情形之一的，人民法院应当准许："},{"i":253,"n":"第二百五十三条","txt":"当庭宣判的案件，除当事人当庭要求邮寄发送裁判文书的外，人民法院应当告知当事人或者诉讼代理人领取裁判文书的时间和地点以及逾期不领取的法律后果。上述情况，应当记入笔录。"},{"i":254,"n":"第二百五十四条","txt":"公民、法人或者其他组织申请查阅发生法律效力的判决书、裁定书的，应当向作出该生效裁判的人民法院提出。申请应当以书面形式提出，并提供具体的案号或者当事人姓名、名称。"},{"i":255,"n":"第二百五十五条","txt":"对于查阅判决书、裁定书的申请，人民法院根据下列情形分别处理："},{"i":256,"n":"第二百五十六条","txt":"民事诉讼法第一百六十条规定的简单民事案件中的事实清楚，是指当事人对争议的事实陈述基本一致，并能提供相应的证据，无须人民法院调查收集证据即可查明事实；权利义务关系明确是指能明确区分谁是责任的承担者，谁是权利的享有者；争议不大是指当事人对案件的是非、责任承担以及诉讼标的争执无原则分歧。"},{"i":257,"n":"第二百五十七条","txt":"下列案件，不适用简易程序："},{"i":258,"n":"第二百五十八条","txt":"适用简易程序审理的案件，审理期限到期后，有特殊情况需要延长的，经本院院长批准，可以延长审理期限。延长后的审理期限累计不得超过四个月。"},{"i":259,"n":"第二百五十九条","txt":"当事人双方可就开庭方式向人民法院提出申请，由人民法院决定是否准许。经当事人双方同意，可以采用视听传输技术等方式开庭。"},{"i":260,"n":"第二百六十条","txt":"已经按照普通程序审理的案件，在开庭后不得转为简易程序审理。"},{"i":261,"n":"第二百六十一条","txt":"适用简易程序审理案件，人民法院可以依照民事诉讼法第九十条、第一百六十二条的规定采取捎口信、电话、短信、传真、电子邮件等简便方式传唤双方当事人、通知证人和送达诉讼文书。"},{"i":262,"n":"第二百六十二条","txt":"人民法庭制作的判决书、裁定书、调解书，必须加盖基层人民法院印章，不得用人民法庭的印章代替基层人民法院的印章。"},{"i":263,"n":"第二百六十三条","txt":"适用简易程序审理案件，卷宗中应当具备以下材料："},{"i":264,"n":"第二百六十四条","txt":"当事人双方根据民事诉讼法第一百六十条第二款规定约定适用简易程序的，应当在开庭前提出。口头提出的，记入笔录，由双方当事人签名或者捺印确认。"},{"i":265,"n":"第二百六十五条","txt":"原告口头起诉的，人民法院应当将当事人的姓名、性别、工作单位、住所、联系方式等基本信息，诉讼请求，事实及理由等准确记入笔录，由原告核对无误后签名或者捺印。对当事人提交的证据材料，应当出具收据。"},{"i":266,"n":"第二百六十六条","txt":"适用简易程序案件的举证期限由人民法院确定，也可以由当事人协商一致并经人民法院准许，但不得超过十五日。被告要求书面答辩的，人民法院可在征得其同意的基础上，合理确定答辩期间。"},{"i":267,"n":"第二百六十七条","txt":"适用简易程序审理案件，可以简便方式进行审理前的准备。"},{"i":268,"n":"第二百六十八条","txt":"对没有委托律师、基层法律服务工作者代理诉讼的当事人，人民法院在庭审过程中可以对回避、自认、举证证明责任等相关内容向其作必要的解释或者说明，并在庭审过程中适当提示当事人正确行使诉讼权利、履行诉讼义务。"},{"i":269,"n":"第二百六十九条","txt":"当事人就案件适用简易程序提出异议，人民法院经审查，异议成立的，裁定转为普通程序；异议不成立的，裁定驳回。裁定以口头方式作出的，应当记入笔录。"},{"i":270,"n":"第二百七十条","txt":"适用简易程序审理的案件，有下列情形之一的，人民法院在制作判决书、裁定书、调解书时，对认定事实或者裁判理由部分可以适当简化："},{"i":271,"n":"第二百七十一条","txt":"人民法院审理小额诉讼案件，适用民事诉讼法第一百六十五条的规定，实行一审终审。"},{"i":272,"n":"第二百七十二条","txt":"民事诉讼法第一百六十五条规定的各省、自治区、直辖市上年度就业人员年平均工资，是指已经公布的各省、自治区、直辖市上一年度就业人员年平均工资。在上一年度就业人员年平均工资公布前，以已经公布的最近年度就业人员年平均工资为准。"},{"i":273,"n":"第二百七十三条","txt":"海事法院可以适用小额诉讼的程序审理海事、海商案件。案件标的额应当以实际受理案件的海事法院或者其派出法庭所在的省、自治区、直辖市上年度就业人员年平均工资为基数计算。"},{"i":274,"n":"第二百七十四条","txt":"人民法院受理小额诉讼案件，应当向当事人告知该类案件的审判组织、一审终审、审理期限、诉讼费用交纳标准等相关事项。"},{"i":275,"n":"第二百七十五条","txt":"小额诉讼案件的举证期限由人民法院确定，也可以由当事人协商一致并经人民法院准许，但一般不超过七日。"},{"i":276,"n":"第二百七十六条","txt":"当事人对小额诉讼案件提出管辖异议的，人民法院应当作出裁定。裁定一经作出即生效。"},{"i":277,"n":"第二百七十七条","txt":"人民法院受理小额诉讼案件后，发现起诉不符合民事诉讼法第一百二十二条规定的起诉条件的，裁定驳回起诉。裁定一经作出即生效。"},{"i":278,"n":"第二百七十八条","txt":"因当事人申请增加或者变更诉讼请求、提出反诉、追加当事人等，致使案件不符合小额诉讼案件条件的，应当适用简易程序的其他规定审理。"},{"i":279,"n":"第二百七十九条","txt":"当事人对按照小额诉讼案件审理有异议的，应当在开庭前提出。人民法院经审查，异议成立的，适用简易程序的其他规定审理或者裁定转为普通程序；异议不成立的，裁定驳回。裁定以口头方式作出的，应当记入笔录。"},{"i":280,"n":"第二百八十条","txt":"小额诉讼案件的裁判文书可以简化，主要记载当事人基本信息、诉讼请求、裁判主文等内容。"},{"i":281,"n":"第二百八十一条","txt":"人民法院审理小额诉讼案件，本解释没有规定的，适用简易程序的其他规定。"},{"i":282,"n":"第二百八十二条","txt":"环境保护法、消费者权益保护法等法律规定的机关和有关组织对污染环境、侵害众多消费者合法权益等损害社会公共利益的行为，根据民事诉讼法第五十八条规定提起公益诉讼，符合下列条件的，人民法院应当受理："},{"i":283,"n":"第二百八十三条","txt":"公益诉讼案件由侵权行为地或者被告住所地中级人民法院管辖，但法律、司法解释另有规定的除外。"},{"i":284,"n":"第二百八十四条","txt":"人民法院受理公益诉讼案件后，应当在十日内书面告知相关行政主管部门。"},{"i":285,"n":"第二百八十五条","txt":"人民法院受理公益诉讼案件后，依法可以提起诉讼的其他机关和有关组织，可以在开庭前向人民法院申请参加诉讼。人民法院准许参加诉讼的，列为共同原告。"},{"i":286,"n":"第二百八十六条","txt":"人民法院受理公益诉讼案件，不影响同一侵权行为的受害人根据民事诉讼法第一百二十二条规定提起诉讼。"},{"i":287,"n":"第二百八十七条","txt":"对公益诉讼案件，当事人可以和解，人民法院可以调解。"},{"i":288,"n":"第二百八十八条","txt":"公益诉讼案件的原告在法庭辩论终结后申请撤诉的，人民法院不予准许。"},{"i":289,"n":"第二百八十九条","txt":"公益诉讼案件的裁判发生法律效力后，其他依法具有原告资格的机关和有关组织就同一侵权行为另行提起公益诉讼的，人民法院裁定不予受理，但法律、司法解释另有规定的除外。"},{"i":290,"n":"第二百九十条","txt":"第三人对已经发生法律效力的判决、裁定、调解书提起撤销之诉的，应当自知道或者应当知道其民事权益受到损害之日起六个月内，向作出生效判决、裁定、调解书的人民法院提出，并应当提供存在下列情形的证据材料："},{"i":291,"n":"第二百九十一条","txt":"人民法院应当在收到起诉状和证据材料之日起五日内送交对方当事人，对方当事人可以自收到起诉状之日起十日内提出书面意见。"},{"i":292,"n":"第二百九十二条","txt":"人民法院对第三人撤销之诉案件，应当组成合议庭开庭审理。"},{"i":293,"n":"第二百九十三条","txt":"民事诉讼法第五十九条第三款规定的因不能归责于本人的事由未参加诉讼，是指没有被列为生效判决、裁定、调解书当事人，且无过错或者无明显过错的情形。包括："},{"i":294,"n":"第二百九十四条","txt":"民事诉讼法第五十九条第三款规定的判决、裁定、调解书的部分或者全部内容，是指判决、裁定的主文，调解书中处理当事人民事权利义务的结果。"},{"i":295,"n":"第二百九十五条","txt":"对下列情形提起第三人撤销之诉的，人民法院不予受理："},{"i":296,"n":"第二百九十六条","txt":"第三人提起撤销之诉，人民法院应当将该第三人列为原告，生效判决、裁定、调解书的当事人列为被告，但生效判决、裁定、调解书中没有承担责任的无独立请求权的第三人列为第三人。"},{"i":297,"n":"第二百九十七条","txt":"受理第三人撤销之诉案件后，原告提供相应担保，请求中止执行的，人民法院可以准许。"},{"i":298,"n":"第二百九十八条","txt":"对第三人撤销或者部分撤销发生法律效力的判决、裁定、调解书内容的请求，人民法院经审理，按下列情形分别处理："},{"i":299,"n":"第二百九十九条","txt":"第三人撤销之诉案件审理期间，人民法院对生效判决、裁定、调解书裁定再审的，受理第三人撤销之诉的人民法院应当裁定将第三人的诉讼请求并入再审程序。但有证据证明原审当事人之间恶意串通损害第三人合法权益的，人民法院应当先行审理第三人撤销之诉案件，裁定中止再审诉讼。"},{"i":300,"n":"第三百条","txt":"第三人诉讼请求并入再审程序审理的，按照下列情形分别处理："},{"i":301,"n":"第三百零一条","txt":"第三人提起撤销之诉后，未中止生效判决、裁定、调解书执行的，执行法院对第三人依照民事诉讼法第二百三十四条规定提出的执行异议，应予审查。第三人不服驳回执行异议裁定，申请对原判决、裁定、调解书再审的，人民法院不予受理。"},{"i":302,"n":"第三百零二条","txt":"根据民事诉讼法第二百三十四条规定，案外人、当事人对执行异议裁定不服，自裁定送达之日起十五日内向人民法院提起执行异议之诉的，由执行法院管辖。"},{"i":303,"n":"第三百零三条","txt":"案外人提起执行异议之诉，除符合民事诉讼法第一百二十二条规定外，还应当具备下列条件："},{"i":304,"n":"第三百零四条","txt":"申请执行人提起执行异议之诉，除符合民事诉讼法第一百二十二条规定外，还应当具备下列条件："},{"i":305,"n":"第三百零五条","txt":"案外人提起执行异议之诉的，以申请执行人为被告。被执行人反对案外人异议的，被执行人为共同被告；被执行人不反对案外人异议的，可以列被执行人为第三人。"},{"i":306,"n":"第三百零六条","txt":"申请执行人提起执行异议之诉的，以案外人为被告。被执行人反对申请执行人主张的，以案外人和被执行人为共同被告；被执行人不反对申请执行人主张的，可以列被执行人为第三人。"},{"i":307,"n":"第三百零七条","txt":"申请执行人对中止执行裁定未提起执行异议之诉，被执行人提起执行异议之诉的，人民法院告知其另行起诉。"},{"i":308,"n":"第三百零八条","txt":"人民法院审理执行异议之诉案件，适用普通程序。"},{"i":309,"n":"第三百零九条","txt":"案外人或者申请执行人提起执行异议之诉的，案外人应当就其对执行标的享有足以排除强制执行的民事权益承担举证证明责任。"},{"i":310,"n":"第三百一十条","txt":"对案外人提起的执行异议之诉，人民法院经审理，按照下列情形分别处理："},{"i":311,"n":"第三百一十一条","txt":"对申请执行人提起的执行异议之诉，人民法院经审理，按照下列情形分别处理："},{"i":312,"n":"第三百一十二条","txt":"对案外人执行异议之诉，人民法院判决不得对执行标的执行的，执行异议裁定失效。"},{"i":313,"n":"第三百一十三条","txt":"案外人执行异议之诉审理期间，人民法院不得对执行标的进行处分。申请执行人请求人民法院继续执行并提供相应担保的，人民法院可以准许。"},{"i":314,"n":"第三百一十四条","txt":"人民法院对执行标的裁定中止执行后，申请执行人在法律规定的期间内未提起执行异议之诉的，人民法院应当自起诉期限届满之日起七日内解除对该执行标的采取的执行措施。"},{"i":315,"n":"第三百一十五条","txt":"双方当事人和第三人都提起上诉的，均列为上诉人。人民法院可以依职权确定第二审程序中当事人的诉讼地位。"},{"i":316,"n":"第三百一十六条","txt":"民事诉讼法第一百七十三条、第一百七十四条规定的对方当事人包括被上诉人和原审其他当事人。"},{"i":317,"n":"第三百一十七条","txt":"必要共同诉讼人的一人或者部分人提起上诉的，按下列情形分别处理："},{"i":318,"n":"第三百一十八条","txt":"一审宣判时或者判决书、裁定书送达时，当事人口头表示上诉的，人民法院应告知其必须在法定上诉期间内递交上诉状。未在法定上诉期间内递交上诉状的，视为未提起上诉。虽递交上诉状，但未在指定的期限内交纳上诉费的，按自动撤回上诉处理。"},{"i":319,"n":"第三百一十九条","txt":"无民事行为能力人、限制民事行为能力人的法定代理人，可以代理当事人提起上诉。"},{"i":320,"n":"第三百二十条","txt":"上诉案件的当事人死亡或者终止的，人民法院依法通知其权利义务承继者参加诉讼。"},{"i":321,"n":"第三百二十一条","txt":"第二审人民法院应当围绕当事人的上诉请求进行审理。"},{"i":322,"n":"第三百二十二条","txt":"开庭审理的上诉案件，第二审人民法院可以依照民事诉讼法第一百三十六条第四项规定进行审理前的准备。"},{"i":323,"n":"第三百二十三条","txt":"下列情形，可以认定为民事诉讼法第一百七十七条第一款第四项规定的严重违反法定程序："},{"i":324,"n":"第三百二十四条","txt":"对当事人在第一审程序中已经提出的诉讼请求，原审人民法院未作审理、判决的，第二审人民法院可以根据当事人自愿的原则进行调解；调解不成的，发回重审。"},{"i":325,"n":"第三百二十五条","txt":"必须参加诉讼的当事人或者有独立请求权的第三人，在第一审程序中未参加诉讼，第二审人民法院可以根据当事人自愿的原则予以调解；调解不成的，发回重审。"},{"i":326,"n":"第三百二十六条","txt":"在第二审程序中，原审原告增加独立的诉讼请求或者原审被告提出反诉的，第二审人民法院可以根据当事人自愿的原则就新增加的诉讼请求或者反诉进行调解；调解不成的，告知当事人另行起诉。"},{"i":327,"n":"第三百二十七条","txt":"一审判决不准离婚的案件，上诉后，第二审人民法院认为应当判决离婚的，可以根据当事人自愿的原则，与子女抚养、财产问题一并调解；调解不成的，发回重审。"},{"i":328,"n":"第三百二十八条","txt":"人民法院依照第二审程序审理案件，认为依法不应由人民法院受理的，可以由第二审人民法院直接裁定撤销原裁判，驳回起诉。"},{"i":329,"n":"第三百二十九条","txt":"人民法院依照第二审程序审理案件，认为第一审人民法院受理案件违反专属管辖规定的，应当裁定撤销原裁判并移送有管辖权的人民法院。"},{"i":330,"n":"第三百三十条","txt":"第二审人民法院查明第一审人民法院作出的不予受理裁定有错误的，应当在撤销原裁定的同时，指令第一审人民法院立案受理；查明第一审人民法院作出的驳回起诉裁定有错误的，应当在撤销原裁定的同时，指令第一审人民法院审理。"},{"i":331,"n":"第三百三十一条","txt":"第二审人民法院对下列上诉案件，依照民事诉讼法第一百七十六条规定可以不开庭审理："},{"i":332,"n":"第三百三十二条","txt":"原判决、裁定认定事实或者适用法律虽有瑕疵，但裁判结果正确的，第二审人民法院可以在判决、裁定中纠正瑕疵后，依照民事诉讼法第一百七十七条第一款第一项规定予以维持。"},{"i":333,"n":"第三百三十三条","txt":"民事诉讼法第一百七十七条第一款第三项规定的基本事实，是指用以确定当事人主体资格、案件性质、民事权利义务等对原判决、裁定的结果有实质性影响的事实。"},{"i":334,"n":"第三百三十四条","txt":"在第二审程序中，作为当事人的法人或者其他组织分立的，人民法院可以直接将分立后的法人或者其他组织列为共同诉讼人；合并的，将合并后的法人或者其他组织列为当事人。"},{"i":335,"n":"第三百三十五条","txt":"在第二审程序中，当事人申请撤回上诉，人民法院经审查认为一审判决确有错误，或者当事人之间恶意串通损害国家利益、社会公共利益、他人合法权益的，不应准许。"},{"i":336,"n":"第三百三十六条","txt":"在第二审程序中，原审原告申请撤回起诉，经其他当事人同意，且不损害国家利益、社会公共利益、他人合法权益的，人民法院可以准许。准许撤诉的，应当一并裁定撤销一审裁判。"},{"i":337,"n":"第三百三十七条","txt":"当事人在第二审程序中达成和解协议的，人民法院可以根据当事人的请求，对双方达成的和解协议进行审查并制作调解书送达当事人；因和解而申请撤诉，经审查符合撤诉条件的，人民法院应予准许。"},{"i":338,"n":"第三百三十八条","txt":"第二审人民法院宣告判决可以自行宣判，也可以委托原审人民法院或者当事人所在地人民法院代行宣判。"},{"i":339,"n":"第三百三十九条","txt":"人民法院审理对裁定的上诉案件，应当在第二审立案之日起三十日内作出终审裁定。有特殊情况需要延长审限的，由本院院长批准。"},{"i":340,"n":"第三百四十条","txt":"当事人在第一审程序中实施的诉讼行为，在第二审程序中对该当事人仍具有拘束力。"},{"i":341,"n":"第三百四十一条","txt":"宣告失踪或者宣告死亡案件，人民法院可以根据申请人的请求，清理下落不明人的财产，并指定案件审理期间的财产管理人。公告期满后，人民法院判决宣告失踪的，应当同时依照民法典第四十二条的规定指定失踪人的财产代管人。"},{"i":342,"n":"第三百四十二条","txt":"失踪人的财产代管人经人民法院指定后，代管人申请变更代管的，比照民事诉讼法特别程序的有关规定进行审理。申请理由成立的，裁定撤销申请人的代管人身份，同时另行指定财产代管人；申请理由不成立的，裁定驳回申请。"},{"i":343,"n":"第三百四十三条","txt":"人民法院判决宣告公民失踪后，利害关系人向人民法院申请宣告失踪人死亡，自失踪之日起满四年的，人民法院应当受理，宣告失踪的判决即是该公民失踪的证明，审理中仍应依照民事诉讼法第一百九十二条规定进行公告。"},{"i":344,"n":"第三百四十四条","txt":"符合法律规定的多个利害关系人提出宣告失踪、宣告死亡申请的，列为共同申请人。"},{"i":345,"n":"第三百四十五条","txt":"寻找下落不明人的公告应当记载下列内容："},{"i":346,"n":"第三百四十六条","txt":"人民法院受理宣告失踪、宣告死亡案件后，作出判决前，申请人撤回申请的，人民法院应当裁定终结案件，但其他符合法律规定的利害关系人加入程序要求继续审理的除外。"},{"i":347,"n":"第三百四十七条","txt":"在诉讼中，当事人的利害关系人或者有关组织提出该当事人不能辨认或者不能完全辨认自己的行为，要求宣告该当事人无民事行为能力或者限制民事行为能力的，应由利害关系人或者有关组织向人民法院提出申请，由受诉人民法院按照特别程序立案审理，原诉讼中止。"},{"i":348,"n":"第三百四十八条","txt":"认定财产无主案件，公告期间有人对财产提出请求的，人民法院应当裁定终结特别程序，告知申请人另行起诉，适用普通程序审理。"},{"i":349,"n":"第三百四十九条","txt":"被指定的监护人不服居民委员会、村民委员会或者民政部门指定，应当自接到通知之日起三十日内向人民法院提出异议。经审理，认为指定并无不当的，裁定驳回异议；指定不当的，判决撤销指定，同时另行指定监护人。判决书应当送达异议人、原指定单位及判决指定的监护人。"},{"i":350,"n":"第三百五十条","txt":"申请认定公民无民事行为能力或者限制民事行为能力的案件，被申请人没有近亲属的，人民法院可以指定经被申请人住所地的居民委员会、村民委员会或者民政部门同意，且愿意担任代理人的个人或者组织为代理人。"},{"i":351,"n":"第三百五十一条","txt":"申请司法确认调解协议的，双方当事人应当本人或者由符合民事诉讼法第六十一条规定的代理人依照民事诉讼法第二百零一条的规定提出申请。"},{"i":352,"n":"第三百五十二条","txt":"调解组织自行开展的调解，有两个以上调解组织参与的，符合民事诉讼法第二百零一条规定的各调解组织所在地人民法院均有管辖权。"},{"i":353,"n":"第三百五十三条","txt":"当事人申请司法确认调解协议，可以采用书面形式或者口头形式。当事人口头申请的，人民法院应当记入笔录，并由当事人签名、捺印或者盖章。"},{"i":354,"n":"第三百五十四条","txt":"当事人申请司法确认调解协议，应当向人民法院提交调解协议、调解组织主持调解的证明，以及与调解协议相关的财产权利证明等材料，并提供双方当事人的身份、住所、联系方式等基本信息。"},{"i":355,"n":"第三百五十五条","txt":"当事人申请司法确认调解协议，有下列情形之一的，人民法院裁定不予受理："},{"i":356,"n":"第三百五十六条","txt":"人民法院审查相关情况时，应当通知双方当事人共同到场对案件进行核实。"},{"i":357,"n":"第三百五十七条","txt":"确认调解协议的裁定作出前，当事人撤回申请的，人民法院可以裁定准许。"},{"i":358,"n":"第三百五十八条","txt":"经审查，调解协议有下列情形之一的，人民法院应当裁定驳回申请："},{"i":359,"n":"第三百五十九条","txt":"民事诉讼法第二百零三条规定的担保物权人，包括抵押权人、质权人、留置权人；其他有权请求实现担保物权的人，包括抵押人、出质人、财产被留置的债务人或者所有权人等。"},{"i":360,"n":"第三百六十条","txt":"实现票据、仓单、提单等有权利凭证的权利质权案件，可以由权利凭证持有人住所地人民法院管辖；无权利凭证的权利质权，由出质登记地人民法院管辖。"},{"i":361,"n":"第三百六十一条","txt":"实现担保物权案件属于海事法院等专门人民法院管辖的，由专门人民法院管辖。"},{"i":362,"n":"第三百六十二条","txt":"同一债权的担保物有多个且所在地不同，申请人分别向有管辖权的人民法院申请实现担保物权的，人民法院应当依法受理。"},{"i":363,"n":"第三百六十三条","txt":"依照民法典第三百九十二条的规定，被担保的债权既有物的担保又有人的担保，当事人对实现担保物权的顺序有约定，实现担保物权的申请违反该约定的，人民法院裁定不予受理；没有约定或者约定不明的，人民法院应当受理。"},{"i":364,"n":"第三百六十四条","txt":"同一财产上设立多个担保物权，登记在先的担保物权尚未实现的，不影响后顺位的担保物权人向人民法院申请实现担保物权。"},{"i":365,"n":"第三百六十五条","txt":"申请实现担保物权，应当提交下列材料："},{"i":366,"n":"第三百六十六条","txt":"人民法院受理申请后，应当在五日内向被申请人送达申请书副本、异议权利告知书等文书。"},{"i":367,"n":"第三百六十七条","txt":"实现担保物权案件可以由审判员一人独任审查。担保财产标的额超过基层人民法院管辖范围的，应当组成合议庭进行审查。"},{"i":368,"n":"第三百六十八条","txt":"人民法院审查实现担保物权案件，可以询问申请人、被申请人、利害关系人，必要时可以依职权调查相关事实。"},{"i":369,"n":"第三百六十九条","txt":"人民法院应当就主合同的效力、期限、履行情况，担保物权是否有效设立、担保财产的范围、被担保的债权范围、被担保的债权是否已届清偿期等担保物权实现的条件，以及是否损害他人合法权益等内容进行审查。"},{"i":370,"n":"第三百七十条","txt":"人民法院审查后，按下列情形分别处理："},{"i":371,"n":"第三百七十一条","txt":"人民法院受理申请后，申请人对担保财产提出保全申请的，可以按照民事诉讼法关于诉讼保全的规定办理。"},{"i":372,"n":"第三百七十二条","txt":"适用特别程序作出的判决、裁定，当事人、利害关系人认为有错误的，可以向作出该判决、裁定的人民法院提出异议。人民法院经审查，异议成立或者部分成立的，作出新的判决、裁定撤销或者改变原判决、裁定；异议不成立的，裁定驳回。"},{"i":373,"n":"第三百七十三条","txt":"当事人死亡或者终止的，其权利义务承继者可以根据民事诉讼法第二百零六条、第二百零八条的规定申请再审。"},{"i":374,"n":"第三百七十四条","txt":"民事诉讼法第二百零六条规定的人数众多的一方当事人，包括公民、法人和其他组织。"},{"i":375,"n":"第三百七十五条","txt":"当事人申请再审，应当提交下列材料："},{"i":376,"n":"第三百七十六条","txt":"再审申请书应当记明下列事项："},{"i":377,"n":"第三百七十七条","txt":"当事人一方人数众多或者当事人双方为公民的案件，当事人分别向原审人民法院和上一级人民法院申请再审且不能协商一致的，由原审人民法院受理。"},{"i":378,"n":"第三百七十八条","txt":"适用特别程序、督促程序、公示催告程序、破产程序等非讼程序审理的案件，当事人不得申请再审。"},{"i":379,"n":"第三百七十九条","txt":"当事人认为发生法律效力的不予受理、驳回起诉的裁定错误的，可以申请再审。"},{"i":380,"n":"第三百八十条","txt":"当事人就离婚案件中的财产分割问题申请再审，如涉及判决中已分割的财产，人民法院应当依照民事诉讼法第二百零七条的规定进行审查，符合再审条件的，应当裁定再审；如涉及判决中未作处理的夫妻共同财产，应当告知当事人另行起诉。"},{"i":381,"n":"第三百八十一条","txt":"当事人申请再审，有下列情形之一的，人民法院不予受理："},{"i":382,"n":"第三百八十二条","txt":"当事人对已经发生法律效力的调解书申请再审，应当在调解书发生法律效力后六个月内提出。"},{"i":383,"n":"第三百八十三条","txt":"人民法院应当自收到符合条件的再审申请书等材料之日起五日内向再审申请人发送受理通知书，并向被申请人及原审其他当事人发送应诉通知书、再审申请书副本等材料。"},{"i":384,"n":"第三百八十四条","txt":"人民法院受理申请再审案件后，应当依照民事诉讼法第二百零七条、第二百零八条、第二百一十一条等规定，对当事人主张的再审事由进行审查。"},{"i":385,"n":"第三百八十五条","txt":"再审申请人提供的新的证据，能够证明原判决、裁定认定基本事实或者裁判结果错误的，应当认定为民事诉讼法第二百零七条第一项规定的情形。"},{"i":386,"n":"第三百八十六条","txt":"再审申请人证明其提交的新的证据符合下列情形之一的，可以认定逾期提供证据的理由成立："},{"i":387,"n":"第三百八十七条","txt":"当事人对原判决、裁定认定事实的主要证据在原审中拒绝发表质证意见或者质证中未对证据发表质证意见的，不属于民事诉讼法第二百零七条第四项规定的未经质证的情形。"},{"i":388,"n":"第三百八十八条","txt":"有下列情形之一，导致判决、裁定结果错误的，应当认定为民事诉讼法第二百零七条第六项规定的原判决、裁定适用法律确有错误："},{"i":389,"n":"第三百八十九条","txt":"原审开庭过程中有下列情形之一的，应当认定为民事诉讼法第二百零七条第九项规定的剥夺当事人辩论权利："},{"i":390,"n":"第三百九十条","txt":"民事诉讼法第二百零七条第十一项规定的诉讼请求，包括一审诉讼请求、二审上诉请求，但当事人未对一审判决、裁定遗漏或者超出诉讼请求提起上诉的除外。"},{"i":391,"n":"第三百九十一条","txt":"民事诉讼法第二百零七条第十二项规定的法律文书包括："},{"i":392,"n":"第三百九十二条","txt":"民事诉讼法第二百零七条第十三项规定的审判人员审理该案件时有贪污受贿、徇私舞弊、枉法裁判行为，是指已经由生效刑事法律文书或者纪律处分决定所确认的行为。"},{"i":393,"n":"第三百九十三条","txt":"当事人主张的再审事由成立，且符合民事诉讼法和本解释规定的申请再审条件的，人民法院应当裁定再审。"},{"i":394,"n":"第三百九十四条","txt":"人民法院对已经发生法律效力的判决、裁定、调解书依法决定再审，依照民事诉讼法第二百一十三条规定，需要中止执行的，应当在再审裁定中同时写明中止原判决、裁定、调解书的执行；情况紧急的，可以将中止执行裁定口头通知负责执行的人民法院，并在通知后十日内发出裁定书。"},{"i":395,"n":"第三百九十五条","txt":"人民法院根据审查案件的需要决定是否询问当事人。新的证据可能推翻原判决、裁定的，人民法院应当询问当事人。"},{"i":396,"n":"第三百九十六条","txt":"审查再审申请期间，被申请人及原审其他当事人依法提出再审申请的，人民法院应当将其列为再审申请人，对其再审事由一并审查，审查期限重新计算。经审查，其中一方再审申请人主张的再审事由成立的，应当裁定再审。各方再审申请人主张的再审事由均不成立的，一并裁定驳回再审申请。"},{"i":397,"n":"第三百九十七条","txt":"审查再审申请期间，再审申请人申请人民法院委托鉴定、勘验的，人民法院不予准许。"},{"i":398,"n":"第三百九十八条","txt":"审查再审申请期间，再审申请人撤回再审申请的，是否准许，由人民法院裁定。"},{"i":399,"n":"第三百九十九条","txt":"人民法院准许撤回再审申请或者按撤回再审申请处理后，再审申请人再次申请再审的，不予受理，但有民事诉讼法第二百零七条第一项、第三项、第十二项、第十三项规定情形，自知道或者应当知道之日起六个月内提出的除外。"},{"i":400,"n":"第四百条","txt":"再审申请审查期间，有下列情形之一的，裁定终结审查："},{"i":401,"n":"第四百零一条","txt":"人民法院审理再审案件应当组成合议庭开庭审理，但按照第二审程序审理，有特殊情况或者双方当事人已经通过其他方式充分表达意见，且书面同意不开庭审理的除外。"},{"i":402,"n":"第四百零二条","txt":"人民法院开庭审理再审案件，应当按照下列情形分别进行："},{"i":403,"n":"第四百零三条","txt":"人民法院审理再审案件应当围绕再审请求进行。当事人的再审请求超出原审诉讼请求的，不予审理；符合另案诉讼条件的，告知当事人可以另行起诉。"},{"i":404,"n":"第四百零四条","txt":"再审审理期间，有下列情形之一的，可以裁定终结再审程序："},{"i":405,"n":"第四百零五条","txt":"人民法院经再审审理认为，原判决、裁定认定事实清楚、适用法律正确的，应予维持；原判决、裁定认定事实、适用法律虽有瑕疵，但裁判结果正确的，应当在再审判决、裁定中纠正瑕疵后予以维持。"},{"i":406,"n":"第四百零六条","txt":"按照第二审程序再审的案件，人民法院经审理认为不符合民事诉讼法规定的起诉条件或者符合民事诉讼法第一百二十七条规定不予受理情形的，应当裁定撤销一、二审判决，驳回起诉。"},{"i":407,"n":"第四百零七条","txt":"人民法院对调解书裁定再审后，按照下列情形分别处理："},{"i":408,"n":"第四百零八条","txt":"一审原告在再审审理程序中申请撤回起诉，经其他当事人同意，且不损害国家利益、社会公共利益、他人合法权益的，人民法院可以准许。裁定准许撤诉的，应当一并撤销原判决。"},{"i":409,"n":"第四百零九条","txt":"当事人提交新的证据致使再审改判，因再审申请人或者申请检察监督当事人的过错未能在原审程序中及时举证，被申请人等当事人请求补偿其增加的交通、住宿、就餐、误工等必要费用的，人民法院应予支持。"},{"i":410,"n":"第四百一十条","txt":"部分当事人到庭并达成调解协议，其他当事人未作出书面表示的，人民法院应当在判决中对该事实作出表述；调解协议内容不违反法律规定，且不损害其他当事人合法权益的，可以在判决主文中予以确认。"},{"i":411,"n":"第四百一十一条","txt":"人民检察院依法对损害国家利益、社会公共利益的发生法律效力的判决、裁定、调解书提出抗诉，或者经人民检察院检察委员会讨论决定提出再审检察建议的，人民法院应予受理。"},{"i":412,"n":"第四百一十二条","txt":"人民检察院对已经发生法律效力的判决以及不予受理、驳回起诉的裁定依法提出抗诉的，人民法院应予受理，但适用特别程序、督促程序、公示催告程序、破产程序以及解除婚姻关系的判决、裁定等不适用审判监督程序的判决、裁定除外。"},{"i":413,"n":"第四百一十三条","txt":"人民检察院依照民事诉讼法第二百一十六条第一款第三项规定对有明显错误的再审判决、裁定提出抗诉或者再审检察建议的，人民法院应予受理。"},{"i":414,"n":"第四百一十四条","txt":"地方各级人民检察院依当事人的申请对生效判决、裁定向同级人民法院提出再审检察建议，符合下列条件的，应予受理："},{"i":415,"n":"第四百一十五条","txt":"人民检察院依当事人的申请对生效判决、裁定提出抗诉，符合下列条件的，人民法院应当在三十日内裁定再审："},{"i":416,"n":"第四百一十六条","txt":"当事人的再审申请被上级人民法院裁定驳回后，人民检察院对原判决、裁定、调解书提出抗诉，抗诉事由符合民事诉讼法第二百零七条第一项至第五项规定情形之一的，受理抗诉的人民法院可以交由下一级人民法院再审。"},{"i":417,"n":"第四百一十七条","txt":"人民法院收到再审检察建议后，应当组成合议庭，在三个月内进行审查，发现原判决、裁定、调解书确有错误，需要再审的，依照民事诉讼法第二百零五条规定裁定再审，并通知当事人；经审查，决定不予再审的，应当书面回复人民检察院。"},{"i":418,"n":"第四百一十八条","txt":"人民法院审理因人民检察院抗诉或者检察建议裁定再审的案件，不受此前已经作出的驳回当事人再审申请裁定的影响。"},{"i":419,"n":"第四百一十九条","txt":"人民法院开庭审理抗诉案件，应当在开庭三日前通知人民检察院、当事人和其他诉讼参与人。同级人民检察院或者提出抗诉的人民检察院应当派员出庭。"},{"i":420,"n":"第四百二十条","txt":"必须共同进行诉讼的当事人因不能归责于本人或者其诉讼代理人的事由未参加诉讼的，可以根据民事诉讼法第二百零七条第八项规定，自知道或者应当知道之日起六个月内申请再审，但符合本解释第四百二十一条规定情形的除外。"},{"i":421,"n":"第四百二十一条","txt":"根据民事诉讼法第二百三十四条规定，案外人对驳回其执行异议的裁定不服，认为原判决、裁定、调解书内容错误损害其民事权益的，可以自执行异议裁定送达之日起六个月内，向作出原判决、裁定、调解书的人民法院申请再审。"},{"i":422,"n":"第四百二十二条","txt":"根据民事诉讼法第二百三十四条规定，人民法院裁定再审后，案外人属于必要的共同诉讼当事人的，依照本解释第四百二十条第二款规定处理。"},{"i":423,"n":"第四百二十三条","txt":"本解释第三百三十八条规定适用于审判监督程序。"},{"i":424,"n":"第四百二十四条","txt":"对小额诉讼案件的判决、裁定，当事人以民事诉讼法第二百零七条规定的事由向原审人民法院申请再审的，人民法院应当受理。申请再审事由成立的，应当裁定再审，组成合议庭进行审理。作出的再审判决、裁定，当事人不得上诉。"},{"i":425,"n":"第四百二十五条","txt":"两个以上人民法院都有管辖权的，债权人可以向其中一个基层人民法院申请支付令。"},{"i":426,"n":"第四百二十六条","txt":"人民法院收到债权人的支付令申请书后，认为申请书不符合要求的，可以通知债权人限期补正。人民法院应当自收到补正材料之日起五日内通知债权人是否受理。"},{"i":427,"n":"第四百二十七条","txt":"债权人申请支付令，符合下列条件的，基层人民法院应当受理，并在收到支付令申请书后五日内通知债权人："},{"i":428,"n":"第四百二十八条","txt":"人民法院受理申请后，由审判员一人进行审查。经审查，有下列情形之一的，裁定驳回申请："},{"i":429,"n":"第四百二十九条","txt":"向债务人本人送达支付令，债务人拒绝接收的，人民法院可以留置送达。"},{"i":430,"n":"第四百三十条","txt":"有下列情形之一的，人民法院应当裁定终结督促程序，已发出支付令的，支付令自行失效："},{"i":431,"n":"第四百三十一条","txt":"债务人在收到支付令后，未在法定期间提出书面异议，而向其他人民法院起诉的，不影响支付令的效力。"},{"i":432,"n":"第四百三十二条","txt":"债权人基于同一债权债务关系，在同一支付令申请中向债务人提出多项支付请求，债务人仅就其中一项或者几项请求提出异议的，不影响其他各项请求的效力。"},{"i":433,"n":"第四百三十三条","txt":"债权人基于同一债权债务关系，就可分之债向多个债务人提出支付请求，多个债务人中的一人或者几人提出异议的，不影响其他请求的效力。"},{"i":434,"n":"第四百三十四条","txt":"对设有担保的债务的主债务人发出的支付令，对担保人没有拘束力。"},{"i":435,"n":"第四百三十五条","txt":"经形式审查，债务人提出的书面异议有下列情形之一的，应当认定异议成立，裁定终结督促程序，支付令自行失效："},{"i":436,"n":"第四百三十六条","txt":"债务人对债务本身没有异议，只是提出缺乏清偿能力、延缓债务清偿期限、变更债务清偿方式等异议的，不影响支付令的效力。"},{"i":437,"n":"第四百三十七条","txt":"人民法院作出终结督促程序或者驳回异议裁定前，债务人请求撤回异议的，应当裁定准许。"},{"i":438,"n":"第四百三十八条","txt":"支付令失效后，申请支付令的一方当事人不同意提起诉讼的，应当自收到终结督促程序裁定之日起七日内向受理申请的人民法院提出。"},{"i":439,"n":"第四百三十九条","txt":"支付令失效后，申请支付令的一方当事人自收到终结督促程序裁定之日起七日内未向受理申请的人民法院表明不同意提起诉讼的，视为向受理申请的人民法院起诉。"},{"i":440,"n":"第四百四十条","txt":"债权人向人民法院申请执行支付令的期间，适用民事诉讼法第二百四十六条的规定。"},{"i":441,"n":"第四百四十一条","txt":"人民法院院长发现本院已经发生法律效力的支付令确有错误，认为需要撤销的，应当提交本院审判委员会讨论决定后，裁定撤销支付令，驳回债权人的申请。"},{"i":442,"n":"第四百四十二条","txt":"民事诉讼法第二百二十五条规定的票据持有人，是指票据被盗、遗失或者灭失前的最后持有人。"},{"i":443,"n":"第四百四十三条","txt":"人民法院收到公示催告的申请后，应当立即审查，并决定是否受理。经审查认为符合受理条件的，通知予以受理，并同时通知支付人停止支付；认为不符合受理条件的，七日内裁定驳回申请。"},{"i":444,"n":"第四百四十四条","txt":"因票据丧失，申请公示催告的，人民法院应结合票据存根、丧失票据的复印件、出票人关于签发票据的证明、申请人合法取得票据的证明、银行挂失止付通知书、报案证明等证据，决定是否受理。"},{"i":445,"n":"第四百四十五条","txt":"人民法院依照民事诉讼法第二百二十六条规定发出的受理申请的公告，应当写明下列内容："},{"i":446,"n":"第四百四十六条","txt":"公告应当在有关报纸或者其他媒体上刊登，并于同日公布于人民法院公告栏内。人民法院所在地有证券交易所的，还应当同日在该交易所公布。"},{"i":447,"n":"第四百四十七条","txt":"公告期间不得少于六十日，且公示催告期间届满日不得早于票据付款日后十五日。"},{"i":448,"n":"第四百四十八条","txt":"在申报期届满后、判决作出之前，利害关系人申报权利的，应当适用民事诉讼法第二百二十八条第二款、第三款规定处理。"},{"i":449,"n":"第四百四十九条","txt":"利害关系人申报权利，人民法院应当通知其向法院出示票据，并通知公示催告申请人在指定的期间查看该票据。公示催告申请人申请公示催告的票据与利害关系人出示的票据不一致的，应当裁定驳回利害关系人的申报。"},{"i":450,"n":"第四百五十条","txt":"在申报权利的期间无人申报权利，或者申报被驳回的，申请人应当自公示催告期间届满之日起一个月内申请作出判决。逾期不申请判决的，终结公示催告程序。"},{"i":451,"n":"第四百五十一条","txt":"判决公告之日起，公示催告申请人有权依据判决向付款人请求付款。"},{"i":452,"n":"第四百五十二条","txt":"适用公示催告程序审理案件，可由审判员一人独任审理；判决宣告票据无效的，应当组成合议庭审理。"},{"i":453,"n":"第四百五十三条","txt":"公示催告申请人撤回申请，应在公示催告前提出；公示催告期间申请撤回的，人民法院可以径行裁定终结公示催告程序。"},{"i":454,"n":"第四百五十四条","txt":"人民法院依照民事诉讼法第二百二十七条规定通知支付人停止支付，应当符合有关财产保全的规定。支付人收到停止支付通知后拒不止付的，除可依照民事诉讼法第一百一十四条、第一百一十七条规定采取强制措施外，在判决后，支付人仍应承担付款义务。"},{"i":455,"n":"第四百五十五条","txt":"人民法院依照民事诉讼法第二百二十八条规定终结公示催告程序后，公示催告申请人或者申报人向人民法院提起诉讼，因票据权利纠纷提起的，由票据支付地或者被告住所地人民法院管辖；因非票据权利纠纷提起的，由被告住所地人民法院管辖。"},{"i":456,"n":"第四百五十六条","txt":"依照民事诉讼法第二百二十八条规定制作的终结公示催告程序的裁定书，由审判员、书记员署名，加盖人民法院印章。"},{"i":457,"n":"第四百五十七条","txt":"依照民事诉讼法第二百三十条的规定，利害关系人向人民法院起诉的，人民法院可按票据纠纷适用普通程序审理。"},{"i":458,"n":"第四百五十八条","txt":"民事诉讼法第二百三十条规定的正当理由，包括："},{"i":459,"n":"第四百五十九条","txt":"根据民事诉讼法第二百三十条的规定，利害关系人请求人民法院撤销除权判决的，应当将申请人列为被告。"},{"i":460,"n":"第四百六十条","txt":"发生法律效力的实现担保物权裁定、确认调解协议裁定、支付令，由作出裁定、支付令的人民法院或者与其同级的被执行财产所在地的人民法院执行。"},{"i":461,"n":"第四百六十一条","txt":"当事人申请人民法院执行的生效法律文书应当具备下列条件："},{"i":462,"n":"第四百六十二条","txt":"根据民事诉讼法第二百三十四条规定，案外人对执行标的提出异议的，应当在该执行标的执行程序终结前提出。"},{"i":463,"n":"第四百六十三条","txt":"案外人对执行标的提出的异议，经审查，按照下列情形分别处理："},{"i":464,"n":"第四百六十四条","txt":"申请执行人与被执行人达成和解协议后请求中止执行或者撤回执行申请的，人民法院可以裁定中止执行或者终结执行。"},{"i":465,"n":"第四百六十五条","txt":"一方当事人不履行或者不完全履行在执行中双方自愿达成的和解协议，对方当事人申请执行原生效法律文书的，人民法院应当恢复执行，但和解协议已履行的部分应当扣除。和解协议已经履行完毕的，人民法院不予恢复执行。"},{"i":466,"n":"第四百六十六条","txt":"申请恢复执行原生效法律文书，适用民事诉讼法第二百四十六条申请执行期间的规定。申请执行期间因达成执行中的和解协议而中断，其期间自和解协议约定履行期限的最后一日起重新计算。"},{"i":467,"n":"第四百六十七条","txt":"人民法院依照民事诉讼法第二百三十八条规定决定暂缓执行的，如果担保是有期限的，暂缓执行的期限应当与担保期限一致，但最长不得超过一年。被执行人或者担保人对担保的财产在暂缓执行期间有转移、隐藏、变卖、毁损等行为的，人民法院可以恢复强制执行。"},{"i":468,"n":"第四百六十八条","txt":"根据民事诉讼法第二百三十八条规定向人民法院提供执行担保的，可以由被执行人或者他人提供财产担保，也可以由他人提供保证。担保人应当具有代为履行或者代为承担赔偿责任的能力。"},{"i":469,"n":"第四百六十九条","txt":"被执行人在人民法院决定暂缓执行的期限届满后仍不履行义务的，人民法院可以直接执行担保财产，或者裁定执行担保人的财产，但执行担保人的财产以担保人应当履行义务部分的财产为限。"},{"i":470,"n":"第四百七十条","txt":"依照民事诉讼法第二百三十九条规定，执行中作为被执行人的法人或者其他组织分立、合并的，人民法院可以裁定变更后的法人或者其他组织为被执行人；被注销的，如果依照有关实体法的规定有权利义务承受人的，可以裁定该权利义务承受人为被执行人。"},{"i":471,"n":"第四百七十一条","txt":"其他组织在执行中不能履行法律文书确定的义务的，人民法院可以裁定执行对该其他组织依法承担义务的法人或者公民个人的财产。"},{"i":472,"n":"第四百七十二条","txt":"在执行中，作为被执行人的法人或者其他组织名称变更的，人民法院可以裁定变更后的法人或者其他组织为被执行人。"},{"i":473,"n":"第四百七十三条","txt":"作为被执行人的公民死亡，其遗产继承人没有放弃继承的，人民法院可以裁定变更被执行人，由该继承人在遗产的范围内偿还债务。继承人放弃继承的，人民法院可以直接执行被执行人的遗产。"},{"i":474,"n":"第四百七十四条","txt":"法律规定由人民法院执行的其他法律文书执行完毕后，该法律文书被有关机关或者组织依法撤销的，经当事人申请，适用民事诉讼法第二百四十条规定。"},{"i":475,"n":"第四百七十五条","txt":"仲裁机构裁决的事项，部分有民事诉讼法第二百四十四条第二款、第三款规定情形的，人民法院应当裁定对该部分不予执行。"},{"i":476,"n":"第四百七十六条","txt":"依照民事诉讼法第二百四十四条第二款、第三款规定，人民法院裁定不予执行仲裁裁决后，当事人对该裁定提出执行异议或者复议的，人民法院不予受理。当事人可以就该民事纠纷重新达成书面仲裁协议申请仲裁，也可以向人民法院起诉。"},{"i":477,"n":"第四百七十七条","txt":"在执行中，被执行人通过仲裁程序将人民法院查封、扣押、冻结的财产确权或者分割给案外人的，不影响人民法院执行程序的进行。"},{"i":478,"n":"第四百七十八条","txt":"有下列情形之一的，可以认定为民事诉讼法第二百四十五条第二款规定的公证债权文书确有错误："},{"i":479,"n":"第四百七十九条","txt":"当事人请求不予执行仲裁裁决或者公证债权文书的，应当在执行终结前向执行法院提出。"},{"i":480,"n":"第四百八十条","txt":"人民法院应当在收到申请执行书或者移交执行书后十日内发出执行通知。"},{"i":481,"n":"第四百八十一条","txt":"申请执行人超过申请执行时效期间向人民法院申请强制执行的，人民法院应予受理。被执行人对申请执行时效期间提出异议，人民法院经审查异议成立的，裁定不予执行。"},{"i":482,"n":"第四百八十二条","txt":"对必须接受调查询问的被执行人、被执行人的法定代表人、负责人或者实际控制人，经依法传唤无正当理由拒不到场的，人民法院可以拘传其到场。"},{"i":483,"n":"第四百八十三条","txt":"人民法院有权查询被执行人的身份信息与财产信息，掌握相关信息的单位和个人必须按照协助执行通知书办理。"},{"i":484,"n":"第四百八十四条","txt":"对被执行的财产，人民法院非经查封、扣押、冻结不得处分。对银行存款等各类可以直接扣划的财产，人民法院的扣划裁定同时具有冻结的法律效力。"},{"i":485,"n":"第四百八十五条","txt":"人民法院冻结被执行人的银行存款的期限不得超过一年，查封、扣押动产的期限不得超过两年，查封不动产、冻结其他财产权的期限不得超过三年。"},{"i":486,"n":"第四百八十六条","txt":"依照民事诉讼法第二百五十四条规定，人民法院在执行中需要拍卖被执行人财产的，可以由人民法院自行组织拍卖，也可以交由具备相应资质的拍卖机构拍卖。"},{"i":487,"n":"第四百八十七条","txt":"拍卖评估需要对现场进行检查、勘验的，人民法院应当责令被执行人、协助义务人予以配合。被执行人、协助义务人不予配合的，人民法院可以强制进行。"},{"i":488,"n":"第四百八十八条","txt":"人民法院在执行中需要变卖被执行人财产的，可以交有关单位变卖，也可以由人民法院直接变卖。"},{"i":489,"n":"第四百八十九条","txt":"经申请执行人和被执行人同意，且不损害其他债权人合法权益和社会公共利益的，人民法院可以不经拍卖、变卖，直接将被执行人的财产作价交申请执行人抵偿债务。对剩余债务，被执行人应当继续清偿。"},{"i":490,"n":"第四百九十条","txt":"被执行人的财产无法拍卖或者变卖的，经申请执行人同意，且不损害其他债权人合法权益和社会公共利益的，人民法院可以将该项财产作价后交付申请执行人抵偿债务，或者交付申请执行人管理；申请执行人拒绝接收或者管理的，退回被执行人。"},{"i":491,"n":"第四百九十一条","txt":"拍卖成交或者依法定程序裁定以物抵债的，标的物所有权自拍卖成交裁定或者抵债裁定送达买受人或者接受抵债物的债权人时转移。"},{"i":492,"n":"第四百九十二条","txt":"执行标的物为特定物的，应当执行原物。原物确已毁损或者灭失的，经双方当事人同意，可以折价赔偿。"},{"i":493,"n":"第四百九十三条","txt":"他人持有法律文书指定交付的财物或者票证，人民法院依照民事诉讼法第二百五十六条第二款、第三款规定发出协助执行通知后，拒不转交的，可以强制执行，并可依照民事诉讼法第一百一十七条、第一百一十八条规定处理。"},{"i":494,"n":"第四百九十四条","txt":"在执行中，被执行人隐匿财产、会计账簿等资料的，人民法院除可依照民事诉讼法第一百一十四条第一款第六项规定对其处理外，还应责令被执行人交出隐匿的财产、会计账簿等资料。被执行人拒不交出的，人民法院可以采取搜查措施。"},{"i":495,"n":"第四百九十五条","txt":"搜查人员应当按规定着装并出示搜查令和工作证件。"},{"i":496,"n":"第四百九十六条","txt":"人民法院搜查时禁止无关人员进入搜查现场；搜查对象是公民的，应当通知被执行人或者他的成年家属以及基层组织派员到场；搜查对象是法人或者其他组织的，应当通知法定代表人或者主要负责人到场。拒不到场的，不影响搜查。"},{"i":497,"n":"第四百九十七条","txt":"搜查中发现应当依法采取查封、扣押措施的财产，依照民事诉讼法第二百五十二条第二款和第二百五十四条规定办理。"},{"i":498,"n":"第四百九十八条","txt":"搜查应当制作搜查笔录，由搜查人员、被搜查人及其他在场人签名、捺印或者盖章。拒绝签名、捺印或者盖章的，应当记入搜查笔录。"},{"i":499,"n":"第四百九十九条","txt":"人民法院执行被执行人对他人的到期债权，可以作出冻结债权的裁定，并通知该他人向申请执行人履行。"},{"i":500,"n":"第五百条","txt":"人民法院在执行中需要办理房产证、土地证、林权证、专利证书、商标证书、车船执照等有关财产权证照转移手续的，可以依照民事诉讼法第二百五十八条规定办理。"},{"i":501,"n":"第五百零一条","txt":"被执行人不履行生效法律文书确定的行为义务，该义务可由他人完成的，人民法院可以选定代履行人；法律、行政法规对履行该行为义务有资格限制的，应当从有资格的人中选定。必要时，可以通过招标的方式确定代履行人。"},{"i":502,"n":"第五百零二条","txt":"代履行费用的数额由人民法院根据案件具体情况确定，并由被执行人在指定期限内预先支付。被执行人未预付的，人民法院可以对该费用强制执行。"},{"i":503,"n":"第五百零三条","txt":"被执行人不履行法律文书指定的行为，且该项行为只能由被执行人完成的，人民法院可以依照民事诉讼法第一百一十四条第一款第六项规定处理。"},{"i":504,"n":"第五百零四条","txt":"被执行人迟延履行的，迟延履行期间的利息或者迟延履行金自判决、裁定和其他法律文书指定的履行期间届满之日起计算。"},{"i":505,"n":"第五百零五条","txt":"被执行人未按判决、裁定和其他法律文书指定的期间履行非金钱给付义务的，无论是否已给申请执行人造成损失，都应当支付迟延履行金。已经造成损失的，双倍补偿申请执行人已经受到的损失；没有造成损失的，迟延履行金可以由人民法院根据具体案件情况决定。"},{"i":506,"n":"第五百零六条","txt":"被执行人为公民或者其他组织，在执行程序开始后，被执行人的其他已经取得执行依据的债权人发现被执行人的财产不能清偿所有债权的，可以向人民法院申请参与分配。"},{"i":507,"n":"第五百零七条","txt":"申请参与分配，申请人应当提交申请书。申请书应当写明参与分配和被执行人不能清偿所有债权的事实、理由，并附有执行依据。"},{"i":508,"n":"第五百零八条","txt":"参与分配执行中，执行所得价款扣除执行费用，并清偿应当优先受偿的债权后，对于普通债权，原则上按照其占全部申请参与分配债权数额的比例受偿。清偿后的剩余债务，被执行人应当继续清偿。债权人发现被执行人有其他财产的，可以随时请求人民法院执行。"},{"i":509,"n":"第五百零九条","txt":"多个债权人对执行财产申请参与分配的，执行法院应当制作财产分配方案，并送达各债权人和被执行人。债权人或者被执行人对分配方案有异议的，应当自收到分配方案之日起十五日内向执行法院提出书面异议。"},{"i":510,"n":"第五百一十条","txt":"债权人或者被执行人对分配方案提出书面异议的，执行法院应当通知未提出异议的债权人、被执行人。"},{"i":511,"n":"第五百一十一条","txt":"在执行中，作为被执行人的企业法人符合企业破产法第二条第一款规定情形的，执行法院经申请执行人之一或者被执行人同意，应当裁定中止对该被执行人的执行，将执行案件相关材料移送被执行人住所地人民法院。"},{"i":512,"n":"第五百一十二条","txt":"被执行人住所地人民法院应当自收到执行案件相关材料之日起三十日内，将是否受理破产案件的裁定告知执行法院。不予受理的，应当将相关案件材料退回执行法院。"},{"i":513,"n":"第五百一十三条","txt":"被执行人住所地人民法院裁定受理破产案件的，执行法院应当解除对被执行人财产的保全措施。被执行人住所地人民法院裁定宣告被执行人破产的，执行法院应当裁定终结对该被执行人的执行。"},{"i":514,"n":"第五百一十四条","txt":"当事人不同意移送破产或者被执行人住所地人民法院不受理破产案件的，执行法院就执行变价所得财产，在扣除执行费用及清偿优先受偿的债权后，对于普通债权，按照财产保全和执行中查封、扣押、冻结财产的先后顺序清偿。"},{"i":515,"n":"第五百一十五条","txt":"债权人根据民事诉讼法第二百六十一条规定请求人民法院继续执行的，不受民事诉讼法第二百四十六条规定申请执行时效期间的限制。"},{"i":516,"n":"第五百一十六条","txt":"被执行人不履行法律文书确定的义务的，人民法院除对被执行人予以处罚外，还可以根据情节将其纳入失信被执行人名单，将被执行人不履行或者不完全履行义务的信息向其所在单位、征信机构以及其他相关机构通报。"},{"i":517,"n":"第五百一十七条","txt":"经过财产调查未发现可供执行的财产，在申请执行人签字确认或者执行法院组成合议庭审查核实并经院长批准后，可以裁定终结本次执行程序。"},{"i":518,"n":"第五百一十八条","txt":"因撤销申请而终结执行后，当事人在民事诉讼法第二百四十六条规定的申请执行时效期间内再次申请执行的，人民法院应当受理。"},{"i":519,"n":"第五百一十九条","txt":"在执行终结六个月内，被执行人或者其他人对已执行的标的有妨害行为的，人民法院可以依申请排除妨害，并可以依照民事诉讼法第一百一十四条规定进行处罚。因妨害行为给执行债权人或者其他人造成损失的，受害人可以另行起诉。"},{"i":520,"n":"第五百二十条","txt":"有下列情形之一，人民法院可以认定为涉外民事案件："},{"i":521,"n":"第五百二十一条","txt":"外国人参加诉讼，应当向人民法院提交护照等用以证明自己身份的证件。"},{"i":522,"n":"第五百二十二条","txt":"依照民事诉讼法第二百七十一条以及本解释第五百二十一条规定，需要办理公证、认证手续，而外国当事人所在国与中华人民共和国没有建立外交关系的，可以经该国公证机关公证，经与中华人民共和国有外交关系的第三国驻该国使领馆认证，再转由中华人民共和国驻该第三国使领馆认证。"},{"i":523,"n":"第五百二十三条","txt":"外国人、外国企业或者组织的代表人在人民法院法官的见证下签署授权委托书，委托代理人进行民事诉讼的，人民法院应予认可。"},{"i":524,"n":"第五百二十四条","txt":"外国人、外国企业或者组织的代表人在中华人民共和国境内签署授权委托书，委托代理人进行民事诉讼，经中华人民共和国公证机构公证的，人民法院应予认可。"},{"i":525,"n":"第五百二十五条","txt":"当事人向人民法院提交的书面材料是外文的，应当同时向人民法院提交中文翻译件。"},{"i":526,"n":"第五百二十六条","txt":"涉外民事诉讼中的外籍当事人，可以委托本国人为诉讼代理人，也可以委托本国律师以非律师身份担任诉讼代理人；外国驻华使领馆官员，受本国公民的委托，可以以个人名义担任诉讼代理人，但在诉讼中不享有外交或者领事特权和豁免。"},{"i":527,"n":"第五百二十七条","txt":"涉外民事诉讼中，外国驻华使领馆授权其本馆官员，在作为当事人的本国国民不在中华人民共和国领域内的情况下，可以以外交代表身份为其本国国民在中华人民共和国聘请中华人民共和国律师或者中华人民共和国公民代理民事诉讼。"},{"i":528,"n":"第五百二十八条","txt":"涉外民事诉讼中，经调解双方达成协议，应当制发调解书。当事人要求发给判决书的，可以依协议的内容制作判决书送达当事人。"},{"i":529,"n":"第五百二十九条","txt":"涉外合同或者其他财产权益纠纷的当事人，可以书面协议选择被告住所地、合同履行地、合同签订地、原告住所地、标的物所在地、侵权行为地等与争议有实际联系地点的外国法院管辖。"},{"i":530,"n":"第五百三十条","txt":"涉外民事案件同时符合下列情形的，人民法院可以裁定驳回原告的起诉，告知其向更方便的外国法院提起诉讼："},{"i":531,"n":"第五百三十一条","txt":"中华人民共和国法院和外国法院都有管辖权的案件，一方当事人向外国法院起诉，而另一方当事人向中华人民共和国法院起诉的，人民法院可予受理。判决后，外国法院申请或者当事人请求人民法院承认和执行外国法院对本案作出的判决、裁定的，不予准许；但双方共同缔结或者参加的国际条约另有规定的除外。"},{"i":532,"n":"第五百三十二条","txt":"对在中华人民共和国领域内没有住所的当事人，经用公告方式送达诉讼文书，公告期满不应诉，人民法院缺席判决后，仍应当将裁判文书依照民事诉讼法第二百七十四条第八项规定公告送达。自公告送达裁判文书满三个月之日起，经过三十日的上诉期当事人没有上诉的，一审判决即发生法律效力。"},{"i":533,"n":"第五百三十三条","txt":"外国人或者外国企业、组织的代表人、主要负责人在中华人民共和国领域内的，人民法院可以向该自然人或者外国企业、组织的代表人、主要负责人送达。"},{"i":534,"n":"第五百三十四条","txt":"受送达人所在国允许邮寄送达的，人民法院可以邮寄送达。"},{"i":535,"n":"第五百三十五条","txt":"人民法院一审时采取公告方式向当事人送达诉讼文书的，二审时可径行采取公告方式向其送达诉讼文书，但人民法院能够采取公告方式之外的其他方式送达的除外。"},{"i":536,"n":"第五百三十六条","txt":"不服第一审人民法院判决、裁定的上诉期，对在中华人民共和国领域内有住所的当事人，适用民事诉讼法第一百七十一条规定的期限；对在中华人民共和国领域内没有住所的当事人，适用民事诉讼法第二百七十六条规定的期限。当事人的上诉期均已届满没有上诉的，第一审人民法院的判决、裁定即发生法律效力。"},{"i":537,"n":"第五百三十七条","txt":"人民法院对涉外民事案件的当事人申请再审进行审查的期间，不受民事诉讼法第二百一十一条规定的限制。"},{"i":538,"n":"第五百三十八条","txt":"申请人向人民法院申请执行中华人民共和国涉外仲裁机构的裁决，应当提出书面申请，并附裁决书正本。如申请人为外国当事人，其申请书应当用中文文本提出。"},{"i":539,"n":"第五百三十九条","txt":"人民法院强制执行涉外仲裁机构的仲裁裁决时，被执行人以有民事诉讼法第二百八十一条第一款规定的情形为由提出抗辩的，人民法院应当对被执行人的抗辩进行审查，并根据审查结果裁定执行或者不予执行。"},{"i":540,"n":"第五百四十条","txt":"依照民事诉讼法第二百七十九条规定，中华人民共和国涉外仲裁机构将当事人的保全申请提交人民法院裁定的，人民法院可以进行审查，裁定是否进行保全。裁定保全的，应当责令申请人提供担保，申请人不提供担保的，裁定驳回申请。"},{"i":541,"n":"第五百四十一条","txt":"申请人向人民法院申请承认和执行外国法院作出的发生法律效力的判决、裁定，应当提交申请书，并附外国法院作出的发生法律效力的判决、裁定正本或者经证明无误的副本以及中文译本。外国法院判决、裁定为缺席判决、裁定的，申请人应当同时提交该外国法院已经合法传唤的证明文件，但判决、裁定已经对此予以明确说明的除外。"},{"i":542,"n":"第五百四十二条","txt":"当事人向中华人民共和国有管辖权的中级人民法院申请承认和执行外国法院作出的发生法律效力的判决、裁定的，如果该法院所在国与中华人民共和国没有缔结或者共同参加国际条约，也没有互惠关系的，裁定驳回申请，但当事人向人民法院申请承认外国法院作出的发生法律效力的离婚判决的除外。"},{"i":543,"n":"第五百四十三条","txt":"对临时仲裁庭在中华人民共和国领域外作出的仲裁裁决，一方当事人向人民法院申请承认和执行的，人民法院应当依照民事诉讼法第二百九十条规定处理。"},{"i":544,"n":"第五百四十四条","txt":"对外国法院作出的发生法律效力的判决、裁定或者外国仲裁裁决，需要中华人民共和国法院执行的，当事人应当先向人民法院申请承认。人民法院经审查，裁定承认后，再根据民事诉讼法第三编的规定予以执行。"},{"i":545,"n":"第五百四十五条","txt":"当事人申请承认和执行外国法院作出的发生法律效力的判决、裁定或者外国仲裁裁决的期间，适用民事诉讼法第二百四十六条的规定。"},{"i":546,"n":"第五百四十六条","txt":"承认和执行外国法院作出的发生法律效力的判决、裁定或者外国仲裁裁决的案件，人民法院应当组成合议庭进行审查。"},{"i":547,"n":"第五百四十七条","txt":"与中华人民共和国没有司法协助条约又无互惠关系的国家的法院，未通过外交途径，直接请求人民法院提供司法协助的，人民法院应予退回，并说明理由。"},{"i":548,"n":"第五百四十八条","txt":"当事人在中华人民共和国领域外使用中华人民共和国法院的判决书、裁定书，要求中华人民共和国法院证明其法律效力的，或者外国法院要求中华人民共和国法院证明判决书、裁定书的法律效力的，作出判决、裁定的中华人民共和国法院，可以本法院的名义出具证明。"},{"i":549,"n":"第五百四十九条","txt":"人民法院审理涉及香港、澳门特别行政区和台湾地区的民事诉讼案件，可以参照适用涉外民事诉讼程序的特别规定。"},{"i":550,"n":"第五百五十条","txt":"本解释公布施行后，最高人民法院于1992年7月14日发布的《关于适用〈中华人民共和国民事诉讼法〉若干问题的意见》同时废止；最高人民法院以前发布的司法解释与本解释不一致的，不再适用。"}],"zuigaorenminfayuanguanyushiyongminfadianqinquanzerd54692":[{"i":1,"n":"第一条","txt":"非法使被监护人脱离监护，监护人请求赔偿为恢复监护状态而支出的合理费用等财产损失的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"非法使被监护人脱离监护，导致父母子女关系或者其他近亲属关系受到严重损害的，应当认定为民法典第一千一百八十三条第一款规定的严重精神损害。"},{"i":3,"n":"第三条","txt":"非法使被监护人脱离监护，被监护人在脱离监护期间死亡，作为近亲属的监护人既请求赔偿人身损害，又请求赔偿监护关系受侵害产生的损失的，人民法院依法予以支持。"},{"i":4,"n":"第四条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害，被侵权人请求监护人承担侵权责任，或者合并请求监护人和受托履行监护职责的人承担侵权责任的，人民法院应当将无民事行为能力人、限制民事行为能力人列为共同被告。"},{"i":5,"n":"第五条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害，被侵权人请求监护人承担侵权人应承担的全部责任的，人民法院应予支持，并在判决中明确，赔偿费用可以先从被监护人财产中支付，不足部分由监护人支付。"},{"i":6,"n":"第六条","txt":"行为人在侵权行为发生时不满十八周岁，被诉时已满十八周岁的，被侵权人请求原监护人承担侵权人应承担的全部责任的，人民法院应予支持，并在判决中明确，赔偿费用可以先从被监护人财产中支付，不足部分由监护人支付。"},{"i":7,"n":"第七条","txt":"未成年子女造成他人损害，被侵权人请求父母共同承担侵权责任的，人民法院依照民法典第二十七条第一款、第一千零六十八条以及第一千一百八十八条的规定予以支持。"},{"i":8,"n":"第八条","txt":"夫妻离婚后，未成年子女造成他人损害，被侵权人请求离异夫妻共同承担侵权责任的，人民法院依照民法典第一千零六十八条、第一千零八十四条以及第一千一百八十八条的规定予以支持。一方以未与该子女共同生活为由主张不承担或者少承担责任的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"未成年子女造成他人损害的，依照民法典第一千零七十二条第二款的规定，未与该子女形成抚养教育关系的继父或者继母不承担监护人的侵权责任，由该子女的生父母依照本解释第八条的规定承担侵权责任。"},{"i":10,"n":"第十条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害，被侵权人合并请求监护人和受托履行监护职责的人承担侵权责任的，依照民法典第一千一百八十九条的规定，监护人承担侵权人应承担的全部责任；受托人在过错范围内与监护人共同承担责任，但责任主体实际支付的赔偿费用总和不应超出被侵权人应受偿的损失数额。"},{"i":11,"n":"第十一条","txt":"教唆、帮助无民事行为能力人、限制民事行为能力人实施侵权行为，教唆人、帮助人以其不知道且不应当知道行为人为无民事行为能力人、限制民事行为能力人为由，主张不承担侵权责任或者与行为人的监护人承担连带责任的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"教唆、帮助无民事行为能力人、限制民事行为能力人实施侵权行为，被侵权人合并请求教唆人、帮助人以及监护人承担侵权责任的，依照民法典第一千一百六十九条第二款的规定，教唆人、帮助人承担侵权人应承担的全部责任；监护人在未尽到监护职责的范围内与教唆人、帮助人共同承担责任，但责任主体实际支付的赔偿费用总和不应超出被侵权人应受偿的损失数额。"},{"i":13,"n":"第十三条","txt":"教唆、帮助无民事行为能力人、限制民事行为能力人实施侵权行为，被侵权人合并请求教唆人、帮助人与监护人以及受托履行监护职责的人承担侵权责任的，依照本解释第十条、第十二条的规定认定民事责任。"},{"i":14,"n":"第十四条","txt":"无民事行为能力人或者限制民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间，受到教育机构以外的第三人人身损害，第三人、教育机构作为共同被告且依法应承担侵权责任的，人民法院应当在判决中明确，教育机构在人民法院就第三人的财产依法强制执行后仍不能履行的范围内，承担与其过错相应的补充责任。"},{"i":15,"n":"第十五条","txt":"与用人单位形成劳动关系的工作人员、执行用人单位工作任务的其他人员，因执行工作任务造成他人损害，被侵权人依照民法典第一千一百九十一条第一款的规定，请求用人单位承担侵权责任的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害，被侵权人合并请求劳务派遣单位与接受劳务派遣的用工单位承担侵权责任的，依照民法典第一千一百九十一条第二款的规定，接受劳务派遣的用工单位承担侵权人应承担的全部责任；劳务派遣单位在不当选派工作人员、未依法履行培训义务等过错范围内，与接受劳务派遣的用工单位共同承担责任，但责任主体实际支付的赔偿费用总和不应超出被侵权人应受偿的损失数额。"},{"i":17,"n":"第十七条","txt":"工作人员在执行工作任务中实施的违法行为造成他人损害，构成自然人犯罪的，工作人员承担刑事责任不影响用人单位依法承担民事责任。依照民法典第一千一百九十一条规定用人单位应当承担侵权责任的，在刑事案件中已完成的追缴、退赔可以在民事判决书中明确并扣减，也可以在执行程序中予以扣减。"},{"i":18,"n":"第十八条","txt":"承揽人在完成工作过程中造成第三人损害的，人民法院依照民法典第一千一百六十五条的规定认定承揽人的民事责任。"},{"i":19,"n":"第十九条","txt":"因产品存在缺陷造成买受人财产损害，买受人请求产品的生产者或者销售者赔偿缺陷产品本身损害以及其他财产损害的，人民法院依照民法典第一千二百零二条、第一千二百零三条的规定予以支持。"},{"i":20,"n":"第二十条","txt":"以买卖或者其他方式转让拼装或者已经达到报废标准的机动车，发生交通事故造成损害，转让人、受让人以其不知道且不应当知道该机动车系拼装或者已经达到报废标准为由，主张不承担侵权责任的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"未依法投保强制保险的机动车发生交通事故造成损害，投保义务人和交通事故责任人不是同一人，被侵权人合并请求投保义务人和交通事故责任人承担侵权责任的，交通事故责任人承担侵权人应承担的全部责任；投保义务人在机动车强制保险责任限额范围内与交通事故责任人共同承担责任，但责任主体实际支付的赔偿费用总和不应超出被侵权人应受偿的损失数额。"},{"i":22,"n":"第二十二条","txt":"机动车驾驶人离开本车后，因未采取制动措施等自身过错受到本车碰撞、碾压造成损害，机动车驾驶人请求承保本车机动车强制保险的保险人在强制保险责任限额范围内，以及承保本车机动车商业第三者责任保险的保险人按照保险合同的约定赔偿的，人民法院不予支持，但可以依据机动车车上人员责任保险的有关约定支持相应的赔偿请求。"},{"i":23,"n":"第二十三条","txt":"禁止饲养的烈性犬等危险动物造成他人损害，动物饲养人或者管理人主张不承担责任或者减轻责任的，人民法院不予支持。"},{"i":24,"n":"第二十四条","txt":"物业服务企业等建筑物管理人未采取必要的安全保障措施防止从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害，具体侵权人、物业服务企业等建筑物管理人作为共同被告的，人民法院应当依照民法典第一千一百九十八条第二款、第一千二百五十四条的规定，在判决中明确，未采取必要安全保障措施的物业服务企业等建筑物管理人在人民法院就具体侵权人的财产依法强制执行后仍不能履行的范围内，承担与其过错相应的补充责任。"},{"i":25,"n":"第二十五条","txt":"物业服务企业等建筑物管理人未采取必要的安全保障措施防止从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害，经公安等机关调查，在民事案件一审法庭辩论终结前仍难以确定具体侵权人的，未采取必要安全保障措施的物业服务企业等建筑物管理人承担与其过错相应的责任。被侵权人其余部分的损害，由可能加害的建筑物使用人给予适当补偿。"},{"i":26,"n":"第二十六条","txt":"本解释自2024年9月27日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianhetongbian53a9a5":[{"i":1,"n":"第一条","txt":"人民法院依据民法典第一百四十二条第一款、第四百六十六条第一款的规定解释合同条款时，应当以词句的通常含义为基础，结合相关条款、合同的性质和目的、习惯以及诚信原则，参考缔约背景、磋商过程、履行行为等因素确定争议条款的含义。"},{"i":2,"n":"第二条","txt":"下列情形，不违反法律、行政法规的强制性规定且不违背公序良俗的，人民法院可以认定为民法典所称的“交易习惯”："},{"i":3,"n":"第三条","txt":"当事人对合同是否成立存在争议，人民法院能够确定当事人姓名或者名称、标的和数量的，一般应当认定合同成立。但是，法律另有规定或者当事人另有约定的除外。"},{"i":4,"n":"第四条","txt":"采取招标方式订立合同，当事人请求确认合同自中标通知书到达中标人时成立的，人民法院应予支持。合同成立后，当事人拒绝签订书面合同的，人民法院应当依据招标文件、投标文件和中标通知书等确定合同内容。"},{"i":5,"n":"第五条","txt":"第三人实施欺诈、胁迫行为，使当事人在违背真实意思的情况下订立合同，受到损失的当事人请求第三人承担赔偿责任的，人民法院依法予以支持；当事人亦有违背诚信原则的行为的，人民法院应当根据各自的过错确定相应的责任。但是，法律、司法解释对当事人与第三人的民事责任另有规定的，依照其规定。"},{"i":6,"n":"第六条","txt":"当事人以认购书、订购书、预订书等形式约定在将来一定期限内订立合同，或者为担保在将来一定期限内订立合同交付了定金，能够确定将来所要订立合同的主体、标的等内容的，人民法院应当认定预约合同成立。"},{"i":7,"n":"第七条","txt":"预约合同生效后，当事人一方拒绝订立本约合同或者在磋商订立本约合同时违背诚信原则导致未能订立本约合同的，人民法院应当认定该当事人不履行预约合同约定的义务。"},{"i":8,"n":"第八条","txt":"预约合同生效后，当事人一方不履行订立本约合同的义务，对方请求其赔偿因此造成的损失的，人民法院依法予以支持。"},{"i":9,"n":"第九条","txt":"合同条款符合民法典第四百九十六条第一款规定的情形，当事人仅以合同系依据合同示范文本制作或者双方已经明确约定合同条款不属于格式条款为由主张该条款不是格式条款的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"提供格式条款的一方在合同订立时采用通常足以引起对方注意的文字、符号、字体等明显标识，提示对方注意免除或者减轻其责任、排除或者限制对方权利等与对方有重大利害关系的异常条款的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的提示义务。"},{"i":11,"n":"第十一条","txt":"当事人一方是自然人，根据该当事人的年龄、智力、知识、经验并结合交易的复杂程度，能够认定其对合同的性质、合同订立的法律后果或者交易中存在的特定风险缺乏应有的认知能力的，人民法院可以认定该情形构成民法典第一百五十一条规定的“缺乏判断能力”。"},{"i":12,"n":"第十二条","txt":"合同依法成立后，负有报批义务的当事人不履行报批义务或者履行报批义务不符合合同的约定或者法律、行政法规的规定，对方请求其继续履行报批义务的，人民法院应予支持；对方主张解除合同并请求其承担违反报批义务的赔偿责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"合同存在无效或者可撤销的情形，当事人以该合同已在有关行政管理部门办理备案、已经批准机关批准或者已依据该合同办理财产权利的变更登记、移转登记等为由主张合同有效的，人民法院不予支持。"},{"i":14,"n":"第十四条","txt":"当事人之间就同一交易订立多份合同，人民法院应当认定其中以虚假意思表示订立的合同无效。当事人为规避法律、行政法规的强制性规定，以虚假意思表示隐藏真实意思表示的，人民法院应当依据民法典第一百五十三条第一款的规定认定被隐藏合同的效力；当事人为规避法律、行政法规关于合同应当办理批准等手续的规定，以虚假意思表示隐藏真实意思表示的，人民法院应当依据民法典第五百零二条第二款的规定认定被隐藏合同的效力。"},{"i":15,"n":"第十五条","txt":"人民法院认定当事人之间的权利义务关系，不应当拘泥于合同使用的名称，而应当根据合同约定的内容。当事人主张的权利义务关系与根据合同内容认定的权利义务关系不一致的，人民法院应当结合缔约背景、交易目的、交易结构、履行行为以及当事人是否存在虚构交易标的等事实认定当事人之间的实际民事法律关系。"},{"i":16,"n":"第十六条","txt":"合同违反法律、行政法规的强制性规定，有下列情形之一，由行为人承担行政责任或者刑事责任能够实现强制性规定的立法目的的，人民法院可以依据民法典第一百五十三条第一款关于“该强制性规定不导致该民事法律行为无效的除外”的规定认定该合同不因违反强制性规定无效："},{"i":17,"n":"第十七条","txt":"合同虽然不违反法律、行政法规的强制性规定，但是有下列情形之一，人民法院应当依据民法典第一百五十三条第二款的规定认定合同无效："},{"i":18,"n":"第十八条","txt":"法律、行政法规的规定虽然有“应当”“必须”或者“不得”等表述，但是该规定旨在限制或者赋予民事权利，行为人违反该规定将构成无权处分、无权代理、越权代表等，或者导致合同相对人、第三人因此获得撤销权、解除权等民事权利的，人民法院应当依据法律、行政法规规定的关于违反该规定的民事法律后果认定合同效力。"},{"i":19,"n":"第十九条","txt":"以转让或者设定财产权利为目的订立的合同，当事人或者真正权利人仅以让与人在订立合同时对标的物没有所有权或者处分权为由主张合同无效的，人民法院不予支持；因未取得真正权利人事后同意或者让与人事后未取得处分权导致合同不能履行，受让人主张解除合同并请求让与人承担违反合同的赔偿责任的，人民法院依法予以支持。"},{"i":20,"n":"第二十条","txt":"法律、行政法规为限制法人的法定代表人或者非法人组织的负责人的代表权，规定合同所涉事项应当由法人、非法人组织的权力机构或者决策机构决议，或者应当由法人、非法人组织的执行机构决定，法定代表人、负责人未取得授权而以法人、非法人组织的名义订立合同，未尽到合理审查义务的相对人主张该合同对法人、非法人组织发生效力并由其承担违约责任的，人民法院不予支持，但是法人、非法人组织有过错的，可以参照民法典第一百五十七条的规定判决其承担相应的赔偿责任。相对人已尽到合理审查义务，构成表见代表的，人民法院应当依据民法典第五百零四条的规定处理。"},{"i":21,"n":"第二十一条","txt":"法人、非法人组织的工作人员就超越其职权范围的事项以法人、非法人组织的名义订立合同，相对人主张该合同对法人、非法人组织发生效力并由其承担违约责任的，人民法院不予支持。但是，法人、非法人组织有过错的，人民法院可以参照民法典第一百五十七条的规定判决其承担相应的赔偿责任。前述情形，构成表见代理的，人民法院应当依据民法典第一百七十二条的规定处理。"},{"i":22,"n":"第二十二条","txt":"法定代表人、负责人或者工作人员以法人、非法人组织的名义订立合同且未超越权限，法人、非法人组织仅以合同加盖的印章不是备案印章或者系伪造的印章为由主张该合同对其不发生效力的，人民法院不予支持。"},{"i":23,"n":"第二十三条","txt":"法定代表人、负责人或者代理人与相对人恶意串通，以法人、非法人组织的名义订立合同，损害法人、非法人组织的合法权益，法人、非法人组织主张不承担民事责任的，人民法院应予支持。法人、非法人组织请求法定代表人、负责人或者代理人与相对人对因此受到的损失承担连带赔偿责任的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"合同不成立、无效、被撤销或者确定不发生效力，当事人请求返还财产，经审查财产能够返还的，人民法院应当根据案件具体情况，单独或者合并适用返还占有的标的物、更正登记簿册记载等方式；经审查财产不能返还或者没有必要返还的，人民法院应当以认定合同不成立、无效、被撤销或者确定不发生效力之日该财产的市场价值或者以其他合理方式计算的价值为基准判决折价补偿。"},{"i":25,"n":"第二十五条","txt":"合同不成立、无效、被撤销或者确定不发生效力，有权请求返还价款或者报酬的当事人一方请求对方支付资金占用费的，人民法院应当在当事人请求的范围内按照中国人民银行授权全国银行间同业拆借中心公布的一年期贷款市场报价利率（LPR）计算。但是，占用资金的当事人对于合同不成立、无效、被撤销或者确定不发生效力没有过错的，应当以中国人民银行公布的同期同类存款基准利率计算。"},{"i":26,"n":"第二十六条","txt":"当事人一方未根据法律规定或者合同约定履行开具发票、提供证明文件等非主要债务，对方请求继续履行该债务并赔偿因怠于履行该债务造成的损失的，人民法院依法予以支持；对方请求解除合同的，人民法院不予支持，但是不履行该债务致使不能实现合同目的或者当事人另有约定的除外。"},{"i":27,"n":"第二十七条","txt":"债务人或者第三人与债权人在债务履行期限届满后达成以物抵债协议，不存在影响合同效力情形的，人民法院应当认定该协议自当事人意思表示一致时生效。"},{"i":28,"n":"第二十八条","txt":"债务人或者第三人与债权人在债务履行期限届满前达成以物抵债协议的，人民法院应当在审理债权债务关系的基础上认定该协议的效力。"},{"i":29,"n":"第二十九条","txt":"民法典第五百二十二条第二款规定的第三人请求债务人向自己履行债务的，人民法院应予支持；请求行使撤销权、解除权等民事权利的，人民法院不予支持，但是法律另有规定的除外。"},{"i":30,"n":"第三十条","txt":"下列民事主体，人民法院可以认定为民法典第五百二十四条第一款规定的对履行债务具有合法利益的第三人："},{"i":31,"n":"第三十一条","txt":"当事人互负债务，一方以对方没有履行非主要债务为由拒绝履行自己的主要债务的，人民法院不予支持。但是，对方不履行非主要债务致使不能实现合同目的或者当事人另有约定的除外。"},{"i":32,"n":"第三十二条","txt":"合同成立后，因政策调整或者市场供求关系异常变动等原因导致价格发生当事人在订立合同时无法预见的、不属于商业风险的涨跌，继续履行合同对于当事人一方明显不公平的，人民法院应当认定合同的基础条件发生了民法典第五百三十三条第一款规定的“重大变化”。但是，合同涉及市场属性活跃、长期以来价格波动较大的大宗商品以及股票、期货等风险投资型金融产品的除外。"},{"i":33,"n":"第三十三条","txt":"债务人不履行其对债权人的到期债务，又不以诉讼或者仲裁方式向相对人主张其享有的债权或者与该债权有关的从权利，致使债权人的到期债权未能实现的，人民法院可以认定为民法典第五百三十五条规定的“债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现”。"},{"i":34,"n":"第三十四条","txt":"下列权利，人民法院可以认定为民法典第五百三十五条第一款规定的专属于债务人自身的权利："},{"i":35,"n":"第三十五条","txt":"债权人依据民法典第五百三十五条的规定对债务人的相对人提起代位权诉讼的，由被告住所地人民法院管辖，但是依法应当适用专属管辖规定的除外。"},{"i":36,"n":"第三十六条","txt":"债权人提起代位权诉讼后，债务人或者相对人以双方之间的债权债务关系订有仲裁协议为由对法院主管提出异议的，人民法院不予支持。但是，债务人或者相对人在首次开庭前就债务人与相对人之间的债权债务关系申请仲裁的，人民法院可以依法中止代位权诉讼。"},{"i":37,"n":"第三十七条","txt":"债权人以债务人的相对人为被告向人民法院提起代位权诉讼，未将债务人列为第三人的，人民法院应当追加债务人为第三人。"},{"i":38,"n":"第三十八条","txt":"债权人向人民法院起诉债务人后，又向同一人民法院对债务人的相对人提起代位权诉讼，属于该人民法院管辖的，可以合并审理。不属于该人民法院管辖的，应当告知其向有管辖权的人民法院另行起诉；在起诉债务人的诉讼终结前，代位权诉讼应当中止。"},{"i":39,"n":"第三十九条","txt":"在代位权诉讼中，债务人对超过债权人代位请求数额的债权部分起诉相对人，属于同一人民法院管辖的，可以合并审理。不属于同一人民法院管辖的，应当告知其向有管辖权的人民法院另行起诉；在代位权诉讼终结前，债务人对相对人的诉讼应当中止。"},{"i":40,"n":"第四十条","txt":"代位权诉讼中，人民法院经审理认为债权人的主张不符合代位权行使条件的，应当驳回诉讼请求，但是不影响债权人根据新的事实再次起诉。"},{"i":41,"n":"第四十一条","txt":"债权人提起代位权诉讼后，债务人无正当理由减免相对人的债务或者延长相对人的履行期限，相对人以此向债权人抗辩的，人民法院不予支持。"},{"i":42,"n":"第四十二条","txt":"对于民法典第五百三十九条规定的“明显不合理”的低价或者高价，人民法院应当按照交易当地一般经营者的判断，并参考交易时交易地的市场交易价或者物价部门指导价予以认定。"},{"i":43,"n":"第四十三条","txt":"债务人以明显不合理的价格，实施互易财产、以物抵债、出租或者承租财产、知识产权许可使用等行为，影响债权人的债权实现，债务人的相对人知道或者应当知道该情形，债权人请求撤销债务人的行为的，人民法院应当依据民法典第五百三十九条的规定予以支持。"},{"i":44,"n":"第四十四条","txt":"债权人依据民法典第五百三十八条、第五百三十九条的规定提起撤销权诉讼的，应当以债务人和债务人的相对人为共同被告，由债务人或者相对人的住所地人民法院管辖，但是依法应当适用专属管辖规定的除外。"},{"i":45,"n":"第四十五条","txt":"在债权人撤销权诉讼中，被撤销行为的标的可分，当事人主张在受影响的债权范围内撤销债务人的行为的，人民法院应予支持；被撤销行为的标的不可分，债权人主张将债务人的行为全部撤销的，人民法院应予支持。"},{"i":46,"n":"第四十六条","txt":"债权人在撤销权诉讼中同时请求债务人的相对人向债务人承担返还财产、折价补偿、履行到期债务等法律后果的，人民法院依法予以支持。"},{"i":47,"n":"第四十七条","txt":"债权转让后，债务人向受让人主张其对让与人的抗辩的，人民法院可以追加让与人为第三人。"},{"i":48,"n":"第四十八条","txt":"债务人在接到债权转让通知前已经向让与人履行，受让人请求债务人履行的，人民法院不予支持；债务人接到债权转让通知后仍然向让与人履行，受让人请求债务人履行的，人民法院应予支持。"},{"i":49,"n":"第四十九条","txt":"债务人接到债权转让通知后，让与人以债权转让合同不成立、无效、被撤销或者确定不发生效力为由请求债务人向其履行的，人民法院不予支持。但是，该债权转让通知被依法撤销的除外。"},{"i":50,"n":"第五十条","txt":"让与人将同一债权转让给两个以上受让人，债务人以已经向最先通知的受让人履行为由主张其不再履行债务的，人民法院应予支持。债务人明知接受履行的受让人不是最先通知的受让人，最先通知的受让人请求债务人继续履行债务或者依据债权转让协议请求让与人承担违约责任的，人民法院应予支持；最先通知的受让人请求接受履行的受让人返还其接受的财产的，人民法院不予支持，但是接受履行的受让人明知该债权在其受让前已经转让给其他受让人的除外。"},{"i":51,"n":"第五十一条","txt":"第三人加入债务并与债务人约定了追偿权，其履行债务后主张向债务人追偿的，人民法院应予支持；没有约定追偿权，第三人依照民法典关于不当得利等的规定，在其已经向债权人履行债务的范围内请求债务人向其履行的，人民法院应予支持，但是第三人知道或者应当知道加入债务会损害债务人利益的除外。"},{"i":52,"n":"第五十二条","txt":"当事人就解除合同协商一致时未对合同解除后的违约责任、结算和清理等问题作出处理，一方主张合同已经解除的，人民法院应予支持。但是，当事人另有约定的除外。"},{"i":53,"n":"第五十三条","txt":"当事人一方以通知方式解除合同，并以对方未在约定的异议期限或者其他合理期限内提出异议为由主张合同已经解除的，人民法院应当对其是否享有法律规定或者合同约定的解除权进行审查。经审查，享有解除权的，合同自通知到达对方时解除；不享有解除权的，不发生合同解除的效力。"},{"i":54,"n":"第五十四条","txt":"当事人一方未通知对方，直接以提起诉讼的方式主张解除合同，撤诉后再次起诉主张解除合同，人民法院经审理支持该主张的，合同自再次起诉的起诉状副本送达对方时解除。但是，当事人一方撤诉后又通知对方解除合同且该通知已经到达对方的除外。"},{"i":55,"n":"第五十五条","txt":"当事人一方依据民法典第五百六十八条的规定主张抵销，人民法院经审理认为抵销权成立的，应当认定通知到达对方时双方互负的主债务、利息、违约金或者损害赔偿金等债务在同等数额内消灭。"},{"i":56,"n":"第五十六条","txt":"行使抵销权的一方负担的数项债务种类相同，但是享有的债权不足以抵销全部债务，当事人因抵销的顺序发生争议的，人民法院可以参照民法典第五百六十条的规定处理。"},{"i":57,"n":"第五十七条","txt":"因侵害自然人人身权益，或者故意、重大过失侵害他人财产权益产生的损害赔偿债务，侵权人主张抵销的，人民法院不予支持。"},{"i":58,"n":"第五十八条","txt":"当事人互负债务，一方以其诉讼时效期间已经届满的债权通知对方主张抵销，对方提出诉讼时效抗辩的，人民法院对该抗辩应予支持。一方的债权诉讼时效期间已经届满，对方主张抵销的，人民法院应予支持。"},{"i":59,"n":"第五十九条","txt":"当事人一方依据民法典第五百八十条第二款的规定请求终止合同权利义务关系的，人民法院一般应当以起诉状副本送达对方的时间作为合同权利义务关系终止的时间。根据案件的具体情况，以其他时间作为合同权利义务关系终止的时间更加符合公平原则和诚信原则的，人民法院可以以该时间作为合同权利义务关系终止的时间，但是应当在裁判文书中充分说明理由。"},{"i":60,"n":"第六十条","txt":"人民法院依据民法典第五百八十四条的规定确定合同履行后可以获得的利益时，可以在扣除非违约方为订立、履行合同支出的费用等合理成本后，按照非违约方能够获得的生产利润、经营利润或者转售利润等计算。"},{"i":61,"n":"第六十一条","txt":"在以持续履行的债务为内容的定期合同中，一方不履行支付价款、租金等金钱债务，对方请求解除合同，人民法院经审理认为合同应当依法解除的，可以根据当事人的主张，参考合同主体、交易类型、市场价格变化、剩余履行期限等因素确定非违约方寻找替代交易的合理期限，并按照该期限对应的价款、租金等扣除非违约方应当支付的相应履约成本确定合同履行后可以获得的利益。"},{"i":62,"n":"第六十二条","txt":"非违约方在合同履行后可以获得的利益难以根据本解释第六十条、第六十一条的规定予以确定的，人民法院可以综合考虑违约方因违约获得的利益、违约方的过错程度、其他违约情节等因素，遵循公平原则和诚信原则确定。"},{"i":63,"n":"第六十三条","txt":"在认定民法典第五百八十四条规定的“违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失”时，人民法院应当根据当事人订立合同的目的，综合考虑合同主体、合同内容、交易类型、交易习惯、磋商过程等因素，按照与违约方处于相同或者类似情况的民事主体在订立合同时预见到或者应当预见到的损失予以确定。"},{"i":64,"n":"第六十四条","txt":"当事人一方通过反诉或者抗辩的方式，请求调整违约金的，人民法院依法予以支持。"},{"i":65,"n":"第六十五条","txt":"当事人主张约定的违约金过分高于违约造成的损失，请求予以适当减少的，人民法院应当以民法典第五百八十四条规定的损失为基础，兼顾合同主体、交易类型、合同的履行情况、当事人的过错程度、履约背景等因素，遵循公平原则和诚信原则进行衡量，并作出裁判。"},{"i":66,"n":"第六十六条","txt":"当事人一方请求对方支付违约金，对方以合同不成立、无效、被撤销、确定不发生效力、不构成违约或者非违约方不存在损失等为由抗辩，未主张调整过高的违约金的，人民法院应当就若不支持该抗辩，当事人是否请求调整违约金进行释明。第一审人民法院认为抗辩成立且未予释明，第二审人民法院认为应当判决支付违约金的，可以直接释明，并根据当事人的请求，在当事人就是否应当调整违约金充分举证、质证、辩论后，依法判决适当减少违约金。"},{"i":67,"n":"第六十七条","txt":"当事人交付留置金、担保金、保证金、订约金、押金或者订金等，但是没有约定定金性质，一方主张适用民法典第五百八十七条规定的定金罚则的，人民法院不予支持。当事人约定了定金性质，但是未约定定金类型或者约定不明，一方主张为违约定金的，人民法院应予支持。"},{"i":68,"n":"第六十八条","txt":"双方当事人均具有致使不能实现合同目的的违约行为，其中一方请求适用定金罚则的，人民法院不予支持。当事人一方仅有轻微违约，对方具有致使不能实现合同目的的违约行为，轻微违约方主张适用定金罚则，对方以轻微违约方也构成违约为由抗辩的，人民法院对该抗辩不予支持。"},{"i":69,"n":"第六十九条","txt":"本解释自2023年12月5日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianhunyinjiat5db6ae":[{"i":1,"n":"第一条","txt":"持续性、经常性的家庭暴力，可以认定为民法典第一千零四十二条、第一千零七十九条、第一千零九十一条所称的“虐待”。"},{"i":2,"n":"第二条","txt":"民法典第一千零四十二条、第一千零七十九条、第一千零九十一条规定的“与他人同居”的情形，是指有配偶者与婚外异性，不以夫妻名义，持续、稳定地共同居住。"},{"i":3,"n":"第三条","txt":"当事人提起诉讼仅请求解除同居关系的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":4,"n":"第四条","txt":"当事人仅以民法典第一千零四十三条为依据提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":5,"n":"第五条","txt":"当事人请求返还按照习俗给付的彩礼的，如果查明属于以下情形，人民法院应当予以支持："},{"i":6,"n":"第六条","txt":"男女双方依据民法典第一千零四十九条规定补办结婚登记的，婚姻关系的效力从双方均符合民法典所规定的结婚的实质要件时起算。"},{"i":7,"n":"第七条","txt":"未依据民法典第一千零四十九条规定办理结婚登记而以夫妻名义共同生活的男女，提起诉讼要求离婚的，应当区别对待："},{"i":8,"n":"第八条","txt":"未依据民法典第一千零四十九条规定办理结婚登记而以夫妻名义共同生活的男女，一方死亡，另一方以配偶身份主张享有继承权的，依据本解释第七条的原则处理。"},{"i":9,"n":"第九条","txt":"有权依据民法典第一千零五十一条规定向人民法院就已办理结婚登记的婚姻请求确认婚姻无效的主体，包括婚姻当事人及利害关系人。其中，利害关系人包括："},{"i":10,"n":"第十条","txt":"当事人依据民法典第一千零五十一条规定向人民法院请求确认婚姻无效，法定的无效婚姻情形在提起诉讼时已经消失的，人民法院不予支持。"},{"i":11,"n":"第十一条","txt":"人民法院受理请求确认婚姻无效案件后，原告申请撤诉的，不予准许。"},{"i":12,"n":"第十二条","txt":"人民法院受理离婚案件后，经审理确属无效婚姻的，应当将婚姻无效的情形告知当事人，并依法作出确认婚姻无效的判决。"},{"i":13,"n":"第十三条","txt":"人民法院就同一婚姻关系分别受理了离婚和请求确认婚姻无效案件的，对于离婚案件的审理，应当待请求确认婚姻无效案件作出判决后进行。"},{"i":14,"n":"第十四条","txt":"夫妻一方或者双方死亡后，生存一方或者利害关系人依据民法典第一千零五十一条的规定请求确认婚姻无效的，人民法院应当受理。"},{"i":15,"n":"第十五条","txt":"利害关系人依据民法典第一千零五十一条的规定，请求人民法院确认婚姻无效的，利害关系人为原告，婚姻关系当事人双方为被告。"},{"i":16,"n":"第十六条","txt":"人民法院审理重婚导致的无效婚姻案件时，涉及财产处理的，应当准许合法婚姻当事人作为有独立请求权的第三人参加诉讼。"},{"i":17,"n":"第十七条","txt":"当事人以民法典第一千零五十一条规定的三种无效婚姻以外的情形请求确认婚姻无效的，人民法院应当判决驳回当事人的诉讼请求。"},{"i":18,"n":"第十八条","txt":"行为人以给另一方当事人或者其近亲属的生命、身体、健康、名誉、财产等方面造成损害为要挟，迫使另一方当事人违背真实意愿结婚的，可以认定为民法典第一千零五十二条所称的“胁迫”。"},{"i":19,"n":"第十九条","txt":"民法典第一千零五十二条规定的“一年”，不适用诉讼时效中止、中断或者延长的规定。"},{"i":20,"n":"第二十条","txt":"民法典第一千零五十四条所规定的“自始没有法律约束力”，是指无效婚姻或者可撤销婚姻在依法被确认无效或者被撤销时，才确定该婚姻自始不受法律保护。"},{"i":21,"n":"第二十一条","txt":"人民法院根据当事人的请求，依法确认婚姻无效或者撤销婚姻的，应当收缴双方的结婚证书并将生效的判决书寄送当地婚姻登记管理机关。"},{"i":22,"n":"第二十二条","txt":"被确认无效或者被撤销的婚姻，当事人同居期间所得的财产，除有证据证明为当事人一方所有的以外，按共同共有处理。"},{"i":23,"n":"第二十三条","txt":"夫以妻擅自中止妊娠侵犯其生育权为由请求损害赔偿的，人民法院不予支持；夫妻双方因是否生育发生纠纷，致使感情确已破裂，一方请求离婚的，人民法院经调解无效，应依照民法典第一千零七十九条第三款第五项的规定处理。"},{"i":24,"n":"第二十四条","txt":"民法典第一千零六十二条第一款第三项规定的“知识产权的收益”，是指婚姻关系存续期间，实际取得或者已经明确可以取得的财产性收益。"},{"i":25,"n":"第二十五条","txt":"婚姻关系存续期间，下列财产属于民法典第一千零六十二条规定的“其他应当归共同所有的财产”："},{"i":26,"n":"第二十六条","txt":"夫妻一方个人财产在婚后产生的收益，除孳息和自然增值外，应认定为夫妻共同财产。"},{"i":27,"n":"第二十七条","txt":"由一方婚前承租、婚后用共同财产购买的房屋，登记在一方名下的，应当认定为夫妻共同财产。"},{"i":28,"n":"第二十八条","txt":"一方未经另一方同意出售夫妻共同所有的房屋，第三人善意购买、支付合理对价并已办理不动产登记，另一方主张追回该房屋的，人民法院不予支持。"},{"i":29,"n":"第二十九条","txt":"当事人结婚前，父母为双方购置房屋出资的，该出资应当认定为对自己子女个人的赠与，但父母明确表示赠与双方的除外。"},{"i":30,"n":"第三十条","txt":"军人的伤亡保险金、伤残补助金、医药生活补助费属于个人财产。"},{"i":31,"n":"第三十一条","txt":"民法典第一千零六十三条规定为夫妻一方的个人财产，不因婚姻关系的延续而转化为夫妻共同财产。但当事人另有约定的除外。"},{"i":32,"n":"第三十二条","txt":"婚前或者婚姻关系存续期间，当事人约定将一方所有的房产赠与另一方或者共有，赠与方在赠与房产变更登记之前撤销赠与，另一方请求判令继续履行的，人民法院可以按照民法典第六百五十八条的规定处理。"},{"i":33,"n":"第三十三条","txt":"债权人就一方婚前所负个人债务向债务人的配偶主张权利的，人民法院不予支持。但债权人能够证明所负债务用于婚后家庭共同生活的除外。"},{"i":34,"n":"第三十四条","txt":"夫妻一方与第三人串通，虚构债务，第三人主张该债务为夫妻共同债务的，人民法院不予支持。"},{"i":35,"n":"第三十五条","txt":"当事人的离婚协议或者人民法院生效判决、裁定、调解书已经对夫妻财产分割问题作出处理的，债权人仍有权就夫妻共同债务向男女双方主张权利。"},{"i":36,"n":"第三十六条","txt":"夫或者妻一方死亡的，生存一方应当对婚姻关系存续期间的夫妻共同债务承担清偿责任。"},{"i":37,"n":"第三十七条","txt":"民法典第一千零六十五条第三款所称“相对人知道该约定的”，夫妻一方对此负有举证责任。"},{"i":38,"n":"第三十八条","txt":"婚姻关系存续期间，除民法典第一千零六十六条规定情形以外，夫妻一方请求分割共同财产的，人民法院不予支持。"},{"i":39,"n":"第三十九条","txt":"父或者母向人民法院起诉请求否认亲子关系，并已提供必要证据予以证明，另一方没有相反证据又拒绝做亲子鉴定的，人民法院可以认定否认亲子关系一方的主张成立。"},{"i":40,"n":"第四十条","txt":"婚姻关系存续期间，夫妻双方一致同意进行人工授精，所生子女应视为婚生子女，父母子女间的权利义务关系适用民法典的有关规定。"},{"i":41,"n":"第四十一条","txt":"尚在校接受高中及其以下学历教育，或者丧失、部分丧失劳动能力等非因主观原因而无法维持正常生活的成年子女，可以认定为民法典第一千零六十七条规定的“不能独立生活的成年子女”。"},{"i":42,"n":"第四十二条","txt":"民法典第一千零六十七条所称“抚养费”，包括子女生活费、教育费、医疗费等费用。"},{"i":43,"n":"第四十三条","txt":"婚姻关系存续期间，父母双方或者一方拒不履行抚养子女义务，未成年子女或者不能独立生活的成年子女请求支付抚养费的，人民法院应予支持。"},{"i":44,"n":"第四十四条","txt":"离婚案件涉及未成年子女抚养的，对不满两周岁的子女，按照民法典第一千零八十四条第三款规定的原则处理。母亲有下列情形之一，父亲请求直接抚养的，人民法院应予支持："},{"i":45,"n":"第四十五条","txt":"父母双方协议不满两周岁子女由父亲直接抚养，并对子女健康成长无不利影响的，人民法院应予支持。"},{"i":46,"n":"第四十六条","txt":"对已满两周岁的未成年子女，父母均要求直接抚养，一方有下列情形之一的，可予优先考虑："},{"i":47,"n":"第四十七条","txt":"父母抚养子女的条件基本相同，双方均要求直接抚养子女，但子女单独随祖父母或者外祖父母共同生活多年，且祖父母或者外祖父母要求并且有能力帮助子女照顾孙子女或者外孙子女的，可以作为父或者母直接抚养子女的优先条件予以考虑。"},{"i":48,"n":"第四十八条","txt":"在有利于保护子女利益的前提下，父母双方协议轮流直接抚养子女的，人民法院应予支持。"},{"i":49,"n":"第四十九条","txt":"抚养费的数额，可以根据子女的实际需要、父母双方的负担能力和当地的实际生活水平确定。"},{"i":50,"n":"第五十条","txt":"抚养费应当定期给付，有条件的可以一次性给付。"},{"i":51,"n":"第五十一条","txt":"父母一方无经济收入或者下落不明的，可以用其财物折抵抚养费。"},{"i":52,"n":"第五十二条","txt":"父母双方可以协议由一方直接抚养子女并由直接抚养方负担子女全部抚养费。但是，直接抚养方的抚养能力明显不能保障子女所需费用，影响子女健康成长的，人民法院不予支持。"},{"i":53,"n":"第五十三条","txt":"抚养费的给付期限，一般至子女十八周岁为止。"},{"i":54,"n":"第五十四条","txt":"生父与继母离婚或者生母与继父离婚时，对曾受其抚养教育的继子女，继父或者继母不同意继续抚养的，仍应由生父或者生母抚养。"},{"i":55,"n":"第五十五条","txt":"离婚后，父母一方要求变更子女抚养关系的，或者子女要求增加抚养费的，应当另行提起诉讼。"},{"i":56,"n":"第五十六条","txt":"具有下列情形之一，父母一方要求变更子女抚养关系的，人民法院应予支持："},{"i":57,"n":"第五十七条","txt":"父母双方协议变更子女抚养关系的，人民法院应予支持。"},{"i":58,"n":"第五十八条","txt":"具有下列情形之一，子女要求有负担能力的父或者母增加抚养费的，人民法院应予支持："},{"i":59,"n":"第五十九条","txt":"父母不得因子女变更姓氏而拒付子女抚养费。父或者母擅自将子女姓氏改为继母或继父姓氏而引起纠纷的，应当责令恢复原姓氏。"},{"i":60,"n":"第六十条","txt":"在离婚诉讼期间，双方均拒绝抚养子女的，可以先行裁定暂由一方抚养。"},{"i":61,"n":"第六十一条","txt":"对拒不履行或者妨害他人履行生效判决、裁定、调解书中有关子女抚养义务的当事人或者其他人，人民法院可依照民事诉讼法第一百一十一条的规定采取强制措施。"},{"i":62,"n":"第六十二条","txt":"无民事行为能力人的配偶有民法典第三十六条第一款规定行为，其他有监护资格的人可以要求撤销其监护资格，并依法指定新的监护人；变更后的监护人代理无民事行为能力一方提起离婚诉讼的，人民法院应予受理。"},{"i":63,"n":"第六十三条","txt":"人民法院审理离婚案件，符合民法典第一千零七十九条第三款规定“应当准予离婚”情形的，不应当因当事人有过错而判决不准离婚。"},{"i":64,"n":"第六十四条","txt":"民法典第一千零八十一条所称的“军人一方有重大过错”，可以依据民法典第一千零七十九条第三款前三项规定及军人有其他重大过错导致夫妻感情破裂的情形予以判断。"},{"i":65,"n":"第六十五条","txt":"人民法院作出的生效的离婚判决中未涉及探望权，当事人就探望权问题单独提起诉讼的，人民法院应予受理。"},{"i":66,"n":"第六十六条","txt":"当事人在履行生效判决、裁定或者调解书的过程中，一方请求中止探望的，人民法院在征询双方当事人意见后，认为需要中止探望的，依法作出裁定；中止探望的情形消失后，人民法院应当根据当事人的请求书面通知其恢复探望。"},{"i":67,"n":"第六十七条","txt":"未成年子女、直接抚养子女的父或者母以及其他对未成年子女负担抚养、教育、保护义务的法定监护人，有权向人民法院提出中止探望的请求。"},{"i":68,"n":"第六十八条","txt":"对于拒不协助另一方行使探望权的有关个人或者组织，可以由人民法院依法采取拘留、罚款等强制措施，但是不能对子女的人身、探望行为进行强制执行。"},{"i":69,"n":"第六十九条","txt":"当事人达成的以协议离婚或者到人民法院调解离婚为条件的财产以及债务处理协议，如果双方离婚未成，一方在离婚诉讼中反悔的，人民法院应当认定该财产以及债务处理协议没有生效，并根据实际情况依照民法典第一千零八十七条和第一千零八十九条的规定判决。"},{"i":70,"n":"第七十条","txt":"夫妻双方协议离婚后就财产分割问题反悔，请求撤销财产分割协议的，人民法院应当受理。"},{"i":71,"n":"第七十一条","txt":"人民法院审理离婚案件，涉及分割发放到军人名下的复员费、自主择业费等一次性费用的，以夫妻婚姻关系存续年限乘以年平均值，所得数额为夫妻共同财产。"},{"i":72,"n":"第七十二条","txt":"夫妻双方分割共同财产中的股票、债券、投资基金份额等有价证券以及未上市股份有限公司股份时，协商不成或者按市价分配有困难的，人民法院可以根据数量按比例分配。"},{"i":73,"n":"第七十三条","txt":"人民法院审理离婚案件，涉及分割夫妻共同财产中以一方名义在有限责任公司的出资额，另一方不是该公司股东的，按以下情形分别处理："},{"i":74,"n":"第七十四条","txt":"人民法院审理离婚案件，涉及分割夫妻共同财产中以一方名义在合伙企业中的出资，另一方不是该企业合伙人的，当夫妻双方协商一致，将其合伙企业中的财产份额全部或者部分转让给对方时，按以下情形分别处理："},{"i":75,"n":"第七十五条","txt":"夫妻以一方名义投资设立个人独资企业的，人民法院分割夫妻在该个人独资企业中的共同财产时，应当按照以下情形分别处理："},{"i":76,"n":"第七十六条","txt":"双方对夫妻共同财产中的房屋价值及归属无法达成协议时，人民法院按以下情形分别处理："},{"i":77,"n":"第七十七条","txt":"离婚时双方对尚未取得所有权或者尚未取得完全所有权的房屋有争议且协商不成的，人民法院不宜判决房屋所有权的归属，应当根据实际情况判决由当事人使用。"},{"i":78,"n":"第七十八条","txt":"夫妻一方婚前签订不动产买卖合同，以个人财产支付首付款并在银行贷款，婚后用夫妻共同财产还贷，不动产登记于首付款支付方名下的，离婚时该不动产由双方协议处理。"},{"i":79,"n":"第七十九条","txt":"婚姻关系存续期间，双方用夫妻共同财产出资购买以一方父母名义参加房改的房屋，登记在一方父母名下，离婚时另一方主张按照夫妻共同财产对该房屋进行分割的，人民法院不予支持。购买该房屋时的出资，可以作为债权处理。"},{"i":80,"n":"第八十条","txt":"离婚时夫妻一方尚未退休、不符合领取基本养老金条件，另一方请求按照夫妻共同财产分割基本养老金的，人民法院不予支持；婚后以夫妻共同财产缴纳基本养老保险费，离婚时一方主张将养老金账户中婚姻关系存续期间个人实际缴纳部分及利息作为夫妻共同财产分割的，人民法院应予支持。"},{"i":81,"n":"第八十一条","txt":"婚姻关系存续期间，夫妻一方作为继承人依法可以继承的遗产，在继承人之间尚未实际分割，起诉离婚时另一方请求分割的，人民法院应当告知当事人在继承人之间实际分割遗产后另行起诉。"},{"i":82,"n":"第八十二条","txt":"夫妻之间订立借款协议，以夫妻共同财产出借给一方从事个人经营活动或者用于其他个人事务的，应视为双方约定处分夫妻共同财产的行为，离婚时可以按照借款协议的约定处理。"},{"i":83,"n":"第八十三条","txt":"离婚后，一方以尚有夫妻共同财产未处理为由向人民法院起诉请求分割的，经审查该财产确属离婚时未涉及的夫妻共同财产，人民法院应当依法予以分割。"},{"i":84,"n":"第八十四条","txt":"当事人依据民法典第一千零九十二条的规定向人民法院提起诉讼，请求再次分割夫妻共同财产的诉讼时效期间为三年，从当事人发现之日起计算。"},{"i":85,"n":"第八十五条","txt":"夫妻一方申请对配偶的个人财产或者夫妻共同财产采取保全措施的，人民法院可以在采取保全措施可能造成损失的范围内，根据实际情况，确定合理的财产担保数额。"},{"i":86,"n":"第八十六条","txt":"民法典第一千零九十一条规定的“损害赔偿”，包括物质损害赔偿和精神损害赔偿。涉及精神损害赔偿的，适用《最高人民法院关于确定民事侵权精神损害赔偿责任若干问题的解释》的有关规定。"},{"i":87,"n":"第八十七条","txt":"承担民法典第一千零九十一条规定的损害赔偿责任的主体，为离婚诉讼当事人中无过错方的配偶。"},{"i":88,"n":"第八十八条","txt":"人民法院受理离婚案件时，应当将民法典第一千零九十一条等规定中当事人的有关权利义务，书面告知当事人。在适用民法典第一千零九十一条时，应当区分以下不同情况："},{"i":89,"n":"第八十九条","txt":"当事人在婚姻登记机关办理离婚登记手续后，以民法典第一千零九十一条规定为由向人民法院提出损害赔偿请求的，人民法院应当受理。但当事人在协议离婚时已经明确表示放弃该项请求的，人民法院不予支持。"},{"i":90,"n":"第九十条","txt":"夫妻双方均有民法典第一千零九十一条规定的过错情形，一方或者双方向对方提出离婚损害赔偿请求的，人民法院不予支持。"},{"i":91,"n":"第九十一条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianhunyinjiat68ffbd":[{"i":1,"n":"第一条","txt":"当事人依据民法典第一千零五十一条第一项规定请求确认重婚的婚姻无效，提起诉讼时合法婚姻当事人已经离婚或者配偶已经死亡，被告以此为由抗辩后一婚姻自以上情形发生时转为有效的，人民法院不予支持。"},{"i":2,"n":"第二条","txt":"夫妻登记离婚后，一方以双方意思表示虚假为由请求确认离婚无效的，人民法院不予支持。"},{"i":3,"n":"第三条","txt":"夫妻一方的债权人有证据证明离婚协议中财产分割条款影响其债权实现，请求参照适用民法典第五百三十八条或者第五百三十九条规定撤销相关条款的，人民法院应当综合考虑夫妻共同财产整体分割及履行情况、子女抚养费负担、离婚过错等因素，依法予以支持。"},{"i":4,"n":"第四条","txt":"双方均无配偶的同居关系析产纠纷案件中，对同居期间所得的财产，有约定的，按照约定处理；没有约定且协商不成的，人民法院按照以下情形分别处理："},{"i":5,"n":"第五条","txt":"婚前或者婚姻关系存续期间，当事人约定将一方所有的房屋转移登记至另一方或者双方名下，离婚诉讼时房屋所有权尚未转移登记，双方对房屋归属或者分割有争议且协商不成的，人民法院可以根据当事人诉讼请求，结合给予目的，综合考虑婚姻关系存续时间、共同生活及孕育共同子女情况、离婚过错、对家庭的贡献大小以及离婚时房屋市场价格等因素，判决房屋归其中一方所有，并确定是否由获得房屋一方对另一方予以补偿以及补偿的具体数额。"},{"i":6,"n":"第六条","txt":"夫妻一方未经另一方同意，在网络直播平台用夫妻共同财产打赏，数额明显超出其家庭一般消费水平，严重损害夫妻共同财产利益的，可以认定为民法典第一千零六十六条和第一千零九十二条规定的“挥霍”。另一方请求在婚姻关系存续期间分割夫妻共同财产，或者在离婚分割夫妻共同财产时请求对打赏一方少分或者不分的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"夫妻一方为重婚、与他人同居以及其他违反夫妻忠实义务等目的，将夫妻共同财产赠与他人或者以明显不合理的价格处分夫妻共同财产，另一方主张该民事法律行为违背公序良俗无效的，人民法院应予支持并依照民法典第一百五十七条规定处理。"},{"i":8,"n":"第八条","txt":"婚姻关系存续期间，夫妻购置房屋由一方父母全额出资，如果赠与合同明确约定只赠与自己子女一方的，按照约定处理；没有约定或者约定不明确的，离婚分割夫妻共同财产时，人民法院可以判决该房屋归出资人子女一方所有，并综合考虑共同生活及孕育共同子女情况、离婚过错、对家庭的贡献大小以及离婚时房屋市场价格等因素，确定是否由获得房屋一方对另一方予以补偿以及补偿的具体数额。"},{"i":9,"n":"第九条","txt":"夫妻一方转让用夫妻共同财产出资但登记在自己名下的有限责任公司股权，另一方以未经其同意侵害夫妻共同财产利益为由请求确认股权转让合同无效的，人民法院不予支持，但有证据证明转让人与受让人恶意串通损害另一方合法权益的除外。"},{"i":10,"n":"第十条","txt":"夫妻以共同财产投资有限责任公司，并均登记为股东，双方对相应股权的归属没有约定或者约定不明确，离婚时，一方请求按照股东名册或者公司章程记载的各自出资额确定股权分割比例的，人民法院不予支持；对当事人分割夫妻共同财产的请求，人民法院依照民法典第一千零八十七条规定处理。"},{"i":11,"n":"第十一条","txt":"夫妻一方以另一方可继承的财产为夫妻共同财产、放弃继承侵害夫妻共同财产利益为由主张另一方放弃继承无效的，人民法院不予支持，但有证据证明放弃继承导致放弃一方不能履行法定扶养义务的除外。"},{"i":12,"n":"第十二条","txt":"父母一方或者其近亲属等抢夺、藏匿未成年子女，另一方向人民法院申请人身安全保护令或者参照适用民法典第九百九十七条规定申请人格权侵害禁令的，人民法院依法予以支持。"},{"i":13,"n":"第十三条","txt":"夫妻分居期间，一方或者其近亲属等抢夺、藏匿未成年子女，致使另一方无法履行监护职责，另一方请求行为人承担民事责任的，人民法院可以参照适用民法典第一千零八十四条关于离婚后子女抚养的有关规定，暂时确定未成年子女的抚养事宜，并明确暂时直接抚养未成年子女一方有协助另一方履行监护职责的义务。"},{"i":14,"n":"第十四条","txt":"离婚诉讼中，父母均要求直接抚养已满两周岁的未成年子女，一方有下列情形之一的，人民法院应当按照最有利于未成年子女的原则，优先考虑由另一方直接抚养："},{"i":15,"n":"第十五条","txt":"父母双方以法定代理人身份处分用夫妻共同财产购买并登记在未成年子女名下的房屋后，又以违反民法典第三十五条规定损害未成年子女利益为由向相对人主张该民事法律行为无效的，人民法院不予支持。"},{"i":16,"n":"第十六条","txt":"离婚协议中关于一方直接抚养未成年子女或者不能独立生活的成年子女、另一方不负担抚养费的约定，对双方具有法律约束力。但是，离婚后，直接抚养子女一方经济状况发生变化导致原生活水平显著降低或者子女生活、教育、医疗等必要合理费用确有显著增加，未成年子女或者不能独立生活的成年子女请求另一方支付抚养费的，人民法院依法予以支持，并综合考虑离婚协议整体约定、子女实际需要、另一方的负担能力、当地生活水平等因素，确定抚养费的数额。"},{"i":17,"n":"第十七条","txt":"离婚后，不直接抚养子女一方未按照离婚协议约定或者以其他方式作出的承诺给付抚养费，未成年子女或者不能独立生活的成年子女请求其支付欠付的抚养费的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"对民法典第一千零七十二条中继子女受继父或者继母抚养教育的事实，人民法院应当以共同生活时间长短为基础，综合考虑共同生活期间继父母是否实际进行生活照料、是否履行家庭教育职责、是否承担抚养费等因素予以认定。"},{"i":19,"n":"第十九条","txt":"生父与继母或者生母与继父离婚后，当事人主张继父或者继母和曾受其抚养教育的继子女之间的权利义务关系不再适用民法典关于父母子女关系规定的，人民法院应予支持，但继父或者继母与继子女存在依法成立的收养关系或者继子女仍与继父或者继母共同生活的除外。"},{"i":20,"n":"第二十条","txt":"离婚协议约定将部分或者全部夫妻共同财产给予子女，离婚后，一方在财产权利转移之前请求撤销该约定的，人民法院不予支持，但另一方同意的除外。"},{"i":21,"n":"第二十一条","txt":"离婚诉讼中，夫妻一方有证据证明在婚姻关系存续期间因抚育子女、照料老年人、协助另一方工作等负担较多义务，依据民法典第一千零八十八条规定请求另一方给予补偿的，人民法院可以综合考虑负担相应义务投入的时间、精力和对双方的影响以及给付方负担能力、当地居民人均可支配收入等因素，确定补偿数额。"},{"i":22,"n":"第二十二条","txt":"离婚诉讼中，一方存在年老、残疾、重病等生活困难情形，依据民法典第一千零九十条规定请求有负担能力的另一方给予适当帮助的，人民法院可以根据当事人请求，结合另一方财产状况，依法予以支持。"},{"i":23,"n":"第二十三条","txt":"本解释自2025年2月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianzongzebiand48e12":[{"i":1,"n":"第一条","txt":"民法典第二编至第七编对民事关系有规定的，人民法院直接适用该规定；民法典第二编至第七编没有规定的，适用民法典第一编的规定，但是根据其性质不能适用的除外。"},{"i":2,"n":"第二条","txt":"在一定地域、行业范围内长期为一般人从事民事活动时普遍遵守的民间习俗、惯常做法等，可以认定为民法典第十条规定的习惯。"},{"i":3,"n":"第三条","txt":"对于民法典第一百三十二条所称的滥用民事权利，人民法院可以根据权利行使的对象、目的、时间、方式、造成当事人之间利益失衡的程度等因素作出认定。"},{"i":4,"n":"第四条","txt":"涉及遗产继承、接受赠与等胎儿利益保护，父母在胎儿娩出前作为法定代理人主张相应权利的，人民法院依法予以支持。"},{"i":5,"n":"第五条","txt":"限制民事行为能力人实施的民事法律行为是否与其年龄、智力、精神健康状况相适应，人民法院可以从行为与本人生活相关联的程度，本人的智力、精神健康状况能否理解其行为并预见相应的后果，以及标的、数量、价款或者报酬等方面认定。"},{"i":6,"n":"第六条","txt":"人民法院认定自然人的监护能力，应当根据其年龄、身心健康状况、经济条件等因素确定；认定有关组织的监护能力，应当根据其资质、信用、财产状况等因素确定。"},{"i":7,"n":"第七条","txt":"担任监护人的被监护人父母通过遗嘱指定监护人，遗嘱生效时被指定的人不同意担任监护人的，人民法院应当适用民法典第二十七条、第二十八条的规定确定监护人。"},{"i":8,"n":"第八条","txt":"未成年人的父母与其他依法具有监护资格的人订立协议，约定免除具有监护能力的父母的监护职责的，人民法院不予支持。协议约定在未成年人的父母丧失监护能力时由该具有监护资格的人担任监护人的，人民法院依法予以支持。"},{"i":9,"n":"第九条","txt":"人民法院依据民法典第三十一条第二款、第三十六条第一款的规定指定监护人时，应当尊重被监护人的真实意愿，按照最有利于被监护人的原则指定，具体参考以下因素："},{"i":10,"n":"第十条","txt":"有关当事人不服居民委员会、村民委员会或者民政部门的指定，在接到指定通知之日起三十日内向人民法院申请指定监护人的，人民法院经审理认为指定并无不当，依法裁定驳回申请；认为指定不当，依法判决撤销指定并另行指定监护人。"},{"i":11,"n":"第十一条","txt":"具有完全民事行为能力的成年人与他人依据民法典第三十三条的规定订立书面协议事先确定自己的监护人后，协议的任何一方在该成年人丧失或者部分丧失民事行为能力前请求解除协议的，人民法院依法予以支持。该成年人丧失或者部分丧失民事行为能力后，协议确定的监护人无正当理由请求解除协议的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"监护人、其他依法具有监护资格的人之间就监护人是否有民法典第三十九条第一款第二项、第四项规定的应当终止监护关系的情形发生争议，申请变更监护人的，人民法院应当依法受理。经审理认为理由成立的，人民法院依法予以支持。"},{"i":13,"n":"第十三条","txt":"监护人因患病、外出务工等原因在一定期限内不能完全履行监护职责，将全部或者部分监护职责委托给他人，当事人主张受托人因此成为监护人的，人民法院不予支持。"},{"i":14,"n":"第十四条","txt":"人民法院审理宣告失踪案件时，下列人员应当认定为民法典第四十条规定的利害关系人："},{"i":15,"n":"第十五条","txt":"失踪人的财产代管人向失踪人的债务人请求偿还债务的，人民法院应当将财产代管人列为原告。"},{"i":16,"n":"第十六条","txt":"人民法院审理宣告死亡案件时，被申请人的配偶、父母、子女，以及依据民法典第一千一百二十九条规定对被申请人有继承权的亲属应当认定为民法典第四十六条规定的利害关系人。"},{"i":17,"n":"第十七条","txt":"自然人在战争期间下落不明的，利害关系人申请宣告死亡的期间适用民法典第四十六条第一款第一项的规定，自战争结束之日或者有关机关确定的下落不明之日起计算。"},{"i":18,"n":"第十八条","txt":"当事人未采用书面形式或者口头形式，但是实施的行为本身表明已经作出相应意思表示，并符合民事法律行为成立条件的，人民法院可以认定为民法典第一百三十五条规定的采用其他形式实施的民事法律行为。"},{"i":19,"n":"第十九条","txt":"行为人对行为的性质、对方当事人或者标的物的品种、质量、规格、价格、数量等产生错误认识，按照通常理解如果不发生该错误认识行为人就不会作出相应意思表示的，人民法院可以认定为民法典第一百四十七条规定的重大误解。"},{"i":20,"n":"第二十条","txt":"行为人以其意思表示存在第三人转达错误为由请求撤销民事法律行为的，适用本解释第十九条的规定。"},{"i":21,"n":"第二十一条","txt":"故意告知虚假情况，或者负有告知义务的人故意隐瞒真实情况，致使当事人基于错误认识作出意思表示的，人民法院可以认定为民法典第一百四十八条、第一百四十九条规定的欺诈。"},{"i":22,"n":"第二十二条","txt":"以给自然人及其近亲属等的人身权利、财产权利以及其他合法权益造成损害或者以给法人、非法人组织的名誉、荣誉、财产权益等造成损害为要挟，迫使其基于恐惧心理作出意思表示的，人民法院可以认定为民法典第一百五十条规定的胁迫。"},{"i":23,"n":"第二十三条","txt":"民事法律行为不成立，当事人请求返还财产、折价补偿或者赔偿损失的，参照适用民法典第一百五十七条的规定。"},{"i":24,"n":"第二十四条","txt":"民事法律行为所附条件不可能发生，当事人约定为生效条件的，人民法院应当认定民事法律行为不发生效力；当事人约定为解除条件的，应当认定未附条件，民事法律行为是否失效，依照民法典和相关法律、行政法规的规定认定。"},{"i":25,"n":"第二十五条","txt":"数个委托代理人共同行使代理权，其中一人或者数人未与其他委托代理人协商，擅自行使代理权的，依据民法典第一百七十一条、第一百七十二条等规定处理。"},{"i":26,"n":"第二十六条","txt":"由于急病、通讯联络中断、疫情防控等特殊原因，委托代理人自己不能办理代理事项，又不能与被代理人及时取得联系，如不及时转委托第三人代理，会给被代理人的利益造成损失或者扩大损失的，人民法院应当认定为民法典第一百六十九条规定的紧急情况。"},{"i":27,"n":"第二十七条","txt":"无权代理行为未被追认，相对人请求行为人履行债务或者赔偿损失的，由行为人就相对人知道或者应当知道行为人无权代理承担举证责任。行为人不能证明的，人民法院依法支持相对人的相应诉讼请求；行为人能够证明的，人民法院应当按照各自的过错认定行为人与相对人的责任。"},{"i":28,"n":"第二十八条","txt":"同时符合下列条件的，人民法院可以认定为民法典第一百七十二条规定的相对人有理由相信行为人有代理权："},{"i":29,"n":"第二十九条","txt":"法定代理人、被代理人依据民法典第一百四十五条、第一百七十一条的规定向相对人作出追认的意思表示的，人民法院应当依据民法典第一百三十七条的规定确认其追认意思表示的生效时间。"},{"i":30,"n":"第三十条","txt":"为了使国家利益、社会公共利益、本人或者他人的人身权利、财产权利以及其他合法权益免受正在进行的不法侵害，而针对实施侵害行为的人采取的制止不法侵害的行为，应当认定为民法典第一百八十一条规定的正当防卫。"},{"i":31,"n":"第三十一条","txt":"对于正当防卫是否超过必要的限度，人民法院应当综合不法侵害的性质、手段、强度、危害程度和防卫的时机、手段、强度、损害后果等因素判断。"},{"i":32,"n":"第三十二条","txt":"为了使国家利益、社会公共利益、本人或者他人的人身权利、财产权利以及其他合法权益免受正在发生的急迫危险，不得已而采取紧急措施的，应当认定为民法典第一百八十二条规定的紧急避险。"},{"i":33,"n":"第三十三条","txt":"对于紧急避险是否采取措施不当或者超过必要的限度，人民法院应当综合危险的性质、急迫程度、避险行为所保护的权益以及造成的损害后果等因素判断。"},{"i":34,"n":"第三十四条","txt":"因保护他人民事权益使自己受到损害，受害人依据民法典第一百八十三条的规定请求受益人适当补偿的，人民法院可以根据受害人所受损失和已获赔偿的情况、受益人受益的多少及其经济条件等因素确定受益人承担的补偿数额。"},{"i":35,"n":"第三十五条","txt":"民法典第一百八十八条第一款规定的三年诉讼时效期间，可以适用民法典有关诉讼时效中止、中断的规定，不适用延长的规定。该条第二款规定的二十年期间不适用中止、中断的规定。"},{"i":36,"n":"第三十六条","txt":"无民事行为能力人或者限制民事行为能力人的权利受到损害的，诉讼时效期间自其法定代理人知道或者应当知道权利受到损害以及义务人之日起计算，但是法律另有规定的除外。"},{"i":37,"n":"第三十七条","txt":"无民事行为能力人、限制民事行为能力人的权利受到原法定代理人损害，且在取得、恢复完全民事行为能力或者在原法定代理终止并确定新的法定代理人后，相应民事主体才知道或者应当知道权利受到损害的，有关请求权诉讼时效期间的计算适用民法典第一百八十八条第二款、本解释第三十六条的规定。"},{"i":38,"n":"第三十八条","txt":"诉讼时效依据民法典第一百九十五条的规定中断后，在新的诉讼时效期间内，再次出现第一百九十五条规定的中断事由，可以认定为诉讼时效再次中断。"},{"i":39,"n":"第三十九条","txt":"本解释自2022年3月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianyouguandan2fc042":[{"i":1,"n":"第一条","txt":"因抵押、质押、留置、保证等担保发生的纠纷，适用本解释。所有权保留买卖、融资租赁、保理等涉及担保功能发生的纠纷，适用本解释的有关规定。"},{"i":2,"n":"第二条","txt":"当事人在担保合同中约定担保合同的效力独立于主合同，或者约定担保人对主合同无效的法律后果承担担保责任，该有关担保独立性的约定无效。主合同有效的，有关担保独立性的约定无效不影响担保合同的效力；主合同无效的，人民法院应当认定担保合同无效，但是法律另有规定的除外。"},{"i":3,"n":"第三条","txt":"当事人对担保责任的承担约定专门的违约责任，或者约定的担保责任范围超出债务人应当承担的责任范围，担保人主张仅在债务人应当承担的责任范围内承担责任的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"有下列情形之一，当事人将担保物权登记在他人名下，债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，债权人或者其受托人主张就该财产优先受偿的，人民法院依法予以支持："},{"i":5,"n":"第五条","txt":"机关法人提供担保的，人民法院应当认定担保合同无效，但是经国务院批准为使用外国政府或者国际经济组织贷款进行转贷的除外。"},{"i":6,"n":"第六条","txt":"以公益为目的的非营利性学校、幼儿园、医疗机构、养老机构等提供担保的，人民法院应当认定担保合同无效，但是有下列情形之一的除外："},{"i":7,"n":"第七条","txt":"公司的法定代表人违反公司法关于公司对外担保决议程序的规定，超越权限代表公司与相对人订立担保合同，人民法院应当依照民法典第六十一条和第五百零四条等规定处理："},{"i":8,"n":"第八条","txt":"有下列情形之一，公司以其未依照公司法关于公司对外担保的规定作出决议为由主张不承担担保责任的，人民法院不予支持："},{"i":9,"n":"第九条","txt":"相对人根据上市公司公开披露的关于担保事项已经董事会或者股东大会决议通过的信息，与上市公司订立担保合同，相对人主张担保合同对上市公司发生效力，并由上市公司承担担保责任的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"一人有限责任公司为其股东提供担保，公司以违反公司法关于公司对外担保决议程序的规定为由主张不承担担保责任的，人民法院不予支持。公司因承担担保责任导致无法清偿其他债务，提供担保时的股东不能证明公司财产独立于自己的财产，其他债权人请求该股东承担连带责任的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"公司的分支机构未经公司股东（大）会或者董事会决议以自己的名义对外提供担保，相对人请求公司或者其分支机构承担担保责任的，人民法院不予支持，但是相对人不知道且不应当知道分支机构对外提供担保未经公司决议程序的除外。"},{"i":12,"n":"第十二条","txt":"法定代表人依照民法典第五百五十二条的规定以公司名义加入债务的，人民法院在认定该行为的效力时，可以参照本解释关于公司为他人提供担保的有关规则处理。"},{"i":13,"n":"第十三条","txt":"同一债务有两个以上第三人提供担保，担保人之间约定相互追偿及分担份额，承担了担保责任的担保人请求其他担保人按照约定分担份额的，人民法院应予支持；担保人之间约定承担连带共同担保，或者约定相互追偿但是未约定分担份额的，各担保人按照比例分担向债务人不能追偿的部分。"},{"i":14,"n":"第十四条","txt":"同一债务有两个以上第三人提供担保，担保人受让债权的，人民法院应当认定该行为系承担担保责任。受让债权的担保人作为债权人请求其他担保人承担担保责任的，人民法院不予支持；该担保人请求其他担保人分担相应份额的，依照本解释第十三条的规定处理。"},{"i":15,"n":"第十五条","txt":"最高额担保中的最高债权额，是指包括主债权及其利息、违约金、损害赔偿金、保管担保财产的费用、实现债权或者实现担保物权的费用等在内的全部债权，但是当事人另有约定的除外。"},{"i":16,"n":"第十六条","txt":"主合同当事人协议以新贷偿还旧贷，债权人请求旧贷的担保人承担担保责任的，人民法院不予支持；债权人请求新贷的担保人承担担保责任的，按照下列情形处理："},{"i":17,"n":"第十七条","txt":"主合同有效而第三人提供的担保合同无效，人民法院应当区分不同情形确定担保人的赔偿责任："},{"i":18,"n":"第十八条","txt":"承担了担保责任或者赔偿责任的担保人，在其承担责任的范围内向债务人追偿的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"担保合同无效，承担了赔偿责任的担保人按照反担保合同的约定，在其承担赔偿责任的范围内请求反担保人承担担保责任的，人民法院应予支持。"},{"i":20,"n":"第二十条","txt":"人民法院在审理第三人提供的物的担保纠纷案件时，可以适用民法典第六百九十五条第一款、第六百九十六条第一款、第六百九十七条第二款、第六百九十九条、第七百条、第七百零一条、第七百零二条等关于保证合同的规定。"},{"i":21,"n":"第二十一条","txt":"主合同或者担保合同约定了仲裁条款的，人民法院对约定仲裁条款的合同当事人之间的纠纷无管辖权。"},{"i":22,"n":"第二十二条","txt":"人民法院受理债务人破产案件后，债权人请求担保人承担担保责任，担保人主张担保债务自人民法院受理破产申请之日起停止计息的，人民法院对担保人的主张应予支持。"},{"i":23,"n":"第二十三条","txt":"人民法院受理债务人破产案件，债权人在破产程序中申报债权后又向人民法院提起诉讼，请求担保人承担担保责任的，人民法院依法予以支持。"},{"i":24,"n":"第二十四条","txt":"债权人知道或者应当知道债务人破产，既未申报债权也未通知担保人，致使担保人不能预先行使追偿权的，担保人就该债权在破产程序中可能受偿的范围内免除担保责任，但是担保人因自身过错未行使追偿权的除外。"},{"i":25,"n":"第二十五条","txt":"当事人在保证合同中约定了保证人在债务人不能履行债务或者无力偿还债务时才承担保证责任等类似内容，具有债务人应当先承担责任的意思表示的，人民法院应当将其认定为一般保证。"},{"i":26,"n":"第二十六条","txt":"一般保证中，债权人以债务人为被告提起诉讼的，人民法院应予受理。债权人未就主合同纠纷提起诉讼或者申请仲裁，仅起诉一般保证人的，人民法院应当驳回起诉。"},{"i":27,"n":"第二十七条","txt":"一般保证的债权人取得对债务人赋予强制执行效力的公证债权文书后，在保证期间内向人民法院申请强制执行，保证人以债权人未在保证期间内对债务人提起诉讼或者申请仲裁为由主张不承担保证责任的，人民法院不予支持。"},{"i":28,"n":"第二十八条","txt":"一般保证中，债权人依据生效法律文书对债务人的财产依法申请强制执行，保证债务诉讼时效的起算时间按照下列规则确定："},{"i":29,"n":"第二十九条","txt":"同一债务有两个以上保证人，债权人以其已经在保证期间内依法向部分保证人行使权利为由，主张已经在保证期间内向其他保证人行使权利的，人民法院不予支持。"},{"i":30,"n":"第三十条","txt":"最高额保证合同对保证期间的计算方式、起算时间等有约定的，按照其约定。"},{"i":31,"n":"第三十一条","txt":"一般保证的债权人在保证期间内对债务人提起诉讼或者申请仲裁后，又撤回起诉或者仲裁申请，债权人在保证期间届满前未再行提起诉讼或者申请仲裁，保证人主张不再承担保证责任的，人民法院应予支持。"},{"i":32,"n":"第三十二条","txt":"保证合同约定保证人承担保证责任直至主债务本息还清时为止等类似内容的，视为约定不明，保证期间为主债务履行期限届满之日起六个月。"},{"i":33,"n":"第三十三条","txt":"保证合同无效，债权人未在约定或者法定的保证期间内依法行使权利，保证人主张不承担赔偿责任的，人民法院应予支持。"},{"i":34,"n":"第三十四条","txt":"人民法院在审理保证合同纠纷案件时，应当将保证期间是否届满、债权人是否在保证期间内依法行使权利等事实作为案件基本事实予以查明。"},{"i":35,"n":"第三十五条","txt":"保证人知道或者应当知道主债权诉讼时效期间届满仍然提供保证或者承担保证责任，又以诉讼时效期间届满为由拒绝承担保证责任或者请求返还财产的，人民法院不予支持；保证人承担保证责任后向债务人追偿的，人民法院不予支持，但是债务人放弃诉讼时效抗辩的除外。"},{"i":36,"n":"第三十六条","txt":"第三人向债权人提供差额补足、流动性支持等类似承诺文件作为增信措施，具有提供担保的意思表示，债权人请求第三人承担保证责任的，人民法院应当依照保证的有关规定处理。"},{"i":37,"n":"第三十七条","txt":"当事人以所有权、使用权不明或者有争议的财产抵押，经审查构成无权处分的，人民法院应当依照民法典第三百一十一条的规定处理。"},{"i":38,"n":"第三十八条","txt":"主债权未受全部清偿，担保物权人主张就担保财产的全部行使担保物权的，人民法院应予支持，但是留置权人行使留置权的，应当依照民法典第四百五十条的规定处理。"},{"i":39,"n":"第三十九条","txt":"主债权被分割或者部分转让，各债权人主张就其享有的债权份额行使担保物权的，人民法院应予支持，但是法律另有规定或者当事人另有约定的除外。"},{"i":40,"n":"第四十条","txt":"从物产生于抵押权依法设立前，抵押权人主张抵押权的效力及于从物的，人民法院应予支持，但是当事人另有约定的除外。"},{"i":41,"n":"第四十一条","txt":"抵押权依法设立后，抵押财产被添附，添附物归第三人所有，抵押权人主张抵押权效力及于补偿金的，人民法院应予支持。"},{"i":42,"n":"第四十二条","txt":"抵押权依法设立后，抵押财产毁损、灭失或者被征收等，抵押权人请求按照原抵押权的顺位就保险金、赔偿金或者补偿金等优先受偿的，人民法院应予支持。"},{"i":43,"n":"第四十三条","txt":"当事人约定禁止或者限制转让抵押财产但是未将约定登记，抵押人违反约定转让抵押财产，抵押权人请求确认转让合同无效的，人民法院不予支持；抵押财产已经交付或者登记，抵押权人请求确认转让不发生物权效力的，人民法院不予支持，但是抵押权人有证据证明受让人知道的除外；抵押权人请求抵押人承担违约责任的，人民法院依法予以支持。"},{"i":44,"n":"第四十四条","txt":"主债权诉讼时效期间届满后，抵押权人主张行使抵押权的，人民法院不予支持；抵押人以主债权诉讼时效期间届满为由，主张不承担担保责任的，人民法院应予支持。主债权诉讼时效期间届满前，债权人仅对债务人提起诉讼，经人民法院判决或者调解后未在民事诉讼法规定的申请执行时效期间内对债务人申请强制执行，其向抵押人主张行使抵押权的，人民法院不予支持。"},{"i":45,"n":"第四十五条","txt":"当事人约定当债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，担保物权人有权将担保财产自行拍卖、变卖并就所得的价款优先受偿的，该约定有效。因担保人的原因导致担保物权人无法自行对担保财产进行拍卖、变卖，担保物权人请求担保人承担因此增加的费用的，人民法院应予支持。"},{"i":46,"n":"第四十六条","txt":"不动产抵押合同生效后未办理抵押登记手续，债权人请求抵押人办理抵押登记手续的，人民法院应予支持。"},{"i":47,"n":"第四十七条","txt":"不动产登记簿就抵押财产、被担保的债权范围等所作的记载与抵押合同约定不一致的，人民法院应当根据登记簿的记载确定抵押财产、被担保的债权范围等事项。"},{"i":48,"n":"第四十八条","txt":"当事人申请办理抵押登记手续时，因登记机构的过错致使其不能办理抵押登记，当事人请求登记机构承担赔偿责任的，人民法院依法予以支持。"},{"i":49,"n":"第四十九条","txt":"以违法的建筑物抵押的，抵押合同无效，但是一审法庭辩论终结前已经办理合法手续的除外。抵押合同无效的法律后果，依照本解释第十七条的有关规定处理。"},{"i":50,"n":"第五十条","txt":"抵押人以划拨建设用地上的建筑物抵押，当事人以该建设用地使用权不能抵押或者未办理批准手续为由主张抵押合同无效或者不生效的，人民法院不予支持。抵押权依法实现时，拍卖、变卖建筑物所得的价款，应当优先用于补缴建设用地使用权出让金。"},{"i":51,"n":"第五十一条","txt":"当事人仅以建设用地使用权抵押，债权人主张抵押权的效力及于土地上已有的建筑物以及正在建造的建筑物已完成部分的，人民法院应予支持。债权人主张抵押权的效力及于正在建造的建筑物的续建部分以及新增建筑物的，人民法院不予支持。"},{"i":52,"n":"第五十二条","txt":"当事人办理抵押预告登记后，预告登记权利人请求就抵押财产优先受偿，经审查存在尚未办理建筑物所有权首次登记、预告登记的财产与办理建筑物所有权首次登记时的财产不一致、抵押预告登记已经失效等情形，导致不具备办理抵押登记条件的，人民法院不予支持；经审查已经办理建筑物所有权首次登记，且不存在预告登记失效等情形的，人民法院应予支持，并应当认定抵押权自预告登记之日起设立。"},{"i":53,"n":"第五十三条","txt":"当事人在动产和权利担保合同中对担保财产进行概括描述，该描述能够合理识别担保财产的，人民法院应当认定担保成立。"},{"i":54,"n":"第五十四条","txt":"动产抵押合同订立后未办理抵押登记，动产抵押权的效力按照下列情形分别处理："},{"i":55,"n":"第五十五条","txt":"债权人、出质人与监管人订立三方协议，出质人以通过一定数量、品种等概括描述能够确定范围的货物为债务的履行提供担保，当事人有证据证明监管人系受债权人的委托监管并实际控制该货物的，人民法院应当认定质权于监管人实际控制货物之日起设立。监管人违反约定向出质人或者其他人放货、因保管不善导致货物毁损灭失，债权人请求监管人承担违约责任的，人民法院依法予以支持。"},{"i":56,"n":"第五十六条","txt":"买受人在出卖人正常经营活动中通过支付合理对价取得已被设立担保物权的动产，担保物权人请求就该动产优先受偿的，人民法院不予支持，但是有下列情形之一的除外："},{"i":57,"n":"第五十七条","txt":"担保人在设立动产浮动抵押并办理抵押登记后又购入或者以融资租赁方式承租新的动产，下列权利人为担保价款债权或者租金的实现而订立担保合同，并在该动产交付后十日内办理登记，主张其权利优先于在先设立的浮动抵押权的，人民法院应予支持："},{"i":58,"n":"第五十八条","txt":"以汇票出质，当事人以背书记载“质押”字样并在汇票上签章，汇票已经交付质权人的，人民法院应当认定质权自汇票交付质权人时设立。"},{"i":59,"n":"第五十九条","txt":"存货人或者仓单持有人在仓单上以背书记载“质押”字样，并经保管人签章，仓单已经交付质权人的，人民法院应当认定质权自仓单交付质权人时设立。没有权利凭证的仓单，依法可以办理出质登记的，仓单质权自办理出质登记时设立。"},{"i":60,"n":"第六十条","txt":"在跟单信用证交易中，开证行与开证申请人之间约定以提单作为担保的，人民法院应当依照民法典关于质权的有关规定处理。"},{"i":61,"n":"第六十一条","txt":"以现有的应收账款出质，应收账款债务人向质权人确认应收账款的真实性后，又以应收账款不存在或者已经消灭为由主张不承担责任的，人民法院不予支持。"},{"i":62,"n":"第六十二条","txt":"债务人不履行到期债务，债权人因同一法律关系留置合法占有的第三人的动产，并主张就该留置财产优先受偿的，人民法院应予支持。第三人以该留置财产并非债务人的财产为由请求返还的，人民法院不予支持。"},{"i":63,"n":"第六十三条","txt":"债权人与担保人订立担保合同，约定以法律、行政法规尚未规定可以担保的财产权利设立担保，当事人主张合同无效的，人民法院不予支持。当事人未在法定的登记机构依法进行登记，主张该担保具有物权效力的，人民法院不予支持。"},{"i":64,"n":"第六十四条","txt":"在所有权保留买卖中，出卖人依法有权取回标的物，但是与买受人协商不成，当事人请求参照民事诉讼法“实现担保物权案件”的有关规定，拍卖、变卖标的物的，人民法院应予准许。"},{"i":65,"n":"第六十五条","txt":"在融资租赁合同中，承租人未按照约定支付租金，经催告后在合理期限内仍不支付，出租人请求承租人支付全部剩余租金，并以拍卖、变卖租赁物所得的价款受偿的，人民法院应予支持；当事人请求参照民事诉讼法“实现担保物权案件”的有关规定，以拍卖、变卖租赁物所得价款支付租金的，人民法院应予准许。"},{"i":66,"n":"第六十六条","txt":"同一应收账款同时存在保理、应收账款质押和债权转让，当事人主张参照民法典第七百六十八条的规定确定优先顺序的，人民法院应予支持。"},{"i":67,"n":"第六十七条","txt":"在所有权保留买卖、融资租赁等合同中，出卖人、出租人的所有权未经登记不得对抗的“善意第三人”的范围及其效力，参照本解释第五十四条的规定处理。"},{"i":68,"n":"第六十八条","txt":"债务人或者第三人与债权人约定将财产形式上转移至债权人名下，债务人不履行到期债务，债权人有权对财产折价或者以拍卖、变卖该财产所得价款偿还债务的，人民法院应当认定该约定有效。当事人已经完成财产权利变动的公示，债务人不履行到期债务，债权人请求参照民法典关于担保物权的有关规定就该财产优先受偿的，人民法院应予支持。"},{"i":69,"n":"第六十九条","txt":"股东以将其股权转移至债权人名下的方式为债务履行提供担保，公司或者公司的债权人以股东未履行或者未全面履行出资义务、抽逃出资等为由，请求作为名义股东的债权人与股东承担连带责任的，人民法院不予支持。"},{"i":70,"n":"第七十条","txt":"债务人或者第三人为担保债务的履行，设立专门的保证金账户并由债权人实际控制，或者将其资金存入债权人设立的保证金账户，债权人主张就账户内的款项优先受偿的，人民法院应予支持。当事人以保证金账户内的款项浮动为由，主张实际控制该账户的债权人对账户内的款项不享有优先受偿权的，人民法院不予支持。"},{"i":71,"n":"第七十一条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianwuquanbiand14def":[{"i":1,"n":"第一条","txt":"因不动产物权的归属，以及作为不动产物权登记基础的买卖、赠与、抵押等产生争议，当事人提起民事诉讼的，应当依法受理。当事人已经在行政诉讼中申请一并解决上述民事争议，且人民法院一并审理的除外。"},{"i":2,"n":"第二条","txt":"当事人有证据证明不动产登记簿的记载与真实权利状态不符、其为该不动产物权的真实权利人，请求确认其享有物权的，应予支持。"},{"i":3,"n":"第三条","txt":"异议登记因民法典第二百二十条第二款规定的事由失效后，当事人提起民事诉讼，请求确认物权归属的，应当依法受理。异议登记失效不影响人民法院对案件的实体审理。"},{"i":4,"n":"第四条","txt":"未经预告登记的权利人同意，转让不动产所有权等物权，或者设立建设用地使用权、居住权、地役权、抵押权等其他物权的，应当依照民法典第二百二十一条第一款的规定，认定其不发生物权效力。"},{"i":5,"n":"第五条","txt":"预告登记的买卖不动产物权的协议被认定无效、被撤销，或者预告登记的权利人放弃债权的，应当认定为民法典第二百二十一条第二款所称的“债权消灭”。"},{"i":6,"n":"第六条","txt":"转让人转让船舶、航空器和机动车等所有权，受让人已经支付合理价款并取得占有，虽未经登记，但转让人的债权人主张其为民法典第二百二十五条所称的“善意第三人”的，不予支持，法律另有规定的除外。"},{"i":7,"n":"第七条","txt":"人民法院、仲裁机构在分割共有不动产或者动产等案件中作出并依法生效的改变原有物权关系的判决书、裁决书、调解书，以及人民法院在执行程序中作出的拍卖成交裁定书、变卖成交裁定书、以物抵债裁定书，应当认定为民法典第二百二十九条所称导致物权设立、变更、转让或者消灭的人民法院、仲裁机构的法律文书。"},{"i":8,"n":"第八条","txt":"依据民法典第二百二十九条至第二百三十一条规定享有物权，但尚未完成动产交付或者不动产登记的权利人，依据民法典第二百三十五条至第二百三十八条的规定，请求保护其物权的，应予支持。"},{"i":9,"n":"第九条","txt":"共有份额的权利主体因继承、遗赠等原因发生变化时，其他按份共有人主张优先购买的，不予支持，但按份共有人之间另有约定的除外。"},{"i":10,"n":"第十条","txt":"民法典第三百零五条所称的“同等条件”，应当综合共有份额的转让价格、价款履行方式及期限等因素确定。"},{"i":11,"n":"第十一条","txt":"优先购买权的行使期间，按份共有人之间有约定的，按照约定处理；没有约定或者约定不明的，按照下列情形确定："},{"i":12,"n":"第十二条","txt":"按份共有人向共有人之外的人转让其份额，其他按份共有人根据法律、司法解释规定，请求按照同等条件优先购买该共有份额的，应予支持。其他按份共有人的请求具有下列情形之一的，不予支持："},{"i":13,"n":"第十三条","txt":"按份共有人之间转让共有份额，其他按份共有人主张依据民法典第三百零五条规定优先购买的，不予支持，但按份共有人之间另有约定的除外。"},{"i":14,"n":"第十四条","txt":"受让人受让不动产或者动产时，不知道转让人无处分权，且无重大过失的，应当认定受让人为善意。"},{"i":15,"n":"第十五条","txt":"具有下列情形之一的，应当认定不动产受让人知道转让人无处分权："},{"i":16,"n":"第十六条","txt":"受让人受让动产时，交易的对象、场所或者时机等不符合交易习惯的，应当认定受让人具有重大过失。"},{"i":17,"n":"第十七条","txt":"民法典第三百一十一条第一款第一项所称的“受让人受让该不动产或者动产时”，是指依法完成不动产物权转移登记或者动产交付之时。"},{"i":18,"n":"第十八条","txt":"民法典第三百一十一条第一款第二项所称“合理的价格”，应当根据转让标的物的性质、数量以及付款方式等具体情况，参考转让时交易地市场价格以及交易习惯等因素综合认定。"},{"i":19,"n":"第十九条","txt":"转让人将民法典第二百二十五条规定的船舶、航空器和机动车等交付给受让人的，应当认定符合民法典第三百一十一条第一款第三项规定的善意取得的条件。"},{"i":20,"n":"第二十条","txt":"具有下列情形之一，受让人主张依据民法典第三百一十一条规定取得所有权的，不予支持："},{"i":21,"n":"第二十一条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianjichengbia5a96b0":[{"i":1,"n":"第一条","txt":"继承从被继承人生理死亡或者被宣告死亡时开始。"},{"i":2,"n":"第二条","txt":"承包人死亡时尚未取得承包收益的，可以将死者生前对承包所投入的资金和所付出的劳动及其增值和孳息，由发包单位或者接续承包合同的人合理折价、补偿。其价额作为遗产。"},{"i":3,"n":"第三条","txt":"被继承人生前与他人订有遗赠扶养协议，同时又立有遗嘱的，继承开始后，如果遗赠扶养协议与遗嘱没有抵触，遗产分别按协议和遗嘱处理；如果有抵触，按协议处理，与协议抵触的遗嘱全部或者部分无效。"},{"i":4,"n":"第四条","txt":"遗嘱继承人依遗嘱取得遗产后，仍有权依照民法典第一千一百三十条的规定取得遗嘱未处分的遗产。"},{"i":5,"n":"第五条","txt":"在遗产继承中，继承人之间因是否丧失继承权发生纠纷，向人民法院提起诉讼的，由人民法院依据民法典第一千一百二十五条的规定，判决确认其是否丧失继承权。"},{"i":6,"n":"第六条","txt":"继承人是否符合民法典第一千一百二十五条第一款第三项规定的“虐待被继承人情节严重”，可以从实施虐待行为的时间、手段、后果和社会影响等方面认定。"},{"i":7,"n":"第七条","txt":"继承人故意杀害被继承人的，不论是既遂还是未遂，均应当确认其丧失继承权。"},{"i":8,"n":"第八条","txt":"继承人有民法典第一千一百二十五条第一款第一项或者第二项所列之行为，而被继承人以遗嘱将遗产指定由该继承人继承的，可以确认遗嘱无效，并确认该继承人丧失继承权。"},{"i":9,"n":"第九条","txt":"继承人伪造、篡改、隐匿或者销毁遗嘱，侵害了缺乏劳动能力又无生活来源的继承人的利益，并造成其生活困难的，应当认定为民法典第一千一百二十五条第一款第四项规定的“情节严重”。"},{"i":10,"n":"第十条","txt":"被收养人对养父母尽了赡养义务，同时又对生父母扶养较多的，除可以依照民法典第一千一百二十七条的规定继承养父母的遗产外，还可以依照民法典第一千一百三十一条的规定分得生父母适当的遗产。"},{"i":11,"n":"第十一条","txt":"继子女继承了继父母遗产的，不影响其继承生父母的遗产。"},{"i":12,"n":"第十二条","txt":"养子女与生子女之间、养子女与养子女之间，系养兄弟姐妹，可以互为第二顺序继承人。"},{"i":13,"n":"第十三条","txt":"继兄弟姐妹之间的继承权，因继兄弟姐妹之间的扶养关系而发生。没有扶养关系的，不能互为第二顺序继承人。"},{"i":14,"n":"第十四条","txt":"被继承人的孙子女、外孙子女、曾孙子女、外曾孙子女都可以代位继承，代位继承人不受辈数的限制。"},{"i":15,"n":"第十五条","txt":"被继承人的养子女、已形成扶养关系的继子女的生子女可以代位继承；被继承人亲生子女的养子女可以代位继承；被继承人养子女的养子女可以代位继承；与被继承人已形成扶养关系的继子女的养子女也可以代位继承。"},{"i":16,"n":"第十六条","txt":"代位继承人缺乏劳动能力又没有生活来源，或者对被继承人尽过主要赡养义务的，分配遗产时，可以多分。"},{"i":17,"n":"第十七条","txt":"继承人丧失继承权的，其晚辈直系血亲不得代位继承。如该代位继承人缺乏劳动能力又没有生活来源，或者对被继承人尽赡养义务较多的，可以适当分给遗产。"},{"i":18,"n":"第十八条","txt":"丧偶儿媳对公婆、丧偶女婿对岳父母，无论其是否再婚，依照民法典第一千一百二十九条规定作为第一顺序继承人时，不影响其子女代位继承。"},{"i":19,"n":"第十九条","txt":"对被继承人生活提供了主要经济来源，或者在劳务等方面给予了主要扶助的，应当认定其尽了主要赡养义务或主要扶养义务。"},{"i":20,"n":"第二十条","txt":"依照民法典第一千一百三十一条规定可以分给适当遗产的人，分给他们遗产时，按具体情况可以多于或者少于继承人。"},{"i":21,"n":"第二十一条","txt":"依照民法典第一千一百三十一条规定可以分给适当遗产的人，在其依法取得被继承人遗产的权利受到侵犯时，本人有权以独立的诉讼主体资格向人民法院提起诉讼。"},{"i":22,"n":"第二十二条","txt":"继承人有扶养能力和扶养条件，愿意尽扶养义务，但被继承人因有固定收入和劳动能力，明确表示不要求其扶养的，分配遗产时，一般不应因此而影响其继承份额。"},{"i":23,"n":"第二十三条","txt":"有扶养能力和扶养条件的继承人虽然与被继承人共同生活，但对需要扶养的被继承人不尽扶养义务，分配遗产时，可以少分或者不分。"},{"i":24,"n":"第二十四条","txt":"继承人、受遗赠人的债权人、债务人，共同经营的合伙人，也应当视为与继承人、受遗赠人有利害关系，不能作为遗嘱的见证人。"},{"i":25,"n":"第二十五条","txt":"遗嘱人未保留缺乏劳动能力又没有生活来源的继承人的遗产份额，遗产处理时，应当为该继承人留下必要的遗产，所剩余的部分，才可参照遗嘱确定的分配原则处理。"},{"i":26,"n":"第二十六条","txt":"遗嘱人以遗嘱处分了国家、集体或者他人财产的，应当认定该部分遗嘱无效。"},{"i":27,"n":"第二十七条","txt":"自然人在遗书中涉及死后个人财产处分的内容，确为死者的真实意思表示，有本人签名并注明了年、月、日，又无相反证据的，可以按自书遗嘱对待。"},{"i":28,"n":"第二十八条","txt":"遗嘱人立遗嘱时必须具有完全民事行为能力。无民事行为能力人或者限制民事行为能力人所立的遗嘱，即使其本人后来具有完全民事行为能力，仍属无效遗嘱。遗嘱人立遗嘱时具有完全民事行为能力，后来成为无民事行为能力人或者限制民事行为能力人的，不影响遗嘱的效力。"},{"i":29,"n":"第二十九条","txt":"附义务的遗嘱继承或者遗赠，如义务能够履行，而继承人、受遗赠人无正当理由不履行，经受益人或者其他继承人请求，人民法院可以取消其接受附义务部分遗产的权利，由提出请求的继承人或者受益人负责按遗嘱人的意愿履行义务，接受遗产。"},{"i":30,"n":"第三十条","txt":"人民法院在审理继承案件时，如果知道有继承人而无法通知的，分割遗产时，要保留其应继承的遗产，并确定该遗产的保管人或者保管单位。"},{"i":31,"n":"第三十一条","txt":"应当为胎儿保留的遗产份额没有保留的，应从继承人所继承的遗产中扣回。"},{"i":32,"n":"第三十二条","txt":"继承人因放弃继承权，致其不能履行法定义务的，放弃继承权的行为无效。"},{"i":33,"n":"第三十三条","txt":"继承人放弃继承应当以书面形式向遗产管理人或者其他继承人表示。"},{"i":34,"n":"第三十四条","txt":"在诉讼中，继承人向人民法院以口头方式表示放弃继承的，要制作笔录，由放弃继承的人签名。"},{"i":35,"n":"第三十五条","txt":"继承人放弃继承的意思表示，应当在继承开始后、遗产分割前作出。遗产分割后表示放弃的不再是继承权，而是所有权。"},{"i":36,"n":"第三十六条","txt":"遗产处理前或者在诉讼进行中，继承人对放弃继承反悔的，由人民法院根据其提出的具体理由，决定是否承认。遗产处理后，继承人对放弃继承反悔的，不予承认。"},{"i":37,"n":"第三十七条","txt":"放弃继承的效力，追溯到继承开始的时间。"},{"i":38,"n":"第三十八条","txt":"继承开始后，受遗赠人表示接受遗赠，并于遗产分割前死亡的，其接受遗赠的权利转移给他的继承人。"},{"i":39,"n":"第三十九条","txt":"由国家或者集体组织供给生活费用的烈属和享受社会救济的自然人，其遗产仍应准许合法继承人继承。"},{"i":40,"n":"第四十条","txt":"继承人以外的组织或者个人与自然人签订遗赠扶养协议后，无正当理由不履行，导致协议解除的，不能享有受遗赠的权利，其支付的供养费用一般不予补偿；遗赠人无正当理由不履行，导致协议解除的，则应当偿还继承人以外的组织或者个人已支付的供养费用。"},{"i":41,"n":"第四十一条","txt":"遗产因无人继承又无人受遗赠归国家或者集体所有制组织所有时，按照民法典第一千一百三十一条规定可以分给适当遗产的人提出取得遗产的诉讼请求，人民法院应当视情况适当分给遗产。"},{"i":42,"n":"第四十二条","txt":"人民法院在分割遗产中的房屋、生产资料和特定职业所需要的财产时，应当依据有利于发挥其使用效益和继承人的实际需要，兼顾各继承人的利益进行处理。"},{"i":43,"n":"第四十三条","txt":"人民法院对故意隐匿、侵吞或者争抢遗产的继承人，可以酌情减少其应继承的遗产。"},{"i":44,"n":"第四十四条","txt":"继承诉讼开始后，如继承人、受遗赠人中有既不愿参加诉讼，又不表示放弃实体权利的，应当追加为共同原告；继承人已书面表示放弃继承、受遗赠人在知道受遗赠后六十日内表示放弃受遗赠或者到期没有表示的，不再列为当事人。"},{"i":45,"n":"第四十五条","txt":"本解释自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyonghaishisusongtebieche80240":[{"i":1,"n":"第一条","txt":"在海上或者通海水域发生的与船舶或者运输、生产、作业相关的海事侵权纠纷、海商合同纠纷，以及法律或者相关司法解释规定的其他海事纠纷案件由海事法院及其上级人民法院专门管辖。"},{"i":2,"n":"第二条","txt":"涉外海事侵权纠纷案件和海上运输合同纠纷案件的管辖，适用民事诉讼法第二十五章的规定；民事诉讼法第二十五章没有规定的，适用海事诉讼特别程序法第六条第二款（一）、（二）项的规定和民事诉讼法的其他有关规定。"},{"i":3,"n":"第三条","txt":"海事诉讼特别程序法第六条规定的海船指适合航行于海上或者通海水域的船舶。"},{"i":4,"n":"第四条","txt":"海事诉讼特别程序法第六条第二款（一）项规定的船籍港指被告船舶的船籍港。被告船舶的船籍港不在中华人民共和国领域内，原告船舶的船籍港在中华人民共和国领域内的，由原告船舶的船籍港所在地的海事法院管辖。"},{"i":5,"n":"第五条","txt":"海事诉讼特别程序法第六条第二款（二）项规定的起运港、转运港和到达港指合同约定的或者实际履行的起运港、转运港和到达港。合同约定的起运港、转运港和到达港与实际履行的起运港、转运港和到达港不一致的，以实际履行的地点确定案件管辖。"},{"i":6,"n":"第六条","txt":"海事诉讼特别程序法第六条第二款（四）项的保赔标的物所在地指保赔船舶的所在地。"},{"i":7,"n":"第七条","txt":"海事诉讼特别程序法第六条第二款（七）项规定的船舶所在地指起诉时船舶的停泊地或者船舶被扣押地。"},{"i":8,"n":"第八条","txt":"因船员劳务合同纠纷直接向海事法院提起的诉讼，海事法院应当受理。"},{"i":9,"n":"第九条","txt":"因海难救助费用提起的诉讼，除依照民事诉讼法第三十二条的规定确定管辖外，还可以由被救助的船舶以外的其他获救财产所在地的海事法院管辖。"},{"i":10,"n":"第十条","txt":"与船舶担保或者船舶优先权有关的借款合同纠纷，由被告住所地、合同履行地、船舶的船籍港、船舶所在地的海事法院管辖。"},{"i":11,"n":"第十一条","txt":"海事诉讼特别程序法第七条（三）项规定的有管辖权的海域指中华人民共和国的毗连区、专属经济区、大陆架以及有管辖权的其他海域。"},{"i":12,"n":"第十二条","txt":"海事诉讼特别程序法第七条（三）项规定的合同履行地指合同的实际履行地；合同未实际履行的，为合同约定的履行地。"},{"i":13,"n":"第十三条","txt":"当事人根据海事诉讼特别程序法第十一条的规定申请执行海事仲裁裁决，申请承认和执行国外海事仲裁裁决的，由被执行的财产所在地或者被执行人住所地的海事法院管辖；被执行的财产为船舶的，无论该船舶是否在海事法院管辖区域范围内，均由海事法院管辖。船舶所在地没有海事法院的，由就近的海事法院管辖。"},{"i":14,"n":"第十四条","txt":"认定海事仲裁协议效力案件，由被申请人住所地、合同履行地或者约定的仲裁机构所在地的海事法院管辖。"},{"i":15,"n":"第十五条","txt":"除海事法院及其上级人民法院外，地方人民法院对当事人提出的船舶保全申请应不予受理；地方人民法院为执行生效法律文书需要扣押和拍卖船舶的，应当委托船籍港所在地或者船舶所在地的海事法院执行。"},{"i":16,"n":"第十六条","txt":"两个以上海事法院都有管辖权的诉讼，原告可以向其中一个海事法院起诉；原告向两个以上有管辖权的海事法院起诉的，由最先立案的海事法院管辖。"},{"i":17,"n":"第十七条","txt":"海事法院之间因管辖权发生争议，由争议双方协商解决；协商解决不了的，报请最高人民法院指定管辖。"},{"i":18,"n":"第十八条","txt":"海事诉讼特别程序法第十二条规定的被请求人的财产包括船舶、船载货物、船用燃油以及船用物料。对其他财产的海事请求保全适用民事诉讼法有关财产保全的规定。"},{"i":19,"n":"第十九条","txt":"海事诉讼特别程序法规定的船载货物指处于承运人掌管之下，尚未装船或者已经装载于船上以及已经卸载的货物。"},{"i":20,"n":"第二十条","txt":"海事诉讼特别程序法第十三条规定的被保全的财产所在地指船舶的所在地或者货物的所在地。当事人在诉讼前对已经卸载但在承运人掌管之下的货物申请海事请求保全，如果货物所在地不在海事法院管辖区域的，可以向卸货港所在地的海事法院提出，也可以向货物所在地的地方人民法院提出。"},{"i":21,"n":"第二十一条","txt":"诉讼或者仲裁前申请海事请求保全适用海事诉讼特别程序法第十四条的规定。外国法院已受理相关海事案件或者有关纠纷已经提交仲裁，但涉案财产在中华人民共和国领域内，当事人向财产所在地的海事法院提出海事请求保全申请的，海事法院应当受理。"},{"i":22,"n":"第二十二条","txt":"利害关系人对海事法院作出的海事请求保全裁定提出异议，经审查认为理由不成立的，应当书面通知利害关系人。"},{"i":23,"n":"第二十三条","txt":"被请求人或者利害关系人依据海事诉讼特别程序法第二十条的规定要求海事请求人赔偿损失，向采取海事请求保全措施的海事法院提起诉讼的，海事法院应当受理。"},{"i":24,"n":"第二十四条","txt":"申请扣押船舶错误造成的损失，包括因船舶被扣押在停泊期间产生的各项维持费用与支出、船舶被扣押造成的船期损失和被申请人为使船舶解除扣押而提供担保所支出的费用。"},{"i":25,"n":"第二十五条","txt":"海事请求保全扣押船舶超过三十日、扣押货物或者其他财产超过十五日，海事请求人未提起诉讼或者未按照仲裁协议申请仲裁的，海事法院应当及时解除保全或者返还担保。"},{"i":26,"n":"第二十六条","txt":"申请人为申请扣押船舶提供限额担保，在扣押船舶期限届满时，未按照海事法院的通知追加担保的，海事法院可以解除扣押。"},{"i":27,"n":"第二十七条","txt":"海事诉讼特别程序法第十八条第二款、第七十四条规定的提供给海事请求人的担保，除被请求人和海事请求人有约定的外，海事请求人应当返还；海事请求人不返还担保的，该担保至海事请求保全期间届满之次日失效。"},{"i":28,"n":"第二十八条","txt":"船舶被扣押期间产生的各项维持费用和支出，应当作为为债权人共同利益支出的费用，从拍卖船舶的价款中优先拨付。"},{"i":29,"n":"第二十九条","txt":"海事法院根据海事诉讼特别程序法第二十七条的规定准许已经实施保全的船舶继续营运的，一般仅限于航行于国内航线上的船舶完成本航次。"},{"i":30,"n":"第三十条","txt":"申请扣押船舶的海事请求人在提起诉讼或者申请仲裁后，不申请拍卖被扣押船舶的，海事法院可以根据被申请人的申请拍卖船舶。拍卖所得价款由海事法院提存。"},{"i":31,"n":"第三十一条","txt":"海事法院裁定拍卖船舶，应当通过报纸或者其他新闻媒体连续公告三日。"},{"i":32,"n":"第三十二条","txt":"利害关系人请求终止拍卖被扣押船舶的，是否准许，海事法院应当作出裁定；海事法院裁定终止拍卖船舶的，为准备拍卖船舶所发生的费用由利害关系人承担。"},{"i":33,"n":"第三十三条","txt":"拍卖船舶申请人或者利害关系人申请终止拍卖船舶的，应当在公告确定的拍卖船舶日期届满七日前提出。"},{"i":34,"n":"第三十四条","txt":"海事请求人和被请求人应当按照海事法院的要求提供海事诉讼特别程序法第三十三条规定的已知的船舶优先权人、抵押权人和船舶所有人的有关确切情况。"},{"i":35,"n":"第三十五条","txt":"海事诉讼特别程序法第三十八条规定的船舶现状指船舶展示时的状况。船舶交接时的状况与船舶展示时的状况经评估确有明显差别的，船舶价款应当作适当的扣减，但属于正常损耗或者消耗的燃油不在此限。"},{"i":36,"n":"第三十六条","txt":"海事请求人申请扣押船载货物的价值应当与其请求的债权数额相当，但船载货物为不可分割的财产除外。"},{"i":37,"n":"第三十七条","txt":"拍卖的船舶移交后，海事法院应当及时通知相关的船舶登记机关。"},{"i":38,"n":"第三十八条","txt":"海事请求人申请扣押船用燃油、物料的，除适用海事诉讼特别程序法第五十条的规定外，还可以适用海事诉讼特别程序法第三章第一节的规定。"},{"i":39,"n":"第三十九条","txt":"二十总吨以下小型船艇的扣押和拍卖，可以依照民事诉讼法规定的扣押和拍卖程序进行。"},{"i":40,"n":"第四十条","txt":"申请人依据《中华人民共和国海商法》第八十八条规定申请拍卖留置的货物的，参照海事诉讼特别程序法关于拍卖船载货物的规定执行。"},{"i":41,"n":"第四十一条","txt":"诉讼或者仲裁前申请海事强制令的，适用海事诉讼特别程序法第五十三条的规定。"},{"i":42,"n":"第四十二条","txt":"海事法院根据海事诉讼特别程序法第五十七条规定，准予申请人海事强制令申请的，应当制作民事裁定书并发布海事强制令。"},{"i":43,"n":"第四十三条","txt":"海事强制令由海事法院执行。被申请人、其他相关单位或者个人不履行海事强制令的，海事法院应当依据民事诉讼法的有关规定强制执行。"},{"i":44,"n":"第四十四条","txt":"利害关系人对海事法院作出海事强制令的民事裁定提出异议，海事法院经审查认为理由不成立的，应当书面通知利害关系人。"},{"i":45,"n":"第四十五条","txt":"海事强制令发布后十五日内，被请求人未提出异议，也未就相关的海事纠纷提起诉讼或者申请仲裁的，海事法院可以应申请人的请求，返还其提供的担保。"},{"i":46,"n":"第四十六条","txt":"被请求人依据海事诉讼特别程序法第六十条的规定要求海事请求人赔偿损失的，由发布海事强制令的海事法院受理。"},{"i":47,"n":"第四十七条","txt":"诉讼前申请海事证据保全，适用海事诉讼特别程序法第六十四条的规定。"},{"i":48,"n":"第四十八条","txt":"海事请求人申请海事证据保全，申请书除应当依照海事诉讼特别程序法第六十五条的规定载明相应内容外，还应当载明证据收集、调取的有关线索。"},{"i":49,"n":"第四十九条","txt":"海事请求人在采取海事证据保全的海事法院提起诉讼后，可以申请复制保全的证据材料；相关海事纠纷在中华人民共和国领域内的其他海事法院或者仲裁机构受理的，受诉法院或者仲裁机构应海事请求人的申请可以申请复制保全的证据材料。"},{"i":50,"n":"第五十条","txt":"利害关系人对海事法院作出的海事证据保全裁定提出异议，海事法院经审查认为理由不成立的，应当书面通知利害关系人。"},{"i":51,"n":"第五十一条","txt":"被请求人依据海事诉讼特别程序法第七十一条的规定要求海事请求人赔偿损失的，由采取海事证据保全的海事法院受理。"},{"i":52,"n":"第五十二条","txt":"海事诉讼特别程序法第七十七条规定的正当理由指："},{"i":53,"n":"第五十三条","txt":"有关海事强制令、海事证据保全的法律文书可以向当事船舶的船长送达。"},{"i":54,"n":"第五十四条","txt":"应当向被告送达的开庭传票等法律文书，可以向被扣押的被告船舶的船长送达，但船长作为原告的除外。"},{"i":55,"n":"第五十五条","txt":"海事诉讼特别程序法第八十条第一款（三）项规定的其他适当方式包括传真、电子邮件（包括受送达人的专门网址）等送达方式。"},{"i":56,"n":"第五十六条","txt":"海事诉讼特别程序法第八十四条规定的当事人应当在开庭审理前完成举证的内容，包括当事人按照海事诉讼特别程序法第八十二条的规定填写《海事事故调查表》和提交有关船舶碰撞的事实证据材料。"},{"i":57,"n":"第五十七条","txt":"《海事事故调查表》属于当事人对发生船舶碰撞基本事实的陈述。经对方当事人认可或者经法院查证属实，可以作为认定事实的依据。"},{"i":58,"n":"第五十八条","txt":"有关船舶碰撞的事实证据材料指涉及船舶碰撞的经过、碰撞原因等方面的证据材料。"},{"i":59,"n":"第五十九条","txt":"海事诉讼特别程序法第八十五条规定的新的证据指非当事人所持有，在开庭前尚未掌握或者不能获得，因而在开庭前不能举证的证据。"},{"i":60,"n":"第六十条","txt":"因船舶碰撞以外的海事海商案件需要进行船舶检验或者估价的，适用海事诉讼特别程序法第八十六条的规定。"},{"i":61,"n":"第六十一条","txt":"依据《中华人民共和国海商法》第一百七十条的规定提起的诉讼和因船舶触碰造成损害提起的诉讼，参照海事诉讼特别程序法关于审理船舶碰撞案件的有关规定审理。"},{"i":62,"n":"第六十二条","txt":"未经理算的共同海损纠纷诉至海事法院的，海事法院应责令当事人自行委托共同海损理算。确有必要由海事法院委托理算的，由当事人提出申请，委托理算的费用由主张共同海损的当事人垫付。"},{"i":63,"n":"第六十三条","txt":"当事人对共同海损理算报告提出异议，经海事法院审查异议成立，需要补充理算或者重新理算的，应当由原委托人通知理算人进行理算。原委托人不通知理算的，海事法院可以通知理算人重新理算，有关费用由异议人垫付；异议人拒绝垫付费用的，视为撤销异议。"},{"i":64,"n":"第六十四条","txt":"因与共同海损纠纷有关的非共同海损损失向责任人提起的诉讼，适用海事诉讼特别程序法第九十二条规定的审限。"},{"i":65,"n":"第六十五条","txt":"保险人依据海事诉讼特别程序法第九十五条规定行使代位请求赔偿权利，应当以自己的名义进行；以他人名义提起诉讼的，海事法院应不予受理或者驳回起诉。"},{"i":66,"n":"第六十六条","txt":"保险人依据海事诉讼特别程序法第九十五条的规定请求变更当事人或者请求作为共同原告参加诉讼的，海事法院应当予以审查并作出是否准予的裁定。当事人对裁定不服的，可以提起上诉。"},{"i":67,"n":"第六十七条","txt":"保险人依据海事诉讼特别程序法第九十五条的规定参加诉讼的，被保险人依此前进行的诉讼行为所取得的财产保全或者通过扣押取得的担保权益等，在保险人的代位请求赔偿权利范围内对保险人有效。被保险人因自身过错产生的责任，保险人不予承担。"},{"i":68,"n":"第六十八条","txt":"海事诉讼特别程序法第九十六条规定的支付保险赔偿的凭证指赔偿金收据、银行支付单据或者其他支付凭证。仅有被保险人出具的权利转让书但不能出具实际支付证明的，不能作为保险人取得代位请求赔偿权利的事实依据。"},{"i":69,"n":"第六十九条","txt":"海事法院根据油污损害的保险人或者提供财务保证的其他人的请求，可以通知船舶所有人作为无独立请求权的第三人参加诉讼。"},{"i":70,"n":"第七十条","txt":"海事诉讼特别程序法第一百条规定的失控指提单或者其他提货凭证被盗、遗失。"},{"i":71,"n":"第七十一条","txt":"申请人依据海事诉讼特别程序法第一百条的规定向海事法院申请公示催告的，应当递交申请书。申请书应当载明：提单等提货凭证的种类、编号、货物品名、数量、承运人、托运人、收货人、承运船舶名称、航次以及背书情况和申请的理由、事实等。有副本的应当附有单证的副本。"},{"i":72,"n":"第七十二条","txt":"海事法院决定受理公示催告申请的，应当同时通知承运人、承运人的代理人或者货物保管人停止交付货物，并于三日内发出公告，敦促利害关系人申报权利。公示催告的期间由海事法院根据情况决定，但不得少于三十日。"},{"i":73,"n":"第七十三条","txt":"承运人、承运人的代理人或者货物保管人收到海事法院停止交付货物的通知后，应当停止交付，至公示催告程序终结。"},{"i":74,"n":"第七十四条","txt":"公示催告期间，转让提单的行为无效；有关货物的存储保管费用及风险由申请人承担。"},{"i":75,"n":"第七十五条","txt":"公示催告期间，国家重点建设项目待安装、施工、生产的货物，救灾物资，或者货物本身属性不宜长期保管以及季节性货物，在申请人提供充分可靠担保的情况下，海事法院可以依据申请人的申请作出由申请人提取货物的裁定。"},{"i":76,"n":"第七十六条","txt":"公示催告期间，利害关系人可以向海事法院申报权利。海事法院收到利害关系人的申报后，应当裁定终结公示催告程序，并通知申请人和承运人、承运人的代理人或者货物保管人。"},{"i":77,"n":"第七十七条","txt":"公示催告期间无人申报的，海事法院应当根据申请人的申请作出判决，宣告提单或者有关提货凭证无效。判决内容应当公告，并通知承运人、承运人的代理人或者货物保管人。自判决公告之日起，申请人有权请求承运人、承运人的代理人或者货物保管人交付货物。"},{"i":78,"n":"第七十八条","txt":"利害关系人因正当理由不能在公示催告期间向海事法院申报的，自知道或者应当知道判决公告之日起一年内，可以向作出判决的海事法院起诉。"},{"i":79,"n":"第七十九条","txt":"海事诉讼特别程序法第一百零一条规定的船舶所有人指有关船舶证书上载明的船舶所有人。"},{"i":80,"n":"第八十条","txt":"海事事故发生在中华人民共和国领域外的，船舶发生事故后进入中华人民共和国领域内的第一到达港视为海事诉讼特别程序法第一百零二条规定的事故发生地。"},{"i":81,"n":"第八十一条","txt":"当事人在诉讼中申请设立海事赔偿责任限制基金的，应当向受理相关海事纠纷案件的海事法院提出，但当事人之间订有有效诉讼管辖协议或者仲裁协议的除外。"},{"i":82,"n":"第八十二条","txt":"设立海事赔偿责任限制基金应当通过报纸或者其他新闻媒体连续公告三日。如果涉及的船舶是可以航行于国际航线的，应当通过对外发行的报纸或者其他新闻媒体发布公告。"},{"i":83,"n":"第八十三条","txt":"利害关系人依据海事诉讼特别程序法第一百零六条的规定对申请人设立海事赔偿责任限制基金提出异议的，海事法院应当对设立基金申请人的主体资格、事故所涉及的债权性质和申请设立基金的数额进行审查。"},{"i":84,"n":"第八十四条","txt":"准予申请人设立海事赔偿责任限制基金的裁定生效后，申请人应当在三日内在海事法院设立海事赔偿责任限制基金。申请人逾期未设立基金的，按自动撤回申请处理。"},{"i":85,"n":"第八十五条","txt":"海事诉讼特别程序法第一百零八条规定的担保指中华人民共和国境内的银行或者其他金融机构所出具的担保。"},{"i":86,"n":"第八十六条","txt":"设立海事赔偿责任限制基金后，向基金提出请求的任何人，不得就该项索赔对设立或以其名义设立基金的人的任何其他财产，行使任何权利。"},{"i":87,"n":"第八十七条","txt":"海事诉讼特别程序法第一百一十一条规定的与被拍卖船舶有关的债权指与被拍卖船舶有关的海事债权。"},{"i":88,"n":"第八十八条","txt":"海事诉讼特别程序法第一百一十五条规定的判决书、裁定书、调解书和仲裁裁决书指我国国内的判决书、裁定书、调解书和仲裁裁决书。对于债权人提供的国外的判决书、裁定书、调解书和仲裁裁决书，适用民事诉讼法第二百六十八条和第二百六十九条规定的程序审查。"},{"i":89,"n":"第八十九条","txt":"在债权登记前，债权人已向受理债权登记的海事法院以外的海事法院起诉的，受理案件的海事法院应当将案件移送至登记债权的海事法院一并审理，但案件已经进入二审的除外。"},{"i":90,"n":"第九十条","txt":"债权人依据海事诉讼特别程序法第一百一十六条规定向受理债权登记的海事法院提起确权诉讼的，应当在办理债权登记后七日内提起。"},{"i":91,"n":"第九十一条","txt":"海事诉讼特别程序法第一百一十九条第二款规定的三项费用按顺序拨付。"},{"i":92,"n":"第九十二条","txt":"船舶转让合同订立后船舶实际交付前，受让人即可申请船舶优先权催告。"},{"i":93,"n":"第九十三条","txt":"海事诉讼特别程序法第一百二十条规定的受让人指船舶转让中的买方和有买船意向的人，但受让人申请海事法院作出除权判决时，必须提交其已经实际受让船舶的证据。"},{"i":94,"n":"第九十四条","txt":"船舶受让人对不准予船舶优先权催告申请的裁定提出复议的，海事法院应当在七日内作出复议决定。"},{"i":95,"n":"第九十五条","txt":"海事法院准予船舶优先权催告申请的裁定生效后，应当通过报纸或者其他新闻媒体连续公告三日。优先权催告的船舶为可以航行于国际航线的，应当通过对外发行的报纸或者其他新闻媒体发布公告。"},{"i":96,"n":"第九十六条","txt":"利害关系人在船舶优先权催告期间提出优先权主张的，海事法院应当裁定优先权催告程序终结。"},{"i":97,"n":"第九十七条","txt":"在中华人民共和国领域内进行海事诉讼，适用海事诉讼特别程序法的规定。海事诉讼特别程序法没有规定的，适用民事诉讼法的有关规定。"},{"i":98,"n":"第九十八条","txt":"本规定自2003年2月1日起实施。"}],"zuigaorenminfayuanguanyushiyongshewaiminshiguanxif71b6a9":[{"i":1,"n":"第一条","txt":"人民法院审理涉外民商事案件适用外国法律的，应当根据涉外民事关系法律适用法第十条第一款的规定查明该国法律。"},{"i":2,"n":"第二条","txt":"人民法院可以通过下列途径查明外国法律："},{"i":3,"n":"第三条","txt":"当事人提供外国法律的，应当提交该国法律的具体规定并说明获得途径、效力情况、与案件争议的关联性等。外国法律为判例法的，还应当提交判例全文。"},{"i":4,"n":"第四条","txt":"法律查明服务机构、法律专家提供外国法律的，除提交本解释第三条规定的材料外，还应当提交法律查明服务机构的资质证明、法律专家的身份及资历证明，并附与案件无利害关系的书面声明。"},{"i":5,"n":"第五条","txt":"查明的外国法律的相关材料均应当在法庭上出示。人民法院应当听取各方当事人对外国法律的内容及其理解与适用的意见。"},{"i":6,"n":"第六条","txt":"人民法院可以召集庭前会议或者以其他适当方式，确定需要查明的外国法律的范围。"},{"i":7,"n":"第七条","txt":"人民法院认为有必要的，可以通知提供外国法律的法律查明服务机构或者法律专家出庭接受询问。当事人申请法律查明服务机构或者法律专家出庭，人民法院认为有必要的，可以准许。"},{"i":8,"n":"第八条","txt":"人民法院对外国法律的内容及其理解与适用，根据以下情形分别作出处理："},{"i":9,"n":"第九条","txt":"人民法院应当根据外国法律查明办理相关手续等所需时间确定当事人提供外国法律的期限。当事人有具体理由说明无法在人民法院确定的期限内提供外国法律而申请适当延长期限的，人民法院视情可予准许。"},{"i":10,"n":"第十条","txt":"人民法院依法适用外国法律审理案件，应当在裁判文书中载明外国法律的查明过程及外国法律的内容；人民法院认定外国法律不能查明的，应当载明不能查明的理由。"},{"i":11,"n":"第十一条","txt":"对查明外国法律的费用负担，当事人有约定的，从其约定；没有约定的，人民法院可以根据当事人的诉讼请求和具体案情，在作出裁判时确定上述合理费用的负担。"},{"i":12,"n":"第十二条","txt":"人民法院查明香港特别行政区、澳门特别行政区的法律，可以参照适用本解释。有关法律和司法解释对查明香港特别行政区、澳门特别行政区的法律另有规定的，从其规定。"},{"i":13,"n":"第十三条","txt":"本解释自2024年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyongxingzhengsusongfade32048a":[{"i":1,"n":"第一条","txt":"公民、法人或者其他组织对行政机关及其工作人员的行政行为不服，依法提起诉讼的，属于人民法院行政诉讼的受案范围。"},{"i":2,"n":"第二条","txt":"行政诉讼法第十三条第一项规定的“国家行为”，是指国务院、中央军事委员会、国防部、外交部等根据宪法和法律的授权，以国家的名义实施的有关国防和外交事务的行为，以及经宪法和法律授权的国家机关宣布紧急状态等行为。"},{"i":3,"n":"第三条","txt":"各级人民法院行政审判庭审理行政案件和审查行政机关申请执行其行政行为的案件。"},{"i":4,"n":"第四条","txt":"立案后，受诉人民法院的管辖权不受当事人住所地改变、追加被告等事实和法律状态变更的影响。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，属于行政诉讼法第十五条第三项规定的“本辖区内重大、复杂的案件”："},{"i":6,"n":"第六条","txt":"当事人以案件重大复杂为由，认为有管辖权的基层人民法院不宜行使管辖权或者根据行政诉讼法第五十二条的规定，向中级人民法院起诉，中级人民法院应当根据不同情况在七日内分别作出以下处理："},{"i":7,"n":"第七条","txt":"基层人民法院对其管辖的第一审行政案件，认为需要由中级人民法院审理或者指定管辖的，可以报请中级人民法院决定。中级人民法院应当根据不同情况在七日内分别作出以下处理："},{"i":8,"n":"第八条","txt":"行政诉讼法第十九条规定的“原告所在地”，包括原告的户籍所在地、经常居住地和被限制人身自由地。"},{"i":9,"n":"第九条","txt":"行政诉讼法第二十条规定的“因不动产提起的行政诉讼”是指因行政行为导致不动产物权变动而提起的诉讼。"},{"i":10,"n":"第十条","txt":"人民法院受理案件后，被告提出管辖异议的，应当在收到起诉状副本之日起十五日内提出。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，人民法院不予审查："},{"i":12,"n":"第十二条","txt":"有下列情形之一的，属于行政诉讼法第二十五条第一款规定的“与行政行为有利害关系”："},{"i":13,"n":"第十三条","txt":"债权人以行政机关对债务人所作的行政行为损害债权实现为由提起行政诉讼的，人民法院应当告知其就民事争议提起民事诉讼，但行政机关作出行政行为时依法应予保护或者应予考虑的除外。"},{"i":14,"n":"第十四条","txt":"行政诉讼法第二十五条第二款规定的“近亲属”，包括配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女和其他具有扶养、赡养关系的亲属。"},{"i":15,"n":"第十五条","txt":"合伙企业向人民法院提起诉讼的，应当以核准登记的字号为原告。未依法登记领取营业执照的个人合伙的全体合伙人为共同原告；全体合伙人可以推选代表人，被推选的代表人，应当由全体合伙人出具推选书。"},{"i":16,"n":"第十六条","txt":"股份制企业的股东大会、股东会、董事会等认为行政机关作出的行政行为侵犯企业经营自主权的，可以企业名义提起诉讼。"},{"i":17,"n":"第十七条","txt":"事业单位、社会团体、基金会、社会服务机构等非营利法人的出资人、设立人认为行政行为损害法人合法权益的，可以自己的名义提起诉讼。"},{"i":18,"n":"第十八条","txt":"业主委员会对于行政机关作出的涉及业主共有利益的行政行为，可以自己的名义提起诉讼。"},{"i":19,"n":"第十九条","txt":"当事人不服经上级行政机关批准的行政行为，向人民法院提起诉讼的，以在对外发生法律效力的文书上署名的机关为被告。"},{"i":20,"n":"第二十条","txt":"行政机关组建并赋予行政管理职能但不具有独立承担法律责任能力的机构，以自己的名义作出行政行为，当事人不服提起诉讼的，应当以组建该机构的行政机关为被告。"},{"i":21,"n":"第二十一条","txt":"当事人对由国务院、省级人民政府批准设立的开发区管理机构作出的行政行为不服提起诉讼的，以该开发区管理机构为被告；对由国务院、省级人民政府批准设立的开发区管理机构所属职能部门作出的行政行为不服提起诉讼的，以其职能部门为被告；对其他开发区管理机构所属职能部门作出的行政行为不服提起诉讼的，以开发区管理机构为被告；开发区管理机构没有行政主体资格的，以设立该机构的地方人民政府为被告。"},{"i":22,"n":"第二十二条","txt":"行政诉讼法第二十六条第二款规定的“复议机关改变原行政行为”，是指复议机关改变原行政行为的处理结果。复议机关改变原行政行为所认定的主要事实和证据、改变原行政行为所适用的规范依据，但未改变原行政行为处理结果的，视为复议机关维持原行政行为。"},{"i":23,"n":"第二十三条","txt":"行政机关被撤销或者职权变更，没有继续行使其职权的行政机关的，以其所属的人民政府为被告；实行垂直领导的，以垂直领导的上一级行政机关为被告。"},{"i":24,"n":"第二十四条","txt":"当事人对村民委员会或者居民委员会依据法律、法规、规章的授权履行行政管理职责的行为不服提起诉讼的，以村民委员会或者居民委员会为被告。"},{"i":25,"n":"第二十五条","txt":"市、县级人民政府确定的房屋征收部门组织实施房屋征收与补偿工作过程中作出行政行为，被征收人不服提起诉讼的，以房屋征收部门为被告。"},{"i":26,"n":"第二十六条","txt":"原告所起诉的被告不适格，人民法院应当告知原告变更被告；原告不同意变更的，裁定驳回起诉。"},{"i":27,"n":"第二十七条","txt":"必须共同进行诉讼的当事人没有参加诉讼的，人民法院应当依法通知其参加；当事人也可以向人民法院申请参加。"},{"i":28,"n":"第二十八条","txt":"人民法院追加共同诉讼的当事人时，应当通知其他当事人。应当追加的原告，已明确表示放弃实体权利的，可不予追加；既不愿意参加诉讼，又不放弃实体权利的，应追加为第三人，其不参加诉讼，不能阻碍人民法院对案件的审理和裁判。"},{"i":29,"n":"第二十九条","txt":"行政诉讼法第二十八条规定的“人数众多”，一般指十人以上。"},{"i":30,"n":"第三十条","txt":"行政机关的同一行政行为涉及两个以上利害关系人，其中一部分利害关系人对行政行为不服提起诉讼，人民法院应当通知没有起诉的其他利害关系人作为第三人参加诉讼。"},{"i":31,"n":"第三十一条","txt":"当事人委托诉讼代理人，应当向人民法院提交由委托人签名或者盖章的授权委托书。委托书应当载明委托事项和具体权限。公民在特殊情况下无法书面委托的，也可以由他人代书，并由自己捺印等方式确认，人民法院应当核实并记录在卷；被诉行政机关或者其他有义务协助的机关拒绝人民法院向被限制人身自由的公民核实的，视为委托成立。当事人解除或者变更委托的，应当书面报告人民法院。"},{"i":32,"n":"第三十二条","txt":"依照行政诉讼法第三十一条第二款第二项规定，与当事人有合法劳动人事关系的职工，可以当事人工作人员的名义作为诉讼代理人。以当事人的工作人员身份参加诉讼活动，应当提交以下证据之一加以证明："},{"i":33,"n":"第三十三条","txt":"根据行政诉讼法第三十一条第二款第三项规定，有关社会团体推荐公民担任诉讼代理人的，应当符合下列条件："},{"i":34,"n":"第三十四条","txt":"根据行政诉讼法第三十六条第一款的规定，被告申请延期提供证据的，应当在收到起诉状副本之日起十五日内以书面方式向人民法院提出。人民法院准许延期提供的，被告应当在正当事由消除后十五日内提供证据。逾期提供的，视为被诉行政行为没有相应的证据。"},{"i":35,"n":"第三十五条","txt":"原告或者第三人应当在开庭审理前或者人民法院指定的交换证据清单之日提供证据。因正当事由申请延期提供证据的，经人民法院准许，可以在法庭调查中提供。逾期提供证据的，人民法院应当责令其说明理由；拒不说明理由或者理由不成立的，视为放弃举证权利。"},{"i":36,"n":"第三十六条","txt":"当事人申请延长举证期限，应当在举证期限届满前向人民法院提出书面申请。"},{"i":37,"n":"第三十七条","txt":"根据行政诉讼法第三十九条的规定，对当事人无争议，但涉及国家利益、公共利益或者他人合法权益的事实，人民法院可以责令当事人提供或者补充有关证据。"},{"i":38,"n":"第三十八条","txt":"对于案情比较复杂或者证据数量较多的案件，人民法院可以组织当事人在开庭前向对方出示或者交换证据，并将交换证据清单的情况记录在卷。"},{"i":39,"n":"第三十九条","txt":"当事人申请调查收集证据，但该证据与待证事实无关联、对证明待证事实无意义或者其他无调查收集必要的，人民法院不予准许。"},{"i":40,"n":"第四十条","txt":"人民法院在证人出庭作证前应当告知其如实作证的义务以及作伪证的法律后果。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一，原告或者第三人要求相关行政执法人员出庭说明的，人民法院可以准许："},{"i":42,"n":"第四十二条","txt":"能够反映案件真实情况、与待证事实相关联、来源和形式符合法律规定的证据，应当作为认定案件事实的根据。"},{"i":43,"n":"第四十三条","txt":"有下列情形之一的，属于行政诉讼法第四十三条第三款规定的“以非法手段取得的证据”："},{"i":44,"n":"第四十四条","txt":"人民法院认为有必要的，可以要求当事人本人或者行政机关执法人员到庭，就案件有关事实接受询问。在询问之前，可以要求其签署保证书。"},{"i":45,"n":"第四十五条","txt":"被告有证据证明其在行政程序中依照法定程序要求原告或者第三人提供证据，原告或者第三人依法应当提供而没有提供，在诉讼程序中提供的证据，人民法院一般不予采纳。"},{"i":46,"n":"第四十六条","txt":"原告或者第三人确有证据证明被告持有的证据对原告或者第三人有利的，可以在开庭审理前书面申请人民法院责令行政机关提交。"},{"i":47,"n":"第四十七条","txt":"根据行政诉讼法第三十八条第二款的规定，在行政赔偿、补偿案件中，因被告的原因导致原告无法就损害情况举证的，应当由被告就该损害情况承担举证责任。"},{"i":48,"n":"第四十八条","txt":"期间包括法定期间和人民法院指定的期间。"},{"i":49,"n":"第四十九条","txt":"行政诉讼法第五十一条第二款规定的立案期限，因起诉状内容欠缺或者有其他错误通知原告限期补正的，从补正后递交人民法院的次日起算。由上级人民法院转交下级人民法院立案的案件，从受诉人民法院收到起诉状的次日起算。"},{"i":50,"n":"第五十条","txt":"行政诉讼法第八十一条、第八十三条、第八十八条规定的审理期限，是指从立案之日起至裁判宣告、调解书送达之日止的期间，但公告期间、鉴定期间、调解期间、中止诉讼期间、审理当事人提出的管辖异议以及处理人民法院之间的管辖争议期间不应计算在内。"},{"i":51,"n":"第五十一条","txt":"人民法院可以要求当事人签署送达地址确认书，当事人确认的送达地址为人民法院法律文书的送达地址。"},{"i":52,"n":"第五十二条","txt":"人民法院可以在当事人住所地以外向当事人直接送达诉讼文书。当事人拒绝签署送达回证的，采用拍照、录像等方式记录送达过程即视为送达。审判人员、书记员应当在送达回证上注明送达情况并签名。"},{"i":53,"n":"第五十三条","txt":"人民法院对符合起诉条件的案件应当立案，依法保障当事人行使诉讼权利。"},{"i":54,"n":"第五十四条","txt":"依照行政诉讼法第四十九条的规定，公民、法人或者其他组织提起诉讼时应当提交以下起诉材料："},{"i":55,"n":"第五十五条","txt":"依照行政诉讼法第五十一条的规定，人民法院应当就起诉状内容和材料是否完备以及是否符合行政诉讼法规定的起诉条件进行审查。"},{"i":56,"n":"第五十六条","txt":"法律、法规规定应当先申请复议，公民、法人或者其他组织未申请复议直接提起诉讼的，人民法院裁定不予立案。"},{"i":57,"n":"第五十七条","txt":"法律、法规未规定行政复议为提起行政诉讼必经程序，公民、法人或者其他组织既提起诉讼又申请行政复议的，由先立案的机关管辖；同时立案的，由公民、法人或者其他组织选择。公民、法人或者其他组织已经申请行政复议，在法定复议期间内又向人民法院提起诉讼的，人民法院裁定不予立案。"},{"i":58,"n":"第五十八条","txt":"法律、法规未规定行政复议为提起行政诉讼必经程序，公民、法人或者其他组织向复议机关申请行政复议后，又经复议机关同意撤回复议申请，在法定起诉期限内对原行政行为提起诉讼的，人民法院应当依法立案。"},{"i":59,"n":"第五十九条","txt":"公民、法人或者其他组织向复议机关申请行政复议后，复议机关作出维持决定的，应当以复议机关和原行为机关为共同被告，并以复议决定送达时间确定起诉期限。"},{"i":60,"n":"第六十条","txt":"人民法院裁定准许原告撤诉后，原告以同一事实和理由重新起诉的，人民法院不予立案。"},{"i":61,"n":"第六十一条","txt":"原告或者上诉人未按规定的期限预交案件受理费，又不提出缓交、减交、免交申请，或者提出申请未获批准的，按自动撤诉处理。在按撤诉处理后，原告或者上诉人在法定期限内再次起诉或者上诉，并依法解决诉讼费预交问题的，人民法院应予立案。"},{"i":62,"n":"第六十二条","txt":"人民法院判决撤销行政机关的行政行为后，公民、法人或者其他组织对行政机关重新作出的行政行为不服向人民法院起诉的，人民法院应当依法立案。"},{"i":63,"n":"第六十三条","txt":"行政机关作出行政行为时，没有制作或者没有送达法律文书，公民、法人或者其他组织只要能证明行政行为存在，并在法定期限内起诉的，人民法院应当依法立案。"},{"i":64,"n":"第六十四条","txt":"行政机关作出行政行为时，未告知公民、法人或者其他组织起诉期限的，起诉期限从公民、法人或者其他组织知道或者应当知道起诉期限之日起计算，但从知道或者应当知道行政行为内容之日起最长不得超过一年。"},{"i":65,"n":"第六十五条","txt":"公民、法人或者其他组织不知道行政机关作出的行政行为内容的，其起诉期限从知道或者应当知道该行政行为内容之日起计算，但最长不得超过行政诉讼法第四十六条第二款规定的起诉期限。"},{"i":66,"n":"第六十六条","txt":"公民、法人或者其他组织依照行政诉讼法第四十七条第一款的规定，对行政机关不履行法定职责提起诉讼的，应当在行政机关履行法定职责期限届满之日起六个月内提出。"},{"i":67,"n":"第六十七条","txt":"原告提供被告的名称等信息足以使被告与其他行政机关相区别的，可以认定为行政诉讼法第四十九条第二项规定的“有明确的被告”。"},{"i":68,"n":"第六十八条","txt":"行政诉讼法第四十九条第三项规定的“有具体的诉讼请求”是指："},{"i":69,"n":"第六十九条","txt":"有下列情形之一，已经立案的，应当裁定驳回起诉："},{"i":70,"n":"第七十条","txt":"起诉状副本送达被告后，原告提出新的诉讼请求的，人民法院不予准许，但有正当理由的除外。"},{"i":71,"n":"第七十一条","txt":"人民法院适用普通程序审理案件，应当在开庭三日前用传票传唤当事人。对证人、鉴定人、勘验人、翻译人员，应当用通知书通知其到庭。当事人或者其他诉讼参与人在外地的，应当留有必要的在途时间。"},{"i":72,"n":"第七十二条","txt":"有下列情形之一的，可以延期开庭审理："},{"i":73,"n":"第七十三条","txt":"根据行政诉讼法第二十七条的规定，有下列情形之一的，人民法院可以决定合并审理："},{"i":74,"n":"第七十四条","txt":"当事人申请回避，应当说明理由，在案件开始审理时提出；回避事由在案件开始审理后知道的，应当在法庭辩论终结前提出。"},{"i":75,"n":"第七十五条","txt":"在一个审判程序中参与过本案审判工作的审判人员，不得再参与该案其他程序的审判。"},{"i":76,"n":"第七十六条","txt":"人民法院对于因一方当事人的行为或者其他原因，可能使行政行为或者人民法院生效裁判不能或者难以执行的案件，根据对方当事人的申请，可以裁定对其财产进行保全、责令其作出一定行为或者禁止其作出一定行为；当事人没有提出申请的，人民法院在必要时也可以裁定采取上述保全措施。"},{"i":77,"n":"第七十七条","txt":"利害关系人因情况紧急，不立即申请保全将会使其合法权益受到难以弥补的损害的，可以在提起诉讼前向被保全财产所在地、被申请人住所地或者对案件有管辖权的人民法院申请采取保全措施。申请人应当提供担保，不提供担保的，裁定驳回申请。"},{"i":78,"n":"第七十八条","txt":"保全限于请求的范围，或者与本案有关的财物。"},{"i":79,"n":"第七十九条","txt":"原告或者上诉人申请撤诉，人民法院裁定不予准许的，原告或者上诉人经传票传唤无正当理由拒不到庭，或者未经法庭许可中途退庭的，人民法院可以缺席判决。"},{"i":80,"n":"第八十条","txt":"原告或者上诉人在庭审中明确拒绝陈述或者以其他方式拒绝陈述，导致庭审无法进行，经法庭释明法律后果后仍不陈述意见的，视为放弃陈述权利，由其承担不利的法律后果。"},{"i":81,"n":"第八十一条","txt":"被告在一审期间改变被诉行政行为的，应当书面告知人民法院。"},{"i":82,"n":"第八十二条","txt":"当事人之间恶意串通，企图通过诉讼等方式侵害国家利益、社会公共利益或者他人合法权益的，人民法院应当裁定驳回起诉或者判决驳回其请求，并根据情节轻重予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"行政诉讼法第五十九条规定的罚款、拘留可以单独适用，也可以合并适用。"},{"i":84,"n":"第八十四条","txt":"人民法院审理行政诉讼法第六十条第一款规定的行政案件，认为法律关系明确、事实清楚，在征得当事人双方同意后，可以迳行调解。"},{"i":85,"n":"第八十五条","txt":"调解达成协议，人民法院应当制作调解书。调解书应当写明诉讼请求、案件的事实和调解结果。"},{"i":86,"n":"第八十六条","txt":"人民法院审理行政案件，调解过程不公开，但当事人同意公开的除外。"},{"i":87,"n":"第八十七条","txt":"在诉讼过程中，有下列情形之一的，中止诉讼："},{"i":88,"n":"第八十八条","txt":"在诉讼过程中，有下列情形之一的，终结诉讼："},{"i":89,"n":"第八十九条","txt":"复议决定改变原行政行为错误，人民法院判决撤销复议决定时，可以一并责令复议机关重新作出复议决定或者判决恢复原行政行为的法律效力。"},{"i":90,"n":"第九十条","txt":"人民法院判决被告重新作出行政行为，被告重新作出的行政行为与原行政行为的结果相同，但主要事实或者主要理由有改变的，不属于行政诉讼法第七十一条规定的情形。"},{"i":91,"n":"第九十一条","txt":"原告请求被告履行法定职责的理由成立，被告违法拒绝履行或者无正当理由逾期不予答复的，人民法院可以根据行政诉讼法第七十二条的规定，判决被告在一定期限内依法履行原告请求的法定职责；尚需被告调查或者裁量的，应当判决被告针对原告的请求重新作出处理。"},{"i":92,"n":"第九十二条","txt":"原告申请被告依法履行支付抚恤金、最低生活保障待遇或者社会保险待遇等给付义务的理由成立，被告依法负有给付义务而拒绝或者拖延履行义务的，人民法院可以根据行政诉讼法第七十三条的规定，判决被告在一定期限内履行相应的给付义务。"},{"i":93,"n":"第九十三条","txt":"原告请求被告履行法定职责或者依法履行支付抚恤金、最低生活保障待遇或者社会保险待遇等给付义务，原告未先向行政机关提出申请的，人民法院裁定驳回起诉。"},{"i":94,"n":"第九十四条","txt":"公民、法人或者其他组织起诉请求撤销行政行为，人民法院经审查认为行政行为无效的，应当作出确认无效的判决。"},{"i":95,"n":"第九十五条","txt":"人民法院经审理认为被诉行政行为违法或者无效，可能给原告造成损失，经释明，原告请求一并解决行政赔偿争议的，人民法院可以就赔偿事项进行调解；调解不成的，应当一并判决。人民法院也可以告知其就赔偿事项另行提起诉讼。"},{"i":96,"n":"第九十六条","txt":"有下列情形之一，且对原告依法享有的听证、陈述、申辩等重要程序性权利不产生实质损害的，属于行政诉讼法第七十四条第一款第二项规定的“程序轻微违法”："},{"i":97,"n":"第九十七条","txt":"原告或者第三人的损失系由其自身过错和行政机关的违法行政行为共同造成的，人民法院应当依据各方行为与损害结果之间有无因果关系以及在损害发生和结果中作用力的大小，确定行政机关相应的赔偿责任。"},{"i":98,"n":"第九十八条","txt":"因行政机关不履行、拖延履行法定职责，致使公民、法人或者其他组织的合法权益遭受损害的，人民法院应当判决行政机关承担行政赔偿责任。在确定赔偿数额时，应当考虑该不履行、拖延履行法定职责的行为在损害发生过程和结果中所起的作用等因素。"},{"i":99,"n":"第九十九条","txt":"有下列情形之一的，属于行政诉讼法第七十五条规定的“重大且明显违法”："},{"i":100,"n":"第一百条","txt":"人民法院审理行政案件，适用最高人民法院司法解释的，应当在裁判文书中援引。"},{"i":101,"n":"第一百零一条","txt":"裁定适用于下列范围："},{"i":102,"n":"第一百零二条","txt":"行政诉讼法第八十二条规定的行政案件中的“事实清楚”，是指当事人对争议的事实陈述基本一致，并能提供相应的证据，无须人民法院调查收集证据即可查明事实；“权利义务关系明确”，是指行政法律关系中权利和义务能够明确区分；“争议不大”，是指当事人对行政行为的合法性、责任承担等没有实质分歧。"},{"i":103,"n":"第一百零三条","txt":"适用简易程序审理的行政案件，人民法院可以用口头通知、电话、短信、传真、电子邮件等简便方式传唤当事人、通知证人、送达裁判文书以外的诉讼文书。"},{"i":104,"n":"第一百零四条","txt":"适用简易程序案件的举证期限由人民法院确定，也可以由当事人协商一致并经人民法院准许，但不得超过十五日。被告要求书面答辩的，人民法院可以确定合理的答辩期间。"},{"i":105,"n":"第一百零五条","txt":"人民法院发现案情复杂，需要转为普通程序审理的，应当在审理期限届满前作出裁定并将合议庭组成人员及相关事项书面通知双方当事人。"},{"i":106,"n":"第一百零六条","txt":"当事人就已经提起诉讼的事项在诉讼过程中或者裁判生效后再次起诉，同时具有下列情形的，构成重复起诉："},{"i":107,"n":"第一百零七条","txt":"第一审人民法院作出判决和裁定后，当事人均提起上诉的，上诉各方均为上诉人。"},{"i":108,"n":"第一百零八条","txt":"当事人提出上诉，应当按照其他当事人或者诉讼代表人的人数提出上诉状副本。"},{"i":109,"n":"第一百零九条","txt":"第二审人民法院经审理认为原审人民法院不予立案或者驳回起诉的裁定确有错误且当事人的起诉符合起诉条件的，应当裁定撤销原审人民法院的裁定，指令原审人民法院依法立案或者继续审理。"},{"i":110,"n":"第一百一十条","txt":"当事人向上一级人民法院申请再审，应当在判决、裁定或者调解书发生法律效力后六个月内提出。有下列情形之一的，自知道或者应当知道之日起六个月内提出："},{"i":111,"n":"第一百一十一条","txt":"当事人申请再审的，应当提交再审申请书等材料。人民法院认为有必要的，可以自收到再审申请书之日起五日内将再审申请书副本发送对方当事人。对方当事人应当自收到再审申请书副本之日起十五日内提交书面意见。人民法院可以要求申请人和对方当事人补充有关材料，询问有关事项。"},{"i":112,"n":"第一百一十二条","txt":"人民法院应当自再审申请案件立案之日起六个月内审查，有特殊情况需要延长的，由本院院长批准。"},{"i":113,"n":"第一百一十三条","txt":"人民法院根据审查再审申请案件的需要决定是否询问当事人；新的证据可能推翻原判决、裁定的，人民法院应当询问当事人。"},{"i":114,"n":"第一百一十四条","txt":"审查再审申请期间，被申请人及原审其他当事人依法提出再审申请的，人民法院应当将其列为再审申请人，对其再审事由一并审查，审查期限重新计算。经审查，其中一方再审申请人主张的再审事由成立的，应当裁定再审。各方再审申请人主张的再审事由均不成立的，一并裁定驳回再审申请。"},{"i":115,"n":"第一百一十五条","txt":"审查再审申请期间，再审申请人申请人民法院委托鉴定、勘验的，人民法院不予准许。"},{"i":116,"n":"第一百一十六条","txt":"当事人主张的再审事由成立，且符合行政诉讼法和本解释规定的申请再审条件的，人民法院应当裁定再审。"},{"i":117,"n":"第一百一十七条","txt":"有下列情形之一的，当事人可以向人民检察院申请抗诉或者检察建议："},{"i":118,"n":"第一百一十八条","txt":"按照审判监督程序决定再审的案件，裁定中止原判决、裁定、调解书的执行，但支付抚恤金、最低生活保障费或者社会保险待遇的案件，可以不中止执行。"},{"i":119,"n":"第一百一十九条","txt":"人民法院按照审判监督程序再审的案件，发生法律效力的判决、裁定是由第一审法院作出的，按照第一审程序审理，所作的判决、裁定，当事人可以上诉；发生法律效力的判决、裁定是由第二审法院作出的，按照第二审程序审理，所作的判决、裁定，是发生法律效力的判决、裁定；上级人民法院按照审判监督程序提审的，按照第二审程序审理，所作的判决、裁定是发生法律效力的判决、裁定。"},{"i":120,"n":"第一百二十条","txt":"人民法院审理再审案件应当围绕再审请求和被诉行政行为合法性进行。当事人的再审请求超出原审诉讼请求，符合另案诉讼条件的，告知当事人可以另行起诉。"},{"i":121,"n":"第一百二十一条","txt":"再审审理期间，有下列情形之一的，裁定终结再审程序："},{"i":122,"n":"第一百二十二条","txt":"人民法院审理再审案件，认为原生效判决、裁定确有错误，在撤销原生效判决或者裁定的同时，可以对生效判决、裁定的内容作出相应裁判，也可以裁定撤销生效判决或者裁定，发回作出生效判决、裁定的人民法院重新审理。"},{"i":123,"n":"第一百二十三条","txt":"人民法院审理二审案件和再审案件，对原审法院立案、不予立案或者驳回起诉错误的，应当分别情况作如下处理："},{"i":124,"n":"第一百二十四条","txt":"人民检察院提出抗诉的案件，接受抗诉的人民法院应当自收到抗诉书之日起三十日内作出再审的裁定；有行政诉讼法第九十一条第二、三项规定情形之一的，可以指令下一级人民法院再审，但经该下一级人民法院再审过的除外。"},{"i":125,"n":"第一百二十五条","txt":"人民检察院提出抗诉的案件，人民法院再审开庭时，应当在开庭三日前通知人民检察院派员出庭。"},{"i":126,"n":"第一百二十六条","txt":"人民法院收到再审检察建议后，应当组成合议庭，在三个月内进行审查，发现原判决、裁定、调解书确有错误，需要再审的，依照行政诉讼法第九十二条规定裁定再审，并通知当事人；经审查，决定不予再审的，应当书面回复人民检察院。"},{"i":127,"n":"第一百二十七条","txt":"人民法院审理因人民检察院抗诉或者检察建议裁定再审的案件，不受此前已经作出的驳回当事人再审申请裁定的限制。"},{"i":128,"n":"第一百二十八条","txt":"行政诉讼法第三条第三款规定的行政机关负责人，包括行政机关的正职、副职负责人以及其他参与分管的负责人。"},{"i":129,"n":"第一百二十九条","txt":"涉及重大公共利益、社会高度关注或者可能引发群体性事件等案件以及人民法院书面建议行政机关负责人出庭的案件，被诉行政机关负责人应当出庭。"},{"i":130,"n":"第一百三十条","txt":"行政诉讼法第三条第三款规定的“行政机关相应的工作人员”，包括该行政机关具有国家行政编制身份的工作人员以及其他依法履行公职的人员。"},{"i":131,"n":"第一百三十一条","txt":"行政机关负责人出庭应诉的，应当向人民法院提交能够证明该行政机关负责人职务的材料。"},{"i":132,"n":"第一百三十二条","txt":"行政机关负责人和行政机关相应的工作人员均不出庭，仅委托律师出庭的或者人民法院书面建议行政机关负责人出庭应诉，行政机关负责人不出庭应诉的，人民法院应当记录在案和在裁判文书中载明，并可以建议有关机关依法作出处理。"},{"i":133,"n":"第一百三十三条","txt":"行政诉讼法第二十六条第二款规定的“复议机关决定维持原行政行为”，包括复议机关驳回复议申请或者复议请求的情形，但以复议申请不符合受理条件为由驳回的除外。"},{"i":134,"n":"第一百三十四条","txt":"复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是共同被告。原告只起诉作出原行政行为的行政机关或者复议机关的，人民法院应当告知原告追加被告。原告不同意追加的，人民法院应当将另一机关列为共同被告。"},{"i":135,"n":"第一百三十五条","txt":"复议机关决定维持原行政行为的，人民法院应当在审查原行政行为合法性的同时，一并审查复议决定的合法性。"},{"i":136,"n":"第一百三十六条","txt":"人民法院对原行政行为作出判决的同时，应当对复议决定一并作出相应判决。"},{"i":137,"n":"第一百三十七条","txt":"公民、法人或者其他组织请求一并审理行政诉讼法第六十一条规定的相关民事争议，应当在第一审开庭审理前提出；有正当理由的，也可以在法庭调查中提出。"},{"i":138,"n":"第一百三十八条","txt":"人民法院决定在行政诉讼中一并审理相关民事争议，或者案件当事人一致同意相关民事争议在行政诉讼中一并解决，人民法院准许的，由受理行政案件的人民法院管辖。"},{"i":139,"n":"第一百三十九条","txt":"有下列情形之一的，人民法院应当作出不予准许一并审理民事争议的决定，并告知当事人可以依法通过其他渠道主张权利："},{"i":140,"n":"第一百四十条","txt":"人民法院在行政诉讼中一并审理相关民事争议的，民事争议应当单独立案，由同一审判组织审理。"},{"i":141,"n":"第一百四十一条","txt":"人民法院一并审理相关民事争议，适用民事法律规范的相关规定，法律另有规定的除外。"},{"i":142,"n":"第一百四十二条","txt":"对行政争议和民事争议应当分别裁判。"},{"i":143,"n":"第一百四十三条","txt":"行政诉讼原告在宣判前申请撤诉的，是否准许由人民法院裁定。人民法院裁定准许行政诉讼原告撤诉，但其对已经提起的一并审理相关民事争议不撤诉的，人民法院应当继续审理。"},{"i":144,"n":"第一百四十四条","txt":"人民法院一并审理相关民事争议，应当按行政案件、民事案件的标准分别收取诉讼费用。"},{"i":145,"n":"第一百四十五条","txt":"公民、法人或者其他组织在对行政行为提起诉讼时一并请求对所依据的规范性文件审查的，由行政行为案件管辖法院一并审查。"},{"i":146,"n":"第一百四十六条","txt":"公民、法人或者其他组织请求人民法院一并审查行政诉讼法第五十三条规定的规范性文件，应当在第一审开庭审理前提出；有正当理由的，也可以在法庭调查中提出。"},{"i":147,"n":"第一百四十七条","txt":"人民法院在对规范性文件审查过程中，发现规范性文件可能不合法的，应当听取规范性文件制定机关的意见。"},{"i":148,"n":"第一百四十八条","txt":"人民法院对规范性文件进行一并审查时，可以从规范性文件制定机关是否超越权限或者违反法定程序、作出行政行为所依据的条款以及相关条款等方面进行。"},{"i":149,"n":"第一百四十九条","txt":"人民法院经审查认为行政行为所依据的规范性文件合法的，应当作为认定行政行为合法的依据；经审查认为规范性文件不合法的，不作为人民法院认定行政行为合法的依据，并在裁判理由中予以阐明。作出生效裁判的人民法院应当向规范性文件的制定机关提出处理建议，并可以抄送制定机关的同级人民政府、上一级行政机关、监察机关以及规范性文件的备案机关。"},{"i":150,"n":"第一百五十条","txt":"人民法院认为规范性文件不合法的，应当在裁判生效后报送上一级人民法院进行备案。涉及国务院部门、省级行政机关制定的规范性文件，司法建议还应当分别层报最高人民法院、高级人民法院备案。"},{"i":151,"n":"第一百五十一条","txt":"各级人民法院院长对本院已经发生法律效力的判决、裁定，发现规范性文件合法性认定错误，认为需要再审的，应当提交审判委员会讨论。"},{"i":152,"n":"第一百五十二条","txt":"对发生法律效力的行政判决书、行政裁定书、行政赔偿判决书和行政调解书，负有义务的一方当事人拒绝履行的，对方当事人可以依法申请人民法院强制执行。"},{"i":153,"n":"第一百五十三条","txt":"申请执行的期限为二年。申请执行时效的中止、中断，适用法律有关规定。"},{"i":154,"n":"第一百五十四条","txt":"发生法律效力的行政判决书、行政裁定书、行政赔偿判决书和行政调解书，由第一审人民法院执行。"},{"i":155,"n":"第一百五十五条","txt":"行政机关根据行政诉讼法第九十七条的规定申请执行其行政行为，应当具备以下条件："},{"i":156,"n":"第一百五十六条","txt":"没有强制执行权的行政机关申请人民法院强制执行其行政行为，应当自被执行人的法定起诉期限届满之日起三个月内提出。逾期申请的，除有正当理由外，人民法院不予受理。"},{"i":157,"n":"第一百五十七条","txt":"行政机关申请人民法院强制执行其行政行为的，由申请人所在地的基层人民法院受理；执行对象为不动产的，由不动产所在地的基层人民法院受理。"},{"i":158,"n":"第一百五十八条","txt":"行政机关根据法律的授权对平等主体之间民事争议作出裁决后，当事人在法定期限内不起诉又不履行，作出裁决的行政机关在申请执行的期限内未申请人民法院强制执行的，生效行政裁决确定的权利人或者其继承人、权利承受人在六个月内可以申请人民法院强制执行。"},{"i":159,"n":"第一百五十九条","txt":"行政机关或者行政行为确定的权利人申请人民法院强制执行前，有充分理由认为被执行人可能逃避执行的，可以申请人民法院采取财产保全措施。后者申请强制执行的，应当提供相应的财产担保。"},{"i":160,"n":"第一百六十条","txt":"人民法院受理行政机关申请执行其行政行为的案件后，应当在七日内由行政审判庭对行政行为的合法性进行审查，并作出是否准予执行的裁定。"},{"i":161,"n":"第一百六十一条","txt":"被申请执行的行政行为有下列情形之一的，人民法院应当裁定不准予执行："},{"i":162,"n":"第一百六十二条","txt":"公民、法人或者其他组织对2015年5月1日之前作出的行政行为提起诉讼，请求确认行政行为无效的，人民法院不予立案。"},{"i":163,"n":"第一百六十三条","txt":"本解释自2018年2月8日起施行。"}],"zuigaorenminfayuanguanyushiyongxingfashijianxiaoli4fbe53":[{"i":1,"n":"第一条","txt":"对于行为人1997年9月30日以前实施的犯罪行为，在人民检察院、公安机关、国家安全机关立案侦查或者在人民法院受理案件以后，行为人逃避侦查或者审判，超过追诉期限或者被害人在追诉期限内提出控告，人民法院、人民检察院、公安机关应当立案而不予立案，超过追诉期限的，是否追究行为人的刑事责任，适用修订前的刑法第七十七条的规定。"},{"i":2,"n":"第二条","txt":"犯罪分子1997年9月30日以前犯罪，不具有法定减轻处罚情节，但是根据案件的具体情况需要在法定刑以下判处刑罚的，适用修订前的刑法第五十九条第二款的规定。"},{"i":3,"n":"第三条","txt":"前罪判处的刑罚已经执行完毕或者赦免，在1997年9月30日以前又犯应当判处有期徒刑以上刑罚之罪，是否构成累犯，适用修订前的刑法第六十一条的规定；1997年10月1日以后又犯应当判处有期徒刑以上刑罚之罪的，是否构成累犯，适用刑法第六十五条的规定。"},{"i":4,"n":"第四条","txt":"1997年9月30日以前被采取强制措施的犯罪嫌疑人、被告人或者1997年9月30日以前犯罪，1997年10月1日以后仍在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的，适用刑法第六十七条第二款的规定。"},{"i":5,"n":"第五条","txt":"1997年9月30日以前犯罪的犯罪分子，有揭发他人犯罪行为，或者提供重要线索，从而得以侦破其他案件等立功表现的，适用刑法第六十八条的规定。"},{"i":6,"n":"第六条","txt":"1997年9月30日以前犯罪被宣告缓刑的犯罪分子，在1997年10月1日以后的缓刑考验期间又犯新罪、被发现漏罪或者违反法律、行政法规或者国务院公安部门有关缓刑的监督管理规定，情节严重的，适用刑法第七十七条的规定，撤销缓刑。"},{"i":7,"n":"第七条","txt":"1997年9月30日以前犯罪，1997年10月1日以后仍在服刑的犯罪分子，因特殊情况，需要不受执行刑期限制假释的，适用刑法第八十一条第一款的规定，报经最高人民法院核准。"},{"i":8,"n":"第八条","txt":"1997年9月30日以前犯罪，1997年10月1日以后仍在服刑的累犯以及因杀人、爆炸、抢劫、强奸、绑架等暴力性犯罪被判处十年以上有期徒刑、无期徒刑的犯罪分子，适用修订前的刑法第七十三条的规定，可以假释。"},{"i":9,"n":"第九条","txt":"1997年9月30日以前被假释的犯罪分子，在1997年10月1日以后的假释考验期内，又犯新罪、被发现漏罪或者违反法律、行政法规或者国务院公安部门有关假释的监督管理规定的，适用刑法第八十六条的规定，撤销假释。"},{"i":10,"n":"第十条","txt":"按照审判监督程序重新审判的案件，适用行为时的法律。"}],"zuigaorenminfayuanguanyushiyongxingfadishiertiaoji2bdeea":[{"i":1,"n":"第一条","txt":"刑法第十二条规定的“处刑较轻”，是指刑法对某种犯罪规定的刑罚即法定刑比修订前刑法轻。法定刑较轻是指法定最高刑较轻；如果法定最高刑相同，则指法定最低刑较轻。"},{"i":2,"n":"第二条","txt":"如果刑法规定的某一犯罪只有一个法定刑幅度，法定最高刑或者最低刑是指该法定刑幅度的最高刑或者最低刑；如果刑法规定的某一犯罪有两个以上的法定刑幅度，法定最高刑或者最低刑是指具体犯罪行为应当适用的法定刑幅度的最高刑或者最低刑。"},{"i":3,"n":"第三条","txt":"1997年10月1日以后审理1997年9月30日以前发生的刑事案件，如果刑法规定的定罪处刑标准、法定刑与修订前刑法相同的，应当适用修订前的刑法。"}],"zuigaorenminfayuanguanyushiyongxingzhengsusongqisu5d3cf8":[{"i":1,"n":"第一条","txt":"公民、法人或者其他组织提起诉讼，符合行政诉讼法第四十九条规定的起诉条件，且未超过法定起诉期限的，人民法院应当依法立案。"},{"i":2,"n":"第二条","txt":"行政诉讼法第四十六条第一款规定的六个月起诉期限与《最高人民法院关于适用〈中华人民共和国行政诉讼法〉的解释》（以下简称行政诉讼法司法解释）第六十四条第一款规定的最长不得超过一年起诉期限，从公民、法人或者其他组织知道或者应当知道行政行为的内容和实施主体之日起计算。"},{"i":3,"n":"第三条","txt":"因不动产提起诉讼的案件自行政行为作出之日起超过二十年，其他案件自行政行为作出之日起超过五年提起诉讼的，人民法院不予立案。"},{"i":4,"n":"第四条","txt":"有下列情形之一的，属于行政诉讼法第四十八条第一款规定的“其他不属于其自身的原因耽误起诉期限”，被耽误的时间不计算在起诉期限内："},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织因行政机关告知的起诉期限长于法定起诉期限导致提起诉讼超过法定期限的，属于行政诉讼法第四十八条第一款规定的“其他不属于其自身的原因耽误起诉期限”，被耽误的时间不计算在起诉期限内；行政机关告知起诉期限短于法定起诉期限的，按照法定期限执行。"},{"i":6,"n":"第六条","txt":"复议机关作出不予受理决定、驳回申请决定或者复议决定后，公民、法人或者其他组织对不予受理决定、驳回申请决定和复议决定提起诉讼的期限为十五日，从决定书送达之日起计算。法律另有规定的除外。"},{"i":7,"n":"第七条","txt":"行政机关对履行法定职责申请既不答复也不履行职责的，公民、法人或者其他组织可以在行政机关接到申请的两个月后提起诉讼。但是，法律、法规规定应当先向行政机关申请复议或者对行政机关履行职责期限另有规定的，从其规定。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织申请行政机关更正已超过法定起诉期限的行政行为后，起诉行政机关不履行更正职责的，人民法院依法不予立案，但法律、法规、规章有特别规定的除外。"},{"i":9,"n":"第九条","txt":"公民、法人或者其他组织有证据证明行政登记记载的有关名称、公民身份号码等身份信息确有错误并向行政机关申请更正，行政机关在接到申请后拒绝履行更正职责的，公民、法人或者其他组织可以从行政机关拒绝履行更正职责之日起提起诉讼。"},{"i":10,"n":"第十条","txt":"对冒名顶替等利用虚假身份信息办理的婚姻登记，相关当事人可以自知道或者应当知道婚姻登记之日起提起诉讼。"},{"i":11,"n":"第十一条","txt":"本解释自2026年5月1日起施行。"}]};
